(window.GIM_TP=window.GIM_TP||{})["Z.Yitro.0"]={"from":0,"a":[[["(שמות י״ח:א׳) וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן חֹתֵן מֹשֶׁה אֵת כָּל אֲשֶׁר עָשָׂה וְגוֹ'. רַבִּי חִזְקִיָּה (נ\"א ר' אלעזר) פָּתַח וְאָמַר, (ויקרא ט׳:כ״ב) וַיִשָּׂא אַהֲרֹן אֶת יָדָו. כְּתִיב יָדוֹ חַד, בְּגִין דְּבָעֵי לְאָרָמָא יְמִינָא עַל שְׂמָאלָא, והָא אוֹקִימְנָא רָזָא.","אַשְׁכַּחְנָא בְּסִפְרָא דְּשְׁלֹמֹה מַלְכָּא, דְּכָל מַאן דְּאָרִים יְדוֹי לְעֵילָּא, וְלָאו אִינּוּן בִּצְלוֹתִין וּבָעוּתִין, הַאי אִיהוּ בַּר נָשׁ, דְּאִתְלַטְיָיא מֵעֲשָׂרָה שׁוּלְטָנִין מְמָנָן. וְאִינּוּן (קהלת ז׳:י״ט) עֲשָׂרָה שַׁלִּיטִין אֲשֶׁר הָיוּ בָּעִיר. אִלֵּין אִינּוּן עַשְׂרָה דִּי מְמָנָן עַל פְּרִישׂוּ דְּיָדִין לְעֵילָּא לְנַטְלָא הַהוּא צְלוֹתָא, אוֹ הַהִיא בִּרְכָתָא, וְיָהֲבֵי בֵּיהּ חֵילָא, לְאִתְיַקְּרָא שְׁמָא קַדִּישָׁא, וְאִתְבְּרַךְ מִתַּתָּא. כֵּיוָן דְּמִתַתָּא אִתְבְּרַךְ, מֵהַהוּא פְּרִישׂוּ דְּיָדִין לְעֵילָּא, כְּדֵין אִתְבָּרְכָא מֵעֵילָּא, וְאִתְיְקַר מִכָּל סִטְרִין.","וְאִלֵּין עֲשָׂרָה מְמָנָן, זְמִינִין לְנַטְלָא מֵאִינּוּן בִּרְכָּאן דִּלְעֵילָּא, וּלְאַרָקָא לְתַתָּא, וּלְבָרְכָא לְהַהוּא דִּמְבָרֵךְ לֵיהּ, דִּכְתִּיב, (במדבר ו׳:כ״ז) וַאֲנִי אֲבָרַכֵם.","בְּגִין כָּךְ, יִסְתַּמַּר בַּר נָשׁ, בְּשַׁעֲתָא דְּיָרִים יְדוֹי לְעֵילָּא, לְמֶהוֵי בִּצְלּוֹ, אוֹ בְּבִרְכָּאן אוֹ בְּבָעוּתָא, וְלָא יָרִים יְדוֹי לְמַגָּנָא, בְּגִין דְּאִלֵּין עֲשָׂרָה אִינּוּן זְמִינִין, וּמִתְעָרִין. לְגַבֵּי הַהוּא פְּרִישׂוּ דְּיָדִין, וְאִי הוּא לְמַגָּנָא, אִינּוּן עֲשָׂרָה לַטְיָין לֵיהּ, בְּמָאתָן וְאַרְבְּעִין וּתְמַנְיָא לְוָוטִין. וְהַאי אִיהוּ דִּכְתִּיב בֵּיהּ, (תהילים ק״ט:י״ז) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ.","וּכְדֵין, רוּחַ מִסְאֲבָא שַׁרְיָא עַל אִינּוּן יְדִין, דְּאִיהוּ אָרְחֵיהּ לְמִשְׁרֵי עַל אֲתָר רֵיקָנַיָּא, וּבִרְכָּתָא לָא שַׁרְיָא בַּאֲתָר רֵיקָנַיָּא. וְעַל דָּא (נ\"א דמברך ליה ואי אינון מתערין לגבי ההוא פרישו דידין ואיהו למגנא אינון לטיין ליה במאתן וארבעין ותמנייא לווטין וכדין רוח מסאבא שרייא על אינון ידין דאיהו ארחיה למשרזי על אתר ריקנייא בגין כך יסתמר בר נש בשעתא דארים ידוי לעילא למהוי בצלו או בברכאן ובצלותא ולא ירים ידוי למגנא ועל דא) כְּתִיב, (בראשית י״ד:כ״ב) הֲרִימוֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, דְּמִתַּרְגְּמִינָן בְּצַלּוּ.","וּבְהַאי פְּרִישׂוּ דְּיָדִין, אִית רָזִין עִלָּאִין, בְּשַׁעֲתָא דְּאִתְפְּרִישׁוּ, וְאִזְדְּקָפוּ לְעֵילָּא, אוֹקִיר בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּכַמָּה רָזִין עִלָּאִין. אַחְזֵי לְיַחֲדָא רָזָא דְּעֶשֶׂר אֲמִירָן, בְּגִין לְיַחֲדָא כֹּלָּא, וּלְאִתְבָּרְכָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזִי, (ר\"ח א' ב') וְאַחְזֵי לְיַחֲדָא רָזָא דִּרְתִּיכִין פְּנִימָאִין, וּרְתִיכִין דִּלְבַר, בְּגִין דְּיִתְבָּרֵךְ שְׁמָא קַדִּישָׁא בְּכָל סִטְרִין, וְיִתְיַחֵד כֹּלָּא כַּחֲדָא, עֵילָּא וְתַתָּא.","פָּתַח וְאָמַר, (שמות כ״ג:ט״ו) וְלֹא יֵרָאוּ פָּנַי רֵיקָם, דָּא אִיהוּ רָזָא דְּזְקִיפוּ דְּאֶצְבְּעָן, כַּד זָקִיף לוֹן בַּר נָשׁ לְעֵילָּא, דְּבָעֵי דְּלָא לְאִזְדַּקְּפָא בְּרֵיקַנְיָּא, אֶלָּא בְּצַלּוּ וּבְבָעוּתִין וּבְבִרְכָּאן. (או בחד מנייהו) וְעַל דָּא וְלֹא יֵרָאוּ פָּנַי רֵיקָם. וְלֹא יֵרָאוּ לְפָנַי לָא כְּתִיב, אֶלָּא פָּנַי, רָזָא דְּזְקִיפוּ דְּאֶצְבְּעָן, דְּלָא אִצְטְרִיכוּ לְזַקְפָא לְמַגָּנָא, כְּמָה דְּאִתְּמַר."],[[0,"וישמע יתרו כהן מדין וגו':","ר' חזקיה פתח ואמר, וישא אהרן את ידו. כתוב ידו חסר יוד, שהמשמעות יד אחד. והוא משום שצריך להרים הימין על השמאל. וכבר ביארנו הסוד."],[1,"אשכחנא בספרא דשלמה וכו':","מצאתי בספר של שלמה המלך שכל מי שמרים ידיו למעלה, ואין הן בתפלות ובקשות, זה הוא אדם שנתקלל מעשרה שליטים. והם עשרה שליטים אשר היו בעיר. אלו הם עשרה שממונים על הפורשים ידיהם למעלה, לקבל התפלה ההיא או הברכה ההיא ונותנים בו כח לכבד את השם הקדוש, ומתברך למטה. כיון שמתברך למטה מפרישת ידיו למעלה, אז מתברך למעלה והתיקר מכל הצדדים."],[2,"ואלין עשרה ממנן וכו':","ואלו עשרה ממונים מזומנים לקבל הברכות שלמעלה ולהוריקם למטה, ולברך לההוא שמברך לו. שכתוב, ואני אברכם."],[3,"בגין כך יסתמר וכו':","בשביל זה, ישמר עצמו בן אדם, בשעה שמרים ידיו למעלה, שיהיו בתפלה או בברכה או בבקשה, ולא ירים ידיו בחנם, משום שאלו עשרה ממונים הם מזומנים, ומתעוררים אל פרישת ידים ההוא, ואם הוא בחנם, עשרה האלו מקללים אותו ברמ\"ח קללות. וזהו שכתוב, ויאהב קללה ותבואהו."],[4,"וכדין רוח מסאבא וכו':","ואז רוח הטומאה שורה על אלו הידים, שהוא דרכו לשרות על מקום ריקן. והברכה אינו שורה במקום ריקן, וע\"כ כתוב הרימותי ידי אל ה' אל עליון, שמתרגם בצלו, דהיינו בתפלה."],[5,"ובהאי פרישו דידין וכו':","ובפרישת ידים ההוא יש סודות עליונים. בשעה שנפרשו ונזדקפו למעלה, מוקיר האדם את הקב\"ה בכמה סודות עליונים, והוא ראוי ליחדהסוד של עשרה מאמרות, כדי ליחד הכל ולברך את השם הקדוש כראוי. וראוי ליחד הסוד של מרכבות פנימיות דאצילות, ומרכבות חיצוניות לחוץ מאצילות, כדי שיתברך השם הקדוש מכל הצדדים ויתיחד הכל כאחד, למעלה ולמטה."],[6,"פתח ואמר וכו':","פתח ואמר, ולא יראו פני ריקם, זה הוא סוד של זקיפת האצבעות, שכאשר האדם זוקף אותם למעלה, צריך שלא יזקוף ריקם, אלא בתפלה ובבקשות ובברכות, ועל זה, ולא יראו פני ריקם, ולא יראו לפני, לא כתוב, אלא, פני, שהוא סוד זקיפת האצבעות, שלא צריך לזקפם בחנם. כמו שאמרנו."]],[[0,"","וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן חֹתֵן מֹשֶׁה אֵת כָּל אֲשֶׁר עָשָׂה וְגוֹ'. רַבִּי חִזְקִיָּה (רביאלעזר) פָּתַח וְאָמַר, (ויקראט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו. כָּתוּב יָדוֹ אַחַת, מִשּׁוּם שֶׁצָּרִיךְ לְהָרִים יָמִין עַל שְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ הַסּוֹד."],[1,"","מָצָאנוּ בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁכָּל מִי שֶׁמֵּרִים יָדוֹ לְמַעְלָה, וְהֵם אֵינָן בִּתְפִלּוֹת וּבַקָּשׁוֹת, זֶהוּ אָדָם שֶׁמִּתְקַלֵּל מֵעֲשָׂרָה שַׁלִּיטִים מְמֻנִּים, וְהֵם עֲשָׂרָה שַׁלִּיטִים אֲשֶׁר הָיוּ בָּעִיר. אֵלּוּ אוֹתָם עֲשָׂרָה שֶׁמְּמֻנִּים עַל פְּרִישַׂת הַיָּדַיִם לְמַעְלָה לִטֹּל אוֹתָהּ תְּפִלָּה אוֹ אוֹתָהּ בְּרָכָה, וְנוֹתְנִים בָּהּ כֹּחַ לְהִתְכַּבֵּד הַשֵּׁם הַקָּדוֹשׁ, וּמִתְבָּרֵךְ מִלְּמַטָּה. כֵּיוָן שֶׁמִּלְּמַטָּה מִתְבָּרֵךְ מֵאוֹתָהּ פְּרִישַׂת הַיָּדַיִם לְמַעְלָה, אָז מִתְבָּרֵךְ מִלְמַעְלָה, וּמִתְכַּבֵּד מִכָּל הַצְּדָדִים."],[2,"","וְאֵלּוּ עֲשֶׂרֶת הַמְמֻנִּים מְזֻמָּנִים לִטֹּל מֵאוֹתָן בְּרָכוֹת שֶׁלְּמַעְלָה, וּלְהוֹרִיק לְמַטָּה, וּלְבָרֵךְ אֶת אוֹתוֹ שֶׁמְּבָרֵךְ אוֹתוֹ, שֶׁכָּתוּב (במדבר ו) וַאֲנִי אֲבָרֲכֵם."],[3,"","וְלָכֵן יִשָּׁמֵר הָאָדָם בְּשָׁעָה שֶׁמֵּרִים יָדָיו לְמַעְלָה לִהְיוֹת בִּתְפִלָּה אוֹ בִּבְרָכוֹת אוֹ בְּבַקָּשָׁה, וְלֹא יָרִים יָדָיו לְחִנָּם, מִשּׁוּם שֶׁעֲשָׂרָה הַלָּלוּ מְזֻמָּנִים וּמִתְעוֹרְרִים אֶל אוֹתָהּ פְּרִישַׂת יָדַיִם. וְאִם זֶה לְחִנָּם, אוֹתָם הָעֲשָׂרָה מְקַלְלִים אוֹתוֹ בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה קְלָלוֹת. וְזֶהוּ שֶׁכָּתוּב בּוֹ (תהלים קט) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ."],[4,"","וְאָז רוּחַ טֻמְאָה שׁוֹרָה עַל אוֹתָם הַיָּדַיִם, שֶׁהוּא דַּרְכּוֹ לִשְׁרוֹת עַל מָקוֹם רֵיק, וּבְרָכָה לֹא שׁוֹרָה בְּמָקוֹם רֵיק. וְעַל זֶה (שמברךאותו. ואם הם מתעוררים אל אותו פורש הידים והם לחגם מקללים אותו במאתים וארבעים ושמנה קללות, ואז רוח טמאה שורה על אותן ידים, שדרכה לשרות על מקום ריק. משום כך יזהר האדםבשעה שמרים ידיו למעלה אובברכות או בתפלה ולא ירים ידיו לחגם. ועל זה) כָּתוּב (בראשית יד) הֲרִמֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, שֶׁמְּתַרְגְּמִים: בִּתְפִלָּה."],[5,"","וּבִפְרִישַׂת הַיָּדַיִם הַזֹּאת יֵשׁ סוֹדוֹת עֶלְיוֹנִים. בְּשָׁעָה שֶׁנִּפְרָשִׂים וּמִזְדַּקְּפִים לְמַעְלָה, מְכַבֵּד הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה סוֹדוֹת עֶלְיוֹנִים. וְרָאוּי לְיַחֵד סוֹד שֶׁל עֶשֶׂר הָאֲמִירוֹת כְּדֵי לְיַחֵד אֶת הַכֹּל, וּלְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. וְרָאוּי לְיַחֵד אֶת סוֹד הַמֶּרְכָּבוֹת הַפְּנִימִיּוֹת וְהַמֶּרְכָּבוֹת הַחִיצוֹנִיּוֹת כְּדֵי שֶׁיִּתְבָּרֵךְ הַשֵּׁם הַקָּדוֹשׁ בְּכָל הַצְּדָדִים, וְיִתְיַחֵד הַכֹּל כְּאֶחָד, מַעְלָה וּמַטָּה."],[6,"","פָּתַח וְאָמַר, (שמות כג) וְלֹא יֵרָאוּ פָנַי רֵיקָם. זֶהוּ סוֹד שֶׁל זְקִיפַת הָאֶצְבָּעוֹת, כְּשֶׁזּוֹקֵף אוֹתָם הָאָדָם לְמַעְלָה, שֶׁצָּרִיךְ שֶׁלֹּא לִזְקֹף בְּרֵיקָנוּת, אֶלָּא בִּתְפִלָּה וּבְבַקָּשׁוֹת וּבִבְרָכוֹת. וְעַל זֶה וְלֹא יֵרָאוּ פָנַי רֵיקָם. לֹא כָתוּב וְלֹא יֵרָאוּ לְפָנַי, אֶלָּא פָנַי, סוֹד שֶׁל זְקִיפַת הָאֶצְבָּעוֹת שֶׁלֹּא צָרִיךְ לְזָקְפָם לְחִנָּם, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["עֲשָׂרָה שַׁלִּיטִין דְּקַאמְרָן, אִינּוּן עֶשֶׂר אֲמִירָן לְתַתָּא, בְּרָזָא (נ\"א עשרה שלטנין ממנן דקאמרן, אינון ממנן לתתא ברזא) דְּאַתְוָון רְשִׁימִין כְּגַוְונָא דִּלְעֵילָּא, וְאִלֵּין קַיְּימִין בְּקַדְמִיתָא עַל הַהוּא זְקִיפָן דְּאֶצְבְּעָאן. וּבְהָא כָּל סִטְרָא דִּקְדוּשָּׁה אִתְאֲחָד לְעֵילָּא לְאָרָמָא, כְּדֵין כָּל סִטְרִין אַחֲרָנִין אִתְכַּפְיָין כֻּלְּהוּ, וְאוֹדָן לְמַלְכָּא קַדִּישָׁא.","תָּא חֲזֵי, בְּרָזָא דִּקְדוּשָּׁה (נ\"א דשמא קדישא) אִיהוּ מֶלֶךְ, וְכֹהֵן וּמְשַׁמֵּשׁ תְּחוֹתֵיהּ, (ברזא דקדושה) בֵּין לְעֵילָּא בֵּין לְתַתָּא. אִית מֶלֶךְ לְעֵילָּא, דְּאִיהוּ רָזָא דְּקֹדֶשׁ הַקֳּדָשִׁים, וְאִיהוּ מֶלֶךְ עִלָּאָה, וּתְחוֹתֵיהּ אִית כֹּהֵן רָזָא דְּאוֹר קַדְמָאָה, דְּקָא מְשַׁמֵּשׁ קָמֵיהּ, וְדָא אִיהוּ כֹּהֵן דְּאִקְרֵי גָּדוֹל, סִטְרָא דִּימִינָא.","אִית מֶלֶךְ לְתַתָּא, דְּאִיהוּ כְּגַוְונָא דְּהַהוּא מֶלֶךְ עִלָּאָה, וְאִיהוּ מֶלֶךְ עַל כֹּלָּא דִּלְתַתָּא. וּתְחוֹתֵיהּ אִית כֹּהֵן דִּמְשַׁמֵּשׁ לֵיהּ, רָזָא דְּמִיכָאֵל כַּהֲנָא רַבָּא, דְּאִיהוּ לִימִינָא. (ודאי בסטרא דקדשה אית מלך וכהן) וְדָא אִיהוּ רָזָא דִּמְהֵימָנוּתָא שְׁלֵימָתָא, סִטְרָא דִּקְדוּשָּׁה.","בְּסִטְרָא אַחֲרָא, דְּלָאו אִיהוּ סִטְרָא דִּקְדוּשָׁה, אִית רָזָא דְּאִיהוּ מֶלֶךְ, וְהָא אוֹקִימְנָא דְּאִקְרֵי (קהלת ד׳:י״ג) מֶלֶךְ זָקֵן וּכְסִיל, וּתְחוֹתֵיהּ אִית כֹּהֵן אוֹן, וְדָא הוּא רָזָא דִּכְתִּיב, (הושע י״ב:ט׳) וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי מָצָאתִי אוֹן לִי, בְּגִין דְּחֵילָא דָּא, שַׁלְטָא עַל הַהוּא עוֹבָדָא דַּעֲבַד יָרָבְעָם. וְאִלְמָלֵא דְּאַשְׁכַּח חֵילָא דָּא, לָא יָכִיל לְאַצְלָחָא בְּהַהוּא עוֹבָדָא.","רָזָא דְּמִלָּה, בְּשַׁעֲתָא דְּהַאי מֶלֶךְ וְהַאי כֹּהֵן אִתְכַּפְיָין, וְאִתְּבָּרוּ, כְּדֵין כָּל סִטְרִין אַחֲרָנִין אִתְכַּפְיָין, וְאוֹדָן לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא שָׁלִיט בִּלְחוֹדוֹי עֵילָּא וְתַתָּא, כְּמָה דְאַתְּ אָמֵר, (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בַּיּוֹם הַהוּא.","כְּגַוְונָא דָּא, וְרָזָא דָּא מַמָּשׁ, עָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, דְּתָבַר מֶלֶךְ זָקֵן וּכְסִיל, וְדָא הוּא פַּרְעֹה, בְּשַׁעֲתָא דְּאָתָא מֹשֶׁה לְפַרְעֹה, וְאָמַר, (שמות ה׳:ג׳) אֱלהֵי הָעִבְרִים נִקְרָא עָלֵינוּ, פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת יְיָ', וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְיָקַּר שְׁמֵיהּ בְּאַרְעָא, כְּמָה דְּאִיהוּ יַקִּירָא לְעֵילָּא. כֵּיוָן דְּאַלְקֵי לֵיהּ וּלְעַמֵּיהּ, אָתָא וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.","וּלְבָתַר אִתְּבַר וְאִתְכַּפְיָיא הַהוּא כֹּהֵן אוֹן, יִתְרוֹ, דִּמְשַׁמֵּשׁ תְּחוֹתֵיהּ, עַד דְּאָתָא וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר בָּרוּךְ יְיָ' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ', עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' וְגוֹ', וְדָא הוּא כֹּהֵן אוֹן, סִטְרָא אַחֲרָא, דְּאִיהוּ סְטָר שְׂמָאלָא. וְדָא אִיהוּ רָזָא דְּאָמְרָה רָחֵל, כַּד חָמָאתּ דְּמִיתַת, כְּמָה דִּכְתִּיב, (בראשית לה) בֶּן אוֹנִי. וּבְגִין דָּא אוֹחֵי (נ\"א אודי) יַעֲקֹב, וְאָמַר בֶּן יָמִין, וְלָא בֶּן אוֹנִי, סְטָר יְמִינָא, וְלָא שְׂמָאלָא.","וְכֵיוָן דְּהַהוּא מֶלֶךְ וְכֹהֵן אוֹדוּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְּבָּרוּ קָמֵיהּ, כְּדֵין אִסְתְּלַק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ עַל כֹּלָּא, עֵילָּא וְתַתָּא, וְעַד דְּאִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, כַּד אוֹדָן אִלֵּין קָמֵיהּ, לָא אִתְיְיהִיבַת אוֹרַיְיתָא. עַד לְבָתַר דְּאָתָא יִתְרוֹ, וְאוֹדֵי וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים. בָּרוּךְ יְיָ' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ'. כְּדֵין אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, עֵילָּא וְתַתָּא, וּלְבָתַר יָהַב אוֹרַיְיתָא בִּשְׁלִימוּ, דְּשֻׁלְטָנוּ עַל כֹּלָּא.","רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים ס״ז:ד׳) יוֹדוּךָ עַמִּים אֱלֹהִים יוֹדוּךָ עַמִּים כֻּלָּם, תָּא חֲזֵי, דָּוִד מַלְכָּא קָם וְשַׁבַּח וְאוֹדֵי לְמַלְכָּא קַדִּישָׁא. וְהוּא אִשְׁתַּדַּל בְּאוֹרַיְיתָא, בְּהַהִיא שַׁעֲתָא כַּד רוּחַ צָפוֹן אִתְּעַר, וַהֲוָה בָּטַשׁ בְּאִינּוּן נִימִין דְּכִנּוֹרָא, וְכִנּוֹרָא הֲוָה מְנַגֵּן וְאָמַר שִׁירָה וְכוּ', וּמַה שִׁירָה הֲוָה קָאָמַר.","תָּא חֲזִי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעַר לְגַבֵּי כָּל אִינּוּן רְתִיכִין, לְמֵיהָב לוֹן טַרְפָּא, כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. כְּדֵין, כֻּלְּהוּ בְּחֵדוּ, פַּתְחֵי וְאַמְרֵי, (תהילים ס״ז:ב׳) אֱלהִים יְחָנֵּנוּ וִיבָרְכֵנוּ יָאֵר פָּנָיו אִתָּנוּ סֶלָה. כַּד רוּחַ צָפוֹן אִתְּעַר וְנָחִית לְעָלְמָא, נָשִׁיב וְאָמַר, לָדַעַת בָּאָרֶץ דַּרְכֶּךָ בְּכָל גּוֹיִם יְשׁוּעָתֶךָ. כִּנּוֹר בְּשַׁעֲתָא דְּאִיהוּ מְנַגְּנָא בֵּיהּ בְּהַהוּא רוּחָא, פָּתַח וְאָמַר יוֹדוּךָ עַמִּים כֻּלָּם (חסר) דָּוִד כַּד הֲוָה קָם, וְאִתְּעַר עָלֵיהּ רוּחַ קֻדְשָׁא, פָּתַח וְאָמַר, אֶרֶץ נָתְנָה יְבוּלָהּ יְבָרְכֵנוּ אֱלהִים אֱלהֵינוּ יְבָרְכֵנוּ אֱלֹהִים וַיִּירְאוּ אוֹתוֹ כָּל אַפְסֵי אָרֶץ. בְּגִין לְאַמְשָׁכָא טִיבוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מֵעֵילָּא לְתַתָּא. לְבָתַר אָתָא דָּוִד בְּרוּחַ קֻדְשָׁא, וְסִדֵּר לוֹן כַּחֲדָא, אִסְתָּכַּל בְּכֹלָּא הַאי קְרָא דְּכִנּוֹרָא, (בגין) דִּשְׁלִימוּ דִּיְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא.","בְּשַׁעֲתָא דִּשְׁאַר עַמִּין אִתְכַּפְיָין, אַתְיָין וְאוֹדָאן לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, כֵּיוָן דְּאִינּוּן אִתְכַּפְיָין, וְאוֹדָן לֵיהּ, כְּדֵין אִשְׁתְּלִים יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא. בְּשַׁעֲתָא דְּאָתָא מֹשֶׁה לְפַרְעֹה וְאָמַר לֵיהּ יְיָ' אֱלהֵי הָעִבְרִים נִקְרָא עָלֵינוּ וְגוֹ', פָּתַח אִיהוּ וְאָמַר לא יָדַעְתִּי אֶת יְיָ'."],[[0,"עשרה שליטין דקאמרן וכו':","עשרה שליטים שאמרנו הם למטה עשרה מאמרות, בסוד אותיות הרשומות כעין שלמעלה.ואלו עומדים בתחילה על זקיפת האצבעות ההוא. ובזה כל צד הקדושה מתאחד למעלה. אזי כל הס\"א נכנעים כולם, ומודים למלך הקדוש."],[1,"ת\"ח ברזא דקדושה וכו':","בוא וראה, בסוד הקדושה יש מלך, וכהן המשמש תחתיו, בין למעלה ובין למטה. יש מלך למעלה שהוא סוד קדש הקדשים, דהיינו בינה, והוא מלך עליון, ותחתיו יש כהן, סוד אור הראשון, המשמש לפניו, דהיינו ספירת החסד. וזהו כהן שנקרא גדול, צד הימין."],[2,"אית מלך לתתא וכו':","יש מלך למטה, דהיינו מלכות, שהוא כעין מלך ההוא העליון, והוא מלך על כל שלמטה, דהיינו בי\"ע, ותחתיו יש כהן המשמש אותו, שה\"ס מיכאל (דפו\"י דף ס\"ז ע\"ב) כהן גדול שהוא לימין. דהיינו חסד. וזה הוא סוד אמונה השלמה, צד הקדושה."],[3,"בסטרא אחרא וכו':","בס\"א, שאינה צד הקדושה, יש סוד שהוא מלך. וכך העמדנו, שנקרא מלך זקן וכסיל. שהוא יצר הרע, ותחתיו יש, כהן און. וז\"ס שכתוב, ויאמר אפרים אך עשרתי מצאתי \u0003און\u0004 לי. דהיינו הכהן דס\"א, משום שכח הזה און, שולט על מעשה ההוא שעשה ירבעם. ואם לא היה נמצא כח הזה, לא היה יכול להצליח במעשה ההוא."],[4,"","רזא דמלה בשעתא וכו': סוד הדבר, בשעה שמלך הזה וכהן הזה, דס\"א, נכנעים ונשברים, אז כל צדדים האחרים נכנעים ומודים לו להקב\"ה, אז הקב\"ה מושל לבדו למעלה ולמטה. כש\"א, ונשגב ה' לבדו ביום ההוא."],[5,"כגוונא דא ורזא וכו':","כעין זה וסוד הזה ממש, עשה הקב\"ה בארץ, ששבר מלך זקן וכסיל, וזהו פרעה. בשעה שבא משה לפרעה, ואמר, אלקי העברים נקרא עלינו, פתח ואמר, לא ידעתי את ה'. ורצה הקב\"ה שיתיקר שמו בארץ כמו שהוא יקר למעלה, והכה אותו עשר מכות, כיון שהכה אותו ואת עמו, בא והודה להקב\"ה."],[6,"ולבתר אתבר ואתכפיא וכו':","ואח\"כ נשבר ונכנע כהן האון ההוא, יתרו, שמשמש תחתיו עד שבא והודה להקב\"ה, ואמר, ברוך ה' אשר הציל אתכם וגו' עתה ידעתי כי גדול ה' וגו'. וזה הוא כהן און, צד אחר, שהוא צד שמאל. וזהו סוד שאמרה רחל, כשראתה שהיא מתה, כמ\"ש, בן אוני. ומשום זה מיהר יעקב ואמר, בן ימין ולא בן אוני צד ימין ולא שמאל."],[7,"וכיון דההוא מלך וכו':","כיון שהמלך והכהן ההוא, מודים להקב\"ה ונשברים לפניו, אז עולה הקב\"ה ביקרו על כולם למעלה ולמטה. ומטרם שעלה הקב\"ה ביקרו כשאלו הודו לפניו, לא ניתנה התורה. עד לאחר שבא יתרו, והודה ואמר, עתה ידעתי כי גדול ה' מכל האלקים. ברוך ה' אשר הציל אתכם. אז עלה הקב\"ה ביקרו למעלה ולמטה, ואח\"כ נתן התורה בשלימות ממשלתו על הכל."],[8,"ר\"א פתח וכו':","ר\"א פתח ואמר. יודוך עמים אלקים יודוך עמים כולם. בוא וראה, דוד המלך, קם ושיבח והודה למלך הקדוש. והוא עסק בתורה, בשעה ההיא כשנתעורר רוח צפון, והיה מכה בנימין של הכנור, והכנור היה מנגן ואמר שירה. שואל, ואיזה שירה היה אומר."],[9,"תא חזי בשעתא וכו':","ומשיב, בוא וראה, בשעה שהקב\"ה מתעורר אל כל אלו המרכבות לתת להם טרף. כמו שהעמדנו, שכתוב, ותקם בעוד לילה ותתן טרף לביתה וחק לנערותיה, אז כולם, פתחו ואמרו בשמחה, אלקים יחננו ויברכנו יאר פניו אתנו סלה. כשרוח צפון נתעורר וירד לעולם, נושב ואומר, לדעת בארץ דרכך בכל גוים ישועתך. הכנור, בשעה שהוא מנגן על ידי רוח ההוא, פתח ואמר, יודוך עמים כולם. דוד כשהיה קם ונתעורר עליו רוח הקודש. פתח ואמר ארץ נתנה יבולה יברכנו אלקים אלקינו יברכנו אלקים וייראו אותו כל אפסי ארץ. כדי להמשיך את הטוב של הקב\"ה מלמעלה למטה. אח\"כ בא דוד ברוח הקודש וסדר אותם יחד, ככתוב, יברכנו אלקים וגו', הסתכל בכל המקרא הזה, של הכשר, דהיינו יודוך עמים כלם. כי שלימות יקר הקב\"ה הוא למעלה ולמטה, דהיינו וייראו אותו כל אפסי ארץ."],[10,"בשעתא דשאר עמין וכו':","בשעה ששאר עמים נכנעים ובאים ומודים להקב\"ה, כיון שהם נכנעים ומודים לו נשלם אז כבוד הקב\"ה למעלה ולמטה. בשעה שבא משה לפרעה, ואמר לו, ה' אלקי העברים נקרא עלינו וגו', פתח הוא ואמר לא ידעתי את ה'."]],[[0,"","עָשָׂרָה שַׁלִּיטִים שֶׁאָמַרְנוּ הֵם עֶשֶׂר אֲמִירוֹת לְמַטָּה, בְּסוֹד (בסוד עשרה שליטים ממגים שאמרנו, אלו ממגים למטה בסוד) שֶׁל הָאוֹתִיּוֹת הָרְשׁוּמוֹת כְּמוֹ שֶׁלְּמַעְלָה, וְאֵלֶּה עוֹמְדִים בָּרִאשׁוֹנָה עַל אוֹתָהּ זְקִיפַת אֶצְבָּעוֹת, וּבָזֶה נֶאֱחָז לְמַעְלָה כָּל צַד הַקְּדֻשָּׁה לְהָרִים, אָז כָּל הַצְּדָדִים הָאֲחֵרִים כֻּלָּם מִתְכּוֹפְפִים וּמוֹדִים לַמֶּלֶךְ הַקָּדוֹשׁ."],[1,"","בֹּא וּרְאֵה, בְּסוֹד שֶׁל קְדֻשָּׁה (של השם הקדוש) הוּא מֶלֶךְ וְכֹהֵן וּמְשַׁמֵּשׁ תַּחְתָּו (בסוד של קדשה), בֵּין לְמַעְלָה בֵּין לְמַטָּה. יֵשׁ מֶלֶךְ לְמַעְלָה, שֶׁהוּא סוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְהוּא מֶלֶךְ עֶלְיוֹן, וְתַחְתָּיו יֵשׁ כֹּהֵן, סוֹד שֶׁל אוֹר רִאשׁוֹן, שֶׁמְּשַׁמֵּשׁ לְפָנָיו, וְזֶהוּ כֹּהֵן שֶׁנִּקְרָא גָּדוֹל, צַד הַיָּמִין."],[2,"","יֵשׁ מֶלֶךְ לְמַטָּה שֶׁהוּא כְּמוֹ אוֹתוֹ מֶלֶךְ עֶלְיוֹן, וְהוּא מֶלֶךְ עַל הַכֹּל שֶׁלְּמַטָּה, וְתַחְתָּיו יֵשׁ כֹּהֵן שֶׁמְּשַׁמֵּשׁ אוֹתוֹ, סוֹד שֶׁל מִיכָאֵל כֹּהֵן גָּדוֹל, שֶׁהוּא לְיָמִין, (ודאי בצד הקדשהישמלךוכהן) וְזֶהוּ סוֹד הָאֱמוּנָה הַשְּׁלֵמָה, צַד הַקְּדֻשָּׁה."],[3,"","בַּצַד הָאַחֵר, שֶׁאֵינוֹ צַד הַקְּדֻשָּׁה, יֵשׁ סוֹד שֶׁהוּא מֶלֶךְ, וַהֲרֵי בֵּאַרְנוּ שֶׁנִּקְרָא מֶלֶךְ זָקֵן וּכְסִיל, וְתַחְתָּיו יֵשׁ כֹּהֵן אוֹן, וְזֶהוּ סוֹד הַכָּתוּב (הושע יב) וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי מָצָאתִי אוֹן לִי. מִשּׁוּם שֶׁכֹּחַ זֶה שׁוֹלֵט עַל אוֹתוֹ מַעֲשֶׂה שֶׁעָשָׂה יָרָבְעָם. וְאִלְמָלֵא שֶׁנִּמְצָא כֹּחַ זֶה, לֹא יָכֹל לְהַצְלִיחַ בְּאוֹתוֹ מַעֲשֶׂה."],[4,"","סוֹד הַדָּבָר - בְּשָׁעָה שֶׁהַמֶּלֶךְ הַזֶּה וְהַכֹּהֵן הַזֶּה נִכְפִּים, וְנִשְׁבְּרוּ, אָז נִכְפִּים כָּל יֶתֶר הַצְּדָדִים וּמוֹדִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט לְבַדּוֹ מַעְלָה וּמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכ) וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא."],[5,"","כְּמוֹ זֶה וְסוֹד זֶה מַמָּשׁ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, שֶׁשָּׁבַר מֶלֶךְ זָקֵן וּכְסִיל, וְזֶהוּ פַּרְעֹה. בְּשָׁעָה שֶׁבָּא מֹשֶׁה לְפַרְעֹה וְאָמַר (שמות ה) אֱלֹהִי הָעִבְרִים נִקְרָא עָלֵינוּ, פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת ה'. וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְכַּבֵּד שְׁמוֹ בָּאָרֶץ, כְּמוֹ שֶׁהוּא נִכְבָּד לְמַעְלָה. כֵּיוָן שֶׁהִלְקָה אוֹתוֹ וְאֶת עַמּוֹ, בָּא וְהוֹדָה לוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא."],[6,"","וְאַחַר נִשְׁבַּר וְנִכְפָּה אוֹתוֹ כֹּהֵן אוֹן, יִתְרוֹ, שֶׁמְּשַׁמֵּשׁ תַּחְתָּיו, עַד שֶׁבָּא וְהוֹדָה לוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְאָמַר, בָּרוּךְ ה' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ', עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' וְגוֹ'. וְזֶהוּ כֹּהֵן אוֹן, צַד הָאַחֵר, שֶׁהוּא צַד שְׂמֹאל. וְזֶהוּ סוֹד שֶׁאָמְרָה רָחֵל, כְּשֶׁרָאֲתָה שֶׁהִיא מֵתָה, כְּמוֹ שֶׁכָּתוּב (בראשית לה) בֶּן אוֹנִי. וְלָכֵן מִהֵר (הודה) יַעֲקֹב וְאָמַר בֶּן יָמִין, וְלֹא בֶּן אוֹנִי. צַד יָמִין, וְלֹא צַד שְׂמֹאל."],[7,"","וְכֵיוָן שֶׁאוֹתוֹ מֶלֶךְ וְכֹהֵן הוֹדוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְנִשְׁבְּרוּ לְפָנָיו, אָז הִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ עַל הַכֹּל, מַעְלָה וּמַטָּה. וְעַד שֶׁהִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ, כְּשֶׁהוֹדוּ אֵלֶּה לְפָנָיו, לֹא נִתְּנָה תּוֹרָה עַד לְאַחַר שֶׁבָּא יִתְרוֹ, וְהוֹדָה וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים. בָּרוּךְ ה' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ'. אָז הִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ מַעְלָה וּמַטָּה, וְאַחַר כָּךְ נָתַן תּוֹרָה בִּשְׁלֵמוּת, כְּשֶׁשִּׁלְטוֹנוֹ עַל הַכֹּל."],[8,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים סז) יוֹדוּךְ עַמִּים אֱלֹהִים יוֹדוּךְ עַמִּים כֻּלָּם. בֹּא וּרְאֵה, דָּוִד הַמֶּלֶךְ קָם וְשִׁבַּח וְהוֹדָה לַמֶּלֶךְ הַקָּדוֹשׁ, וְהוּא הִשְׁתַּדֵּל בַּתּוֹרָה בְּאוֹתָהּ שָׁעָה כְּשֶׁרוּחַ צָפוֹן הִתְעוֹרְרָה וְהָיְתָה מַכָּה בְּאוֹתָם נִימֵי הַכִּנּוֹר, וְהַכִּנּוֹר הָיָה מְנַגֵּן וְאוֹמֵר שִׁירָה וְכוּ'. וְאֵיזוֹ שִׁירָה הוּא אָמַר?"],[9,"","בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר אֶל כָּל אוֹתָן הַמֶּרְכָּבוֹת לָתֵת לָהֶן טֶרֶף, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ, אָז כֻּלָּם בְּשִׂמְחָה פּוֹתְחִים וְאוֹמְרִים, (תהלים סז) אֱלֹהִים יְחָנֵּנוּ וִיבָרְכֵנוּ יָאֵר פָּנָיו אִתָּנוּ סֶלָה. כְּשֶׁרוּחַ צָפוֹן מִתְעוֹרֶרֶת וְיוֹרֶדֶת לָעוֹלָם, נוֹשֶׁבֶת וְאוֹמֶרֶת, לָדַעַת בָּאָרֶץ דַּרְכֶּךְ בְּכָל גּוֹיִם יְשׁוּעָתֶךְ. בְּשָׁעָה שֶׁמְּנַגֵּן הַכִּנּוֹר בְּאוֹתָהּ רוּחַ, פּוֹתֵחַ וְאוֹמֵר, יוֹדוּךְ עַמִּים כֻּלָּם. כְּשֶׁהָיָה דָּוִד קָם וּמִתְעוֹרֵר עָלָיו רוּחַ הַקֹּדֶשׁ, פָּתַח וְאָמַר, אֶרֶץ נָתְנָה יְבוּלָהּ יְבָרְכֵנוּ אֱלֹהִים אֱלֹהֵינוּ יְבָרְכֵנוּ אֱלֹהִים וְיִירְאוּ אוֹתוֹ כָּל אַפְסֵי אָרֶץ. כְּדֵי לְהַמְשִׁיךְ אֶת טוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה לְמַטָּה. אַחַר כָּךְ בָּא דָּוִד וְסִדֵּר אוֹתָם בְּרוּחַ הַקֹּדֶשׁ כְּאֶחָד, הִסְתַּכֵּל בְּכָל הַכָּתוּב הַזֶּה שֶׁל הַכִּנּוֹר, שֶׁל שְׁלֵמוּת וּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה."],[10,"","בְּשָׁעָה שֶׁשְּׁאָר הָעַמִּים נִכְפִּים, הֵם בָּאִים וּמוֹדִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. כֵּיוָן שֶׁנִּכְפִּים וּמוֹדִים לוֹ, אָז מִשְׁתַּלֵּם כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה. בְּשָׁעָה שֶׁבָּא מֹשֶׁה לְפַרְעֹה וְאָמַר לוֹ ה' אֱלֹהֵי הָעִבְרִים נִקְרָא עָלֵינוּ וְגוֹ', הוּא פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת ה'."]]],[["וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא, דְּיִתְיָיקַּר שְׁמֵיהּ בְּאַרְעָא, כְּמָה דְּאִיהוּ יַקִּירָא לְעֵילָּא, כֵּיוָן דְּאַלְקֵי לֵיהּ וּלְעַמֵּיהּ, אָתָא וְאוֹדֵי לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (שמות ט) יְיָ' הַצַּדִיק. אִיהוּ דְּהֲוָה מַלְכָּא קְרוֹפִינוֹס דְּכָל עָלְמָא, כֵּיוָן דְּאִיהוּ אוֹדֵי, כָּל שְׁאַר מַלְכִין אוֹדוּן, דִּכְתִּיב, (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם.","אָתָא יִתְרוֹ, כּוֹמָרָא עִלָּאָה וְרַבְרְבָא, רַב מְמָנָא (דכל ממנא) דְּכָל טַעֲוָון אַחֲרָנִין, וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים, כְּדֵין אִסְתַּלָּק וְאִתְיְיקָר קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ עֵילָּא וְתַתָּא, וּלְבָתַר יָהַב אוֹרַיְיתָא בִּשְׁלִימוּ, דְּשֻׁלְטָנוּ עַל כֹּלָּא.","אָמַר רַבִּי שִׁמְעוֹן לְרַ' אֶלְעָזָר בְּרֵיהּ, עַל דָּא כְּתִיב, (תהילים ס״ז:ד׳) יוֹדוּךָ עַמִּים אֱלֹהִים יוֹדוּךָ עַמִּים כּוּלָּם. אָתָא ר' אֶלְעָזָר וְנָשִׁיק יְדוֹי. בָּכָה ר' אַבָּא וְאָמַר, (תהילים ק״ג:י״ג) כְּרַחֵם אָב עַל בָּנִים. מַאן יְרַחֵם עַל ר' אֶלְעָזָר, וּלְאַשְׁלְמָא מִלּוֹי, בַּר רְחִימוּ דְּמֹר, זַכָּאָה חוּלָקָנָא, דְּזָכֵינָא לְמִשְׁמַע מִלִּין אִלֵּין קָמֵיהּ, דְּלָא נִכְסוֹף בְּהוּ לְעָלְמָא דְּאָתֵי.","אָמַר רַבִּי אַבָּא, הָא כֹּהֵן אוֹן לָא כְּתִיב בְּיִתְרוֹ, כֹּהֵן מִדְיָן כְּתִיב. אֲמַר לֵיהּ, כֹּלָּא אִיהוּ חַד. בְּקַדְמִיתָא חָמוּי דְּיוֹסֵף, כֹּהֵן אוֹן אִקְרֵי. וּלְבָתַר חָמוּי דְּמֹשֶׁה, כֹּהֵן מִדְיָן. וְכֹלָּא רָזָא חֲדָא, דְּהָא אִלֵּין תְּרֵין מֹשֶׁה וְיוֹסֵף. בְּדַרְגָּא דְרָזָא חֲדָא קַיְימִין, בְּרָזָא דְּאָת וָ\"ו, תְּרֵין וָוִין כַּחֲדָא. וּמַה דְּאִתְּמַר כֹּהֵן מִדְיָן, רָזָא דָּא אֵשֶׁת מִדְיָנִים. (משה ויוסף ברזא חדא קיימי, רזא דא ו\"ו תרין כחדא)","אָרִים יְדוֹי עַל רֵישֵׁיהּ ר' אַבָּא וּבָכָה, אָמַר, נְהִירוּ דְּאוֹרַיְיתָא סַלְּקָא הַשְׁתָּא עַד רוּם רְקִיעָא דְּכֻרְסְיָיא עִלָּאָה, לְבָתַר דְּיִסְתַּלַּק מֹר מֵעָלְמָא, מַאן יַנְהִיר נְהִירוּ דְּאוֹרַיְיתָא. וַוי לְעָלְמָא דְּיִשְׁתְּאַר יָתוֹם מִינָךְ. אֲבָל מִלִּין דְּמֹר יִתְנְהִירוּ בְּעָלְמָא עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא וּכְדֵין כְּתִיב, (ישעיהו י״א:ט׳) וּמָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ' וְגוֹ'.","וַיִּשְׁמַע יִתְרוֹ כֹּהֵן וְגוֹ, רַבִּי חִיָּיא אָמַר, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, בְּקַדְמִיתָא כְּתִיב, אֵת כָּל אֲשֶׁר עָשָׂה אֱלהִים לְמֹשֶׁה, וּלְבָתַר כְּתִיב כִּי הוֹצִיא יְיָ'. אֶלָּא רָזָא דָּא אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים, דָּא שְׁמָא דְּאָגִין עַל מֹשֶׁה וְעַל יִשְׂרָאֵל, וְלָא אִתְעָדֵי מִנַּיְיהוּ בְּגָלוּתָא. וּלְבָתַר, שְׁמָא עִלָּאָה אַפִּיק לוֹן מִמִּצְרַיִם. דְּהָא שְׁמָא קַדִּישָׁא דְּאַפִּיק לוֹן, בְּרָזָא דְּיוֹבְלָא הֲוָה.","דָּבָר אַחֵר אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה, כַּד אִתְרְמֵי לְנָהֲרָא, וְכַד שֵׁזִיב לֵיהּ מֵחַרְבָּא דְּפַרְעֹה, וּלְיִשְׂרָאֵל עַמּוֹ, דִּכְתִּיב, (שמות ב׳:כ״ד) וַיִּשְׁמַע אֱלֹהִים אֶת נַאֲקָתָם. וּכְתִיב (שמות א׳:י״ב) וְכַאֲשֶׁר יְעַנּוּ אוֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרוֹץ.","וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן. רַבִּי יוֹסִי פָּתַח, (תהילים קי״א:ט׳) פְּדוּת שָׁלַח לְעַמּוֹ צִוָּה לְעוֹלָם בְּרִיתוֹ קָדוֹשׁ וְנוֹרָא שְׁמוֹ. מַאי שְׁנָא, בְּכָל שְׁאַר קְרָאֵי, דִּבְכֻלְּהוּ, תְּרֵין תֵּיבִין מֵאַלְפָא בֵּיתָא, וּבְהַאי קְרָא, וּבִקְרָא דַּאֲבַתְרֵיהּ, תְּלַת תְּלַת. אֶלָּא, בְּגִין לְאַשְׁלְמָא שִׁית סִטְרִין, בְּהַאי אַלְפָא בֵּיתָא, הַאי לָקֳבֵל תְּלַת פּוּרְקָנִין דְּיִשְׂרָאֵל, בַּר פּוּרְקָנָא קַדְמָאָה. קְרָא אַחֲרָא, לָקֳבֵל תּוֹרָה נְבִיאִים וּכְתוּבִים. וְכֹלָּא תַּלְיָא בְּהַאי חָכְמָה.","פְּדוּת שָׁלַח לְעַמּוֹ, כַּד פָּרִיק קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, מִגָּלוּתָא דְּמִצְרַיִם, וְעָבִיד לוֹן נִסִּין וּגְבוּרָן. צִוָּה לְעוֹלָם בְּרִיתוֹ, כַּד אָתָא יִתְרוֹ, וְקָבִּיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְקָרִיב לֵיהּ לְפוּלְחָנֵיהּ. וּמִתַּמָּן, אִתְקְרִיבוּ כָּל אִינּוּן גִּיּוֹרִין, תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, מִתַּמָּן וּלְהָלְאָה, קָדוֹשׁ וְנוֹרָא שְׁמוֹ. דְּהָא כְּדֵין אִתְקַדָּשׁ שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא (מסטרא אחרא) יִתְקַדָּשׁ שְׁמָא קַדִּישָׁא, כַּד אִתְּבַר, וְאִתְכַּפְיָא סִטְרָא אַחֲרָא, כְּמָה דְּהֲוָה בְּיִתְרוֹ.","וַיִּשְׁמַע יִתְרוֹ וְגוֹ', וְכִי יִתְרוֹ שָׁמַע, וְכָל עָלְמָא לא שַׁמְעוּ, וְהָא כְּתִיב, (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן. אֶלָּא, כָּל עָלְמָא שָׁמְעוּ, וְלָא אִתְּבָּרוּ, וְאִיהוּ שָׁמַע וְאִתְּבַּר, וְאִתְכַּפְיָא מִקַּמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְקְרַב לְדַחַלְתֵּיהּ."],[[0,"ובעא קב\"ה דיתייקר וכו':","ורצה הקב\"ה שיתיקר שמו בארץ כמו שהוא יקר למעלה, כיון שהכה אותו ועמו, בא והודה להקב\"ה, שכתוב, ה' הצדיק. הוא שהיה מלך חשוב בכל העולם, כיון שהוא הודה, הודו כל שאר המלכים, שכתוב, אז נבהלו אלפי אדום."],[1,"אתא יתרו כומרא וכו':","בא יתרו, כומר עליון וגדול, שר ממונה של כל אלילים האחרים והודה להקב\"ה, ואמר עתה ידעתי כי גדול ה' מכל האלקים, אז נתעלה ונתיקר הקב\"ה ביקרו למעלה ולמטה, ואח\"כ נתן התורה בשלמות שליטתו על הכל."],[2,"אר\"ש לר' אלעזר וכו':","אמר ר' שמעון לר\"א בנו, על זה כתוב, יודוך עמים אלקים יודוך עמים כולם. בא ר' אלעזר ונשק ידיו של אביו. בכה ר' אבא ואמר, כרחם אב על בנים. מי ירחם על ר' אלעזר וישלים את דבריו חוץ מאהבתו של אדוני. אשרי חלקנו שזכינו לשמוע דברים אלו לפניו, שלא נתבייש בהם לעולם הבא."],[3,"אמר ר' אבא וכו':","אר\"א, הרי כהן און לא כתוב ביתרו, כהן מדין כתוב. אמר לו, הכל הוא אחד, מתחילה היה נקרא כהן און חותנו של יוסף, ואח\"כ נקרא חותנו של משה כהן מדין. והכל הוא סוד אחד. שכהן מדין הוא כמו כהן און. כי אלו השנים משה ויוסף במדרגה של סוד אחד הם נמצאים, בסוד של אות \u0003ו'\u0004 שבמילוי היא \u0003ו\"ו\u0004 שתי ווין ביחד. אשר \u0003ו'\u0004 ראשונה הוא משה, שהוא ת\"ת, \u0003ו'\u0004 שניה הוא יוסף, שהוא יסוד. ומה שנאמר כהן מדין, ה\"ס אשת מדינים."],[4,"ארים ידוי על וכו':","הרים ר' אבא ידיו על ראשו ובכה, אמר, אור התורה עולה עתה עד רום הרקיע של הכסא העליון. אחר שיסתלק אדוני מן העולם, מי יאיר אור התורה. אוי לעולם שישאר יתום ממך. אבל הדברים של אדוני יאירו בעולם עד שיבוא מלך המשיח, ואז כתוב, ומלאה הארץ דעה את ה' וגו'."],[5,"וישמע יתרו כהן וגו':","ר' חייא אמר מקרא זה, יש להסתכל בו. בתחילה כתוב, את כל אשר עשה \u0003אלקים\u0004 למשה. ואח\"כ כתוב, כי הוציא \u0003הוי\"ה.\u0004 ומשיב, אלא סוד זה, אשר עשה אלקים שהוא המלכות, זהו השם שהגין על משה ועל ישראל ולא סר מהם בגלות. ואח\"כ שם העליון הוציאם ממצרים, כי השם שהוציאם ממצרים היה בסוד היובל, שהיא בינה."],[6,"ד\"א, את כל אשר וכו':","פי' אחר. כל אשר עשה אלקים למשה, היינו כשנשלך לנהר, וכשהצילו מחרב פרעה. \u0003ולישראל\u0004 עמו, שכתוב, וישמע אלקים את נאקתם. וכתוב, וכאשר יענו אותו כן ירבה וכן יפרוץ."],[7,"וישמע יתרו כהן מדין:","ר' יוסי פתח. פדות שלח לעמו צוה לעולם בריתו קדוש ונורא שמו. שואל, מה השינוי שבכל שאר הפסוקים יש בכולם רק ב' תיבות מאלפא ביתא, כגון בפסוק שלפני זה כתוב ב' אותיות ס' ע', ובפסוק הזה ובפסוק שלאחריו יש ג' ג'. כי בפסוק הזה יש ג' אותיות פ' צ' ק', ובשלאחריו, יש ג' אותיות ר' ש' ת'. ומשיב, אלא כדי להשלים שש בחינות באלפא ביתא הזה, שהם ג' גאולות, ותורה נביאים וכתובים. מקרא הזה הוא כנגד ג' גאולות של ישראל, שהם בבל יון אדום. חוץ מגאולה הראשונה של מצרים שכבר היתה. ומקרא האחר, הוא כנגד תורה נביאים וכתובים. והכל תלוי בחכמה הזו. שתורה נביאים וכתובים תלוים ויוצאים מחכמה וע\"כ מתחיל המקרא האחר, ראשית חכמה."],[8,"פדות שלח לעמו:","פירוש אחר, פדות שלח לעמו, היינו כשהוציא את ישראל ממצרים ועשה להם נסים וגבורות \u0003צוה לעולם בריתו,\u0004 היינו כשבא יתרו וקבלו הקב\"ה, וקרבו לעבודתו. ומשם התקרבו כל אלו הגרים תחת כנפי השכינה. משם ולהלאה, \u0003קדוש ונורא שמו.\u0004 כי אז נתקדש שמו של הקב\"ה, כי השם הקדוש מתקדש, כשנשבר ונכנע הס\"א, כמו שהיה ביתרו."],[9,"וישמע יתרו וגו':","שואל, וכי יתרו שמע, וכל העולם לא שמעו, והרי כתוב, שמעו עמים ירגזון. ומשיב, אלא כל העולם שמעו, ולא נשברו, וע\"כ אין שמיעתם שמיעה. והוא שמע ונשבר ונכנע לפני הקב\"ה ונתקרב ליראתו. ע\"כ שמיעתו שמיעה."]],[[0,"","וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְכַּבֵּד שְׁמוֹ בָּאָרֶץ, כְּמוֹ שֶׁהוּא נִכְבָּד לְמַעְלָה. כֵּיוָן שֶׁהִלְקָה אוֹתוֹ וְאֶת עַמּוֹ, בָּא וְהוֹדָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא, שֶׁכָּתוּב ה' הַצַּדִּיק. הוּא שֶׁהָיָה מֶלֶךְ חָשׁוּב שֶׁל כָּל הָעוֹלָם, כֵּיוָן שֶׁהוֹדָה, אָז כָּל שְׁאָר הָעַמִּים הוֹדוּ, שֶׁכָּתוּב (שמות טו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם."],[1,"","בָּא יִתְרוֹ, כֹּמֶר עֶלְיוֹן וְגָדוֹל, מְמֻנֶּה גָּדוֹל (של כל הממונים) שֶׁל כָּל הָאֱלִילִים הָאֲחֵרִים, וְהוֹדָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים. אָז הִתְעַלָּה וְהִתְכַּבֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ מַעְלָה וּמַטָּה, וְאַחַר כָּךְ נָתַן תּוֹרָה בִּשְׁלֵמוּת, כְּשֶׁשִּׁלְטוֹנוֹ עַל הַכֹּל."],[2,"","אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, עַל זֶה כָּתוּב (תהלים סז) יוֹדוּךְ עַמִּים אֱלֹהִים יוֹדוּךְ עַמִּים כֻּלָּם. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. בָּכָה רַבִּי אַבָּא וְאָמַר, (שם קג) כְּרַחֵם אָב עַל בָּנִים. מִי יְרַחֵם עַל רַבִּי אֶלְעָזָר וְיַשְׁלִים דְּבָרָיו, חוּץ מֵאַהֲבַת מוֹרֵנוּ? אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִשְׁמֹעַ דְּבָרִים אֵלּוּ לְפָנָיו, שֶׁלֹּא נֵבוֹשׁ בָּהֶם לָעוֹלָם הַבָּא."],[3,"","אָמַר רַבִּי אַבָּא, הֲרֵי כֹּהֵן אוֹן לֹא כָתוּב בְּיִתְרוֹ, אֲבָל כֹּהֵן מִדְיָן כָּתוּב. אָמַר לוֹ, הַכֹּל אֶחָד. בַּתְּחִלָּה חָמִיו שֶׁל יוֹסֵף נִקְרָא כֹּהֵן אוֹן, וְאַחַר כָּךְ חָמִיו שֶׁל מֹשֶׁה - כֹּהֵן מִדְיָן. וְהַכֹּל סוֹד אֶחָד. שֶׁהֲרֵי שְׁנֵי אֵלֶּה, מֹשֶׁה וְיוֹסֵף, עוֹמְדִים בְּדַרְגָּה שֶׁל סוֹד אֶחָד בְּסוֹד הָאוֹת וָ\"ו, שְׁנֵי וָוִי\"ם כְּאֶחָד. וּמַה שֶּׁנֶּאֱמַר כֹּהֵן מִדְיָן, סוֹד זֶה אֵשֶׁת מִדְיָנִים. (משהויוסףבסודאחדעומדים, וסוד זה ו\"ו, שנים כאחד)."],[4,"","הֵרִים יָדָיו עַל רֹאשׁוֹ רַבִּי אַבָּא וּבָכָה. אָמַר, אוֹר הַתּוֹרָה עוֹלֶה עַתָּה עַד רוּם הָרָקִיעַ שֶׁל הַכִּסֵּא הָעֶלְיוֹן, אַחַר שֶׁיִּסְתַּלֵּק מוֹרֵנוּ מֵהָעוֹלָם, מִי יָאִיר אֶת אוֹר הַתּוֹרָה? אוֹי לָעוֹלָם שֶׁיִּשָּׁאֵר יָתוֹם מִמְּךְ, אֲבָל דִּבְרֵי רַבֵּנוּ יָאִירוּ בָּעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וְאָז כָּתוּב (ישעיה יא) וּמָלְאָה הָאָרֶץ דֵּעָה אֶת ה' וְגוֹ'."],[5,"","וַיִּשְׁמַע יִתְרוֹ כֹּהֵן וְגוֹ'. רַבִּי חִיָּיא אָמַר, פָּסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, בַּתְּחִלָּה כָּתוּב אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה, וְאַחַר כָּךְ כָּתוּב כִּי הוֹצִיא ה'. אֶלָּא סוֹד זֶה אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים, זֶה הַשֵּׁם שֶׁהֵגֵן עַל מֹשֶׁה וְעַל יִשְׂרָאֵל וְלֹא זָז מֵהֶם בַּגָּלוּת, וְאַחַר כָּךְ הַשֵּׁם הָעֶלְיוֹן הוֹצִיא אוֹתָם מִמִּצְרַיִם, שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ שֶׁהוֹצִיא אוֹתָם הָיָה בְּסוֹד הַיּוֹבֵל."],[6,"","דָּבָר אַחֵר אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה - כְּשֶׁנִּזְרַק לַנָּהָר, וּכְשֶׁהִצִּיל אוֹתוֹ מֵחֶרֶב פַּרְעֹה, וְאֶת יִשְׂרָאֵל עַמּוֹ, שֶׁכָּתוּב (שמות כ) וַיִּשְׁמַע אֱלֹהִים אֶת נַאֲקָתָם. וְכָתוּב (שם א) וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ."],[7,"","וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן. רַבִּי יוֹסֵי פָּתַח, (תהלים קיא) פְּדוּת שָׁלַח לְעַמּוֹ צִוָּה לְעוֹלָם בְּרִיתוֹ קָדוֹשׁ וְנוֹרָא שְׁמוֹ. מַה שּׁוֹנֶה בְּכָל שְׁאַר הַפְּסוּקִים, שֶׁבְּכֻלָּם שְׁתֵּי תֵבוֹת מֵאַלְפָא בֵּיתָא, וּבְפָסוּק זֶה וְשֶׁלְּאַחֲרָיו שָׁלֹשׁ שָׁלֹשׁ? אֶלָּא כְּדֵי לְהַשְׁלִים שִׁשָּׁה צְדָדִים בָּאַלְפָא בֵּיתָא הַזֶּה, זֶה כְּנֶגֶד שְׁלֹשׁ הַגְּאֻלּוֹת שֶׁל יִשְׂרָאֵל, חוּץ מֵהַגְּאֻלָּה הָרִאשׁוֹנָה, פָּסוּק אַחֵר כְּנֶגֶד תּוֹרָה נְבִיאִים וּכְתוּבִים, וְהַכֹּל תָּלוּי בַּחָכְמָה הַזּוֹ."],[8,"","פְּדוּת שָׁלַח לְעַמּוֹ - כְּשֶׁגָּאַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל מִגָּלוּת מִצְרַיִם וְעָשָׂה לָהֶם נִסִּים וּגְבוּרוֹת. צִוָּה לְעוֹלָם בְּרִיתוֹ - כְּשֶׁבָּא יִתְרוֹ וְקִבְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְקֵרְבוֹ לַעֲבוֹדָתוֹ, וּמִשָּׁם הִתְקָרְבוּ כָּל אוֹתָם גֵּרִים תַּחַת כַּנְפֵי הַשְּׁכִינָה. מִשָּׁם וָהָלְאָה, קָדוֹשׁ וְנוֹרָא שְׁמוֹ. שֶׁהֲרֵי אָז הִתְקַדֵּשׁ שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי (מהצד האחר) מִתְקַדֵּשׁ שֵׁם הַקָּדוֹשׁ, כְּשֶׁנִּשְׁבָּר וְנִכְפֶּה הַצַּד הָאַחֵר, כְּמוֹ שֶׁהָיָה בְּיִתְרוֹ."],[9,"","וַיִּשְׁמַע יִתְרוֹ וְגוֹ', וְכִי יִתְרוֹ שָׁמַע וְכָל הָעוֹלָם לֹא שָׁמַע, וַהֲרֵי כָּתוּב (שמות טו) שָׁמְעוּ עַמִּים יִרְגָּזוּן?! אֶלָּא כָּל הָעוֹלָם שָׁמְעוּ וְלֹא נִשְׁבְּרוּ, וְהוּא שָׁמַע וְנִשְׁבַּר וְנִכְפָּה מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְקָרַב לְיִרְאָתוֹ."]]],[["רַבִּי אַבָּא אָמַר, בְּכַמָּה אֲתָר תָּנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל מַה דְּעָבַד לְעֵילָּא וְתַתָּא כֹּלָּא אִיהוּ קְשׁוֹט, וְעוֹבָדָא דִּקְשׁוֹט. וְלֵית לָךְ מִלָּה בְּעָלְמָא דְּבָעֵי בַּר נָשׁ לְדַחְיָא לֵיהּ מִנֵּיהּ, וּלְאַנְהָגָא בֵּיהּ קְלָנָא, דְּהָא כֻּלְּהוּ עוֹבָדָא דִּקְשׁוֹט אִינּוּן, וְכֹלָּא אִצְטְרִיךְ בְּעָלְמָא.","דְּהָא זִמְנָא חֲדָא, הֲוָה ר' אֶלְעָזָר אָזִיל בְּאָרְחָא, וַהֲוָה אָזִיל עִמֵּיהּ ר' חִזְקִיָּה, חָמוּ חַד חִוְיָא, קָם ר' חִזְקִיָּה לְמִקְטְלֵיהּ. אֲמַר לֵיהּ ר' אֶלְעָזָר, שָׁבִיק לֵיהּ לָא תְּקַטְלִינֵיהּ. אֲמַר לֵיהּ, וְהָא מִלָּה בִּישָׁא אִיהוּ, דְּקָטִיל בְּנִי נָשָׁא. אֲמַר לֵיהּ לְרַ' חִזְקִיָּה, וְהָא כְּתִיב (קהלת י׳:י״א) אִם יִשּׁוֹךְ הַנָּחָשׁ בְּלֹא לָחַשׁ. לָא נָשִׁיךְ חִוְיָא לְבַר נָשׁ, עַד דְּלָחֲשִׁין לֵיהּ מִלְּעֵילָּא, וְאַמְרֵי לֵיהּ זִיל קָטִיל לֵיהּ לִפְלָנַיָּא.","וּלְזִמְנִין כְּמָה דְּעָבִיד הַאי, הָכִי נָמֵי שֵׁזִיב לְבַר נָשׁ, מִמִּלִּין אַחֲרָנִין, וְעַל יְדוֹי אַרְחִישׁ קוּדְשָׁא בְּרִיךְ הוּא נִיסָא לִבְנֵי נָשָׁא, וְכֹלָּא בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא תַּלְיָא, וְכֹלָּא אִיהוּ עוֹבָדֵי יְדוֹי, וְאִצְטְרִיךְ עָלְמָא לְהוּ, וְאִי לָאו דְּאִיצְטְרִיךָ לוֹן עָלְמָא, לָא עָבֵד לוֹן קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא לָא בָּעֵי בַּר נָשׁ לְאַנְהָגָא בְּהוּ קְלָנָא בְּמִלֵּי דְּעָלְמָא. בְּמִלּוֹי וּבְעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא עַל אַחַת כַּמָּה וְכַמָּה.","פָּתַח וְאָמַר, (בראשית א׳:ל״א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנִּה טוֹב מְאֹד. וַיַּרְא אֱלהִים: דָּא אֱלהִים חַיִּים. וַיַּרְא: דְּאִסְתָּכַּל לְאַנְהָרָא לוֹן, וּלְאַשְׁגָּחָא לוֹן. אֶת כָּל אֲשֶׁר עָשָׂה כֹּלָּא בִּכְלָלָא חֲדָא, עֵילָּא וְתַתָּא. וְהִנֵּה טוֹב: דָּא סִטְרָא דִּימִינָא. מְאֹד: דָּא סִטְרָא דִּשְׂמָאלָא, וְהָא אוּקְמוּהָ, טוֹב: דָּא מַלְאַךְ חַיִּים מְאֹד: דָּא מַלְאַךְ הַמָּוֶת. וְכֹלָּא רָזָא חֲדָא. רָזָא הוּא, לְאִינוּן דְּמִסְתַּכְלֵי בְּרָזָא דְּחָכְמְתָא.","וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה. בְּכָל עוֹבָדָא דִּבְרֵאשִׁית, כְּתִיב, וַיַּרְא אֱלהִים כִּי טוֹב, וְהָכָא וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה. אֱלֹהִים לְתַתָּא, שָׁלִיט עַל תַּתָּאֵי. אֱלהִים לְעֵילָּא, שָׁלִיט עַל עִלָּאֵי. דָּא אִיהוּ רָזָא דֶּאֱלהִים חַיִּים, (נ\"א דבר אחר כלא איהו אלהים חיים) דְּאַנְהִיר וְאַדְלִיק כָּל אִינּוּן בּוּצִינִין עִלָּאִין וְתַתָּאִין, וּמִתַּמָּן נָפְקִין כָּל אִינּוּן נְהוֹרִין לְאַנְהָרָא.","\u0003תוספתא\u0004 בִּטְמִירוּ דִּטְמִירִין, אִתְרְשִׁים רְשִׁימוּ חַד, דְּלָא אִתְחָזֵי וְלָא אִתְגַּלְיָא. הַהוּא רְשִׁימוּ, רָשִׁים וְלָא רָשִׁים. מָארֵי דְּסָכְלְתָנוּ, וּפִקְחִין דְּעַיְינִין, לָא יַכְלִין לְמֵיקָם בֵּיהּ. אִיהוּ קִיּוּמָא דְּכֹלָּא. הַהוּא רְשִׁימוּ אִיהוּ זְעֵיר, דְּלָא אִתְחַזְיָא וְלָא אִתְגַּלְיָא. קַיְּימָא בִּרְעוּתָא, לְקַיְּימָא כֹּלָּא. לְנַטְלָא מַה דְּנַטְלָא, מִמַּה דְּלֵית בֵּיהּ רְשִׁימוּ, וְלָא רְעוּתָא, דְּלָא אִתְחָזֵי.","הַהוּא רְשִׁימוּ בָּעָא לְאַחֲפָיָא גַּרְמֵיהּ, וְעָבִיד לֵיהּ לְגַרְמֵיהּ, לְאִתְטַמְּרָא בֵּיהּ, חַד הֵיכָלָא. הַהוּא הֵיכָלָא אַפִּיק לֵיהּ מִגַרְמֵיהּ, וּמָתַח לֵיהּ בִּמְתִּיחוּ רַב וְסַגִּיא לְכָל סִטְרִין, אוֹקִיר לֵיהּ בִּלְבוּשֵׁי יְקָר, פָּתַח לֵיהּ חַמְשִׁין תַּרְעִין.","לְגוֹ בְּגוֹ, אִתְטָמַּר וְאִתְגְּנִיז הַהוּא רְשִׁימוּ. כֵּיוָן דְּאִתְגְּנִיז בֵּיהּ, וְעָאל בְּגַוֵּיהּ, אִתְמַלְיָא נְהוֹרָא. מֵהַהוּא נְהִירוּ, נַבְעִין נְהוֹרִין, וְנִצוֹצִין נָפְקִין מֵאִינּוּן תַּרְעִין, וְנָהֲרִין כֹּלָּא.","הַהוּא הֵיכָלָא אִתְחַפְיָיא בְּשִׁית יְרִיעָן. אִינּוּן שִׁית יְרִיעָן, אִינּוּן חֲמֵשׁ. לְגוֹ בְּגוֹ אִינּוּן יְרִיעָן, קַיְּימָא חַד יְרִיעָא מְרֻקָּמָא, בְּהַהוּא יְרִיעָה אִתְחַפְיָיא הַהוּא הֵיכָלָא, מִנֵּיהּ אַשְׁגַּח וְחָמָא לְכֹלָּא.","הַאי הֵיכָלָא אִיהוּ פְּקִיחָא דְּעַיְינִין, דְּלָא נָיִים. אִיהוּ אַשְׁגַּח תָּדִיר לְאַנְהָרָא לְתַתָּא, מִגּוֹ נְהִירוּ דְּהַהוּא רְשִׁימוּ. הַהוּא סָכְלְתָנוּ, חָכְמְתָא טְמִירְתָּא, רְעוּ דִּרְעוּתִין (ס\"א בעו דבעותין) הֲוֵי גָּנִיז וְטָמִיר, וְלָא אִתְגַּלְיָא, קַיְּימָא וְלָא קַיְּימָא. בְּרִיךְ הוּא מִטְּמִיר דִּטְמִירוּ, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עַד אָמֵן. (ע\"כ תוספתא)","תָּא חֲזִי, יִתְרוֹ הוּא דְּיָהַב עֵיטָא לְמֹשֶׁה, עַל תִּקּוּנָא דְּדִינִין, הָכִי אִצְטְרִיךְ. וְרָזָא דָּא דְּאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְסִדֵּר קָמֵיהּ תִּקּוּנָא דְּדִינוֹי, לְאַחֲזָאָה מַה דִּכְתִּיב, (דברים א׳:י״ז) כִּי הַמִּשְׁפָּט לֵאלהִים הוּא, וְלָא לְסִטְרָא אַחֲרָא. וְדִינִין לְיִשְׂרָאֵל אִתְיְיהִיבוּ, וְלָא לְאַחֲרָא, דִּכְתִּיב, (תהילים קמ״ז:י״ט) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. וְתָּא חֲזֵי, לָא יַנְהִיג בַּר נָשׁ קְלָנָא בְּאַחֲרָא, וּמִלָּה דְּהֶדְיוֹטָא, מִלָּה אִיהוּ. דְּהָא בְּמֹשֶׁה כְּתִיב, וַיִּשְׁמַע מֹשֶׁה לְקוֹל חוֹתְנוֹ וְגוֹ'."],[[0,"ר' אבא אמר וכו':","רא\"א, בכמה מקומות למדנו, שהקב\"ה כל מה שעושה למעלה ולמטה הכל הוא אמת ופעולתו אמת. ואין לך דבר בעולם, שהאדם צריך לדחותו ולנהוג בו בזיון, כי כולם פעולות אמת הם, והכל נצרך בעולם."],[1,"דהא זמנא חדא וכו':","כי פעם אחת, היה ר' אלעזר הולך בדרך, והיה הולך עמו ר' חזקיה. ראו נחש אחד. קם ר' חזקיה להרגו. אמר לו ר' אלעזר, עזוב אותו, אל תהרגו. אמר לה והרי דבר רע הוא, שהורג בני אדם. אמר לו לר' חזקיה, והרי כתוב אם ישוך הנחש בלא לחש. אין הנחש נושך בני אדם עד שלוחשים לו מלמעלה, ואומרים לו לך הרוג את פלוני."],[2,"ולזמנין כמה דעביד וכו':","ולפעמים כמו שעושה זה, כן מציל את האדם מדברים אחרים. ועל ידו עושה הקב\"ה נס לבני אדם. והכל בידי הקב\"ה תלוי, והכל הוא מעשה ידיו, והעולם צריך להם, ואם לא היה העולם צריך להם לא עשה אותם הקב\"ה. וע\"כ אין האדם צריך לנהוג בהם בזיון בדברי העולם, בדבריו ובמעשה הקב\"ה על אחת כמה וכמה."],[3,"פתח ואמר וכו':","פתח ואמר, וירא אלקים את כל אשר עשה והנה טוב מאוד. \u0003וירא אלקים,\u0004 זה אלקים חיים, שהוא בינה. \u0003וירא,\u0004 פירושו שהסתכל להאיר להם ולהשגיח עליהם. \u0003את כל אשר עשה,\u0004 הכל בכלל אחד,למעלה ולמטה. \u0003והנה טוב,\u0004 זהו צד ימין. \u0003מאד\u0004 זהו צד שמאל. וכבר העמידוהו, \u0003טוב,\u0004 זה מלאך חיים, \u0003מאד,\u0004 זה מלאך המות. והכל סוד אחד. סוד הוא לאלו שמסתכלים בסוד החכמה."],[4,"וירא אלקים את כל אשר עשה:","שואל, בכל מעשה בראשית, כתוב, וירא אלקים כי טוב. וכאן, וירא אלקים את כל אשר עשה. ומשיב. אלקים למטה, שהיא המלכות, שולט על תחתונים. אלקים למעלה, שהיא בינה, שולט על העליונים. אלקים למעלה השולט על עליונים זהו סוד אלקים חיים, שהיא בינה. שזהו וירא אלקים את כל אשר עשה, כי האיר והדליק כל אלו הנרות העליונים והתחתונים ומשם יוצאים כל אלו האורות להאיר."],[5,"בטמירו דטמירין אתרשים וכו':","במכוסה מכל המכוסים, שהוא פרצוף עתיק, נרשם רושם אחד שהוא הרושם דמסך דמלכות דמדת הדין המשתמשת בעתיק, שלא נראה ואינו מתגלה. רושם ההוא, רושם פרצוף שני, שהוא אריך אנפין, ואינו רושם, כי לא נרשם ממנו. בעלי התבונה, ועינים פקוחות, שהם בעלי החכמה, אינם יכולים לעמוד עליו. הוא קיום הכל. רושם ההוא, שבא\"א, הוא קטן עד שאינו נראה, ואינו מתגלה, עומד שם ברצון לקיים הכל. כלומר, שמציאותו נרגש, רק ברצון שיהיה, כי בגללה מתקיים הכל, לקבל מה שמקבל ממה שאין בו רשימו ולא רצון, ואינו נראה, שהוא א\"ס ב\"ה. ולולא הרושם ההוא לא יכלו לקבל מא\"ס ב\"ה."],[5,"","פירוש. התוספתא מבאר לפנינו, סדר אצילות של פרצופי אצילות, עתיק וא\"א ואו\"א וז\"א. ואיך מקור הכל הוא המסך דמלכות דמדת הדין המשתמשת בפרציף עתיק, ופועלת בא\"א, להסתים שם החכמה. ואיך חלק ממנה נמתק בבינה, הנק' היכל, והיא עצמה נגנזה בג\"ר של היכל, שהם או\"א עלאין. ואח\"כ מבאר ו\"ק דז\"א בסוד ששה יריעות, ויריעה המרוקמת שה\"ס הג\"ר דז\"א וכו' כמו שמבואר לפנינו."],[6,"ההוא רשימו בעא וכו':","הרושם ההוא רצה לכסות עצמו, ועשה לו לעצמו כדי להתכסות בו, היכל אחד. דהיינו שהעלה חלק ממנו להתמתק בבינה, ואז נעשה הבינה להיכל. הוציא אותו מעצמו, דהיינה שהעלה חלק ממנו לבינה, ומשך אותו בהתפשטות רבה וגדולה, דהיינו הארת חכמה, המאירה לכל הצדדים, והוקיר אותו בלבוש, יקר, דהיינו אור החסדים להלביש החכמה, ופתח בו חמשים שערים."],[7,"לגו בגו אתטמר וכו':","לפני ולפנים, שבאותו היכל, דהיינו בג\"ר שבו, הנקראים או\"א עלאין, נתכסה ונגנז רושם ההוא, כיון שנגנז בו ונכנס בתוכו נתמלאו או\"א עלאין באור. מאור ההוא נובעים אורות, וניצוצים שהוא או\"ח ויוצאים מאלו השערים שבהיכל, ומאירים כולם."],[8,"ההוא היכלא אתחפייא וכו':","היכל ההוא מתכסה, כלומר שנתלבש, בשש יריעות, שהם ז\"א, שיש בו שש ספירות חג\"ת נה\"י. אלו שש יריעות הם חמשה, כי יסוד אינו ספירה מיוחדת, אלא הוא כולל של ה' ספירות חג\"ת נ\"ה בלבד. לפני ולפנים של אלו היריעות עומדת יריעה אחת מרוקמת, שהיא הג\"ר של היריעות, ביריעה הזו מתכסה, ומתלבש ההיכל, כלומר היא הראשונה המלבשת להיכל שהיא בינה, ועליה שאר שש היריעות. ממנה הוא משגיח ורואה הכל. כלומר, היא הג\"ר שנוהג בהן ראיה."],[9,"האי היכלא איהו וכו':","היכל הזה הוא פקיחת עינים שלא ינום, דהיינו, שמשגיח תמיד להאיר למטה, מתוך האור של רושם ההוא הנזכר. שהוא אור החסדים. תבונה ההיא, חכמה המכוסה, ורצון הרצונות שהוא הכתר, דהיינו הג\"ר שבהיכל, הנקראים או\"א עלאין, הוא גנוז ומכוסה, ואינו מתגלה, נמצא ואינו נמצא. ברוך הוא ממכוסה של כל המכוסים, שהוא כתר, ברוך הוא לעולם ולעולמי עד, אמן. (ע\"כ תוספתא)"],[10,"תא חזי יתרו וכו':","בוא וראה, יתרו, הוא שנתן עצה למשה על תקון הדינים. וכך צריך להיות. וז\"ס שהודה להקב\"ה, וסדר לפניו תקון דיניו. להורות מה שכתוב, כי המשפט לאלקים הוא, ולא לסטרא אחרא. והדינים ניתנו לישראל ולא לאחר. שכתוב, חקיו ומשפטיו לישראל. ובוא וראה, לא ינהג אדם בזיון באחר, ודבר מהדיוט, הוא דבר. שהרי במשה כתוב, וישמע משה לקול חותנו וגו'."]],[[0,"","רַבִּי אַבָּא אָמַר, בְּכַמָּה מְקוֹמוֹת שָׁנִינוּ, שֶׁכָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה - הַכֹּל אֱמֶת וּמַעֲשֵׂה אֱמֶת. וְאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁצָּרִיךְ אָדָם לִדְחוֹתוֹ וְלִנְהֹג בּוֹ קָלוֹן, שֶׁהֲרֵי כֻּלָּם מַעֲשֵׂי אֱמֶת הֵם, וְהַכֹּל צָרִיךְ בָּעוֹלָם."],[1,"","שֶׁהֲרֵי פַּעַם אַחַת הָיָה רַבִּי אֶלְעָזָר הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה הוֹלֵךְ עִמּוֹ רַבִּי חִזְקִיָּה. רָאוּ נָחָשׁ אֶחָד. קָם רַבִּי חִזְקִיָּה לַהֲרֹג אוֹתוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, עֲזב אוֹתוֹ, אַל תַּהֲרֹג אוֹתוֹ. אָמַר לוֹ, וַהֲרֵי הוּא דָּבָר רַע שֶׁהוֹרֵג בְּנֵי אָדָם. אָמַר לוֹ לְרַבִּי חִזְקִיָּה, וַהֲרֵי כָּתוּב (קהלתי) אִם יִשֹּׁךְ הַנָּחָשׁ בְּלוֹא לָחַשׁ. לֹא נוֹשֵׁךְ הַנָּחָשׁ אֶת הָאָדָם עַד שֶׁלּוֹחֲשִׁים לוֹ מִלְמַעְלָה וְאוֹמְרִים לוֹ לֵךְ הֲרֹג אֶת פְּלוֹנִי."],[2,"","וְלִפְעָמִים כְּמוֹ שֶׁעָשָׂה זֶה, כָּךְ גַּם מַצִּיל אֶת הָאָדָם מִדְּבָרִים אֲחֵרִים, וְעַל יָדוֹ מַרְחִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס לִבְנֵי אָדָם, וְהַכֹּל תָּלוּי בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַכֹּל מַעֲשֵׂי יָדָיו. וְצָרִיךְ אוֹתָם הָעוֹלָם. וְאִם הָעוֹלָם לֹא הָיָה צָרִיךְ אוֹתָם, לֹא הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אוֹתָם. וְלָכֵן לֹא צָרִיךְ אָדָם לִנְהֹג בָּהֶם קָלוֹן בְּדִבְרֵי הָעוֹלָם. בִּדְבָרָיו וּמַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַחַת כַּמָּה וְכַמָּה."],[3,"","פָּתַח וְאָמַר, וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. וַיַּרְא אֱלֹהִים - זֶה אֱלֹהִים חַיִּים. וַיַּרְא - שֶׁהִסְתַּכֵּל לְהָאִיר לָהֶם וּלְהַשְׁגִּיחַ עֲלֵיהֶם. אֶת כָּל אֲשֶׁר עָשָׂה - הַכֹּל בִּכְלָל אֶחָד, מַעְלָה וּמַטָּה. וְהִנֵּה טוֹב - זֶה צַד הַיָּמִין. מְאֹד - זֶה צַד הַשְּׂמֹאל. וַהֲרֵי פֵּרְשׁוּהָ, טוֹב - זֶה מַלְאַךְ הַחַיִּים. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת. וְהַכֹּל סוֹד אֶחָד. סוֹד הוּא לְאוֹתָם שֶׁמִּתְבּוֹנְנִים בְּסוֹד הַחָכְמָה."],[4,"","וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה (בראשית א). בְּכָל מַעֲשֵׂה בְרֵאשִׁית כָּתוּב וַיַּרְא אֱלֹהִים כִּי טוֹב, וְכָאן - וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה. אֱלֹהִים לְמַטָּה שׁוֹלֵט עַל הַתַּחְתּוֹנִים, אֱלֹהִים לְמַעְלָה שׁוֹלֵט עַל הָעֶלְיוֹנִים. זֶהוּ סוֹד שֶׁל אֱלֹהִים חַיִּים, (דבר אחר, הכל הוא אלהים חיים) שֶׁמֵּאִיר וּמַדְלִיק כָּל אוֹתָם מְקוֹרוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, וּמִשָּׁם יוֹצְאִים כָּל אוֹתָם אוֹרוֹת לְהָאִיר."],[5,"","בַּמְכֻסֶּה שֶׁבַּמְכֻסִּים נִרְשָׁם רֹשֶׁם אֶחָד שֶׁלֹּא נִרְאֶה וְלֹא הִתְגַּלָּה אוֹתוֹ רֹשֶׁם רָשׁוּם וְלֹא רָשׁוּם. בַּעֲלֵי הַתְּבוּנָה וְעֵינַיִם פְּקוּחוֹת לֹא יְכוֹלִים לַעֲמֹד בּוֹ. הוּא קִיּוּם הַכֹּל. אוֹתוֹ הָרֹשֶׁם הוּא קָטָן, שֶׁלֹּא נִרְאָה וְלֹא הִתְגַּלָּה. עוֹמֵד בְּרָצוֹן לְקַיֵּם הַכֹּל. לְקַבֵּל מַה שֶּׁמְּקַבֵּל מִמַּה שֶׁאֵין בּוֹ רֹשֶׁם וְלֹא רָצוֹן, שֶׁלֹּא נִרְאֶה."],[6,"","אוֹתוֹ הָרֹשֶׁם רוֹצֶה לְכַסּוֹת אֶת עַצְמוֹ, וְעוֹשֶׂה אוֹתוֹ לְעַצְמוֹ לְהִטָּמֵן בּוֹ הֵיכָל אֶחָד. אוֹתוֹ הֵיכָל מוֹצִיא אוֹתוֹ מֵעַצְמוֹ, וּמוֹתֵחַ אוֹתוֹ בִּמְתִיחָה גְּדוֹלָה וְרַבָּה לְכָל הַצְּדָדִים, מְכַבֵּד אוֹתוֹ בִּלְבוּשֵׁי כָבוֹד, וּפוֹתֵחַ לוֹ חֲמִשִּׁים שְׁעָרִים."],[7,"","לִפְנַי וְלִפְנִים נִטְמָן וְנִגְנָז אוֹתוֹ רֹשֶׁם. כֵּיוָן שֶׁנִּגְנָז בּוֹ וְנִכְנָס לְתוֹכוֹ, מִתְמַלֵּא בְּאוֹר. מֵאוֹתוֹ הָאוֹר נוֹבְעִים אוֹרוֹת, וְנִיצוֹצוֹת יוֹצְאִים מֵאוֹתָם הַשְּׁעָרִים, וּמְאִירִים הַכֹּל."],[8,"","אוֹתוֹ הֵיכָל מְכֻסֶּה בְּשֵׁשׁ יְרִיעוֹת. אוֹתָן שֵׁשׁ יְרִיעוֹת הֵן חָמֵשׁ. לִפְנַי וְלִפְנִים אוֹתָן יְרִיעוֹת עוֹמֶדֶת יְרִיעָה אַחַת רְקוּמָה, וּבְאוֹתָהּ הַיְרִיעָה מִתְכַּסֶּה אוֹתוֹ הַהֵיכָל, מִמֶּנּוּ מַשְׁגִּיחַ וְרוֹאֶה הַכֹּל."],[9,"","הַהֵיכָל הַזֶּה הוּא פְּקִיחַת הָעֵינַיִם שֶׁלֹּא יָנוּם. הוּא מַשְׁגִּיחַ תָּמִיד לְהָאִיר לְמַטָּה מִתּוֹךְ הָאוֹר שֶׁל אוֹתוֹ הָרשֶׁם. אוֹתָהּ תְּבוּנָה, חָכְמָה נִסְתֶּרֶת, רְצוֹן הָרְצוֹנוֹת, (ב, קשת הב, קשות) הָיָה גָּנוּז וְטָמוּן, וְלֹא הִתְגַּלָּה, עוֹמֵד וְלֹא עוֹמֵד, בָּרוּךְ הוּא מְּהַמְכוּסֶה שֶּׁבָּמְכוּסִים בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עַד, אָמֵן."],[10,"","בֹּא וּרְאֵה, יִתְרוֹ הוּא שֶׁנָּתַן עֵצָה לְמֹשֶׁה עַל תִּקּוּן הַדִּינִים, כָּךְ צָרִיךְ. וְסוֹד זֶה שֶׁהוֹדָה לוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא וְסִדֵּר לְפָנָיו תִּקּוּן הַדִּינִים, לְהַרְאוֹת מַה שֶּׁכָּתוּב כִּי הַמִּשְׁפָּט לֵאלֹהִים הוּא, וְלֹא לַצַּד הָאַחֵר. וְהַדִּינִים נִתְּנוּ לְיִשְׂרָאֵל, וְלֹא לְאַחֵר, שֶׁכָּתוּב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. וּבא רְאֵה, לֹא יִנְהַג אָדָם קָלוֹן בְּאַחֵר, וּדְבַר הֶדְיוֹט דָּבָר הוּא, שֶׁהֲרֵי בְּמֹשֶׁה כָּתוּב וַיִּשְׁמַע מֹשֶׁה לְקוֹל חֹתְנוֹ וְגוֹ'."]]],[["וַיִּשְׁמַע יִתְרוֹ וְגוֹ'. פָּתַח וְאָמַר (תהילים י״ח:נ׳) עַל כֵּן אוֹדְךָ בַּגּוֹיִם יְיָ' וּלְשִׁמְךָ אֲזַמֵּרָה. דָּוִד מַלְכָּא אָמַר דָּא בְּרוּחַ קֻדְשָׁא, בְּשַׁעֲתָא דְּחָמָא, דְּהָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא אִסְתְּלִיק בִּסְלִיקוּ וְלָא אִתְיָיקְרָא בְּעָלְמָא, אֶלָּא מִסִּטְרָא דִּשְׁאַר עַמִין. וְאִי תֵּימָא, הָא קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְיָיקַר בְּעָלְמָא, אֶלָּא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. הָכִי הוּא וַדַּאי, דְּהָא יִשְׂרָאֵל אִינּוּן הֲוֵי יְסוֹדָא דִּשְׁרָגָּא לְאַנְהָרָא, אֲבָל כַּד שְׁאַר עַמִּין אָתָאן וְאוֹדָן לֵיהּ, בְּשִׁעְבּוּדָא דִּיְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין אִתּוֹסָף יְסוֹדָא דִּשְׁרָגָּא, וְאִתְתָּקַּף עַל כָּל עוֹבָדוֹי. בְּחִבּוּרָא חֲדָא, וְשָׁלִיט קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי עֵילָּא וְתַתָּא.","כְּגַוְונָא דָּא, כָּל עָלְמָא, דְּחִילוּ וְאֵימָתָא נָפַל עָלַיְיהוּ מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּאָתָא יִתְרוֹ, דְּאִיהוּ כּוֹמָרָא עִלָּאָה, דְּכָל טַעֲוָון אַחֲרָנִין, כְּדֵין אִתְתָּקַּף וְשָׁלִיט יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא.","בְּגִין, דְּכָל עָלְמָא, כַּד שָׁמְעוּ שֵׁמַע גְּבוּרְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, זָעוּ. וְכֻלְּהוּ הֲווֹ מִסְתַּכְּלָן בְּיִתְרוֹ, דְּאִיהוּ חַכִּים וְרַב מְמָנָא דְּכָל טַעֲוָון דְּעָלְמָא, כֵּיוָן דְּחָמוּ, דְּאִיהוּ אָתָא וּפָלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים, כְּדֵין כֻּלְּהוּ אִתְרַחֲקוּ מִפּוּלְחָנֵיהוֹן, וְיָדְעוּ דְּלֵית בְּהוּ מַמָּשׁוּ. כְּדֵין אִתְיָיקַר יְקָרָא דִּשְׁמָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל סִטְרִין. וְעַל דָּא אִתְרְשִׁים פַּרְשְׁתָּא דָּא בְּאוֹרַיְיתָא, וְשֵׁירוּתָא דְּפַרְשְׁתָּא הֲוָה בֵּיהּ בְּיִתְרוֹ.","יִתְרוֹ חַד מֵחַכִּימִין דְּפַרְעֹה הֲוָה. תְּלַת חַכִּימִין הֲווֹ לֵיהּ לְפַרְעֹה, חַד יִתְרוֹ, וְחַד אִיּוֹב, וְחַד בִּלְעָם. חַד יִתְרוֹ: דְּלָא הֲוָה פּוּלְחָנָא וּמְמַנָּא וְשַׁמָּשָׁא וְכֹכָבָא דְּשָׁלִיט עַל שׁוּלְטָנֵיהּ, דְּלָא הֲוָה יָדַע פּוּלְחָנָא דְּאִתְחָזֵי לֵיהּ, וְהַהוּא שִׁמּוּשָׁא דִּילֵיהּ. בִּלְעָם, הֲוָה חַרְשָׁא בְּכָל מִינִי חֲרָשִׁין בֵּין בְּעוֹבָדָא בֵּין בְּמִלָּה.","אִיּוֹב הֲוָה דָּחִיל בִּדְחִילוּ, וּבְהַהוּא דְּחִילוּ הֲוָה עִקָרָא דִּילֵיהּ, בְּגִין דְּמִלָּה דִּלְעֵילָּא, בֵּין דִּקְדוּשָׁה, בֵּין דְּסִטְרָא אַחֲרָא, לָא יָכִיל בַּר נָשׁ לְאַמְשָׁכָא רוּחָא דִּלְעֵילָּא לְתַתָּא וּלְמִקְרַב גַּבֵּיהּ, אֶלָּא בִּדְחִילוּ. וִיכַוֵּין לִבֵּיהּ וּרְעוּתֵיהּ בִּדְחִילוּ וּתְבִירוּ דְּלִבָּא, וּכְדֵין יַמְשִׁיךְ לְתַתָּא רוּחָא דִּלְעֵילָּא וּרְעוּתָא דְּאִצְטְרִיךְ.","וְאִי לָא יְשַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ בִּדְחִילוּ לְהַהוּא סִטְרָא, לָא יָכִיל לְאִתְדַּבְּקָא בֵּיהּ רְעוּתֵיהּ, בַּר לְהָנֵי טוֹפְסֵי דְּקִיקִין, וְלָא בְּכֻלְּהוּ, בְּגִין דְּאִית בְּהוּ שָׁלְטָנִין, דְּאִצְטְרִיךְ לְגַבַּיְיהוּ, רְעוּתָא דְּלִבָּא וּדְחִילוּ. כָּל שֶׁכֵּן אִינּוּן מִלִּין עִלָּאִין, דְּאִצְטְרִיךְ דְּחִילוּ וְאֵימָתָא וּרְעוּתָא יַתִּיר.","יִתְרוֹ אִצְטְרִיךְ פּוּלְחָנֵיהּ דְּהַהוּא סִטְרָא תָּדִיר, בֵּין בְּזִמְנָא דְּאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, בֵּין בְּזִמְנָא דְּלָא אִצְטְרִיךְ לֵיהּ, בְּגִין דְּהַהוּא סִטְרָא יְהֵא דָּבִיק לְגַבֵּיהּ, בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ. בִּלְעָם אִתְדָּבַּק בְּאִינּוּן חֲרָשִׁין, כְּמָה דְּאִתְּמַר.","אִיּוֹב בִּסְגִיאוּ דְּהַהוּא דְּחִילוּ דִּילֵיהּ אַהְדָּר בְּמִצְרַיִם לְמִדְחַל מִקָּמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד חָמָא אִינּוּן גְּבוּרָן וְנִסִּין, דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. יִתְרוֹ, לָא אַהְדָּר בְּכָל דָּא, עַד דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְכָל אִינּוּן קִשְׁרִין וְטִפְסִין דְּקָשִׁירוּ מִצְרָאֵי, לָא הֲווֹ כְּלוּם, וְנַפְקוּ. וּלְבָתַר דְּטָבַע לוֹן בְּיַמָּא, כְּדֵין תָּב, וְאַהְדָּר לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","בִּלְעָם לָא תָּב, וְלָא אַהְדָּר, דְּטִנּוּפָא (נ\"א דטפסא) דְּסִטְרָא אַחֲרָא הֲוָה מִתְדָּבַק בֵּיהּ, וְעִם כָּל דָּא אִסְתַּכְּלוּתָא דְּמֵרָחִיק הֲוָה מִסְתַּכֵּל, בְּגוֹ הַהוּא טִנּוּפָא (ס\"א טפסא) וְאִתְדַּבְּקוּתָא דְּסִטְרָא אַחֲרָא. דְּהָא בְּסִטְרָא אַחֲרָא אִית נְהִירוּ דָּקִיק חַד, דְּנָהִיר סַחֲרָנֵיהּ, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:ד׳) וְנֹגַהּ לוֹ סָבִיב. וְדָא אִסְתַּכְּלוּתָא זְעֵיר (ועל דא) הֲוָה מִסְתַּכֵּל מֵרָחִיק, וְלָא בְּכֻלְּהוּ מִלִּין.","וְכַד הֲוָה מִסְתַּכֵּל מִלָּה זְעֵיר מֵהַהוּא נְהִירוּ, כְּבָתַר כּוֹתָלָא הֲוָה, אָמַר וְלָא יָדַע מַאי קָאָמַר. וַהֲוָה מִסְתַּכֵּל בְּהַהוּא נְהִירוּ בִּסְתִימוּ דְּעֵינָא, וְאִתְגַּלְגַּל עֵינָא, וְחָזֵי בַּר נָשׁ נְהוֹרָא סְתִימָא, וְלָא חֲזִי. וְרָזָא דָּא (במדבר כ״ד:ג׳) שְׁתוּם הָעָיִן, וְאוּקְמוּהָ שְׁתוּם: סְתוּם, וְכֹלָּא חַד."],[[0,"וישמע יתרו וגו':","פתח ואמר. על כן אודך בגוים ה' ולשמך אזמרה. דוד המלך אמר זה ברוח הקודש, בשעה שראה שכבוד הקב\"ה אינו עולה בהתעלות ואינו מתיקר בעולם, אלא מצד שאר העמים. ואם תאמר, הרי הקב\"ה אינו מתיקר בעולם אלא בשביל ישראל. כן הוא ודאי, שהרי ישראל הם היסוד של הנר להאיר, אבל כאשר שאר העמים באים ומודים לו בשעבוד אל יקר של הקב\"ה, אז נתוסף יסודו של הנר, ומתחזק על כל מעשיו בחבור אחד, ושולט הקב\"ה לבדו למעלה ולמטה."],[1,"כגוונא דא כל וכו':","כעין זה. כל העולם נפל עליהם פחד ואימה לפני הקב\"ה, בעת ששמעו הנסים של יציאת מצרים. וכיון שבא יתרו, שהוא כומר עליון של כל אלהים אחרים, אז התחזק ושלט כבוד הקב\"ה על כל."],[2,"בגין דכל עלמא וכו':","משום שכל העולם כששמעו שמע גבורתו של הקב\"ה זעו, וכולם היו מסתכלים ביתרו, שהוא חכם וממונה הגדול על כל אלילי העולם, כיון שראו שהוא בא ועובד להקב\"ה, ואמר כי עתה ידעתי כי גדול ה' מכל האלהים. אז נתרחקו כולם מעבודתם, וידעו שאין בהם ממש, אז נתיקר יקרו של השם הקדוש של הקב\"ה בכל הצדדים. ועל כן נרשם פרשה זו בתורה ותחילת הפרשה הוא ביתרו."],[3,"יתרו חד מחכימין וכו':","יתרו היה אחד מחכמי פרעה. שלשה חכמים היה לו לפרעה, אחד יתרו, ואחד איוב, ואחד בלעם. אחד יתרו, שלא היה עבודה וממונה ושמש וכוכב השולט על ממשלתו, שלא היה יודע העבודה הראויה לו והשמוש שלו. בלעם היה מכשף בכל מיני כישוף בין במעשה ובין בדבור."],[4,"איוב הוה דחיל וכו':","איוב היה ירא ביראה, וביראה ההיא היה העיקר שלו, דהיינו עיקר כחו, משום, שמלה שלמעלה, בין של הקדושה, ובין של הסטרא אחרא, אינו יכול האדם להמשיך רוח שלמעלה למטה ולקרב אליו, אלא ביראה, שיכוון לבו ורצונו ביראה ושבירת הלב, ואז ימשיך למטה רוח שלמעלה, והרצון שצריך."],[5,"ואי לא ישוי וכו':","ואם לא ישים לבו ורצונו ביראה לאותו הצד, רצונו אינו יכול להתדבק בו. חוץ מאלו צורות הדקות, ולא בכולם, משום שיש בהם שליטים שצריכים אליהם רצון הלב ויראה. כל שכן אלו דברים עליונים שצריכים יראה ואימה ורצון ביותר."],[6,"יתרו אצטריך פולחניה וכו':","יתרו היה צריך לעבודה לאותו הצד תמיד, בין בזמן שאדם היה צריך לו, ובין בזמן שלא היה צריך לו, כדי שהצד ההוא יהיה דבוק בו בשעה שיהיה צריך לו. בלעם נתדבק באלו הכשפים, כמו שאמרנו."],[7,"איוב בסגיאו דההוא וכו':","איוב, ברוב היראה ההיא שלו, חזר במצרים לירא את הקב\"ה, כשראה אלו הגבורות והנסים שעשה הקב\"ה במצרים. יתרו, לא חזר להקב\"ה בכל זה, עד שיצאו ישראל ממצרים, שכל הקשרים והצורות שקשרו מצרים, לא היו כלום, ויצאו, ואחר שהטביע אותם בים, אז שב וחזר לעבודת הקב\"ה."],[8,"בלעם לא תב וכו':","בלעם לא שב ולא חזר, כי הטנוף של הסטרא אחרא היה מתדבק בו, ועם כל זה, הסתכלות מרחוק היה מסתכל בתוך הטנוף ההוא והדבקות בסטרא אחרא. כי בסטרא אחרא יש הארה דקה אחת שמאירה מסביב. כמש\"א ונגה לו סביב. והסתכלות זו הקטנה היה מסתכל מרחוק. ולא בכל הדברים."],[9,"וכד הוה מסתכל וכו':","וכשהיה מסתכל דבר קטן מתוך הארה ההוא, היה כמאחורי הקיר, אמר, ולא ידע מה אמר. והיה מסתכל בהארה ההוא בסתום שבעין, שמתגלגל העין, ואדם רואה אור סתום ואינו רואה. וז\"ס שתום העין, והעמדנו, שתום פירושו סתום, והכל אחד."]],[[0,"","וַיִּשְׁמַע יִתְרוֹ וְגוֹ'. פָּתַח וְאָמַר (תהלים יח) עַל כֵּן אוֹדְךְ בַּגּוֹיִם ה' וּלְשִׁמְךְ אֲזַמֵּרָה. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה בְּרוּחַ הַקֹּדֶשׁ בְּשָׁעָה שֶׁרָאָה שֶׁכְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹלֶה בַּעֲלִיָּה וְלֹא מִתְכַּבֵּד בָּעוֹלָם, אֶלָּא מִצַּד שְׁאָר הָעַמִּים. וְאִם תֹּאמַר, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִתְכַּבֵּד בָּעוֹלָם אֶלָּא מִשּׁוּם יִשְׂרָאֵל - כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי יִשְׂרָאֵל הֵם הַיְסוֹד שֶׁל הַנֵּר לְהָאִיר, אֲבָל כְּשֶׁשְּׁאָר הָעַמִּים בָּאִים וּמוֹדִים לוֹ בְּשִׁעְבּוּד הַכָּבוֹד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז נוֹסָף יְסוֹד הַנֵּר וּמִתְחַזֵּק עַל כָּל מַעֲשָׂיו בְּחִבּוּר אֶחָד, וְשׁוֹלֵט הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ מַעְלָה וּמַטָּה."],[1,"","כְּמוֹ זֶה כָּל הָעוֹלָם, אֵימָה וָפַחַד נָפַל עֲלֵיהֶם מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁבָּא יִתְרוֹ, שֶׁהוּא כֹּמֶר עֶלְיוֹן שֶׁל כָּל יֶתֶר הָאֱלִילִים, אָז הִתְחַזֵּק וְשָׁלַט כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַכֹּל."],[2,"","מִשּׁוּם שֶׁכָּל הָעוֹלָם, כְּשֶׁשָּׁמְעוּ שֵׁמַע גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, זָעוּ. וְכֻלָּם הָיוּ מִסְתַּכְּלִים בְּיִתְרוֹ שֶׁהוּא חָכָם וּמְמֻנֶּה גָּדוֹל שֶׁל כָּל אֱלִילֵי הָעוֹלָם. כֵּיוָן שֶׁרָאוּ שֶׁהוּא בָּא וְעוֹבֵד לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָדוֹל ה' מִכָּל הָאֱלֹהִים, אָז כֻּלָּם הִתְרַחֲקוּ מֵעֲבוֹדוֹתֵיהֶם וְיָדְעוּ שֶׁאֵין בָּהֶם מַמָּשׁ, וְאָז הִתְכַּבֵּד כְּבוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הַצְּדָדִים. וְלָכֵן נִרְשְׁמָה פָּרָשָׁה זוֹ בַּתּוֹרָה, וְרֵאשִׁית הַפָּרָשָׁה הָיָה בּוֹ, בְּיִתְרוֹ."],[3,"","יִתְרוֹ הָיָה אֶחָד מֵחַכְמֵי פַרְעֹה. לְפַרְעֹה הָיוּ שְׁלֹשָׁה חֲכָמִים - אֶחָד יִתְרוֹ, וְאֶחָד אִיּוֹב, וְאֶחָד בִּלְעָם. אֶחָד יִתְרוֹ - שֶׁלֹּא הָיְתָה עֲבוֹדָה וּמְמֻנֶּה וְשַׁמָּשׁ וְכוֹכָב שֶׁשּׁוֹלֵט עַל שִׁלְטוֹנוֹ שֶׁלֹּא הָיָה יוֹדֵעַ הָעֲבוֹדָה שֶׁרְאוּיָה לוֹ וְאוֹתוֹ הַשִּׁמּוּשׁ שֶׁלּוֹ. בִּלְעָם הָיָה מְכַשֵּׁף בְּכָל מִינֵי כְשָׁפִים, בֵּין בְּמַעֲשֶׂה בֵּין בְּדִבּוּר."],[4,"","אִיּוֹב הָיָה פּוֹחֵד בְּפַחַד, וּבְאוֹתוֹ פַּחַד הָיָה עִקָּרוֹ, מִשּׁוּם שֶׁדָּבָר שֶׁלְּמַעְלָה, בֵּין שֶׁל קְדֻשָּׁה בֵּין שֶׁל הַצַּד הָאַחֵר, לֹא יָכוֹל אָדָם לִמְשֹׁךְ רוּחַ שֶׁלְּמַעְלָה לְמַטָּה וְלִקְרַב אֵלָיו אֶלָּא בְּפַחַד, וִיכַוֵּן לִבּוֹ וּרְצוֹנוֹ בְּפַחַד וּבְשִׁבְרוֹן הַלֵּב, וְאָז יַמְשִׁיךְ לְמַטָּה רוּחַ שֶׁלְּמַעְלָה וְהָרָצוֹן שֶׁהִצְטָרֵךְ."],[5,"","וְאִם לֹא יָשִׂים לִבּוֹ וּרְצוֹנוֹ בְּפַחַד לְאוֹתוֹ הַצַּד, לֹא יוּכַל לְהַדְבִּיק בּוֹ רְצוֹנוֹ, פְּרָט לְאוֹתָם הַצּוּרוֹת הַדַּקִּיקוֹת, וְלֹא בְּכֻלָּם, מִשּׁוּם שֶׁיֵּשׁ בָּהֶם שַׁלִּיטִים שֶׁצְּרִיכִים אֲלֵיהֶם אֶת רְצוֹן הַלֵּב וְהַפַּחַד. כָּל שֶׁכֵּן אוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁצָּרִיךְ אֵימָה וָפַחַד וְרָצוֹן יוֹתֵר."],[6,"","יִתְרוֹ הִצְטָרֵךְ עֲבוֹדָתוֹ שֶׁל אוֹתוֹ הַצַּד תָּמִיד, בֵּין בִּזְמַן שֶׁצָּרִיךְ לוֹ לָאָדָם וּבֵין בִּזְמַן שֶׁלֹּא צָרִיךְ לוֹ, כְּדֵי שֶׁאוֹתוֹ הַצַּד יִדְבַּק אֵלָיו בְּשָׁעָה שֶׁצָּרִיךְ אוֹתוֹ. בִּלְעָם נִדְבַּק בְּאוֹתָם כְּשָׁפִים, כְּמוֹ שֶׁנִּתְבָּאֵר."],[7,"","אִיּוֹב, בְּרֹב אוֹתוֹ הַפַּחַד שֶׁלּוֹ, חָזַר בְּמִצְרַיִם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁרָאָה אוֹתָם גְּבוּרוֹת וְנִסִּים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. יִתְרוֹ לֹא חָזַר בְּכָל זֶה, עַד שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. וְכָל אוֹתָם קְשָׁרִים וְהַצּוּרוֹת שֶׁקָּשְׁרוּ הַמִּצְרִים, לֹא הָיוּ כְלוּם, וְיָצְאוּ. וְאַחַר שֶׁטִּבַּע אוֹתָם בַּיָּם, אָז שָׁב וְחָזַר לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","בִּלְעָם לֹא שָׁב וְלֹא חָזַר, שֶׁטִּנֹּפֶת (שצורת) הַצַּד הָאַחֵר הָיָה דָּבוּק בּוֹ, וְעִם כָּל זֶה הָיָה מִסְתַּכֵּל הִסְתַּכְּלוּת שֶׁל מֶרְחָק בְּתוֹךְ אוֹתָהּ טִנֹּפֶת (צורה) וְהִדָּבְקוּת לַצַּד הָאַחֵר, שֶׁהֲרֵי בַּצַּד הָאַחֵר יֵשׁ אוֹר דַּקִּיק אֶחָד שֶׁמֵּאִיר סְבִיבוֹ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאלא) וְנֹגַהּ לוֹ סָבִיב. וְזוֹ הִסְתַּכְּלוּת קְטַנָּה (ועל זה) הָיָה מִסְתַּכֵּל מֵרָחוֹק, וְלֹא בְּכָל הַדְּבָרִים."],[9,"","וּכְשֶׁהָיָה מִסְתַּכֵּל דָּבָר קָטָן מֵאוֹתוֹ הָאוֹר, זֶה הָיָה כְּמֵאַחֲרֵי הַכֹּתֶל. אָמַר וְלֹא יָדַע מָה אָמַר. וְהָיָה מִסְתַּכֵּל בְּאוֹתוֹ הָאוֹר בִּסְתִימוּת הָעַיִן, וְהָעַיִן מִתְגַּלְגֶּלֶת, וְרוֹאֶה הָאָדָם אוֹר סָתוּם וְלֹא רוֹאֶה. וְסוֹד זֶה שְׁתֻם הָעָיִן, וּפֵרְשׁוּהָ שְׁתֻם - סְתוּם, וְהַכֹּל אֶחָד."]]],[["דְּהָא לֵית סִטְרָא אַחֲרָא, דְּלֵית בֵּיהּ נְהִירוּ דָּקִיק זְעֵיר מִסִּטְרָא דִּקְדוּשָּׁה, כְּגַוְונָא דְּרוֹב חֶלְמִין, דְּבִסְגִיאוּת תַּבְנָא, אִית חַד גַּרְעִינָא דְּחִטִּין. בַּר אִלֵּין טַפְסֵי דְּקִיקִין חֲצִיפִין, דְּכֻלְּהוּ מְסָאֲבֵי יַתִּיר. וּבְהוּ הֲוָה בִּלְעָם יוֹדֵעַ.","זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּאִיהוּ לְעֵילָּא בְּכָל קְדוּשִׁין עִלָּאִין, וְאִסְתַּכַּל, בְּמָה דְּלָא אִתְיְיהִב רְשׁוּ לְבַר נָשׁ אַחֲרָא בְּעָלְמָא לְאִסְתַּכְּלָא. וּכְמָה דְּבִלְעָם הֲוָה חָמֵי נְהִירוּ זְעֵיר דָּקִיק כְּמִבָּתַר כּוֹתָלָא, מִגּוֹ הַהוּא סִטְרָא אַחֲרָא. אוּף הָכִי מֹשֶׁה, מִגּוֹ נְהִירוּ עִילָּאָה רַב וְסַגִּי, הֲוָה חָמֵי לְתַתָּא כְּמִבָּתַר כּוֹתָלָא, חַד חֲשׁוֹכָא דָּקִיק, דְּאִתְחֲזֵי לֵיהּ. וְלָאו בְּכָל זִמְנָא, כְּמָה דְּבִלְעָם לָא הֲוָה מִסְתַּכֵּל הַהוּא נְהִירוּ בְּכָל זִמְנָא.","זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, מַה כְּתִיב בֵּיהּ, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. הַסְּנְה וַדַּאי הֲוָה בְּגוֹ הַהוּא קְדוּשָׁה וְאִתְדָבַּק בֵּיהּ. דְּכֹלָּא אִתְדָּבַּק דָּא בְּדָא, טָהוֹר וְטָמֵא, לֵית טָהוֹר אֶלָּא מִגּוֹ טָמֵא.","וְרָזָא דָּא, (איוב י״ד:ד׳) מִי יִתֵּן טָהוֹר מִטָּמֵא. קְלִיפָה וּמוֹחָא דָּא בְּדָא סַלְּקָא. וְדָא קְלִיפָה לָא יִתְעֲדֵי וְלָא יִתְּבַּר, עַד זִמְנָא דִּיקוּמוּן מֵתִין מֵעַפְרָא, כְּדֵין יִתְּבַּר קְלִיפָה, וּנְהִירוּ יַנְהִיר בְּעָלְמָא בְּלֹא סְתִימוּ מִגּוֹ מוֹחָא. זַכָּאִין אִינּוּן צַדִּיקַיָּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","וְאֵת שְׁנֵי בָּנֶיהָ, אָמַר רַבִּי חִיָּיא, וְכִי בָּנְיהָ וְלֹא בָּנָיו שֶׁל מֹשֶׁה. אֶלָּא, בְּגִין דְּאִיהִי אִשְׁתַּדְּלַת אֲבַתְרַיְיהוּ, בְּלָא בַּעְלָהּ, קָרָא לוֹן אוֹרַיְיתָא בָּנֶיהָ, וְלֹא בָּנָיו. אָמַר רִבִּי יוֹסִי, אַף עַל גַּב דִּבְנוֹי דְּמֹשֶׁה הֲווֹ. מִלָּה דִּקְשׁוֹט בָּנֶיהָ וַדַּאי. ר' אֶלְעָזָר אָמַר, הָא מֹשֶׁה הֲוָה מִזְדַּוֵּוג בַּאֲתָר אַחֲרָא קַדִּישָׁא עִלָּאָה, וְלָאו יְקָרָא דִּילֵיהּ לְמִקְרֵי לוֹן בָּנָיו. הַשְׁתָּא אַף עַל גַּב דִּבְנוֹי הֲווֹ, בְּגִין יְקָרָא דְּהַהוּא אֲתָר דְּאִזְדָּוַּוג בֵּיהּ, קָרָא לוֹן בָּנֶיהָ הָכָא, לְבָתַר קָרָא לוֹן בָּנָיו מַאי טַעְמָא, בְּגִין דְּהַהוּא שַׁעֲתָא דְּמָטוּ, הֲוָה מֹשֶׁה מְמַלֵּל בִּשְׁכִינְתָּא. לְבָתַר דְּאִתְפְּרַשׁ וְנָפַק לְגַבֵּי חָמוּי, כְּדֵין כְּתִיב (שמות י״ח:ה׳) וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ וְגוֹ'.","אָמַר ר' שִׁמְעוֹן, אֶלְעָזָר אֶלְעָזָר, אָנָא חֲמֵינָא בְּפַרְשְׁתָּא דָּא, דְּאַתְּ שָׁארֵי מִלָּה כְּדְקָא יֵאוֹת, וְסִיּוּמָא לָאו הָכִי. וַדַּאי בְּגִין יְקָרָא דִּשְׁכִינְתָּא, אִזְדַּוְּוגוּתָא עִלָּאָה דְּאִזְדָּוַּוג בֵּיהּ בְּמֹשֶׁה, כְּתִיב בָּנְיהָ. וְאִי תֵּימָא, וְהָא כְּתִיב וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה. כֹּלָּא אִיהוּ כְּלָלָא חֲדָא. וּבָנָיו, בָּנָיו דְּיִתְרוֹ, דְּהָא לְבָתַר דְּאָתָא מֹשֶׁה לְגַבֵּיהּ, הֲווֹ לֵיהּ בְּנִין.","וְהָכִי הֲוָה בְּיַעֲקֹב, דְּכֵיוָן דְּאָתָא לְגַבֵּיהּ דְּלָבָן, וְשַׁוֵּי דִּיוֹרֵיהּ בֵּיהּ, הֲווֹ לֵיהּ בְּנִין. אוּף הָכָא מֹשֶׁה, כֵּיוָן דְּשַׁוֵּי דִּיוֹרֵיהּ בְּיִתְרוֹ, הֲווֹ לֵיהּ לְיִתְרוֹ בְּנִין וְכָל בֵּיתֵיהּ אַיְיתֵי עִמֵּיהּ, לְמֵיעַל לוֹן תְּחוֹת גַּדְפֵּי דִּשְׁכִינְתָּא, וְיִתְרוֹ אָמַר לְמֹשֶׁה, אֲנִי חוֹתֶנְךָ יִתְרוֹ בָּא אֵלֶיךָ וְאִשְׁתְּךָ וּשְׁנִי בָּנֶיהָ עִמָּהּ, וּשְׁנֵי בָּנֶיהָ כְּתִיב, וְלָא כְּתִיב וּשְׁנֵי בָּנֶיךָ. (ס\"א ויבא יתרו חתן משה ובניו) בְּנִין הֲווֹ לֵיהּ לְיִתְרוֹ, דִּכְתִּיב, (שופטים א׳:ט״ז) וּבְנִי קֵנִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים וּבְנוֹי שָׁבַק עִם מֹשֶׁה.","וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה. פָּתַח וְאָמַר, (ישעיהו ב׳:ג׳) וְהָלְכוּ עַמִּים רָבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר יְיָ' וְגוֹ'. הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אֲתָר. אֲבָל זְמִינִין שְׁאַר עַמִּין לְמֵהַךְ וּלְכַתְּתָא רַגְלַיְיהוּ, לְמֵיעַל תְּחוֹת גַּדְפֵּי דִּשְׁכִינְתָּא. לְכוּ וְנַעֲלֶה, כָּל טַעֲוָון דְּעָלְמָא אִית לוֹן יְרִידָה, וְקוּדְשָׁא בְּרִיךְ הוּא מַאן דְּאִתְדַּבָּק בֵּיהּ, אִית בֵּיהּ עֲלִיָּה.","אֶל הַר יְיָ', דָּא אַבְרָהָם, דִּכְתִּיב, (בראשית כ״ב:י״ד) אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר יְיָ' יֵרָאֶה, דְּהָא אַבְרָהָם קָרֵי לֵיהּ הַר. מַה הַר הֶפְקֵירָא לְכָל מַאן דְּבָעֵי בְּעָלְמָא, אוּף אֲתָר דָּא קַדִּישָׁא, הֶפְקֵירָא לְקַבְּלָא לְכָל מַאן דְּבָעֵי בְּעָלְמָא. אֶל בֵּית, דָּא יַעֲקֹב, דְּקָרָא לְהַאי אֲתָר בַּיִת, דִּכְתִּיב, (בראשית כח) אֵין זֶה כִּי אִם בֵּית אֱלהִים."],[[0,"דהא לית סטרא וכו':","אין סטרא אחרא שאין בה הארה דקה וקטנה מצד הקדושה. כעין רוב החלומות, שבהרבה תבן יש גרעין אחד של חטה. חוץ מאלו צורות הקטנות, שכולם טמאים ביותר. ובהם היה בלעם יודע."],[1,"זכאה חולקיה דמשה וכו':","אשרי חלקו של משה, שהוא למעלה בכל קדושות העליונות, והסתכל במה שלא ניתן רשות לאדם אחר בעולם להסתכל, וכמו שבלעם היה רואה הארה קטנה ודקה כמאחורי הקיר, מתוך סטרא אחרא ההוא, אף משה, מתוך הארה עליונה רבה וגדולה, היה רואה למטה כמאחורי הקיר, חשכות אחת דקה, שנראה לו. ולא בכל עת, כמו שבלעם לא היה מסתכל בהארה ההוא בכל עת."],[2,"זכאה חולקיה דמשה נביאה וכו':","אשרי חלקו של משה הנביא הנאמן. מה כתוב בו, וירא מלאך ה' אליו בלבת אש מתוך הסנה. הסנה, שהוא קליפה, היה ודאי בקדושה ההיא, ונתדבק בה, שהכל מתדבק זה בזה, טהור וטמא, ואין טהור אלא מתוך טמא."],[3,"ורזא דא מי וכו':","וז\"ס מי יתן טהור מטמא. קליפה ומוחא עולים זה בזה. וקליפה זו לא תהיה נעדרת ולא תשבר, עד הזמן שיקומו המתים מעפר. אז תשבר הקליפה, והאור יאיר בעולם, בלא סתימה, מן המוח. אשרי הם הצדיקים בעולם הזה ובעולם הבא."],[4,"ואת שני בניה:","אמר ר' חייא, וכי בניה היו ולא בניו של משה. ומשיב, אלא משום שהיא השתדלה אחריהם בלי בעלה, קרא אותם התורה, בניה, ולא בניו. אמר ר' יוסי, אע\"פ שהיו בניו של משה, דבר אמת, היינו ע\"פ סוד, ודאי בניה היו, כי, ר' אלעזר אמר, משה היה מתחבר במקום אחר קדוש עליון, ואין כבודו לקרוא אותם בניו. עתה אע\"פ שבניו היו, משום כבודו של מקום ההוא שהתחבר בו, שהוא השכינה, קרא אותם בניה כאן, לאחר כך, קרא אותם בניו. מהו הטעם. משום שבשעה ההוא שהגיעו למשה, היה משה מדבר עם השכינה. אחר כך אחר שנפרד מן השכינה, ויצא לקראת חותנו, אז כתוב ויבא יתרו חתן משה \u0003ובניו\u0004 וגו'."],[5,"אמר ר' שמעון וכו':","אר\"ש, אלעזר אלעזר, אני רואה בפרשה זו, שהתחלת הדבר כראוי. אבל הסיום אינו כן כמו שאמרת. ודאי שבשביל כבוד השכינה, שהיא התחברות העליון שהתחבר בו במשה, כתוב בניה. ואם תאמר, הרי כתוב, ויבא יתרו חתן משה ובניו ואשתו אל משה, שקורא אותם בניו, הכל הוא כלל אחד, ומה שאומר, בניו, היינו בניו דיתרו. כי לאחר שבא משה אליו היה לו בנים."],[6,"והכי הוה ביעקב וכו':","וכן היה ביעקב, כיון שבא אצל לבן ושם משכנו עמו, היו לו בנים. אף כאן, משה, כיון ששם משכנו עם יתרו, היה לו בנים. וכל ביתו הביא עמו להכניס אותם תחת כנפי השכינה. ויתרו אמר למשה אני חתנך יתרו בא אליך ואשתך ושני בניה עמה. ולא כתוב ושני בניך. מאין לנו שבנים היו לו ליתרו, שכתוב, ובני קני חתן משה עלו מעיר התמרים. ובניו עזב עם משה."],[7,"ויבא יתרו חתן משה וגו':","פתח ואמר, והלכו עמים רבים ואמרו לכו ונעלה אל הר ה'. מקרא זה העמידוהו בכמה מקומות. אבל עתידים שאר העמים ללכת ולכתת רגליהם, לבא תחת כנפי השכינה. לכו ונעלה, כל אלילי העולם יש להם ירידה, והקב\"ה מי שמתדבק בו, יש בו עליה. ע\"כ כתוב לכו ונעלה."],[8,"אל הר ה':","זה אברהם, שכתוב, אשר יאמר היום בהר ה' יראה. כי אברהם קרא לו הר (פסחים פח.) מה הר הפקר לכל מי שרוצה בעולם, אף מקום זה הקדוש, בית המקדש, הוא לקבל לכל מי שרוצה בעולם. \u0003אל בית\u0004, זה יעקב, שקרא למקום הזה בית. שכתוב, אין זה כי אם בית אלקים."]],[[0,"","שֶׁהֲרֵי אֵין צַד אַחֵר שֶׁאֵין בּוֹ אוֹר דַּקִּיק קָטָן מִצַּד הַקְּדֻשָּׁה, כְּמוֹ רֹב הַחֲלוֹמוֹת, שֶׁבְּרֹב הַתֶּבֶן יֵשׁ גַּרְעִין אֶחָד שֶׁל חִטָּה, פְּרָט לַצּוּרוֹת הַדַּקִּיקוֹת הַלָּלוּ הַחֲצוּפוֹת שֶׁכֻּלָּם יוֹתֵר טְמֵאוֹת, וּבָהֶם הָיָה בִּלְעָם יוֹדֵעַ."],[1,"","אֲשֶׁר חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהוּא לְמַעְלָה בְּכָל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת, וְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא נִתְּנָה רְשׁוּת לְאָדָם אַחֵר בָּעוֹלָם לְהִסְתַּכֵּל. וּכְמוֹ שֶׁבִּלְעָם הָיָה רוֹאֶה אוֹר קָטָן דַּקִּיק כְּמֵאֲחוֹרֵי הַכֹּתֶל מִתּוֹךְ אוֹתוֹ הַצַּד הָאַחֵר, אַף כָּךְ מֹשֶׁה מִתּוֹךְ אוֹר עֶלְיוֹן גָּדוֹל וָרַב הָיָה רוֹאֶה לְמַטָּה כְּמֵאֲחוֹרֵי הַכֹּתֶל חֹשֶׁךְ דַּקִּיק אֶחָד שֶׁנִּרְאָה לוֹ, וְלֹא בְּכָל זְמַן, כְּמוֹ שֶׁבִּלְעָם לֹא הָיָה מִסְתַּכֵּל בְּאוֹתוֹ אוֹר בְּכָל זְמַן."],[2,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן, מַה כָּתוּב בּוֹ? (שמותג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. הַסְּנֶה הָיָה וַדַּאי בְּתוֹךְ אוֹתָהּ קְדֻשָּׁה, וְנִדְבַּק בּוֹ. שֶׁהַכֹּל נִדְבַּק זֶה בָּזֶה, טָהוֹר וְטָמֵא. אֵין טָהוֹר אֶלָּא מִתּוֹךְ טָמֵא."],[3,"","וְסוֹד זֶה - (איוב יד) מִי יִתֵּן טָהוֹר מִטָּמֵא. קְלִפָּה וּמֹחַ עוֹלִים זֶה בָּזֶה, וּקְלִפָּה זוֹ לֹא תָזוּז וְלֹא תִשָּׁבֵר עַד הַזְּמַן שֶׁבּוֹ יָקוּמוּ הַמֵּתִים מִן הֶעָפָר, אָז תִּשָּׁבֵר הַקְּלִפָּה, וְאוֹר יָאִיר בָּעוֹלָם בְּלִי סֵתֶר מִתּוֹךְ הַמֹּחַ. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[4,"","וְאֵת שְׁנֵי בָנֶיהָ. אָמַר רַבִּי חִיָּיא, וְכִי בָנֶיהָ וְלֹא בָּנָיו שֶׁל מֹשֶׁה? אֶלָּא מִשּׁוּם שֶׁהִיא הִשְׁתַּדְּלָה אַחֲרֵיהֶם בְּלִי בַעְלָהּ, קָרְאָה לָהֶם הַתּוֹרָה בָּנֶיהָ וְלֹא בָּנָיו. אָמַר רַבִּי יוֹסֵי, אַף עַל גַּב שֶׁבְּנֵי מֹשֶׁה הָיוּ, דְּבַר אֱמֶת בָּנֶיהָ וַדַּאי. רַבִּי אֶלְעָזָר אָמַר, הֲרֵי מֹשֶׁה הָיָה מִזְדַּוֵּג בְּמָקוֹם אַחֵר קָדוֹשׁ עֶלְיוֹן, וְלֹא כְּבוֹדוֹ לִקְרֹא לָהֶם בָּנָיו. עַכְשָׁו, אַף עַל גַּב שֶׁבָּנָיו הָיוּ, מִשּׁוּם כְּבוֹד אוֹתוֹ מָקוֹם שֶׁהִזְדַּוֵּג בּוֹ, קָרָא לָהֶם כָּאן בָּנֶיהָ, וְאַחַר כָּךְ קָרָא לָהֶם בָּנָיו. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָהּ הַשָּׁעָה שֶׁהִגִּיעוּ, הָיָה מֹשֶׁה מְדַבֵּר בַּשְּׁכִינָה. אַחַר שֶׁנִּפְרַד וְיָצָא אֶל חָמִיו, אָז כָּתוּב וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ וְגוֹ'."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר אֶלְעָזָר, אֲנִי רוֹאֶה שֶׁבַּפָּרָשָׁה הַזּוֹ שֶׁאַתָּה מַתְחִיל אֶת הַדָּבָר כָּרָאוּי, אַךְ הַסִּיּוּם לֹא כָּךְ. וַדַּאי בִּשְׁבִיל כְּבוֹד הַשְּׁכִינָה, הִזְדַּוְּגוּת הָעֶלְיוֹנָה שֶׁנִּזְדַּוְּגָה בְּמֹשֶׁה, כָּתוּב בָּנֶיהָ. וְאִם תֹּאמַר, וַהֲרֵי כָתוּב וַיָּבא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה? הַכֹּל הוּא כְּלָל אֶחָד. וּבָנָיו - בָּנָיו שֶׁל יִתְרוֹ, שֶׁהֲרֵי לְאַחַר שֶׁבָּא אֵלָיו מֹשֶׁה, הָיוּ לוֹ בָּנִים."],[6,"","וְכָךָ הָיָה בְּיַעֲקֹב, שֶׁכֵּיוָן שֶׁבָּא אֶל לָבָן וְשָׂם בּוֹ אֶת דִּיּוּרוֹ, הָיוּ לוֹ בָּנִים. אַף כָּאן מֹשֶׁה, כֵּיוָן שֶׁשָּׂם דִּיּוּרוֹ בְּיִתְרוֹ, הָיוּ לְיִתְרוֹ בָּנִים, וְאֶת כָּל בֵּיתוֹ הֵבִיא עִמּוֹ לְהַכְנִיסָם תַּחַת כַּנְפֵי הַשְּׁכִינָה. וְיִתְרוֹ אָמַר לְמֹשֶׁה, אֲנִי חֹתֶנְךְ יִתְרוֹ בָּא אֵלֶיךְ וְאִשְׁתְּךְ וּשְׁנֵי בָנֶיהָ עִמָּהּ. כָּתוּב וּשְׁנֵי בָנֶיהָ, וְלֹא כָתוּב וּשְׁנֵי בָנֶיךְ. (ויבא יתרו חתן משה ובניו) בָּנִים הָיוּ לוֹ לְיִתְרוֹ, שֶׁכָּתוּב (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים. וּבָנָיו הִשְׁאִיר עִם מֹשֶׁה."],[7,"","וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה. פָּתַח וְאָמַר, (ישעיה ב) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ בְּכַמָּה מְקוֹמוֹת. אֲבָל עֲתִידִים שְׁאָר הָעַמִּים לָלֶכֶת וּלְכַתֵּת רַגְלֵיהֶם לְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה. לְכוּ וְנַעֲלֶה - כָּל אֱלִילֵי הָעוֹלָם יֵשׁ לָהֶם יְרִידָה, וּמִי שֶׁנִּדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא יֵשׁ לוֹ עֲלִיָּה."],[8,"","אֶל הַר ה' - זֶה אַבְרָהָם, שֶׁכָּתוּב (בראשית כב) אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר ה' יֵרָאֶה, שֶׁהֲרֵי אַבְרָהָם קָרָא לוֹ הַר. מַה הַר הֶפְקֵר לְכָל מִי שֶׁרוֹצֶה בָּעוֹלָם, אַף מָקוֹם קָדוֹשׁ זֶה הֶפְקֵר כְּנֶגֶד כָּל מִי שֶׁרוֹצֶה בָּעוֹלָם. אֶל בֵּית - זֶה יַעֲקֹב, שֶׁקָּרָא לְמָקוֹם זֶה בַּיִת, שֶׁכָּתוּב (שם כח) אֵין זֶה כִּי אִם בֵּית אֱלֹהִים."]]],[["דָּבָר אַחֵר, הַר וּבַיִת, אַף עַל גַּב דְּכֹלָּא חַד דַּרְגָּא, סְלִיקוּ לְדָא מִן דָּא, הַר, לִשְׁאַר עַמִּין, כַּד אָתָאן לְאָעָלָא תְּחוֹת גַּדְפּוֹי. בַּיִת, לְיִשְׂרָאֵל, לְמֶהֱוֵי עִמְּהוֹן כְּאִתְּתָא בְּבַעְלָהּ. בְּדִיּוּרָא חַד בְּחֶדְוָוה, וּרְבִיעָא עָלַיְיהוּ כְּאִימָּא עַל בְּנִין.","תָּא חֲזֵי מָה כְּתִיב הָכָא בְּיִתְרוֹ וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבַנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה וְגו' כֵּיוָן דִכְתִיב אֶל מֹשֶׁה אַמָּאי כְּתִיב אֶל הַמִּדְבָּר. אֶלָּא עִיקָרָא דְכֹלָא לְמָה דַהֲוָה אָתֵי אֶל הַמִּדְבָּר. וּמָאן אִיהוּ הַר הָאֱלהִים דְדָּא אִיהוּ אֲתַר לְגַיוּרֵי לְאִתְגַיְירָא וְעַל דָא כְּתִיב אֶל מֹשֶׁה אֶל הַמִּדְבָּר לְמֹשֶׁה לְגַיְירָא לוֹן וּלְאַעָלָא לוֹן תֵחוֹת גַּדְפֵי שְׁכִינְתָּא אֶל הַמִּדְבָּר הֲווּ אַתְיָין דְּאִיהוּ הַר הָאֱלֹהִים לְמֶעְבָּד נַפְשָׁיְיהוּ","וּבְגִין כַּךְ קַיְּימָא הַהוּא אֲתָר, בְּרָזָא דְּהַר דְּכָל מַאן דְּאָתֵי זָכֵי בֵּיהּ. וְאִקְרֵי (ויקרא קס\"ח ע\"א) גֵּר צֶדֶק. וְהָא אוֹקִימְנָא, גֵּר, אַף עַל גַּב דְּאִתְדַּבָּק בַּאֲתָר דָּא עִלָּאָה קַדִּישָׁא, כֵּיוָן דְּשָׁבַק עִמֵּיהּ וַאֲבַהְתוֹי (ואתדבק בבריתו), גֵּר (צדק) אִקְרֵי, כְּמַאן דְּשַׁוֵּי מָדוֹרֵיהּ בַּאֲתָר דְּלָא יָדַע מִקַּדְמַת דְּנָא.","רַבִּי יִצְחָק וְרַבִּי יוֹסִי, הֲווֹ יַתְבֵי יוֹמָא חַד וְלָעָאן בְּאוֹרַיְיתָא בִּטְבֶרְיָא. אַעְבָּר רַבִּי שִׁמְעוֹן, אָמַר לוֹן בְּמַאי עַסְקִיתּוּ, אָמְרוּ לֵיהּ, בְּהַאי קְרָא דְּאוֹלִיפְנָא מִנֵּיהּ דְּמֹר, אָמַר לוֹן מַאי אִיהוּ. אָמְרוּ לֵיהּ, הַאי דִּכְתִּיב, (בראשית ה׳:א׳) זֶה סֵפֶר תוֹלְדוֹת אָדָם בְּיוֹם בְּרוֹא אֱלהִים אָדָם בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. וְהָא אִתְּמַר, דְּאַחְמֵי קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם הָרִאשׁוֹן, כָּל אִינּוּן דָּרִין דַּהֲווֹ זְמִינִין לְמֵיתֵי לְעָלְמָא, וְכָל אִינּוּן פַּרְנָסִין, וְכָל אִינּוּן חַכִּימִין, דַּהֲווֹ זְמִינִין בְּכָל דָּרָא וְדָרָא.","וְרָזָא אוֹלִיפְנָא, זֶה סֵפֶר. אִית סֵפֶר וְאִית סֵפֶר. סֵפֶר לְעֵילָּא, סֵפֶר לְתַתָּא. סֵפֶר לְתַתָּא אִקְרֵי סֵפֶר הַזִּכָּרוֹן, סֵפֶר דְּהַהוּא זִכָּרוֹן, וְדָא חַד צַדִּיק, וְאִקְרֵי זֶה. וּבְגִין דְּלָא לְאַפְרְשָׁא לוֹן, דְּאִינּוּן תָּדִיר כַּחֲדָא בְּיִחוּדָא חֲדָא, כְּתִיב, זֶה סֵפֶר תְּרֵין דַּרְגִּין דְּאִינּוּן חַד, כְּלָלָא דְּכַר וְנוּקְבָּא.","וְדָא אִיהוּ כְּלָלָא חֲדָא, דְּכָל אִינּוּן נִשְׁמָתִין וְרוּחִין דְּפַרְחִין בִּבְנֵי נָשָׁא, כְּלָלָא דְּכָל תוֹלְדוֹת, אִינּוּן בְּרָזָא תוֹלְדוֹת אָדָם וַדַּאי. דְּהָא מֵהַהוּא צַדִּיק דְּקָאָמַר, פַּרְחִין אִינּוּן נִשְׁמָתִין בְּתִיאוּבְתָּא חֲדָא, וְדָא אִיהוּ שַׁקְיוּ דְּגִנְתָּא דְּאַשְׁקֵי הַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְדָא אִיהוּ רָזָא דְּאָדָם, דִּכְתִּיב תוֹלְדוֹת אָדָם."],[[0,"ד\"א הר ובית וכו':","פי' אחר. הר ובית, אע\"פ שהכל מדרגה אחת, עולה זה על זה, הר, הוא לשאר העמים, כשבאים להכנס תחת כנפיו. בית, הוא לישראל, להיות עמהם כאשה עם בעלה בדירה אחת בשמחה, ורובץ עליהם כאם על הבנים."],[1,"תא חזי מה וכו':","בוא וראה, מה כתוב כאן ביתרו. ויבא יתרו וגו' אל משה אל המדבר. שואל, כיון שכתוב, אל משה למה כתוב אל המדבר. ומשיב, אלא עיקר הכל הוא מה שיתרו בא אל המדבר, ומי הוא. הוא הר האלקים, שזהו המקום לגרים להתגייר. ועל כן כתוב, אל משה אל המדבר. \u0003אל משה\u0004, היינו לגייר אותם ולהביאם תחת כנפי השכינה. \u0003אל המדבר\u0004, היו באים. שהוא הר האלקים, לעשות נפשותם, כלומר לקבל משם נפש הגר."],[2,"ובגין כך קיימא וכו':","ומשום זה עומד המקום ההוא בסוד, הר. שכל מי שבא זוכה בו. ונקרא גר צדק. והרי העמדנו, גר נקרא אע\"פ שנתדבק במקום זה העליון הקדוש, כי מפני שעזב עמו ואבותיו נקרא גר. גר צדק נקרא, כמי ששם דירתו במקום שלא ידע מקודם לכן, דהיינו בהשכינה שנקראת צדק."],[3,"ר' יצחק ור' יוסי וכו':","ר\"י ור\"י היו יום אחד יושבים ולומדים בתורה בטבריה. עבר לפניהם ר' שמעון. אמר להם, במה אתם עוסקים. אמרו לו, במקרא זה שלמדנו מן אדוננו. אמר להם מה הוא. אמרו לו, זה שכתוב, זה ספר תולדות אדם ביום ברוא אלקים אדם בדמות אלקים עשה אותו. והרי למדנו, שהראה הקב\"ה את אדם הראשון כל אלו הדורות שעתידים לבא לעולם, וכל אלו פרנסים וכל אלו החכמים העתידים להיות בכל דור ודור."],[4,"ורזא אוליפנא וכו':","וסוד למדנו, \u0003זה ספר,\u0004 יש ספר ויש ספר. יש ספר למעלה ויש ספר למטה. הספר למטה נקרא ספר הזכרון שפירושו, ספר של זכרון ההוא, והוא צדיק אחד, דהיינו יסוד, ונקרא \u0003זה.\u0004 והמלכות היא הספר שלו, וכדי שלא להפרידם, כי הם תמיד ביחד, ביחוד אחד, ע\"כ כתוב, \u0003זה ספר.\u0004 שתי מדרגות שהם אחת, שהם כלל של זכר ונקבה, כי זה היא זכר שהוא יסוד, וספר הוא נקבה. שהיא מלכות."],[5,"ודא איהו כללא חדא וכו':","וזה הוא כלל אחד. שכל אלו הנשמות והרוחות הפורחות בבני אדם, שהם כלל של כל התולדות, הם בסוד תולדות אדם ודאי, דהיינו תולדות אדם העליון שהוא ז\"א. כי מצדיק הזה, שאמרנו, פורחות אלו הנשמות בתשוקה אחת. וזה הוא השקוי של הגן, שמשקה נהר ההוא היוצא מעדן, שכתוב, ונהר יוצא מעדן להשקות את הגן, שפירושו, שהיסוד משפיע הנשמות והרוחות של הגן, שהוא מלכות. וזהו הסוד של אדם, שכתוב, תולדות אדם."]],[[0,"","דָּבָר אַחֵר הַר וּבַיִת - אַף עַל גַּב שֶׁהַכֹּל דַּרְגָּה אַחַת, מַּעֲלֶה לָזֶה מִן זֶה. הַר לִשְׁאָר הָעַמִּים, כְּשֶׁבָּאִים לְהִכָּנֵס תַּחַת כְּנָפָיו. בַּיִת לְיִשְׂרָאֵל, לִהְיוֹת עִמָּם כְּמוֹ אִשָּׁה לְבַעְלָהּ, בְּדִיּוּר אֶחָד בְּשִׂמְחָה, וְרוֹבֶצֶת עֲלֵיהֶם כְּאֵם עַל הַבָּנִים."],[1,"","בֹּא וּרְאֵה מַה כָּתוּב כָּאן בְּיִתְרוֹ, וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה וְגוֹ'. כֵּיוָן שֶׁכָּתוּב אֶל מֹשֶׁה, לָמָּה כָּתוּב אֶל הַמִּדְבָּר? אֶלָּא הָעִקָּר שֶׁל הַכֹּל לְמַה שֶּׁהָיָה בָּא, אֶל הַמִּדְבָּר. וּמַהוּ? הַר הָאֱלֹהִים, שֶׁזֶּהוּ מָקוֹם לְגֵרִים לְהִתְגַּיֵּר. וְעַל זֶה כָּתוּב אֶל מֹשֶׁה אֶל הַמִּדְבָּר. לְמֹשֶׁה לְגַיֵּר אוֹתָם וּלְהַכְנִיסָם תַּחַת כַּנְפֵי הַשְּׁכִינָה. אֶל הַמִּדְבָּר הָיוּ בָּאִים, שֶׁהוּא הַר הָאֱלֹהִים, לַעֲשׂוֹת בָּהֶם נַפְשׁוֹתָם."],[2,"","וְלָכֵן עוֹמֵד אוֹתוֹ מָקוֹם בְּסוֹד שֶׁל הַר, שֶׁכָּל מִי שֶׁרוֹצֶה זוֹכֶה בּוֹ. וְנִקְרָא גֵּר צֶדֶק. וַהֲרֵי בֵּאַרְנוּ, גֵּר - אַף עַל גַּב שֶׁנִּדְבָּק בְּמָקוֹם קָדוֹשׁ עֶלְיוֹן זֶה, כֵּיוָן שֶׁעָזַב אֶת עַמּוֹ וְאֶת אֲבוֹתָיו (ונדבקבבריתו), גֵּר (צדק) נִקְרָא, כְּמִי שֶׁשָּׂם מְדוֹרוֹ בְּמָקוֹם שֶׁלֹּא הִכִּיר מִקֹּדֶם לָכֵן."]]],[["לְבָתַר בְּיוֹם בְּרוֹא אֱלהִים אָדָם, דָּא אָדָם דִּלְתַתָּא, דְּהָא תְּרֵין אָדָם כְּתִיבֵי בְּהַאי קְרָא, חַד רָזָא דִּלְעֵילָּא, וְחַד רָזָא דִּלְתַתָּא, אָדָם דְּאִיהוּ רָזָא דִּלְעֵילָּא, אִיהוּ בִּגְנִיזוּ, דְּגָנִיז קְרָא, בִּדְכַר וְנוּקְבָּא בְּרָזָא חֲדָא, דִּכְתִּיב זֶה סֵפֶר, דָּא כְּלָלָא דְּכַר וְנוּקְבָּא כַּחֲדָא. כֵּיוָן דְּעָבְדוּ תוֹלְדוֹת כַּחֲדָא, קָרָא לוֹן אָדָם, דִּכְתִּיב תוֹלְדוֹת אָדָם.","לְבָתַר דְּאִתְגַּלְיָיא מִלְּתָא, מִגּוֹ סְתִימוּ עִלָּאָה קַדְמָאָה דִּקְרָא, בָּרָא אָדָם לְתַתָּא, דִּכְתִּיב בְּיוֹם בְּרוֹא אֱלהִים אָדָם בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. בִּדְמוּת (ס\"א דא איהו) דְּאָדָם אִיהוּ כְּהַאי חֵיזוּ דְּאִתְחָזֵי דִּיּוּקְנִין בֵּיהּ, וְאִינּוּן דִּיּוּקְנִין לָא קַיְימִין בְּהַהוּא חֵיזוּ בְּדִיּוּקְנָא בְּקִיּוּמָא, אֶלָּא מִתְעַבְּרָן מִינֵּיהּ, אוּף הָכִי בִּדְמוּת אֱלהִים.","דָּבָר אַחֵר, בִּדְמוּת אֱלהִים, דִּיּוּקְנָא דְּשַׁיְיפִין דְּכָר וְנוּקְבָּא, בְּרָזָא (תהלים קלט) דְּאָחוֹר וָקֶדֶם. אָחוֹר: בְּרָזָא דְּשָׁמוֹר. וָקֶדֶם: בְּרָזָא דְּזָכוֹר. וּבְאִלֵּין תַּלְיָין כָּל פִּקּוּדֵי אוֹרַיְיתָא, שִׁית מְאָה וּתְלֵיסָר פִּקּוּדֵי אוֹרַיְיתָא, כְּלָלָא דְּכֹלָּא. וְתָנֵינָן, אָחוֹר לְעוֹבָדָא דִּבְרִאשִׁית, וָקֶדֶם לְעוֹבָדָא דְּמֶרְכָּבָה. וְכֹלָּא דָּא בְּדָא תַּלְיָא. בִּדְמוּת אֱלהִים, בְּהַהוּא דִּיּוּקְנָא מַמָּשׁ, וְהָא אוֹקִים לֵיהּ מֹר.","תּוּ, זֶה סֵפֶר תוֹלְדוֹת אָדָם: לְדִּיּוּקְנִין, בְּרָזֵי דְּדִיּוּקְנִין דְּבַּר נָשׁ, לְאִשְׁתְּמוֹדְעָא בְּאִינּוּן תוֹלְדוֹת דְּבַּר נָשׁ, דִּיּוּקְנָא דְּרָזִין דְּבַּר נָשׁ, בְּשַׂעְרָא, בְּמִצְחָא, בְּעַיְינִין, בְּאַנְפִּין. בְּשִׁפְוָון, וּבְשִׂרְטוּטֵי יְדִין, וּבְאוּדְנִין. בְּאִלֵּין שֶׁבַע בְּנֵי נָשָׁא אִשְׁתְּמוֹדְעָן.","בְּשַׂעְרָא. הַאי מַאן דְּשַׂעֲרֵיהּ קָמִיט, וְסָלִיק לְעֵילָּא עַל רֵישֵׁיהּ, מָארֵיהּ דִּרְגִּיזוּ. לִבֵּיהּ קָמִיט כְּטוּפְסָא, לָאו כַּשְׁרָאן עוֹבָדוֹי. בְּשׁוּתָפוּ אִתְרְחַק מִנֵּיהּ.","שַׂעֲרָא שְׁעִיעַ יַתִּיר, וְתָלֵי לְתַתָּא, טָב אִיהוּ לְשׁוּתָפוּ. וּרְוָוחָא אִשְׁתְּכַח בֵּיהּ. וְאִיהוּ בִּלְחוֹדוֹי לָאו הָכִי. מָארֵי דְּרָזִין אִיהוּ בְּאִינּוּן רָזִין עִלָּאִין. בְּרָזִין זְעִירִין לָא קַיְּימָא בְּהוּ. עוֹבָדוֹי כַּשְׁרָאן וְלָא כַּשְׁרָאָן."],[[0,"לבתר ביום ברוא וגו':","אחר כך שכתוב, ביום ברוא אלקים אדם, זהו אדם שלמטה. כי שני אדם כתובים במקרא הזה, אחד, הוא סוד אדם שלמעלה, ואחד ה\"ס אדם שלמטה. אדם שהוא בסוד שלמעלה, שהוא ז\"א, הוא בגניזה שגנז הכתוב בזכר ונקבה בסוד אחד, שכתוב, \u0003זה ספר,\u0004 שהוא כלל זכר ונקבה ביחד, כנ\"ל. כיון שעשו תולדות ביחד קרא אותם אדם, שכתוב, תולדות אדם."],[1,"לבתר דאתגליא מלתא וכו':","לאחר שהדבר נגלה מתוך הסתום העליון הראשון שבכתוב, דהיינו שנגלה שזה ספר סובבים על אדם העליון, שתולדותיהם הם נשמות ורוחות בני אדם, כנ\"ל, ברא אדם שלמטה, שכתוב ביום ברוא אלקים אדם בדמות אלקים עשה אותו. \u0003בדמות,\u0004 פירושו, שאדם הוא כמראה הזה שהצורות נראות בו, והצורות אינן עומדות במראה ההוא בצורות של קיום, אלא נעברים ממנו. אף כאן כן הוא, בדמות אלקים."],[2,"ד\"א, בדמות אלהים:","פירוש אחר. בדמות אלקים פירושו, צורת האברים דכר ונוקבא בסוד של אחור וקדם. אחור, הוא בסוד שמור, שהיא הנוקבא. וקדם הוא בסוד זכור, שהוא ז\"א, ובאלו תלוים כל מצות התורה, שש מאות ושלש עשרה מצות התורה, שהם כלל הכל. ולמדנו, שאדם נברא אחור למעשה בראשית, וקדם למעשה מרכבה. והכל תלוי זה בזה. בדמות אלקים היינו בצורה זו ממש של המלכות. והרי ביאר אותו אדוני."],[3,"תו, זה ספר תולדות אדם:","הוא לצורות, בסוד הצורות של בני אדם, להכיר באלו תולדות אדם, את הצורה שבסודות האדם: בשער, במצח, בעינים, בפנים, בשפתים, וברשמי היד, ובאזנים. בשבע אלו ניכרים בני אדם."],[4,"בשערא. האי מאן וכו':","ניכר בשער. כי כל מי ששערותיו קמוטות, דהיינו שמסולסלות, ועולות על ראשו כלפי מעלה, כלומר, שאינן תלויות למטה מראשו: הוא בעל כעס. לבו קמוט כמו סחבה, דהיינו, שלבו מלא פחד. מעשיו אינם טובים. בשותפות, צריכים להתרחק ממנו. \u0003טופסא\u0004 פירושו סחבה. כי על בלוי הסחבות מתרגם בלאי טפסן (ירמיה ל\"ח י\"א)."],[5,"שערא שעיע יתיר וכו':","אם שערותיו חלקות ביותר ותלויות למטה: טוב להשתתף עמו, ריוח נמצא בו, כלומר, שישתכר וירויח עמו. והוא כשלעצמו, דהיינו בלי שותף, אינו כן. שאין לו הצלחה. הוא בעל סוד באלו סודות העליונים, בסודות קטנים, אינו עומד בהם. מעשיו, לפעמים טובים ולפעמים אינם טובים."]],[]],[["וְאִי תָּלֵי לְתַתָּא, וְלָא שְׁעִיעַ, לִבֵּיהּ לָא דָּחִיל, מָארֵיהּ דִּזְדוֹנָא אִיהוּ. כָּסִיף בְּעוֹבָדִין דְּכַשְׁרָן, וְיָאָן קָמֵיהּ, וְלָא עָבִיד. וְכַד אִיהוּ סִיב, אַהְדָּר לְמֶהֱוִי דָּחִיל וְיָאָן עוֹבָדוֹי. וְהָנֵי מִילֵּי, בְּמִילֵּי דְּעָלְמָא. אֲבָל בְּמִילֵּי דִּשְׁמַיָּא, יִצְלַח מַאן דְּיִקְרַב בֵּיהּ. לָא יִתְגַּלּוּן לֵיהּ רָזִין עִלָּאִין, אֲבָל רָזִין זְעִירִין טָב אִיהוּ לְנַטְרָא לוֹן, מִמִּלָּה זְעֵירָא עָבִיד רַב, וּמִלּוֹי אִשְׁתְּמָעוּ. וְרָזָא דָּא זַיִ\"ן, בְּאִינּוּן אַתְוָון דְּשִׁיעוּרָא דְּמֹר.","שַׂעֲרָא אוּכָמָא יַתִּיר צָהִיב, אַצְלַח בְּכָל עוֹבָדוֹי בְּמִלֵּי דְּעָלְמָא, וּבַסְּחוֹרָא, וּבְדְדָמֵי לוֹן. וַתְרָן אִיהוּ דָּא אַצְלַח לְחוֹדוֹי. מַאן דְּמִתְחַבֵּר בַּהֲדֵיהּ, לָא אַצְלַח לְיוֹמִין סַגִּיאִין, אֶלָּא אַצְלַח מִיַּד, וְהַהִיא אַצְלָחוּתָא פַּרְחָא מִנֵּיהּ. וְרָזָא דָּא דְּאִיהוּ בִּכְלָלָא דְּאָת ז'.","שַׂעֲרָא אוּכָמָא דְּלָא צָהִיב, לְזִמְנִין אַצְלַח, לְזִמְנִין לָא אַצְלַח. דָּא אִיהוּ לְשׁוּתָפוּ וּלְאִשְׁתַּדְּלָא בַּהֲדֵיהּ, טָב לִזְמַן קָרִיב, וְלָא לִזְמַן רָחִיק, דְּהָא לִזְמַן רָחִיק יַחֲשׁוֹב מַחֲשָׁבִין. וּבְגִין דְּלָא יִתְפָּרְשׁוּן מִנֵּיהּ, הֲוֵי טָב לִזְמַן קָרִיב. דָּא יִצְלַח בְּאוֹרַיְיתָא. אִי יִשְׁתָּדַּל אֲבַתְרָהָא. וְיִצְלְחוּן בֵּיהּ אַחֲרָנִין. לֵית לֵיהּ רָזָא, לִזְמַן רָחִיק. דָּחִיק לִבָּא אִיהוּ. יֶחֱמֵי בְּשַׂנְאוֹי. לָא יַכְלִין לֵיהּ שַׂנְאוֹי, וְאִיהוּ דָּחִיק לִבָּא, וְאִיהוּ בְּרָזָא דְּאָת י', דְּלָא קַיְּימָא בִּכְלָלָא דְּאָת ז', אֶלָּא י' בִּלְחוֹדוֹי, בְּרָזָא דְּאַתְוָון דְּקִיקִין.","שַׂעֲרָא דְּמָרִיט, יִצְלַח בְּעוֹבָדוֹי, וְרַמָּאָה אִיהוּ כַּפִין בְּבֵיתֵיהּ. אִתְחָזֵי דָּחִיל חַטָּאָה לְבַר, לָאו הָכִי לְגוֹ. דָּא עַד לָא סִיב. אִי שַׂעֲרֵיהּ מָרִיט, לְבָתַר דְּסִיב, אִתְהַפַּךְ מִכַּמָּה דְּהֲוָה בְּקַדְמִיתָא, הֵן לְטָב הֵן לְבִישׁ.","וְהָנֵי מִילֵּי שַׂעֲרָא דְּמָרִיט בֵּין עֵינוֹי, עַל גַּבֵּי מוֹחָא, בַּאֲתָר דְּאָנַח תְּפִלִין. וְאִי בַּאֲתָר אַחֲרָא דְּרִישָׁא, לָאו הָכִי. וְלָאו אִיהוּ רַמָּאָה, אֶלָּא מָארֵיהּ דְּלִישָׁנָא בִּישָׁא. בִּלְחִישׁוּ, בְּלָא אֲרָמוּת קָלָא. לְזִמְנִין דָּחִיל חַטָּאָה אִיהוּ, לְזִמְנִין לָא. וְדָא אִיהוּ בְּרָזָא דְּאָת ז', כַּד כָּלִיל אָת י'."],[[0,"ואי תלי לתתא וכו':","ואם שערותיו תלויות למטה, ואינן חלקות: אין פחד בלבו. בעל זדונות הוא. חושק למעשים טובים, והם יפים לפניו, ואינו עושה אותם. וכשיגיע לזקנה, חוזר להיות ירא ה', ומעשיו יפים. והדברים אמורים בדברי העולם, שאז הוא בעל זדונות, ואינו עושה מעשים טובים, אבל בדברי שמים, יצלח כל מי שיקרב אליו. לא יתגלה לו סודות עליונים, אבל סודות קטנים, טוב הוא לשמרם. מדבר קטן עושה דבר גדול, ודבריו נשמעים. וסוד זה הוא \u0003ז',\u0004 באלו אותיות השיעור של אדוני."],[0,"","ביאור הדברים. השערות האלו ה\"ס הכלים של החכמה במקום יציאתה, וע\"כ הן בחינת דינים. ובדרך כלל, יש להבחין בהן ג' מדרגות, הנמשכות מג' נקודות חולם שורק חירק. א) \u0003האי מאן דשעריה קמיט וסליק לעילא על רישיה\u0004 שאם שערותיו של בעל המדרגה מסולסלות ועולות למעלה, יורה שהוא במדרגת הקטנות של השערות, מבחינת נקודת החולם, שאז הם חסרים ג\"ר, וע\"כ הן עולות על ראשו כלפי מעלה, כלומר, שאינו משפיעות אלא ממטה למעלה, וז\"ש \u0003מאריה דרגיזו,\u0004 כי הדינים שבהן מביאים אותו תמיד לידי כעס. \u0003לביה קמיט כטופסא,\u0004 שלבו מלא פחד מן הדינים. \u0003לאו כשראן עובדוי,\u0004 כי החסרון ג\"ר מביא אותו למעשים רעים. \u0003בשותפו אתרחק מניה,\u0004 שכל המשתתף עמו ניזוק ממנו."],[0,"","ב) \u0003שערא שעיע יתיר ותלי לתתא,\u0004 שהיותן תלויות למטה, מורה, שיש בהם ג\"ר, המשפיעות מלמעלה למטה. והיותן חלקות ביותר, יורה, שלא נגלה בהן שום דין. ואז, \u0003טב איהו לשותפו.\u0004 דהיינו אחר שיתתקנו ג' קוין. יקבל ממנו הקו ימין והקו אמצעי, שהם שותפיו, את הארת הג\"ר שלהם. \u0003ורווחא אשתכח ביה.\u0004 דהיינו הארת הג\"ר. אבל \u0003ואיהו בלחודוי לאו הכי,\u0004 כי בהיתו לבדו הוא מחוסר חסדים, כבחינת נקודת \u0003השורק,\u0004 וע\"כ הוא סתום, שאין החכמה שבו יכולה להאיר בלי חסדים. וז\"ש \u0003מארי דרזין איהו באינון רזין עלאין,\u0004 דהיינו שיש בו אור החכמה שנק' רזין עלאין. אבל, \u0003ברזין זעירין לא קיימא בהו,\u0004 דהיינו שהוא מחוסר חסדים, הנקראים רזין זעירין. וע\"כ כל עוד שהוא לעצמו הוא חושך, כי החכמה אינה יכולה להאיר בו מחמת חסרון החסדים. וע\"כ \u0003עובדוי כשראן ולא כשראן,\u0004 שמבחינת השתתפותו אח\"כ בין הקוין, מעשיו טובים. ומטרם שמשתתף עם הקוין מעשיו לא טובים. כמבואר."],[0,"","ג) \u0003ואי תלי לתתא ולה שעיע,\u0004 דהיינו שיש בו ג\"ר, וממשיך ממעלה למטה, ואינן חלקות, כי נתגלה בהן דינין. ועם כל זה הן תלויות, שממשיכות ממעלה למטה ניכר מזה, \u0003לביה לא דחיל,\u0004 שאין בו יראה מפני הדינין. \u0003מאריה דזדונא איהו,\u0004 כי עם המשכתו מלמעלה למטה הוא מרבה דינים, בסו\"ה ולפתח חטאת רובץ. \u0003כסיף בעובדין דכשרן ויאן קמיה ולא עביד,\u0004 הוא חושק למעשים טובים, אבל לא יוכל לעשות אותן מחמת התגלות הדינים. \u0003וכד איהו סיב,\u0004 דהיינו אחר שיתוקן בתקון קוין, \u0003אהדר למהוי דחיל, ויאן עובדוי,\u0004 כי אז מן הדינים האלו המתגלים בעת המשכתו מלמעלה למטה, נעשה מהם בחינת מסך דנקודת \u0003החירק.\u0004 שעל ידו מכריע הקו האמצעי את ב' הקוין ימין ושמאל ומקיים הארת שניהם (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) \u0003והני מילי במלי דעלמא,\u0004 היינו בדברי הנוקבא הנקרא עולם, שאז נבחן למאריה דזדונא, להיותו מרבה דינים בה, \u0003אבל במלי דשמיא,\u0004 היינו בדברי ז\"א, הנקרא שמים, \u0003יצלח מאן דיקרב ביה,\u0004 דהיינו קו האמצעי שיקרב אליו, ויקבל ממנו הדינים לבחינת תקון מסך דחירק כנ\"ל. ואז, \u0003לא יתגלון ליה רזין עלאין,\u0004 שהוא חכמה, דהיינו מחמת הדינים שבו, \u0003אבל רזין זעירין,\u0004 שהוא חסדים, \u0003טב איהו לנטרא לון,\u0004 כי המסך דחירק עם הכרעתו את הקוין נמצא שומר שלא יחסר עוד אור החסדים הנקראים רזין זעירין. ועם כל זה יש בו חכמה גם כן, כי, \u0003ממלה זעירא עביד רב ומלוי אשתמעו,\u0004 שמן הארת החסדים הנקראים \u0003מלה זעירא,\u0004 עושה הארת החכמה הנקראת \u0003רב.\u0004 והוא, כי מתוך שחסדים דקו אמצעי פתחו את ב' הקוין ימין ושמאל, זוכה קו האמצעי שהוא חסדים בהארת ב' קוין העליונים, שהם חכמה, בסוד \u0003תלת נפקי מחד חד בתלת קיימא,\u0004 כי כל השעור שהתחתון גורם שיאיר בעליון זוכה בו התחתון. (כנ\"ל בראשית א' אות שס\"ג) ונמצא \u0003שמלה זעירא\u0004 שהוא אור החסדים נעשה אור \u0003רב\u0004 שהוא ג\"ר. \u0003ורזא דא ז'\u0004 וכו', ומדרגה זו היא בחינת אות \u0003ז'.\u0004 שה\"ס מלכות במוחין דחכמה, שאז היא עטרת בעלה."],[1,"שערא אוכמא יתיר וכו':","שער שחור וצהוב יותר: הוא מצליח בכל מעשיו, בדברי העולם, שהוא המלכות הנקראת עולם, ובסחורה, שהיא שפע המלכות בסו\"ה, היתה כאניות סוחר וגו'. וכדומה להם. הוא ותרן. זה מצליח לבדו, בלי שותף. ומי שמתחבר עמו בשותפות, אינו מצליח לימים רבים, אלא מצליח מיד, וההצלחה פורחת ממנו. וסוד זה, שהוא בכלל של אות \u0003ז'.\u0004"],[1,"","ביאור הדברים. הנה עד כאן ביאר אותן השערות שהן כלים דחכמה במקום יציאתה, כנ\"ל. אמנם אחר כך, מתתקנים בג' קוין, ואז עיקר ההיכר בהם הוא בגוונים. וכאן מדבר ממדרגת קו אמצעי, שבכח המסך דחירק הוא מיחד ב' הקוין ימין ושמאל. ונודע שב' פעולות במסך הזה, שמתחילה נגלה בו המסך דצמצום א' שהוא מלכות דמדת הדין. ואז גוון השערות שחור בלי שום צהיבות. ובמצב הזה הוא ראוי לקבל רק חסדים ולא חכמה. ומבחינה זו הוא מדבר להלאה, בדבור הסמוך. ופעולה האחרת היא להמתיק המסך במדת הרחמים שהיא בינה, ובזה נעשה ראוי לקבל גם אור החכמה. (כמ\"ש לעיל לך י\"ג ד\"ה ונתבאר ע\"ש כל ההמשך) ובמצב הזה שערותיו שחורות וצהיבות, שהצהיבות יורה על המיתוק דמדת הרחמים."],[1,"","וז\"ש כאן. \u0003שערא אוכמא יתיר צהיב,\u0004 שיורה על פעלה ב' דקו האמצעי, שהמסך דחירק כבר נמתק במדת הרחמים וראוי לקבל חכמה. כנ\"ל, \u0003אצלח בכל עובדוי,\u0004 בין שממשיך חסדים, ובין שממשיך הארת חכמה, הוא מצליח. \u0003במלי דעלמא,\u0004 בצרכי הנוקבא, הנקראת עולם. \u0003ובסחורא ובדדמי לון,\u0004 שהיא השפע שלה בסו\"ה, היתה כאניות \u0003סוחר\u0004 ממרחק תביא לחמה, שה\"ס הארת החכמה המאירה מרחוק. \u0003ותרן איהו,\u0004 אע\"פ שקו האמצעי חשקו בחסדים ולא בחכמה, מכל מקום מותר על שלו, וממשיך חכמה לצורך הנוקבא. \u0003דא אצלח לחודוי,\u0004 שבהיותו לבדו הוא ממשיך אור החסדים ומצליח. \u0003מאן דמתחבר בהדיה,\u0004 דהיינו הנוקבא שמתחברת עם קו האמצעי לקבל ממנו חכמה, כנ\"ל, \u0003לא אצלח ליומין סגיאין, אלא אצלח מיד וההיא אצלחותא פרחא מניה.\u0004 כי החכמה אינה מאירה בז\"א, רק בעת נסיעת הקוין, וכשנחים פורח החכמה מהם (כנ\"ל פ' בשלח דף מ' ד\"ה פירוש). וסוד הזה הוא שמדרגה זו היא בכלל של אות \u0003ז'.\u0004 הנ\"ל."],[2,"שערא אוכמא דלא וכו':","שער שחור שאינו צהוב, לפעמים הוא מצליח ולפעמים אינו מצליח. זה הוא טוב לשותפות ולהשתדלות עמו, לזמן קרוב, ולא לזמן רחוק, כי לזמן רחוק יחשוב מחשבות. ובכדי שלא יפרדו ממנו הוא טוב לזמן קרוב. זה יצלח בתורה אם ישתדל אחריה. ויצלחו בו אחרים. אין לו סוד לזמן רחוק. צר לב הוא. יראה בשונאין. לא יכלו לו שונאיו. והוא צר לב, כמו סוד אות \u0003י',\u0004 שהיא קטנה וצרה, ואינו עומד בכלל אות \u0003ז'\u0004 הנ\"ל, אלא י' בלבדה בסוד אותיות הקטנות."],[2,"","ביאור הדברים. כאן הזהר מדבר ממדרגת קו האמצעי בפעולה הא' שלו (כנ\"ל בדבור הסמוך) שאז הוא במסך דמדת הדין שאינו נמתק בבינה, ואינו ראוי לקבל חכמה, אלא חסדים בלבד כנ\"ל ע\"ש."],[2,"","וזה אמרו, \u0003שערא אוכמא דלא צהיב.\u0004 דהיינו שאינו נמתק במדת הרחמים, אז, \u0003לזמנין אצלח ולזמנין לא אצלח\u0004 דהיינו כשממשיך חסדים הוא מצליח, וכשממשיך חכמה אינו מצליח. \u0003דא איהו לשותפו ולאשתדלא בהדיה טב לזמן קריב,\u0004 דהיינו, שטוב רק להמשכת החסדים, המכונה זמן קרוב משום שאין בהם דינים. \u0003ולא לזמן רחיק,\u0004 ולא לחכמה המכונה זמן רחוק, בסו\"ה מרחוק ה' נראה לי, (כמ\"ש לעיל וירא דף ט\"ז ד\"ה וזה) \u0003דהא לזמן רחיק יחשוב מחשבין,\u0004 כי לזמן רחוק צריכים להמשיך מחכמה הנקראת מחשבה, והוא אינו ראוי לזה מחמת שלא נמתק המסך בבינה. (כמ\"ש לעיל בראשית א' דף ז' ד\"ה וכבר). \u0003ובגין דלא יתפרשון מניה,\u0004 דהיינו מחשש שיפרשו ממנו ולא ירצו לקבלו, \u0003הוי טב לזמן קריב,\u0004 עשהו המאציל טוב להמשכת החסדים. \u0003דא יצלח באורייתא אי ישתדל אבתרהא,\u0004 והיינו בבחינת הו\"ק שבתורה. \u0003ויצלחון ביה אחרנין,\u0004 היינו אותם שיקחו את המסך הזה וימתקו אותו בבינה, המה יצליחו גם לג\"ר, (כנ\"ל בדבור הסמוך.) אבל לו עצמו, \u0003לית ליה רזא לזמן רחיק,\u0004 שאין לו סוד מהארת החכמה. \u0003דחיק לבא\u0004 החסר מחכמה נבחן לצר לב, כי החכמה משכנה בלב, בסו\"ה ובלב כל חכם לב נתתי חכמה. וע\"כ בחסרונה משם מצטמצם הלב. \u0003יחמי בשנאוי,\u0004 כי הקו האמצעי מכניע בכח המסך הזה את כל הדינים שבקו שמאל, שהם נבחנים לשונאי הקדושה. (כנ\"ל פרשת לך דף י\"ג ד\"ה ונתבאר) \u0003לא יכלון ליה שנאוי,\u0004 כי כחו חזק יותר מכולם, ומוכרחים להכנע מפניו. כמ\"ש שם. ואע\"פ, \u0003ואיהו דחיק לבא,\u0004 שחסר חכמה, כנ\"ל מ\"מ מכניע את כל שונאיו. \u0003ואיהו ברזא דאת י',\u0004 שה\"ס המלכות בשעה שאינה ראויה לחכמה. \u0003דלא קיימא בכללא דאת ז',\u0004 כי אות \u0003ז'\u0004 יורה על המלכות בשעה שמקבלת חכמה, כנ\"ל. \u0003אלא י' בלחודוי ברזא דאתוון דקיקין,\u0004 כי אותיות קטנות מורות על חסרון חכמה."],[2,"","והגם שאיני מבאר את דברי האגדה שבזהר מטעם שהערתי לעיל (פרשת נח דף א' בשולי הדף, ע\"ש). עם כל זה, לרוב חשיבות המאמר, ואתה תחזה, הוכרחתי לבאר קצתו, כדי להראות דרך למשכילים, כיצד צריכים ללמוד אותו. מכאן ולהלאה אסתפק בתרגומו ללשון הקודש, כמו בכל האגדות."],[3,"שערא דמריט יצלח וכו':","אם השערות נקרחו: יצלח במעשיו. והוא רמאי. רעב בביתו. נראה מבחוץ שהוא ירא חטא, ואינו כן בפנימיות. וכל זה הוא מטרם שבא לזקנה. ואם נקרחו שערותיו לעת זקנה, הוא מתהפך ממה שהיה בתחילה, הן לטוב והן לרע."],[4,"והני מילי שערא וכו':","והדברים אמורים, בשער שנקרח בין עיניו על המוח, במקום שמניח תפלין, ואם במקום אחר שבראש אינו כן, שאין הוא רמאי, אלא בעל לשון הרע, בלחש בלי הרמת קול. לפעמים הוא ירא חטא, ולפעמים לא. וזה הוא בסוד אות \u0003ז'\u0004 כשהיא כלולה באות \u0003י'.\u0004"]],[]],[["עַד הָכָא, רָזִין דְּשַׂעֲרָא לְמָרֵי מִדִּין, דְּיַדְעֵי אָרְחֵי וְרָזֵי דְּאוֹרַיְיתָא, לְאִשְׁתְּמוֹדְעָא טְמִירוּ דִּבְנֵי נָשָׁא, דְּאִינּוּן בְּצֶלֶם אֱלהִים סָתוּם שְׁמָא, דְּאִתְפְּרַשׁ לְכַמָּה אָרְחִין.","בְּרָזָא דְּמִצְחָא, בְּאָת נ', דְּאִיהוּ שְׁלִימוּ דְּאָת זַיִ\"ן, לְזִמְנִין אִתְכְּלִילַת בְּרָזָא דְּאָת ז', וּלְזִמְנִין אִיהוּ בִּלְחוֹדָהָא. מִצְחָא דְּאִיהוּ דָּקִיק וְחַד, בְּלָא עִגּוּלָא דָּא הוּא בַּר נָשׁ דְּלָא מִתְיַישְׁבָא בְּדַעְתֵּיהּ, חָשִׁיב דְּאִיהוּ חַכִּים, וְלא יָדַע. אִתְבְּהִיל בְּרוּחֵיהּ. חֲיִּיךְ (ס\"א נשיך) בְּלִישָׁנֵיהּ כְּחִוְיָא.","קְמִיטִין דְּמִצְחֵיהּ רַבְרְבָן, וְלָאו אִינּוּן בְּזִוּוּגָא. בְּשַׁעֲתָא דְּמַלִּיל אִתְעָבִידוּ אִינּוּן קְמִיטִין בְּמִצְחֵיהּ, וְלָאו בְּזִוּוּגָא. רְשִׁימִין אַחֲרָנִין דִּי בְּמִצְחֵיהּ כֻּלְּהוּ בְּזִוּוּגָא. דָּא, בָּעֵי דְּלָא לְאִזְדַּוְּוגָא לֵיהּ, אֶלָּא זִמְנָא זְעֵירָא, וְלָא זִמְנָא סַגִּי. כָּל מַה דְּעָבַד וְחָשַׁב, אִיהוּ לְתוֹעַלְתֵּיה, וְלָא חָיִישׁ לְתוֹעַלְתָּא דְּאַחֲרָנִין. לָאו אִיהוּ מָארֵי דְּרָזִין כְּלָל. דָּא אִיהוּ, (משלי י״א:י״ג) הוֹלֵךְ רָכִיל מְגַלֶּה סּוֹד, וְלָא חָשִׁיב מִלּוֹי כְּלָל. דָּא אִיהוּ בְּרָזָא דְּאָת נ' דִּכְלִילָא בְּאָת ז', וְלָא אִקְרֵי נֶאֱמָן רוּחַ בְּקִיּוּמָא.","מִצְחָא דָּקִיק בְּעִגּוּלָא, דָּא אִיהוּ בַּר נָשׁ חַכִּימָא, בְּמָה דְּאִסְתָּכַּל. לְזִמְנִין אִתְבְּהִיל בְּרוּחֵיהּ. רְחִימוּ דִּילֵיהּ בְּחֶדְוָה. רַחֲמָן אִיהוּ עַל כֹּלָּא, אִסְתָּכַּל בְּמִלִּין סַגִּיאִין. אִי יִשְׁתָּדַּל בְּאוֹרַיְיתָא לֶהֱוֵי חַכִּים יַתִּיר.","תְּלַת קְמִיטִין עִלָּאִין רַבְרְבִין בְּמִצְחֵיהּ בְּשַׁעֲתָא דְּאִיהוּ מַלִּיל. תְּלַת קְמִיטִין קָרִיב לְעֵינָא חַד. וּתְלַת קְמִיטִין עַל עֵינָא אַחֲרָא. בָּכֵי בְּשַׁעֲתָא דְּאַרְגִּיז. דָּא אִיהוּ טָב יַתִּיר מִכַּמָּה דְּאִתְחָזֵי. אַרְמִי בָּתַר כִּתְפוֹי כָּל מִלִּין דְּעָלְמָא, בֵּין בְּעוֹבָדוֹי, בֵּין בְּמִלִּין אַחֲרָנִין, וְלָא חָיִישׁ. אַצְלַח בְּאוֹרַיְיתָא. כָּל בַּר נָשׁ דְּיִשְׁתְּדַל בַּהֲדֵיהּ יַתִּיר מִמִּלִּין אַחֲרָנִין דְּעָלְמָא, לְזִמְנִין אִתְדְּבָק רְעִוּתֵיהּ בְּקֻדְשָׁא בְּרִיךְ הוּא, וּלְזִמְנִין לָא. בְּדִינָא לָא אַצְלַח. אִתְרְחַק אִיהוּ מִן דִּינָא. וְרָזָא דָּא אָת נ' בִּלְחוֹדוֹי, דְּלָא אִתְכְּלִילַת בְּאָת ז'. וּבְגִין דְּלָא אִתְכְּלִילַת בְּאָת ז', אִתְרְחַק מִן דִּינָא, וְלָא קָאִים בֵּיהּ, וּרְחִימוּתָא אִיהוּ סִטְרָא דִּילֵיהּ."],[[0,"עד הכא וכו':","עד כאן, סודות השערות ליושבי על כסא מדין, היודעים הדרכים והסודות שבתורה, להכיר המכוסה שבבני אדם, שהם בצלם אלקים, שהשם הזה, \u0003אלקים,\u0004 הוא סתום אצלם, (עי' לעיל בראשית א' דף י\"ד ד\"ה אבל) המתבאר לכמה דרכים."],[1,"ברזא דמצחא. באת נ' וכו':","בסוד המצח. באות \u0003נ'\u0004 שהיא גבורה, שהיא השלמות של אות \u0003ז'.\u0004 שהיא מלכות, כי המלכות נבנית מקו שמאל שהוא גבורה. לפעמים נכללת ה \u0003נ'\u0004 באות \u0003ז'.\u0004 ולפעמים היא בלבדה. המצח שהוא קטן וחד ואינו עגול. זה הוא אדם שאינו מתישב בדעתו, חושב שהוא חכם, ואינו יודע. נבהל ברוחו, נושך בלשונו כנחש."],[2,"קמיטין דמצחיה רברבן וכו':","אם הקמטים שבמצחו הם גדולים ואינם בחיבור זה עם זה. בשעה שמדבר נעשים אלו הקמטים במצחו בלא חיבור. רשימות אחרות שבמצחו כולם בחיבור זה עם זה. זה, צריכים שלא להתחבר עמו רק לזמן קצר, ולא זמן מרובה. כל מה שעושה וחושב הוא לתועלתו עצמו, ואינו דואג לתועלת אחרים. הוא אינו בעל סוד כלל. זה הוא הולך רכיל מגלה סוד. ודבריו אינם חשובים כלל. זה הוא בסוד אות \u0003נ'\u0004 הכלולה באות \u0003ז'.\u0004 ואינו נקרא נאמן רוח להתקיים."],[3,"מצחא דקיק בעגולה וכו':","אם המצח קטן ועגול. זה הוא אדם חכם במה שמסתכל. לפעמים נבהל ברוחו. האהבה שלו היא בשמחה. רחמן הוא על הכל. מתבונן בדברים רבים. אם ישתדל בתורה יהיה חכם ביותר."],[4,"תלת קמיטין עלאין וכו':","אם שלשה קמטים עליונים גדולים במצחו בשעה שמדבר, ג' קמטים קרובים לעין אחת וג' קמטים על עין האחרת. בוכה בשעת כעסו. זה הוא יותר טוב ממה שנראה. משליך אחר כתפיו כל דברי העולם, בין במעשיו ובין בדברים אחרים, ואינו דואג להם. הוא מצליח בתורה. כל אדם שיעסוק עמו, ירויח מדברי העולם האחרים, שהוא אינו מחשיבם כנ\"ל. לפעמים מתדבק רצונו בחקב\"ה ולפעמים לא. בדין לא מצליח. הוא מתרחק מן דין. וזה סוד אות \u0003נ'\u0004 בלבדה, שאינה נכללת באות \u0003ז'.\u0004 ומשום שאינה נכללת באות \u0003ז'\u0004 הוא מתרחק מן דין, ואינו עומד בו. והאהבה הוא הצד שלו."]],[]],[["מִצְחָא דְּאִיהוּ בְּלָא עִגּוּלָא, וְאִיהוּ רַבְרְבָא. הַאי אִיהוּ בַּר נָשׁ דְּכָל זִמְנִין כַּד קָאִים, וְכַד אָזִיל, כָּפִיף רֵישֵׁיהּ. הַאי אִתְפְּלִיג לִתְרֵין לְסִטְרִין, וְאִינּוּן סִטְרֵי שִׁגְעוֹנָא. סִטְרָא חֲדָא אִיהוּ שִׁגְעוֹנָא דְּאִתְחָזֵי, וּבְנֵי נָשָׁא אַחֲרָנִין יַדְעִין שִׁגְעוֹנָא, דְּאִשְׁתְּמוֹדְעָא קַמֵי כֹּלָּא. וְאִיהוּ טִפְּשָׁא.","בְּמִצְחֵיהּ אִית ד' קְמִיטִין רַבְרְבִין, לְזִמְנִין בְּשַׁעֲתָא דְּמַלִּיל קָמִיט לוֹן בְּמִצְחֵיהּ, וּלְזִמְנִין דְּאִתְפְּשַׁט מִצְחֵיהּ בְּמַשְׁכֵיהּ, וְלָא אִתְחָזוּן. אִינּוּן קְמִיטִין אִתְחָזוּן, קְמִיטִין אַחֲרָנִין רַבְרְבִין בְּסִטְרָא דְּעֵינוֹי, חַיִיךְ לְמַגָּנָא. פּוּמֵיהּ רַבְרְבָא. לָאו אִיהוּ בַר נָשׁ לְתוֹעַלְתָּא. סִטְרָא אַחֲרָא אִיהוּ. שִׁגְעוֹנָא דְּאִתְכַּסֵּי בֵּיהּ, וּבְנֵי נָשָׁא לָא מִסְתַּכְּלָן בֵּיהּ. וְאִיהוּ אִתְחַכָּם בְּמָה דְּאִשְׁתַּדַּל, וַאֲפִילּוּ בְּאוֹרַיְיתָא, אֲבָל לָא לִשְׁמָהּ, אֶלָּא בְּגִין לְאִתְגָּאָה בִּפְנֵי עַמָּא. וְכֹלָּא בִּלְחִישׁוּ וּבְגַאֲוַת לִבָּא, לְאַחֲזָאָה דְּאִיהוּ זַכָּאָה וְלָאו הָכִי. כָּל מִלּוֹי לָאו אִינּוּן לִשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּגִין בְּנֵי נָשָׁא. וְחָשִׁיב מַחֲשָׁבִין, וְאַנְהִיג גַּרְמֵיהּ. כְּמִנְהָגָא דִּלְבַר, דְּיִסְתַּכְּלוּן בֵּיהּ. הַאי אִיהוּ בְּרָזָא דְּאָת נ', דִּי בִּכְלָלָא דְּאָת ז'.","מִצְחָא דְּאִיהוּ בְּעִגּוּלָא רַבְרְבָא, פְּקִיחָא אִיהוּ, דָבְּרָנוּ (ס\"א דכרנו) דְּכֹלָּא בֵּיהּ. יָדַע בְּכָל מַה דְּאִשְׁתַּדַּל, אֲפִילּוּ בְּלָא אוּמָנָא דְּיוֹלִיף לֵיהּ. אַצְלַח בְּכָל מַה דְּאִשְׁתַּדַּל. וּבְמָמוֹנָא, לְזִמְנִין אַצְלַח, לְזִמְנִין לָא. מִמִּלָּה זְעֵירָא אִסְתָּכַל בְּמִלִּין סַגִּיאִין. נָבוֹן אִקְרֵי. לָא חָיִישׁ לְמִלִּין דְּעָלְמָא, וַאֲפִילּוּ דְּיִנְדַּע דְּיִתְכְּסִיף בְּהוּ לָא חָיִישׁ לוֹן, וְלָא שָׁוִי עַל לִבֵּיהּ. רָכִיךְ לִבָּא אִיהוּ."],[[0,"מצחא דאיהי בלא וכו':","אם המצח הוא בלא עיגול, והוא גדול. זה הוא אדם, שכל פעם, כשהוא עומד וכשהוא הולך, כופף ראשו. זה נחלק לב' בחינות, והן בחינות שגעון. בחינה אחת מהן, הוא שגעון הנראה, ואנשים אחרים יודעים את שגעונו, שניכר לכל. והוא כסיל."],[1,"במצחיה אית ד' וכו':","אם יש במצחו ד' קמטים גדולים. לפעמים בשעה שמדבר מקמט אותם במצחו, ולפעמים מתפשט מצחו בעורו ואינם נראים, ואלו הקמטים הנראים אז, הם קמטים אחרים גדולים בצד עיניו. צוחק בחנם, בלי סבה. פיו גדול. אין הוא אדם לתועלת, מצד האחר הוא. שגעון מסתתר בו, ובני אדם אינם מסתכלים בו. והוא מתחכם במה שעוסק, ואפילו בתורה, אבל שלא לשמה, אלא כדי להתגאות בפני העם. וכל מנהגו בחשאי ובגאות הלב, מראה שהוא צדיק ואינו כן. כל דבריו אינם לשם הקב\"ה אלא בשביל אנשים, וחושב מחשבות ומנהיג עצמו מנהג חיצוני, כדי שיסתכלו בו. זה הוא בסוד אות \u0003נ'\u0004 שהיא בכלל אות \u0003ז'.\u0004"],[2,"מצחא דאיהי בעגולא וכו':","אם המצח הוא בעיגול וגדול, הוא פקח. זכרון הכל בו. יודע בכל מה שמשתדל, ואפילו בלא אומן שילמוד אותו. מצליח בכל מה שמשתדל. ובכסף, לפעמים מצליח ולפעמים לא. מדבר קטן הוא מסתכל בדברים גדולים. נקרא נבון. אינו דואג לדברי העולם, ואפילו שידע שיתביש בהם אינו דואג ואינו שם על לבו. רך הלב הוא."]],[]],[["תְּרֵין קְמִיטִין עִלָּאִין רַבְרְבִין בְּמִצְחֵיהּ. חַד קְמִיטָא עַל עֵינָא חַד, וְחַד קְמִיטָא עַל עֵינָא אַחֲרָא. וְאִשְׁתְּכָחוּ תְּלַת קְמִיטִין רַבְרְבִין בְּמִצְחֵיהּ, בְּאִלֵּין דְּעַיְינִין, בַּר קְמִיטָא תַּתָּאָה, דְּאִיהוּ אִתְפְּלַג עַל עַיְינִין. דָּא חָשִׁיב מַחֲשָׁבִין לְגוֹ וְלָא לְבַר. בְּגִין דְּלָא חָשִׁיב לִבְנֵי נָשָׁא בְּעוֹבָדוֹי, וְדָחִיל אִיהוּ לְפוּם שַׁעֲתָא, וְלָא יַתִּיר. לְפַיּוּסָא, אִתְפַּיְּיסָא בְּעוֹבָדוֹי דִּלְבַר מִקָּמֵי בַּר נָשׁ, לָאו אִינּוּן, אֶלָּא לְזִמְנִין כְּרַבְיָא, וּלְזִמְנִין בְּחָכְמָה. דָּא אִיהוּ בְּרָזָא דְּאָת נ', דְּאִיהוּ בִּלְחוֹדוֹי, דְּלָא אִתְכְּלִיל בְּאָת ז'. וְחַלְשָׁא אִיהוּ, דְּלָא אִתְכְּלִיל בְּאִלֵּין אַתְוָון קַדְמָאֵי, אֶלָּא אִסְתְּמִיךְ לְאָת ס' לְאִתְכְּלָלָא בֵּיהּ. וְלָא בְּאַתְוָון קַדְמָאֵי. עַד הָכָא רָזִין דְּחָכְמְתָא דְּמִצְחָא.","בְּרָזָא דְּעַיְינִין, בְּרָזָא דְּאָת ס', בְּהַהוּא גַּוְונָא דְּסַחֲרָא לְבַר, וּכְמָה דְּיָתְבָא עֵינָא, דְּיָתְבָא עַל שְׁלִימוּ, דְּלָא שְׁקִיעַ, הַאי לָאו רַמָּאָה הִיא, וְרָחִיק מֵרַמָּאוּתָא, דְּלָא אִית בֵּיהּ כְּלָל.","גַּוְונֵי דְּעַיְינִין אִינּוּן ד'. חִוָּורוּ לְבַר, דְּסַחֲרָא עֵינָא, כְּגַוְונָא דְּכָל בַּר נָשׁ. לְגוֹ מִנֵּיהּ אוּכָמָא דְּסַחֲרָא, וְאִתְכְּלִיל חִוָּורוּ וְאוּכָמוּ כַּחֲדָא. לְגוֹ מִנֵּיהּ יְרוֹקָא. וְאִתְכְּלִיל בְּאוּכָמָא. לְגוֹ מִנֵּיהּ הַהוּא בַּת עֵינָא, נְקוּדָא אוּכָמָא. דָּא אִיהוּ בַּר נָשׁ דְּחַיִיךְ תָּדִיר, וְחַדֵּי בְּחֵדוּ. וְחָשִׁיב מַחֲשָׁבִין לְטָב, וְלָא אִשְׁתְּלִימוּ אִינּוּן מַחֲשָׁבִין, בְּגִין דְּסָלִיק לוֹן מִיַּד מֵרְעוּתֵיהּ. אִשְׁתַּדַּל בְּמִילֵּי דְּעָלְמָא. וְכַד אִשְׁתַּדַּל בְּמִילֵּי דִּשְׁמַיָּא, אַצְלַח. הַאי אִצְטְרִיךְ לְאִתַּתְקְפָא בֵּיהּ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּהָא יִצְלַח בָּהּ.","גְּבִינִי עֵינוֹי רַבְרְבִין, וְכַסְיָין לְתַתָּא. בְּאִינּוּן גַּוְונִין דְּעֵינָא אִית רְשִׁימִין סוּמָקִין דְּקִיקִין בְּאַרְכָּא. אִינּוּן רְשִׁימִין אִקְרוּן אַתְוָון זְעִירִין דְּעֵינָא. בְּגִין דְּאִינּוּן גַּוְונִין דְּעֵינָא. אִי נְהִרִין בִּנְהִירוּ, הַהוּא נְהִירוּ סָלִיק אַתְוָון לְאִתְחֲזָאָה, לְאִינוּן מָארִי דְּמִדִּין. בְּאִינּוּן רְשִׁימִין אַחֲרָנִין דְּקִיקִין, וְהַאי אִיהוּ בְּאָת ס', וּכְלִילָא בְּאָת ה'."],[[0,"תרין קמיטין עלאין וכו':","אם ב' קמטים עליונים גדולים במצחו, קמט אחד על עין אחת, וקמט אחד על עין האחרת. ונמצאים ג' קמטים גדולים במצחו, באלו שעל העינים, וחוץ מהם קמט תחתון הנחלק על העינים. זה חושב מחשבות בפנימיותו, ואינן נודעות לחוץ, משום שאינו מחשיב בני אדם במעשיו. הוא ירא לשעתו ולא יותר. לריצוי, הוא מתרצה במעשיו החצונים לפני בני אדם, והם, המעשים, אינם, אלא לפעמים כמעשה ילד, ולפעמים בחכמה. זה הוא בסוד אות \u0003נ'\u0004 שהוא בלבדה, ולא נכלל באות \u0003ז'.\u0004 והוא חלש, מחמת שלא נכלל באותיות הראשונות, אלא נסמך לאות \u0003ס'\u0004 להכלל בה, ולא באותיות הראשונות. עד כאן סודות החכמה של המצח."],[1,"ברזא דעיינין וכו':","בסוד העינים. שהן בסוד אות \u0003ס'.\u0004 שיש להסתכל בצבע ההוא הסובב על העינים בחוץ, וכמו שהעין יושבת אם יושבת על מילואה, שאינה שקועה בעומק המצח. זה אינו רמאי, והוא רחוק מרמאות, שאין בו כלל."],[2,"גווני דעיינין אינון וכו':","הצבעים שבעינים הם ארבעה. א) הלבן שבחוץ הסובב את העין, כעין שיש בכל אדם. כלומר, שאין בזה חילוק בין אדם לאדם. ב) לפנים ממנו צבע השחור הסובב. ונכללו הלבן והשחור יחד, הרומזים על חסד וגבורה הנכללים זה בזה. ג) לפנים ממנו ירוק, הרומז על ת\"ת, ונכלל בשחור. ד) לפנים ממנו בת עין, שהיא נקודה שחורה. הרומזת על המלכות. זה הוא אדם שצוחק תמיד ושמח בשמחה. וחושב מחשבות לטוב, והמחשבות אינן נשלמות, משום שמעלה אותן מיד מרצונו. עוסק בדברי העולם. וכשהוא עוסק בדברי שמים הוא מצליח. זה, צריכים לעודד אותו שיעסוק בתורה, כי יצליח בה."],[3,"גביני עינוי רברבין וכו':","אם, גבות עיניו גדולות ומכסות למטה. ואם בצבעים שבעינים יש רשימות אדומות באורך. אלו הרשימות נקראות, אותיות קטנות שבעין, משום שהם צבעים שבעין, ואם מאירים באור, אור ההוא מעלה אותיות, להראות לאלו בעלי מדון, עם אלו רשימות האחרות הקטנות. וזה הוא באות \u0003ס'\u0004 וכלול באות \u0003ה'\u0004."]],[]],[["עַיְינִין יְרוֹקִין דְּסַחֲרִין (נ\"א דמסחרא) בְּחִוָּורוּ, וּמִתְעָרְבִין אִינּוּן יְרוֹקִין, בְּהַהוּא חִוָּורוּ. רַחֲמָנָא אִיהוּ, וְאִיהוּ חָשִׁיב תָּדִיר לְתוֹעַלְתֵּיה, וְלָא חָשִׁיב לְנִזְקָא דְּאַחֲרָנִין כְּלוּם.","גַּוְונָא אוּכָמָא לָא אִתְחָזֵי בֵּיהּ. חָמִיד אִיהוּ וְלָא מִסִּטְרָא בִּישָׁא. וְאִי סַלְּקָא בִּידֵיהּ מִסִּטְרָא בִּישָׁא, לָא יֵתוּב מִנֵּיהּ. מְהֵימָנָא אִיהוּ בְּמָה דְּאִשְׁתְּמוֹדְעא. וּבַמֶּה דְּלָא אִשְׁתְּמוֹדְעָא לָאו מְהֵימָנָא אִיהוּ. מָארֵיהּ דְּרָזִין אִיהוּ, בְּמִלָּה דְּאִיהוּ רָזָא, עַד דְּיִשְׁמַע לְהַהוּא רָזָא בְּאֲתָר אַחֲרָא. כֵּיוָן דִּשְׁמַע לֵיהּ גַּלֵּי כֹּלָּא. וְלָאו עִמֵּיהּ רָזָא כְּלָל, דְּכָל מִלּוֹי לָאו אִינּוּן בִּשְׁלִימוּ. גַּוְונֵי עֵינוֹי סָחֲרָן בְּחִוָּורוּ וּבִירוֹקָא. דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְכְּלִיל בְּאָת ז', וּבְאָת ס'.","עַיְינִין צְהִיבִין יְרוֹקִין, שִׁגְעוֹנָא אִית בֵּיהּ. וּבְגִין שִׁגְעוֹנֵיהּ אִיהוּ פּוּם מְמַלֵּל רַבְרְבָן, וְעָבִיד גַּרְמֵיהּ כְּבַר נָשׁ רַב, בְּרַבְרְבָנוּ. וּמַאן דְּאִתְתָּקַּף בֵּיהּ, נֶצַח לֵיהּ. לָא אִתְחָזֵי לְרָזִין דְּאוֹרַיְיתָא, דְּהָא לָא שָׁכִיךְ בְּלִבֵּיהּ, בְּאִינּוּן רָזִין. דְּעָבִיד גַּרְמֵיהּ רַב בְּהוּ. דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְכְּלִיל בְּאָת ז' בִּלְחוֹדוֹי, וְאִתְרְחַק מֵאָת ס'. וּבְגִין דְּאִיהוּ עָבֵד גַּרְמֵיהּ בְּרַבְרְבָנוּ, אִתְרְחַק מִנֵּיהּ מֵאָת ס', וְלָא אִתְקְרִיב בַּהֲדֵיהּ. דָּא כַּד אִיהוּ מַלִּיל, עָבִיד קְמִיטִין סַגִּיאִין בְּמִצְחֵיהּ.","עַיְינִין חִוָּורִן, דְּסַחֲרָן זְעֵיר בִּירוֹקָא, מָארֵיהּ דְּרוּגְזָא, וְרַחֲמָנָא אִיהוּ לְרוֹב זִמְנִין. וְכַד אִתְמְלֵי רוּגְזָא, לֵית בֵּיהּ רְחִימוּ כְּלָל, וְאִתְהַפָּךְ לְאַכְזָרִיּוּת. לָאו אִיהוּ מָארֵיהּ דְּרָזִין, דָּא אִיהוּ בְּרָזָא דְּאָת ה', דְּאִתְכְּלִיל בְּאָת ס'.","עַיְינִין יְרוֹקִין וְחִוָּורִן כַּחֲדָא, וּזְעֵיר מִגָּוֶון אוּכָם בְּהוּ, דָּא אִיהִי מָארֵיהּ דְּרָזִין, וְאַצְלַח בְּהוּ. וְאִי שָׁאַרִי בְּאַצְלָחוּתָא אַצְלַח וְסָלִיק. שַׂנְאוֹי לָא יַכְלִין לֵיהּ, וְאִיהוּ שַׁלִּיט עָלַיְיהוּ בְּשׁוּלְטָנוּ, וְאִתְכַּפְיָין קָמֵיהּ. דָּא אִיהוּ בְּרָזָא דְּאָת כ', דְּאִתְכְּלִיל בְּרָזָא דְּאָת ס'. וְעַל דָּא אִיהוּ שַׁלִּיט, אִי שָׁאֲרִי בֵּיהּ. עַד הָכָא רָזִין דְּעַיְינִין לְאִינוּן מָארֵי דְּחָכְמְתָא."],[[0,"עיינין ירוקין דסחרין וכו':","עינים יריקות המסובבות בלבן, והירוק מתערב בלבן ההוא: הוא רחמן וחושב תמיד רק לתועלתו, ואינו מחשיב את נזק האחרים כלום."],[1,"גוונא אוכמא וכו':","אם גוון שחור לא נראה בו. הוא חומד, ולא מצד הרע. ואם עולה בידו דבר מצד הרע, לא ישיב ממנו. נאמן הוא במה שנודע, ואינו נאמן במה שלא נודע. בעל סוד הוא בדבר שהוא סוד, עד שישמע הסוד במקום אחר, כיון ששמע אותו, הוא מגלה הכל, ואין עוד עמו סוד כלל. כי כל דבריו אינם בשלימות. מי שצבעי עיניו מסבבים בלבן וירוק, זה הוא בסוד אות \u0003ה'\u0004 ונכלל באות \u0003ז'\u0004 ובאות \u0003ס'.\u0004"],[2,"עיינין צהיבין ירוקין וכו':","אם עיניו צהובות וירוקות: יש בו שגעון, ומשום השיגון שבו, הוא פה מדבר גדולות, ועושה עצמו כאדם גדול בגאותו ומי שמתקיפו מנצחו. אינו ראוי לסודות התורה, כי לבו אינו שקט בסודות, עד שיגלה אותם לאחרים. כדי לעשות עצמו אדם גדול בהם. זה הוא בסוד אות \u0003ה'\u0004 ונכלל באות \u0003ז'\u0004 לבדה ומתרחק מאות \u0003ס'.\u0004 ומשום שמנהיג עצמו בגאות הוא מתרתק מאות \u0003ס'\u0004 ואינו קרב אליה. זה, כשהוא מדבר, עושה קמטים רבים במצחו."],[3,"עיינין חוורן דסחרן וכו':","עינים לבנות, המסובבות קצת בירוק: הוא בעל כעס, והוא רחמן על פי רוב. וכשנתמלא בכעס, אין בו אהבה כלל, ומתהפך לאכזריות. אין הוא בעל סוד. זה הוא בסוד אות \u0003ה'\u0004 שנכלל באות \u0003ס'.\u0004"],[4,"עיינין ירוקין וחוורין וכו':","עינים ירוקות ולבנות ביחד, ומעט מצבע שחור בהן: זה הוא בעל סודות, ומצליח בהם. ואם מתחיל להצליח הוא מצליח ועולה. שונאיו לא יכלו לו והוא שולט עליהם בשליטה גמורה, והם נכנעים לפניו. זה הוא בסוד אות \u0003כ'\u0004 הנכלל בסוד אות \u0003ס'.\u0004 וע\"כ הוא שולט, אם מתחיל לשלוט. ע\"כ סוד העינים לאלו בעלי החכמה."]],[]],[["רָזָא דְּאַנְפִּין, לְאִינוּן מָארֵי דְּחָכְמְתָא פְּנִימָאָה. דִּיוּקְנִין דְּאַנְפִּין, לָאו אִינּוּן בִּרְשִׁימִין דִּלְבַר, אֶלָּא בְּגוֹ רְשִׁימָא דְּרָזִין פְּנִימָאִין. דְּדִיּוּקְנִין דְּאַנְפִּין, מִתְהַפְּכָן מִגּוֹ דִּיוּקְנִין דִּרְשִׁימוּ דְּאַנְפִּין, סְתִימִין בְּרוּחָא דְּשַׁרְיָא לְגוֹ. וּמִגּוֹ הַהוּא רוּחָא, אִתְחָזֵי לְבַר דִּיוּקְנִין דְּאַנְפִּין, דְּאִשְׁתְּמוֹדְעָן לְגַבֵּי אִינּוּן חַכִּימִין.","דִּיוּקְנִין דְּאַנְפִּין אִשְׁתְּמוֹדְעָן מִגּוֹ רוּחָא. רוּחָא אִית בְּבַר נָשׁ, דְּרָזִין דְּאַתְוָון חֲקִיקִין בֵּיהּ. וְכֻלְּהוּ אַתְוָון סְתִימִין גּוֹ הַהוּא רוּחָא, וּלְפוּם שַׁעֲתָא סַלְּקִין רְשִׁימִין דְּאִינּוּן אַתְוָון לְגוֹ אַנְפִּין. וּכְמָה דְּאִינּוּן אַתְוָון סַלְּקִין, הָכִי אִתְחָזוּן אַנְפִּין, בְּדִיּוּקְנִין רְשִׁימִין לְפוּם שַׁעֲתָא, בְּחֵיזוּ דְּלָא קַיְּימָא. בַּר אִינּוּן מָארֵי דְּחָכְמְתָא דְּאִתְקַיְּימָן בְּהוּ, וְלָא אִתְנְּשֵׁי מִנַּיְיהוּ.","הַהוּא אֲתָר דְּאִקְרֵי עָלְמָא דְּאָתֵי, (איהו רזא דאורייתא) וּמִתַּמָּן נַפְקָא רָזָא דְּאוֹרַיְיתָא, בְּכֻלְּהוּ אַתְוָון דְּאִינּוּן כ\"ב אַתְוָון, כְּלָלָא דְּכֹלָּא. וְהַהוּא נַהֲרָא דְּנָפִיק מֵעֵדֶן, נָטִיל כֹּלָּא. וְכַד פַּרְחָן מִנֵּיהּ אִינּוּן רוּחִין וְנִשְׁמָתִין, כֻּלְּהוּ מִצְטַיְּירָן בְּצִיּוּרָא דְּאִינּוּן אַתְוָון, וְהָכִי נַפְקֵי כֻּלְּהוּ. וּבְּגִין כָּךְ, רוּחָא דְּבַר נָשׁ דְּמִצְטַיְּירָא בְּצִיּוּרָא דְּאַתְוָון, עָבִיד צִיּוּרָא בְּאַנְפִּין.","אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן, אִי הָכִי צִיּוּרָא דְּאִימָא, לָא מִצְטַיְּירָא גּוֹ הַהוּא רוּחָא, אָמְרוּ, הָכִי שְׁמַעְנָא מִנֵּיהּ דְּמֹר, דְּצִיּוּרָא דְּאַתְוָון מִסִּטְרָא דִּלְעֵילָּא, וְצִיּוּרָא דְּאֵימָא מִצְטַיְּירָא בְּהַהוּא רוּחָא לְתַתָּא. צִיּוּרָא דְּאַתְוָון אִתְגְּנִיזוּ לְגוֹ, וְצִיּוּרָא דְּאֵימָא בָּלִיט לְבַר.","צִיּוּרָא דְּאִימָא, פְּנֵי אָדָ\"ם, פְּנֵי אַרְיֵ\"ה, פְּנֵי שׂוֹ\"ר, פְּנֵי נֶשֶׁ\"ר. וְרוּחָא עָבִיד צִיּוּרָא דְּכֻלְּהוּ לְבַר לְפוּם שַׁעֲתָא, בְּגִין דְּכָל מַה דְּאִיהוּ מִסִּטְרָא דְּרוּחָא בָּלְטָא לְבַר, וְאִתְחַזֵּי וְאִתְגְּנִיז. וְכָל הָנֵי דִּיוּקְנִין, אִתְחַזְיָין, מִתְצַיְּירָן בְּצִיּוּרָא דְּאַתְוָון אַף עַל גַּב דְּאִינּוּן גְּנִיזִין. אִלֵּין אַרְבַּע דִּיוּקְנִין אִתְחַזְיָין לְפוּם שַׁעֲתָא, לְאִינוּן מָארֵי דְּעַיְינִין, דְּיַדְעִין בְּרָזָא דְּחָכְמְתָא לְאִסְתַּכְּלָא בְּהוּ."],[[0,"רזא דאנפין וכו':","סוד הפנים לאלו בעלי החכמה הפנימית. צורות הפנים אינן ניכרות ברשימות שמבחוץ על עור הפנים, כמ\"ש במצח, אלא בתוך רשימה של סודות פנימיים, כי צורות הפנים מתהפכות ובאות, מכח הצורות של רשימות הפנים, שהן סתומות ברוח, השורה בפנימיות, ומתוך הרוח ההוא, נראות מבחוץ צורות הפנים, שהן ניכרות אל אלו החכמים. בעלי חכמה הפנימית כנ\"ל."],[1,"דיוקנין דאנפין אשתמודען וכו':","צורות הפנים ניכרות מתוך הרוח, רוח יש באדם, שסוד האותיות חקוקות בו, וכל כ\"ב אותיות סתומות בתוך רוח ההוא, ולפי השעה של האדם, עולות רשימות של אלו האותיות לתוך הפנים, וכמו שאלו האותיות עולות, כן הפנים נראות בצורות הרשומות לפי שעה של האדם, במראה שאינה מתקיימת, אלא הן צורות עוברות, ובעלי החכמה בלבד רואים אותן ומתקיימות בהם ואינן נשכחות מהם."],[2,"ההוא אתר דאקרי וכו':","מקום ההוא שנקרא עולם הבא, דהיינו בינה, משם יוצא סוד התורה, שהוא ז\"א הנאצל מבינה, בכל האותיות, שהן כ\"ב אותיות, כלל הכל, ונהר ההוא היוצא מעדן, שהוא ז\"א, לוקח הכל. וכשפורחים ממנו הרוחות והנשמות, כולם מצטיירים בציור של האותיות האלו. וכן יוצאים כולם. ועל כן רוח האדם המצטייר בציור של האותיות, עושה ציור בפנים של האדם."],[3,"א\"ל ר\"ש וכו':","אמר לו ר' שמעון, אם כן, ציור של אמו של הרוח, דהיינו מלכות, אינו מצטייר תוך רוח ההוא. כי האותיות הן באות מאבי הרוח שהוא ז\"א כנ\"ל. אמרו לו, כך שמענו מאדוני, שציור האותיות בא מצד מעלה, מז\"א, וציור של אמא, דהיינו המלכות, שהוא ד' פנים אריה שור וכו' כלהלן, מצטייר ברוח ההוא מלמטה. וציור האותיות, הבאות מז\"א, נגנזות מבפנים. וציור של אמא בולט לחוץ."],[4,"ציורא דאמא פני וכו':","הציור של אמא, שהיא מלכות, הוא פני אדם, פני אריה, פני שור, פני נשר. והרוח עושה ציור כולם רק לפי שעה, כי כל מה שהוא מצד הרוח,בולט לחוץ ונראה ומיד נגנז. וכל אלו הצורות נראות מצטיירות בציור האותיות, הבאות מז\"א, אע\"פ שהן גנוזות מבפנים. כנ\"ל. אלו ארבע צורות נראות לפי שעה לאלו בעלי העינים, דהיינו בעלי החכמה, היודעים בסוד החכמה להסתכל בהן."]],[]],[["צִיוּרָ\"א קַדְמָאָ\"ה, כַּד אָזִיל בַּר נָשׁ בְּאֹרַח קְשׁוֹט, אִינּוּן דְּיַדְעִין בְּרָזִין דְמָרֵיהוֹן מִסְתַּכְּלָן בֵּיהּ, בְּגִין דְּהַהוּא רוּחָא דִּלְגוֹ, מְתַּתְקְנָא בֵּיהּ, וּבָלִיט לְבַר, צִיּוּרָא דְּכֹלָּא. וְהַהוּא צִיּוּרָא אִיהוּ צִיּוּרָא דְּאָדָם, וְדָא אִיהוּ צִיּוּרָא שְׁלִים יַתִּיר מִכָּל צִיּוּרִין. וְדָא אִיהוּ צִיּוּרָא, דְּאַעְבַּר לְפוּם שַׁעֲתָא, קָמֵי עֵינַיְיהוּ דְּחַכִּימֵי לִבָּא. הַאי כַּד מִסְתַּכְּלָן בְּאַנְפּוֹי לְבַר, אִינּוּן אַנְפִּין דְּקַיְימִן קָמֵיהּ, עַיְינִין דְּלִבָּא רָחִים לוֹן.","אַרְבַּע סִימָנִין דְּאַתְוָון אִית בְּהוּ, שׁוּרְיְיקָא חַד בָּלִיט בִּשְׁכִיבוּ, בְּסִטְרָא דִּיִמִינָא, וְשׁוּרְיְיקָא חַד דְּכָלִיל תְּרֵין אַחֲרָנִין דַּאֲחִידָן בֵּיהּ, בְּסִטְרָא דִּשְׂמָאלָא. וְאִלֵּין ד' סִימָנִים, אִינּוּן ד' אַתְוָון, דְּאִקְרוּן עֵדוּת וְסִימָנָא דָּא ע'. הַהוּא שׁוּרְיְיקָא דִּסְטַר יְמִינָא, דְּבָלִיט בִּשְׁכִיבוּ. ד' וְאִינּוּן תְּרִין אַתְוָון דְּמִתְחַבְּרָן בֵּיהּ (ס\"א ו\"ת אינון עדות') ו\"ת אִינּוּן הַהִיא שׁוּרְיְיקָא דְּכָלִיל תְּרֵין אַחֲרָנִין, וְדָא אִיהוּ רָזָא דִּכְתִּיב, (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שְׁמוֹ דְּכָל מַאן דְּחָמָא לֵיהּ הֲוָה רָחִים לֵיהּ בְּלִבּוֹי, וּבִרְחִימוּ אִשְׁתְּלִים.","זַרְעָא דְּדָוִד מִתְהַפְּכָן בֵּיהּ חֵיזוּ דִּגְוָונִין, וּבְּגִין כָּךְ טָעָה שְׁמוּאֵל, דִּכְתִּיב, (שמואל א ט״ז:ז׳) אַל תַּבֵּט אֶל מַרְאֵהוּ, בְּגִין דְּסִטְרָא אַחֲרָא הֲוָה בֵּיהּ בֶּאֱלִיאָב, דְּלָא הֲוָה הָכִי בְּדָוִד, דְּיּוּקְנִין דְּדָוִד טְמִירִין אִינּוּן, דְּהָא דְּיּוּקְנִין דְּסִטְרָא אַחֲרָא, אִתְכְּלִיל גּוֹ דִּיּוּקְנִין, וְהַהוּא דִּיּוּקְנָא דִּסְטָר אַחֲרָא אִתְחָזֵי בֵּיהּ בְּקַדְמִיתָא, דְּאַעְבַּר עַל עַיְינִין לְפוּם שַׁעֲתָא, וּבָהִיל לִבָּא וְדָחִיל, וּלְבָתַר (שמואל א ט״ז:י״ב) וְטוֹב רוֹאִי וַיְיָ' עִמּוֹ. וְדָא אִיהוּ עֵדוּת לְגַבֵּיהּ.","דִּיּוּקְנָא דָּא דְּאָדָם, כָּלִיל כָּל דִּיוּקְנִין, וְכֻלְּהוּ כְּלִילָן בֵּיהּ, הַאי לָא בָּהִיל בְּרוּחֵיהּ. בְּשַׁעֲתָא דְּרוּגְזֵיהּ אִיהוּ בְּנַיְיחָא, וּמִלּוֹי בְּנַיְיחָא, וּמִיָּד אִתְפָּיָּיס."],[[0,"ציורא קדמאה וכו':","ציור הראשון, הוא, כשהולך האדם בדרך האמת, אותם שיודעים בסוד אדונם מסתכלים בו, משום שרוח ההוא שבפנים מתתקן בו, ובולט לחוץ ציור הכולל הכל, וציור ההוא הוא ציור פני \u0003אדם,\u0004 וזה הוא ציור השלם יותר מכל הציורים. וזה הוא ציור העובר לפי שעה לפני עיניהם של חכמי לב. זה, כשמסתכלים בפניו בחוץ, אלו הפנים העומדים לפניו, עיני הלב אוהבות אותם."],[1,"ארבע סימנין דאתוון וכו':","ארבעה סימנים של אותיות יש בהם: גיד אחד בולט בפניו בשקיעה, כלומר שאינו בולט לחוץ אלא כמו שבולט בשקיעה. שכיבו פירושו שקיעה, מצד ימין, וגיד אחד הכולל ב' אחרים האחוזים בו, מצד שמאל של הפנים. אלו ד' סימנים הם ד' אותיות \u0003עדות.\u0004 וסימן זה הוא \u0003ע'\u0004 היא גיד ההוא שמצד ימין הבולט בשכיבה. \u0003ד'\u0004 ואלו ב' אותיות המתחברות עמו שהם ות, הן גיד ההוא הכולל שני גידים האחרים שמצד שמאל של הפנים. וזה הוא סוד שכתוב, \u0003עדות\u0004 ביהוסף שמו וגו'. שכל מי שראה אותו היה אוהב אותו בלבו. ובאהבה הוא נשלם."],[2,"זרעא דדוד מתהפכן וכו':","זרעו של דוד, מתהפכים בו המראות של הגוונים. וע\"כ טעה שמואל, שכתוב אל תבט אל מראהו. משום שהצד האחר היה באליאב, שלא היה כן בדוד, הצורות של דוד מכוסות הן, כי הצורות של הצד האחר נכללו תוך הצורות שלו, והצורה של הצד האחר נראה בו תחלה, שעוברת על העינים לפי שעה, והלב מבוהל ומתירא, ואחר כך, \u0003וטוב רואי וה' עמו.\u0004 וזהו עדות אצלו."],[3,"דיוקנא דא דאדם וכו':","צורה זו של פני אדם, כולל לכל הצורות, וכולן כלולות בו. זה, אינו מבוהל ברוחו. בשעת כעסו הוא במנוחה, ודבריו בנחת, ומיד מתרצה."]],[]],[["זַרְעָא דְּדָוִד דְּאִתְחָזֵי בֵּיהּ הַהוּא דִּיּוּקְנָא בְּקַדְמִיתָא, דְּאַעְבַּר לְפוּם שַׁעֲתָא עַל עַיְינִין, בְּרוּגְזֵיהּ בְּנַיְיחָא, מִיָּד אִתְפָּיַּיס. אֲבָל נָטִיר דְּבָבוּ כְּנָחָשׁ לְסוֹפָא. בְּגִין דְּהַהוּא סִטְרָא גַּרְמָא לֵיהּ, דְּסַחֲרָא בְּכָל סִטְרִין. אֲבָל מוֹחָא דִּבְגוֹ קְלִיפָה וְלִבָּא מִתְיַשְּׁרָא, וְיַצִּיבָא דָּא לְאִינוּן זַכָּאִין. אֲבָל חַיָּיבִין לָא מִתְעַבְּרָן מֵהַהוּא דִּיּוּקְנָא קַדְמָאָה בִּישָׁא, וְאִתְחַבְּרָן (ואסתאבן) בֵּיהּ בְּכֹלָּא.","צִיוּרָ\"א תִּנְיָינָ\"א, אִי הַהוּא בַּר נָשׁ לָא אָזִיל כָּל כַּךְ בְּאָרְחָא בִּישָׁא, וְאַסְטֵי מֵהַהוּא אָרְחָא, וְתָב לְמָארִיהּ, לָא דְּהוּא רְגִילָא בְּאָרְחוֹי דִּמְתַקְּנָן, אֶלָּא אִיהוּ דְּהֲוָה בְּאִינּוּן אוֹרְחֵי מִתְעֲדֵי, וְסָטֵי מִנַּיְיהוּ וְתָב לְמָארֵיהּ. הַאי אִיהוּ רוּחָא טָבָא שָׁארֵי לְמִשְׁרִי עֲלוֹי, וּלְאִתַּתְקְפָא עַל זוּהֲמָא קַדְמָאָה דְּהֲוָה בֵּיהּ, וּבָלִיט לְבַר, בְּאִסְתַּכְּלוּתָא, דְּעַיְינִין לְפוּם שַׁעֲתָא, כְּחַד דִּיּוּקְנָא דְּאַרְיֵה דְּאִתְגַּבָּר הַאי בְּשַׁעֲתָא דְּחָמֵי לֵיהּ, הַהוּא חֵיזוּ גָּרִים לֵיהּ לְאַעְבָּר בְּלִבֵּיהּ אַרְיֵה דְּמִתְגַּבְּרָא לְפוּם שַׁעֲתָא.","הַאי מִסְתַּכְּלָן בְּאַנְפּוֹי לְבָתַר, אִינּוּן אַנְפִּין דְּלִבָּא לָא רָחִים לוֹן לְפוּם שַׁעֲתָא, וּמִיָּד תָּב לִבֵּיהּ וְרָחִים לֵיהּ. כַּד מִסְתַּכְּלָן בֵּיהּ אַכְסִיף, וְחָשִׁיב דְּכֹלָּא יַדְעִין בֵּיה. אַנְפּוֹי חַפְיָין דָּמָא לְפוּם שַׁעֲתָא, מִתְהַפְּכָן לְחִוְּורָא אוֹ לִירוֹקָא.","תְּלַת שׁוּרְיְיקָן אִית בְּאַנְפּוֹי. חַד לִימִינָא, דְּדָא אִתְפָּשַׁט בְּאַנְפּוֹי וְאִתְאֲחִיד בֵּיהּ. חַד דְּסַלְּקָא לְחוֹטָמֵיהּ לְעֵילָּא, וּתְרֵין לִשְׂמָאלָא. וְחַד דְּאִתְפָּשַּׁט לְתַתָּא מֵאִינּוּן תְּרִין, וְאָחִיד בְּהַאי וּבְהַאי. וְאִלֵּין אִינּוּן אַתְוָון דְּמִתְחַקְּקָן בְּאַנְפּוֹי, וְאִינּוּן בַּלְטִין דְּלָא שְׁכִיבִין. וְכַד מִתְיַישְׁבָא וְאַרְגִּיל בְּאֹרַח קְשׁוֹט, שְׁכִבִין.","וְרָזָא דְּאִינּוּן אַתְוָון אִיהוּ קָרִיב. דָּא הֲוָה רָחִיק, וְהַשְׁתָּא אִינּוּן אַתְוָון בַּלְטִין בְּאַנְפּוֹי, וְסָהֲדִין בֵּיהּ בִּבְהִילוּ. וְסִימָנָא דָּא ק' (ד\"א ה') מִסְּטָר יְמִינָא אַתְוָון אַחֲרָנִין מִסְּטָר שְׂמָאלָא, וְאַף עַל גַּב דְּשׁוּרְיָיקֵי אַחֲרָנִין אִתְחָזוּן בְּאַנְפּוֹי, לָא בַּלְטִין לְבַר כְּהָנֵי. בַּר בְּזִמְנָא דְּהֲוָה אָזִיל בְּעַקִּימוּ."],[[0,"זרעא דדוד דאתחזי וכו':","זרעו של דוד, אשר נראה בו צורה ההיא של הס\"א בתחילה ועוברת לפי שעה לפני העינים, כנ\"ל. בכעסו הוא במנוחה ומיד מתרצה. אבל נוטר שנאה כנחש לבסוף. משום שהצד ההוא גרם לו זה, שמסבב בכל הצדדים עד שלוקח נקמתו, אבל המוח שבתוך קליפה זו והלב מתישרים. וזה נכון לצדיקים, אבל הרשעים אינם סרים מאותה צורה הראשונה הרעה, ומתחברים בה לגמרי."],[1,"ציורא תנינא וכו':","הציור השני הוא. אם אדם ההוא אינו הולך כל כך בדרך הרע, וסר מדרך ההוא ושב לאדונו, זה, רוח טוב מתחיל לשרות עליו, ומתחזק על זוהמא הראשונה שהיתה בו, ובולט לחוץ, בהסתכלות עינים לפי שעה, כצורה אחת של אריה המתגבר. זה, בשעה שרואים בו צורה זו, מראה ההיא גרמה לו, שיעבור בלבו אריה המתגבר לפי שעה, דהיינו שלבו יתגבר על צד הרע לפי שעה."],[2,"האי מסתכלן באנפוי וכו':","זה, שיש לו פני אריה המתגבר, כשמסתכלים בפניו אחר כך, הם פנים שהלב אינו אוהב אותם לפי שעה, ומיד חוזר לבו ואוהב אותם. כשמסתכלים בו מתבייש, וחושב שהכל יודעים בו, כלומר, שנדמה לו שיודעים כל מה שחושב ועושה במסתרים. ומתוך בושה, פניו מתמלאים בדם לפי שעה, ואח\"כ מתהפכים ללבן או לירוק."],[3,"תלת שורייקן אית וכו':","ג' גידים דקים יש בפניו. א' לימין, שזה מתפשט בפניו ונאחז בו. ואחד, שעולה לחוטמו למעלה. ושנים לשמאל, ואחד מתפשט למטה מאלו השנים, ואוחז בזה ובזה. ואלו הן אותיות הנחקקות בפניו, והן בולטות ואינן שוקעות. וכשמתישב ומתרגל בדרך האמת, הן שוקעות."],[4,"ורזא דאינון אתוון וכו':","והסוד של אלו האותיות, הוא \u0003קרוב.\u0004 כי זה היה רחוק, ועתה ששב ונתקרב, בולטות אלו האותיות בפניו ומעידות עליו בחפזה. וסימן זה הוא, \u0003ק'\u0004 מצד ימין של הפנים. והאותיות האחרות שהן \u0003רוב,\u0004 הן מצד שמאל של הפנים. ואע\"פ שגידים אחרים מתראים בפניו, אינם בולטים לחוץ כמו אלו. חוץ אם הולך בדרך עקלקלות. בולטות גם הן."]],[]],[["הַאיִ אִיהוּ זַרְעָא דְּדָוִד, אִתְהַפַּךְ מֵחֵיזוּ דָּא. בְּקַדְמִיתָא אִתְחָזֵי בְּדִיּוּקְנָא דְּאָדָם, וּלְבָתַר קַיְימָא בְּדִיּוּקְנָא דְּאַרְיֵה, וְאִתְפְּרַשׁ בְּדִיּוּקְנָא דְּסִטְרָא אַחֲרָא, וּבְכֹלָּא, מִתְהַפְּכָא מִשְּׁאָר בְּנֵי נָשָׁא.","צִיוּרָ\"א תְּלִי\"תָאָה, אִי הַהוּא בַּר נָשׁ אָזִיל בְּאָרְחָא דְּלָא מְתַּתְקְנָא, וְסָטֵי אוֹרְחוֹי מֵאָרְחֵי דְּאוֹרַיְיתָא, הַהוּא רוּחָא קַדִּישָׁא אִסְתַּלָּק מִנֵּיהּ, וְרוּחָא אַחֲרָא אִתְחָזֵי בֵּיהּ, וּדְיוּקְנָא אַחֲרָא, וּבָלִיט לְבַר, בְּאִסְתַּכְּלוּתָא דְּעַיְינִין דְּחַכִּימֵי לִבָּא, לְפוּם שַׁעֲתָא דִּיּוּקְנָא דְּשׁוֹר. בְּשַׁעֲתָא דְּחָמָאן לֵיהּ, מַעְבְּרָן בְּלִבַּיְיהוּ הַהוּא דִּיּוּקְנָא, וְאִסְתַּכְּלָן בֵּיהּ.","ג' קוּרְטָמֵי סוּמָקֵי בְּאַנְפּוֹי, בְּסִטְרָא דִּימִינָא, וְאִינּוּן שׁוּרְיָיקֵי סוּמָקִין דְּקִיקִין. וּתְלַת בִּשְׂמָאלָא, וְאִלֵּין אִינּוּן אַתְוָון דְּבַלְטִין בֵּיהּ. חַד אִיהוּ שׁוּרְיְיקָא דָּקִיק בְּעִגּוּלָא, וּתְרֵין דְּקִיקִין אַחֲרָנִין עָלֵיהּ, וְכֻלְּהוּ בְּעִגּוּלָא. וּכְדֵין שְׁקִיעִין עֵינוֹי.","וְרָזָא דְּאִינּוּן אַתְוָון. חַד אִיהוּ כ', תְּרֵין אַחֲרָנִין ר\"ת אִינּוּן. וְכֵן לִסְטַר שְׂמָאלָא, וְסִימָנָא דָּא הַהוּא דִּכְתִּיב, (ישעיהו ג׳:ט׳) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם וְאִלֵּין אַתְוָון בַּלְטִין בְּאַנְפִּין, עַל כָּל שְׁאַר שׁוּרְיָיקִין. וְאִי תָּב מִשְּׂמָאלָא לִימִינָא, אִתְכַּפְיָא הַהוּא רוּחָא וְאִתְתָּקַּף רוּחָא דְּקֻדְשָׁא, וְאִלֵּין שׁוּרְיָיקִין שְׁכִיבוּ, וְאַחֲרָנִין בַּלְטִין לְבַר, כְּמָה דְּאִתְּמַר.","זַרְעָא דְּדָוִד אִיהוּ בְּהִפּוּכָא, אִתְחַזְיָא בְּדִיּוּקְנָא דְּאַרְיֵה בְּקַדְמִיתָא, וּלְבָתַר אִתְהַדַּר בְּדִיּוּקְנָא דְּשׁוֹר. תְּרִין שׁוּרְיָיקִין אוּכָּמִין בְּאַנְפּוֹי, חַד מִימִינָא, וְחַד מִשְּׂמָאלָא, וְאִלֵּין אִינּוּן אַתְוָון, חַד אִקְרֵי ד', וְחַד אִקְרֵי ע', וְכֹלָּא מִתְהַפְּכָא מִשְּׁאָר בְּנֵי נָשָׁא.","צִיוּרָ\"א רְבִיעָ\"אָה, דָּא אִיהוּ צִיּוּרָא דְּבַר נָשׁ, דְּקַיְּימָא תָּדִיר לְאִתְתַּקְנָא עַל רָזָא דְּמִלְקַדְּמִין, הַאי אִיהוּ חֵיזוּ לְחַכִּימֵי לִבָּא בְּדִיּוּקְנָא דְּנֶשֶׁר. הַהוּא רוּחָא דִּילֵיהּ אִיהוּ רוּחָא חַלְשָׁא. הַאי לָא אַחְזֵי בְּאַנְפִּין אַתְוָון דְּבַלְטִין לְבַר, דְּהָא אִתְאֲבִידוּ מִנֵּיהּ, וְאִשְׁתְּקָעוּ בְּזִמְנָא אַחֲרָא דְּמִלְקַדְּמִין, דְּאִסְתָּלָּקוּ מִנֵּיהּ, וְעַל דָּא לָא בַּלְטִין בֵּיִהּ.","וְרָזָא דִּילֵיהּ, עֵינוֹי לָא נְהִרִין בִּנְצִיצוּ, כַּד אִיהוּ בְּחֶדְוָה. וּבְזִמְנָא דְּסָפַר שְׂעַר רֵישֵׁיהּ וְדִיקְנִיהּ. בְּגִין דְּרוּחֵיהּ לָא נָהִיר לֵיהּ בְּאַתְוָון, וְאִשְׁתְּקַע נְצִיצוּ דִּילֵיהּ דְּהֲוָה בְּקַדְמִיתָא. לָא קַיְּימָא בְּאִסְתַּכְּלוּתָא דְּאַנְפִּין לְאִסְתַּכְּלָא. וְרָזָא דְּהַאי (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָּה. זַרְעָא דְּדָוִד, (תהילים כ״ה:י״ד) סּוֹד יְיָ' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.","בְּרוּחָא דְּבַר נָשׁ, אִצְטְיָּירוּ אַתְוָון, כְּמָה דְּאִתְּמַר, וְאִיִהוּ בָּלִיט לוֹן לְבַר, וְאִתְמְסַר חָכְמְתָא דָּא לְחַכִּימֵי לִבָּא לְמִנְדַּע וּלְאִשְׁתְּמוֹדְעָא, רוּחָא קַיְימָא בְּרָזָא (בראשית ה) דְּזֶה סֵפֶר, וְכֹלָּא בְּרָזָא דָּא קַיְּימָא, בַּר חֵיזוּ דְּאַנְפִּין דְּאִתְּדָּן בְּגַוְונָא אַחֲרָא, כְּפוּם שׁוּלְטָנוּ דְּרוּחָא, אוֹ מָארִיהּ דְּרוּחָא. זַכָּאִין אִינּוּן חַכִּימִין דְּכֹלָּא אִתְמְסַר לוֹן לְמִנְדַּע. עַד הָכָא רָזָא דְּאַנְפִּין."],[[0,"האי איהו זרעא דדוד וכו':","זה שהוא מזרעו של דוד, הוא מתהפך ממראה זו, מתחילה נראה בצורת אדם, ואח\"כ עומד בצורת אריה, ונפרד מצד האחר. ובכל דבר, הוא מתהפך משאר בני אדם."],[1,"ציורא תליתאה וכו':","ציור השלישי הוא. אם אדם ההוא הולך בדרך שאינו מתוקן, ודרכיו סרים מדרך התורה. ההוא, רוח הקדוש נסתלק ממנו, ורוח אחר נראה בו, וצורה אחרת, ובולט לחוץ, בהסתכלות עינים של חכמי לב לפי שעה, צורה של \u0003שור.\u0004 בשעה שרואים אותו, חכמי הלב, מעבירים בלבם צורה ההיא של שור, ומסתכלים בה."],[2,"ג' קורטמי סומקי וכו'",": כג' גרעינים של כרכום פראי הנקרא קורטמא, אדומים, בפניו מצד ימין, והם גידים אדומים קטנים. וג' בשמאל של הפנים. אלו הן האותיות הבולטות בו. אחד, מן הג' שבימין ושמאל, הוא גיד קטן בעגול, וב' גידין קטנים עליו, וכולם בעגול. ואז עיניו שקועות בתוך המצח."],[3,"ורזא דאינון אתוון וכו':","והסוד של אלו האותיות. אחד מן הג' הוא \u0003כ',\u0004 ושני גידים האחרים הם \u0003ר\"ת.\u0004 וכן הג' של צד השמאל, א' מהם הוא \u0003כ'\u0004 והאחרים \u0003ר\"ת.\u0004 וסימן זה הוא שכתוב, \u0003הכרת\u0004 פניהם ענתה בם. ואלו האותיות בולטות בפנים יותר מכל שאר הגידים ואם שב בתשובה משמאל, ובא לצד ימין, נכנע רוח ההוא ומתחזק רוח של הקדושה, ואלו הגידים שוקעים ואחרים בולטים לחוץ. כמו שלמדנו."],[4,"זרעא דדוד איהו וכו':","זרעו של דוד הוא להיפך. שנראה בצורת אריה תחילה, ואח\"כ חוזר לצורת שור. ב' גידים שחורים בפניו, אחד מימין ואחד משמאל, ואלו הם האותיות, אחד נקרא \u0003ד'\u0004 ואחד נקרא \u0003ע'.\u0004 וכולו מתהפך משאר בני אדם."],[5,"ציורא רביעאה וכו':","ציור הרביעי, זה הוא ציור של אדם, העומד תמיד להתתקן על סוד מה שעשה בראשונה, ואינו פוגם יותר. זה הוא מראה לחכמי לב בצורת \u0003נשר.\u0004 רוח ההוא שלו הוא רוח חלש. זה אינו מראה בפנים אותיות בולטות לחוץ, כי נאבדו ממנו ונשתקעו בזמן אחר בקדמות ימיו, שנסתלקו ממנו אז, ועל כן אינן בולטות בו."],[6,"ורזא דיליה עינוי וכו':","והסוד שלו. עיניו אינן מאירות בהתנוצצות כשהוא בשמחה, ובזמן שגוזז שער ראשו וזקנו, משום שרוחו אינו מאיר לו באותיות, ונשקע ההתנוצצות שלו שהיתה לו מתחילה. אינו עומד בהסתכלות הפנים להסתכל בו. מפני שאין לו אותיות בולטות כנ\"ל. והסוד של זה הוא, ושבח אני את המתים שכבר מתו מן החיים אשר המה חיים עדנה. זרעו של דוד, סוד ה' ליראיו ובריתו להודיעם."],[7,"ברוחא דבר נש וכו':","ברוח האדם מצטיירים אותיות כמו שלמדנו, והוא מבליט אותן לחוץ על הפנים. ונמסר חכמה זו לחכמי לב לדעת ולהכיר. הרוח עומד בסוד \u0003זה ספר,\u0004 והכל עומדים בסוד זה, חוץ ממראה הפנים שנדון באפן אחר, כפי שליטת הרוח או בעל הרוח. אשרי הם החכמים שהכל נמסר להם לדעת. עד כאן סוד הפנים."]],[]],[["מִכָּאן וּלְהָלְאָה בְּרָזָא דְּשִׂפְוָון, בְּאָת פ' דְּכָלִיל בְּרָזָא דְּאָת ס'. שִׂפְוָון רַבְרְבָן, דָּא אִיהוּ בַּר נָשׁ מַלִּיל בְּלִישָׁנָא בִּישָׁא, וְלָא אַכְסִיף, וְלָא דָּחִיל, מָארֵי דְּמַחְלוֹקֶת, רְכִילָא אִיהוּ בֵּין הַאי לְהַאי. (משלי ו׳:י״ט) וּמְשַׁלֵּחַ מְדָנִים בֵּין אַחִים. לָאו אִיהוּ מָארִיהּ דְּרָזִין, וְכַד אִשְׁתַּדַּל בְּאוֹרַיְיתָא מְכַסֶּה רָזִין, אֲבָל מָארִיהּ דְּלִישָׁנָא בִּישָׁא, וְלָא שָׁוִי דְּחִילוּ בְּלִבֵּיהּ.","וְסִימָנָא דָּא, אָת פ' דְּכָלִיל בְּאָת ר' וְלָא אִתְכְּלִיל בְּאָת ס'. הַאי אִיהוּ דְּאִתְחָזֵי דְּאִיהוּ זַכָּאָה, וְלָא דָּחִיל חַטָּאָה אִיהוּ, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא אֲבַתְרֵיהּ, בְּגִין דְּכָל מִלּוֹי אִינּוּן בְּפוּמָא וְלָא בְּגוּפָא.","שִׂפְוָון עַתִּיקִין בְּעַתִּיקוּ, וְלָאו דְּקִיקִין. הַאי אִיהוּ בַּר נָשׁ מָארֵיהּ דְּרוּגְזָא יַתִּיר. מָארִיהּ דִּזְדוֹנָא. לָא יָכִיל לְמִסְבַּל מִלָּה. מָארֵי דְּלִישָׁנָא בִּישָׁא בְּפַרְהֶסְיָא, בְּלָא כִּסּוּפָא כְּלַל. לְזִמְנִין אִשְׁתָּדַּל בְּלֵיצָנוּתָא. הַאי אִיהוּ בַּר נָשׁ דְּבָעֵי לְאִתְרַחֲקא מִנֵּיהּ.","אִתְמְלֵי דִּיקְנֵיהּ בְּשַׂעְרָא, הַהוּא, לִישָׁנָא בִּישָׁא, אוִֹרִי עָלֵיהּ בְּפַרְהֶסְיָא, לֵית לֵיהּ כִּסּוּפָא. אִשְׁתָּדַּל בְּמַחְלוֹקֶת. אַצְלַח בְּמִלֵּי דְּעָלְמָא. חָמֵי בְּשַׂנְאוֹי. דָּא אִיהוּ (משלי ו׳:י״ג) קוֹרֵץ בְּעֵינָיו, עַל דָּא אִתְּמַר (משלי כ״א:כ״ט) הֵעֵז אִישׁ רָשָׁע בְּפָנָיו. דָּא אִיהוּ בְּרָזָא דְּאָת פ' בִּלְחוֹדוֹי. דְּלָא אִתְכְּלִיל בְּאָת ס' כְּלָל. וּלְזִמְנִין אִתְחַבָּר בְּאָת ר' בְּהַאי אָת ר' אִתְכְּלִיל.","בְּרָזָא דְּאוּדְנִין, מַאן דְּאוּדְנוֹי רַבְרְבִין, טִפְּשָׁא בְּלִיבֵּיהּ וְשִׁגְעוֹנָא בְּרוּחֵיהּ. מַאן דְּאוּדְנוֹי זְעִירִין, וְקַיְימִין עַל קִיּוּמָא. פְּקִיחָא דְּלִבָּא בְּאִתְעָרוּתָא אִיהוּ. צָבֵי לְאִשְׁתַּדְּלָא בְּכֹלָּא. וְרָזָא דָּא אָת י' דְּאִתְכְּלִיל בְּכָל שְׁאַר אַתְוָון.","עַד הָכָא, רָזִין דְּדִיּוּקְנִין דְּבַר נָשׁ. מִכָּאן וּלְהָלְאָה, רָזִין אַחֲרָנִין בְּאַתְוָון דְּמֹר, דְּלָא קַיְימִין גּוֹ פַּרְצוּפָא, אֶלָּא לְמִנְדַּע רָזִין דְּהַאי פְּסוּקָא, גּוֹ דַּרְגִּין עִלָּאִין, בִּזְמַנִין וּתְקִיפִין דְּהַאי עָלְמָא, וְלָא זָכֵינָן בְּהוּ.","אָמַר ר' שִׁמְעוֹן, בָּנַי, זַכָּאִין אַתּוּן בְּעָלְמָא, דֵּין, וּבְעָלְמָא דְּאָתֵי, וְזַכָּאִין עֵינַי, דְּיִזְכּוּן לְמֶיחֱמֵי דָּא, כַּד אֵיעוּל לְהַהוּא עָלְמָא דְּאָתֵי. בְּגִין נִשְׁמָתִי קָרֵי לְעַתִּיק יוֹמִין, הַאי קְרָא, (תהילים כ״ג:ה׳) תַּעֲרוֹךְ לְפָנַי שֻלְחָן נֶגֶד צוֹרְרָי דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי כּוֹסִי רְוָיָה. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי עֲלָן, (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְיָבֹא גּוֹי צַדִּיק שׁוֹמֵר אֱמוּנִים. \"","אוּף אִינּוּן פָּתְחוּ וְאָמְרוּ, כְּתִיב (יחזקאל א׳:ח׳) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, דְּאִינּוּן יְדִין לְקַבְּלָא מָארִיהוֹן דִתִיוּבְתָּא דְּתָבָאָן לְגַבֵּי (נ\"א לקבל) קוּדְשָׁא בְּרִיךְ הוּא. אֲבָל יְדֵי אָדָם, אִלֵּין אִינּוּן דְּיּוּקְנִין וְרָזִין עִלָּאִין, דְּשַׁוִּי קוּדְשָׁא בְּרִיךְ הוּא בְּבַר נָשׁ, וְסִדֵּר לוֹן בְּאֶצְבְּעָן לְבַר וּלְגוֹ. וּבְהַהוּא כַּ\"ף.","וְקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא לֵיהּ לְבַר נָשׁ, סִדֵר בֵּיהּ, כָּל דִּיּוּקְנִין דְּרָזִין עִלָּאִין, דְּעָלְמָא דִּלְעֵילָּא, וְכָל דִּיּוּקְנִין דְּרָזִין תַּתָּאִין, דְּעָלְמָא דִּלְתַתָּא, וְכֹלָּא מִתְחַקְּקָא בְּבַּר נָשׁ, דְּאִיהוּ קָאִים בְּצֶלֶם אֱלהִים, בְּגִין דְּאִקְרֵי יְצִיר כַּ\"ף.","וְרָזָא דְּכַ\"ף, דְּאָת דָּא דְּאִקְרֵי כַּ\"ף, דִּכְתִּיב, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלהִים אֶת הָאָדָם בְּצַלְמוֹ, דָּא אִיהוּ רָזָא דְּאָת כַּ\"ף. אָת דָּא, אִית בֵּיהּ רָזִין עִלָּאִין, וְדִיּוּקְנִין עִלָּאִין. בְּהַאי כַּ\"ף תַּלְיָין עֶשֶׂר אֲמִירָן מִימִינָא וּמִשְּׂמָאלָא, חָמֵשׁ מִימִינָא, וְחָמֵשׁ מִשְּׂמָאלָא, וְאִינּוּן חַד בְּרָזָא חֲדָא.","(תנינן כתיב (יחזקאל כ״א:כ״ב) וגם אני אכה כפי אל כפי, דלהוו דא עם דא בפלוגתא ויסתלקו ברכאן מעלמא, הואיל וגאותא דישראל אתיהיבת לעמין. כד מתחברן כחדא, כתיב, (במדבר ז׳:י״ד) כף אחת עשרה זהב מלאה קטרת רמז לחבורא חדא.) וְכַד הֲווֹ בְּחִבּוּרָא חֲדָא, כְּתִיב, וַיִּבְרָא אֱלהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ'. וַיִּבְרָא אֱלֹהִים (את האדם) דָּא סְלִיקוּ דְּמַחֲשָׁבָה בְּרָזָא פְּנִימָאָה. אֶת הָאָדָם: רָזָא דְּכַר וְנוּקְבָּא כַּחֲדָא, בְּצֶלֶם אֱלהִים רָזָא דְּכַף (אחרא)."],[[0,"מכאן ולהלאה ברזא דשפוון:","מכאן ולהלאה הוא בסוד השפתים. באות \u0003פ'\u0004 שנכללה בסוד אות \u0003ס'.\u0004 שפתים גדולות, זה הוא אדם המדבר לשון הרע ואנו מתביש ואינו מפחד. בעל מחלוקת ורכילות הוא בין זה לזה, דהיינו בין אדם לחבירו. ומשלח מדנים בין אחים, הוא אינו בעל סוד. וכשמשתדל בתורה הוא מכסה סוד. אבל בעל לשון הרע ואינו שם יראה בלבו."],[1,"וסימנא דא את וכו':","וסימן זה, אות \u0003פ'\u0004 הכלולה באות \u0003ר'\u0004 ואינה כלולה באות \u0003ס',\u0004 זה הוא נראה שהוא צדיק. ואינו ירא חטא. ולא צריכים להשתדל אחריו, מפני שכל דבריו הם בפה ולא בגוף."],[2,"שפוון עתיקין בעתיקו וכו':","שפתים נובלות וצומקות, ואינן קטנות. זהו אדם בעל כעס ביותר. בעל זדונות. אינו יכול לסבול דבר. בעל לשון הרע בגלוי לכל בלא בושה. לפעמים עוסק בלצנות. זה הוא אדם שצריכים להתרחק ממנו. \u0003עתיקין,\u0004 פירשו נובלות. כי על בלה, מתרגם עתק (איכה ג' ד')."],[3,"אתמלי דיקניה בשערא וכו':","אם נתמלא זקנו בשער: ההוא לשון הרע, יורה עליו שמדבר בגלוי לכל, אין לו בושה. עוסק במחלוקת. מצליח בדברי העולם. רואה בשונאיו. זה הוא קורץ בעיניו. על זה נאמר, העז איש רשע בפניו. זה הוא בסוד אות \u0003פ'\u0004 בלבד, שאינה נכללת באות \u0003ס'\u0004 כלל. ולפעמים מתחברת באות \u0003ר',\u0004 ובאות \u0003ר'\u0004 הזו היא נכללת."],[4,"ברזא דאודנין וכו':","בסוד האזנים. מי שאזניו גדולות, הוא אויל בלבו ושגעון ברוחו. מי שאזניו קטנות, ועומדות על קיומן כראוי, בהתעוררותו הוא חכם לב. רוצה לעסוק בכל. וזה סוד אות \u0003י'\u0004 הנכללת בכל שאר האותיות."],[5,"עד הכא רזין וכו':","עד כאן סוד הצורות של האדם. מכאן ולהלאה סודות אחרים באותיות של אדוני, דר' שמעון, שאינם עומדות תוך הפרצוף. אלא לדעת הסודות של פסוק הזה, זה ספר, בתוך מדרגות עליונות, בזמנים ותקופות של עולם הזה, ועוד לא זכינו בהם."],[6,"אמר ר' שמעון וכו':","אר\"ש, בני, אשריכם בעולם הזה ובעולם הבא. ואשרי עיני שזכו לראות זה, כשאני נכנס לעולם הבא. בשביל נשמתי, אני קורא לעתיק יומין מקרא הזה, תערוך לפני שלחן וגו'. והקב\"ה קורא עלינו, פתחו שערים ויבוא גוי צדיק שומר אמונים."],[7,"אוף אינון פתחו וכו':","אף הם פתחו ואמרו, כתוב, וידי אדם מתחת כנפיהם. מקרא זה העמידוהו החברים, שהם ידים לקבל בעלי תשובה השבים אל הקב\"ה. אבל ידי אדם, אלו הם צורות וסודות עליונים ששם הקב\"ה באדם, וסידר אותם באצבעות מבחוץ ומבפנים, \u0003ובכף\u0004 ההוא. דהיינו בכף היד."],[8,"וקב\"ה כד ברא וכו':","והקב\"ה, כשברא את האדם, סידר בו כל הצורות של סודות העליונים של עולם העליון, שהוא בינה, וכל הצורות של הסודות התחתונים של עולם התחתון, שהוא מלכות. וכולם נחקקים באדם, הנמצא בצלם אלקים, משום שנקרא, יציר \u0003כף,\u0004 דהיינו יציר \u0003כפו\u0004 של הקב\"ה."],[9,"ורזא דכף דאת וכו':","וסוד הכף, הוא של אות הזו הנקראת כף. שכתוב, ויברא אלקים את האדם בצלמו, זהו סוד של אות כף. אות זו יש בה סודות עליונים וצורות עליונות. בכף הזו, היינו בכף היד, תלוים עשרה מאמרות מימין ומשמאל, חמשה בכף ימין וחמשה בכף שמאל, והם אחד בסוד אחד. שהימין והשמאל מתיחדים לאחד."],[10,"תנינן, כתיב וכו':","למדנו, כתוב, וגם אני אכה כפי אל כפי. פירושו, שתהיינה זו עם זו במחלוקת, ותסתלקנה הברכות מעולם, משום שגאות ישראל ניתנה לעכו\"ם. כי מיחוד ימין ושמאל נמשכות משמאל ג\"ר לישראל, שהן גאותם, וכשהם במחלוקת, יונקים העכו\"ם מקו שמאל, וגאות ישראל ניתנה לעכו\"ם. כשמתחברים יחד, כתוב, כף אחת עשרה זהב מלאה קטורת, שזה רמז לחיבור אחד. דהיינו שהעשרה שמימין ושמאל נעשו כף אחת. וכשהם בחבור אחד, כתוב, ויברא אלקים את האדם בצלמו וגו'. \u0003ויברא\u0004 אלקים, הוא הסתלקות המחשבה בסוד הפנימית. פירוש. שתחלת הכל צריכים להמתיק המלכות בבינה, שהוא מדת הרחמים דהיינו ע\"י עלית המלכות לבינה, הנקראת מחשבה. ואז נסתלקו הג\"ר של המחשבה, שהן הפנימית שלה, (כנ\"ל בהקדמת ספר הזהר דף י\"ד אות י\"ג בסולם ע\"ש כל ההמשך) ונשארה בו\"ק שהן חצי מדרגה. ופעולה זו מכונה ברא או ויברא, שהיא לשון מיעוט. ולולא מיעוט הזה לא היה האדם ראוי לקבל מוחין. (כנ\"ל ב\"א דף ז' ד\"ה וכבר ע\"ש) \u0003את האדם,\u0004 ה\"ס דכר ונוקבא ביחד. כי \u0003את\u0004 היא נוקבא ואדם הוא דכר. \u0003בצלם אלקים,\u0004 ה\"ס כף. דהיינו ב' הכפות ימין ושמאל בעת שנעשו כף אחת, שאז יוצא מהן כל המוחין העליונים."]],[]],[["כַּד אִתְבְּרֵי אָדָם, מַה כְּתִיב, בֵּיהּ, (איוב י׳:י״א) עוֹר (בראשית כ' ע\"ב) וּבָשָׂר תַּלְבִּישֵׁנִי וְגוֹ'. אִי הָכִי הָאָדָם מַהוּ. אִי תֵּימָא, דְּאֵינוֹ אֶלָּא עוֹר וּבָשָׂר וְעַצָמוֹת וְגִידִים, לָאו הָכִי, דְּהָא וַדַּאי הָאָדָם לָאו אִיהוּ אֶלָּא נִשְׁמְתָא. וְאִלֵּין דְּקָאָמַר עוֹר וּבָשָׂר עַצָמוֹת וְגִידִים, כֻּלְּהוּ לָא הֲווֹ אֶלָּא מַלְבּוּשָׁא בִּלְחוֹדוֹי, מָאנִין אִינּוּן דְּבַר נָשׁ, וְלָאו אִינּוּן אָדָם. וְכַד הַאי אָדָם אִסְתַּלָּק, אִתְפָּשַׁט מֵאִנּוּן מָאנִין דְּקָא לְבִישׁ.","עוֹר דְּאִתְלְבַּשׁ בֵּיהּ בַּר נָשׁ. וְכָל אִינּוּן עַצְמוֹת וְגִידִים, כֻּלְּהוּ בְּרָזָא דְּחָכְמְתָא עִלָּאָה כְּגַוְונָא דִּלְעֵילָּא. עוֹר כְּגַוְונָא דִּלְעֵילָּא, כְּמָה דְּאוֹלִיף מֹר, בְּאִינּוּן יְרִיעוֹת, דִּכְתִּיב, (תהילים ק״ד:ב׳) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. (שמות כ״ה:ה׳) עוֹרוֹת אֵלִים מְאָדָּמִים וְעוֹרוֹת תְּחָשִׁים. אִינּוּן מַלְבּוּשִׁין דִּלְעֵילָּא, דִּמְסַכְּכֵי לְמַלְבּוּשָׁא, אִתְפַּשָּׁטוּתָא דְּשָׁמַיִם, דְּאִיהוּ מַלְבּוּשָׁא דִּלְבַר. יְרִיעוֹת אִינּוּן מַלְבּוּשָׁא דִּלְגוֹ, וְאִיהוּ קְרוּמָא דְּסָכִיךְ עַל בִּשְׂרָא.","עַצְמוֹת וְגִידִים, אִינּוּן רְתִיכִין, וְכָל אִינּוּן חַיָּילִין, דְּקַיְימִין לְגוֹ. וְכֻלְּהוּ מַלְבּוּשִׁין לִפְנִימָאָה, רָזָא דְּאָדָם עִילָּאָה, דְּאִיהוּ פְּנִימָאָה.","אוּף הָכִי רָזָא לְתַתָּא, אָדָם אִיהוּ פְּנִימָאָה לְגוֹ. מַלְבּוּשִׁין דִּילֵיהּ כְּגַוְונָא דִּלְעֵילָּא. עַצְמוֹת וְגִידִין, כְּגַוְונָא דְּקָאמְרָן בְּאִינּוּן רְתִיכִין וּמַשִׁירְיָין. בָּשָׂר אִיהוּ סָכִיךְ עַל אִינּוּן מַשִׁירְיָין וּרְתִיכִין, וְקַיְּימָא לְבַר, וְדָא (ויקרא ק\"ע ע\"א) רָזָא דְּאִתְמַשְּׁכָא לְסִטְרָא אַחֲרָא. עוֹר דְּסָכִיךְ עַל כֹּלָּא, דָּא אִיהוּ כְּגַוְונָא דְּאִינּוּן רְקִיעִין, דְּסָכִיכוּ עַל כֹּלָּא. וְכֻלְּהוּ מַלְבּוּשִׁין לְאִתְלַבְּשָׁא בְּהוּ. פְּנִימָאָה דִּלְגוֹ רָזָא דְּאָדָם. וְכֹלָּא רָזָא, לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. וְעַל דָּא וַיִּבְרָא אֱלקִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹקִים, (תרי אלהים הכא חד כלפי דכר וחד כלפי נוקבא) וְרָזָא דְּאָדָם לְתַתָּא כֹּלָּא אִיהוּ בְּרָזָא דִּלְעֵילָּא.","בְּהַאי רְקִיעָא דִּלְעֵילָּא, דִּמְסַכֵּךְ עַל כֹּלָּא, אִתְרְשִׁימוּ בֵּיהּ רְשִׁימִין, לְאִתְחֲזָאָה וּלְמִנְדַּע בְּאִינּוּן רְשִׁימִין, דְּאִתְקְבִיעוּ בֵּיהּ מִלִּין וְרָזִין סְתִימִין. וְאִינּוּן רְשִׁימִין דְּכֹּכָבַיָּא וּמַזָּלֵי, דְּאִתְרְשִׁימוּ וְאִתְקְבִיעוּ בְּהַאי רְקִיעָא, דְּסָכִיךְ לְבַר. אוּף הָכִי עוֹר, דְּאִיהוּ סִכּוּכָא לְבַר בְּבַר נָשׁ, דְּאִיהוּ רְקִיעָא דְּסָכִיךְ עַל כֹּלָּא, אִית בֵּיהּ רְשִׁימִין וְשִׂרְטוּטִין, וְאִינּוּן כֹּכָבַיָּא וּמַזָּלֵי דְּהַאי עוֹר. לְאִתְחֲזָאָה בְּהוּ, וּלְמִנְדַּע בְּהוּ, מִלִּין וְרָזִין סְתִימִין, בְּכֹכָבַיָּא וּמַזְלַיא, לְעַיְּינָא בְּהוּ חַכִּימֵי לִבָּא, וּלְאִסְתַּכְּלָא בְּהוּ לְמִנְדַּע אִסְתַּכְּלוּתָא בְּאַנְפִּין, בְּרָזִין דְּקָאָמַרָן, וְרָזָא דָּא, (ישעיהו מ״ז:י״ג) הוֹבְרֵי שָׁמַיִם הַחוֹזִים בַּכֹּכָבִים.","וְדָא אִיהוּ, כַּד אִינּוּן נְהִירִין וְקַיְימִין, בְּלא רוּגְזָא. בְּזִמְנָא דְּרוּגְזָא שַׁלְטָא עָלֵיהּ דְּבַר נָשׁ, דִּינָא אַחֲרָא אִתְמְסַר לְמִנְדַּע בֵּיהּ. בְּמָה דְּלָא אִתְיְיהִיב לְשַׁלְּטָאָה, לְמִנְדַּע בְּזִמְנָא דְעֵינָא (נ\"א דדינא) שַׁלְטָא בִּרְקִיעָא.","אֲבָל אִסְתַּכְּלוּתָא דְּאַנְפִּין עַל אָרַח קְשׁוֹט, בְּשַׁעֲתָא דְּאַנְפִּין נְהִירִין, וְקַיְּימָא בַּר נָשׁ עַל קִיּוּמָא, וְאִינּוּן רְשִׁימִין אִתְחָזוּן בְּאֹרַח קְשׁוֹט, דִּכְדֵין בְּהַהוּא אִסְתַּכְּלוּתָא יָכִיל לְאִתְּדָּנָא עַל בּוּרְיֵיהּ יַתִּיר, וְאַף עַל גַּב דִּבְכֹלָּא כָּל אִינּוּן חַכִּימִין יַכְלִין לְאִסְתַּכְּלָא.","שִׂרְטוּטֵי יְדִין וְשִׂרְטוּטֵי אֶצְבְּעָן, לְגוֹ, כֻּלְּהוּ קַיְימִין בְּרָזִין אַחֲרָנִין, לְמִנְדַּע בְּמִלִּין סְתִימִין. וְאִלֵּין אִינּוּן כֹּכָבַיָּא, דִּנְהִירִין לְאִסְתַּכְּלָא גּוֹ מַזָּלֵי, בִּטְסִירִין עִלָּאִין.","אֶצְבְּעָן קַיְימֵי בְּרָזִין עִלָּאִין. טוּפְרֵי אֶצְבְּעָאן, דְּקַיְימִין דְּחַפְיָן, לְבַר, הוּא אוּקְמוּהָ בְּאִינּוּן רָזִין, דַּהֲווֹ (בראשית כ\"א ע\"א) פָּנִים דִּלְבַר, וּבְהוּ אִית רָזִין, לְאִינוּן חֲרָשִׁין, דְּמִסְתַּכְלֵי בְּטוּפְרֵי, בִּנְהִירוּ דְּמִלָּה אַחֲרָא, דְּשַׁלְטָא בְּהוּ, וְאִינּוּן חֲרָשִׁין קָא מְסָאֲבֵי לְהַהוּא אֲתָר.","בְּטוּפְרִין אִית זִמְנִין, דְּנַהֲרִין בְּהוּ כֹּכָבִין חִוָּורִין דְּקִיקִין, וְאִלֵּין אִינּוּן כְּתוֹלְדָה דִּטְלוּפְחִין, וְאִינּוּן שְׁקִיעִין כְּהַאי מַסְמְרָא עַל לוּחָא. וְלָאו אִינּוּן כְּאִינּוּן חִוָּורִן אַחֲרָנִין דְּלָא שְׁקִיעִין, אֶלָּא דְּקַיְימִין לְעֵילָּא. בְּהָנִי דְּלָא שְׁקִיעִין, לֵית בְּהוּ מַמָּשָׁא. אֲבָל הָנִי דִּשְׁקִיעִין חִוָּורִין כְּתוֹלְדָה דִּטְלוּפְחִין אִית בְּהוּ מַמָּשָׁא, וְאִית סִימָנָא טָבָא לֵיהּ לְבַר נָשׁ בְּחֵדוּ (נ\"א בהו') וְיַצְלַח בְּהַהוּא זִמְנָא. אוֹ גְּזֵרָה אִתְגְּזַר עָלֵּיהּ וְאִשְׁתֵּזִיב מִינָהּ."],[[0,"כד אתברי אדם וכו':","כשנברא האדם מה כתוב בו, עור ובשר תלבישני וגו'. ושואל, אם כן, מהו האדם עצמו. ומשיב, אם תאמר שהאדם אינו אלא עור ובשר ועצמות וגידים, אינו כן, כי ודאי, האדם אינו אלא הנשמה, ואלו שאומר, עור ובשר עצמות וגידים, כולם אינם אלא מלבוש בלבד. הם כלים של האדם, ולא האדם עצמו. וכשהאדם נפטר הוא מתפשט מאלו הכלים שלבש."],[1,"עור דאתלבש ביה וכו':","העור שהאדם מתלבש בו, וכל אלו עצמות וגידים כולם הם בסוד החכמה העליונה כעין של מעלה. ומפרש. עור כעין של מעלה, הוא כמו שלמדנו באלו היריעות, שכתוב נוטה שמים כיריעה. עורות אלים מאדמים ועורות תחשים, הם מלבושים שלמעלה המסככים על המלבוש שהוא התפשטות השמים שהוא המלבוש שמבחוץ יריעות הן המלבוש שמבפנים, והוא קרום הסוכך על הבשר. וע\"כ נאמר נוטה שמים כיריעה. שיריעות הן לבוש הפנימי ועליהן השמים מבחוץ."],[2,"עצמות וגידין וכו':","עצמות וגידין הם המרכבות וכל אלו הצבאות העומדים בפנימיות. כלומר, שהם בחינת הפנימיות והג\"ר של חיצוניות המדרגה, כי גידים הם נשמה של המלבוש, והעצמות הם בחינת חיה של המלבוש. וכולם הם מלבושים לפנימי, שהוא סוד אדם העליון, שהוא פנימית להם."],[3,"אוף הכי רזא וכו':","אף כן הסוד למטה. האדם הוא פנימי בפנים, המלבושים שלו הם כעין של מעלה, עצמות וגידים הם כעין שאמרנו באלו המרכבות והצבאות שנקראים עצמות וגידים. בשר הוא סוכך על אלו המחנות והמרכבות הנקראים עצמות וגידים ועומד מבחוץ להם. וזה סוד שהבשר נמשך ממנו לצד האחר. (כמ\"ש פרשת נח דף מ\"ח ד\"ה ת\"ח) עור הסוכך על כל, זה הוא כעין אלו הרקיעים הסוככים על כל. וכולם מלבושים להתלבש בהם, הפנימי שבתוכם הוא סוד האדם.והכל הוא סוד, שלמטה הוא כעין שלמעלה. וע\"כ אוה\"כ, ויברא אלקים את האדם בצלמו בצלם אלקים, כי הסוד של אדם למטה, הוא כולו בסוד שלמעלה."],[4,"בהאי רקיעא דלעילא וכו':","ברקיע הזה שלמעלה הסוכך על כל, נרשמו בו רשימות להראות ולדעת באלו הרשימות שנקבעו בו דברים וסודות סתומים, והם הרשימות של כוכבים ומזלות שנרשמו ונקבעו ברקיע הזה הסוכך מבחוץ. אף כן, העור שהוא סוכך מבחוץ באדם, שהוא כמו הרקיע הסוכך על כל, יש בו רשימות וקוים, והם בחינת כוכבים ומזלות של עור הזה, להראות בהם, ולדעת בהם דברים וסודות סתומים בכוכבים ומזלות, שהם הרשימות והקוין שבעור שיעיינו בהם חכמי לב, ולהסתכל בהם לדעת הסתכלות בפנים בסודות שאמרנו. וז\"ס הוברי שמים החוזים בכוכבים."],[5,"ודא איהו כד וכו':","וזה הוא כשהפנים מאירים ועומדים בלי רוגז. אז אפשר להסתכל ולדעת כנ\"ל, בזמן שהרוגז שולט על האדם, דין אחר נמסר לדעת בו, ולמה לא ניתן לשלוט על האדם. זה אפשר לדעת בזמן שהדין שולט ברקיע."],[6,"אבל אסתכלותא וכו':","אבל הסתכלות הפנים בדרך אמת, הוא בשעה שהפנים מאירים והאדם עומד על קיומו, ואז, אלו הרשימות נראים בדרך אמת, כי אז בהסתכלות ההיא יכול לדון יותר על בירורו. ואף על פי שבכל האפנים יכולים כל אלו החכמים להסתכל."],[7,"שרטוטי ידין ושרטוטי אצבען וכו':","קוי הידים וקוי האצבעות, מבפנים.כולם עומדים בסודות אחרים לדעת בדברים סתומים. ואלו הם ככבים המאירים להסתכל בתוך המזלות, בממונים העליונים."],[8,"אצבען קיימי ברזין וכו':","האצבעות עומדות בסודות עליונים. הצפרנים של האצבעות העומדים ומכסים עליהם הם מבחוץ. והעמידוהו באלו הסודות, שהם פנים שמבחוץ. (כמ\"ש לעיל בראשית א' אות קכ\"ט וע\"ש בסולם) ובהם יש סודות לאלו המכשפים המסתכלים בצפרנים, באור של דבר אחר השולט בהם, ואלו המכשפים מטמאים למקום ההוא."],[9,"בטופרין אית זמנין וכו':","בצפרנים יש זמנים שמאירים בהם ככבים לבנים קטנים, כלומר, שנראות נקודות לבנות בצפרנים ואלו הם כתולדה של עדשים, והם שקועים בצפרנים, כמסמר הזה על הלוח. והם אינם כאלו נקודות לבנות אחרות שאינם שקועות, אלא עומדות למעלה על הצפרנים, באלו שאינן שקועות אין בהם ממש, אבל אלו השקועות ולבנים כתולדה של עדשים, יש בהם ממש, וסימן טוב יש לאדם בהם, ויצליח בזמן ההוא. או גזרה נגזר עליו ונצול ממנה."]],[]],[["שִׂרְטוּטֵי יְדִין בְּרָזִין עִלָּאִין, (שרטוטין) בְּאֶצְבְּעָן לְגוֹ. בְּיָדִין שִׂרְטוּטִין רַבְרְבִין, שִׂרְטוּטִין זְעִירִין דְּקִיקִין עִלָּאִין בִּימִינָא. בְּאִינּוּן אֶצְבְּעָן דִּבְהוּ שִׂרְטוּטִין זְעִירִין. בְּאֶצְבְּעָא זְעֵירָא דִּימִינָא, אִית רְשִׁימִין דְּקִיקִין. אֶצְבְּעָא דָּא, קַיְּימָא תָּדִיר עַל עוֹבָדִין דְּבִסְטַר אַחֲרָא.","בְּהַאי אֶצְבְּעָא קַיְימִין שִׂרְטוּטִין, אִינּוּן דְּאֶצְבְּעָא אִתְכְּפִיל בְּהוּ. הָנֵי לָאו אִינּוּן לְאִסְתַּכְּלָא, אֶלָּא אִי אִתּוֹסְפָן בֵּיהּ. אִי אִתּוֹסְפָן תְּרֵין אוֹחֳרָנִין, עַל הַהוּא שִׂרְטוּטָא דְּאִתְכְּפַל בְּהוּ. אָרְחָא לָא אִזְדָּמַן לֵיהּ. וְאִי יַעֲבֹד לָא יִצְלַח.","בַּר אִי קַיְימָן בְּאַרְכָּא, בֵּין רְשִׁימָא לִרְשִׁימָא, בְּזִמְנָא דְּיִתְמְשַׁךְ מַשְׁכָא לַאֲחוֹרָא, וְאִשְׁתָּאָרוּ אִינּוּן רְשִׁימִין דְּאִשְׁתְּמוֹדְעָן. הַאי יִצְלַח בְּאָרְחָא. וְסִימָן דָּא, תְּלַת תְּלַת בְּפוּתְיָא. וְאַרְבַּע בְּאַרְכָּא. וְרָזָא דָּא ז' מֵאַתְוָון זְעִירִין.","רְשִׁימָא חַד בְּאַרְכָּא, וּתְרֵין תְּרֵין בְּפוּתְיָא. מֵאָרְחָא, יִשְׁמַע מִלִּין בִּזְמַן קָרִיב, וְלֵית לֵיהּ בְּהוּ תּוֹעַלְתָּא. אַרְבַּע רְשִׁימִין בְּאַרְכָּא, וְד' רְשִׁימִין בְּפוּתְיָא, אָרְחָא אִזְדָּמַן לֵיהּ בְּטֹרַח סַגִּי, וּלְסוֹפָא לְתוֹעַלְתָּיה. וְרָזָא דָּא ז' מֵאַתְוָון אֶמְצָעִיִּין, דְּבֵין זְעִירִין וְרַבְרְבִין.","חָמֵשׁ זְעִירִין רְשִׁימִין בְּפוּתְיָא לְתַתָּא, וְאַרְבַּע בְּפוּתְיָא לְעֵילָּא, וְאַרְבַּע בְּאַרְכָּא. נַיְיחָא לֵיהּ בְּבֵיתֵיהּ, וְעַצְלָא אִיהוּ. וְאָרְחָא הֲוַת מְתַּתְקְנָא קָמֵיהּ, וְלָא בָּעֵי לְמֶעְבַּד. וְאִי יַעֲבֹד, יִצְלַח בְּהַהוּא אָרְחָא, אֲבָל לָא עָבִיד לֵיהּ, וְעַצְלָא הֲוֵי וְרָזָא דָּא ז' דְּאִיהִי פְּשׁוּטָה.","בְּאֶצְבְּעָא דְּאֶמְצָעִיתָא, הַאי אֶצְבְּעָא קַיְּימָא, לְמֶעְבַּד עוֹבָדָא הַהוּא דְּחָשִׁיב. אִי שִׂרְטוּטָא חֲדָא קַיְּימָא בְּאַרְכָּא, בֵּין שִׂרְטוּטֵי דְּפוּתְיָא, הַאי חָשַׁב מַחֲשָׁבִין, וְאִסְתַּלְּקָן מִנֵּיהּ, וְדָחִיל וְלָא עָבִיד, וְהַהִיא מַחֲשָׁבָה לָא אִתְעָבִיד כְּלָל.","אִי תְּרֵין שִׂרְטוּטִין בְּאַרְכָּא, דְּקַיְימִין כַּד אִתְפָּשַׁט מַשְׁכָא לַאֲחוֹרָא. הַאי לָאו בֵּיהּ מַחֲשָׁבִין, וְחָשִׁיב מַחֲשָׁבִין לְפוּם שַׁעֲתָא, וְאִתְעָבִיד, וְלָא מַחֲשָׁבָה דְּהִרְהֵר בֵּיהּ כְּלָל, אֶלָּא מַחֲשָׁבָה דְּאִיהוּ בִּבְהִילוּ וּזְעִירָא, אֲבָל הִרְהוּרָא וּמַחֲשָׁבָה לָא.","וְאִי תְּלַת רְשִׁימִין בְּאַרְכָּא. וּבְפוּתְיָא תְּרֵין אוֹ תְּלַת, כַּד אִתְפָּשַׁט מַשְׁכָא לַאֲחוֹרָא. הַאי אִיהוּ בַּר נָשׁ דְּאִיהוּ פְּקִיחָא, וְחָשִׁיב מַחֲשָׁבִין, וְכָל אִינּוּן מַחֲשָׁבִין דְּאִינּוּן לִסְטַר קוּדְשָׁא בְּרִיךְ הוּא אִתְקַיְּימָן בִּידֵיהּ, וּמַחֲשָׁבִין אַחֲרָנִין לָאו הָכִי.","אִי אַרְבַּע אוֹ חֲמִשָּׁה בְּאַרְכָּא, בְּאִתְפְּשָׁטוּ דְּמַשְׁכָא כִּדְקָאמְרַן, (דא איהו) כַּד שָׁרָאן עַל פּוּתְיָא, בִּתְלַת, אוֹ בְּאַרְבַּע, אוֹ מִתְּרֵין וּלְהָלְאָה. דָּא בַּר נָשׁ דְּמַחֲשָׁבוֹי לְאַבְאָשָׁא, וְאִשְׁתָּבַח בְּהוּ. וְדִיקְנִה וּגְבִינֵי עֵינוֹי סוּמָקִין, מְחַשֵּׁב לְבִישׁ וְאִשְׁתָּבַּח בְּהוּ. קִצְרָא דְּיוֹמִין אִיהוּ. פְּקִיחָא אִיהוּ. וְאַכְנַע תָּדִיר לִמְכִילָן דְּבִישׁ. אַצְלַח. וּלְסוֹפָא דְּיוֹמִין זְעִירִין אִסְתַּלָּק מֵעָלְמָא.","אַסְוָותָא לְהַאי תִּיּוּבְתָּא. כְּדֵין אִשְׁתְּכָחוּ תְּלַת רְשִׁימִין, אוֹ אַרְבַּע, וְשַׁרְיָין עַל תְּרֵין. תְּלַת רְשִׁימִין אוֹ ד' בְּאַרְכָּא וְשַׁרְיָין עַל תְּרֵין בְּפוּתְיָא. דְּהָא כְּפוּם מִנְהֲגָא דְּבַר נָשׁ, הָכִי מִתְחַלְּפֵי שִׂרְטוּטִין, מִזְּמַן לִזְמַן. וְרָזָא דָּא (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפַּר צְבָאָם וְגוֹ', מֵרֹב אוֹנִים וְאַמִּיץ כֹּחַ וְגוֹ'.","כְּמָה דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְלָף חַיָּילִין וּזְמָנִין בְּכֹכְבֵי שְׁמַיָא, יוֹמָא דָּא כָּךְ, וּלְיוֹמָא אַחֲרָא כַּךְ. (ודא איהו דאמרינן בצלותא דערבית ומחליף את הזמנים ומסדר את הכוכבים כפום דחלופא דזמנים כך איהו מסדר כוכבים.) כְּפוּם דְּאָדָם דִּלְגוֹ כָּל עוֹבָדוֹי. הָכִי אִתְחָזוּן בְּהַאי רְקִיעָא. וְהָכִי אִתְחָזֵי בְּהַאי מַשְׁכָא דְּהַאי אָדָם תַּתָּאָה. דְּאִיהוּ רְקִיעָא, עוֹר דְּחַפְיָא עַל כֹּלָּא.","וְכֹלָּא כְּפוּם גַּוְונָא דְּאָדָם דִּלְגוֹ, דְּהַאי לְזִמְנִין קָאִים בְּדִינָא, לְזִמְנִין בְּרַחֲמֵי, כְּהַהוּא גַּוְונָא מַמָּשׁ אַחְזֵי לְבַר. לְזִמְנִין כְּהַאי גַּוְונָא, וּלְזִמְנִין כְּהַאי גַּוְונָא כְּגַוְונָא דָּא לְתַתָּא בְּהַאי אָדָם, כְּמָה דְּאַמָרָן, לְזִמְנִין כְּהַאי גַּוְונָא, וּלְזִמְנִין כְּהַאי גַּוְונָא, וְרָזָא דָּא אָת ז' אִתְכְּלִיל בֵּיהּ אָת י'."],[[0,"שרטוטי ידין ברזין וכו':","קוי היד בסודות עליונים, ובאצבעות מבפנים, שלא לצד הצפרנים אלא לצד הבשר. בידים יש קוים גדולים וקוים קטנים ודקים עליונים בימין. ובאלו האצבעות שבהם קוין קטנים. באצבע קטנה שבימין יש רשימות דקות, אצבע זה עומד תמיד על מעשים שבצד האחר."],[1,"בהאי אצבעא קיימין וכו':","באצבע הזה נמצאים קוים, אלו שהאצבע מתכפל עליהם בשעת סגירת היד, אלו אינם להסתכל בהם, אלא אם נוספים עוד קוים. אם נוספו ב' קוין אחרים על קו ההוא שהאצבע מתכפל עליו. לא יזדמן לו דרך. ואם עושה אינו מצליח."],[2,"בר אי קיימן וכו':","חוץ אם הקוים עומדים באורך בין רשימה לרשימה, דהיינו בין הרשימות שהאצבע מתכפל עליהם, בזמן שימשוך עור האצבע לאחור, ועם כל זה, ישארו אלו הרשימות הנודעות, ולא יתבטלו מחמת משיכת העור. זה יצלח בדרך. וסימן זה הוא, ג' ג' קוים ברוחב, וארבעה באורך. וסוד זה הוא \u0003ז'\u0004 מאותיות הקטנות. כי יש ג' מיני אלפא ביתות, גדולות בינונות וקטנות. וה \u0003ז'\u0004 שבכאן שייך לא\"ב דאותיות הקטנות."],[3,"רשימא חד בארכא וכו':","אם רשימה אחת הוא באורך וב' ב' ברוחב. מן הדרך, ישמע דברים בזמן קרוב, ואין בהם תועלת. אם ד' רשימות באורך וד' רשימות ברוחב, דרך יזדמן לו ביגיעה מרובה, ולבסוף יהיה לתועלתו. וסוד זה \u0003ז'\u0004 מאותיות א\"ב בינונות שבין א\"ב גדולות ובין א\"ב קטנות."],[4,"חמש זעירין רשימין וכו':","חמש רשימות קטנות ברוחב למטה, וארבע ברוחב למעלה, וארבע באורך. יש לו מנוחה בביתו. והוא עצל. דרך היה מתתקן לפניו ולא רצה לעשות. ואם יעשה יצלח בדרך הזה, אבל לא יעשה אותו שהוא עצל. וסוד זה הוא \u0003ז'\u0004 שהיא קטנה."],[5,"באצבעא דאמצעיתא וכו':","באצבע האמצעי: אצבע הזו עומדת להראות אם לעשות מעשה ההוא שחשב. אם קו אחד עומד באורך בין הקוין שברוחב. זה חושב מחשבות ומסתלקות ממנו, וירא ואינו עושה אותם, ומחשבה ההיא אינה נעשית כלל."],[6,"אי תרין שרטוטין וכו':","אם ב' קוים באורך, העומדים אפילו, כשמושכים עור האצבע לאחור, ואינם מתבטלים מחמת משיכת העור. זה אין בו מחשבות, שחושב מחשבות לפי שעה, ונעשות, אבל לא מחשבה שמעיין בה, אלא מחשבה שהיא במהירות וקטנה, אבל מחשבה בעיון אין בו."],[7,"ואי תלת רשימין וכו':","ואם ג' רשימות באורך, וברוחב ב' או ג', לאחר שמתפשט עור האצבע לאחור. זה הוא אדם שהוא חכם וחושב מחשבות, וכל אלו מחשבות שהן לצד הקב\"ה מתקיימים בידו, ומחשבות אחרות אינן כן."],[8,"אי ארבע או וכו':","אם ארבע או חמשה רשימות באורך, אחר התפשטות עור האצבע כמו שאמרנו, כששורים על הרשימות שברוחב על ג' או ד' או מב' והלאה. זה אדם שמחשבותיו הן להרע, ומשתבח בהן. והזקן וגבות עיניו אדומים, חושב רע ומשתבח בו קצר ימים הוא. חכם הוא. ונכנע תמיד למדות הרעות. מצליח. ולסוף ימים מועטים מסתלק מן העולם."],[9,"אסוותא להאי תיובתא וכו':","הרפואה לזה, היא תשובה. ואז נמצאות ג' רשימות או ארבע השורות על שתים, דהיינו ג' רשימות או ד' באורך ושורות על ב' שברוחב. כי לפי מנהגו של אדם כן מתחלפות הרשימות מזמן לזמן. וסוד זה, המוציא במספר צבאם וגו' מרב אונים ואמיץ כח וגו'."],[10,"כמה דקב\"ה אחלף וכו':","כמו שהקב\"ה מחליף צבאות וזמנים בככבי השמים, יום זה כך וליום אחר כך, שכפי האדם העליון שבפנימיות כל מעשיו, וכן הם נראים ברקיע הזה, כן נראה בעור הזה של אדם הזה התחתון, שהעור שלו המכסה על כל, הוא רקיע."],[11,"דכלא כפום גוונא וכו':","והכל כפי עין האדם שבפנימיות, שזה, לפעמים עומד בדין ולפעמים ברחמים, כעין זה ממש מראה מבחוץ על הרקיע, לפעמים כאפן הזה ולפעמים כאפן הזה. כעין זה למטה באדם הזה כמו שאמרנו שלפעמים, נראה על העור כאפן הזה ולפעמים כאפן הזה. וסוד זה הוא אות \u0003ז'\u0004 שנכלל בו אות \u0003י'.\u0004"]],[]],[["וְרָזִין אִלֵּין בְּאֶצְבְּעָן דִּימִינָא, בִּזְעֵירָא וּבְרַבְרְבָא. וְסִימָן (דברים א׳:י״ז) כַּקָּטֹן כַּגָּדוֹל תִּשְׁמָעוּן. אֵלּוּ תְּרֵין אֶצְבְּעָן בְּרָזִין אִלֵּין, וְהָכִי אִינּוּן בְּרָזִין דְּאוֹלִיפְנָא מִנֵּיהּ דְּמֹר, (ולא אינון) בְּרָזֵי דְּרַב יֵיסָא סָבָא. מִכָּאן וּלְהָלְאָה שִׂרְטוּטִין אַחֲרָנִין, דְּאִקְרוּן כֻּלְּהוּ תוֹלְדוֹת, וְאִינּוּן תוֹלְדוֹת אָדָם, כְּמָה דִּכְתִּיב, (בראשית ב׳:ד׳) תוֹלְדוֹת הַשָּׁמַיִם, וְהָא אִתְּמַר, דְּכֹלָּא רָזָא דָּא. כְּגַוְונָא דָּא תוֹלְדוֹת אָדָם, בְּכָל אִינּוּן דִּיּוּקְנִין דְּאַנְפִּין, וּבְכָל אִינּוּן דְּקָאָמַרָן. וּבְאִלֵּין תוֹלְדוֹת דְּשִׂרְטוּטֵי יְדִין, דְּאִתְחַזְיָין בְּרָזִין פְּנִימָאִין, כְּמָה דְּאִתְחָזֵי.","זֶה סֵפֶר תוֹלְדוֹת אָדָם, לְשִׂרְטוּטִין, סִימָן זר\"ה פס\"ץ. רָזִין לְחַכִּימֵי לִבָּא, רזהס\"ף, חָמֵשׁ אַתְוָון, בְּחָמֵשׁ תַּרְעִין, לְמִנְדַּע חָכְמָה בְּסוּכְלְתָנוּ.","תַּרְעָא קַדְמָאָה, ר'. בִּידָא אִית שִׂרְטוּטִין דְּקִיקִין, וְשִׂרְטוּטִין רַבְרְבִין. וְכֻלְּהוּ מִתְעָרְבֵי דָּא עִם דָּא. שִׂרְטוּטִין רַבְרְבִין דְּאִית בִּידָא, כַּד אִינּוּן תְּרֵין בְּאַרְכָּא, וּתְרֵין בְּפוּתְיָא, וְאָחִידוּ דָּא בְּדָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וּבְרָזָא דְּאָת ר' וְדָחֵי לְאָת ז', וְנָטִיל אִלֵּין תְּרֵין אַתְוָון. בְּפוּתְיָא נָטִיל ה', בְּאַרְכָּא נָטִיל ר', וְסִימָן דִּילֵיהּ ה\"ר.","דָּא אִית לֵיהּ בִּידָא שְׂמָאלָא כְּהַאי גַּוְונָא בְּאִלֵּין שִׂרְטוּטִין רַבְרְבִין. אֲבָל אִינּוּן שִׂרְטוּטִין זְעִירִין דְּנָטְלָא יְמִינָא, לָא נָטְלָא שְׂמָאלָא. דִּימִינָא נָטְלָא, חַד שִׂרְטוּטָא דָּקִיק לְעֵילָּא בְּאַרְכָּא, וְחַד שִׂרְטוּטָא דָּקִיק לְתַתָּא, דְּאָחִיד בֵּין אִינּוּן תְּרֵין שִׂרְטוּטִין רַבְרְבָן. בְּפוּתְיָא אִית חַד שִׂרְטוּטָא דָּקִיק, דְּאָחִיד לְתַתָּא בְּאִינּוּן תְּרֵין דְּשַׁרְיָא עָלֵיהּ. וּבִשְׂמָאלָא לָאו הָכִי, וְרָזָא דִּילֵיהּ אִיהוּ בִּימִינָא, וְלָאו בִּשְׂמָאלָא.","הַאי אִיהוּ בַּר נָשׁ, דִּלְזִמְנִין תָּאִיב בְּבֵיתָא, וּלְזִמְנִין בְּאָרְחָא, דָּא לָא שָׁכִיךְ לִבֵּיהּ בְּהַאי וּבְהַאי. כַּד אִיהוּ בְּבֵיתָא תָּאִיב בְּאָרְחָא, וְכַד אִיהוּ בְּאָרְחָא, תָּאִיב בְּבֵיתָא. אַצְלַח תָּדִיר בְּאָרְחָא, וּלְזִמְנִין בְּבֵיתָא. דָּא אַצְלַח בְּאוֹרַיְיתָא, וּבְרָזֵי דְּאוֹרַיְיתָא אִי אִשְׁתְּדַל בְּהוּ. הַאי חָמֵי בְּשַׂנְאוֹי, תּוֹעַלְתָּא לְסַגִּיאִין בֵּיהּ. עַצְלָא אִיהוּ בְּמִלֵּי דְּעָלְמָא. אִי אִתְּעַר, אִתְּעָרוּן לְאוֹטָבָא לֵיהּ מִלְּעֵילָּא. זָכֵי בְּמִלּוֹי. דָּא אִיהוּ חֲמִידָא וּמְפַזֵּר מָמוֹנָא. טָב עֵינָא אִיהוּ. צְלוֹתֵיהּ אִשְׁתְּמַע. נָחִית וְסָלִיק בְּמָמוֹנָא.","דָּא אִיהוּ דִּלְזִמְנִין מִתְּבַּר לִבֵּיהּ לְגַבֵּיהּ מָארֵיהּ. וּכְדֵין אִשְׁתְּכָחוּ תְּלַת שִׂרְטוּטִין זְעִירִין, דִּמְעַבְּרָן בְּהַהוּא שִׂרְטוּטָא דָּקִיק, דְּאִתּוֹסָף עַל אִינּוּן תְּרֵין דְּפוּתְיָא, וְרָזָא דָּא ה' דְּמִתְחַבְּרָא עם ר'. דָּא אָרְחָא, דָּא בֵּיתָא. דָּא חֶדְוָה, דָּא עֲצִיבוּ, דָּא תּוֹעַלְתָּא, דָּא עַצְלָא, דָּא טָב עֵינָא, דָּא חֲמִידָא, וּמְפַזֵּר מָמוֹנָא. דָּא מִתְּבַּר לִבֵּיהּ, וְתָב לְמָארֵיהּ.","תַּרְעָא תִּנְיָינָא, ז'. בִּימִינָא, בְּקַסְטִירוּ דְּקוֹלְטָא, רְשִׁימִין שְׁכִיחֵי, כַּד אִשְׁתְּכָחוּ תְּלַת שִׂרְטוּטִין רַבְרְבִין בְּפוּתְיָא, וּתְרֵין רַבְרְבִין בְּאַרְכָּא, וְחַד מֵאִינּוּן דְּאָרְכָּא, אָחִיד בְּאִינּוּן תְּרֵין דְּפוּתְיָא, וְחַד אַחֲרָא לָא אָחִיד בְּהוּ. הַאי אִית פַּסְלוּ בְּזַרְעֵיהּ, מִסִּטְרָא דַּאֲבוֹי, אוֹ מִסִּטְרָא דְּאִמֵּיהּ.","וּכְדֵין מִשְׁתַּכְּחֵי לְתַתָּא מֵאִינּוּן תְּלַת שִׂרְטוּטִין דְּפוּתְיָא, תְּרֵין שִׂרְטוּטִין דְּקִיקִין, דַּאֲחִידָן בְּהוּ לְתַתָּא. הַאי אִיהוּ בַּר נָשׁ, מְתַקֵּן עוֹבָדוֹי, קָמֵי בְּנֵי נָשָׁא, וְלִבֵּיהּ לָא קְשׁוֹט. וּלְזִמְנָא דְּסִיב, אַהְדָּר לְאִתְתַּקְנָא. כְּדֵין אִשְׁתְּכָחוּ אִינּוּן תְּרֵין שִׂרְטוּטִין בְּאָרְכָא, אֲחִידָן בְּאִינוּן דְּפוּתְיָא, דָא עִם דָא. וּתְרֵין אַחֲרָנִין עִמְהוֹן בְּאֶמְצָעִיתָא, דְּקִיקִין, וְדָא בְּאַרְכָּא. וּתְלַת דְּקִיקִין בְּפוּתְיָא, וְרָזָא דָּא ז' דְּמִתְחַבְּרָא בְּאָת ר'.","וְכַד אִיהוּ סִיב וְתָב כִּדְקָאמְרַן, אִתְתָּקַּן אִיהוּ בְּרָזָא דְּאָת ר', וְאִתְחֲבָּר בְּאָת ז'. לְבָתַר כַּד הַאי אִתְתָּקַּן, אִיהוּ תָּדִיר בִּלְחִישׁוּ, וְכָל עוֹבָדוֹי בִּלְחִישׁוּ. אֲבָל לָאו אִיהוּ בְּקִיּוּמָא כַּדְקָא חֲזִי בְּגִין דְּהַהוּא פַּסְלוּ, עַד לָא אִתְיָיאָשָׁא בֵּיהּ. (מכאן אוליפנא מאן דפסיל זרעיה עד תלת דרין לא אתייאשא ההוא פסילו (דף ע\"ז ע\"ב) מלכשכשא. בגין כך תנינן ווי ליה לההוא בר נש דפסל זרעיה ולא חייש ליקרא דמאריה. פסיל זרעיה ודאי.)"],[[0,"ורזין אלין באצבען וכו':","וסודות אלו הם באצבעות דיד ימין, באצבע קטנה, ובגדולה, דהיינו אצבע האמצעית, והסימן הוא, כקטן כגדול תשמעון. אלו ב' האצבעות הם בסודות האלו. וכך הם בסודות שלמדנו מאדוני בסודות דרב ייסא סבא. מכאן ולהלאה קוים אחרים הנקראים כולם \u0003תולדות,\u0004 והם תולדות אדם, כמ\"ש תולדות השמים, והרי למדנו, שהכל הוא סוד זה. כעין זה תולדות אדם. בכל אלו הצורות של הפנים, ובכל אלו שאמרנו, ובאלו תולדות של קוי הידים הנראים בסודות פנימיים כמו שראוי."],[1,"זה ספר תולדות אדם:","היינו לקוים. סימן \u0003זר\"ה פס\"ץ,\u0004 שהם אותיות, זה ספר, ונתוסף עליהן צ'. הסודות לחכמי לב. \u0003רזהס\"ף.\u0004 חמש אותיות בחמשה שערים לדעת חכמה בתבונה."],[2,"תרעא קדמאה וכו':","שער הראשון הוא \u0003ר'.\u0004 ביד, יש קוים דקים וקוים גדולים וכולם מתערבים זה עם זה. קוים הגדולים שיש ביד כשהם ב' באורך וב' ברוחב, ונאחזים זה בזה: הוא בסוד אות \u0003ה'\u0004 ובסוד אות \u0003ר',\u0004 ודוחה לאות \u0003ז'\u0004 ולוקח אלו ב' אותיות, ברוחב לוקח \u0003ה'\u0004 ובאורך לוקח \u0003ר'.\u0004 והסימן שלו \u0003ה\"ר.\u0004"],[3,"דא אית ליה וכו':","זה יש לו כעין זה שביד ימין, גם ביד שמאל, באלו קוין הגדולים, אבל אלו קוים הקטנים שלוקח הימין, אינו לוקח השמאל. שהימין לוקח קו אחד דק למעלה באורך, וקו אחד דק למטה הנאחז בין אלו ב' קוים הגדולים אשר שם. ברוחב, יש קו אחד דק הנאחז למטה באלו ב' הקוים השורים עליו. ובשמאל אינו כן והסוד שלו הוא בימין ולא בשמאל."],[4,"האי איהו בר נש וכו':","זה הוא אדם, שלפעמים חושק להיות בבית, ולפעמים בדרך, זה, לא ישקוט לבו בזה ובזה, כשהוא בבית חושק לדרך, וכשהוא בדרך חושק לבית. מצליח תמיד בדרך, ולפעמים גם בבית. זה מצליח בתורה ובסודות התורה אם משתדל בהם. זה רואה בשונאיו. תועלת לרבים בו. עצל הוא בדברי העולם. אם מתעורר מלמטה, מתעוררים להטיב לו מלמעלה. זוכה בדבריו. זה הוא חמוד ומפזר כסף. טוב עין הוא. תפלתו נשמע, יורד ועולה בכסף, דהיינו ברכושו."],[5,"דא איהו דלזמנין וכו':","זה הוא שלפעמים נשבר לבו לפני אדונו. ואז נמצאים ג' קוים קטנים העוברים על קו הדק ההוא הנתוסף על אלו השנים שברוחב. וסוד זה הוא. \u0003ה'\u0004 המתחברת עם \u0003ר'.\u0004 וחוזר על הדברים בדרך קצר, הטוב לזכרון. זה דרך. זה בית. זה חדוה. זה עצבות. זה תועלת. זה עצל. זה טוב עין. זה חמוד ומפזר כסף. זה נשבר לבו ושב לאדונו."],[6,"תרעא תניינא וכו':","שער השני, הוא \u0003ז'\u0004. ביד הימין, בחלק שקולט ומקבל דהיינו בכף היד, נמצאות רשימות. קסטירו הוא כמו גסטרא שפירושו חלק. כמ\"ש (וי\"ר ט\"ו) גסטרא בפני עצמה. \u0003דקולטא\u0004 פירושו קליטה וקבלה. כשנמצאים ג' קוים גדולים ברוחב, וב' גדולים באורך, ואחד מאלו שבאורך אוחז באלו ב' שברוחב, וקו האחר אינו אוחז בחם. זה יש פסול בזרעו מצד אביו או מצד אמו."],[7,"וכדין משתכחי לתתא וכו':","ואז נמצאים למטה מאלו ג' קוים שברוחב, ב' קוים דקים הנאחזים בהם למטה. זה הוא אדם מתקן מעשיו לפני בני אדם, ולבו אינו אמת. ולעת זקנה חוזר להתתקן. אז נמצאים אלו ב' קוים שבאורך שנאחזים באלו שברוחב, זה עם זה. וב' אחרים עמהם באמצע, דקים, וזה באורך. וג' דקים ברוחב. וסוד זה הוא \u0003ז'\u0004 המתחברת עם אות \u0003ר'.\u0004"],[8,"וכד איהו סיב וכו':","וכשהגיע לזקנה ושב, כמו שאמרנו, הוא מתתקן בסוד אות \u0003ר'\u0004 ומתחברת באות \u0003ז'.\u0004 ואח\"כ, כשזה נתתקן הוא תמיד בחשאי וכל מעשיו בחשאי. אבל אין הוא בקיום כראוי, משום שפסול הזה שבזרעו עוד לא התיאש בו ומעורר אותו לרע."]],[]],[["וּלְבָתַר דְּאִתְיָיאָשָׁא. הַהוּא פְּסִילוּ, כְּדֵין אִשְׁתְּכָחוּ שִׂרְטוּטִין בִּידָא יְמִינָא, אַרְבַּע וְחָמֵשׁ. אַרְבַּע בְּאַרְכָּא, חָמֵשׁ בְּפוּתְיָא. וְרָזָא דָּא ז', וְאִתְחֲבָּר בְּאָת ה'. הַאי לְזִמְנִין אַצְלַח, לְזִמְנִין לָא אַצְלַח. אַצְלַח בְּאוֹרַיְיתָא, וּלְסוֹף יוֹמוֹי, אַצְלַח אֲפִילּוּ בְּמָמוֹנָא.","תַּרְעָא תְּלִיתָאָה, ה'. בִּימִינָא, כַּד אִשְׁתְּכָחוּ חָמֵשׁ שִׂרְטוּטִין בְּפוּתְיָא, וּתְלַת בְּאַרְכָּא, וְאִשְׁתְּכַח הַהוּא שִׂרְטוּטָא דְּאֶמְצָעִיתָא מֵאִינּוּן תְּלַת, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִסְתְּמִיךְ בְּאוֹת ס'.","בְּזִמְנָא דְּאִשְׁתְּכַח הַהוּא שִׂרְטוּטָא דְּאֶמְצָעִיתָא, דְּעָאל וְאָחִיד גּוֹ אִינּוּן חָמֵשׁ שִׂרְטוּטִין דְּפוּתְיָא, דָּא אִיהוּ בַּר נָשׁ עָצִיב וְרָגִיז גּוֹ בֵּיתֵיהּ, וּבְגוֹ בְּנֵי נָשָׁא לָאו הָכִי. קַמְצָן אִיהוּ בְּבֵיתֵיהּ, וְרָגִיז וְכָפִין, וּלְזִמְנִין לָא. לְבַר מִבֵּיתֵיהּ לָאו הָכִי. אַצְלַח בְּעוֹבְדֵי עָלְמָא. כַּד אִשְׁתָּדַּל בְּאוֹרַיְיתָא אִסְתַּכִּיל זְעֵיר וְאִתְהַדָּר בָּהּ. מְהֵימָנָא אִיהוּ, אֲבָל לָאו כָּל זִמְנָא. וְהַהוּא זִמְנָא דְּלָאו מְהֵימָנָא, אַחְזֵי גּוָֹון קְשׁוֹט, וְלָא קְשׁוֹט בִּשְׁלִימוּ. בְּדִינָא יִצְלַח. מְהֵימָנָא אִיהוּ בְּרָזִין דְּאוֹרַיְיתָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְחֲבָּר בְּאָת ס'.","וְאִי אַרְבַּע שִׂרְטוּטִין בְּפוּתְיָא, וְחָמֵשׁ בְּאַרְכָּא, תְּרֵין מֵאִינּוּן דְּאָרְכָּא, עָאלִין גּוֹ אִינּוּן אַרְבַּע, דָּא אִיהוּ בַּר נָשׁ חַדֵּי בְּבֵיתֵיהּ, וְאִתְחַזֵּי עָצִיב לִבָּא לְבַר, וְלָאו הָכִי דְּכֵיוָן דְּמַלִּיל עִם בְּנֵי נָשָׁא, אַחְזֵי חֵדוּ וְאִתְכְּוָון בְּמִלּוֹי.","תְּלַת שִׂרְטוּטִין זְעִירִין עָאלִין גּוֹ אִינּוּן דְּאָרְכָּא, דָּא אִית לֵיהּ חַד רְשִׁימוּ אוּכָם בְּגוּפֵיהּ, וּתְלַת שַׂעֲרִין תַּלְיָין בְּהַהוּא רְשִׁימוּ, וְהַהוּא רְשִׁימוּ אִיהוּ כְּעִגּוּלָא, וְחַד תְּבִירָא (חבורא) בְּרֵישֵׁיהּ. וּלְהַאי רְשִׁימָא, קָרָאן לֵיהּ חַכִּימֵי לִבָּא, דְּיַדְעִין רָזִין אִלֵּין, רֵישׁ נִשְׁרָא. רְשִׁימוּ דָּא, אִתְחָזֵי לְזִמְנִין, בֵּין כִּתְפוֹי. וּלְזִמְנִין, בִּדְרוֹעָא יְמִינָא. וּלְזִמְנִין, עַל יְדָא יְמִינָא בְּאֶצְבְּעוֹי.","אִי רְשִׁימָא דָּא רֵישׁ נִשְׁרָא, אִיהוּ בְּאֹרַח מֵישָׁר בְּתִיקוּנוֹי, יִסְתַּלַּק לְעוּתְרָא וְלִיקָרָא. וְאִי הַהוּא רֵישׁ נִשְׁרָא אִתְהַפַּךְ לַאֲחוֹרָא, יִזְכֶּה לְבֵנִין לְזִמְנִין. אֲבָל כַּד אִיהוּ סִיב, יִזְכֶּה לְעוּתְרָא יַתִּיר, וְלִיקָר סַגְיָא, יַתִּיר מֵעוּלְמוֹי, וְיַצְלַח בְּאוֹרַיְיתָא, אִי אִשְׁתַּדַּל בָּהּ.","רֵישׁ נִשְׁרָא דָּא, אִתְחָזֵי לְזִמְנִין אוּכָמָא, וּלְזִמְנִין גּוָֹון דְּלָא סוּמָק זְעֵיר, דְּלָא אִצְטְבַּע כָּל כַּךְ. לְזִמְנִין בְּשַׂעֲרִין לְזִמְנִין שְׁעִיעַ, וְכֹלָּא חַד סִימָנָא אִיהוּ, וּבְחַד דִּינָא אִתְדָּן.","וְאִי הַהוּא גּוָֹון סוּמָק אִצְטְבַּע יַתִּיר, וְקָאִים בִּגְוָונֵיהּ, זְמַן זְעֵיר הוּא דְּאִצְטְבַע, בְּגִין דְּאִלֵּין גַּוְונִין, לְזִמְנִין קַיְימִין נְהִירִין, וּלְזִמְנִין חֲשׁוּכִין. וְאִי אִצְטְבַּע הַהוּא סוּמָק וְנָהִיר, כְּדֵין אִית בִּידָא שְׂמָאלָא, תְּלַת שִׂרְטוּטִין בְּאַרְכָּא, וּתְלַת בְּפוּתְיָא, וְחַד דָּקִיק עַל אִינּוּן דְּפוּתְיָא, וְחַד דָּקִיק עַל אִינּוּן דְּאָרְכָּא. וּבִידָא יְמִינָא אִתּוֹסָף חַד בְּפוּתְיָא בִּלְחוֹדוֹי. הַאי בַּר נָשׁ שָׁכִיב בְּנִּדָּה, וְלָא תָּב מִינֵּהּ לְמָארֵיהּ.","וְכַד תָּב בִּתְיוּבְתָּא, אִשְׁתָּאָרוּ אִינּוּן שִׂרְטוּטִין בִּידָא שְׂמָאלָא, וְהַהוּא דְּאִתּוֹסָף בִּימִינָא, אִתְעָדֵי מִנֵּיהּ, וְאִתְעָדֵי הַהוּא סוּמָקָא, דְּלָא אִתְחָזֵי נָהִיר כָּל כַּךְ מִנֵּיהּ. וּלְזִמְנִין דְּאַף עַל גַּב דְּתָב, לָא אַעְדִּיוּ מִנִּיהּ הַהוּא סוּמָקָא, עַד זְמַן. הַאי אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְעָדֵי אָת ס', וְעָאל תְּחוֹתוֹי אָת ץ', וְאִתְחֲבָּר אָת ה' בְּאָת ץ'. הַאי בָּעֵי תִּקּוּנָא לְנַפְשֵׁיהּ בִּבְהִילוּ. חַכִּימָא דְּלִבָּא דְּחָמֵי לֵיהּ, חוֹבָתָא אִית עָלֵיהּ, לוֹמַר לֵיהּ זִיל אַסֵּי לְנַפְשָׁךְ.","וְאִי תְּלַת שִׂרְטוּטִין בְּאַרְכָּא, וְחַד בְּפוּתְיָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה' בִּלְחוֹדֵיהּ. וּלְזִמְנִין אִתְחַבַּר בְּרָזָא דְּאָת ז'. הַאי אִיהוּ בַּר נָשׁ תָּאִיב בָּתַר בִּצְעִין דְּעָלְמָא. וְאִי לָאו, רָדִיף בָּתַר נָשִׁין, וְתֵיאוּבְתֵיהּ נִאוּפִים. וְאַף עַל גַּב דְּתָאִיב לְבִצְעִין דְּעָלְמָא, הַאי לָא אַעְדִּיו מִנֵּיהּ, וְלָא אַכְסִיף. עֵינוֹי שְׁקִיעִין וּמַלִּיל בְּהוּ.","אִי תָּב לְמָארֵיהּ מִתְחַלְּפֵי שִׂרְטוּטִין. תְּלָת בְּפוּתְיָא וְחַד לְאָרְכָּא, וְאִינּוּן תְּרֵין דְּקִיקִין קַיְימִין בְּקִיּוּמָא, כְּדֵין רְעוּ דִּילֵיהּ יַתִּיר בְּאִתְּתֵיהּ, וְאִתְדְּבַק בָּהּ. חַד דָּקִיק יַתִּיר, עָאל בֵּין אִינּוּן תְּרֵין דְּקִיקִין. כְּדֵין אִתְחַבַּר אָת ה' בְּאָת ז'."],[[0,"ולבתר דאתיאשא ההוא וכו':","ואחר שמתיאש פסול ההוא, אז נמצאים קוים ביד ימין, ארבע וחמש, דהיינו ארבע באורך וחמש ברוחב, וסוד זה \u0003ז'\u0004 שנתחברה באות \u0003ה'.\u0004 זה, לפעמים מצליח ולפעמים אינו מצליח. מצליח בתורה. ולבסוף ימיו מצליח אפילו בכסף."],[1,"תרעא תליתאה וכו':","שער השלישי הוא \u0003ה'.\u0004 בימינא, כשנמצאים חמשה קוים ברוחב, ושלש באורך, ונמצא ניכר בו ביותר קו ההוא האמצעי מאלו השלשה שבאורך. זה הוא בסוד אות \u0003ה'\u0004 ונסמכת באות \u0003ס'.\u0004"],[2,"בזמנא דאשתכח ההוא וכו':","בזמן שנמצא קו ההוא האמצעי, מאלו השלשה שבאורך, שנכנס ואוחז תוך אלו חמש קוים שברוחב. זה הוא אדם עצב וכועס בתוך ביתו. ובין בני אדם אינו כן. הוא קמצן בביתו, וכועס ורעב, ולפעמים לא. לחוץ מביתו אינו כן. מצליח בדברי העולם. כשעוסק בתורה מסתכל מעט וחוזר בה. הוא נאמן, ולא בכל זמן. ובזמן ההוא שאינו נאמן, הוא מראה כמו שהוא אמת, ואינו אמת בשלימות. מצליח בדין. נאמן הוא בסודות התורה. זה הוא בסוד אות \u0003ה'\u0004 ומתחברת באות \u0003ס'.\u0004"],[3,"ואי ארבע שרטוטין וכו':","ואם ארבעה קוים ברוחב, וחמש באורך, ושנים מאלו שבאורך נכנסים תוך אלו ארבע שברוחב. זה הוא אדם שמח בביתו, ונראה עצוב לב בחוץ, ואינו כן, כי כיון שמדבר עם אנשים מראה שמחה. ומתכוון בדבריו."],[4,"תלת שרטוטין זעירין וכו':","ג' קוים קטנים נכנסים בתוך אלו שבאורך, זה יש לו רושם אחד שחור בגופו, וג' שערות תלויות ברושם ההוא, ורושם ההוא הוא כעגול, ושבר אחד בראש הרושם. לרושם הזה קוראים חכמי לב היודעים סודות אלו, בשם, ראש נשר. רושם הזה נראה לפעמים בין כתפיו, ולפעמים בזרוע ימין, ולפעמים על יד ימין על אצבעותיו."],[5,"אי רשימא דא וכו':","אם רושם הזה הנקרא ראש נשר הוא בדרך יושר בתקוניו, יעלה לעשירות ולכבוד. ואם ראש נשר הזה מתהפך לאחוריו, יזכה לפעמים לבנים. אבל כשיזקין יזכה לעושר גדול וליקר גדול, יותר מבילדותו. ויזכה בתורה אם יעסוק בה."],[6,"ריש נשרא דא וכו':","ראש נשר הזה, נראה לפעמים שחור, ולפעמים בצבע שאינו אלא מעט אדום, שלא הצטבע כל כך. ולפעמים רואים בשערות התלויות עליו, שלפעמים הן חלקות. והכל סימן אחד הוא, ובדין אחד נידון."],[7,"ואי ההוא גוון וכו':","ואם צבע אדום ההוא נצטבע יותר, ועומד בצבעו, וזמן קטן הוא שנצטבע. כי אלו הצבעים לפעמים נמצאים מאירים, ולפעמים חשכים, ואם נצטבע אדום ההוא ומאיר, אז יש לו ביד שמאל ג'קוים באורך וג' קוין ברוחב, וקו אחד דק על אלו שברוחב, וקו אחד דק על אלו שבאורך. וביד ימין נתוסף קו אחד ברוחב בלבד. זה הוא אדם ששכב עם נדה ולא שב עליה לאדונו."],[8,"וכד תב בתיובתא וכו':","וכשחוזר בתשובה, נשארו הקוים שביד שמאל, וקו ההוא שנתוסף בימין, הוסר ממנו. והוסר צבע האדום ההוא, שאינו נראה מאיר כל כך. ולפעמים אע\"פ ששב, לא הוסר ממנו האדום ההוא עד זמן. זה הוא בסוד אות \u0003ה'\u0004 והוסרה אות \u0003ס'\u0004 ונכנס תחתיה אות \u0003ץ'\u0004 ונתחברה אות \u0003ה'\u0004 באות \u0003ץ'.\u0004 זה צריך במהרה תקון לנפשו. חכמי לב הרואים אותו, חוב עליהם לומר לו, לך רפא את עצמך."],[9,"ואי תלת שרטוטין וכו':","ואם ג' קוים באורך ואחד ברוחב. זה הוא בסוד אות \u0003ה'\u0004 בלבד, ולפעמים מתחברת בסוד אות \u0003ז'.\u0004 זה, הוא אדם חומד בצע שבעולם. ואם לא, הוא רודף אחר נשים, ותאותו נאופים. ואע\"פ שחומד בצע שבעולם, גם זה לא הוסר ממנו, ואינו מתביש. עיניו שקועות ומדבר בהם. כלומר בשעה שמדבר קורץ בעיניו."],[10,"אי תב למאריה וכו':","אם שב לאדונו מתחלפים הקוים, ג' ברוחב ואחד לאורך, ואלו ב' הדקים עומדים בקיומם. אז הרצון שלו הוא באשתו יותר והתדבק בה. קו אחד דק ביותר נכנס בין אלו ב' קוין הדקים. אז מתחבר אות \u0003ה'\u0004 באות \u0003ז'.\u0004"]],[]],[["וְאִי שִׂרְטוּטָא חַד בְּאַרְכָּא וְאַרְבַּע בְּפוּתְיָא, וּתְלַת דְּקִיקִין קַיְימִין עַל הַהוּא חַד, וְחַד עַל אִינּוּן אַרְבַּע. עַל דְּרוֹעָא שְׂמָאלָא, אִית לֵיהּ תְּלַת קִסְטְרִין דְּקִיקִין, דְּאִתְיְלִידוּ בֵּיהּ מִיּוֹמִין זְעִירִין, וְחַד שַׂעֲרָא תַּלְיָא, בְּהַהוּא חַד דְּרֵישָׁא. הַאי אִיהוּ רָדִיף בָּתַר נְאוּפָא דְּאֵשֶׁת חַבְרֵיהּ. מָארֵיהּ דִּזְדוֹנָא אִיהוּ. אַגְזִים בְּעֵינָא שְׂמָאלָא, בְּלָא מִלּוּלָא כָּלַל, וְאַשְׁלִים. וּבְגִין דְּאִיהוּ מָארִיהּ זְדוֹנָא, לָא חָיִישׁ לִיקָרָא דְּמָארֵיהּ, לְאָתָבָא קָמֵיהּ. לְבָתַר קָטִיל חִוְיָא לֵיהּ, אוֹ בַּר נָשׁ סוּמָקָא.","וְאִי אַרְבַּע בְּאַרְכָּא, וּתְלַת בְּפוּתְיָא, וְאִינּוּן דְּסַלְּקִין לְעֵילָּא אַעְדִּיוּ מִנֵּיהּ. הַאי, תָּבַר לִבֵּיהּ לְגַבֵּי מָארֵיהּ, וְתָב בְּתִיוּבְתָא. כְּדֵין אִיהוּ בְּרָזָא דְּאָת פ', וְאִתְחֲבָּר בְּאָת ה'. עַל אִלֵּין, וְעַל אִינּוּן דִּכְוָותֵיהּ, כְּתִיב, (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב.","עַד הָכָא, כָּל אִינּוּן רָזִין דְּתוֹלְדוֹת אָדָם, דְּאִינּוּן תוֹלְדוֹת, דְּאִתְיְלִידוּ בֵּיהּ מִזְּמַן לִזְמַן, כְּפוּם אָרְחוֹי דְּבַר נָשׁ. זַכָּאָה חוּלָקֵיהוֹן דְּאִינּוּן דְּיַתְבִין קָמֵיהּ דְּמֹר, וְזָכוּ לְמִשְׁמַע מִפּוּמֵיהּ רָזִין דְּאוֹרַיְיתָא. זַכָּאָה אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן לְעָלְמָא דְּאָתֵי. אָמַר ר' שִׁמְעוֹן, זַכָּאִין אַתּוּן חַבְרַיָּא, דְּכָל רָזִין לָא אָנִיס לְכוּ, כַּמָּה דּוּכְתִּין עִלָּאִין אִזְדַּמְּנָן לְכוּ לְעָלְמָא דְּאָתֵי.","פָּתַח וְאָמַר (שמות י״ח:כ״א) וְאַתָּה תֶחזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים אַנְשֵׁי אֱמֶת שׂוֹנְאֵי בָצַע, הַאי קְרָא אוּקְמוּהָ. אֲבָל וְאַתָּה תֶחזֶה, תִּבְחַר לָא כְּתִיב. אֶלָּא תֶחזֶה: לְפוּם חֵיזוּ דְּעַיְינִין. בְּמַאי. בְּדִיּוּקְנָא דְּבַר נָשׁ בְּאִלֵּין שִׁית סִטְרִין דְּקָאָמַרְתּוּן וְכֹלָּא בְּהַאי קְרָא. וְאַתָּה תֶחזֶה, חַד, בְּשַׂעְרָא. מִכָּל הָעָם, תְּרֵין, בְּמִצְחָא. אַנְשֵׁי חַיִל, תְּלַת, בְּאַנְפִּין. יִרְאֵי אֱלֹהִים, אַרְבַּע, בְּעַיְינִין. אַנְשֵׁי אֱמֶת, חָמֵשׁ, בְּשִׁפְוָון. שׂוֹנְאֵי בָצַע, שִׁית, בְּיָדִין. בְּשִׂרְטוּטֵיהוֹן.","דְּאִלֵּין אִינּוּן סִימָנִין, לְאִשְׁתְּמוֹדְעָא בְּהוּ בְּנִי נָשָׁא, לְאִינוּן דְּרוּחַ חָכְמְתָא שַׁרְיָא עָלַיְיהוּ. וְעִם כָּל דָּא, מֹשֶׁה לָא אִצְטְרִיךְ דָּא, אֶלָּא מַה כְּתִיב, וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חַיִל מִכָּל יִשְׂרָאֵל. בְּגִין דְּרוּחָא קוּדְשָׁא הֲוָה אָתֵי לְגַבֵּיהּ, וְאוֹדַע לֵיהּ, וּבֵיהּ הֲוָה חָמֵי כֹּלָּא.","מְנָא לָן, דִּכְתִּיב כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי. בָּאִים אֵלַי לָא כְּתִיב, אֶלָּא בָּא אֵלַי, דָּא רוּחַ קוּדְשָׁא, דְּהֲוָה אָתֵי לְגַבֵּיהּ, וּבֵיהּ הֲוָה יָדַע, וְלָא אִצְטְרִיךְ לְכָל דָּא לְאִסְתַּכְּלָא וּלְעַיְינָא, אֶלָּא לְפוּם שַׁעֲתָא הֲוָה יָדַע מֹשֶׁה.","כְּהַאי גַּוְונָא, יָדַע שְׁלֹמֹה מַלְכָּא, יָדַע בְּכוּרְסְיֵיהּ, דְּרוּחַ קוּדְשָׁא שַׁרְיָא עָלֵיהּ, דְּכָל מַאן דְּקָרִיב לְכוּרְסְיֵיהּ, דְּחִילוּ וְאֵימָתָא נָפִיל עָלֵיהּ, וּבֵיהּ הֲוָה דָּאִין דִּינָא בְּלָא סָהֲדִין. בְּגִין דְּדִיּוּקְנִין הֲווֹ בְּכוּרְסְיֵיהּ, וְכָל מַאן דְּמִקְרַב בְּשִׁקְרָא, מְכַשְׁכְּשָׁא הַהוּא דִּיּוּקְנָא, וַהֲוָה יָדַע שְׁלֹמֹה מַלְכָּא, דִּבְשִׁקְרָא קָאֲתֵי. בְּגִין כַּךְ, אֵימָתָא דְּכוּרְסְיֵהּ הֲוָה נָפִיל עַל כֹּלָּא, וְכֻלְּהוּ אִשְׁתְּכָחוּ זַכָּאִין קָמֵיהּ.","מַלְכָּא מְשִׁיחָא בְּרֵיחָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו י״א:ג׳) וַהֲרִיחוֹ בְּיִרְאַת יְיָ' וְלא לְמַרְאֵה עֵינָיו יִשְׁפּוֹט וְגוֹ'. וּתְלַת אִלֵּין, דָּנוּ עָלְמָא, בְּלָא סָהֲדִין וְהַתְרָאָה. שְׁאַר בְּנֵי עָלְמָא עַל פּוּם סָהֲדִין, עַל מֵימָר אוֹרַיְיתָא. חַכִּימִין דְּאִשְׁתְּמוֹדְעָן בְּאִינּוּן דִּיּוּקְנִין, עָלַיְיהוּ לְאַזְהָרָא לִבְנֵי עָלְמָא, וּלְמֵיהַב אַסְוָותָא לִבְנֵי נָשָׁא, וּלְאַסֵּי נַפְשַׁיְיהוּ. זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.","\u0003רזא דרזין\u0004 (שמות י״ח:כ״א) ואַתָּה תֶחֱזְה מִכָּל הָעָם. זֶה סֵפֶר תוֹלְדוֹת אָדָם. דָּא סֵפֶר מֵאִינּוּן סִפְרִין, סְתִימִין ועֲמִיקִין, (נ\"א דא ספרא מאינון סתימין ועמיקין) אָמַר ר' שִׁמְעוֹן, אֲרִימִית יְדָי בְּצַּלּוּ לְמַאן דְּבָרָא עָלְמָא, דְּאַף עַל גַּב דִּבְּהַאי קְרָא גָּלוּ קַדְמָאֵי סְתִימִין עִלָּאִין, אִית לְאִסְתַּכְּלָא וּלְעַיְינָא בְּרָזִין דְּסִפְרָא דְּאָדָם קַדְמָאָה, דְּמִתַּמָּן אִתְמַשְּׁכָא סִפְרָא גְּנִיזָא דְּשְׁלֹמֹה מַלְכָּא.","זֶה: דְּתַלְיָא בֵּיהּ כֹּלָּא. זְה: אִילָנָא דְּחַיִּי. זֶה: וְלָא אַחֲרָא דְּגַלֵּי. (מאי) זֶה: כְּמָה דְּאַתְּ אָמֵר, (שמות י״ב:ב׳) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים, זְה נִיסָן וְלָא אַחֲרָא.","זֶה סֵפֶר, לְאַשְׁגָּחָא וּלְגַלָּאָה תוֹלְדוֹת אָדָם, אִילָנָא דְּגַלֵּי תוֹלְדוֹת אָדָם. וְעָבִיד אִיבִין לְאַפָּקָא לְעָלְמָא. זְה סֵפֶר, לְמִנְדַּע חָכְמְתָא סְתִימָא וַעֲמִיקָא, דְּאִתְּמְסַר לְאָדָם קַדְמָאָה, בְּדִיּוּקְנָא דִּבְנֵי נָשָׁא, חָכְמְתָא דָּא אִתְמְסַר לִשְׁלֹמֹה מַלְכָּא, ויָרִית לָהּ וְכָתַב בְּסִפְרֵיהּ.","אוֹלִיפְנָא, דְּמֹשֶׁה אִתְקָשֵׁי בְּדָא, עַד דְּאָתַת שְׁכִינְתָּא וְאוֹלִיפַת לֵיהּ, והִיא חָמַאת וּבָרִירַת לְכָל אִינּוּן גּוּבְרִין דְּאִתְחָזוּן בְּפַרְצּוּפָא, וְתַמָּן אוֹלִיף מֹשֶׁה חָכְמְתָא דָּא, וְעָיִיל בְּגַוִּיהּ, הֲדָא הוּא דִכְתִיב ואַתָּה תֶחֱזֶה מִכָּל הָעָם. הַהוּא דִּכְתִּיב בֵּיהּ (תהילים ק״ב:כ״ח) ואַתָּה הוּא וּשְׁנוֹתֶיךָ לֹא יתַּמּוּ. (נחמיה ט׳:ו׳) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. (תהילים ג׳:ד׳) וְאַתָּה יְיָ' מָגֵן בַּעֲדִי.","וְאַתָּה תֶחֱזְה, וְתִסְתַּכַּל בְּהָא. אַנְתְּ, וְלָא אַחֲרָא, לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּשִׁתִין רִבּוֹא. בְּשִׁית סִטְרִין אִית לְאִסְתַּכְּלָא. בְּדִיּוּקְנִין דִּבְנֵי נָשָׁא, וּלְמִנְדַּע חָכְמְתָא עַל בּוּרְיִיהּ. ואִלֵּין אִינּוּן בְּשַׂעְרָא. בְּעַיְינִין. בְּחוֹטָמָא. בְּשִׁפְוָון. בְּאַפִּין. בְּיָדִין. בְּאִינּוּן שִׂרְטוּטִין דְּיָדִין. וּבְשִׁית סִטְרִין אִלֵּין, כְּתִיב וְאַתָּה תֶחֱזְה. וְאַתָּה תֶחֱזְה, בְּשַׂעְרָא,","בִּקְמִיטִין דְּמִצְּחָא, בְּאִלֵּין קְרִיצִּין דְּעַל עַיְינִין. מִכָּל הָעָם, בְּעַיְינִין. בְּדוּקִין דְּעֵינָא, וּבִּקְמִיטִין דִּתְחוֹת עֵינָא. אַנְשֵׁי חָיִל, לְמֵיקָם חֵילָא דִּבְהוּ בְּהֵיכָלִין דְּמַלְכָּא. בִּצְּהִיבוּ דְּאַפִּין. בְּאַפִּין, בִּקְמִיטוּ דְּאַפִּין. בִּרְשִׁימוּ דִּבְהוּ בְּדִיקְנָא. שׂנְאֵי בָצַּע, בְּיָדִין, בְּשִׂרְטוּטֵי יְדִין, רְשִׁימִין דִּבְהוּ. וְכֻלְּהוּ שִׁית סִטְרִין רְמִיזִין הָכָא, דְּאִתְמְסָרוּ לְמֹשֶׁה, לְאִסְתַּכְּלָא וּלְמִנְדַּע חָכְמְתָא סְתִימָאָה, וחָכְמְתָא דָּא, יָרְתָּן זַכָּאֵי קְשׁוֹט כְּדְקָא יֵאוֹת, זכָּאָה חוּלָקֵיהוֹן.","כְּתִיב (איוב י׳:י״א) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וגוֹ', (ע\"ז ע\"א) כְּגַוונָא דָּא עָבֵד קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, דַּרְגִּין עַל דַּרְגִּין, אִלֵּין עַל אִלֵּין, סְתִימִין גּוֹ סְתִימִין, וְחַיָּילִין וּרְתִיכִין, אִלֵּין עַל אִלֵּין, הָכִי עָבִיד בְּכָל אִינּוּן, עַרְקִין וְגִידִין, וְאִלֵּין אִינּוּן גַּרְמִין, וְקַיְימִין בְּקִיּוּמָא דְּדַרְגִּין עִלָּאִין, ואִלֵּין אִקְרוּן (ויקרא ק\"ע ע\"א) בָּשָׂר, דַּרְגִּין ושֻׁלְטָנוּתָא דְּקֵץ כָּל בָּשָׂר, וְכָל אִינּוּן דְּאִתְהֲנוּן מִתְּנָנָא דְּבָשָׂר, דְּרֵיחִין דְּקָרְבְּנִין, ואַחֲרָנִין דְּשַׁלְטִין בַּבָּשָׂר. ועֵילָּא מִכֻּלְּהוּ עוֹר, מַשְׁכָא (דאתפטותא דרקיע ואיהו עור דמשכא) דְּחָפֵי עַל כֹּלָּא.","כְּגַוונָא דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא כֹּכָבִים וּמַזָּלוֹת דִּרְקִיעָא, בְּמַשְׁכָא לְאִסְתַּכְּלָא בְּהוּ, וְאִינּוּן אוֹתוֹת הַשָּׁמַיִם, וּלְמִנְדַּע בְּהוּ חָכְמְתָא. הָכִי עָבֵד קוּדְשָׁא בְּרִיךְ הוּא בִּבְנִי נָשָׁא, רְשִׁימִין וּקְמִיטִין בְּהַהוּא פַּרְצּוּפָא דְּאָדָם, כְּאִינּוּן כֹּכָבִים וּמַזָּלוֹת, לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּהוּ חָכְמְתָא סַגְיָא, וּלְאִתְנַהֲגָא בְּהוּ גּוּפָא.","כְּמָה דְּמִתְחַלְּפֵי בְּמַשְׁכָא חֵיזוּ דִּרְקִיעָא, דְּכֹּכָבַיָּא וּמַזָּלֵי, לְפוּם עוֹבָדִין דְּעָלְמָא, הָכִי מִתְחַלְּפִין חֵיזוּ דִּרְשִׁימִין וּקְמִיטִין בְּמַשְׁכָא דְּבַּר נָשׁ, לְפוּם עוֹבָדוֹי מִזְּמַן לִזְמַן. וּמִלִּין אִלֵּין לָא אִתְמְסָרוּ אֶלָּא לְזָכָּאֵי קְשׁוֹט, לְמִנְדַּע וּלְאַלְפָא חָכְמְתָא סַגְיָא.","זֶה סֵפֶר תוֹלְדוֹת אָדָם, מִזְּמַן לִזְמַן, לְפוּם עוֹבָדוֹי דְּאָדָם, הָכִי אִתְיְלִידוּ, וְאִתְרְשִׁימוּ ואִתְחַלְּפוּ בֵּיהּ רְשִׁימִין מִזְּמַן לִזְמַן. דְּהָא בְּזִמְנָא דְּרוּחָא קֻדְשָׁא שַׁרְיָא בְּגַוִּיהּ, הָכִי עָבִיד תוֹלְדוֹת, וְאַחְזֵי רְשִׁימִין הַהוּא רוּחַ לְבַר.","וּבְזִמְנָא דְּמִתְעַבְּרָא וְזָז מִנֵּיהּ רוּחַ קֻדְשָׁא, וְאַתְיָא רוּחַ מִסְאֲבָא, וְהַהוּא רוּחַ מִסְאֲבָא הוּא מְכַשְׁכְּשָׁא בְּגַוִּיהּ, ואַחְזֵי לְבַר חֵיזוּ יְדִיעָאן, וּרְשִׁימִין דְּאִשְׁתְּמוֹדְעָן בֵּיהּ בִּקְמִיטִין בְּמַשְׁכָא לְבַר. וְאַף עַל גַּב (דשערא ומצחא וחוטמא ועיינין, וכל אינון סימנין, קיימין על קיומייהו.)","זר\"ה פס\"ץ, אָת דָּא דְּמִתְחַלְּפָא תָּדִיר בְּהָא חָכְמְתָא. בְּאָת זַיִ\"ן, מִלָּה דְּקַיְּימָא בְּשַׂעְרָא הֲוָה וְסִימָנִיךְ זַיִ\"ן, וּמָאנֵי קְרָבָא דְּשִׁמְשׁוֹן, בְּשַׂעְרָא. וְדָא הוּא נִזְרָא דֶּאֱלהִים עָלֵיהּ. דְּקַיְּימָא","שַׂעֲרָא לְאִשְׁתְּמוֹדְעָא, וְתַלְיָא. דָּא קַיְּימָא בְּאָת ז', ואִתְחֲבָּר בֵּיהּ אָת צּ'. דָּא עָאל וְאַפִּיק ס'.","אִי שַׂעֲרָא דָּא תַּלְיָא ואוּכָם, וּבְמִצְּחָא תְּלָתָא שִׂרְטוּטִין מִסִּטְרָא דִּימִינָא, וּתְרֵין מִשְּׂמָאלָא, וְלָא מִתְחַבְּרָן אִלֵּין בְּאִלֵּין. בִּסְטַר יְמִינָא אִית תְּלָתָא רְשִׁימִין דְּקִיקִין, דְּעַבְרִין עָלַיְיהוּ. וְאִינּוּן שְׁבִילִין לְמֶעְבַּר עַל אִינּוּן שִׂרְטוּטִין אַחֲרָנִין. וּבִסְטַר שְׂמָאלָא חָמֵשׁ, וְחַד מִנֵּיהּ זְעֵיר בְּאַרְכֵּיהּ. דָּא קַיְּימָא בְּגוֹ אָת ז' וְאָת ץ'. כְּדֵין תִּשְׁכַּח קְרִיצִּין תַּקִּיפִין דְּעַל חוֹרֵי עֵינוֹי, דְּמִתְחַבְּרָן דָּא בְּדָא.","דָּא אִיהוּ בַּר נָשׁ מָארֵיהּ דְּרוּגְזָא, וְלָא בִּבְהִילוּ, וְנַיְיחָא דִּילֵיהּ בְּעִכּוּבָא. חָשִׁיב בְּגַרְמֵיהּ דְּאִיהוּ חַכִּים. וְלָאו הָכִי. זָקִיף רֵישָׁא לְאִסְתַּכְּלָא תָּדִיר. מָארֵי מָצּוּתָא לְבַר. בְּבֵיתֵיהּ לָאו הָכִי. אוֹרַיְיתָא לָא חָשִׁיב לְאִסְתַּכְּלָא בָּהּ. מִלִּין דִּבְנֵי נָשָׁא חֲשִׁיבִין עָלֵיהּ כְּמָטוּל, ואָתִיב מִלִּין תַּקִּיפִין עָלַיְיהוּ.","וְאִי מִתְפָּרְשָׁן קְרִיצִּין דָּא מִן דָּא, מָטוּ וְלָא מָטוּ, כְּדֵין תִּשְכַּח בְּמִצְּחָא לְסִטְרָא דִּימִינָא, תְּרֵין שִׂרְטוּטִין רַבְרְבִין וחַד זְעֵירָא, וּתְרֵין רְשִׁימִין זְעִירִין דְּעָאלִין בֵּינַיְיהוּ לְפוּתְיָא. וְלִסְטַר שְׂמָאלָא תְּרֵין, חַד רַבְרְבָא, וְחַד זְעֵירָא, וְחַד רְשִׁימוּ זְעֵיר דְּעָאל בְּחַד וְלָא מָטֵי לְתִנְיָינָא.","דָּא אִיהוּ מָארֵיהּ דְּרוּגְזָא, לְפוּם שַׁעֲתָא אִתְמְלֵי רוּגְזָא, וּלְפוּם שַׁעֲתָא שָׁכִיךְ רוּגְזֵיהּ, וּמָארֵי קְטָטָא בְּבֵיתֵיהּ, ולָאו בְּרוּחַ נַיְיחָא. זִמְנָא חֲדָא בְּעָלְמָא (נ\"א ביומוי) אָתִיב תּוּקְפִין לִבְנֵי נָשָׁא. אִסְתַּכַּל לְתַתָּא. מִצְּחֵיהּ קָמִיט בְּרוּגְזֵיהּ, וְדָמִי כְּכַלְבָּא, וּמִיָּד שָׁכִיךְ וְאָתִיב רְכִיכִין. דָּא אִיהוּ בַּר נָשׁ, דְּרוּחָא דִּילֵיהּ וּרְעוּתָא לְאִשְׁתַּדְּלָא דִּילֵיהּ, בִּסְחוֹרָתָא (עזרא ד׳:כ׳) וּמִנְדָּה בְלוֹ והָלַךְ וּבְאִשְׁתַּדְּלוּתֵיהּ, סָלִיק לְמָמוֹנָא. דְּהָא אִתְחַלָּף אָת ץ' בְּאָת ס'.","וְאִי מִתְפָּרְשָׁן קְרִיצִּין דָּא מִן דָּא, וְשַׂעֲרִין אַחֲרָנִין עַיְילִין בֵּין דָּא לְדָא זְעִירִין. דָּא נָטִיר דְּבָבוּ סַגִי תָּדִיר. טַב אִיהוּ בְּבֵיתֵיהּ. וְחַדֵי ועָצִּיב בִּבְנֵי נָשָׁא, דָא קַיְּימָא בֵּין ץ' וּבֵין ס'. טָמִיר מָמוֹנֵיהּ. לָא בָּעֵי לְאַגְלוּיֵי, וּלְאִתְגְּלֵי בְּעוֹבָדוֹי. קַמְצָּן אִיהוּ. וְשַׂעֲרֵיהּ גָּבִיל דָּא עִם דָּא, וְתַלְיָיא. לָא חָשִׁיב גַּרְמֵיהּ לְמִלְבַּשׁ כְּדְקָא יֵאוֹת. מַה דְּלָבִישׁ לָא אִתְתַּקַּן בֵּיהּ. מִצְּחֵיהּ רַבְרְבָא, תְּלַת שִׂרְטוּטִין בִּימִינָא, ואַרְבַּע בִּשְׂמָאלָא תְּרֵין רְשִׁימִין עַיְילִין בֵּינַיְיהוּ.","דָּא כַּד מַלִּיל פָּשִׁיט מַשְׁכָא וְאִינּוּן דְּמִצְּחָא, שִׂרְטוּטִין לָא אִתְחָזוּן כָּל כַּךְ. כָּפִיף רֵישֵׁיהּ אָזִיל. יְמִינָא מִנֵּיהּ שְׂמָאלָא. שְׂמָאלָא מִנֵּיהּ יְמִינָא. עָצִּיב תָּדִיר אֲנִינָא אִיהוּ, מָארֵיהּ דְּלִישָׁנָא בִּישָׁא. חָשִׁיב גַּרְמֵיהּ חַכִּים בְּכָל עוֹבָדוֹי. מָארֵי דְּבָבוּ בְּכָל אִינּוּן דְּמִשְׁתַּדְּלָן בְּאוֹרַיְיתָא.","בִּדְרוֹעָא שְׂמָאלָא, אִית לֵיהּ רְשִׁימָא אוּכָמָא, וד' שַׂעֲרִין זְעִירִין בָּהּ, וּתְרֵין רַבְרְבִין דְּתַלְיָין בֵּיהּ סוּמָקִין. שַׂעֲרָא שְׁעִיעַ ותָלֵי, ואִיהוּ, לָאו סוּמָק, וְלָאו אוּכָם, מִצְּחָא דִּילֵיהּ לָא רַב וְלָא זְעֵיר. דָּא קַיְּימָא בֵּין אָת ס', וּבֵין אָת ץ' כְּלִילָא בְּאָת ז'.","חָד שִׂרְטוּטָא רַב בְּמִצְּחֵיהּ, דְּאַזְלָא בְּפוּתְיָא, מִסִּטְרָא דָּא לְסִטְרָא דָּא. תְּרֵין שִׂרְטוּטִין אַחֲרָנִין, אֲבָל לָא רְשִׁימִין כָּל כַּךְ, דְּהָא לָא קַיְּימִין מִסִּטְרָא דָּא לְסִטְרָא דָּא, כְּהַאי. אַרְבַּע קְמִיטִין זְעִירִין קַיְּימִין, בֵּין תְּרֵין קְרִיצִּין, עַל רֵישָׁא דְּחוֹטָמָא לְעֵילָּא.","דָּא אִיהוּ מָארֵיהּ דְּחֶדְוָה, חַכִּים, פְּקִיחַ, וַותְרָן בְּמָמוֹנֵיהּ, בְּכָל מַה דְּאִשְׁתַּדַּל לְמִנְדַּע אִיהוּ חַכִּים. לְפוּם שַׁעֲתָא רָגַז, וּלְפוּם שַׁעֲתָא נָח רוּגְזֵיהּ, לָא נָטַר דְּבָבוּ לְעָלְמִין. לְזִמְנָא טָב, וּלְזִמְנָא לָאו הָכִי כָּל כַּךְ, קָאִים בְּמַתְקְלָא. כַּד תָּב לְמָארִיהּ, מָארֵיהּ אָחִיד בִּידֵיהּ, וסָלִיק לִיקָר סַגְיָא. כֹּלָּא צְּרִיכִין לֵיהּ. אָת ס' אַזְלָא לְדִידֵיהּ תָּדִיר יַתִּיר מֵאָת ץ'. כָּל אִינּוּן דְּיָעֲטִין עָלֵיהּ עֵיטָא בִּישָׁא, לָא מַצְּלִיחִין, וְלָא אִתְקְיָים הַהוּא עֵיטָא, וְלָא יַכְלִין לְאַבְאָשָׁא לֵיהּ. אִתְחָזֵי רַמָּאָה וְלָאו הָכִי הוּא. אָת ס' ואָת ץ' מַגִּיחִין עָלֵיהּ, וּבְּגִין כָּךְ סָלִיק וְנָחִית. כַּד תָּב לְמָארֵיהּ, אָת ס' נָצַּח, וְאִתְעָבִיד רְעוּתֵיהּ בְּכֹלָּא. רַחֲמָן אִיהוּ. וּבָכֵי כַּד אִתְמְלֵי רַחֲמִין.","חָד רְשׁוּמָא אִית לֵיהּ בִּדְרוֹעָא יְמִינָא, וְקַיְּימָא פַּרְצּוּפָא, וְלֵית עָלֵיהּ שַׂעֲרִין כְּלַל. ואִי שַׂעֲרָא קְמִיטָא, וְלָא תָּלֵי תְּחוֹת אוּדְנִין, ואִיהוּ קָמִיט לְעֵילָּא מֵאוּדְנִין דָּא קַיְּימָא בְּמִלּוּלֵיהּ.","מִצְּחֵיהּ רַב וְלָאו כָּל כַּךְ. שִׂרְטוּטִין דִּילֵיהּ חָמֵשׁ. תְּלַת עַבְרִין מִסִּטְרָא דָּא לְסִטְרָא דָּא, וּתְרֵין לָא עַבְרִין. מָארֵי קְטָטָה אִיהוּ, וּבְבֵיתֵיהּ יַתִּיר. כָּל עוֹבָדוֹי בִּבְהִילוּ, אִתְחָזֵי טָב, וְלָאו הָכִי. שָׁבַח גַּרְמֵיהּ בְּמָה דְּלָא אִית בֵּיהּ. דָּא קָאִים בְּאָת ז' לְחוּד, וסָלִיק לְמֵרָחִיק בְּאָת צּ' לְחוֹד, מָטֵי ולָא מָטֵי אָת ס' לֵית בֵּיהּ כְּלָל. וַותְרָן בְּמִלּוּלֵיהּ ולָא יַתִּיר, אָעִיל גַּרְמֵיהּ בְּמָה דְּלָא אִתְחָזֵי לֵיהּ, מַאן דְּאִשְׁתַּתַּף בַּהֲדֵיהּ, אִצְּטְרִיךְ לְאִסְתַּמְּרָא מֵחֲמִידוּ דִּילֵיהּ, אֲבָל אַצְּלַח אִיהוּ בַּהֲדֵיהּ.","שַׂעֲרָא דְּתָלֵי וְלָא שְׁעִיעַ, וְשַׂעֲרֵיהּ רַב. חָמֵשׁ שִׂרְטוּטִין בֵּיהּ, דְּמָטוּ וְלָא מָטוּ דָּא לְדָא, עַיְינִין דִּילֵיהּ צְּהִיבִין פִּקְחִין. דָּא כָּפִיף רֵישֵׁיהּ. אִתְחָזִי טָב וְזַכָּאָה, ולָאו הָכִי. שָׁבַח גַּרְמֵיהּ. אִי אִשְׁתָּדַּל בְּאוֹרַיְיתָא כְּבַר נָשׁ רַב. תַּקִּיף בְּיִצְּרֵיהּ. כַּד מַלִּיל, אַקְמִיט חוֹטָמֵיהּ וּפָשִׁיט מַשְׁכָא דְּמִצְּחֵיהּ. כָּל עוֹבָדוֹי לְחֵיזוּ דִּבְנֵי נָשָׁא, אַצְּלַח בְּמָמוֹנָא, רַמָּאָה אִיהוּ בְּכָל עוֹבָדוֹי. מָארֵי דְּלִישָׁנָא בִּישָׁא. יָדַע לְאִסְתַּמְּרָא מִבְּנֵי נָשָׁא בְּכֹלָּא. שִׁגְעוֹנָא בֵּיהּ, וְאִתְכַּסֵּי בְּמָה דְּאִיהוּ עָבִיד. אָעִיל קְטָטִין בִּלְחִישׁוּ.","אוּדְנוֹי רַבְרְבָן, קַיְימִין בְּקִיּוּמַיְיהוּ תְּחוֹת שַׂעֲרָא, דָּא קַיְּימָא בְּאָת ץ' וְאָת ז', וּבְגִין כַּךְ עוֹבָדוֹי לְחֵיזוּ בְּנֵי נָשָא. בֵּין כִּתְפוי תַּלְיָין תְּלַת שַׂעֲרִין בְּלָא רְשִׁימָא כְּלָל. מַאן דְּאִשְׁתַּתַּף בַּהֲדֵיהּ לָא אַצְּלַח. ואִיהוּ אַצְּלַח בְּרַמָּאוּתָא דִּילֵיהּ, וְאִתְחַזִּי זַכָּאָה לְאַחֲרָא, וְחָשִׁיב דְּעָבַד לָקֳבְלֵיהּ עוֹבָדֵי קְשׁוֹט.","שַׂעֲרָא קְמִיטָא ותָלֵי תְּחוֹת אוּדְנִין, אִי אִיהוּ רַוָוק, חַד שִׂרְטוּטָא בְּמִצְּחֵיהּ, וּתְלַת קְמִיטִין עַל רֵישָׁא דְּחוֹטְמִין, בֵּין קְרִיצִּין דִּילֵיהּ. מָארֵיהּ דְּחֶדְוָה אִיהוּ. פְּקִיחָא בְכֹלָּא. רַמָּאָה. וותְרָן אִיהוּ, עָבִיד וַותְּרָנוּתָא לְאִינוּן דִּמְקָרְבִין בַּהֲדֵיהּ. דָּא קַיְּימָא בְּאָת ס' וְאָת ז'. וְכַד הֲוִי סִיב, מִתְחַלְּפָן (ס\"א ציורא דאתוון) אַתְוון, אָת ז' בְּרֵישָׁא, וְאָת ס' בַּהֲדֵיהּ. לָאו אִיהוּ וותְרָן, אֶלָּא בְּבֵיתֵיהּ. אַצְּלַח בְּמָמוֹנֵיהּ. רַמָּאָה לָא הֲוִי. אַעְדֵּי גַּרְמֵיהּ מֵהַהוּא אָרְחָא.","עַל קְרִיצָּא שְׂמָאלָא, אִית חַד רִישׁוּמָא זְעֵיר, דְּמָחָה לֵיהּ בַּר נָשׁ בְּיוֹמֵי עוֹלְימוֹי, אָטִים עֵינָא יְמִינָא. חָמֵשׁ קְמִיטִין עַל רֵישָא דְּחוּטָמֵיהּ, בְּפוּתְיִיהּ בֵּין קְרִיצֵּי עֵינוֹי. שַׂעֲרָא קְמִיטָא זְעֵיר עַל רֵישֵׁיהּ. קָמִיט דְּעַיְינִין. דָּא אִיהוּ בְּאָת ז' בִּלְחוֹדוֹי. בְּלָא סָכְלְתָנוּ. שִׁגְעוֹנָא בְּלִבֵּיהּ. בָּהִיל בְּעוֹבָדוֹי. חַד שִׂרְטוּטָא עַל מִצְּחֵיהּ. וְאַרְבַּע אַחֲרָנִין זְעִירִין. לֵית בֵּיהּ מְהֵימָנוּתָא, לָא יִשְׁתָּתַּף בַּר נָשׁ בַּהֲדֵיהּ, דְּלָא יִצְּלַח. חַיָּיבָא אִיהוּ לְמָארֵיהּ בְּכָל עוֹבָדוֹי.","חַד תּוּלְדוּתָא זְעֵירָא אִית לֵיהּ עַל יַרְכָא שְׂמָאלָא. לְזִמְנִין אִתְמְחֵי, וּלְזִמְנִין אִתְיילִיד. וְאִי אַרְבַּע שִׂרְטוּטִין עַל מִצְּחֵיהּ, כָּל הָנִי אִית בֵּיהּ, אֲבָל לֵית בַּהּ תּוּלְדָתָא. וְאִי תְּלַת רַבְרְבִין וּתְלַת זְעִירִין, שַׁפִּירוּ דְּשַׂעֲרָא אִיהוּ, וְאִיהוּ בְּאֶמְצָּעִיתָא. עֲד כָּאן רָזָא דְּשַׂעֲרָא.","מִצְּחָא מִתְפָּרְשָׁא בְּשַׂעְרָא, וּמִצְּחָא מִתְפָּרְשָׁא בְּעַיְינִין, עֵינָא מִתְפָּרְשָׁא בְּשַׂעְרָא, לְד' סִטְרִין. בְּבַת עֵינָא, בִּגְוָונִין דְּעֵינָא, בְּחִוּורוּ דְּעֵינָא, בְּאוּכָּמוּ דְּעֵינָא. כָּל אִסְתַּכְּלוּתָא לְאִסְתַּכְּלָא, בְּכָל אִינּוּן סִימָנִין דְּשִׁית דְּקַאָמְרָן, לֵית לְהוּ אֶלָּא מי\"ג שְׁנִין וּלְעֵילָּא, דְּאִתְפָּרְשָׁא רוּחַ קֻדְשָׁא מֵרוּחַ מְסָאֲבָא. בַּר בְּשִׂרְטוּטֵי בִּלְחוֹדוֹי, דְּשִׂרְטוּטִין בֵּין זְעֵירָא וּבֵין רַב מִתְחַלְּפֵי תָּדִיר וכֵן בְּכֻלְּהוּ.","כְּתִיב (שמות י״ח:כ״ה) וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חָיִל מִכָּל יִשְׂרָאֵל וְגוֹ', דְּאִילּוּ עַל אִינּוּן סִימָנִין אַחֲרָנִין בָּעָא וְלָא אַשְׁכַּח. וְכֵן (דברים א׳:ט״ו) הָבוּ לָכֶם אֲנָשִׁים חֲכָמִים וִידוּעִים לְשִׁבְטֵיכֶם. מַאי יְדוּעִים. דְּאִשְׁתְּמוֹדְעָאן בְּאִינּוּן סִימָנִין, ואַשְׁכַּח, בַּר נְבוֹנִים דְּלָא אַשְׁכַּח.","עֵינָא בְּרָזָא דְּאָת ר' וְאָת פ', דְּגְבִינִין חִוָּורִין וְשַׂעֲרָא סוּמָקָא. אִי גְּבִינִין דְּעֵינוֹי חִוָּורִין, דָּא הוּא בַּר נָשׁ דְּאִצְּטְרִיכוּ בְּנֵי נָשָׁא לְאִסְתַּמְּרָא מִנֵּיהּ. כָּל מִלּוֹי בְּרַמָּאוּתָא. פְּקִיחָא אִיהוּ. נָטִיר דְּבָבוּ. דָּא אִיהוּ בְּאָת ר' בִּלְחוֹדוֹי. ולָא אִתְחַבָּר בַּהֲדֵיהּ אָת פ'. אָת דָּא, אַזְלָא ושָאט עָלֵיהּ, וְלָא אִתְיַשְּבָא בֵּיהּ. עֵינוֹי דְּדָא שְׁקִיעִין, בָּהִיל בְּעוֹבָדוֹי. וְכֵן כָּל מַאן דְּעֵינוֹי שְׁקִיעִין, אִצְּטְרִיךְ לְאִסְתַּמְּרָא מִנֵּיהּ בְּכָל עוֹבָדִין. רַמָּאָה אִיהוּ, וּבְרַמָּאוּתֵיהּ יָהִיב טַעֲמָא לְמִלּוֹי.","מִצְּחָא דִּילֵיהּ רַב, ולָא עִגּוּלָא. תְּרֵין רְשִׁימִין רַבְרְבִין אַזְלִין בְּפוּתְיָא דְּמִצְּחֵיהּ, מִסְּטָר לִסְטָר, וְאַרְבַּע זְעִירִין. שַׂעֲרָא דִּילֵיהּ תַּלְיָא. קָרִיר מוֹחָא אִיהוּ. וְעַל דָּא פְּקִיחָא הֲוִי. אוּדְנוֹי זְעִירִין, בִּדְרוֹעוֹי שַׂעֲרָא רַב. נָקִיד אִיהוּ בִּנְקוּדִין דִּרְשִׁימִין אוּכָּמִין. וְאִי רְשִׁימִין סוּמָקִין, תָּב לְזִמְנִין לְמֶעְבַּד טִיבוּ, וְאִתְקַיַּים בֵּיהּ זִמְנָא זְעֵירָא, וּלְזִמְנִין תָּב לְקִלְקוּלֵיהּ. חַמְדָּן אִיהוּ.","זַרְעָא דְּדָוִד בְּהִפּוּכָא. דָּוִד מַלְכָּא יָרִית דָּא סוּמָקָא שַׁפִּירָא, לְמֶעְבַּד דִּינָא, וּלְמֶעְבַּד שַׁפִּירוּ דְּעוֹבָדוֹי. עֵינוֹי עַיְנִין דְּרַחֲמֵי, יַתְבִין עַל שְׁלִימוּ, סַלְּקִין חִנָּא וְחִסְדָּא. חַד חוּטָא יְרוֹקָא אָזִיל בְּגַוַּויְיהוּ. בְּשַׁעֲתָא דְּאַגָּח קְרָבָא, הַהוּא חוּטָא אִתְהַפַּךְ ואִתְהָוִי סוּמָקָא כְּוורְדָא. נָח רוּגְזֵיהּ בִּקְרָבָא, תָּב הַהוּא חוּטָא כְּמִלְקַדְּמִין. נִסִּין (כסין) רַבְרְבִין הֲווֹ בְּעֵינוֹי. הֲווֹ חַדָּאן. תְּאִיבִין לְמֵחֱמֵי. נְקוּדִין בִּתְלַת גַּוונִין, חִדוּ דְּלִבָּא הֲווֹ בְּלֵב כֹּלָּא, חַיָּיבַיָּא דְּמִסְתַּכְּלִין בְּהוּ, הֲווֹ זָעִין וְדָחֲלִין, סַלְּקִין בְּלִבַּיְיהוּ אֵימָתָא וּדְחִילוּ.","מִצְּחָא דִּילֵיהּ רַב עִגּוּלָא בִּשְׁפִירוּ, וכָל אַתְוָון אִתְחָזוּן וְסַלְּקִין בֵּיהּ, אִלֵּין סַלְּקִין ואִלֵּין נַחְתִּין. אִינּוּן דְּנַחְתִּין סַלְּקִין, יַהֲבִין דּוּכְתָּא אִלֵּין לְאִלֵּין. בְּגִין כַּךְ רְשִׁימִין דִּילֵיהּ סַלְּקִין בְּאַרְכָּא לְעֵילָּא. גְּבִינִין דְּעֵינוֹי רַחֲמִין לְרַחֲמָנוּתָא. לָא אוּכָּמִין וְלָא סוּמָקִין, אֶלָּא בֵּין תְּרֵין גַּוְונִין. בַּת עֵינָא דִּלְגוֹ, אַחְזֵי כָּל דִּיוּקְנִין דְּעָלְמָא, חוּטָא סוּמָקָא סַחֲרָא לֵיהּ, וְחֶדְוָוא סְחוֹר סְחוֹר כֹּלָּא.","שֵׁירוּתָא, דְּחַיָּיבִין מְקָרְבִין לְמֵחֱמֵי, אִינּוּן חַיָּיבַיָּא חָמָאן לוֹן חַיְיכָאן, רַחֲמֵי חִנָּא וְחִסְדָּא. לְבָתַר תּוּקְפָּא וּדְחִילוּ וְאֶמְתָּנוּ ורוּגְזָא. וְעֵינוי יונִים לְגַבַּיְיהוּ. מַאי יוֹנִים. דְּעַבְדִין לוֹן אוֹנָאָה לְחַיָּיבַיָּא. כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ה:י״ז) לֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ וּכְתִיב (שיר השירים א׳:ט״ו) עֵינַיִךְ יוֹנִים. מְקָרְבָן, וּמְרַחֲקָן. כָּל דִּיּוּקְנִין דְּעָלְמָא כֻּלְּהוּ כְּלִילָן בְּאַנְפּוֹי. שַׂעֲרָא דְּרֵישֵׁיהּ, הֲוָה רָשִׁים בִּגְוָונִי שִׁבְעָה זִינֵי דַּהֲבָא.","חֲמֵינָא בְּסִפְרָא דְּאָדָם קַדְמָאָה, דְּאָמַר הָכִי דִּיּוּקְנִין דִּמְשִׁיחָא קַדְמָאָה, לְסִיהֲרָא, גּוָֹון דִּילֵיהּ, זָהָב יְרַקְרַק בְּאַנְפּוֹי. גּוָֹון דִּילֵיהּ, זְהַב אוֹפִיר בְּדִיקְנֵיהּ. גּוָֹון דִּילֵיהּ, זְהַב שְׁבָא בִּגְבִינוֹי. גּוָֹון דִּילֵיהּ (דברי הימים ב ג׳:ו׳) זְהַב פַּרְוַיִם, בִּקְרִיצִּין דְּעַל עֵינוֹי. גּוָֹון דִּילֵיהּ, זָהָב סָגוּר בְּשַׂעְרָא דְּרֵישֵׁיהּ. גּוָֹון דִּילֵיהּ, זָהָב מוּפַז עַל חַדּוֹי בְּלוּחָא דְּעַל לִבֵּיהּ. גּוָֹון דִּילֵיהּ זְהַב תַּרְשִׁישׁ, עַל תְּרֵין דְּרוֹעִין. כָּל שִׁבְעָה גַּוְונִין אִלֵּין, הֲווֹ רְשִׁימִין, עַל כָּל אִינּוּן דּוּכְתֵּי דְּשַׂעֲרוֹי.","בִּדְרוֹעָא יְמִינָא, הֲוָה חָקִיק וְרָשִׁים רְשׁוּמָא חֲדָא סָתִים מִבְּנֵי נָשָא, מִגְדָּל חָקִיק בְּאַרְיִה. וְאָלֶף זְעֵירָא רָשִׁים בְּגַוִּיהּ, וְסִימָנָא דָּא (שיר השירים ד׳:ד׳) אֶלֶף הַמָּגֵן תָּלוּי עָלָיו. כָּל זִמְנָא דְּאַגָּח קְרָבָא, הַהוּא רְשִׁימָא סַלְּקָא וּבַלְטָא, וְעַל מִגְדָּל מְכַשְׁכְּשָׁא הַאי אָלֶף, וּכְדֵין אִתְתָּקַּף לְאַגָּחָא קְרָבָא. כַּד עָאל בִּקְרָבָא מְכַשְׁכְּשָׁא הַהוּא אַרְיֵה, וּכְדֵין אִתְגַּבָּר כְּאַרְיִה, וְנֶצַּח קְרָבִין. והַהוּא מִגְדָּל אִתְרְהִיט, וסִימָנֵיהּ (משלי י״ח:י׳) בּוֹ יָרוּץ צַּדִּיק וְנִשְׂגַּב. וְנִשְׂגַּב דָּוד מִשַּׂנְאוֹי דְּלָא יַכְלִין לְגַבֵּיהּ. וּמִן סִמָנִין אִלֵּין וּרְשִׁימִין אִלֵּין, הֲווֹ רְשִׁימִין בְּדַרְעֵיהּ שְׂמָאלָא. רְשׁוּמָא דְּבַר נָשׁ אַחֲרָא לָאו כְּהַאי.","עַיְינִין צְּהִיבִין פְּקִיעִין, שִׁגְעוֹנָא בְּלִיבֵּיהּ. מִצְּחָא רַב. שַׂעֲרוֹי סַגִּיאִין, תַּלְיָין, רְחִיקִין מִמַּשְׁכָא דְּרֵישָׁא. פְּקִיחָא אִיהוּ. פּוּם מְמַלֵּל רַבְרְבָן. שִׂפְוָון דִּילֵיהּ עַתִּיקִין מָארֵיהּ דְּלִישָׁנָא בִּישָׁא.","בְּמִצְּחֵיהּ תְּלַת שִׂרְטוּטִין, אִי בְּעֵינֵיהּ תְּרֵין שוּרְיָיקֵי סוּמָקֵי, דָּא הֲוָה בְּאָת ר' בִּלְחוֹדוֹי, וְשׁוּרְיְיקָא זָהִיר לְגַבַּיְיהוּ. עֲבֵירָה אִזְדַּמְּנַת לְגַבֵּיהּ, ואִשְׁתֵּזִיב מִינָהּ.","וְאִי שׁוּרְיְיקָא חֲדָא סוּמָקָא לְגוֹ בְּעֵינָא, קַיְּימָא בְּאַרְכָּא, וּתְרֵין זְעִירִין תְּחוֹתֵיהּ, וְחַד דְּאַעְבַּר בְּעֵינוֹי. דְּדֵין אִית לֵיהּ עֵיטָא בִּישָׁא, בְּאִתְּתָא אֲסוּרָה, וַעֲדַיִן עֵיטָא קַיְּימָא. כְּדֵין תִּשְׁתְּכַח בְּמִצְּחֵיהּ, חַד שִׂרְטוּטָא לְאָרְכָּא. מִקְּרִיצָּא יְמִינָא חַד שַׂעֲרָא וְאַרְבַּע זְעִירִין תְּחוֹתֵיהּ, וְחַד דְּאַעְבַּר בֵּינַיְיהוּ לְפוּתְיִיהּ.","וְאִי יִתְפְּרַשׁ מֵהַהוּא חַטָאָה, תִּשְׁכַּח בְּעֵינֵיהּ, תְּרֵין שׁוּרְיָיקֵי דְּקִיקִין, אַזְלִין בְּפוּתְיִיהּ דְּעֵינָא, וְלָא אַעְבָּר חַד בֵּינַיְיהוּ, וְכֵן בְּמִצְּחָא. וּמִזְמַן דְּאִתְפְּרַשׁ מֵהַהוּא חוֹבָה, הוּא מִזְּמַן ט' יוֹם, דְּהָא מִתַּמָּן וּלְהָלְאָה, יִתְמַחוּן רְשִׁימִין אִלֵּין, וְיִתְיְילִדוּ אַחֲרָנִין.","עַיְינִין דְּקִיקִין, וּמִתְהַפְּכָן זְעִיר בְּסוּמָקָא. דָּא אִיהוּ פְּקִיחָא. כָּל מִלּוֹי (ס\"א בתיובתא) בְחִיוּבָא. בְּמִצְּחוי תִּשְכַּח רְשִׁימִין תְּלַת. חַד רַב, דְּאַעְבַּר מִסִּטְרָא דָּא לְסִטְרָא דָּא. וּתְרֵין אַחֲרָנִין דְּלָא עַבְרִין. קְרִיצִּין דְּעֵינוֹי רַבְרְבִין. מָארֵיהּ דְּקַשְׁיוּ אִיהוּ. כַּד מַלִּיל, קָמִיט בְּחוּטְמִין, בְּרוּגְזִיהּ, (ס\"א או) אִי בְּקַשְׁיוּ דְּלִבֵּיהּ. זָקִיף שׁוּם בִּישׁ עָלֵיהּ. בִּישׁ בְּעֵינֵי דְּכֹלָּא. כֹּלָּא שַׂנְאִין לֵיהּ. אַצְּלַח לְזִמְנִין וּלְזִמְנִין לָא.","תְּלַת שַׂעֲרִין רַבְרְבִין בְּחַדּוֹי עַל לִבֵּיהּ. שִׂפְוָון דִּילֵיהּ עַתִּיקִין, מָארֵיהּ גָּאוּתָא בְּשִׁגְעוֹנָא. לִישָׁנָא בִּישָׁא.","שַׂעֲרוֹי שְׁעִיעִין רַבְרְבִין וְסַגִּיאִין. אַנְפּוֹי אַנְפִּין אֲרִיכִין זְעֵיר, וְעַגּוּלִין זְעֵיר, לְזִמְנִין אִתְחָרַט מִכָּל מַה דְּעָבַד וְתָב לְקִלְקוּלֵיהּ. בְּעֵינֵיהּ תִּשְׁכַּח שׁוּרְיָיקֵי, תְּרֵין בְּעֵינָא דִּימִינָא, וְחַד בְּעֵינָא דִּשְׂמָאלָא. אוּדְנוֹי זְעִירִין, קַיְימִין בְּקִיּוּמָא.","זַרְעָא דְּדָוִד בְּהִפּוּכָא. זַרְעָא דְּדָוִד כָּל סִימָנִין אִלֵּין לְטָב, וּלְמֶעְבַּד טִיבוּ. בַּר שִׂפְוון רַבְרְבִין, דְּכָל מַאן דְּשִׁפְוָותֵיהּ רַבְרְבִין, מָארֵיהּ דְּלִישָׁנָא בִּישָׁא אִיהוּ, בֵּין זַכָּאָה, בֵּין חַיָּיבָא. בַּר אִי צַּדִּיק גָּמוּר הוּא. וּבְזַכְיוּ דִּילֵיהּ נָצַּח וְנָטִיר גַּרְמֵיהּ.","עַיְינִין יְרוֹקִין, זְעִיר מִגָּוִון סוּמָק אָזִיל בֵּינַיְיהוּ, בְּמִצְּחֵיהּ תְּרֵין רְשׁוּמִין, מִסִּטְרָא דָּא לְסִטְרָא דָּא, וְחַד לְעֵילָּא זְעֵירָא, וְחַד לְתַתָּא. אִיהוּ בְּאָת פ' וְאָת ר'. דָּא מִצְּחֵיהּ רַב בְּעִגּוּלָא, אִיהוּ טָב לְכֹלָּא. יָהִיב מִכָּל מַה דְּאִית לֵיהּ לְכָל בַּר נָשׁ. ותְרָן אִיהוּ. שַׂעֲרוֹי שְׁעִיעַ וְתָלֵי. בִּסְטַר יְמִינָא אִית לֵיהּ חִוָּורוּ דְּשַׂעֲרֵי, מִיּוֹמָא דְּאִתְבְּרֵי.","מַתְנִיתִין. בְּנֵי עָלְמָא מָארֵיהוֹן דְּסָכְלְתָנוּ, פְּקִיחִין מָארֵיהוֹן עַיְינִין, דִּמְהֵימָנוּתָא, דִּי הֲוָה גְּנִיזָא בְּכוּ. מַאן מִנְּכוּן דְּסָלִיק וְנָחִית. מַאן דִּי רוּחַ אֱלָהִין קַדִּישִׁין בֵּיהּ. לִיקוּם וְלִינְדַע, בְּשַׁעֲתָא דְּסָלִיק בִּרְעוּתָא דְּרֵישָׁא חִוָּורָא, לְמִבְרֵי אָדָם, בָּטַשׁ בְּגוֹ בּוּצִּינָא חֲדָא, וּבָטַשׁ בּוּצִּינָא בִּפְשִׁיטוּ דְּנָהִיר, והַהוּא פְּשִׁיטוּ דְּבוּצִּינָא אַפִּיק נִשְׁמָתִין.","אוּף הָכִי בָּטַשׁ גּוֹ טִנָרָא חֲדָא תַּקִּיפָא, ואַפִּיק הַהוּא טִינָרָא שַלְהובָא חֲדָא מְלַהֲטָא, מְרֻקָּמָא בְּכַמָּה גַּוונִין, וְהַהוּא שַׁלְהוֹבָא סַלְּקָא וְנַחְתָּא, עַד דְּהַהוּא פְּשִׁיטוּ (נ\"א פטישו) בָּטַשׁ בֵּיהּ, וְתָב ואִתְיְשָׁב בְּדוּכְתֵּיהּ, ואִתְעָבִיד רוּחָא דְּחַיִּיא.","וְהַהוּא רוּחָא אִתְתְּחָם, וְנָטִיל גּוָֹון חַד מִשִּׁמְשָׁא. נָחִית לְתַתָּא, נָטִיל גּוָֹון חַד מִסִּיהֲרָא. סָטָא לִימִינָא, נָטַל גּוָֹון מַיָּיא, כָּלִיל בְּפוּמָא דְּאַרְיֵה חֲדָא. סָטָא לִשְׂמָאלָא, נָטַל גּוָֹון אֶשָּׂא, כָּלִיל בְּפוּמָא דְּחָד שׁוֹר, סוּמָקָא כְּוַורְדָא. סָטָא לְקַמֵיהּ, נָטַל גּוָֹון רוּחָא, כָּלִיל בְּפוּמָא דְּחָד נֶשֶׁר רַבְרְבָא, רַב גַּדְפִּין, מָארֵיהּ דְּנוֹצָּה, כָּל גַּוונִין בֵּיהּ מִתְחַמָּאן. סָטָא לַאֲחוֹרָא, נָטַל גּוָֹון עַפְרָא, כָּלִיל מד' סִטְרֵי עָלְמָא. בְּפוּמָא דְּאָדָם, וְכָל דִּיּוּקְנִין מִסְתַּכְּלָן לְגַבֵּיהּ.","אִתְיָישַּׁב הַהוּא רוּחָא בְּהַהוּא עַפְרָא, וְאִתְלָבַשׁ בֵּיהּ. כְּדֵין הַהוּא עַפְרָא, מְכַשְׁכְּשָׁא וְנָחַת לְתַתָּא, וְכָנַשׁ עַפְרָא מד' סִטְרִין דְּעָלְמָא, וְאִתְעָבִיד דִּיּוּקְנָא חֲדָא וּפַרְצּוּפָא, וְהַהוּא רוּחָא אִתְטָמַּר מִגּוֹ לְגוֹ. וְהַהוּא עַפְרָא דְּאִתְכְּנִישׁ מד' סִטְרִין בָּטַשׁ לְגַבֵּיהּ נֶפֶשׁ כְּלִילָא בְּעַפְרָא (ס\"א ברוחא.)","וְהַהוּא נֶפֶשׁ אִיהוּ יְסוֹדָא לְעוֹבָדֵי גּוּפָא. כְּפוּם עוֹבָדִין דְּהַהוּא נֶפֶשׁ בְּגוּפָא, הָכִי אִתְחָזִי בְּמַשְׁכָא לְבַר. רוּחָא דָּא אִתְטָמַּר לְגוֹ. וְהַהוּא אַחְזֵי לְבַר, סָלִיק וְנָחִית, וּבָטַשׁ בְּאַנְפּוֹי, וְאַחְזֵי דִּיּוּקְנִין וּרְשִׁימִין. בָּטַשׁ בְּמִצְּחֵיהּ, אַחְזֵי דִּיּוּקְנִין וּרְשִׁימִין בָּטַשׁ בְּעֵינוֹי, וְאַחְזֵי דִּיּוּקְנִין וּרְשִׁימִין. הֲדָא הוּא דִכְתִיב, (ישעיהו ג׳:ט׳) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם.","בּוּצִּינָא דְּאִתְמְשָׁךְ מִנֵּיהּ מְדִידוּ, דְּחָד חוּטָא יְרוֹקָא, שַׁלְהָבוּתָא דְּתֹהוּ. בָּטַשׁ בִּידוֹי בְּשַׁעֲתָא דְּבַר נָשׁ נָאִים, וְרָשִׁים רְשִׁימִין וְשִׂרְטוּטִין בִּידֵיהּ, וּכְפוּם עוֹבָדִין דְּבַּר נָשׁ הָכִי אִתְרְשִׁים. וְאִלֵּין אַתְוָון מִתְהַפְּכָן מִתַּתָּא לְעֵילָּא, וְיַדְעֵי לוֹן חַבְרֵי קְשׁוֹט, בִּרְשִׁימוּ דְּאַתְוָון דְּבוּצִּינָא, וְכָל אִלֵּין חֵילִין דִּלְגוֹ בְּבַּר נָש, עַבְדִין רְשוּמִין ושִרְטוּטִין אַתְוָון מִתְהַפְּכָן. מַאן דְּרָקִים דָּא, רָקִים בְּשִׁפּוּלֵי מַשְׁכְּנָא. כְּמָה דְאַתְּ אָמֵר, (תהילים קל״ט:ט״ו) רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ. בְּרִיךְ הוּא בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין.","עַיְינִין חִוָּורָא, וְאֵבָרִין סוּמָקִין, בְּאַתְרֵיהּ דְּנָפִיק מִינֵּיהּ, דָּא אִיהוּ בְּאָת פ' ואָת ר' כְּלִילָא כַּחֲדָא.","מִצְּחֵיהּ רַב, תְּלַת שִׂרְטוּטִין סַלְּקִין בְּמִצְּחֵיהּ, שִׁית זְעִירִין אַחֲרָנִין. סוּמָק הוּא ולָא סוּמָק, קַיְּימָא בֵּין תְּרֵין גַּוְונִין. שַׂעֲרֵיהּ אוּף הָכִי. אַנְפּוֹי רַבְרְבָן. שַׂעֲרֵיהּ קָמִיט, וְלָא כָּל כַּךְ. תָּלֵי זְעֵיר תְּחוֹת אוּדְנוֹי. טָב אִיהוּ, מָארֵי דִּמְהֵימְנוּתָא, מָארֵי דְּרוּגְזָא תַּקִּיף, בְּשַׁעֲתָא דְּאִתְרְגִיז.","הַהוּא סוּמָקָא דִּתְחוֹת עֵינָא, אִתְפָּשַׁט בְּעֵינֵיהּ. רוּגְזֵיהּ בִּישׁ. בְּשַׁעֲתָא דְּמַלִּיל בְּרוּגְזֵיהּ סָתִים פּוּמֵיהּ, וְנָפִיק תְּנָנָא מִנְּחִירוֹי. וְלִזְמַן זְעֵיר נָח רוּגְזֵיהּ, וְלָא כָּל רוּגְזֵיהּ, עַד יוֹמָא אַחֲרָא, אוֹ תְּרֵין יוֹמִין. דָּא אַצְּלַח לְזִמְנִין, וּלְזִמְנִין לָא. אֲבָל קָאִים תָּדִיר בְּאַצְּלָחוּתָא, בֵּין זְעֵיר וּבֵין רַב.","וְאִי סוּמָקָא דְּפוּם עֵינָא, זְעֵיר כְּחוּטָא, וְלָא אִתְפָּשַׁט בְּשַׁעֲתָא דְּרוּגְזִיהּ בְּעֵינָא, ואִית בֵּיהּ כָּל הָנֵי סִימָנִין. חַלְשָׁא בְּלִבָּא. וְאִיהוּ דָּחִיל מִכֹּלָּא, שֵׁינָתֵיהּ לָא אִתְיָישַּׁב בֵּיהּ. חָשִׁיב תָּדִיר מַחֲשָׁבִין וְדָחִיל מִכֻּלְּהוּ. וְאַצְּלַח לְכֹלָּא. מָארֵיהּ דִּגְרִיעַ (דגיידא). לָא חָשׁ לְגִיּוּפָא.","לְזִמְנִין תָּב בִּתְיוּבְתָּא וְדָחִיל. וּמִגּוֹ דְּחִילוּ, כְּדֵין תִּשְׁכַּח בְּעֵינֵיהּ יְמִינָא, הַהוּא סוּמָקָא דְּפוּם עֵינָא, בְּסוֹפָא בְּשִׁפּוּלֵי עֵינָא, וחַד שׁוּרְיָיקָא דָּקִיק סוּמָק בְּעֵינֵיהּ שְׂמָאלָא, ואִי מִתְחַלְּפֵי מַה דִּימִינָא לִשְׂמָאלָא, וּמַה דִּשְׂמָאלָא לִימִינָא, כְּדֵין אִיהוּ בְּקִלְקוּלֵיהּ. ותָב וְתָבַר גְּזִיזָא דְּבַרְדָּא, בְּגִין לְאַעְבְּרָא עֲבֵירָה.","תְּרֵין קְמִיטִין עַל רֵישָׁא וּתְלַת דְּעֵינָא, לְתַתָּא. וּבְרַגְלֵיהּ שְׂמָאלָא, בְּאֶצְּבְּעָא דְּאֶמְצָּעִיתָא, שִׁית שַׂעֲרִין, וּבְזִמְנָא אַחֲרָא חָמֵש, והַשְתָּא שִית, חַד זְעִירָא בֵּינַיְיהוּ. עַיְינִין אוּכָּמִין, וּקְרִיצִּין דְּעַל עֵינוֹי רַבְרְבִין, סַגִּיאִין שַׂעֲרִין, אִלֵּין עַל אִלֵּין, ואִינּוּן עַיְינִין אוּכָּמִין וְיָרוֹקָא, אָזִיל בְּגַוַּויְיהוּ, וְהַהוּא יְרוֹקָא אַטְבַּע יַתִּיר. הַאי אִית לֵיהּ חָמֵשׁ שִׂרְטוּטִין בְּמִצְּחָא, תְּרֵין דְּעַבְרִין מִסְּטָר לִסְטַר. וּתְלַת דְּלָא עַבְרִין וְכוּ'.","(שמות י״ט:א׳) בַּחֹדֶשׁ הַשְׁלִישִׁי לְצֵאת בְּנֵי יִשְׂרָאֵל וְגוֹ', דְּשָׁלִיט בֵּיהּ אוריא\"ל לֵיהּ, רַב מְמָנָא, וּתְלַת מְאָה וְשִׁתִּין וְחָמֵשׁ רִבּוֹא מַשְׁרְיָין עִמֵּיהּ, כְּחוּשְׁבָּן יוֹמֵי שַׁתָּא. וְכֻלְּהוּ אִית לוֹן תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ מַפְתְּחָן נְהוֹרִין, מֵהַהוּא נְהוֹרָא דְּנָפְקָא מִגּוֹ חַשְׁמַל עִלָּאָה פְּנִימָאָה גָּנִיז וְסָתִים, דִּי רָזִין דְּאַתְוָון קַדִּישִׁין עִלָּאִין דִּשְׁמָא קַדִּישָׁא, תַּלְיָין בֵּיהּ."],[[0,"ואי שרטוטא חד וכו':","ואם קו אחד באורך וארבעה ברוחב, וג' דקים עומדים על אותו האחד שבאורך, וקו אחד על אלו הארבע שברוחב. על זרוע השמאל ג' סימנים דקים שנולדו בו מימים מועטים, ושערה אחת תלויה באותו האחד העומד בראשם. זה הוא רודף אחר נאוף אשת חברו. בעל זדון הוא. מפחיד בעין שמאל בלא דבור כלל, ומשלים, כלומר, שמשלים פעלתו ואינו צריך לדבר. ומשום שהוא בעל זדון, אינו דואג לכבוד אדונו לשוב לפניו. ואח\"כ הורג אותו נחש, או אדם אדום."],[1,"ואי ארבע באורכא וכו':","ואם ד' באורך, וג' ברוחב, ואלו העולים למעלה הוסרו ממנו. זה, שובר לבו לפני אדונו ושב בתשובה. אז הוא בסוד אות \u0003פ'\u0004 ומתחברת באות \u0003ה'.\u0004 על אלו ועל אלו שכמותו כתוב, שלום שלום לרחוק ולקרוב."],[2,"עד הכא כל וכו':","עד כאן כל אלו הסודות של תולדות אדם, שהם תולדות הנולדים בו מזמן לזמן לפי דרכיו של האדם. אשרי חלקם של אלו היושבים לפני אדוני, שהוא ר\"ש, וזכו לשמוע מפיו סודות התורה. אשרי הם בעולם הזה ואשרי הם בעולם הבא. אמר ר' שמעון, אשריכם חברים, שכל סוד לא נעלם מכם. כמה מקומות עליונים מזומנים לכם לעולם הבא."],[3,"פתח ואמר ואתה תחזה וגו':","שואל, אבל כתוב ואתה תחזה ולא כתוב, תבחר. ומשיב אלא תחזה הוא לפי ראות עינים. במה. בצורה של האדם, באלו שש בחינות שאמרתם (באות ס\"ח) והכל הוא במקרא הזה. \u0003ואתה תחזה,\u0004 א' בשער. \u0003מכל העם,\u0004 ב' במצח. \u0003אנשי חיל,\u0004 ג' בפנים. \u0003יראי אלקים,\u0004 ד' בעינים. \u0003אנשי אמת,\u0004 ה' בשפתים. \u0003שונאי בצע,\u0004 ו' בידים, בקוים שלהם."],[4,"דאלין אינון סימנין וכו':","כי אלו הם סימנים להכיר על ידם בני אדם, לאלו שרוח החכמה שורה עליהם. ועם כל זה, משה לא היה צריך לזה, אלא מה כתוב, ויבחר משה אנשי חיל מכל ישראל. משום שרוח הקודש היה בא אליו והודיע לו, ובו היה רואה הכל."],[5,"מנא לן דכתיב וכו':","מאין לנו זה, כי כתוב, כי יהיה להם דבר בא אלי. באים אלי לא כתוב, אלא בא אלי, זה הוא רוח הקודש שהיה בא אליו, ובו היה יודע, ולא היה צריך לכל זה להסתכל ולעיין, אלא לפי שעה היה משה יודע."],[6,"כה\"ג ידע שלמה וכו':","כעין זה ידע שלמה המלך. ידע בכסאו, שרוח הקודש היה שורה עליו, שכל מי שקרב לכסאו, אימה ופחד נפל עליו. ובו היה דן דין בלי עדות. משום שצורות היו בכסאו, וכל מי שקרב עם שקר, היתה דופקת אותה צורה, והיה יודע שלמה המלך שבא עם שקר. משום זה האימה של הכסא נפל על הכל, וכולם נמצאו צדיקים לפניו."],[7,"מלכא משיחא בריחא וכו':","מלך המשיח דן בריח. כמש\"א, והריחו ביראת ה' ולא למראה עיניו ישפוט וגו'. ושלשה אלו, משה ושלמה המלך ומלך המשיח, דנים העולם בלא עדות והתראה. שאר בני העולם, דנים על פי עדות על פי התורה. החכמים הנודעים באלו הצורות, עליהם להזהיר את בני העולם, ולתת רפואה לבני אדם, ולרפאותם. אשריהם בעולם הזה ואשריהם בעולם הבא."],[8,"ואתה תחזה מכל העם:","זה ספר תולדות אדם. היינו, שזה ספר, מאלו הספרים הסתומים והעמוקים. אמר ר' שמעון הרימותי ידי בתפלה למי שברא העולם, שאע\"פ שבמקרא הזה גלו הקדמונים סתומים עליונים, יש עוד להסתכל ולעיין בסודות הספר של אדם הראשון, שמשם נמשך ספר הגנוז של שלמה המלך."],[9,"זה, דתליא ביה כלא וכו':","ומפרש המקרא זה ספר. \u0003זה,\u0004 יורה שתלוי בו הכל. \u0003זה\u0004 הוא עץ החיים, דהיינו ת\"ת. \u0003זה,\u0004 מגלה ואין אחר שיגלה. \u0003זה,\u0004 הוא כש\"א, החודש הזה לכם ראש חדשים, שפירשו זה ניסן ולא אחר. אף זה שבכאן, פירושו זה מגלה ולא אחר."],[10,"זה ספר:","היינו להסתכל בו ולגלות תולדות אדם. הוא אילן המגלה תולדות אדם שעושה פירות, דהיינו שמוליד נשמות, להוציא לעולם. \u0003זה ספר,\u0004 לדעת חכמה סתומה ועמוקה שנמסר לאדם הראשון בצורות של בני אדם. חכמה זו נמסרה לשלמה המלך, וירש אותה, וכתב בספרו."],[11,"אוליפנא דמשה אתקשי וכו':","למדנו, שמשה התקשה בזה, עד שבאה השכינה ולמדה לו, והיא ראתה ובררה לכל אלו האנשים שנראו והוכרו בפרצופיהם, ושם למד משה חכמה זו, והכניסה בתוכו. ז\"ש \u0003ואתה\u0004 תחזה. ההוא שכתוב בו \u0003ואתה\u0004 הוא ושנותיך לא יתמו. \u0003ואתה\u0004 מחיה את כלם. \u0003ואתה\u0004 ה' מגן בעדי שכל אלו המלות, ואתה, פירושם השכינה, אף כאן \u0003ואתה\u0004 תחזה, פירשו השכינה."],[12,"ואתה תחזה ותסתכל וכו':","ואתה, דהיינו השכינה, תחזה ותסתכל בזה, אתה ולא אחר, לדעת ולהסתכל בששים רבוא. בשש בחינות יש להסתכל בצורות בני אדם ולדעת חכמה על בירורה. ואלו הם, בשער, בעינים, בחוטם, בשפתים, בפנים, בידים דהיינו בקוים שבידים. ובשש בחינות אלו כתוב, ואתה תחזה."],[13,"ואתה תחזה:","פירושו, בשער, בקמטים שבמצח, באלו הגבות שעל העינים. \u0003מכל העם,\u0004 היינו, בעינים, בקרומין שבעין, ובקמטים שמתחת העין. \u0003אנשי חיל,\u0004 היינו אותם שיש להם כח לעמוד בהיכל המלך. וניכרים, בצהוב שבפנים, בפנים, ובקמטים שבפנים, וברשימו שבהם בזקן. \u0003שנאי בצע,\u0004 היינו בידים ובקוים שבידים, וברשימות שבהן. וכל שש בחינות רמוזים כאן בכתוב, שנמסרו למשה להסתכל ולדעת חכמה סתומה. וחכמה זו יורשים צדיקי אמת כראוי, אשרי חלקם."],[14,"כתיב, עור ובשר תלבישני וגו':","כעין זה עשה הקב\"ה למעלה מדרגות על מדרגות, אלו על אלו, סתומות תוך סתומות, וצבאות ומרכבות, אלו על אלו, כך עשה בכל אלו עורקים \u0003וגידים,\u0004 שעשה בהם מדרגות על מדרגות וכו'. ואלו הם \u0003העצמות,\u0004 העומדים בקיום מדרגות עליונות. ואלו, מן המדרגות, נקראות \u0003בשר,\u0004 שהם המדרגות והשליטה דקץ כל בשר (כמ\"ש פרשת נח דף מ\"ח ד\"ה ת\"ח) וכל אלו הנהנים מעשן הבשר מריחות הקרבנות, ואחרים השולטים בבשר. ולמעלה מכולם הוא \u0003עור,\u0004 דהיינו עור המכסה על כל."],[15,"כגוונא דעבד קב\"ה וכו':","כעין שעשה הקב\"ה ככבים ומזלות בעור הרקיע להסתכל בהם, שהם אותות השמים, ולדעת בהם חכמה. כך עשה הקב\"ה בבני אדם, רשימות וקמטים בעור פרצוף ההוא של אדם, שהם כאלו הככבים ומזלות שברקיע, לדעת ולהסתכל בהם חכמה גדולה, ולהתנהג בהם הגוף."],[16,"כמה דמתחלפי במשכא וכו':","כמו שמתחלפין בעור הרקיע מראה הככבים ומזלות לפי המעשים של העולם, כן מתחלפים מראה הרשימות והקמטים בעור האדם, לפי מעשיו, מזמן לזמן. ודברים אלו לא נמסרי אלא לצדיקי אמת לדעת וללמוד חכמה רבה."],[17,"זה ספר תולדות אדם:","מזמן לזמן לפי מעשיו של האדם, כך נולדים ונרשמים ומתחלפים בו הרשימות, מזמן לזמן. כי בזמן שרוח הקודש שורה בתוכו, כך עישה תולדות ומראה רשימות רוח ההוא שמבחוץ."],[18,"ובזמנא דמתעברא וזז וכו':","ובזמן שנעבר ומש ממנו רוח הקודש ובא רוח הטומאה, רוח הטומאה ההוא דופק בתוכו ומראה לחוץ מראות ורשימות ידועות, שניכרות בו בקמטים שבעור מבחוץ, ואע\"פ שהשער והמצח והחוטם וכל אלו סימנים עומדים על קיומם."],[19,"זר\"ה פס\"ץ","אות זו, דהיינו \u0003ץ'\u0004 מתחלף תמיד בחכמה זו. כלומר שעיקרם הן ה' אותיות \u0003זרה פס,\u0004 שהן אותיות \u0003זה ספר,\u0004 וה \u0003ץ'\u0004 מתחבר עמהם להיותה מתחלפת תמיד עם אותיות ההן. אות \u0003ז'\u0004 היא דבר העומד בשערות האדם, וסימניך, זין, דהיינו כלי זיין, וכלי זיין של שמשון היו בשערותיו, שבהן היתה כל גבורתו. וזה הוא נזר האלקים שעליו."],[20,"שערא דקיימא לאשתמודעא וכו':","שער העומד להיות מוכר, ותלוי ממעלה למטה. זה עומד באות \u0003ז'\u0004 ומתחברת בו אות \u0003צ',\u0004 זו נכנסת ומוציאה אות \u0003ס'.\u0004"],[21,"אי שערא דא וכו':","אם שערות אלו תלויות ושחורות, ובמצח יש ג' קוים מצד ימין, וב' מצד שמאל, ואינן מתחברות אלו באלו. בצד ימין יש ג' רשימות דקות העוברות עליהן, והן שבילים לעבור על אלו קוים האחרים. ובצד שמאל חמשה קוים, ואחד מהם קטן באורכו זה עומד בתוך אות \u0003ז'\u0004 ואות \u0003ץ'.\u0004 אז תשכח גבות חזקות שעל חורי עיניו שמתחברים זה בזה."],[22,"דא איהו בר נש וכו':","זה הוא אדם בעל כעס, ולא במהרה, ומעכב את מצב המנוחה שלו. מחזיק עצמו שהוא חכם ואינו כן. מרים ראשו תמיד להסתכל. בעל מריבה הוא בחוץ, ובביתו אינו כן. אינו מחשיב התורה להסתכל בה. דברי בני אדם נחשבים לו כמשא, ומשיב דברים נמרצים עליהם."],[23,"ואי מתפרשן קריצין וכו':","ואם נפרדות הגבות זו מזו, מגיעים ואינם מגיעים זה לזה, אז תמצא במצח לצד ימין, שני קוים גדולים ואחד קטן, ושתי רשימות קטנות שנכנסות ביניהם ברוחב. ולצד שמאל שנים, אחד גדול ואחד קטן, ורשימה אחת קטנה שנכנסת באחד ואינה מגעת לשני."],[24,"דא איהו מאריה וכו':","זהו בעל כעס, לפי שעה מתמלא בכעס, ולפי שעה שוכך כעסו. בעל מריבה בביתו, ואינו ברוח נוח. פעם אחת בימיו משיב נמרצות לבני אדם. מסתכל למטה. מצחו נקמט בשעת כעסו, ודומה לכלב, ומיד נשתכך ומשיב רכות. זה הוא אדם שהרוח שלו והרצון שלו לעסוק בסחורה, ומנדה בלו והלך, כלומר, ולתת כל מיני מסים למלך. ובהשתדלותו במסחר עולה לעשירות. כי נחלף אות \u0003צ'\u0004 באות \u0003ס'.\u0004"],[25,"ואי מתפרשן וכו':","ואם הגבות נפרדות זו מזו, ושערות אחרות קטנות נכנסות בין זו לזו, זהו תמיד נוטר שנאה גדול. טוב הוא בביתו. והוא שמח ועצב עם בני אדם. זה עומד בין \u0003ץ'\u0004 ובין \u0003ס'.\u0004 מסתיר כספו אינו רוצה להתגלות ושיתגלו מעשיו. קמצן הוא, ושערותיו שוות זו עם זו ותלויות. אינו מחשיב את עצמו שיתלבש כראוי. מה שלובש אינו מתוקן בו. מצחו גדול, ג' קוים בימין, וד' בשמאל, ב' רשימות נכנסות ביניהם."],[26,"דא כד מליל וכו':","זה, כשמדבר, פושט את עור מצחו, ואלו הקוים אינם נראים כל כך. כופף ראשו והולך. הימין ממנו משמשת כשמאל, והשמאל ממנו משמשת כימין. הוא עצב תמיד. הוא אונן. בעל לשון הרע. מחזיק עצמו חכם בכל מעשיו. בעל שנאה לכל העוסקים בתורה."],[27,"בדרועא שמאלא אית וכו':","אם בזרוע שמאל יש לו רשימה שחורה, וד' שערות קטנות בה, וב' גדולות התלויות בה הן אדומות השערות חלקות ותלויות, והן, אינן אדומות ואינן שחורות. המצח שלו, אינו גדול ואינו קטן. זה עומד בין אות \u0003ס'\u0004 ובין אות \u0003ץ',\u0004 כלול באות \u0003ז'.\u0004"],[28,"חד שרטוטא רב וכו':","קו אחד גדול במצחו ההולך ברוחב מצד זה לצד זה. ב' קוים אחרים, אבל אינם רשומים כל כך, כי אינם נמשכים מצד זה לצד זה, כמו קו האחד. ד' קמטים קטנים עומדים בין שתי גבות שבראש החוטם למעלה."],[29,"דא איהו מאריה וכו':","זה הוא איש שמח. חכם. פקח. וותרן בכספו. בכל מה שמשתדל לדעת הוא חכם. לפי שעה כועס ולפי שעה נח כעסו. אינו נוטר שנאה לעולם. לפעמים הוא טוב, ולפעמים אינו כן כל כך, אלא שנמצא במשקל, דהיינו לא טוב ביותר ולא רע ביותר. כששב בתשובה לאדונו, אדונו אוחזו בידו, ועולה לכבוד גדול. הכל צריכים אליו. האות \u0003ס'\u0004 הולך אצלו תמיד יותר מאות \u0003ץ'\u0004. כל אלו המיעצים עליו עצה רעה, אינם מצליחים והעצה אינה מתקיימת, ואינם יכולים להזיק לו. נראה שהוא רמאי ואינו כן. אות \u0003ס'\u0004 ואות \u0003ץ'\u0004 מתאבקים עליו, וע\"כ פעם עולה ופעם יורד. כששב לאדונו מנצח אות \u0003ס'\u0004 ומתמלא רצונו בכל דבר. הוא רחמן, ובוכה כשמתמלא רחמים."],[30,"חד רשימא אית וכו':","רשימה אחת יש לו בזרוע ימין, והפרצוף עומד ואין עליו שערות כלל. ואם השערות מסולסלות ואינן תלויות תחת אזניו, והן עומדות מסולסלות למעלה מאזניו. זה עומד בדבורו."],[31,"מצחיה רב ולאו וכו':","מצחו גדול ולא כל כך, הקוים שלו חמשה, ג' עוברים מצד זה לצד זה של המצח, ושנים אינם עוברים. בעל מחלוקת הוא, וביותר בביתו. כל מעשיו במהירות, נראה טוב ואינו כן. משבח עצמו במה שאין בו. זה עומד באות \u0003ז'\u0004 לבד ועולה למרחוק באות \u0003צ'\u0004 לבד הוא מגיע ואינו מגיע. אות \u0003ס'\u0004 אין בו כלל. וותרן בדיבורו ולא יותר. מכניס עצמו במה שאינו ראוי לו. מי שמשתתף עמו צריך להזהר מן החמדה שלו, אבל מצליח עמו."],[32,"שערא דתלי ולא וכו':","שערות התלויות ואינן חלקות, ושערותיו רבות, חמשה קוים בו שמגיעים ואינם מגיעים זה לזה. העינים שלו צהובות ופקוחות. זה כופף ראשו. נראה טוב וצדיק ואינו כן. משבח את עצמו. אם עוסק בתורה הוא כאדם גדול. גבור ביצרו כשמדבר, מקמט את חוטמו ופושט עור מצחו. כל מעשיו הם למראה בני אדם. מצליח בעשירות. רמאי הוא בכל מעשיו. בעל לשון הרע. יודע להשמר בכל דבר מפני בני אדם. שגעון בו, ונתכסה במה שעושה. שאינו ניכר מביא מחלוקת, בין אדם לחבירו, בחשאי."],[33,"אודנוי רברבין קיימין וכו':","אזניו גדולות, עומדות על קיומן תחת השערות. זה עומד באות \u0003ץ'\u0004 ואות \u0003ז'.\u0004 ומשום זה, מעשיו הם לעיני בני אדם. אם בין כתיפיו תלויות ג' שערות, בלא רושם כלל. מי שמשתתף עמו אינו מצליח. והוא מצליח ברמאות שלו. ונראה כצדיק כלפי אחר, וחושב שעשה עמו מעשים של אמת."],[34,"שערא קמיטא ותלי וכו':","אם השערות קמוטות ותלויות תחת אזניו, אם הוא פנוי מאשה, קו אחד במצחו, וג' קמטים על ראש החוטם, בין הגבות שלו. הוא איש שמח. פקח בכל דבר. רמאי. הוא וותרן, ומוותר לאלו המתקרבים לו. זה עומד באות \u0003ס'\u0004 ואות \u0003ז'.\u0004 ולכשיזקין, תתחלפנה האותיות, אות \u0003ז'\u0004 בתחילה, ואות \u0003ס'\u0004 עמו. אינו וותרן אלא בביתו. מצליח בעשירות. אינו רמאי, ומסיר את עצמו מדרך הזה."],[35,"על קריצא שמאלא וכו':","על גבה השמאלית יש רושם אחד קטן, שהכהו אדם בימי נעוריו. עין ימין סתום. חמשה קמטים על ראש חוטמו ברוחבו בין גבות עיניו. שערות מסולסלות מעט על ראשו. קומט את העינים. זה הוא באות \u0003ז'\u0004 לבד. הוא בלא תבונה. שגעון יש בלבו. מבוהל במעשיו."],[36,"חד שרטוטא על וכו':","קו אחד על מצחו, וארבעה אחרים קטנים. אין בו אמונה. לא ישתתף עמו אדם, כי לא יצלח. רשע הוא לאדונו בכל מעשיו. ותולדה אחת קטנה, יש לו על ירך השמאל, לפעמים נמחה, ולפעמים חוזר ונולד. ואם ד' קוים, על מצחו, יש בו כל זה הנ\"ל, אבל אין בו תולדה על ירכו השמאלית. ואם ג' קוים גדולים וג' קטנים על מצחו, והם באמצע המצח. הוא בעל שערות יפות. (ע\"כ סוד השערות)."],[37,"מצחא מתפרשא בשערא וכו':","המצח מתבאר בשערות, והמצח מתבאר בעינים,העינים מתבארות בשערות, לד' צדדים: בבת עין, בצבעים שבעין, בלבן שבעין, ובשחור שבעין. כל הסתכלות להסתכל בכל אלו ששת הסימנים שאמרנו, בשערא דמצחא וכו' כנ\"ל (אות ק\"פ) אינם אלא מי\"ג שנים ומעלה, שכבר נפרד באדם, רוח הקדושה מרוח הטומאה. חוץ בקוים בלבד, כי הקוים בין קטן ובין גדול מתחלפים תמיד. ואפשר לבחון בהם, אם הם מטומאה או מקדושה. וכן בכולם הנאמר להלאה."],[38,"כתיב ויבחר משה וגו':","כי הסימנים אחרים חוץ מאנשי חיל, בקש ולא מצא. וכן, הבו לכם אנשים חכמים וידועים לשבטיכם. מהו ידועים. היינו שנודעים באלו סימנים הנ\"ל, ומצא, חוץ מנבונים שלא מצא, מכאן משמע, שאנשי חיל וחכמים מעלתם קרובות זו לזו, כי כאן אוה\"כ ויבחר משה אנשי חיל וגו'. ובדברים אוה\"כ ואקח את ראשי שבטיכם אנשים חכמים וגו'. (ועי' עירובין ק' ע\"ב)."],[39,"עינא ברזא דאת וכו':","העין בסוד אות \u0003ר'\u0004 ואות \u0003פ',\u0004 שהגבות לבנות, והשער אדום. אם גבות עיניו לבנות, זהו אדם שאנשים צריכים להשמר מפניו. כל דבריו ברמאות. פקח הוא. נוטר שנאה. זהו באות \u0003ר'\u0004 בלבד, ולא נתחברה עמו אות \u0003פ',\u0004 אות זו, דהיינו \u0003פ',\u0004 הולכת ומשוטטת עליו, ואינה מתישבת בו. עיניו של זה שקועות. מהיר במעשיו. וכן כל מי שעיניו שקועות צריכים להשמר ממנו בכל המעשים. רמאי הוא, וברמאות נותן טעם לדבריו."],[40,"מצחא דיליה רב וכו':","אם המצח שלו גדול ואינו עגול, ב' רשימות גדולות הולכות ברוחב המצח מצד לצד, וד' קטנות. השערות שלו תלויות. קר מוח הוא. ועל כן פקח הוא. אזניו קטנות. בזרועותיו שער רב. נקוד הוא בנקודות של רשימות שחורות. ואם רשימות אדומות, חוזר לפעמים לעשות טוב, ומתקיים בו זמן קצר, ולפעמים חוזר לסורו, בעל חמדה הוא."],[41,"זרעא דדוד בהפוכא וכו':","זרעו של דוד הוא בהיפך. דוד המלך ירש אדום הזה הנאה, כדי לעשות דין ולעשות מעשים נאים. עיניו עינים של רחמים יושבות על מלאת, מעלות חן וחסד, חוט אחד ירוק הולך ביניהן, בשעה שעושה מלחמה, חוט ההוא מתהפך ונעשה אדום כורד. נח כעסו במלחמה, חוזר החוט כבתחילה. נסים גדולים היו בעיניו: היו שמחים, היו מתאוים לראותן, היו בהן, נקודות בג' צבעים, שמחת לב היתה בכל הלב, הרשעים שהיו מסתכלים בהן, היו זעים ומפחדים ועלה בלבם אימה ופחד."],[42,"מצחא דיליה רב עגולא וכו':","אם המצח שלו גדול ועגול ביופי, וכל האותיות נראות ועולות בו, אלו עולות ואלו יורדות אלו שירדו עולות, ונותנות מקום אלו לאלו. משום זה, הרשימות שלו עולות באורך למעלה במצחו. גבות עיניו רחמי רחמים, אינן שחורות, ולא אדומות, אלא שהן בין שני צבעים אלו. בת עין שמבפנים מראה כל צורות העולם, חוט אדום מסבב אותה, ושמחה סביב סביב הכל."],[43,"שירותא דחייבין מקרבין וכו':","בתחילה, כשאלו הרשעים מתקרבים לראות העינים אלו הרשעים כשרואים אותן צוחקים, ורחמים וחן וחסד בהן. ולאחר כך רואים בהן אומץ ופחד ואימה וכעס. ועיניו יונים כלפיהם. מה יונים. הוא, שעושים אונאה לרשעים, כש\"א לא \u0003תונו\u0004 איש את עמיתו. וכתוב, עיניך יונים, שמקרבים המסתכל בהן, ומרחקים אותם. כל הצורות שבעולם כלולות בפניו. שערות ראשו היו רשומות בצבעים של שבעה מיני זהב."],[44,"חמינא בספרא דאדם וכו':","ראיתי בספר אדם הראשון שאמר כך. הצורות של משיח הראשון, ללבנה שהיא המלכות, דהיינו מזרעו של דוד, כי משיח השני הוא משיח בן יוסף. המראה שלו זהב ירקרק, בפניו. המראה שלו זהב אופיר, בזקנו. המראה שלו זהב שבא, בגבות עיניו. המראה שלו זהב פרוים, בקריצין שעל עיניו. דהיינו בריסי העינים. המראה שלו זהב סגור, בשערות ראשו. המראה שלו זהב מופז, על החזה שלו בלוח שעל לבו. המראה שלו זהב תרשיש על שני זרועות. כל שבע מראות האלו היו רשומות על כל אלו מקומות של השערות."],[45,"בדרועא ימינא הוה וכו':","בזרוע הימין שלו, היה חקוק ורשום רושם אחד סתום מבני אדם, שהוא מגדל שחקוק בו אריה. ואלף קטנה רשומה בתוכו. וזה סימן, אלף המגן תלוי עליו. כל זמן שעושה מלחמה, רושם ההוא עולה ובולט, ועל המגדל דופקת אלף הזו, ואז מתגבר לעשות מלחמה. וכשנכנס במלחמה, דופק האריה ואז מתגבר כארי ומנצח המלחמות, ומגדל ההוא מריץ, וסימנו, בו ירוץ צדיק ונשגב. ונשגב דוד משונאיו, שאינם יכולים לו. ומן סימנים אלו ורשימות אלו, היו רשומות בזרוע שמאל. רושם של אדם אחר אינו כזה. כזרעו של דוד."],[46,"עיינין צהיבין פקיעין וכו':","אם העינים צהובות ובולטות: שגעון בלבו. מצחו רב. שערותיו מרובות תלויות למטה, רחוקות מעור הראש. הוא נבון. פה מדבר גדולות. שפתותיו בלויות. בעל לשון הרע."],[47,"במצחיה תלת שרטוטין וכו':","במצחו ג' קוים. אם בעינו ב' גידים אדומים. זה הוא באות \u0003ר'\u0004 בלבד, וגיד מאיר שורה אצלם. עבירה נזדמנה לו וניצל ממנה."],[48,"ואי שורייקא חדא וכו':","ואם גיד אחד אדום בעין בפנים, עומד באורך, וב' קטנים תחתיו, ואחד עובר בעיניו. זה יש לו עצה רעה באשה האסורה לו, ועוד העצה קיימת. אז תמצא במצחו, קו אחד לאורכו. מגבת עין ימנית יוצאת שערה אחת, וארבע שערות קטנות תחתיה. ואחת העוברת ביניהן לרוחבן."],[49,"ואי יתפרש מההוא וכו':","ואם יפרוש מן חטא ההוא, תמצא בעיניו ב' גידים דקים הולכים ברוחבו של העין, ואחר אינו עובר ביניהן. וכן במצח. והזמן שנפרש מחטא ההוא, נחשב עד ט' ימים. כי משם ולהלאה ימחו רשימות אלו ויתילדו אחרים."],[50,"עיינין דקיקין ומתהפכן וכו':","עינים דקות ונהפכים מעט לאדום. זה הוא נבון. כל דבריו בתשובה. במצחו תמצא ג' רשימות, אחד גדול העובר מצד זה לצד זה. ושני אחרים שאינם עוברים. גבות עיניו גדולות. הוא קשה עורף. כשמדבר, מקמט את חוטמו בכעסו או בעת שהוא קשה לב. שם רע עומד עליו. הוא רע בעיני הכל, הכל שונאים אותו. לפעמים מצליח ולפעמים לא."],[51,"תלת שערין רברבין וכו':","ג' שערות גדולות בחזהו על לבו. שפתותיו בלויות. בעל גאוה עד לשגעון. בעל לשון הרע."],[52,"שערוי שעיעין רברבין וכו':","שערותיו חלקות גדולות ורבות. פניו, פנים ארוכות מעט, ועגולות מעט. לפעמים מתנחם על כל מה שעשה, וחוזר לסורו. בעיניו תמצא ב' גידים בעין ימין, ואחד בעין שמאל. אזניו קטנות עומדות על קיומן."],[53,"זרעא דדוד בהפוכא וכו':","זרעו של דוד הם בהיפך. בזרעו של דוד כל סימנים האלו הם לטוב, ולעשות טוב. חוץ משפתים גדולות, שכל מי ששפתיו גדולות, הוא בעל לשון הרע בין צדיק ובין רשע, חוץ אם הוא צדיק גמור, שבזכיות שלו מנצח, ושומר את עצמו מלשון הרע."],[54,"עיינין ירוקין זעיר וכו':","אם העינים ירוקות ומעט מצבע אדום הולך ביניהן. במצחו ב' רשימות מצד זה לצד זה, ואחת קטנה למעלה, ואחת למטה. הוא באות \u0003פ'\u0004 ואות \u0003ר'.\u0004 זה מצחו גדול בעגול. הוא טוב לכל. נותן מכל מה שיש לו לכל אדם. הוא ותרן. שערותיו חלקות ותלויות. בצד ימין יש לו וסערות לבנות מיום שנברא."],[55,"מתניתין, בני עלמא וכו':","משנה, בני העולם בעלי התבונה, פקיחי העינים, דהיינו בעלי החכמה, בעלי האמונה, שהיא השכינה. שהיתה גנוזה בכם. מי מכם שעלה וירד דהיינו שקבל אורות המאירים ממטה למעלה המכונים עליה, ואורות המאירים ממעלה למטה המכונים ירידה. מי שרוח אלקים קדושים בו, יקום וידע שבשעה שעלה ברצונו של ראש הלבן, שהוא כתר, לברוא את האדם, השפיע בתוך מאור אחד, שהיא בינה, והמאור השפיע בהתפשטות המאור, שהוא ז\"א, המכריע ומאיר את ב' קוין ימין ושמאל דבינה. והתפשטות ההוא של המאור, הוציא \u0003נשמות\u0004 בני אדם."],[56,"אוף הכי בטש וכו':","אף כן הזדווג והשפיע התפשטות המאור, שהוא ז\"א, תוך סלע אחד חזק, שהוא המלכות, וסלע ההוא הוציא שלהבת אחת הלוהטת ומרוקמת בכמה גוונין, שהוא בחינת העיבור של הרוח, המלא דינים. ושלהבת ההוא עולה, שמקבל בחינת יניקה, שהאורות מאירים בו ממטה למעלה. ויורדת, דהיינו שמקבל ג\"ר דרוח, שהאורות מאירים ממעלה למטה, אבל בדינים, מצד חסרון חסדים. עד שהתפשטות המאור ההוא, שהוא ז\"א, השפיע בו, דהיינו שמשפיע בו בחינת קו אמצעי וחסדים, ואז, ושב ומתישב במקומו ונעשה \u0003רוח החיים.\u0004 לאדם הראשון."],[57,"וההוא רוחא אתתחם וכו':","ורוח ההוא נעשה בו תחומין, דהיינו י\"ב גבולי אלכסון שמקבל מז\"א, ולוקח גוון אחד משמש, שהוא ז\"א, דהיינו גוון ירוק. יורד למטה ולוקח גוון אחד מלבנה, שהיא המלכות, דהיינו גוון המקבל מכל הגוונין. ומקבל מד' חיות, אריה שור נשר אדם, שבמרכבה התחתונה. סר לימין ולוקח גוון מים, שהוא לבן, הכלול בפה האריה. שהוא חסד. סר לשמאל, ולוקח גוון אשא, שהוא אדום הכלול בפה של שור אחד האדום כורד. שהוא גבורה. סר לפניו ולוקח גוון הרוח שהוא ירוק, הכלול בפה של נשר גדול אחד, גדול הכנפים, בעל נוצות, כל הגוונים נראים בו, שהוא גוון ארגמן, הכולל לכל הגוונים. שהוא ת\"ת. סר לאחור ולוקח גוון עפר, המקבל מכל הגוונים הכלול מד' רוחות העולם חו\"ג תו\"מ, המקבל מן הפה של פני אדם, שכל הצורות מסתכלות אליו. והוא מלכות."],[58,"אתישב ההוא רוחא וכו':","התישב רוח ההוא בעפר ההוא והתלבש בו. כי העפר הוא מלכות, שהוא הנפש של אדם הראשון, והרוח התלבש בנפש. אז עפר ההוא שהוא הנפש, התנדנד וירד למטה, וקבץ עפר מד' רוחות העולם ונעשה צורה אחת ופרצוף, דהיינו גופו של אדם הראשון. והרוח נגנז בו לפני ולפנים. ועפר ההוא שנתקבץ מד' רוחות, שהוא הגוף, הנפש השפיע בו כשהוא כלול ברוח."],[59,"וההוא נפש איהו וכו':","ונפש ההיא היא יסוד למעשי הגוף, כפי מעשי הנפש ההיא בגוף, כך נראה בעור מבחוץ, הרוח נגנז מבפנים, וההיא, דהיינו הנפש, נראה מבחוץ, עולה ויורדת ומכה בפניו ומראה צורות ורשימות, מכה במצחו ומראה צורות רשימות, מכה בעיניו ומראה צורות ורשימות. ז\"ש, הכרת פניהם ענתה בם."],[60,"בוצינא דאתמשך מניה וכו':","המאור, שנמשך ממנו המדידה, דהיינו המסך דחירק, המודד את שיעור הקומה, של חוט אחד ירוק, שהוא קו אמצעי שיש לו גוון ירוק. שהוא מקבל המסך הזה מן המלכות שהיא שלהבת של התהו, דהיינו האש של מלכות דמדת הדין הנקרא תוהו, מכה בידיו על האדם בשעה שהוא ישן, ורושם רשימות וקוים בידיו. וכפי מעשי האדם כך נרשם. ואלו האותיות מתהפכות בו ממטה למעלה, ויודעים אותם החברים צדיקי האמת ברשימת האותיות של המאור, דהיינו מלכות הנ\"ל, וכל הכחות שבפנים האדם עושים רשימות וקוים ואותיות מתהפכות. מי שרושם זה, רושם בסוף המשכן, שהוא המלכות הנקראת משכן, כמש\"א רקמתי בתחתיות ארץ, דהיינו בתחתיות המלכות הנקראת ארץ. שהיא נרקמת ג\"כ מכח שלהבת המלכות דמדת הדין, כמו הידים של האדם. ברוך הוא וברוך שמו לעולם ולעולמי עולמים."],[61,"עיינין חורא ואברין וכו':","עינים לבנות ונתחי בשר אדומים במקום שהעינים יוצאות משם, דהיינו בחורי עינים, וכשמסבב עיניו הם נראים. זה הוא באות \u0003פ'\u0004 ואות \u0003ר'\u0004 כלולות יחד."],[62,"מצחיה רב, תלת וכו':","מצחו גדול, שלשה קוים עולים במצחו, וששה קטנים אחרים. אדום ולא אדום הוא ועומד בין שני צבעים. וכן גם שערותיו. פניו גדולות. שערותיו קמוטות, דהיינו מסולסלות, ולא כל כך. תלויות מעט מתחת אזניו. זה הוא טוב. בעל אמונה. בעל כעסן חזק בשעה שכועס."],[63,"ההוא סומקא דתחות וכו':","אם אדום ההוא שתחת עינו, שבחורי עיניו כנ\"ל, מתפשט בעינו. כעסו רע. בשעה שמדבר בכעסו, סותם פיו, ויוצא עשן מנחיריו. ולזמן קצר נח כעסו, ולא כל כעסו, עד יום האחר או שני ימים. זה לפעמים מצליח ולפעמים לא. אבל עומד תמיד בהצלחה אם מעט ואם רב."],[64,"ואי סומקא דפום וכו':","ואם האדום שבפי עינו מעט כחוט, ואינו מתפשט בשעת כעסו, בעין. ויש בו כל אלו הסימנים הנ\"ל. הוא חלש הלב. והוא מתירא מכל. השינה, אינה מיושבת בו. חושב תמיד מחשבות. ומפחד מכל. ומצליח לכל המשתתף עמו. איש משחת. אינו מתרחק מניאוף."],[65,"לזמנין תב בתיובתא וכו':","לפעמים חוזר בתשובה ומתירא, ומתוך היראה, תמצא אז בעינו הימין, אדום ההוא שבפי העין, שהוא בסוף בשולי העין, וגיד אחד דק אדום בעין השמאל. ואם מתחלפים בה מה שבימין בשמאל ומה שבשמאל בימין, אז עוד הוא בקלקולו, שעוד לא עשה תשובה, וחזר ושבר חתיכת קרח, שהפסיק בינו ובין העבירה, כדי לעבור העבירה."],[66,"תרין קמיטין על וכו':","ב' קמטים על ראש עינו, וג' למטה. וברגל שמאל באצבע האמצעי שש שערות, ובזמן אחר חמש, ועתה יש בו שש כי שערה אחת קטנה ביניהן. עינים שחורות, וגבות עיניו גדולות, שיש בהן הרבה שערות אלו על אלו, ואלו עינים השחורות והירוקות הולכות בתוכם והירוקות שקועות יותר. זה יש לו חמשה קוים במצח. שנים העוברים מצד אל צד, וג' שאינם עוברים. ע\"כ רזין דרזין. (חסר הסיום. ועי' בזהר חדש דף ל\"ה)."],[67,"בחדש השלישי לצאת וגו':","שבחדש הזה שולט אוריאל הממונה הגדול. כי ניסן אייר סיון, הם כנגד חג\"ת, שבחסד שולט מיכאל, ובגבורה גבריאל, ובתפארת אוריאל. ושלוש מאות וששים וחמשה רבבות מחנות עמו, כמספר ימות השנה, שהם שס\"ה ימות החמה. וכולם יש להם שס\"ה מפתחות של האורות, מאור ההוא היוצא מתוך חשמל העליון הפנימי הגנוז והסתום. שסודות האותיות הקדושות העליונות של השם הקדוש תלויות בו."]],[[2,"","עַד כָּאן כָּל אוֹתָם סוֹדוֹת שֶׁל תּוֹלְדוֹת אָדָם, שֶׁהֵם תּוֹלָדוֹת שֶׁנּוֹלְדוּ בוֹ מִזְּמַן לִזְמַן כְּפִי דַרְכֵי הָאָדָם. אַשְׁרֵי חֶלְקָם שֶׁל אֵלּוּ שֶׁיּוֹשְׁבִים לִפְנֵי מוֹרֵנוּ וְזָכוּ לִשְׁמֹעַ מִפִּיו סוֹדוֹת הַתּוֹרָה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם לָעוֹלָם הַבָּא! אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵיכֶם הַחֲבֵרִים שֶׁכָּל הַסּוֹדוֹת לֹא נִסְתְּרוּ מִכֶּם, כַּמָּה מְקוֹמוֹת עֶלְיוֹנִים מְזֻמָּנִים לָכֶם לָעוֹלָם הַבָּא."],[3,"","פָּתַח וְאָמַר, וְאַתָּה תֶחֱזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים אַנְשֵׁי אֱמֶת שּנְאֵי בָצַע. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל וְאַתָּה תֶחֱזֶה, לֹא כָתוּב תִּבְחַר אֶלָּא תֶחֱזֶה, לְפִי מַרְאֵה הָעֵינַיִם. בַּמֶּה? בַּדְּיוֹקָן שֶׁל אָדָם בְּשֵׁשֶׁת הַצְּדָדִים הַלָּלוּ שֶׁאֲמַרְתֶּם, וְהַכֹּל בַּפָּסוּק הַזֶּה. וְאַתָּה תֶחֱזֶה - אַחַת, בַּשֵּׂעָר. מִכָּל הָעָם - שְׁתַּיִם, בַּמֵּצַח. אַנְשֵׁי חַיִל - שָׁלֹשׁ, בַּפָּנִים. יִרְאֵי אֱלֹהִים - אַרְבַּע, בָּעֵינַיִם. אַנְשֵׁי אֱמֶת - חָמֵשׁ, בַּשְּׂפָתַיִם. שּנְאֵי בָצַע - שֵׁשׁ, בַּיָּדַיִם, בְּשִׂרְטוּטֵיהֶם."],[4,"","שֶׁאֵלּוּ הֵם הַסִּימָנִים לָדַעַת בָּהֶם בְּנֵי אָדָם לְאוֹתָם שֶׁרוּחַ הַחָכְמָה שׁוֹרָה עֲלֵיהֶם. וְעִם כָּל זֶה, מֹשֶׁה לֹא הִצְטָרֵךְ לָזֶה, אֶלָּא מַה כָּתוּב? וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חַיִל מִכָּל יִשְׂרָאֵל, מִשּׁוּם שֶׁרוּחַ הַקֹּדֶשׁ הָיְתָה בָּאָה אֵלָיו וּמוֹדִיעָה לוֹ, וּבָהּ הָיוּ רוֹאִים הַכֹּל."],[5,"","מִנַּיִן לָנוּ? שֶׁכָּתוּב כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי. בָּאִים אֵלַי לֹא כָתוּב, אֶלָּא בָּא אֵלַי. זוֹ רוּחַ הַקֹּדֶשׁ שֶׁהָיְתָה בָּאָה אֵלָיו, וּבָהּ הָיָה יוֹדֵעַ. וְלֹא הִצְטָרֵךְ לְכָל זֶה לְהִתְבּוֹנֵן וּלְעַיֵּן, אֶלָּא לְפִי שָׁעָה הָיָה מֹשֶׁה יוֹדֵעַ."],[6,"","כְּמוֹ זֶה יָדַע שְׁלֹמֹה הַמֶּלֶךְ, יָדַע בְּכִסְאוֹ, שֶׁרוּחַ הַקֹּדֶשׁ שָׁרְתָה עָלָיו. שֶׁכָּל מִי שֶׁקָּרַב לְכִסְאוֹ, פַּחַד וְאֵימָה נָפְלוּ עָלָיו, וּבוֹ הָיָה דָּן דִּין בְּלִי עֵדוּת, מִשּׁוּם שֶׁהַדְּיוֹקְנָאוֹת הָיוּ בְּכִסְאוֹ, וְכָל מִי שֶׁקָּרַב בְּשֶׁקֶר, אוֹתוֹ הַדְּיוֹקָן מְכַשְׁכֵּשׁ, וְהָיָה שְׁלֹמֹה הַמֶּלֶךְ יוֹדֵעַ שֶׁבָּא בְשֶׁקֶר. לָכֵן אֵימַת הַכִּסֵּא הָיְתָה נוֹפֶלֶת עַל הַכֹּל, וְכֻלָּם נִמְצְאוּ צַדִּיקִים לְפָנָיו."],[7,"","מֶלֶךָ הַמָּשִׁיחַ בְּרֵיחַ, כְּמוֹ שֶׁנֶּאֱמַר (שם יא) וַהֲרִיחוֹ בְּיִרְאַת ה' וְלֹא לְמַרְאֵה עֵינָיו יִשְׁפֹּט וְגוֹ'. וּשְׁלֹשֶׁת אֵלֶּה דָּנוּ אֶת הָעוֹלָם בְּלֹא עֵדִים וְהַתְרָאָה. שְׁאָר בְּנֵי הָעוֹלָם עַל פִּי עֵדִים, עַל מַאֲמַר הַתּוֹרָה. חֲכָמִים שֶׁמַּכִּירִים בְּאוֹתָם דְּיוֹקְנָאוֹת, עֲלֵיהֶם לְהַזְהִיר אֶת בְּנֵי הָעוֹלָם וְלָתֵת רְפוּאָה לִבְנֵי אָדָם וּלְרַפֵּא אֶת נַפְשָׁם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא!"],[67,"","בַּחֹדֶשׁ הַשְּׁלִישִׁי לְצֵאת בְּנֵי יִשְׂרָאֵל וְגוֹ'. שֶׁשּׁוֹלֵט בּוֹ אוֹרִיאֵ\"ל, מְמֻנֶּה גָּדוֹל, וּשְׁלֹשׁ מֵאוֹת וְשִׁשִׁים וְחָמֵשׁ רִבּוֹא מַחֲנוֹת עִמּוֹ כְּחֶשְׁבּוֹן יְמוֹת הַשָּׁנָה, וּלְכֻלָּם יֵשׁ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מַפְתְּחוֹת שֶׁל אוֹרוֹת, מֵאוֹתוֹ הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַחַשְׁמַל הָעֶלְיוֹן הַפְּנִימִי הַגָּנוּז וְהַנִּסְתָּר שֶׁסּוֹדוֹת שֶׁל אוֹתִיּוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ תְּלוּיִים בּוֹ."]]],[["וְאִיהוּ רָזָא דְּאִישׁ תָּם, מָארֵיהּ דְּבֵיתָא, אִישׁ הָאֱלֹהִים. תָּם: דְּתַמָּן סִיּוּמָא וְקִשְׁרָא דִּתְפִילִין, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם הֲוָה. וּבְדִיּוּקְנֵיהּ, קַיְּימָא רָזָא דְּחַשְׁמַל פְּנִימָאָה עִלָּאָה טָמִיר וְגָנִיז. וְכָל נְהוֹרִין סְתִימִין עִלָּאִין נָקִיט אִיהוּ, וְנַפְקֵי מִנֵּיהּ, וְכֻלְּהוּ מַשְׁרְיָין נַקְטֵי אִינּוּן מַפְתְּחָן דְּהַהוּא נְהוֹרָא דְּנָפִיק מִגּוֹ חַשְׁמַל.","וְהַהוּא נְהוֹרָא, כָּלִיל בִּתְרֵין נְהוֹרִין, וְאִינּוּן חַד. נְהוֹרָא קַדְמָאָה, אִיהוּ נְהוֹרָא חִוָּורָא, דְּלָא שַׁלְטָא בֵּיהּ עֵינָא, וְדָא אִיהוּ נְהוֹרָא דְּגָנִיז לְצַדִּיקַיָּיא. כְּמָה דְאַתְּ אָמֵר (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וְגו'. נְהוֹרָא תִּנְיָינָא, אִיהוּ נְהוֹרָא מְנַצְּצָא מְלַהֲטָא, כְּגָוַון סוּמָק. וְאִתְכְּלִילוּ תְּרֵין נְהוֹרִין כְּחַד, וַהֲווּ חַד.","וְהַאי אוריא\"ל רַב מְמָנָא, וְכָל אִינּוּן מַשִׁירְיָין, נַטְלֵי הַהוּא נְהוֹרָא, וּבְגִין דְּכָלִיל בִּתְרֵין, אִקְרֵי תְּאוֹמִי\"ם. וְעַל דָּא שַׁלְטָא בֵּיהּ, הַהוּא מַזָּלָא דְּאִקְרֵי בְּרָזָא דִּילֵיהּ תְּאוֹמִים, וּבֵיהּ אִתְיְהִיבַת אוֹרַיְיתָא. וּמִכָּאן אִתְמַשְּׁכָאן דַּרְגִּין לְתַתָּא, עַד דְּסַלְּקִין בִּשְׁמָהָן, (ס\"א לאנהגא) לְאַנְהָרָא עָלְמָא.","כָּל שְׁאַר מַזָּלֵי, לֵית לוֹן פֶּה וְלָשׁוֹן, וְהַאי אִית לֵיהּ פֶּה וְלָשׁוֹן כְּלִילָן כַּחֲדָא. וְעַל דָּא בְּאוֹרַיְיתָא, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וְלַיְלָה כְּתִיב. יוֹמָם, לָקֳבֵל לָשׁוֹן. לַיְלָה, לָקֳבֵל פֶּה. וְכֹלָּא כָּלִיל כַּחֲדָא. וּבְכֹלָּא סָלִיק תְּאוֹמִים.","תוֹמִים כְּתִיב, וְעַל רָזָא דָּא כְּתִיב תוֹמִים, (בראשית כ״ה:כ״ד) וְהִנֵּה תוֹמִים בְּבִטְנָהּ. אִי תֵּימָא דִּבְגִין תַּרְוַויְיהוּ קָאָמַר. לָאו הָכִי, דְּהָא עֵשָׂו לָא סָלִיק בְּרָזָא דָּא. אֶלָּא בְּגִין יַעֲקֹב קָאָמַר, וּשְׁבָחָא דָּא, דְּהֲוָה בִּמְעָהָא דְּהַהִיא צַדֶּקֶת, קָא מְשַׁבַּח קְרָא. וּבְגִין דְּהֲוָה תַּמָּן הַהוּא רָשָׁע, אִסְתַּלָּק מִתַּמָּן אָלֶף.","וְכֹלָּא רָזָא חֲדָא. יַעֲקֹב נָטִיל בְּרָזָא דִּילֵיהּ, תְּרֵין יַרְחִין ניס\"ן ואיי\"ר, וְאִתְכְּלִיל אִיהוּ בְּרָזָא דְּסִיוָן, דְּאִיהוּ תְּאוֹמִים. עֵשָׂו, נָטִיל בְּרָזָא דִּילֵיהּ, תְּרֵין יַרְחִין תַּמּוּ\"ז אָ\"ב, וְאִיהוּ לָא אִשְׁתְּכַח, וְאִתְאֲבִיד, דְּהָא אֱלוּ\"ל לָאו דִּילֵיהּ הוּא, וַאֲפִילּוּ אָ\"ב, ט' יוֹם אִינּוּן דִּילֵיהּ, וְלָא יַתִּיר, וְאִתְאֲבִיד, וְלָא אִשְׁתְּכַח, וְלָאו אִיהוּ בְּרָזָא דִּתְאוֹמִים, אֶלָּא אִתְפְּרַשׁ לְחוֹדֵיהּ, וְסָטָא לְסִטְרָא אַחֲרָא בַּאֲפִיסָה וּשְׁמָמוּ, כְּמָה דְאַתְּ אָמֵר, (תהילים ט׳:ז׳) הָאוֹיֵב תַּמּוּ חֳרָבוֹת לָנֶצַח.","וּבְגִין דְּיַעֲקֹב אִיהוּ תְּאוֹמִים, אִתְיְהִיבַת אוֹרַיְיתָא לִבְנוֹי בַּחֹדֶשׁ תְּאוֹמִים, וְאוֹרַיְיתָא בְּרָזָא דִּתְאוֹמִים, תּוֹרָה שֶׁבִּכְתָב, וְתוֹרָה שֶׁבְּעַל פֶּה. בַּחֹדֶשׁ תְּלִיתָאֵי, לְעַם תְּלִיתָאֵי, בְּדַרְגִּין תְּלִיתָאִין, תּוֹרָה תְּלִיתָאֵי: תּוֹרָה, נְבִיאִים, וּכְתוּבִים. וְכֹלָּא חַד.","בַּחֹדֶשׁ הַשְׁלִישִׁי וְגוֹ'. פַּרְשְׁתָּא דָּא בְּהַאי קְרָא אוּקְמוּהָ לֵיהּ לְעֵילָּא. תָּאנִי רַבִּי חִיָּיא, בְּהַהוּא זִמְנָא דְּמָטוּ יִשְׂרָאֵל לְטוּרָא דְּסִינַי, כָּנִישׁ לְהוּ קוּדְשָׁא בְּרִיךְ הוּא לְזַרְעִיין דְּיִשְׂרָאֵל, וְאַשְׁגַּח לֵיהּ בְּכֻלְּהוּ, וְלָא אַשְׁכַּח בְּכֻלְּהוּ זַרְעָא דְּיִשְׂרָאֵל פַּסְלוּ, אֶלָּא כֻּלְּהוּ זַרְעָא קַדִּישָׁא, כֻּלְּהוּ בְּנֵי קְשׁוֹט.","בְּהַהוּא זִמְנָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, הַשְׁתָּא אֲנָא בָּעֵי לְמֵיהָב אוֹרַיְיתָא לְיִשְׂרָאֵל, מָשִׁיךְ לְהוּ בִּרְחִימוּתָא דַּאֲבָהָן, בִּרְחִימוּתָא דְּרָחִימְנָא לְהוּ, וּבְאַתְוָון דַּעֲבָדִית לְהוּ. וְאַתְּ הֲוֵי לִי שְׁלוּחָא, וְאָתִיב מִלִּין אִלֵּין. אָמַר ר' יוֹסִי אָמַר ר' יְהוּדָה, כַּךְ אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, בְּמִלָּה דָּא הוֵי לִי שְׁלִיחָא מְהֵימָנָא, לְאַמְשָׁכָא יִשְׂרָאֵל אֲבַתְרָאי.","(שמות י״ט:ג׳) וּמֹשֶׁה עָלָה אֶל הָאֱלהִים וַיִּקְרָא אֵלָיו יְיָ' מִן הָהָר וְגוֹ'. וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים, לְאַתְרָא דִּפְרִישָׂן גַּדְפּוֹי דִּשְׁכִינְתָּא, כְּמָה דְאַתְּ אָמֵר (תהילים י״ח:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד וְגוֹ'.","תָּאנָא אָמַר ר' יְהוּדָה, כָּל זִמְנָא דִּגְלוּפֵי מַלְכָּא עִלָּאָה מִתְיַשְּׁרָן בְּאַתְרַיְיהוּ, עָלְמִין כֻּלְּהוּ בְּחִידוּ, וְכָל עוֹבָדִין מִתְיַשְּׁרָן בְּקִיּוּמַיְיהוּ. (מאן כל עובדין מתיישרן בקיומייהו) כְּמָה דְאַתְּ אָמֵר, (שמות לה) אֶת מַעֲשֵׂה יְיָ' כִּי נוֹרָא הוּא. מַאי כִּי נוֹרָא הוּא. אָמַר ר' אֶלְעָזָר, שְׁלִימוּ דְּכֹלָּא. כְּמָה דְאַתְּ אָמֵר (דברים י׳:י״ז) הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא. מַאי וְהַנּוֹרָא. דָּא יַעֲקֹב. וּכְתִיב, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם, כְּתַרְגּוּמוֹ, גְּבַר שְׁלִים. שְׁלִים בְּכֹלָּא. כַּךְ כָּל עוֹבָדִין דְּקוּדְשָׁא בְּרִיךְ הוּא, שְׁלֵימִין בִּשְׁלִימוּ, בְּקִיּוּמָא שְׁלִים."],[[0,"ואיהו רזא דאיש תם וכו':","והוא סוד, איש תם, שנקרא יעקב שה\"ס תפארת, שפירושו. אדון הבית איש האלקים. פירוש. כי המלכות שמחזה ולמעלה נקראת תם, ויעקב בעלה של המלכות, ע\"כ נקרא איש תם, שהוא בעלה ואישה. \u0003תם,\u0004 הוא מלשון שלימות, כי שם הסיום של קשר של תפלין. שה\"ס המלכות הנקראת לאה. ויעקב \u0003איש\u0004 תם היה, דהיינו אישה כנ\"ל. ובצורתו עומד סוד חשמל הפנימי העליון המכוסה וגנוז, וכל האורות הסתומים העליונים הוא אוחז וממנו הם יוצאים, וכל המחנות של המלאך אוריאל הנזכר, אוחזים אלו המפתחות של אור ההוא היוצא מתוך החשמל."],[1,"וההוא נהורא כליל וכו':","ואור ההוא כלול בב' אורות של ימין ושמאל, והם בו אור אחד. אור הראשון, הוא אור לבן שאין העין שולטת בו, וזה הוא אור הגנוז לצדיקים, כמש\"א, אור זרוע לצדיק וגו'. אור השני הוא אור נוצץ ולוהט כמראה אדום. שה\"ס אור השמאל. ונכללו ב' האורות בו כאחד, והיו אחד."],[2,"והאי אוריאל רב וכו':","ואוריאל הזה הממונה הגדול, וכל אלו המחנות שעמו, לוקחים את אור הזה, ומשום שכלול משנים, נקרא תאומים. ועל כן שולט בו בחדש הזה מזל ההוא הנקרא בסוד שלו, תאומים ובו ניתנה התורה. ומכאן נמשכות המדרגות למטה עד שעולות בשם להאיר את העולם."],[3,"כל שאר מזלי וכו':","כל שאר המזלות, השולטים בחדשים האחרים, אין להם פה ולשון, ומזל הזה תאומים, יש לו פה ולשון כלולים יחד, ועל כן בתורה, והגית בו יומם ולילה כתוב, יומם כנגד לשון, שהוא ז\"א, לילה כנגד פה שהוא מלכות. והכל כלול יחד. ובהכל עולה סוד התאומים."],[4,"תומים כתיב, ועל וכו':","תומים כתוב, חסר \u0003א'\u0004, ועל סוד זה כתוב תומים, והנה תומים בבטנה. אם תאמר שבשביל שניהם, יעקב ועשו, אומר תומים. אינו כן, כי עשו אינו עולה בסוד הזה, אלא בשביל יעקב לבדו אומר תומים, כי יעקב ה\"ס קו האמצעי הכולל ב' אורות, ימין ושמאל, ועל שם ב' אורות אלו נקרא תומים, ואוה\"כ, והנה \u0003תומים\u0004 שהוא יעקב \u0003בבטנה,\u0004 ושבח הזה, שהיה בבטן של צדקת ההיא, משבח הכתוב. ומשום שהיה שם אותו רשע, עשו, נסתלק משם \u0003א'\u0004 וכתוב, תומים בלי \u0003א'.\u0004"],[5,"וכלא רזא חדא וכו':","והכל הוא סוד אחד. יעקב לוקח בסוד שלו, שה\"ס ת\"ת קו אמצעי, ב' חדשים, ניסן ואייר, והוא נכלל בסוד חדש סיון, שהוא מזל תאומים. כלומר שלהיותו נכלל בחודש סיון שהוא כולל ב' החדשים ניסן אייר, שהם ימין ושמאל, שע\"כ נקרא מזל תאומים, נמצא גם יעקב הכלול בו, לוקח ב' חדשים אלו. עשו לוקח בסוד שלו, ב' חדשים, תמוז אב, והוא לא נמצא בקו אמצעי שהוא אלול, ונאבד, משום שאלול אינו שלו. ואפילו חדש אב, ט' ימים בלבד המה שלו, ולא יותר. וע\"כ נאבד ואינו נמצא, והוא אינו בסוד תאומים שהוא קו אמצעי, אלא נפרד לבדו וסר לצד האחר באפס ושממה. כש\"א האויב תמו חרבות לנצח."],[6,"ובגין דיעקב איהו וכו':","ומשום שיעקב הוא תאומים, ניתנה התורה לבניו בחדש תאומים. והתורה הוא בסוד תאומים, שהיא תורה שבכתב, ותורה שבעל פה. וניתנה בחדש השלישי, לעם השלישי, שנכלל במדרגות שלש, דהיינו שלשה אבות. תורה משולשת, שהיא תורה נביאים וכתובים. והכל אחד."],[7,"בחדש השלישי וגו':","פרשה זו במקרא הזה כבר העמידוהו למעלה. תאני ר' חייא, בזמן ההוא שהגיעו ישראל להר סיני אסף הקב\"ה לזרע ישראל והסתכל בכולם ולא מצא פסול בכל זרע ישראל. אלא כולם זרע קדוש, כולם בני אמת."],[8,"בההוא זמנא אמר וכו':","בזמן ההוא, אמר הקב\"ה למשה, עתה אני רוצה לתת התורה לישראל, משוך אותם באהבת האבות, באהבה שאני אוהב אותם, ובאותות שעשיתי להם. ואתה תהיה לי שליח, והשב להם דברים האלו. אמר ר' יוסי אמר ר' יהודה, כך אמר הקב\"ה למשה, בדבר זה תהיה לי שליח נאמן, להמשיך את ישראל אחרי."],[9,"ומשה עלה אל האלקים ויקרא וגו':","ומשה עלה אל האלקים, פירושו, שעלה למקום שנפרשים כנפי השכינה, כש\"א ויט שמים וירד וגו'."],[10,"תאנא אמר ר' יהודה וכו':","למדנו, אר\"י, כל זמן שחקיקות המלך העליון, שהוא חקיקת המסך דחירק, שבקו האמצעי, שהוא ז\"א, מתישרים במקומם, דהיינו שמכריעים בין ימין לשמאל, העולמות כולם הם בשמחה, וכל המעשים מתישרים על קיומם. כש\"א, את מעשה ה' כי נורא הוא. מהו כי נורא הוא. אמר ר' אלעזר הוא שלימות הכל. כש\"א, האל הגדול הגבור והנורא, מהו והנורא, זה יעקב, דהיינו קו אמצעי. וכתוב, ויעקב איש תם, כתרגומו, איש שלם. שלם בכל. כך כל מעשה הקב\"ה, שלימים בשלימות בקיום שלם."]],[[0,"","וְהוּא סוֹד שֶׁל אִישׁ תָּם, בַּעַל הַבַּיִת, אִישׁ הָאֱלֹהִים. תָּם - שֶׁשָּׁם סִיּוּם וְקֶשֶׁר שֶׁל תְּפִלִּין. וְיַעֲקֹב הָיָה אִישׁ תָּם, וּבִדְיוֹקְנוֹ עוֹמֵד סוֹד הַחַשְׁמַל הַפְּנִימִי הָעֶלְיוֹן הַטָּמִיר וְהַגָּנוּז. וְכָל הָאוֹרוֹת הַנִּסְתָּרִים הָעֶלְיוֹנִים הוּא לוֹקֵחַ, וְיוֹצְאִים מִמֶּנּוּ, וְכָל הַמַּחֲנוֹת לוֹקְחִים אוֹתָם מַפְתְּחוֹת שֶׁל אוֹתוֹ הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַחַשְׁמַל."],[1,"","וְאוֹתוֹ הָאוֹר כָּלוּל בִּשְׁנֵי אוֹרוֹת, וְהֵם אֶחָד. אוֹר רִאשׁוֹן הוּא אוֹר לָבָן שֶׁלֹּא שׁוֹלֶטֶת בּוֹ הָעַיִן, וְזֶהוּ הָאוֹר הַגָּנוּז לַצַּדִּיקִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק וְגוֹ'. אוֹר שֵׁנִי הוּא אוֹר נוֹצֵץ לוֹהֵט כְּצֶבַע אָדם, וְנִכְלְלוּ שְׁנֵי אוֹרוֹת כְּאֶחָד וְהָיוּ אֶחָד."],[2,"","וְהָאוֹרִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל הַזֶּה וְכָל אוֹתָם מַחֲנוֹת נוֹטְלִים אוֹתוֹ הָאוֹר, וּמִשּׁוּם שֶׁכָּלוּל בִּשְׁנַיִם נִקְרָא תְּאוֹמִי\"ם. וְעַל זֶה שׁוֹלֵט בּוֹ אוֹתוֹ הַמַּזָּל שֶׁנִּקְרָא בַּסּוֹד שֶׁלּוֹ תְּאוֹמִים, וּבוֹ נִתְּנָה תוֹרָה, וּמִכָּאן נִמְשָׁכוֹת דְּרָגוֹת לְמַטָּה, עַד שֶׁעוֹלִים בְּשֵׁמוֹת (להנהיג) לְהָאִיר אֶת הָעוֹלָם."],[3,"","לְכָל שְׁאָר הַמַּזָּלוֹת אֵין לָהֶם פֶּה וְלָשׁוֹן, וְלָזֶה יֵשׁ פֶּה וְלָשׁוֹן כְּלוּלִים כְּאֶחָד, וְעַל זֶה בַּתּוֹרָה, (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה כָּתוּב. יוֹמָם - כְּנֶגֶד לָשׁוֹן. לַיְלָה - כְּנֶגֶד פֶּה. וְהַכֹּל כָּלוּל כְּאֶחָד, וּבַכֹּל עוֹלֶה תְּאוֹמִים."],[4,"","תוֹמִים כָּתוּב, וְעַל סוֹד זֶה כָּתוּב תוֹמִים, (בראשית כה) וְהִנֵּה תוֹמִם בְּבִטְנָהּ. אִם תֹּאמַר שֶׁבִּשְׁבִיל שְׁנֵיהֶם הוּא אָמַר - לֹא כָּךְ, שֶׁהֲרֵי עֵשָׂו לֹא עָלָה בְּסוֹד זֶה. אֶלָּא בִּשְׁבִיל יַעֲקֹב הוּא אָמַר, וְשֶׁבַח זֶה שֶׁהָיָה בְּמֵעֶיהָ שֶׁל אוֹתָהּ הַצַּדֶּקֶת מְשַׁבֵּחַ הַכָּתוּב. וּמִשּׁוּם שֶׁהָיָה שָׁם אוֹתוֹ רָשָׁע, הִסְתַּלֵּק מִשָּׁם אָלֶף."],[5,"","וְהַסֹל סוֹד אֶחָד. יַעֲקֹב נָטַל בַּסּוֹד שֶׁלּוֹ שְׁנֵי חֳדָשִׁים - נִיסָ\"ן וְאִיָּ\"ר, וְהוּא נִכְלָל בַּסּוֹד שֶׁל סִיוָן שֶׁהוּא תְאוֹמִים. עֵשָׂו נָטַל בַּסּוֹד שֶׁלּוֹ שְׁנֵי חֳדָשִׁים - תַּמּוּ\"ז וְאָ\"ב, וְהוּא לֹא נִמְצָא וְנֶאֱבָד, שֶׁהֲרֵי אֱלוּ\"ל אֵינוֹ שֶׁלּוֹ, וַאֲפִלּוּ בְּאָב תִּשְׁעָה יָמִים הֵם שֶׁלּוֹ וְלֹא יוֹתֵר, וְנֶאֱבָד וְלֹא נִמְצָא, וְאֵינוֹ בַּסּוֹד שֶׁל תְּאוֹמִים, אֶלָּא נִפְרַד לְבַדּוֹ וְסָטָה לְצַד אַחֵר בְּאֶפֶס וּשְׁמָמָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ט) הָאוֹיֵב תַּמּוּ חֳרָבוֹת לָנֶצַח."],[6,"","וּמִשּׁוּם שֶׁיַּעֲקֹב הוּא תְאוֹמִים, נִתְּנָה תוֹרָה לְבָנָיו בְּחֹדֶשׁ תְּאוֹמִים, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, בַּחֹדֶשׁ הַשְּׁלִישִׁי, לָעָם הַשְּׁלִישִׁי, בִּדְרָגוֹת שְׁלִישִׁיּוֹת, תּוֹרָה מְשֻׁלֶּשֶׁת - תּוֹרָה נְבִיאִים וּכְתוּבִים. וְהַכֹּל אֶחָד."],[7,"","בַּחֹדֶשׁ הַשְּׁלִישִׁי וְגוֹ'. פָּרָשָׁה זוֹ בְּפָסוּק זֶה פֵּרְשׁוּ אוֹתָהּ לְמַעְלָה. שָׁנָה רַבִּי חִיָּיא, בְּאוֹתוֹ זְמַן שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי, כִּנֵּס אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת זֶרַע יִשְׂרָאֵל וְהִשְׁגִּיחַ בָּהֶם בְּכֻלָּם, וְלֹא מָצָא בְּכָל זֶרַע יִשְׂרָאֵל פְּסוּל, אֶלָּא כֻּלָּם זֶרַע קֹדֶשׁ, כֻּלָּם בְּנֵי אֱמֶת."],[8,"","בְּאוֹתוֹ זְמַן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: עַכְשָׁו אֲנִי רוֹצֶה לָתֵת תּוֹרָה לְיִשְׂרָאֵל, מְשֹׁךְ אוֹתָם בְּאַהֲבָה שֶׁל אָבוֹת, בָּאַהֲבָה שֶׁאֲנִי אוֹהֵב אוֹתָם וּבָאוֹתוֹת שֶׁעָשִׂיתִי לָהֶם, וְאַתָּה תִּהְיֶה לִי שָׁלִיחַ וְהָשֵׁב הַדְּבָרִים הַלָּלוּ. אָמַר רַבִּי יוֹסֵי אָמַר רַבִּי יְהוּדָה, כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: בְּדָבָר זֶה תִּהְיֶה לִי שָׁלִיחַ נֶאֱמָן לִמְשֹׁךְ אֶת יִשְׂרָאֵל אַחֲרַי."],[9,"","וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וַיִּקְרָא אֵלָיו ה' מִן הָהָר וְגוֹ'. וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים - לַמָּקוֹם שֶׁפְּרוּשׂוֹת כַּנְפֵי הַשְּׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (שם יח) וַיֵּט שָׁמַיִם וַיֵּרַד וְגוֹ'."],[10,"","שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, כָּל זְמַן שֶׁחֲקִיקוֹת הַמֶּלֶךְ הָעֶלְיוֹן מִתְיַשְּׁרוֹת בִּמְקוֹמָן, כָּל הָעוֹלָמוֹת בְּשִׂמְחָה וְכָל הַמַּעֲשִׂים מִתְיַשְּׁרִים עַל קִיּוּמָם, (מי כל המעשים המתישרים על קיומם) כְּמוֹ שֶׁנֶּאֱמַר (שמות לד) אֶת מַעֲשֵׂה ה' כִּי נוֹרָא הוּא. מַה זֶּה כִּי נוֹרָא הוּא? אָמַר רַבִּי אֶלְעָזָר, שְׁלֵמוּת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברים י) הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא. מַה זֶּה וְהַנּוֹרָא? זֶה יַעֲקֹב. וְכָתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם, כְּתַרְגּוּמוֹ - אָדָם שָׁלֵם. שָׁלֵם בַּכֹּל. כָּךְ כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלֵמִים בִּשְׁלֵמוּת בְּקִיּוּם שָׁלֵם."]]],[["תַּנְיָא, רַבִּי יוֹסִי אוֹמֵר, יוֹמָא חַד הֲוָה קָאִימְנָא קָמֵיהּ דְּר' יְהוּדָה סָבָא, שָׁאִילְנָא לֵיהּ, מַאי דִּכְתִּיב, (בראשית כ״ח:י״ז) וַיִּירָא וַיֹּאמַר מַה נּוֹרָא וְגוֹ'. מַאי קָא חָמָא, דְּקָאָמַר דְּאִיהוּ נּוֹרָא. אָמַר לִי, חָמָא שְׁלִימוּ דִּמְהֵימָנוּתָא קַדִּישָׁא, דְּהֲוָה שְׁכִיחַ בְּהַהוּא אֲתָר, כְּגַוְונָא דִּלְעֵילָּא. וּבְכָל אֲתָר דְּהַוִי שְׁלֵימוּתָא שְׁכִיחַ, אִקְרֵי נוֹרָא.","אֲמֵינָא לֵיהּ, אִי הָכִי, אֲמַאי תַּרְגּוּמוֹ דְּחִילוּ, וְלָא שְׁלִים. אָמַר לִי, לֵית דְּחִילוּ אֶלָּא בְּאֲתָר דְּהַוְי שְׁלֵימוּתָא שְׁכִיחַ, וּבְכָל אֲתָר דְּהַוְי שְׁלֵימוּתָא שְׁכִיחַ, אִתְקְרֵי נוֹרָא. דִּכְתִּיב, (תהלים לה) יְראוּ אֶת יְיָ' קְדוֹשָׁיו כִּי אֵין מַחְסוֹר לִירֵאָיו, מִמַּשְׁמַע דְּקָאָמַר כִּי אֵין מַחְסוֹר, בַּאֲתָר דְּלֵית מַחְסוֹר, שְׁלֵימוּתָא שְׁכִיחַ.","תָּאנָא (משלי ל׳:ד׳) מִי עָלָה שָׁמַיִם וַיֵּרַד, אָמַר ר' יוֹסִי, דָּא הוּא מֹשֶׁה, דִּכְתִּיב וּמֹשֶׁה עָלָה אֶל הָאֱלהִים. מִי אָסַף רוּחַ בְּחָפְנָיו, דָּא הוּא אַהֲרֹן. דִּכְתִּיב, (ויקרא ט״ז:י״ב) וּמְלֹא חָפְנָיו קְטֹרֶת סַמִּים דַּקָּה. מִי צָרַר מַיִם בַּשִּׂמְלָה, דָּא אֵלִיָּהוּ. דִּכְתִּיב, (מלכים א י״ז:א׳) אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְּבָרִי. מִי הֵקִים כָּל אַפְסֵי אָרֶץ, דָּא הוּא אַבְרָהָם. דִּכְתִּיב בֵּיהּ, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם.","הוּא תָּנֵי הַאי, וְהוּא אָמַר, מִי עָלָה שָׁמַיִם, דָּא קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב בֵּיהּ (תהילים מ״ז:ו׳) עָלָה אֱלֹהִים בִּתְרוּעָה (מי עלה תקון בסוד את האור אמנם בתרועה וירד בסוד ויבדל, הבדילו לו אלהים בתרועה) מִי אָסַף רוּחַ בְּחָפְנָיו, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (איוב י״ב:י׳) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְגוֹ'. מִי צָרַר מַיִם בַּשִּׂמְלָה דָּא קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב בֵּיהּ (איוב כ״ו:ח׳) צוֹרֵר מַיִם בְּעָבָיו. מִי הֵקִים כָּל אַפְסֵי אָרֶץ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב בֵּיהּ, (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יְיָ' אֱלהִים אֶרֶץ וְשָׁמָיִם. תּוּ אָמַר, מִי עָלָה שָׁמַיִם וַיֵּרַד וְגוֹ', אִלֵּין אִינּוּן אַרְבַּע קְטִירֵי עָלְמָא, אֵשׁ רוּחַ מַיִם וְעָפָר.","אָמַר ר' יֵיסָא, אִתְחָזוּן מִלּוֹי דְּר' יוֹסִי, דְּלָא מִתְקַיְּימָאן. כַּד מָטוּ מִלִּין אִלֵּין לְגַבֵּיהּ דְּר' שִׁמְעוֹן, אֲנָח יְדוֹי בְּרֵישֵׁיהּ דְּר' יוֹסִי וּבַרְכֵיהּ, וְאָמַר שַׁפִּיר קָא אָמַרְתְּ, וְהָכִי הוּא. אָמַר לֵיהּ מְנָא לָךְ. אָמַר הָכִי אוֹלִיפְנָא מֵאַבָּא, דְּהֲוָה אָמַר מִשְּׁמֵיהּ דְּרַב הַמְנוּנָא סָבָא.","יוֹמָא חַד הֲוָה יָתִיב ר' שִׁמְעוֹן בְּתַרְעָא דְּצִפּוֹרִי, אָמַר לֵיהּ ר' יֵיסָא, הַאי דְּאָמַר ר' יוֹסִי, מִי עָלָה שָׁמַיִם וַיֵּרַד וְגוֹ', זִמְנָא חֲדָא אָמַר, דָּא מֹשֶׁה. לְבָתַר אָמַר, דָּא קוּדְשָׁא בְּרִיךְ הוּא. לְבָתַר אָמַר, אִלֵּין ד' קְטִירִין אֵשׁ רוּחַ מַיִם וְעָפָר. וַחֲמֵינָא לֵיהּ לְמֹר דְּבָרְכֵיהּ.","אָמַר לֵיהּ וַדַּאי שַׁפִּיר קָא אָמַר, וְהָכִי הוּא, וְכֹלָּא חַד מִלָּה, וְכֻלְּהוּ מִלֵּי אִתְקַיְימוּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ בְּחַד מַתְקְלָא סַלְּקָא. אִתְרְגִישׁ ר' יֵיסָא בְּמִלּוֹי דְּר' שִׁמְעוֹן, וְאָמַר וַדַּאי הַאי הָכִי הוּא, וְהָכִי אוֹלִיפְנָא מִקָּמֵיהּ דְּמֹר זִמְנָא אַחֲרָא. (אלה תולדות השמים והארץ בהבראם, אל תקרי בהבראם, אלא באברהם. דכתיב, (תהילים פ״ט:ג׳) כי אמרתי עולם חסד יבנה. אבל)","וְכֹלָּא שַׁפִּיר. אֲבָל סוֹפָא דִּקְרָא מַאי קָא מַיְירֵי דִּכְתִּיב, (משלי ל׳:ד׳) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵּדַע. מַה שְׁמוֹ תִּינַח, מַה שֶּׁם בְּנוֹ מַהוּ. אָמַר לֵיהּ, רָזָא דְּמִלָּה הָא אוֹלִיפְנָא לְרַ' אֶלְעָזָר בְּרִי. אָמַר לֵיהּ, לֵימָא לִי מֹר, דְּהָא בְּחֶלְמִי שָׁאִילְנָא קָמֵיהּ דְּמֹר הַאי מִלָּה, וְאָמַר לִי, וַאֲנְשִׁינָא לָהּ. אָמַר לֵיהּ, אִי אֵימָא תִּדְכַּר. אָמַר לֵיהּ וַדַּאי. דְּהָא מַה דְּאוֹלִיפְנָא קָמֵי דְּמֹר יוֹמָא דָּא אַדְכַּרְנָא.","אֲמַר לֵיהּ רָזָא דְּמִלָּה, הַיְינוּ דִּכְתִּיב, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל וּכְתִיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. וּבְרָזָא עִלָּאָה, וְהַאי אִקְרֵי בְּנוֹ. אָמַר יָנוּח דַּעְתֵּיהּ דְּמֹר, דְּהָא רָזָא דָּא יְדַעְנָא. אַדְהָכִי, לָא אִדְכַּר ר' יֵיסָא, חָלַשׁ דַּעְתֵּיהּ, אָזַל לְבֵיתֵיהּ, אַדְמוּךְ, אַחְזִיאוּ לֵיהּ בְּחֶלְמָא, חַד סִפְרָא דְּאַגַּדְתָּא, דְּהֲוָה כְּתִיב בֵּיהּ, חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ."],[[0,"תניא ר' יוסי וכו':","למדנו ר' יוסי אומר, יום אחד הייתי עומד לפני ר' יהודה הזקן, שאלתי אותו, מה שכתוב, ויירא ויאמר מה נורא וגו'. מה ראה, שאמר שהוא נורא. אמר לי, שראה השלימות של האמונה הקדושה, שהיא המלכות, שהיתה שכיח במקום הזה כעין של מעלה, ובכל מקום ששלימותו היתה נמצאת, נקרא נורא."],[1,"אמינא ליה, אי וכו':","אמרתי לו, אם כן, למה תרגומו דחילו ולא שלים. שאם נורא פירושו שלימות, היה צריך לתרגם שלים. אמר לי, אין יראה אלא במקום ששלימות נמצא, ובכל מקום שהשלימות נמצא נקרא נורא. שכתוב, יראו את ה' קדושיו כי אין מחסור ליראיו. ומשמע ממה שאומר בי אין מחסור, שיראה הוא שלימות, כי במקום שאין מחסור, יש שלימות."],[2,"תאנא, מי עלה וכו':","למדנו, מי עלה שמים וירד. אמר ר' יוסי זה הוא משה. שכתוב, ומשה עלה אל האלקים. מי אסף רוח בחפניו. זה הוא אהרן, שכתוב ומלא חפניו קטורת סמים דקה. מי צרר מים בשמלה. זה הוא אליהו, שכתוב, אם יהיה השנים האלה טל ומטר כי אם לפי דברי. מי הקים כל אפסי ארץ. זה הוא אברהם, שכתוב בו, אלה תולדות השמים והארץ בהבראם. אל תקרי בהבראם אלא באברהם."],[3,"הוא תני האי וכו':","הוא למד זה, והוא אמר. מי עלה שמים זה הקב\"ה שכתוב בו, עלה אלקים בתרועה. מי אסף רוח בחפניו, זה הקב\"ה, שכתוב, אשר בידו נפש כל חי ורוח וגו'. מי צבר מים בשמלה זה הקב\"ה, שכתוב בו צורר מים בעביו. מי הקים כל אפסי ארץ זה הקב\"ה, שכתוב בו, ביום עשות ה' אלקים ארץ ושמים. עוד אמר ר' יוסי, מי עלה שמים וירד וגו' אלו הם ד' קשרי העולם, אש רוח מים ועפר."],[4,"אמר ר' ייסא וכו':","אמר ר\"י, נראים דבריו של ר' יוסי שאינם מתקיימים, כי דבריו סותרים זה את זה. כשהגיעו דברים אלו לפני ר\"ש, הניח ידו על ראשו של ר' יוסי וברכו, ואמר, יפה אתה אומר, וכך הוא. אמר לו, מאין לך זה. אמר, כך למדתי מאבי, שהיה אמר משמו של ר' המנונא סבא."],[5,"יומא חד הוה וכו':","יום אחד היה יושב ר' שמעון בשער צפורי. אמר לו ר' ייסא, זה שאמר ר' יוסי, עלה שמים וירד, פעם אחת אמר זה משה. ואח\"כ אמר, זה הקב\"ה. ואח\"כ אמר, אלו הם ד' קשרים, אש רוח מים ועפר. וראיתי את אדוני שברכו."],[6,"אמר ליה ודאי וכו':","א\"ל ודאי יפה אמר, וכך הוא. והכל דבר אחד הוא, וכל הדברים נמצאים בהקב\"ה, וכולם במשקל אחד עולים. התרגש ר' ייסא בדבריו של ר\"ש, ואמר ודאי זה כך הוא וכך למדתי לפני אדוני בפעם אחר, אלה תולדות השמים והארץ בהבראם אל תקרי בהבראם אלא באברהם, דהיינו בחסד דז\"א, שכתוב, כי אמרתי עולם חסד יבנה. וכן שאר השמות, משה אהרן אליהו ד' יסודות ארמ\"ע. הם שמותיו של הקב\"ה."],[7,"וכלא שפיר, אבל וכו':","והכל יפה, אבל סוף הכתוב, מהו אומר, שכתוב, מה שמו ומה שם בנו כי תדע. מה שמו, צודק, אבל, מה שם בנו, מהו. אמר לו, סוד הדבר, כבר למדתי לר' אלעזר בני. אמר לו, יאמר לי אדוני, כי בחלומי שאלתי דבר זה לפני אדוני, ואמר לי, ושכחתי אותו. אמר לו אם אומר, תזכור. אמר לו ודאי, כי מה שלמדתי לפני אדוני ביום זה אני זוכר."],[8,"א\"ל רזא דמלה וכו':","אמר לו, סוד הדבר, היינו שכתוב, בני בכורי ישראל. וכתוב, ישראל אשר בך אתפאר. ובסוד עליון, שישראל פירושו תפארת, וזה נקרא בנו. אמר, ינוח דעת אדוני, כי סוד הזה אני יודע. בתוך כך לא נזכר ר' ייסא מה שאמר לו בחלום. חלש דעתו. הלך לביתו. ישן. הראו לו בחלום ספר אחד של אגדה, שהיה כתוב בו, חכמה ותפארת במקדשו."]],[[0,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, יוֹם אֶחָד הָיִיתִי עוֹמֵד לִפְנֵי רַבִּי יְהוּדָה הַזָּקֵן וְשָׁאַלְתִּי אוֹתוֹ עַל מַה שֶּׁכָּתוּב (שם כח) וַיִּירָא וַיֹּאמַר מַה נּוֹרָא וְגוֹ'. מָה רָאָה שֶׁאָמַר שֶׁהוּא נוֹרָא? אָמַר לִי, רָאָה שְׁלֵמוּת הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהָיְתָה מְצוּיָה בְּאוֹתוֹ מָקוֹם כְּמוֹ שֶׁלְּמַעְלָה, וּבְכָל מָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת נִקְרָא נוֹרָא."],[1,"","אָמַרְתִּי לוֹ, אִם כָּךְ, לָמָּה תַּרְגּוּמוֹ פַּחַד וְלֹא שָׁלֵם? אָמַר לִי, אֵין פַּחַד אֶלָּא בְּמָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת, וּבְכָל מָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת נִקְרָא נוֹרָא, שֶׁכָּתוּב (תהליםלד) יְראוּ אֶת ה' קְדשָׁיו כִּי אֵין מַחְסוֹר לִירֵאָיו. מִמַּשְׁמָע שֶׁאָמַר כִּי אֵין מַחְסוֹר - בְּמָקוֹם שֶׁאֵין מַחְסוֹר מְצוּיָה שְׁלֵמוּת."],[2,"","שָׁנִינוּ, מִי עָלָה שָׁמַיִם וַיֵּרַד - אָמַר רַבִּי יוֹסֵי, זֶהוּ מֹשֶׁה, שֶׁכָּתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. מִי אָסַף רוּחַ בְּחָפְנָיו - זֶהוּ אַהֲרֹן, שֶׁכָּתוּב (ויקרא טז) וּמְלֹא חָפְנָיו קְטֹרֶת סַמִּים דַּקָּה. מִי צָרַר מַיִם בַּשִּׂמְלָה - זֶה אֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְבָרִי. מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶהוּ אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם."],[3,"","הוּא שָׁנָה אֶת זֶה, וְהוּא אָמַר. מִי עָלָה שָׁמַיִם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (תהלים מז) עָלָה אֱלֹהִים בִּתְרוּעָה. (מיעלה, תקוןבסודאת האור. אמנם בתרועה. וירד, בסוד ויבדל. הבדילו לו אלהים בתרועה) מִי אָסַף רוּחַ בְּחָפְנָיו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (איוב יב) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְגוֹ'. מִי צָרַר מַיִם בַּשִּׂמְלָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (שם כו) צוֹרֵר מַיִם בְּעָבָיו. מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמַיִם. עוֹד אָמַר, מִי עָלָה שָׁמַיִם וַיֵּרַד וְגוֹ' - אֵלֶּה אוֹתָם אַרְבָּעָה קִשְׁרֵי הָעוֹלָם - אֵשׁ, רוּחַ, מַיִם וְעָפָר."],[4,"","אָמַר רַבִּי יֵיסָא, נִרְאִים דִּבְרֵי רַבִּי יוֹסֵי שֶׁלֹּא מִתְקַיְּמִים. כְּשֶׁהִגִּיעוּ הַדְּבָרִים הַלָּלוּ אֶל רַבִּי שִׁמְעוֹן, הִנִּיחַ יָדוֹ בְּרֹאשׁוֹ שֶׁל רַבִּי יוֹסֵי וּבֵרְכוֹ, וְאָמַר, יָפֶה אָמַרְתָּ וְכָךְ זֶה. אָמַר לוֹ, מִנַּיִן לְךְ? אָמַר לוֹ, כָּךְ לָמַדְתִּי מֵאָבִי שֶׁהָיָה אוֹמֵר מִשְּׁמוֹ שֶׁל רַב הַמְנוּנָא סָבָא."],[5,"","יוֹם אֶחָד הָיָה יוֹשֵׁב רַבִּי שִׁמְעוֹן בַּשַּׁעַר שֶׁל צִפּוֹרִי. אָמַר לוֹ רַבִּי יֵיסָא, זֶה שֶׁאָמַר רַבִּי יוֹסֵי מִי עָלָה שָׁמַיִם וַיֵּרַד - פַּעַם אַחַת אָמַר זֶה מֹשֶׁה, אַחַר כָּךְ אָמַר זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, אַחַר כָּךְ אָמַר אֵלּוּ אַרְבָּעָה קְשָׁרִים, אֵשׁ רוּחַ מַיִם וְעָפָר, וְרָאִיתִי שֶׁמּוֹרֵנוּ בֵּרְכוֹ?"],[6,"","אָמַר לוֹ, וַדַּאי שֶׁיָּפֶה אָמַר, וְכָךְ הוּא, וְהַכֹּל דָּבָר אֶחָד, וְכָל הַדְּבָרִים הִתְקַיְּמוּ בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, וְכֻלָּם עוֹלִים בְּמִשְׁקָל אֶחָד. הִתְרַגֵּשׁ רַבִּי יֵיסָא בְּדִבְרֵי רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי כָּךְ זֶה, וְכָךְ לָמַדְנוּ מִשֵּׁם מוֹרֵנוּ בְּפַעַם אַחֶרֶת. וְהַכֹּל יָפֶה. (אלה תולדות השמים והארץ בהבראם, אל תקרי בהבראם אלא באברהם, שכתוב (תהלים פט) כי אמרתי עולם חסד יבנה. אבל)"],[7,"","אֲבָל סוֹף הַכָּתוּב מַהוּ אוֹמֵר? שֶׁכָּתוּב מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. מַה שְּׁמוֹ מֵילָא, מַה זֶה מַה שֶּׁם בְּנוֹ? אָמַר לוֹ, סוֹד הַדָּבָר הֲרֵי לִמַּדְתִּי לְרַבִּי אֶלְעָזָר בְּנִי. אָמַר לוֹ, יֹאמַר לוֹ מוֹרִי, שֶׁהֲרֵי בַּחֲלוֹמִי שָׁאַלְתִּי לִפְנֵי מוֹרִי דָּבָר זֶה, וְאָמַר לִי וְשָׁכַחְתִּי אוֹתוֹ. אָמַר לוֹ, אִם אֹמַר - תִּזְכֹּר? אָמַר לוֹ, וַדַּאי, שֶׁהֲרֵי מַה שֶּׁלָּמַדְתִּי לִפְנֵי מוֹרִי, יוֹם זֶה נִזְכַּרְתִּי."],[8,"","אָמַר לוֹ, סוֹד הַדָּבָר - הַיְנוּ שֶׁכָּתוּב (שמות ו) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וּבְסוֹד עֶלְיוֹן, וְזֶה נִקְרָא בְנוֹ. אָמַר, תָּנוּחַ דַּעְתוֹ שֶׁל מוֹרִי, שֶׁהֲרֵי סוֹד זֶה יָדַעְתִי. בֵּין כָּךְ לֹא נִזְכַּר רַבִּי יֵיסָא, חָלְשָׁה דַעְתּוֹ וְהָלַךְ לְבֵיתוֹ. נִרְדַּם. הֶרְאוּ לוֹ בַּחֲלוֹם סֵפֶר אַגָּדָה אֶחָד שֶׁהָיָה כָּתוּב בּוֹ חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ."]]],[["אִתְּעַר, אָזִל לְגַבֵּיהּ דְּרַבִּי שִׁמְעוֹן, נָשַׁק יְדוֹי, אָמַר, הָכִי חֲמֵינָא בְּחֶלְמָא. זִמְנָא אַחֲרָא חֲמֵינָא בְּחֶלְמָא, חַד סִפְרָא דְּאַגַּדְתָּא דְּאַחְזִיוּ קַמָאי, וַהֲוָה כְּתִיב בֵּיהּ, חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ, חָכְמָה לְעֵילָּא, תִּפְאֶרֶת לְתַתָּא. בְּמִקְדָּשׁוֹ לְגַבַּיְיהוּ. וְהָכִי חֲמֵינָא בְּחֶלְמָא זִמְנָא חֲדָא. וְהָכִי אַשְׁכַּחְנָא בְּפוּמַאי. אֲמַר לֵיהּ ר' שִׁמְעוֹן, עַד כְּעַן רַבְיָא אַנְתְּ, לְמֵיעַל בֵּין מְחַצְּדֵי חַקְלָא, וְהָא כֹּלָּא אַחְזִיאוּ לָךְ. וְדָא הוּא דִּכְתִּיב, מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵּדַע. חָכְמָה שְׁמוֹ, תִּפְאֶרֶת בְּנוֹ.","(תנא) (שמות י״ט:ג׳) וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּזָכֵי לִיקָרָא דָּא, דְּאוֹרַיְיתָא אַסְהִיד בְּגִינֵיהּ כַּךְ. (תאני ר' יהודה) תָּא חֲזֵי, מַה בֵּין מֹשֶׁה לִשְׁאַר בְּנִי עָלְמָא. שְׁאַר בְּנֵי עָלְמָא, כַּד סַלְּקִין, סַלְּקִין לְעֻתְרָא, סַלְּקִין לִרְבּוּ, סַלְּקִין לְמַלְכוּ, אֲבָל מֹשֶׁה כַּד סָלִיק, מַה כְּתִיב בֵּיהּ, וּמֹשֶׁה עָלָה אֶל הָאֱלהִים, זַכָּאָה חוּלָקֵיהּ.","ר' יוֹסִי אָמַר, מִכָּאן אָמְרוּ חַבְרַיָּא, הַבָּא לִיטָהֵר מְסַיְּיעִין אוֹתוֹ, דִּכְתִּיב וּמֹשֶׁה עָלָה אֶל הָאֱלהִים. מַה כְּתִיב בַּתְרֵיהּ, וַיִּקְרָא אֵלָיו יְיָ'. דְּמַאן דְּבָעֵי לְאִתְקָרְבָא, מְקָרְבִין לֵיהּ.","וַיִּקְרָא אֵלָיו יְיָ' מִן הָהָר לֵאמֹר כֹּה תֹאמַר לְבֵית יַעֲקֹב וְגוֹ'. ר' יִצְחָק פָּתַח, (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכּוֹן חֲצֵרֶיךָ, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ, וְקָרִיב לֵיהּ, לְמִשְׁרֵי בְּגוֹ הֵיכָלָא קַדִּישָׁא, דְּכָל מַאן דְּאִיהוּ אִתְרְעֵי בֵּיהּ לְפוּלְחָנֵיהּ, רָשִׁים הוּא מֵרְשִׁימִין דִּלְעֵילָּא, לְמִנְדַּע דְּהָא הוּא אִתְבָּחַר מִקַּמֵיהּ דְּמַלְכָּא קַדִּישָׁא עִלָּאָה, לְמִשְׁרֵי בִּמְדוֹרוֹי. וְכָל מַאן דְּאִשְׁתְּכַח בֵּיהּ הַהוּא רְשִׁימָא, אַעְבַּר בְּכָל תַּרְעִין דִּלְעֵילָּא, וְלֵית דְּיִמְחֵי בִּידוֹי.","ר' יְהוּדָה אָמַר, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּעָלֵיהּ כְּתִיב אַשְׁרֵי תִּבְחַר וּתְקָרֵב, וּכְתִיב בֵּיהּ (שמות כ״ד:ב׳) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל יְיָ' וְהֵם לא יִגָשׁוּ. כֹּה תֹאמַר לְבֵית יַעֲקֹב: אִלֵּין נוּקְבֵי, וְתַגֵּיד לִבְנִי יִשְׂרָאֵל: אִלֵּין דּוּכְרִין.","ר' שִׁמְעוֹן אָמַר, כֹּה תֹאמַר, כְּמָה דְאַתְּ אָמֵר (במדבר ו׳:כ״ג) כֹּה תְבָרַכוּ. וּכְתִיב, (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרַכוּכָה, כְּלוֹמַר יְבָרְכוּ כֹּה. כֹּה תֹאמַר לְבֵית יַעֲקֹב, בַּאֲמִירָה. וְהַיְינוּ מִסִּטְרָא דְּדִינָא. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל, כְּמָה דְאַתְּ אָמֵר, (דברים ד׳:י״ג) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ. וּכְתִיב (דברים כ״ו:ג׳) הִגַּדְתִּי הַיּוֹם לַיְיָ' אֱלהֶיךָ. לִבְנֵי יִשְׂרָאֵל, דּוּכְרִין, דְּאָתוּ מִסִּטְרָא דְּרַחֲמֵי.","אָמַר רִבִּי יִצְחָק, (ס\"א יוסי) הוֹאִיל וַאֲתֵינָא לְהַאי, מַה הוּא הִגַּדְתִּי הַיּוֹם לַיְיָ' אֱלֹהֶיךָ. לַיְיָ' אֱלֹהֵינוּ, מִבָּעֵי לֵיהּ. אָמַר לֵיהּ ר' שִׁמְעוֹן, וְכִי הַאי בִּלְחוֹדוֹי הוּא. וְהָא כְּתִיב (דברים ח׳:ז׳) כִּי יְיָ' אֱלהֶיךָ מְבִיאֲךָ אֶל אֶרֶץ טוֹבָה וְגוֹ'. (דברים ז׳:ט״ז) אֲשֶׁר יְיָ' אֱלהֶיךָ נוֹתֵן לָךְ. (דברים ד׳:כ״ד) כִּי יְיָ' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא, וְכֻלְּהוּ הָכִי.","אֶלָּא הָכִי תָּנֵינָן, כָּל הַדָּר בְּאֶרֶץ יִשְׂרָאֵל דּוֹמֶה כְּמִי שֶׁיֵּשׁ לוֹ אֱלוֹהַּ. וְכָל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. מַאי טַעֲמָא. מִשּׁוּם דְּזַרְעָא קַדִּישָׁא, לְאַרְעָא קַדִּישָׁא סַלְּקָא. וּשְׁכִינְתָּא בְּאַתְרָה יָתְבָא. וְהַאי בְּהַאי תַּלְיָא. וּמֹשֶׁה לָא קָאָמַר אֱלֹהֶיךָ, אֶלָּא לְאִינוּן דַּהֲווֹ זְמִינִין לְמֵיעַל לְאַרְעָא קַדִּישָׁא, וּלְקַבְּלָא אַפֵּי שְׁכִינְתָּא. וּמַה דְּלָא אָמַר אֱלהֵינוּ, מִשּׁוּם דְּהָא מֹשֶׁה לָא זָכָה לְמֵיעַל לְאַרְעָא, וּבְגִינִי כַּךְ, אֱלֹהֶיךָ וַדַּאי בְּכָל אֲתָר, מִשּׁוּם דְּאִינּוּן הֲווֹ זְמִינִין לְמֵיעַל תַּמָּן.","אֲמַר לֵיהּ ודַּאי הָכִי הוּא. אֲבָל הָכָא כְּתִיב, (דברים כ״ו:ג׳) וּבְאָת אֶל הַכֹּהֵן אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְאָמַרְתָּ אֵלָיו הִגַּדְתִּי הַיּוֹם לַיְיָ' אֱלהֶיךָ, וְהָא אִינּוּן בְּאַרְעָא שַׁרְיָין, מַאי טַעֲמָא אֱלֹהֶיךָ, וְלֹא אֱלהֵינוּ. אֶלָּא אִינּוּן בַּעְיָין לְאַחֲזָאָה וּלְאוֹדָאָה, דִּבְגִינֵי דְּחֶסֶד עִלָּאָה, זָכָאן לְכָל הַאי, וְשַׁרְיָין בְּאַרְעָא, וְעָאֲלָן לְהַהִיא אַרְעָא, וְעָבִיד עִמְּהוֹן כָּל אִינּוּן טָבָאן, וּבְגִינֵי כַּךְ, הֲווֹ אַמְרִי מִלִּין אִלֵּין לַכֹּהֵן, (ולא לבר נש אחרא) דִּכְתִּיב הִגַּדְתִּי הַיּוֹם לַיְיָ' אֱלהֶיךָ, (והכי הוא ודאי) מִשּׁוּם דְּאָתֵי מִסִּטְרָא דְּחֶסֶד.","כֹּה תֹאמַר לְבֵית יַעֲקֹב, לְהַהוּא אֲתָר דְּאִתְחָזֵי לְהוּ. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל, בְּהַהוּא אֲתָר שְׁלִים דְּאִתְחָזֵי לְהוּ, דְּהָא יַעֲקֹב וְיִשְׂרָאֵל, תְּרֵין דַּרְגִּין אִסְתָּלָקוּ, וּבְדַרְגָּא חַד סַלְּקִין, אֶלָּא יִשְׂרָאֵל שְׁלֵימוּתָא דְּכֹלָּא אִקְרֵי. וְתַגֵּיד לִבְנִי יִשְׂרָאֵל, לְאַחֲזָאָה חָכְמְתָא, וּלְאִשְׁתָּעֵי בְּרוּחַ חָכְמְתָא, טִיבוּ וּקְשׁוֹט דְּעָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ."],[[0,"אתער, אזל לגביה וכו':","הקיץ משנתו, הלך אל ר\"ש, נשק ידיו, אמר, כך ראיתי בחלומי. ובפעם אחר ראיתי בחלומי ספר אחד של אגדה, שהראו לפני, והיה כתוב בו, חכמה ותפארת במקדשו: חכמה למעלה, תפארת למטה במקדשו, שהוא מלכות, אצלם. וכך ראיתי פעם אחת בחלומי, וכך מצאתי בפי, שנפל מקרא הזה בפי. א\"ל ר\"ש עד עתה עוד ילד אתה להכנס בין קוצרי השדה, דהיינו בעלי הסוד, והרי הכל הראו לך. וזה הוא שכתוב, מה שמו ומה שם בנו כי תדע. חכמה הוא שמו, תפארת בנו. כי חו\"ב הם או\"א של תפארת כנודע."],[1,"ומשה עלה אל האלקים:","אשרי חלקו של משה, שזכה לכבוד הזה, שהתורה מעידה עליו כך. בוא וראה מה בין משה לשאר בני העולם, שאר בני העולם, כשעולים, עולים לעושר, עולים לגדולה, עולים למלכות, אבל משה, כשעלה מה כתוב בו, ומשה עלה אל האלקים. אשרי חלקו."],[2,"ר' יוסי אמר וכו':","רי\"א, מכאן אמרו החברים, הבא לטהר מסייעים אותו. שכתוב, ומשה עלה אל האלקים מה כתוב אחריו, ויקרא אליו ה'. כי מי שרוצה להתקרב מקרבים אותו."],[3,"ויקרא אליו ה' מן ההר וגו':","ר' יצחק פתח, אשרי תבחר ותקרב ישכון חצריך אשרי חלקו של אותו האדם, שהקב\"ה רוצה בו, וקרב אותו לשכון בתוך היכל הקדוש. שכל מי שהוא רוצה בו לקבלו לעבודתו רשום הוא שמרשימים אותו למעלה, לדעת כי הוא נבחר לפני מלך הקדוש העליון לשכון במדור שלו. וכל מי שנמצא בו רושם ההוא, עובר בכל השערים של מעלה ואין מוחה בידיו."],[4,"ר' יהודה אמר וכו':","אשרי חלקו של משה, שעליו כתוב, אשרי תבחר ותקרב. וכתוב בו, ומשה נגש אל הערפל. ונגש משה לבדו אל ה' והם לא יגשו. כה תאמר לבית יעקב. היינו לנקבות. ותגיד לבני ישראל, היינו לזכרים."],[5,"ר' שמעון אמר וכו':","רש\"א, כה תאמר, הוא כש\"א, \u0003כה\u0004 תברכו. וכתוב וחסידיך יברכוכה. כלומר, יברכו \u0003כה.\u0004 אשר כה, פירושו המלכות שנקראת כה. כה תאמר לבית יעקב, היינו באמירה, והיינו מצד הדין. ותגיד לבני ישראל. הוא כש\"א ויגד לכם את בריתו. וכתוב, הגדתי היום לה' אלקיך. שהגדה הוא רחמים. לבני ישראל, היינו הזכרים הבאים מצד הרחמים. ע\"כ נאמר בהם הגדה."],[6,"א\"ר יצחק הואיל וכו':","אר\"י, כיון שבאנו לזה, מהו, הגדתי לה' אלקיך, לה' אלקינו היה צריך לומר. אמר לו ר' שמעון, וכי זה בלבד הוא, והרי כתוב, כי ה' אלקיך מביאך וגו'. אשר ה' אלקיך נותן לך. כי ה' אלקיך אש וגו'. וכולם כך."],[7,"אלא הכי תנינן וכו':","אלא כך למדנו. כל הדר בארץ ישראל דומה כמי שיש לו אלוה, וכל הדר בחוצה לארץ דומה כמי שאין לו אלוה. מהו הטעם. הוא משום שזרע קדוש, לארץ הקדושה עולה, והשכינה במקומה יושבת, וזה בזה תלוי. וע\"כ משה לא אמר אלהיך אלא לאלו שהיו עתידים להכנס לארץ הקדושה, ולקבל פני השכינה. ומה שלא אמר אלקינו, הוא משום שמשה לא זכה להכנס לארץ. ומשום זה, כתוב אלקיך ודאי בכל מקום, משום שהם היו עתידים להכנס שמה."],[8,"א\"ל, ודאי הכי וכו':","אמר לו, ודאי כן הוא. אבל כאן כתוב, ובאת אל הכהן וגו' הגדתי לה' אלקיך והרי אלו כבר היו בארץ, מהו הטעם שאמר אלקיך ולא אלקינו. ומשיב. אלא הם צריכים להראות ולהודות, משום \u0003שהחסד\u0004 עליון, זיכה אותם לכל זה, ושורים בארץ, ונכנסו לארץ ההיא, ועשה עמהם כל הטוב הזה, ומשום זה היו אומרים דברים אלו אל הכהן, שכתוב הגדתי היום לה' אלקיך וגו', משום שבא מצד \u0003החסד.\u0004"],[9,"כה תאמר לבית יעקב:","היינו למקום ההוא הראוי למדרגתם. \u0003ותגיד לבני ישראל,\u0004 היינו למקום ההוא הראוי למדרגתם. כי יעקב וישראל, שתי מדרגות הם, כי יעקב מדרגת ו\"ק, וישראל הוא מדרגת ג\"ר. ובמדרגה אחת עולים. דהיינו בז\"א, אלא ישראל שלימות הכל נקרא. וע\"כ כתוב ותגיד לבני ישראל, שפירשו, להראות חכמה ולדבר ברוח החכמה את החסד והאמת שעשה להם הקב\"ה. כי הגדה רומזת על חכמה. שכתוב, ויגד לכם את בריתו."]],[[0,"","הִתְעוֹרֵר וְהָלַךְ אֶל רַבִּי שִׁמְעוֹן. נָשַׁק יָדוֹ וְאָמַר, כָּךְ רָאִיתִי בַּחֲלוֹם. פַּעַם אַחֶרֶת רָאִיתִי בַּחֲלוֹם סֵפֶר אַגָּדָה אֶחָד שֶׁהֶרְאוּ לְפָנַי, וְהָיָה כָּתוּב בּוֹ חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ, חָכְמָה לְמַעְלָה, תִּפְאֶרֶת לְמַטָּה, בְּמִקְדָּשׁוֹ אֲלֵיהֶם. וְכָךְ רָאִיתִי בַּחֲלוֹם פַּעַם אַחַת וְכָךְ מָצָאתִי בְּפִי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, עַד עַכְשָׁו אַתָּה תִינוֹק לְהִכָּנֵס בֵּין קוֹצְרֵי הַשָּׂדֶה, וַהֲרֵי הַכֹּל הֶרְאוּ לְךְ. וְזֶהוּ שֶׁכָּתוּב מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. חָכְמָה שְׁמוֹ, תִּפְאֶרֶת בְּנוֹ."],[1,"","וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁזָּכָה לְכָבוֹד זֶה שֶׁהַתּוֹרָה הֵעִידָה בִּשְׁבִילוֹ כָּךְ. (שנה רבי יהודה) בֹּא וּרְאֵה מַה בֵּין מֹשֶׁה לִשְׁאָר בְּנֵי הָעוֹלָם. שְׁאָר בְּנֵי הָעוֹלָם, כְּשֶׁעוֹלִים - עוֹלִים לְעֹשֶׁר, עוֹלִים לִגְדֻלָּה, עוֹלִים לְמַלְכוּת. אֲבָל בְּמֹשֶׁה, כְּשֶׁעוֹלֶה, מַה כָּתוּב? וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. אַשְׁרֵי חֶלְקוֹ!"],[2,"","רַבִּי יוֹסֵי אָמַר, מִכָּאן אָמְרוּ הַחֲבֵרִים, הַבָּא לִטָּהֵר מְסַיְּעִין אוֹתוֹ, שֶׁכָּתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. מַה כָּתוּב אַחֲרָיו? וַיִּקְרָא אֵלָיו ה'. שֶׁמִּי שֶׁרוֹצֶה לְהִתְקָרֵב, מְקָרְבִים אוֹתוֹ."],[3,"","וַיִּקְרָא אֵלָיו מַלְאַךְ ה' מִן הָהָר לֵאמֹר כֹּה תֹאמַר לְבֵית יַעֲקֹב וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בּוֹ וְקֵרַב אוֹתוֹ לִשְׁרוֹת בְּתוֹךְ הַהֵיכָל הַקָּדוֹשׁ, שֶׁכָּל מִי שֶׁהוּא הִתְרַצָּה בּוֹ לַעֲבוֹדָתוֹ, רָשׁוּם הוּא מֵרִשּׁוּמִים שֶׁלְּמַעְלָה לָדַעַת, שֶׁהֲרֵי הוּא נִבְחָר מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן לִשְׁרוֹת בִּמְדוֹרוֹ, וְכָל מִי שֶׁנִּמְצָא בּוֹ אוֹתוֹ הָרֹשֶׁם, עוֹבֵר בְּכָל הַשְּׁעָרִים שֶׁלְּמַעְלָה וְאֵין מוֹחֶה בְּיָדוֹ."],[4,"","רַבִּי יְהוּדָה אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁעָלָיו כָּתוּב אַשְׁרֵי תִּבְחַר וּתְקָרֵב, וְכָתוּב (שמותב) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל, (שם כד) וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל ה' וְהֵם לֹא יִגָּשׁוּ. כֹּה תֹאמַר לְבֵית יַעֲקֹב - אֵלּוּ הַנְּקֵבוֹת. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל - אֵלּוּ הַזְּכָרִים."],[5,"","רַבִּי שִׁמְעוֹן אָמַר, כֹּה תֹאמַר, כְּמוֹ שֶׁנֶּאֱמַר כֹּה תְבָרֲכוּ. וְכָתוּב וַחֲסִידֶיךְ יְבָרֲכוּכָה, כְּלוֹמַר יְבָרְכוּ כֹה. כֹּה תֹאמַר לְבֵית יַעֲקֹב - בַּאֲמִירָה, וְהַיְנוּ מִצַּד הַדִּין. וְתַגֵּיד לְבֵית יִשְׂרָאֵל - כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ. וְכָתוּב (שם כו) הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ. לִבְנֵי יִשְׂרָאֵל - הַזְּכָרִים, שֶׁבָּאוּ מִצַּד הָרַחֲמִים."],[6,"","אָמַר רַבִּי יִצְחָק, הוֹאִיל וּבָאנוּ לָזֶה, מַה זֶּה הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ? לַה' אֱלֹהֵינוּ הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ רַבִּי שִׁמְעוֹן, וְכִי רַק בִּלְבַדּוֹ הוּא, וַהֲרֵי כָּתוּב (שם ח) כִּי ה' אֱלֹהֶיךְ מְבִיאֲךְ אֶל אֶרֶץ טוֹבָה וְגוֹ', (שם) אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ, (שם ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, וְכֻלָּם כָּךְ?"],[7,"","אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַדָּר בְּאֶרֶץ יִשְׂרָאֵל דּוֹמֶה כְּמִי שֶׁיֵּשׁ לוֹ אֱלוֹהַּ, וְכָל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזֶּרַע הַקָּדוֹשׁ עוֹלֶה לָאָרֶץ הַקְּדוֹשָׁה, וּשְׁכִינָה יוֹשֶׁבֶת בִּמְקוֹמָהּ, וְזֶה בָּזֶה תָּלוּי. וּמֹשֶׁה לֹא אָמַר אֱלֹהֶיךְ אֶלָּא לְאוֹתָם שֶׁהָיוּ עֲתִידִים לְהִכָּנֵס לָאָרֶץ הַקְּדוֹשָּׁה וּלְקַבֵּל פְּנֵי שְׁכִינָה. וּמַה שֶּׁלֹּא אָמַר אֱלֹהֵינוּ, מִשּׁוּם שֶׁהֲרֵי מֹשֶׁה לֹא זָכָה לְהִכָּנֵס לָאָרֶץ, וְלָכֵן אֱלֹהֶיךְ וַדַּאי בְּכָל מָקוֹם, מִשּׁוּם שֶׁהֵם הָיוּ עֲתִידִים לְהִכָּנֵס לְשָׁם."],[8,"","אָמַר לוֹ, וַדַּאי כָּךְ הוּא. אֲבָל כָּאן כָּתוּב (שם כו) וּבָאתָ אֶל הַכֹּהֵן אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְאָמַרְתָּ אֵלָיו הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ, וַהֲרֵי הֵם בָּאָרֶץ שׁוֹרִים. מָה הַטַּעַם אֱלֹהֶיךְ וְלֹא אֱלֹהֵינוּ? אֶלָּא הֵם רָצוּ לְהַרְאוֹת וּלְהוֹדוֹת שֶׁבִּגְלַל הַחֶסֶד הָעֶלְיוֹן זָכוּ לְכָל זֶה וְשָׁרוּ בָאָרֶץ וְנִכְנָסִים לְאוֹתָהּ אֶרֶץ וְעָשָׂה עִמָּהֶם כָּל אוֹתָן טוֹבוֹת, וּמִשּׁוּם כָּךְ הָיוּ אוֹמְרִים דְּבָרִים אֵלֶּה לַכֹּהֵן (ולא לאדם אחר), שֶׁכָּתוּב הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ, (וכך הוא ודאי) מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד."],[9,"","כֹּה תֹאמַר לְבֵית יַעֲקֹב - לְאוֹתוֹ מָקוֹם שֶׁרָאוּי לָהֶם. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל - בְּאוֹתוֹ מָקוֹם שָׁלֵם שֶׁרָאוּי לָהֶם, שֶׁהֲרֵי יַעֲקֹב וְיִשְׂרָאֵל שְׁתֵּי דְרָגוֹת עָלוּ, וּבְדַרְגָּה אַחַת עוֹלִים. אֶלָּא יִשְׂרָאֵל שְׁלֵמוּת הַכֹּל נִקְרָא. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל, לְהַרְאוֹת חָכְמָה וּלְדַבֵּר בְּרוּחַ חָכְמָה טוֹב וֶאֱמֶת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ."]]],[["תַּנְיָא, אָמַר ר' יוֹסִי, זִמְנָא חֲדָא הֲוֵינָא אָזִיל בְּאָרְחָא, וַהֲוָה ר' חִיָּיא בְּרִי עִמִּי. עַד דַּהֲוֵינָא אַזְלִין, אַשְׁכַּחְנָא חַד גְּבָר, דְּהֲוָה לָקִיט בְּחַקְלָא, עֲשָׂבִין לְאַסְוָותָא. קָרִיבְנָא לְגַבֵּיהּ, אֲמֵינָא לֵיהּ, בַּר נָשׁ, קוּטְרָא דְּקוּטְרֵי דַּעֲשָׂבִין לָמָּה. לָא זָקִיף רֵישֵׁיהּ, וְלָא אָמַר מִידִי. אַהֲדַרְנָא זִמְנָא אַחֲרָא וַאֲמֵינָא הַאי, וְלָא אָמַר מִידִי. אֲמֵינָא לֵיהּ לְרַבִּי חִיָּיא בְּרִי, אוֹ הַאי בַּר נָשׁ אָטִים אוּדְנִין, אוֹ שַׁטְיָא, אוֹ חַכִּימָא. יָתִיבְנָא גַּבּוֹי. לְבָתַר לָקִיט אִינּוּן עֲשָׂבִין, וְאָחִיד לוֹן, וְחָפָא עֲלֵיהוֹן טַרְפֵּי גּוּפְנִין.","אָמַר לָן, אֲנָא חֲמֵינָא דְּיוּדָאִין אָתוּן, וְיוּדָאִין אַמְרֵי עָלַיְיהוּ, דְּאִינּוּן חַכִּימִין, אִי לָא דְּחַיִּיסְנָא עָלַיְיכוּ הַשְׁתָּא, תֶּהֱווֹן רְחִיקִן מִבְּנֵי נָשָׁא כִּסְגִירָא דָּא, דְּמַרְחִקִין לֵיהּ מִכֹּלָּא, דְּהָא אֲנָא חֲמֵינָא, דְּרֵיחָא דְּחָד עִשְׂבָּא דְּהֲוָה קָרִיב גַּבֵּיכוֹן, עָאל בְּגוּפַיְיכוּ, וְתֶהֱווֹן רְחִיקִין תְּלָתָא יוֹמִין. אֶלָּא אֲכִילוּ אִלֵּין תּוּמֵי בָּרָא וְתִתְסוּן,","אֲכַלְנָא מִנַּיְיהוּ דַּהֲווֹ שְׁכִיחִין קַמָּן, וְאַדְמַכְנָא, וְאִתְקָטַרְנָא בְּזֵיעָא, עַד עִידָּן סַגִּי. לְבָתַר אִתְּעַרְנָא, אָמַר לָן הַהוּא גַּבְרָא, הַשְׁתָּא אֱלָהֲכוֹן עִמְּכוֹן, דְּאַשְׁכַּחְתּוּן לִי, דְּהָא אַסְוָותָא דְּגוּפֵיכוֹן עַל יְדִי אִשְׁתְּלִים.","עַד דַּהֲוֵינָא אַזְלִין, אָמַר לַן, כָּל בַּר נָשׁ בָּעֵי לְאִשְׁתְּעֵי בְּבַר נָשׁ אַחֲרָא, כְּפוּם אָרְחוֹי, דְּהָא לְנוּקְבָּא כְּפוּם אָרְחוֹי. לְגַבְרָא כְּפוּם אָרְחוֹי. לְגַבְרָא דְּגַבְרֵי כְּפוּם אָרְחוֹי. אֲמֵינָא לְרַבִּי חִיָּיא בְּרִי, הַיְינוּ דִּכְתִּיב, כֹּה תֹאמַר לְבֵית יַעֲקֹב וְתַגֵּיד לִבְנִי יִשְׂרָאֵל. (ס\"א כה תאמר לבית יעקב בההוא אתר דאתחזי להו. ותגיד לבני ישראל בההוא אתר שלים דאתחזי להו. דהא יעקב וישראל תרין דרגין אינון ובדרגא חד סלקין אלא ישראל שלימותא דבלא אקרי)","אָמַר לָן, חֲמִיתוּן דְּלָא זָקִיפְנָא רֵישָׁאי, וְלָא אִשְׁתָּעֵינָא בַּהֲדַיְיכוּ, מִשּׁוּם דְּאַבָּא, חַכִּימָא בַּעֲשָׂבִין מִכָּל בְּנִי דָּרָא הֲוָה. וְאוֹלִיפְנָא מֵאַבָּא אָרְחוֹי דְּכָל עֲשָׂבִין, דִּבְּהוֹן קְשׁוֹט, וַאֲנָא בְּכָל שַׁתָּא מָדוֹרָאי בֵּינַיְיהוּ.","וְהַאי עִשְׂבָּא דַּחֲמִיתוּן, דַּחֲפֵינָא לֵיהּ בְּטַרְפֵּי דְּגוּפְנִין אִלֵּין, בְּבֵיתָאי אִית אֲתָר חַד, וְהוּא לִסְטַר צָפוֹן, וּבְהַהוּא אֲתָר נָעִיץ חַד רֵיחַיָּא, וּמֵעֵינָא דְּהַהוּא רֵיחַיָּא, נָפִיק חַד גְּבַר בִּתְרֵין רֵישִׁין, וְחַרְבָּא שִׁינָנָא בִּידֵיהּ וּבְכָל יוֹמָא קָא מְצַעֵר לָן. וַאֲנָא לָקִיטְנָא הַאי עִשְׂבָּא, וְזִילוּ אֲבַתְרָאי, וְתֶחמוּן חֵילֵיהּ דְּהַאי עִשְׂבָּא, וּמַה דִּי אֱלָהָא עִלָּאָה גַּלֵּי בְּעָלְמָא, וְלֵית מַאן דְּיֵדַע אָרְחוֹי בְּכֹלָּא.","אֲזִילְנָא אֲבַתְרֵיהּ, עַד דַּהֲוֵינָא אַזְלֵי בְּאָרְחָא, מָאִיךְ לְחַד נוּקְבָּא בְּעַפְרָא, וְשַׁוֵּי מֵהַהוּא עִשְׂבָּא בְּנוּקְבָא, נָפַק חַד חִוְיָא וְרֵישָׁא דִּילֵיהּ סַגִּי. נָטַל חַד סַנְטִירָא, (נ\"א סודרא) וְקָטִיר לֵיהּ כְּחַד גַּדְיָא. דָּחִילְנָא. אָמַר לוֹן זִילוּ אֲבַתְרָאי.","עַד דְּמָטֵינָא לְבֵיתֵיהּ. חֲמֵינָא הַהוּא אֲתָר בְּחָשׁוֹכָא, בָּתַר חַד כּוֹתָלָא. נָטַל חַד שַׁרְגָּא וְדָלִיק דְּלֵיקָא סַחֲרָנִיהּ דְּהַהוּא אֲתָר דְּרֵיחַיָּא. אָמַר לוֹן, מִמַּה דְּתֶחֱמוּן, לָא תִּדְחָלוּן וְלָא תִּשְׁתָּעוּן מִידִי.","אַדְהָכִי, שָׁרֵי חִוְיָא מִקִּטְרוֹי, וְכָתַשׁ בְּקִיסְטָא מֵהַהוּא עִשְׂבָּא. וְשַׁוֵּי בְּרֵישֵׁיהּ דְּחִוְיָא. עָאל חִוְיָא בְּהַהוּא עֵינָא דְּרֵחַיָּיא, וּשְׁמַעְנָא קָלָא דְּכָל אֲתָר מִזְדַּעְזְעָא. בָּעֵינָן לְמֵיפַק, אָחִיד בִּידָנָא הַהוּא גַּבְרָא, אָמַר, לָא תִּדְחָלוּן קְרִיבוּ גַּבָּאי.","אַדְהָכִי, נָפַק חִוְיָא שָׁתִית דָּמָא, נָקִיט הַהוּא גַּבְרָא מֵהַהוּא עִשְׂבָּא, וְשַׁוֵּי בְּרֵישֵׁיהּ כִּבְקַדְמֵיתָא. עָאל בְּהַהוּא עֵינָא דְּרֵחַיָּא. לְשַׁעֲתָא זְעִירָא, חֲמֵינָא, דְּנָפִיק מֵהַהוּא עֵינָא חַד גַּבְרָא בִּתְרֵין רֵישִׁין, וְחִוְיָא שַׁרְיָיא סַחֲרָנֵיהּ דְּקִדְלוֹי. עָאל בְּהַהוּא עֵינָא דְּרֵחַיָּא וְנָפַק תְּלַת זִמְנֵי. הָוָה אָמַר, זְקִיטָא זְקִיטָא, וַוי לְאִימֵיהּ דִּלְהַהוּא אֲתָר אוֹבִיל לֵיהּ.","אַדְהָכִי, אִתְּעֲקָר רֵיחַיָּא מֵאַתְרֵיהּ, וְנַפְקוּ, גַּבְרָא וְחִוְיָא, וְנָפְלוּ וּמִיתוּ תַּרְוַויְיהוּ. וַאֲנָן דָּחִילְנָא סַגִּי. אָמַר לָן הַהוּא גַּבְרָא, דָּא הוּא חֵילָא דְּעִשְׂבָּא דַּאֲנָא לָקִיטְנָא קָמַיְיכוּ, וּבְגִינֵי כַּךְ לָא אִשְׁתָּעֵינָא בַּהֲדַיְיכוּ, וְלָא זָקִיפְנָא רֵישָׁאי, בְּשַׁעֲתָא דְּקַרִיבְתּוּן גַּבָּאי."],[[0,"תניא אמר ר' יוסי וכו':","למדנו, אר\"י, פעם אחת, הייתי הולך בדרך, והיה ר' חייא בני עמי. בעוד שהיינו הולכים, מצאנו איש אחד, שהיה לוקט עשבים בשדה לרפואה. קרבנו אליו, אמרתי לו: אדם, אגודות אגודות העשבים למה לך. לא זקף ראשו ולא ענה כלום. חזרתי פעם שנית ואמרתי זה, ולא ענה כלום. אמרתי לר' חייא בני, או שאיש הזה אטומים אזניו, או שהוא שוטה, או שהוא חכם. ישבתי אצלו. אחר כך, לקט העשבים, וקשר אותם, וכסה אותם בעלי תאנה."],[1,"אמר לן אנא וכו':","אמר לנו, אני רואה שיהודים אתם, ויהודים אומרים עליהם שהם חכמים, אם איני מרחם עליכם עתה, תהיו רחוקים מבני אדם כמצורע הזה, שמרחקים אותו מכל, כי אני רואה, שריח של עשב אחד שקרב אליכם נכנס לגופיכם, ותהיו רחוקים מאיש ג' ימים. אלא אכלו, אלו שומים הפראים, ותתרפאו."],[2,"אכלנא מנייהו דהוו וכו':","אכלנו מהם, שהיו נמצאים לפנינו, ונישן, ונתקשרנו בזיעה זמן רב. אח\"כ הקצנו. אמר לנו איש הזה, עתה אלקיכם עמכם, שמצאתם אותי, כי רפואת גופיכם נשלם על ידי."],[3,"עד דהוינא אזלין וכו':","בעוד שהיינו הולכים, אמר לנו, כל אדם צריך לדבר עם אדם אחר כפי דרכיו, לנקבה לפי דרכיה ולגבר כפי דרכיו. ולגבר שבגברים כפי דרכיו. אמרתי לר' חייא בני, היינו שכתוב, כה תאמר לבית יעקב ותגיד לבני ישראל."],[4,"אמר לן חמיתון וכו':","אמר לנו, ראיתם, שלא הרימותי את ראשי, ולא דברתי עמכם. משום שאבי חכם היה בעשבים יותר מכל בני דורו. ולמדתי מאבי, דרכיהם של כל העשבים, שאמת בהם, ואני בכל השנה משכני ביניהם."],[5,"והאי עשבא דחמיתון וכו':","ועשב הזה, שראיתם, שכסיתי אותו בעלי תאנה אלו, הוא, כי בביתי יש מקום אחד, והוא לצד צפון, ובמקום ההוא תקוע רחים אחת, ומעין הרחים ההיא, יוצא איש אחד בשני ראשים, וחרב שנונה בידו, ובכל יום מצער אותנו. ואני לקטתי עשב הזה, ובואו אחרי, ותראו כוחו של עשב הזה, ומה שאלקים העליון גילה בעולם. ואין מי שידע דרכיו בכל דבר."],[6,"אזילנא אבתריה עד וכו':","הלכנו אחריו. בעוד שהיינו הולכים בדרך, כפף עצמו, לנקב אחד שבעפר, ושם מעשב ההוא לתוך הנקב, יצא נחש אחד וראשו גדול. לקח חבל אחד וקשר אותו כגדי אחד. היינו יראים. אמר לנו, בואו אחרי."],[7,"עד דמטינא לביתיה וכו':","עד שהגענו לביתו. ראינו מקום ההוא בחושך, אחר כותל אחד. לקח נר אחד, והדליק אש מסביב מקום ההוא של הרחים. אמר לנו ממה שתראו לא תפחדו, ולא תדברו כלום."],[8,"אדהכי שרי חויא וכו':","בתוך כך, התיר את הנחש מקשריו, וכתש במכתשת מעשב ההוא, ושם אותו בראש הנחש. נכנס הנחש בעין הרחים ההוא, ושמענו קול עד שכל המקום נזדעזע. רצינו לצאת, אחז בידינו איש ההוא, ואמר, אל תפחדו, קרבו אצלי."],[9,"אדהכי נפק חויא וכו':","בתוך כך, יצא הנחש משם והיה שותת דם. לקח איש ההוא מעשב ההוא, ושם בראשו כבתחילה. נכנס הנחש בעין הרחים ההוא. לזמן קצר, ראינו שיצא, מעין הריחים ההוא, איש אחד בשני ראשים ונחש שורה מסביב צוארו. ונכנס ויצא בעין הריחים ההוא שלש פעמים. והיה אומר, זקיטא זקיטא, הוא מין שרץ, אוי לאמו, שלמקום ההוא הוליכה אותו."],[10,"אדהכי אתעקר ריחיא וכו':","בתוך כך, נעקרה הריחים ממקומה, ויצאו, האיש והנחש, ונפלו ומתו שניהם. ואנחנו היינו מתיראים מאד. אמר לנו איש ההוא, זה הוא כח העשב שלקטתי לפניכם, ומשום זה, לא דברתי עמכם, ולא הרימותי ראשי בשעה שקרבתם אלי."]],[[0,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, פַּעַם אַחַת הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וְהָיָה עִמִּי רַבִּי חִיָּיא בְּנִי. עַד שֶׁהָיִינוּ הוֹלְכִים, מָצָאתִי אִישׁ אֶחָד שֶׁהָיָה לוֹקֵט בַּשָּׂדֶה עֲשָׂבִים לִרְפוּאָה. קָרַבְתִּי אֵלָיו וְאָמַרְתִּי לוֹ: בֶּן אָדָם, כָּל הָאֲגֻדּוֹת הַקְּשׁוּרוֹת הַלָּלוּ שֶׁל הָעֲשָׂבִים לָמָּה? לֹא הֵרִים רֹאשׁוֹ וְלֹא אָמַר דָּבָר. חָזַרְתִּי פַּעַם נוֹסֶפֶת וְאָמַרְתִּי אֶת זֶה - וְלֹא אָמַר דָּבָר. אָמַרְתִּי לְרַבִּי חִיָּיא בְּנִי: אוֹ שֶׁהָאִישׁ הַזֶּה אָזְנָיו אֲטוּמוֹת, אוֹ שׁוֹטֶה, אוֹ חָכָם. יָשַׁבְתִּי אֶצְלוֹ. אַחַר כָּךְ לִקֵּט אוֹתָם עֲשָׂבִים, וְאָחַז אוֹתָם וְכִסָּה עֲלֵיהֶם בַּעֲלֵי גֶפֶן."],[1,"","אֲנִי רָאִיתִי שֶׁאַתֶּם יְהוּדִים, וְעַל הַיְּהוּדִים אוֹמְרִים שֶׁהֵם חֲכָמִים. אִם לֹא הָיִיתִי חָס עֲלֵיכֶם, עַכְשָׁו תִּהִיוּ מְרֻחָקִים מִבְּנֵי אָדָם כְּמוֹ הַמְּצֹרָע הַזֶּה שֶׁמַּרְחִיקִים אוֹתוֹ מֵהַכֹּל, שֶׁהֲרֵי אֲנִי רוֹאֶה שֶׁרֵיחַ שֶׁל עֵשֶׂב אֶחָד שֶׁהָיָה קָרוֹב אֲלֵיכֶם נִכְנַס בְּגוּפְכֶם, וְתִהְיוּ מְרֻחָקִים שְׁלֹשָׁה יָמִים, אֶלָּא אִכְלוּ שׁוּמֵי הַבָּר הַלָּלוּ וְתִתְרַפְּאוּ."],[2,"","אָכַלְנוּ מֵהֶם, שֶׁהָיוּ מְצוּיִים שָׁם, וְנִרְדַּמְנוּ וְנִקְשַׁרְנוּ בְּזֵעָה עַד זְמַן רַב. אַחַר כָּךְ הִתְעוֹרַרְנוּ. אָמַר לָנוּ אוֹתוֹ הָאִישׁ: עַכְשָׁו אֱלֹהֵיכֶם עִמָּכֶם שֶׁמְּצָאתֶם אוֹתִי, שֶׁהֲרֵי רְפוּאַת גּוּפְכֶם עַל יָדִי נִשְׁלְמָה."],[3,"","עַד שֶׁהָיִינוּ הוֹלְכִים, אָמַר לָנוּ: כָּל אָדָם צָרִיךְ לְדַבֵּר עִם אָדָם אַחֵר כְּפִי דְרָכָיו. שֶׁהֲרֵי לַנְּקֵבָה כְּפִי דַרְכָּהּ, לָאִישׁ כְּפִי דְרָכָיו, וְלַגֶּבֶר שֶׁבַּגְּבָרִים כְּפִי דְרָכָיו. אָמַרְתִּי לְרַבִּי חִיָּיא בְּנִי, זֶהוּ שֶׁכָּתוּב כֹּה תֹאמַר לְבֵית יַעֲקֹב וְתַגֵּיד לְבֵית יִשְׂרָאֵל. (כה תאמר לבית יעקב, באותו מקום שראוי להם. ותגיד ותגיד לבני ישראל, באותו מקוםשלםשראוילהם, שהרייעקבוישראלשתי דרגות הם ובדרגה אחת עולים, אלא ישראל שלמות הכל נקרא)."],[4,"","רְאִיתֶם שֶׁלֹּא הֵרַמְתִּי רֹאשִׁי וְלֹא דִבַּרְתִּי עִמָּכֶם, מִשּׁוּם שֶׁאָבִי הָיָה חֲכַם הָעֲשָׂבִים מִכָּל בְּנֵי דוֹרוֹ, וְלָמַדְתִּי מֵאָבִי דַּרְכֵי כָּל הָעֲשָׂבִים שֶׁבָּהֶם אֱמֶת, וַאֲנִי בְּכָל הַשָּׁנָה מְדוֹרִי בֵּינֵיהֶם."],[5,"","וְהָעֵשֶׂב הַזֶּה שֶׁרְאִיתֶם שֶׁכִּסִּיתִי אוֹתוֹ בַּעֲלֵי הַגֶּפֶן הַלָּלוּ - בְּבֵיתִי יֵשׁ מָקוֹם אֶחָד, וְהוּא לְצַד צָפוֹן, וּבְאוֹתוֹ מָקוֹם נָעוּץ רֵחַיִם אֶחָד, וּמֵהָעַיִן שֶׁל אוֹתוֹ רֵחַיִם יוֹצֵא אִישׁ אֶחָד עִם שְׁנֵי רָאשִׁים וְחֶרֶב שְׁנוּנָה בְיָדוֹ, וּבְכָל יוֹם הוּא מְצַעֵר אוֹתָנוּ, וַאֲנִי לִקַּטְתִּי אֶת הָעֵשֶׂב הַזֶּה, וּלְכוּ אַחֲרַי וְתִרְאוּ אֶת כֹּחוֹ שֶׁל הָעֵשֶׂב הַזֶּה וּמַה שֶּׁאֱלוֹהַּ הָעֶלְיוֹן גִּלָּה בָּעוֹלָם, וְאֵין מִי שֶׁיּוֹדֵעַ דְּרָכָיו בַּכֹּל."],[6,"","הָלַכְנוּ אַחֲרָיו. עַד שֶׁהָיִינוּ הוֹלְכִים בַּדֶּרֶךְ, הִתְכּוֹפֵף לְנֶקֶב אֶחָד בֶּעָפָר, וְשָׂם מֵאוֹתוֹ הָעֵשֶׂב בַּנֶּקֶב. יָצָא נָחָשׁ אֶחָד וְרֹאשׁוֹ גָּדוֹל. לָקַח חֶבֶל (סודר) אֶחָד וְקָשַׁר אוֹתוֹ כְּמוֹ גְדִי אֶחָד. פָּחַדְנוּ. אָמַר לָנוּ: לְכוּ אַחֲרַי."],[7,"","עֵד שֶׁהִגַּעְנוּ לְבֵיתוֹ, רָאִינוּ אוֹתוֹ מָקוֹם בַּחֲשֵׁכָה אַחַר כֹּתֶל אֶחָד. לָקַח נֵר אֶחָד וְהִדְלִיק אֵשׁ סְבִיב אוֹתוֹ מְקוֹם הָרֵחַיִם. אָמַר לָנוּ: מִמַּה שֶּׁתִּרְאוּ - לֹא תִפְחֲדוּ וְלֹא תְדַבְּרוּ דָבָר."],[8,"","בֵּין כָּךְ הִתִּיר אֶת הַנָּחָשׁ מִקְּשָׁרָיו, וְכָתַשׁ בְּמַכְתֶּשֶׁת מֵאוֹתוֹ הָעֵשֶׂב וְשָׂם בְּרֹאשׁ הַנָּחָשׁ. נִכְנַס הַנָּחָשׁ בְּאוֹתוֹ עֵין הָרֵחַיִם, וְשָׁמַעְנוּ קוֹל שֶׁכָּל הַמָּקוֹם הִזְדַּעֲזַע. רָצִינוּ לָצֵאת, אָחַז בְּיָדֵינוּ אוֹתוֹ הָאִישׁ וְאָמַר: אַל תִּפְחֲדוּ, קִרְבוּ אֵלַי."],[9,"","בֵּין כָּךְ יָצָא הַנָּחָשׁ שׁוֹתֵת דָּם. לָקַח אוֹתוֹ הָאִישׁ מֵאוֹתוֹ הָעֵשֶׂב וְשָׂם בְּרֹאשׁוֹ כְּבַתְּחִלָּה. נִכְנַס לְאוֹתוֹ עֵין הָרֵחַיִם. לְשָׁעָה קְטַנָּה רָאִינוּ שֶׁיָּצָא מֵאוֹתוֹ הָעַיִן אִישׁ אֶחָד עִם שְׁנֵי רָאשִׁים וְנָחָשׁ שָׁרוּי סְבִיב צַוָּארוֹ. נִכְנַס לְאוֹתוֹ עֵין הָרֵחַיִם וְיָצָא שָׁלֹשׁ פְּעָמִים. וְהוּא אָמַר: זְקִיטָא זְקִיטָא (מין שרץ) ! אוֹי לְאִמּוֹ שֶׁהוֹבִילָה אוֹתוֹ לְאוֹתוֹ מָקוֹם!"],[10,"","בֵּין כָּךְ נֶעֱקַר הָרֵחַיִם מִמְּקוֹמוֹ, וְיָצְאוּ הָאִישׁ וְהַנָּחָשׁ, וְנָפְלוּ וּמֵתוּ שְׁנֵיהֶם. וְאָנוּ פָּחַדְנוּ מְאֹד. אָמַר לָנוּ אוֹתוֹ הָאִישׁ: זֶהוּ כֹּחוֹ שֶׁל אוֹתוֹ עֵשֶׂב שֶׁאֲנִי לָקַטְתִּי לִפְנֵיכֶם, וְלָכֵן לֹא דִבַּרְתִּי עִמָּכֶם וְלֹא הֵרַמְתִּי רֹאשִׁי בְּשָׁעָה שֶׁקְּרַבְתֶּם אֵלַי."]]],[["אָמַר לוֹן אִילוּ יַדְעִין בְּנֵי נָשָׁא חָכְמְתָא, דְּכָל מַה דְּנָטַע קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, וְחֵילָא דְּכָל מַה דְּאִשְׁתְּכַח בְּעָלְמָא, יִשְׁתְּמוֹדְעוּן חֵילָא דְּמָארֵיהוֹן, בְּחָכְמָתֵיהּ סַגִּיאָה. אֲבָל לָא טָמִיר קוּדְשָׁא בְּרִיךְ הוּא חָכְמְתָא דָּא מִבְּנֵי נָשָׁא, אֶלָּא בְּגִין דְּלָא יִסְטוּן מֵאָרְחוֹי, וְלָא יִתְרְחִיצוּ בְּהַהִיא חָכְמְתָא וְיִנְשׁוּן לֵיהּ.","כַּד אֲתֵינָא, וַאֲמֵינָא הָנֵי מִלֵּי קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, אָמַר וַדַּאי חַכִּימָא הֲוָה. וְתָּא חֲזֵי, לֵית עִשְׂבָּא וְעִשְׂבָּא דְּאִתְיְילִיד בְּאַרְעָא, דְּלָא הֲוָה בֵּיהּ חָכְמְתָא סַגִּיאָה, וְחֵילֵיהּ בִּשְׁמַיָּא סַגְיָא. תָּא חֲזֵי, מִן אֵזוֹבָא. דִּבְכָל אֲתָר דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לְבַּר נָשׁ, (ויחי ר\"נ ע\"א) בְּאֵזוֹבָא מִתְדָּכֵי. מַאי טַעְמָא. מִשּׁוּם דְּיִתְּעַר חֵילֵיהּ דִּלְעֵילָּא דְּאִתְפָּקְּדָא עֲלוֹי, דְּהָא הַהוּא חֵילָא דְּאִתְפָּקְּדָא עֲלוֹי כַּד אִתְּעָרָא, מְבָעֲרָא רוּחַ מְסָאֲבָא, וְאִתְדַכֵּי בַּר נָשׁ. וְעָלָךְ אֲמֵינָא בְּרִיךְ רַחֲמָנָא דְּשֵׁזְבָךְ.","(שמות י״ט:ד׳) אַתֶּם רְאִיתֶם אֲשֶׁר עָשִׂיתִי לְמִצְרָיִם וְאֶשָּׁא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים. מַאי כַּנְפֵי נְשָׁרִים. אָמַר רִבִּי יְהוּדָה בְּרַחֲמֵי. דִּכְתִּיב, (דברים לכ) כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'. וְהַיְינוּ רָזָא דְּאָמַר ר' שִׁמְעוֹן, (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. מַאי בַּשָּׁמַיִם. בְּרַחֲמֵי. מַה נֶשֶׁר אִשְׁתְּכַח בְּרַחֲמֵי עַל בְּנוֹי, וְדִינָא לְגַבֵּי אַחֲרָנִין. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בְּרַחֲמֵי לְגַבֵּי יִשְׂרָאֵל, וְדִינָא לְגַבֵּי עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.","ר' אֶלְעָזָר, הֲוָה אָזִיל מִקַּפּוּטְקִיָּא לְלוּד, וַהֲוָה אָזִיל ר' יוֹסֵי וְר' חִיָּיא עִמֵּיהּ, קָמוּ בִּנְהוֹרָא, כַּד נָהִיר יְמָמָא, וַהֲווּ אַזְלֵי. אָמַר ר' חִיָּיא, חֲמֵינָא הַאי קְרָא דִּכְתִּיב, (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּן וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן הָא אַרְיֵה בִּימִינָא, שׁוֹר מִשְּׂמָאלָא, (ק\"כ ע\"א) נֶשֶׁר בְּאָן אֲתָר דּוּכְתֵּיהּ.","אָמַר לֵיהּ ר' אֶלְעָזָר, בְּאַתְרָא (נ\"א דיעקב) דְיָנִיקָא שַׁרְיָא. מַאי טַעְמָא. מִשּׁוּם דְּנֶשֶׁר בְּכֹלָּא אִשְׁתְּכַח, רַחֲמֵי לִבְנוֹי, דִּינָא לְגַבֵּי אַחֲרָנִין. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, אוֹבִיל לוֹן לְיִשְׂרָאֵל בְּרַחֲמֵי. וּבְדִינָא לְגַבֵּי אַחֲרָנִין, דִּכְתִּיב וְאֶשָּׁא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים. וּכְתִיב כְּנֶשֶׁר יָעִיר קִנּוֹ.","מְנָלָן דְּנֶשֶׁר רַחֲמֵי אִקְרֵי. דִּכְתִּיב דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בַּשָּׁמַיִם מַמָּשׁ. וּבְגִינֵי כַּךְ אַרְיֵה לִימִינָא. שׁוֹר לִשְׂמָאלָא. נֶשֶׁר בֵּינַיְיהוּ וְאָחִיד לוֹן. אָדָם כָּלִיל כֻּלְּהוּ, וְכֹלָּא אִתְּכְּלִילָן בֵּיהּ, דִּכְתִּיב וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְּמַעְלָה.","וַיְהִי בַיּוֹם הַשְׁלִישִׁי וְגוֹ'. ר' אַבָּא פָּתַח, (שיר השירים ח׳:ח׳) אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ. אָחוֹת לָנוּ קְטַנָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִקְרֵי אָחוֹת לְקוּדְשָׁא בְּרִיךְ הוּא. וְשָׁדַיִם אֵין לָהּ, הַיְינוּ דְּתָנֵינָן, בְּשַׁעֲתָא דְּקָרִיבוּ יִשְׂרָאֵל לְטוּרָא דְּסִינַי, לָא הֲוָה בְּהוֹן זַכְוָון, וְעוֹבָדִין טָבִין, לְאַגָּנָא עָלַיְיהוּ, דִּכְתִּיב וְשָׁדַיִם אֵין לָהּ. דְּהָא אִינּוּן תִּקּוּנָא וּשְׁפִירוּ דְּאִתְּתָא, וְלֵית שַׁפִּירוּ דְּאִתְּתָא אֶלָּא אִינּוּן. מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ. מַה יִתְעֲבִיד מִינָהּ, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, יִתְגְּלֵי בְּטוּרָא דְּסִינַי, לְמַלְּלָא בְּפִתְגָּמֵי אוֹרַיְיתָא, וְיִפְרַח נִשְׁמָתְהוֹן מִנַיְיהוּ.","אָמַר ר' יוֹסֵי. בְּהַהוּא שַׁעֲתָא דְּקָרִיבוּ יִשְׂרָאֵל לְטוּרָא דְּסִינַי, בְּהַהוּא לֵילְיָא וְנַגְהֵי, תְּלָתָא יוֹמִין דְּלָא אִזְדַּוְּוגוּ לְאִנְתְּתַיְיהוּ, אָתוּ מַלְאָכִין עִלָּאִין, וְקַבִּילוּ לְיִשְׂרָאֵל בְּאַחְוָותָא. אִינּוּן מַלְאָכִין לְעֵילָּא, וְיִשְׂרָאֵל מַלְאָכִין לְתַתָּא. אִינּוּן מְקַדְּשִׁין שְׁמָא עִלָּאָה לְעֵילָּא, וְיִשְׂרָאֵל מְקַדְּשִׁין שְׁמָא עִלָּאָה לְתַתָּא.","וְאִתְעַטְּרוּ יִשְׂרָאֵל בְּשִׁבְעִין כִּתְרִין בְּהַהוּא לֵילְיָא. וּמַלְאֲכֵי עִלָּאֵי הֲווֹ אַמְרֵי אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ, דְּלֵית בְּהוּ זַכְוָון וְעוֹבָדִין טָבִין. מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ, כְּלוֹמַר מַה יְקָר וּרְבוּ נַּעְבִיד לְאַחֲתָנָא דָּא בְּיוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא יִתְגְּלֵי בְּטוּרָא דְּסִינַי לְמֵיהָב לְהוּ אוֹרַיְיתָא.","וַיְהִי בַיּוֹם הַשְׁלִישִׁי, כְּתִיב היוּ נְכוֹנִים לִשְׁלֹשֶׁת יָמִים אַל תִּגְּשׁוּ אֶל אִשָּׁה וְהַיְינוּ בַיּוֹם הַשְׁלִישִׁי. ר' שִׁמְעוֹן אָמַר, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאִתְגַּלָּאָה בְּטוּרָא דְּסִינַי, קָרָא קוּדְשָׁא בְּרִיךְ הוּא לְכָל פָּמַלְיָיא דִּילֵיהּ, אָמַר לוֹן, הַשְׁתָּא יִשְׂרָאֵל רַבְיָין, דְּלָא יַדְעִין נִימוּסַי, וַאֲנָא בָּעֵי לְאִתְגְּלֵי עָלַיְיהוּ, אִי אִתְגְּלֵי עָלַיְיהוּ בְּחֵילָא דִּגְבוּרָה, לָא יַכְלִין לְמִסְבַּל. אֲבָל אִתְגְּלֵי עָלַיְיהוּ בְּרַחֲמֵי, וִיקַבְּלוּן נִימוּסַי, הֲדָא הוּא דִכְתִיב, וַיְהִי בַיּוֹם הַשְׁלִישִׁי. בַיּוֹם הַשְׁלִישִׁי וַדַּאי דְּאִיהוּ רַחֲמֵי מְנָלָן. דִּכְתִּיב, (שמואל ב כ״ב:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד."],[[0,"אמר לון אלו וכו':","אמר לנו, אלו היו יודעים בני אדם חכמה מכל מה שנטע הקב\"ה בארץ, וכח כל מה שנמצא בעולם, היו מכירים כח רבונם בחכמה גדולה. אבל לא הסתיר הקב\"ה חכמה זו מבני אדם, אלא כדי שלא יסורו מדרכיו, ולא יבטחו בחכמה ההיא, וישכחו את הקב\"ה."],[1,"כד אתינא ואמינא וכו':","כשבאתי וספרתי דברים אלו לפני ר' שמעון, אמר, ודאי חכם היה. ובוא וראה, אין עשב ועשב הנולד בארץ, שלא תהיה בו חכמה רבה, וכח גדול בשמים. בוא וראה מן האזוב. שבכל מקום שרצה הקב\"ה לטהר את האדם, באזוב הוא נטהר. מהו הטעם. משום שיתעורר כחו של מעלה שנפקד עליו, כי כח ההוא שנפקד עליו, כשמתעורר, הוא מבער את רוח הטומאה והאדם מטהר. ועליך אני אומר, ברוך הרחמן שהצילוך."],[2,"אתם ראיתם וגו' על כנפי נשרים:","מהו כנפי נשרים. א\"ר יהודה, ברחמים. שכתוב כנשר יעיר קנו וגו'. שמשמע, שנשר יורה על רחמים. והיינו הסוד שאמר ר' שמעון, דרך הנשר בשמים. מהו בשמים. ברחמים. כי ז\"א נקרא שמים, והוא בעל הרחמים, כי חג\"ת הוא חסד דין ורחמים מה נשר נמצא ברחמים על בניו ודין לאחרים, כך הקב\"ה, נמצא ברחמים לישראל ודין לעמים עעכו\"ם."],[3,"ר' אלעזר הוה וכו':","ר\"א היה הולך מקפוטקיא ללוד. והיו הולכים עמו ר' יוסי ור' חייא. קמו לאור הבוקר כשהאיר היום, והיו הולכים. אמר ר' חייא, אני רואה מקרא הזה, שכתוב, ופני אריה אל הימין לארבעתן ופני שור מהשמאל לארבעתן ופני נשר לארבעתן. שואל, הנה אריה הוא בימין, שור משמאל, נשר, באיזה מקום מקומו."],[4,"אמר ליה ר' אלעזר וכו':","א\"ל ר\"א, במקום שיעקב שורה, שהוא בקו אמצעי, שם מקומו של הנשר. מה הטעם. משום שנשר כלול בכל, ברחמים ובדין, רחמים לבניו דין לאחרים כך הקב\"ה, שה\"ס קו האמצעי, מוליך את ישראל ברחמים, ולאחרים בדין. שכתוב, ואשא אתכם על כנפי נשרים. וכתוב, כנשר יעיר קנו."],[5,"מנלן דנשר רחמי וכו':","מאין לנו שנשר הוא רחמים. שכתוב, דרך הנשר בשמים. בשמים ממש, שהוא ז\"א בעל הרחמים. ומשום זה, אריה לימין, שור לשמאל, נשר ביניהם באמצע, וכולל את שניהם. פני אדם כולל את כולם, והכל נכללים בו. כי הוא בחינת המלכות המקבלת מכולם. שכתוב, ועל דמות הכסא דמות כמראה אדם עליו מלמעלה."],[6,"ויהי ביום השלישי וגו':","ר' אבא פתח, אחות לנו קטנה ושדים אין לה מה נעשה לאחותנו ביום שידובר בה. \u0003אחות לנו קטנה,\u0004 זה כנסת ישראל שנקראת אחות אל הקב\"ה. \u0003ושדים אין לה,\u0004 היינו שלמדנו, בשעה שקרבו ישראל להר סיני, לא היה בהם זכיות ומעשים טובים להגן עליהם, שכתוב, ושדים אין לה. שהם תקונה ויפיה של האשה, ואין יופי לאשה אלא הם. \u0003מה נעשה לאחותנו,\u0004 מה יעשה ממנה, בשעה שהקב\"ה יתגלה בהר סיני לדבר בדברי תורה, ויפרחו הנשמות מהם."],[7,"אמר ר' יוסי וכו':","אר\"י, בשעה ההיא שקרבו ישראל להר סיני, עם לילה ההיא והבוקר, היו שלשה ימים שלא נזדווגו עם נשותיהם. באו מלאכים הקדושים וקבלו את ישראל באחוה, כי הם מלאכים למעלה, וישראל מלאכים למטה, הם מקדשים שם העליון למעלה. וישראל מקדשים שם העליון למטה."],[8,"ואתעטרו ישראל בשבעין וכו':","ונתעטרו ישראל בלילה ההוא בע' כתרים. ומלאכים העליונים היו אומרים, אחות לנו קטנה ושדים אין לה. שאין בהם זכיות ומעשים טובים. \u0003מה נעשה לאחותנו,\u0004 כלומר, מה יקר ותפארת נעשה לאחותנו זו ביום, שהקב\"ה יתגלה בהר סיני, לתת להם התורה."],[9,"ויהי ביום השלישי:","כתוב, היו נכונים לשלשת ימים אל תגשו אל אשה. והיינו שכתוב, ויהי ביום השלישי. ר' שמעון אמר. בשעה שהקב\"ה רצה להתגלות בהר סיני, קרא הקב\"ה לכל הפמליא שלו, אמר להם, עתה, נער ישראל, שאינם יודעים מצותי, ואני רוצה להתגלות עליהם ברחמים ויקבלו מצותי. ז\"ש ויהי ביום השלישי. ביום השלישי ודאי, שהוא ת\"ת, שהוא רחמים. מאין לנו, שכתוב, ויט שמים וירד. ושמים הוא ת\"ת, שהוא רחמים כנ\"ל."]],[[0,"","אִלּוּ יָדְעוּ בְּנֵי אָדָם חָכְמָה, שֶׁכָּל מַה שֶּׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ וְכֹחַ כָּל מַה שֶּׁנִּמְצָא בָּעוֹלָם, יָדְעוּ אֶת כֹּחַ רִבּוֹנָם בְּחָכְמָתוֹ הָרַבָּה. אֲבָל לֹא הִסְתִּיר הַקָּדוֹשׁ בָּרוּךְ הוּא חָכְמָה זוֹ מִבְּנֵי אָדָם, אֶלָּא כְּדֵי שֶׁלֹּא יִסְטוּ מִדְּרָכָיו וְלֹא יִבְטְחוּ בְּאוֹתָהּ חָכְמָה וְיִשְׁכְּחוּ אוֹתוֹ."],[1,"","כְּשֶׁבָּאתִי וְאָמַרְתִּי אֶת הַדְּבָרִים הַלָּלוּ לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁחָכָם הָיָה. וּבֹא רְאֵה, אֵין עֵשֶׂב וְעֵשֶׂב שֶׁנּוֹלַד בָּאָרֶץ שֶׁלֹּא הָיְתָה בּוֹ חָכְמָה רַבָּה וְכֹחוֹ בַּשָּׁמַיִם רַב. בּא וּרְאֵה מִן הָאֵזוֹב, שֶׁבְּכָל מָקוֹם שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת הָאָדָם, הוּא נִטְהָר בְּאֵזוֹב. מָה הַטַּעַם? מִשּׁוּם שֶׁיִּתְעוֹרֵר כֹּחוֹ שֶׁלְּמַעְלָה שֶׁנִּפְקָד עָלָיו, שֶׁהֲרֵי כְּשֶׁמִּתְעוֹרֵר אוֹתוֹ הַכֹּחַ שֶׁנִּפְקָד עָלָיו, הוּא מְבַעֵר רוּחַ הַטֻּמְאָה וְנִטְהָר הָאָדָם. וְעָלֶיךְ אֲנִי אוֹמֵר, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילְךְ!"],[2,"","אַתֶּם רְאִיתֶם אֲשֶׁר עָשִׂיתִי לְמִצְרָיִם וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים. מַה זֶּה כַּנְפֵי יְשָׁרִים? אָמַר רַבִּי יְהוּדָה, בְּרַחֲמִים, שֶׁכָּתוּב (דבריםלב) כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'. וְהַיְנוּ סוֹד הַכָּתוּב שֶׁאָמַר רַבִּי שִׁמְעוֹן, דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. מַה זֶּה בַּשָּׁמַיִם? בְּרַחֲמִים. מָה הַנֶּשֶׁר נִמְצָא בְרַחֲמִים עַל בָּנָיו וְדִין לַאֲחֵרִים - כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְרַחֲמִים לְיִשְׂרָאֵל, וּבְדִין אֶל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת."],[3,"","רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ מִקַּפּוּטְקִיָּא לְלוֹד, וְהָיוּ הוֹלְכִים עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. קָמוּ בָאוֹר, כְּשֶׁהֵאִיר הַיּוֹם, וְהָיוּ הוֹלְכִים. אָמַר רַבִּי חִיָּיא, רָאִיתִי אֶת הַפָּסוּק הַזֶּה שֶׁכָּתוּב (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. הֲרֵי אַרְיֵה בְּיָמִין, שׁוֹר מִשְּׂמֹאל. נֶשֶׁר בְּאֵיזֶה מָקוֹם מְקוֹמוֹ?"],[4,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, בַּמָּקוֹם (שיעקב) שֶׁהַיּוֹנֵק שָׁרוּי. מָה הַטַּעַם? מִשּׁוּם שֶׁנֶּשֶׁר נִמְצָא בַּכֹּל - רַחֲמִים לְבָנָיו, וְדִין אֶל אֲחֵרִים. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא - מוֹבִיל אֶת יִשְׂרָאֵל בְּרַחֲמִים, וּבְדִין אֶל אֲחֵרִים, שֶׁכָּתוּב וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, וְכָתוּב כְּנֶשֶׁר יָעִיר קִנּוֹ."],[5,"","מִנַּיִן לָנוּ שֶׁנֶּשֶׁר נִקְרָא רַחֲמִים? שֶׁכָּתוּב (משלי ל) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בַּשָּׁמַיִם מַמָּשׁ. וְלָכֵן אַרְיֵה לְיָמִין, שׁוֹר לִשְׂמֹאל, נֶשֶׁר בֵּינֵיהֶם, וְאוֹחֵז אוֹתָם. אָדָם כּוֹלֵל אֶת כֻּלָּם, וְהַכֹּל נִכְלְלוּ בוֹ, שֶׁכָּתוּב וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה."],[6,"","וַיְהִי בַיּוֹם הַשְּׁלִישִׁי וְגוֹ'. רַבִּי אַבָּא פָּתַח, (שיר ח) אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ. אָחוֹת לָנוּ קְטַנָּה - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת אָחוֹת לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְשָׁדַיִם אֵין לָהּ - הַיְנוּ שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לְהַר סִינַי, לֹא הָיָה בָּהֶם זְכֻיּוֹת וּמַעֲשִׂים טוֹבִים לְהָגֵן עֲלֵיהֶם, שֶׁכָּתוּב וְשָׁדַיִם אֵין לָהּ, שֶׁהֲרֵי הֵם הַתִּקּוּן וְהַיֹּפִי שֶׁל הָאִשָּׁה, וְאֵין יֹפִי שֶׁל אִשָּׁה אֶלָּא הֵם. מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ - מַה יַּעֲשֶׂה מִמֶּנָּה בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְגַּלֶּה בְּהַר סִינַי לְדַבֵּר אֶת דִּבְרֵי הַתּוֹרָה וְתִפְרַח מֵהֶם נִשְׁמָתָם."],[7,"","אָמַר רַבִּי יוֹסֵי, בְּאוֹתָהּ שָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לְהַר סִינַי בְּאוֹתוֹ לַיְלָה וְנִשְׁלְמוּ, שְׁלֹשָׁה יָמִים שֶׁלֹּא הִזְדַּוְּגוּ לִנְשׁוֹתֵיהֶם, בָּאוּ מַלְאָכִים עֶלְיוֹנִים וְקִבְּלוּ אֶת יִשְׂרָאֵל בְּאַחֲוָה. אוֹתָם מַלְאָכִים לְמַעְלָה, וְיִשְׂרָאֵל מַלְאָכִים מִלְּמַטָּה. הֵם מְקַדְּשִׁים אֶת הַשֵּׁם הָעֶלְיוֹן לְמַעְלָה, וְיִשְׂרָאֵל מְקַדְּשִׁים אֶת הַשֵּׁם הָעֶלְיוֹן לְמַטָּה."],[8,"","וְהִתְעַטְרוּ יִשְׂרָאֵל בְּשִׁבְעִים כְּתָרִים בְּאוֹתוֹ לַיְלָה, וּמַלְאָכִים עֶלְיוֹנִים הָיוּ אוֹמְרִים, אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ, שֶׁאֵין בָּהֶם זְכֻיּוֹת וּמַעֲשִׂים טוֹבִים, מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ? כְּלוֹמַר, מַה כָּבוֹד וּגְדֻלָּה נַעֲשֶׂה לַאֲחוֹתֵנוּ זוֹ בַּיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְגַּלֶּה בְּהַר סִינַי לָתֵת לָהֶם תּוֹרָה?"],[9,"","(ויהי ביום השלישי). כָּתוּב הֱיוּ נְכֹנִים לִשְׁלֹשֶׁת יָמִים אַל תִּגְּשׁוּ אֶל אִשָּׁה, וְהַיְנוּ בַיּוֹם הַשְּׁלִישִׁי. רַבִּי שִׁמְעוֹן אָמַר, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִגָּלוֹת בְּהַר סִינַי, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַפָּמַלְיָה שֶׁלּוֹ וְאָמַר לָהֶם: עַכְשָׁו יִשְׂרָאֵל תִּינוֹקוֹת שֶׁאֵינָם יוֹדְעִים אֶת הַנְהָגוֹתַי, וַאֲנִי רוֹצֶה לְהִתְגַּלּוֹת עֲלֵיהֶם. אִם אֶתְגַּלֶּה אֲלֵיהֶם בְּכֹחַ הַגְּבוּרָה - לֹא יוּכְלוּ לִסְבֹּל. אֲבָל אֶתְגַּלֶּה עֲלֵיהֶם בְּרַחֲמִים וִיקַבְּלוּ אֶת הַנְהָגוֹתַי. זֶהוּ שֶׁכָּתוּב וַיְהִי בַיּוֹם הַשְּׁלִישִׁי. בַּיּוֹם הַשְּׁלִישִׁי וַדַּאי, שֶׁהוּא רַחֲמִים. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד."]]],[["וּבְהַאי אִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, אַקְדִּים לְהוּ רַחֲמֵי בְּקַדְמִיתָא. וּלְבָתַר אִתְיְיהִיב לְהוּ אוֹרַיְיתָא, מִסִּטְרָא דִּגְבוּרָה. בַיּוֹם הַשְׁלִישִׁי, דְּהָכִי אִתְחָזֵי לְהוּ, דִּבְגִינֵי כַּךְ יִשְׂרָאֵל אִקְרוּן.","בִּהְיוֹת הַבֹּקֶר, דִּכְתִּיב, (שמואל ב כ״ג:ד׳) בֹּקֶר לֹא עָבוֹת. הָא אִי הֲוָה עָבוֹת קַדְרוּתָא אִשְׁתְּכַח, וְלָא אִתְגַּלְּיָיא חֶסֶ\"ד. וְאֵימָתַי אִתְגַּלְּיָיא חֶסֶ\"ד. בַּבֹּקֶר. כְּמָה דְאַתְּ אָמֵר, (בראשית מה) הַבֹּקֶר אוֹר. דְּכַד נָהִיר צַפְרָא, חֶסֶ\"ד אִשְׁתְּכַח בְּעָלְמָא, וְדִינִין מִתְעַבְּרָן. וּבְזִמְנָא דְּלָא נָהִיר בֹּקֶר, דִּינִין עַד כְּעַן לָא מִתְעַבְּרָן. דִּכְתִּיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים. כֵּיוָן דְּאִתְעַבְּרָן אִינּוּן כֹּכָבַיָּא וְנָהִיר שִׁמְשָׁא, בֵּיהּ שַׁעֲתָא כְּתִיב, בֹּקֶר לֹא עָבוֹת. וְחֶסֶ\"ד אִתְּעַר בְּעָלְמָא תַּתָּאָה, בְּהַהִיא שַׁעֲתָא כְּתִיב, בִּהְיוֹת הַבֹּקֶר. וְכֵיוָן דְּמִתְעַבְּרָן כֹּכָבַיָּא בֹּקֶר אִשְׁתְּכַח. (נ\"א דאתער בקר, דינין לא אשתכחו)","אָמַר ר' יוֹסֵי, בִּהְיוֹת הַבֹּקֶר שָׁארֵי קוּדְשָׁא בְּרִיךְ הוּא לְאִתְגַּלָּאָה בְּטוּרָא דְּסִינַי. תָּאנָא, בִּהְיוֹת הַבֹּקֶר, כַּד אִתְּעַר זְכוּתֵיהּ דְּאַבְרָהָם, דִּכְתִּיב בֵּיהּ (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר.","וַיְהִי קֹלֹת וּבְרָקִים, אָמַר רַבִּי אַבָּא, קֹלת כְּתִיב חָסֵר. תְּרֵין קָלִין דְּאַהַדְרוּ לְחָד, דָּא נָפְקָא מִן דָּא, רוּחָא מִמַּיָּא. וּמַיָּא מֵרוּחָא. תְּרֵין דְּאִינּוּן חַד, וְחַד דְּאִיהוּ תְּרֵי.","אָמַר רַבִּי יוֹסֵי, קֹלֹת חַד, וְאִיהוּ קָלָא רַבְרְבָא תַּקִּיפָא, דְּלָא פַּסְקַת לְעָלְמִין, הַהוּא דִּכְתִּיב בֵּיהּ (דברים ה׳:י״ט) קוֹל גָּדוֹל וְלא יָסָף דְּהָא שְׁאַר קָלִין אִתְפַּסְּקָן, דְּתַנְיָא, בְּאַרְבָּעָה תְּקוּפִין בַּשַׁתָּא, קָלָא אִתְפַּסְּקַת, וּכְדֵין דִּינִין מִתְעָרִין בְּעָלְמָא. וְהַאי קָלָא דְּכָלִיל שְׁאַר קָלִין בֵּיהּ, לָא אִתְפְּסָק לְעָלְמִין, וְלָא אִתְעֲבָר מִקּיּוּמָא שְׁלִים וְתּוּקְפָּא דִּילֵיהּ. תָּאנָא, הַאי קָלָא, קָלָא דְּקַלִין, קָלָא דְּכָלִיל כָּל שְׁאַר קַלִין.","אָמַר ר' יְהוּדָה, לֵית קָלָא, אֶלָּא מִסִּטְרָא דְּרוּחָא וּמַיָּא וְאֶשָּׁא. וְכֹלָּא (דבר אחר וכלא) עָבִיד קָלָא, וְאִתְכְּלִיל דָּא בְּדָא, וְעַל דָּא כְּתִיב קֹלֹת. וּבְרָקִים, אָמַר רִבִּי יוֹסֵי, הַיְינוּ דִּכְתִּיב, (תהילים קל״ה:ז׳) בְּרָקִים לַמָּטָר עָשָׂה, שַׁלְהוֹבָא בְּעוּטְרֵי, קְטִירָא דְּרַחֲמֵי בְּחִיבָּתָא, דְּלָא (שקיע) שְׁכִיחוּ.","תָּנָא, ר' יְהוּדָה אוֹמֵר, בִּסְטַר גְּבוּרָה, אוֹרַיְיתָא אִתְיְיהִיבַת. אָמַר רַבִּי יוֹסֵי, אִי הָכִי בִּסְטַר שְׂמָאלָא הֲוִי. אָמַר לֵיהּ, אִתְהַדַּר לִימִינָא. דִּכְתִּיב, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. וּכְתִיב (שמות ט״ו:ו׳) יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ וְגוֹ'. אַשְׁכְּחָן שְׂמָאלָא דְּאִתְחַזָּר לִימִינָא, וִימִינָא לִשְׂמָאלָא, הָא גְּבוּרָה לִשְׂמָאלָא (דבר אחר לימינא).","וְעָנָן כָּבֵד עַל הָהָר וְגוֹ', עֲנָנָא תַּקִּיף, דִּשְׁקִיעַ בְּאַתְרֵיהּ, דְּלָא נָטִיל. וְקֹל שֹׁפָר חָזָק מְאֹד, מִגּוֹ דַּעֲנָנָא תַּקִּיף הֲוָה, נָפִיק הַהוּא קָלָא, כְּמָה דְאַתְּ אָמֵר (דברים ה׳:כ׳) וַיְהִי כְּשָׁמְעֲכֶם אֶת הַקּוֹל מִתּוֹךְ הַחֹשֶׁךְ.","אָמַר רַבִּי יְהוּדָה, תְּלַת חֲשׁוֹכֵי הֲווֹ, דִּכְתִּיב חֹשֶׁךְ עָנָן וַעֲרָפֶל. וְהַהוּא קָלָא הֲוָה נָפִיק פְּנִימָאָה מִכֻּלְּהוּ. אָמַר רַבִּי יוֹסֵי, פְּנִימָאָה דְּכֹלָּא הֲוָה, דְּבֵיהּ כְּתִיב, קוֹל גָּדוֹל וְלֹא יָסָף.","אָמַר ר' אַבָּא כְּתִיב (שמות כ׳:ט״ו) וְכָל הָעָם רֹאִים אֶת הַקּוֹלוֹת. רֹאִים, שֹׁמְעִים מִבָּעֵי לֵיהּ. אֶלָּא הָכִי תָּנִינָן, אִינּוּן קָלִין, הֲווֹ מִתְגַּלְּפֵי בְּהַהוּא חֲשׁוֹכָא וַעֲנָנָא וְקַבָּלָא, וּמִתְחַזְיָין בְּהוּ, כְּמָה דְּאִתְחָזֵי גּוּפָא, וְחָמָאן מַה דְּחָמָאן, וְשַׁמְעִין מַה דְּשַׁמְעִין, מִגּוֹ הַהוּא חֲשׁוֹכָא וְקַבָּלָא וַעֲנָנָא, וּמִגּוֹ הַהוּא חֵיזוּ דַּהֲווֹ חָמָאן, הֲווֹ נְהִירִין בִּנְהִירוּ עִלָּאָה, וְיַדְעִין, מַה דְּלָא יָדְעוּ דָּרִין אַחֲרָנִין, דְּאָתוּ בַּתְרַיְיהוּ.","וְכֻלְּהוּ, הֲווֹ חָמָאן אַפִּין בְּאַפִּין, הֲדָא הוּא דִכְתִיב, (דברים ה׳:ד׳) פָּנִים בְּפָנִים דִּבֶּר יְיָ' עִמָּכֶם. וּמַאן הֲווֹ חָמָאן. תָּאנֵי רַבִּי יוֹסֵי, מִנְּהִירוּ דְּאִינּוּן קַלָן, דְּלָא הֲוָה קוֹל, דְּלָא הֲוָה נָהִיר בִּנְהִירוּ, דְּמִסְתַּכְלֵי בֵּיהּ כָּל גְּנִיזִין, וְכָל טְמִירִין, וְכָל דָּרִין דְּיֵיתוּן עַד מַלְכָּא מְשִׁיחָא. וּבְגִינֵי כַּךְ כְּתִיב וְכָל הָעָם רֹאִים אֶת הַקּוֹלת, רֹאִים רְאִיָּה מַמָּשׁ."],[[0,"ובהאי אתגלי קב\"ה וכו':","ובזה נגלה הקב\"ה לישראל, שהקדים להם רחמים בתחילה, ואה\"כ נתן להם התורה מצד הגבורה ביום השלישי, ונמצאים כלולים מרחמים וגבורה, כי כן ראוי להם, ובשביל כך נקראים ישראל. שהשם ישראל יורה על התכללות רחמים וגבורה."],[1,"בהיות הבקר:","שכתוב בקר לא עבות. כי אם היה עבות, היה נמצא בחושך, ולא היה נגלה החסד. ומתי נגלה החסד, בבקר. כש\"א, הבוקר אור. כי כשהאיר הבקר נמצא חסד בעולם, והדינים נעברים. ובזמן שאין הבקר מאיר, עוד לא נעברו הדינים, שכתוב, ברן יחד ככבי בקר ויריעו כל בני אלקים. כיון שנעברו הככבים, והשמש מאיר, בשעה ההיא, כתוב, בקר לא עבות, וחסד מתעורר בעולם התחתון, בשעה ההיא כתוב בהיות הבקר. שכיון שנעברו הככבים נמצא הבקר."],[2,"אמר ר' יוסי וכו':","אר\"י, בהיות הבקר התחיל הקב\"ה להתגלות על הר סיני, למדנו, \u0003בהיות הבוקר,\u0004 היינו כשנתעוררה זכותו של אברהם, שכתוב בו, וישכם אברהם בבקר."],[3,"ויהי קלת וברקים:","אמר ר' אבא, קלת כתוב חסר ו' של סימן הרבים, יורה על שני קולות שחזרו לאחד, זה יוצא מן זה, רוח ממים, ומים מרוח, שנים שהם אחד, ואחד שהוא שנים. וע\"כ כתוב קלת חסר ו'."],[3,"","פירוש. כעין קול הגשמי, שהוא מורכב מרוח ומים, כן קול הרוחני מורכב ממים, שה\"ס קו ימין, ומרוח שה\"ס קו אמצעי. וברוח ומים אלו יש ב' בחינות, א) בג' קוין דבינה, ששם קו אמצעי שהוא \u0003רוח\u0004 הוא תולדה מקו הימין שהוא \u0003מים.\u0004 והיינו \u0003רוח ממים.\u0004 ב) בג' קוין דז\"א, כי אח\"כ כשנתפשט קו אמצעי מבינה ויורד במקום ז\"א בסוד חד בתלת קיימא (בראשית א' אות שס\"ג) נמצא בו שקו אמצעי הוא שורש וסבה לב' קוין ימין ושמאל, (כמ\"ש שם בסולם) ונמצא \u0003שהמים\u0004 שה\"ס קו ימין, הוא כמו תולדה מן \u0003הרוח\u0004 שה\"ס קו אמצעי, והיינו \u0003מים מרוח.\u0004 והנה מצד אחד אפשר לומר שאלו ב' בחינות הן אחת, כי לא נמשך לז\"א אלא מה שיש בבינה. וז\"ש \u0003תרין קלין דאהדרו לחד,\u0004 שהרי \u0003דא נפקא מן דא.\u0004 ומצד הב', אפשר לומר שהן שנים, כי קול אחד הוא בבינה, וקול הב' הוא בז\"א. וז\"ש \u0003תרין דאינון חד וחד דאיהו תרי.\u0004 שאפשר לומר כך ואפשר לומר כך, וע\"כ כתוב, קלת, חסר ו' של סימן הרבים."],[4,"אמר ר' יוסי וכו':","אר\"י, קלת, היינו אחד, והוא קול גדול וחזק שאינו נפסק, לעולם. ההוא, שכתוב בו, קול גדול ולא יסף. שה\"ס הרוח שבאו\"א עלאין, שאין הי' יוצאת מאויר שלהם, וקומת רוח שבהם נשאר קיים לעולם בלי שינוי. (כנ\"ל בראשית א' דף רנ\"א ד\"ה נחית עש\"ה) ורוח הזה מאיר גם בזו\"ן הגדולים (כנ\"ל בהקדמת ספר הזהר דף מ\"ד ד\"ה וטעם) כי שאר הקולות נפסקים, שלמדנו בארבע תקופות בשנה הקול נפסק, ואז דינים מתעוררים בעולם. וקול הזה, שכולל שאר הקולות בו, אינו נפסק לעולם, ואינו נעבר מקיום השלם והתוקף שלו. למדנו, קול הזה הוא קול הקולות, קול הכולל כל שאר הקולות."],[4,"","פירוש. בד' תקופות השנה מתעורר שליטת קו השמאל, ואז תיכף נפסק הקול, שה\"ס קומת החסדים, ודינים שולטים בעולם. וזהו רק בקול של ישסו\"ת ושל ז\"א אבל בקול של או\"א, אין השמאל שולט להפסיקו והחסדים אינם פוסקים מהם לעולם. וקול הזה כולל כל הקולות שלמטה ממנו."],[5,"אמר ר' יהודה וכו:","אר\"י, אין קול אלא מצד רוח ומים ואש, שהם ג' קוין. והכל עושה הקול, שהוא קו האמצעי, ועל ידו נכללים הקוים זה בזה ונעשו לאחד, וע\"כ כתוב קלת, חסר ו' של סימן הרבים. וברקים, אמר ר' יוסי, היינו שכתוב, ברקים למטר עשה, כלומר שברקים פירושו, אש המחובר במים, כמו ברקים במטר. ששלהבת הברק במטר, יורה שהוא קשר של רחמים באהבה שאינה מצויה. וצריך לומר שלהובא במטרא, ולא בעוטרי."],[6,"תנא, ר' יהודה וכו':","למדנו, ר' יהודה אומר, בצד הגבורה ניתנה התורה. אמר ר' יוסי, אם כן התורה היא בצד שמאל. אמר לו שחזרה לימין, שכתוב מימינו אש דת למו. וכתוב, ימינך ה' נאדרי בכח. הרי מצאנו, ששמאל נכלל בימין, שכתוב, מימינו אש וגו'. וימין בשמאל, שכתוב ימינך ה' נאדרי בכח. הרי שגבורה, שהיא שמאל, נכללה בימין."],[7,"וענן כבד על ההר וגו':","היינו ענן חזק השקוע במקומו מחמת הכבד שלו, ואינו נוסע ממקום למקום כשאר עננים, \u0003וקל שפר חזק מאד.\u0004 כי מתוך שהענן היה חזק יצא קול ההוא, כדי לשברו. כש\"א, ויהי בשמעכם הקול מתוך החשך."],[8,"אמר ר' יהודה וכו':","אר\"י, ג' מיני חושך היו, שכתוב, חשך ענן וערפל. וקול ההוא דהיינו הקול שופר, היה יוצא פנימי מכולם. אמר ר' יוסי, פנימיות הכל היה הקול, שבו כתוב, קול גדול ולא יסף."],[9,"וכל העם רואים את הקולות:","שואל, הכתוב אומר, רואים, שומעים היה צריך לומר. ומשיב, אלא כך למדנו, אלו הקולות היו נחקקים בחשך ענן וערפל, ונראים בהם, כמו שנראה גוף, ורואים מה שרואים, ושומעים מה ששומעים, מתוך חשך וערפל וענן אלו, ומתוך מראה ההיא שהיו רואים היו מאירים בהארה עליונה, ויודעים מה שלא ידעו דורות אחרים הבאים אחריהם."],[10,"וכלהו הוו חמאן וכו':","וכולם היו רואים פנים בפנים, ז\"ש פנים בפנים דבר ה' עמכם. ומי היו רואים. תאני ר' יוסי, מהארת קולות האלו, שלא היה קול, שלא היה מאיר בהארה, שמסתכלים בה כל הגנוזות, וכל הנסתרות, וכל הדורות שיבואו עד מלך המשיח. ומשום זה כתוב, וכל העם \u0003רואים\u0004 את הקולות, רואים ראיה ממש."]],[[0,"","וּבָזְהִ הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. הִקְדִּים לָהֶם רַחֲמִים בַּתְּחִלָּה, וְאַחַר נִתְּנָה לָהֶם תּוֹרָה מִצַּד הַגְּבוּרָה. בַיּוֹם הַשְּׁלִישִׁי, שֶׁכָּךְ רָאוּי לָהֶם, שֶׁבִּגְלַל כָּךְ נִקְרְאוּ יִשְׂרָאֵל."],[1,"","בִּהְיוֹת הַבֹּקֶר, שֶׁכָּתוּב (שם כג) בֹּקֶר לֹא עָבוֹת. הֲרֵי אִם הָיָה עָבוֹת, אָז נִמְצֵאת קַדְרוּת וְלֹא הִתְגַּלָּה חֶסֶ\"ד. וּמָתַי מִתְגַּלֶּה חֶסֶ\"ד? בַּבֹּקֶר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מד) הַבֹּקֶר אוֹר. שֶׁכְּשֶׁמֵּאִיר הַבֹּקֶר, נִמְצָא חֶסֶ\"ד בָּעוֹלָם וְהַדִּינִים עוֹבְרִים. וּבִזְמַן שֶׁלֹּא מֵאִיר הַבֹּקֶר, הַדִּינִים עַד אָז לֹא עוֹבְרִים, שֶׁכָּתוּב (איובלח) בְּרָן יַחַד כֹּכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. כֵּיוָן שֶׁעָבְרוּ אוֹתָם כּוֹכָבִים וּמֵאִיר הַשֶּׁמֶשׁ, בְּאוֹתָהּ שָׁעָה כָּתוּב בֹּקֶר לֹא עָבוֹת, וְחֶסֶ\"ד מִתְעוֹרֵר בָּעוֹלָם הַתַּחְתּוֹן. בְּאוֹתָהּ שָׁעָה כָּתוּב בִּהְיוֹת הַבֹּקֶר. וְכֵיוָן שֶׁעָבְרוּ הַכּוֹכָבִים, נִמְצָא הַבּקֶר. (כשהתעורר הבקר, דינים לא נמצאו)."],[2,"","אָמַר רַבִּי יוֹסֵי, בִּהְיוֹת הַבֹּקֶר הִתְחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְגַּלּוֹת בְּהַר סִינַי. שָׁנִינוּ בִּהְיוֹת הַבֹּקֶר - כְּשֶׁהִתְעוֹרְרָה זְכוּתוֹ שֶׁל אַבְרָהָם שֶׁכָּתוּב בּוֹ (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר."],[3,"","וַיְהִי קֹלֹת וּבְרָקִים. אָמַר רַבִּי אַבָּא, קֹלֹת כָּתוּב חָסֵר. שְׁנֵי קוֹלוֹת שֶׁחָזְרוּ לִהְיוֹת אֶחָד. זֶה יוֹצֵא מִזֶּה. רוּחַ מִמַּיִם, וּמַיִם מֵרוּחַ. שְׁנַיִם שֶׁהֵם אֶחָד, וְאֶחָד שֶׁהוּא שְׁנַיִם."],[4,"","אָמַר רַבִּי יוֹסֵי, קֹלֹת אֶחָד, וְהוּא קוֹל גָּדוֹל חָזָק שֶׁאֵינוֹ פוֹסֵק לְעוֹלָמִים, הוּא שֶׁכָּתוּב בּוֹ קוֹל גָּדוֹל וְלֹא יָסָף, שֶׁהֲרֵי שְׁאָר הַקּוֹלוֹת פּוֹסְקִים, שֶׁשָּׁנִינוּ, בְּאַרְבַּע תְּקוּפוֹת בַּשָּׁנָה הַקּוֹל נִפְסָק, וְאָז הַדִּינִים מִתְעוֹרְרִים בָּעוֹלָם, וְקוֹל זֶה שֶׁכּוֹלֵל בּוֹ אֶת שְׁאָר הַקּוֹלוֹת, לֹא נִפְסָק לְעוֹלָמִים וְלֹא עוֹבֵר מִקִּיּוּם שָׁלֵם וְהַחֹזֶק שֶׁלּוֹ. שָׁנִינוּ, קוֹל זֶה קוֹל שֶׁל הַקּוֹלוֹת, קוֹל שֶׁכּוֹלֵל אֶת כָּל שְׁאָר הַקּוֹלוֹת."],[5,"","אָמַר רַבִּי יְהוּדָה, אֵין קוֹל אֶלָּא מִצַּד רוּחַ וּמַיִם וְאֵשׁ, וּבַקּוֹל (והכל) עוֹשֶׂה קוֹל, וְנִכְלָל זֶה בָּזֶה, וְעַל זֶה כָּתוּב קֹלֹת וּבְרָקִים. אָמַר רַבִי יוֹסֵי, הַיְנוּ מַה שֶּׁכָּתוּב (תהלים קלה) בְּרָקִים לַמָּטָר עָשָׂה. שַׁלְהֶבֶת בַּעֲטָרוֹת, קֶשֶׁר שֶׁל רַחֲמִים בְּחִבָּה, שֶׁלֹּא (שוקעת) מְצוּיִים."],[6,"","שָׁנִינוּ, רַבִּי יְהוּדָה אוֹמֵר, בְּצַד הַגְּבוּרָה נִתְּנָה הַתּוֹרָה. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, הִיא הָיְתָה בְּצַד שְׂמֹאל? אָמַר לוֹ, הָחְזְרָה לְיָמִין, שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וְכָתוּב יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ וְגוֹ'. מָצָאנוּ שְׂמֹאל שֶׁהָחְזַר לְיָמִין, וְיָמִין לִשְׂמֹאל. הֲרֵי גְּבוּרָה לִשְּׂמֹאל (לימין)."],[7,"","וְעָנָן כָּבֵד עַל הָהָר וְגוֹ' - עָנָן חָזָק שֶׁשָּׁקוּעַ בִּמְקוֹמוֹ, שֶׁלֹּא לוֹקֵחַ. וְקֹל שֹׁפָר חָזָק מְאֹד - מִתּוֹךְ הֶעָנָן הֶחָזָק הָיָה יוֹצֵא אוֹתוֹ הַקּוֹל, כְּמוֹ שֶׁנֶּאֱמַר (דבריםה) וַיְהִי כְּשָׁמְעֲכֶם אֶת הַקּוֹל מִתּוֹךְ הַחֹשֶׁךְ."],[8,"","אָמַר רַבִּי יְהוּדָה, שָׁלֹשׁ חֲשֵׁכִים הָיוּ, שֶׁכָּתוּב חֹשֶׁךְ עָנָן וַעֲרָפֶל. וְאוֹתוֹ קוֹל הָיָה יוֹצֵא פְּנִימִי מִכֻּלָּם. אָמַר רַבִּי יוֹסֵי, הַפְּנִימִי שֶׁל הַכֹּל הָיָה, שֶׁבּוֹ כָּתוּב קוֹל גָּדוֹל וְלֹא יָסָף."],[9,"","אָמַר רַבִּי אַבָּא, כָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. רֹאִים? שׁוֹמְעִים הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּךְ שָׁנִינוּ, אוֹתָם קוֹלוֹת הָיוּ נֶחְקָקִים בְּאוֹתוֹ חֹשֶׁךְ וְעָנָן וַעֲרָפֶל וְנִרְאִים בָּהֶם כְּמוֹ שֶׁנִּרְאֶה גוּף, וְרוֹאִים מַה שֶּׁרוֹאִים, וְשׁוֹמְעִים מַה שֶּׁשּׁוֹמְעִים מִתּוֹךְ אוֹתוֹ חֹשֶׁךְ וַעֲרָפֶל וְעָנָן, וּמִתּוֹךְ אוֹתוֹ מַרְאֶה שֶׁהָיוּ רוֹאִים, הָיוּ מְאִירִים בְּאוֹר עֶלְיוֹן, וְיוֹדְעִים מַה שֶּׁלֹּא יָדְעוּ דּוֹרוֹת אַחֲרוֹנִים שֶׁבָּאוּ אַחֲרֵיהֶם."],[10,"","וְכֻלָּם הָיוּ רוֹאִים פָּנִים בְּפָנִים, זֶהוּ שֶׁכָּתוּב פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם. וּמֶה הָיוּ רוֹאִים? שָׁנָה רַבִּי יוֹסֵי, מֵהָאוֹר שֶׁל אוֹתָם הַקּוֹלוֹת, שֶׁלֹּא הָיָה קוֹל, שֶׁלֹּא הָיָה מֵאִיר בְּאוֹר, שֶׁמִּסְתַּכְּלִים בּוֹ כָּל הַגְּנָזִים, וְכָל הַנִּסְתָּרִים, וְכָל הַדּוֹרוֹת שֶׁיָּבאוּ עַד מֶלֶךְ הַמָּשִׁיחַ. וּמִשּׁוּם כָּךְ כָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. רֹאִים - רְאִיָּה מַמָּשׁ."]]],[["אָמַר רַבִּי אֶלְעָזָר, וְכָל הָעָם רֹאִים. רֹאִים: כְּמָה דַּאֲמֵינָא, דְּחָמוּ מִנְּהִירוּ דְּאִינּוּן קַלָן, מַה דְּלָא חָמוּ דָּרִין בַּתְרָאִין אַחֲרָנִין. אֶת הַקּוֹלֹת: כְּמָה דְאַתְּ אָמֵר, (ישעיה ו) וָאֵרֶא אֶת יְיָ'. וָאֵרֶא יְיָ', לָא כְּתִיב, אֶלָּא אֶת יְיָ'. אוּף הָכָא, וְכָל הָעָם רֹאִים הַקּוֹלת לֹא נֶאֱמַר, אֶלָּא אֶת הַקּוֹלֹת.","כְּגַוְונָא דָּא, אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, דְּהָא אָתִין דִּבְאוֹרַיְיתָא, לְאִסְתַּכְּלָא בְּאוֹרַיְיתָא (נ\"א בחכמתא) אִתְיְיהִיבוּ. (שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ (משלי ג׳:ט׳) כַּבֵּד אֶת יְיָ' מֵהוֹנֶךָ. וְכֻלְּהוּ לְאִתְכְּלָלָא בְּהוּ מִלָּה אַחֲרָא. אוּף הָכָא, אֶת הַקּוֹלֹת, לְאַסְגָּאָה הַהוּא קָלָא אַחֲרָא לְתַתָּא, דְּכָנִישׁ לוֹן לְגַבֵּיהּ, מַה דְּנָפִיק מִנַּיְיהוּ, דְּבֵיהּ חָמָאן וּמִסְתַּכְּלָן בְּחָכְמְתָא עִלָּאָה כָּל גִּנְזִין עִלָּאִין, וְכָל רָזִין טְמִירִין וּסְתִימִין, מַה דְּלָא אִתְגַּלְּיָיא לְדָרִין בַּתְרָאִין, דְּאָתוּ בַּתְרֵיהוֹן, וְלָא לְדָרִין דְּיֵיתוּן לְעָלְמִין, עַד זִמְנָא דְּיֵיתֵי מַלְכָּא מְשִׁיחָא. דִּכְתִּיב, (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יֵרָאוּ בְּשׁוּב יְיָ' צִיּוֹן. וְאֶת הַלַּפִּידִים, בְּקַדְמִיתָא בְּרָקִים, וְהַשְׁתָּא לַפִּידִים. כֹּלָּא חַד. אֲבָל מִדְּאִתְתְּקָנוּ בְּתִקּוּנוֹי לְאִתְחֲזָאָה, אִתְקְרוּן הָכִי.","וְאֵת קוֹל הַשׁוֹפָר. תָּאנֵי רַבִּי יִצְחָק, כְּתִיב (תהילים ס״ב:י״ב) אַחַת דִּבֶּר אֱלהִים שְׁתַּיִם זוּ שָׁמַעְתִּי, כְּמָה דְאַתְּ אָמֵר, אָנֹכִי, וְלא יִהְיֶה לְךָ.","אָמַר רִבִּי יְהוּדָה, קֹל בַּשֹׁפָר מִבָּעֵי לֵיהּ. הַשֹׁפָר לָמָּה. אֶלָּא, הַהוּא קוֹל דְּאִקְרֵי שׁוֹפָר. דִּכְתִּיב, (ויקרא כ״ה:ט׳) וְהַעֲבַרְתָּ שׁוֹפָר תְרוּעָה בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ בְּיוֹם הַכִּפּוּרִים, בְּדָא אִתְבְּרֵי (אתקרי) שׁוֹפָר.","אָמַר רִבִּי יוֹסֵי, מַה שׁוֹפָר, אַפִּיק קָלָא, אֶשָּׁא וְרוּחָא וּמַיָּא, אוּף הָכָא, כֹּלָּא אִתְכְּלִיל בְּהַאי, וּמִדָּא נָפְקִין קָלִין אַחֲרָנִין.","אָמַר רִבִּי אֶלְעָזָר, קוֹל דְּנָפִיק מִשּׁוֹפָר, דְּמַשְׁמַע דְּשׁוֹפָר חַד, וְקוֹל נָפִיק מִנֵּיהּ, וְשּׁוֹפָר בְּקִיוּמֵיהּ שְׁכִיחַ, וּבְגִינֵי כָּךְ כְּתִיב, קוֹל הַשֹׁפָר.","רַבִּי יְהוּדָה אָמַר הָכִי, קוֹל הַשֹׁפָר, הַשֹׁפָר כְּתִיב חָסֵר, כְּמָה דְאַתְּ אָמֵר, (דניאל ו׳:ב׳) שְׁפַר קֹדֶם דָּרְיָוֶשׁ. (דניאל ד׳:כ״ד) מִלְכִּי יִשְׁפַּר עֲלָךְ. (דניאל ג׳:ל״ב) שְׁפַר קֳדָמַי לְהַחֲוָיָא.","רַבִּי שִׁמְעוֹן אָמַר, קוֹל הַשֹׁפָר, אַתְרָא דְּקָלָא נָפִיק מִנֵּיהּ, אִקְרֵי שׁוֹפָר. תּוּ אָמַר רַבִּי שִׁמְעוֹן, תָּא חֲזֵי, קוֹל הַשׁוֹפָר: אַתְרָא דְּקָלָא, הַיְינוּ דִּכְתִּיב, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָא פִּי יְיָ' יִחְיֶה הָאָדָם. מַאי מוֹצָא פִּי יְיָ'. דָּא קוֹל (ס\"א דנפיק משופר והאי קול) הַשׁוֹפָר, הוּא רַב מִכָּל שְׁאַר קַלֵי תַּתָּאֵי, וְתַקִּיפָא מִכֻּלְּהוּ, דִּכְתִּיב וְקוֹל שֹׁפָר חָזָק מְאֹד, וְעַל כָּל שְׁאַר קָלִין לָא אִתְּמַר חָזָק מְאֹד. (נ\"א אמר רבי שמעון) בְּהַאי קוֹל הַשׁוֹפָר תַּלְיָא כֹּלָּא, וְדָא הוּא דְּאִקְרֵי קוֹל גָּדוֹל, דִּכְתִּיב קוֹל גָּדוֹל וְלא יָסָף. וְאִקְרֵי (מלכים א י״ט:י״ב) קוֹל דְּמָמָה דַקָּה, נְהִירוּ דְּבוּצִינֵי, דְּהוּא זַךְ וְדָקִיק, וְזָכִיך וְנָהִיר לְכֹלָּא.","דְּמָמָה, מַהוּ דְּמָמָה. אָמַר רַבִּי שִׁמְעוֹן, דְּבָעֵי בַּר נָשׁ לְמִשְׁתּוֹקָא מִנֵּיהּ, וּלְמֶחֱסָם פּוּמֵיהּ. כְּמָה דְאַתְּ אָמֵר, (תהילים ל״ט:ב׳) אָמַרְתִּי אֶשְׁמְרָה דְּרָכַי מֵחֲטוֹא בִלְשׁוֹנִי אֶשְׁמְרָה לְפִי מַחְסוֹם. דְּמָמָה אִיהִי שְׁתּוּקָא דְּלָא אִשְׁתְּמַע לְבַר. וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק, דְּחָמוּ מַה דְּחָמוּ. וַיָּנוּעוּ כְּמָה דְאַתְּ אָמֵר (ישעיהו ו׳:ד׳) וַיָּנוּעוּ אַמּוֹת הַסִּפִּים מִקּוֹל הַקּוֹרֵא.","תָּאנָא, מַה כְּתִיב בֵּיהּ בִּיחֶזְקֵאל, כַּד חָמָא גְּבוּרָן נִימוּסֵי קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (יחזקאל א׳:ד׳) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה וְגוֹ', רוּחַ סְעָרָה אֲמַאי. אָמַר רִבִּי יוֹסֵי, לְתַבְרָא אַרְבַּע מַלְכְּוַון. אָמַר רִבִּי יְהוּדָה, תַּנִּינָא, רוּחָא רַבָּה, דְּאִתְּעַר בְּנִימוּסֵי גְּבוּרָה דִּלְעֵילָּא בָּאָה מִן הַצָּפוֹן. מִצָּפוֹן לָא כְּתִיב אֶלָּא מִן הַצָּפוֹן הַהוּא דְּאִשְׁתְּמוֹדָע לְעֵילָּא, הַהוּא דְּטָמִיר וְגָנִיז לְעֵילָּא.","עָנָן גָּדוֹל וְאֵשׁ מִתְלַקַּחַת, דְּהֲוָה אָחִיד בֵּיהּ, (ס\"א ולא אחיד, אחיד בסטרוי וכו'), וְלָא הָוָה אָחִיד בְּסִטְרוֹי לְאִתְּעָרָא דִּינָא, דְּתָנֵינָן, תְּלַת זִמְנִין בְּיוֹמָא, יַנְקָא הַהוּא דִּינָא קַשְׁיָא, בְּקַרְדִיטֵי גְּלִיפִין מִסִּטְרָא דִּגְבוּרָה, הֲדָא הוּא דִכְתִיב וְאֵשׁ מִתְלַקַּחַת. בְּגִין לְאִתְּעָרָא בְּעָלְמָא.","וּמַה מְבַסֵּם לֵיהּ, הַהוּא דִּכְתִּיב בֵּיהּ וְנֹגַהּ לוֹ סָבִיב. דְּהַהוּא זִיהֲרָא דְּאַסְחַר לֵיהּ מִכָּל סִטְרוֹי, מְבַסֵּם לֵיהּ, וּמַתְקִין לֵיהּ, בְּגִין דְּלָא לֶהוֵי דִּינָא קַשְׁיָא, וְיֵיכְלוּן בְּנֵי נָשָׁא לְמִסְבְּלֵיהּ.","(יחזקאל א׳:ד׳) וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל, תָּאנָא, וּמִתּוֹכָהּ: וּמִגַּוָּוהּ. כְּעֵין הַחַשְׁמַל, מַאי חַשְׁמַל. אָמַר רִבִּי יְהוּדָה, (ק\"ט ע\"ב, ר\"ג ע\"ב, רמ\"ז ע\"א) חַיּוֹת אֶשָּׂא מְמַלְּלָא.","תָּאנָא, אָמַר רִבִּי יוֹסֵי, חַשְׁמַל: מַה דְּהֲוָה לִבָּא לְאֶשָּׁא, דִּכְתִּיב מִתּוֹךְ הָאֵשׁ כְּעֵין הַחַשְׁמַל. וְלֹא הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, מִגּוֹ אֶשָּׁא דְּאִיהִי לְגוֹ בְּאֶשָּׁא. כְּעֵין הַחַשְׁמַל דְּאִיהִי בָּתַר אַרְבַּע דַּרְגִּין, דִּכְתִּיב, רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב. וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, הַהוּא דִּכְתִּיב בֵּיהּ וְאֵשׁ מִתְלַקַּחַת."],[[0,"אמר ר' אלעזר וכו':","אר\"א, וכל העם רואים. \u0003רואים,\u0004 הוא כמו שאמרנו, שראו מהארת הקולות האלו, מה שלא ראו דורות אחרונים האחרים. \u0003את הקולות,\u0004 הוא כש\"א, וארא את ה'. וארא ה', לא כתוב, אלא \u0003את\u0004 ה', שפירושו, שראה השכינה שנקראת \u0003את.\u0004 אף כאן וכל העם רואים הקולות לא נאמר, אלא, \u0003את\u0004 הקולות. שסובב גם כן על ראית השכינה."],[1,"כגוונא דא את וכו':","כעין זה, את השמים ואת הארץ, כי האתין שבתורה, ניתנו להסתכל בחכמה. כמו כבד את אביך ואת אמך. כבד את ה' מהונך. וכולם נדרשים לכלול בהם דבר אחר. אף כאן \u0003את\u0004 הקולות לרבות קול אחר ההוא שלמטה, שהוא המלכות, שמקבץ אותם הקולות אליו ומה שיוצא מהם, שבו, במלכות, רואים ומסתכלים בחכמה עליונה כל גנזי עליונים, וכל סודות הנעלמים והסתומים, מה שלא נגלה לדורות אחרונים הבאים אחריהם, ולא לדורות שיבואו לעולם, עד הזמן שיבא מלך המשיח. שכתוב, כי עין בעין יראו בשוב ה' ציון. \u0003ואת הלפידים,\u0004 שואל, בתחילה קורא אותם ברקים, ועתה לפידים. ומשיב, הכל אחד, אלא אחר שנתקנו הברקים בתקוניהם, להראות, נקראים כך, לפידים."],[2,"ואת קול השופר:","תאני ר' יצחק, כתוב, אחת דבר אלקים שתים זו שמעתי, כמש\"א, אנכי ולא יהיה לך. שאנכי ה\"ס בינה, ולא יהיה לך, ה\"ס ז\"א, ונשמעו שניהם בבת אחת, אף כאן קול הוא ז\"א. השופר, הוא בינה, ונשמעו שניהם בבת אחת."],[3,"אמר ר' יהודה וכו':","אר\"י, קל בשפר, היה צריך לומר, למה אומר השופר, ומשיב, אלא קול ההוא שנקרא שופר, שכתוב, והעברת שופר תרועה בחדש השביעי בעשור לחדש ביום הכפורים. בזה, ביום הכפורים שהוא בינה, נקרא שופר. כלומר, אם הקול יוצא מבינה, נקרא הקול שופר."],[4,"א\"ר יוסי וכו':","אר\"י, מה שופר הגשמי, מוציא קול הכלול אש רוח ומים, אף כאן הכל נכלל בזה שגם כאן כלול בקול היוצא משפר, אש רוח ומים, שהם חג\"ת, סוד ג' הקוין. ומקול הזה יוצאים קולות אחרים."],[5,"אמר ר' אלעזר וכו':","אר\"א, קול השופר פירושו, קול היוצא משופר, שמשמע, ששופר הוא אחד, וקול היוצא ממנו הוא אחד, שהקול ה\"ס ז\"א, והשופר ה\"ס בינה, והשופר נמצא בקיומו מבחוץ הקול היוצא ממנו, ועל כך כתוב, קל השפר. ולא קל בשפר."],[6,"ר' יהודה אמר וכו':","רי\"א כך, קל השפר, השפר כתוב חסר ו', שפירושו הוא כמש\"א, שפר קדם דריוש. מלכי ישפר עלך. שפר קדמי להחויא. דהיינו לשון תפארת ויופי הרומז על ז\"א שה\"ס ת\"ת."],[7,"רבי שמעון אמר וכו':","רש\"א, קול השפר, היינו, כי המקום שהקול יוצא ממנו נקרא שופר. כי הקול הוא ז\"א, והשופר הוא בינה, וז\"א יוצא מבינה, כנודע. עוד אמר ר' שמעון, בוא וראה, שקול השופר הוא המקום של הקול, כי היינו שכתוב, כי על כל מוצא פי ה' יחיה האדם. מהו, מוצא פי ה'. זהו קול השופר, הוא גדול מכל שאר קולות התחתונים וחזק מכולם. שכתוב, וקול שופר חזק מאד, ועל כל שאר הקולות לא נאמר, חזק מאד. בקול שופר הזה תלוי הכל, וזה שנקרא קול גדול, שכתוב, קול גדול ולא יסף. ונקרא, קול דממה דקה, שהוא האור של המאור, שהוא זך ודק, ומזכך ומאיר לכל."],[8,"דממה מהו דממה וכו':","כתוב, דממה, מהו דממה. אמר ר\"ש, שאדם צריך לשתוק מפחדו ולסגור פיו. כש\"א, אמרתי אשמרה דרכי מחטוא בלשוני אשמרה לפי מחסום. דממה, היא שתיקה, שאינו נשמע לחוץ. וירא העם וינעו ויעמדו מרחוק. כי ראו מה שראו, והיו מפחדים. וינעו הוא כש\"א, וינועו אמות הספים מקול הקורא."],[9,"תאנא מה כתיב וכו':","למדנו. מה כתוב בו ביחזקאל, כאשר ראה הגבורות מנהגיו של הקב\"ה. שכתוב, וארא והנה רוח סערה באה וגו'. רוח סערה למה. אמר ר' יוסי, כדי לשבר ארבע מלכיות. אמר ר' יהודה, למדנו, הוא רוח גדול שנתעורר במנהגי הגבורה של מעלה. \u0003באה מן הצפון:\u0004 מצפון לא כתוב, אלא מן הצפון, עם ה' הידיעה, יורה על רוח ההוא הנודע למעלה, ההוא, שמכוסה וגנוז למעלה. רומז על מלכות דמדת הדין, המכוסה וגנוזה בג\"ר דכל מדרגה.(כנ\"ל בהקדמת ספר הזהר דף מ\"ד ד\"ה וטעם)."],[10,"ענן גדול ואש מתלקחת:","מתלקחת, פירושו, שהיה נאחז בו ולא נאחז בו, נאחז בצדדיו לעורר הדין, שלמדנו, ג' פעמים ביום, יונק דין קשה ההוא בחקיקות הגבוהות מצד הגבורה. ז\"ש ואש מתלקחת. כדי להתעורר בעולם. \u0003גרדיני\u0004 פירושו מקום גבוה וחשוב, מלשון שהעלוהו לגרדום (שבת ל\"ב ע\"א) שהוא מקום מיוחד וגבוה למושב השופטים."],[10,"","פירוש. המלכות דמדת הדין הקשה, מכונה אש. ומבחינה זו, היו הט' ספירות ראשונות נקיים מכל דין. אלא אח\"כ, כשעלתה המלכות לבינה, ונמתקה במדת הרחמים אז נאחז הדין שבמלכות בבינה שבכל הספירות, וז\"ש ואש מתלקחת, כי נתלקחה למעלה בבינה. ונודע שבג' קוין של ז\"א שולטת מלכות זו שעלתה לבינה, וז\"ש \u0003תלת זמנין ביומא,\u0004 שה\"ס ג' קוין דז\"א שנקרא יום, \u0003ינקא ההוא דינא קשיא בגרדינוי גליפין מסטרא דגבורה,\u0004 דהיינו בחקיקות הספירות העליונות הגבוהות מן המלכות, בצד הגבורה. דהיינו בקו שמאל. אמנם לעת גדלות נטהרת הבינה מדינים של המלכות (כנ\"ל ב\"א דף ר\"צ ד\"ה בגין) ועכ\"ז מכח קו האמצעי אינה נטהרת לגמרי, (כנ\"ל לך י\"ג ד\"ה ונתבאר) וע\"כ אומר, \u0003דהוה אחיד ביה ולא אחיד,\u0004 שמצד אחד \u0003לא אחיד\u0004 שהרי יש שם ג\"ר, ומצד אחד \u0003אחיד,\u0004 שהרי אין שם אלא ו\"ק דג\"ר."],[11,"ומה מבסם ליה וכו':","ומה ממתיק אותו, את אש מתלקחת שבבינה, הוא, ההוא שכתוב בו, ונגה לו סביב. כי זוהר ההוא המסבב אותו מכל צדדיו שהוא חכמה, ממתיק אותו ומתקן אותו שלא יהיה דין קשה ויוכלו בני אדם לסובלו."],[12,"ומתוכה כעין החשמל:","למדנו, \u0003ומתוכה,\u0004 פירושו מפנימיותה. \u0003כעין החשמל,\u0004 מהו חשמל. א\"ר יהודה, חיות אש מדברות. שהן מבחינת זו\"ן פב\"פ, שנקראים אז קול ודבור, וע\"כ הן מדברות."],[13,"תאנא א\"ר יוסי, וכו':","למדנו, אר\"י, חשמל, פירושו, מה שהוא לב לאש. כלומר, שה\"ס ל\"ב נתיבות החכמה, שהוא החיות של הבינה, שהוא בסוד אש מתלקחת. שכתוב, מתוך האש \u0003כעין\u0004 החשמל, ולא כתוב החשמל סתם. כי כעין, רומז על אור החכמה הנקרא עין. \u0003מתוך האש,\u0004 פירושו בפנימיות האש, כי הוא בפנימיות האש. \u0003כעין החשמל,\u0004 שהוא אחר ד' מדרגות, שכתוב, רוח סערה, ענן גדול, ואש מתלקחת, ונגה לו סביב, ומתוכה כעין החשמל. \u0003מתוך האש,\u0004 היינו ההוא שכתוב בו ואש מתלקחת. שהוא בינה. ואין הפירוש מתוכה של נגה."],[13,"","פירוש. כי הם ה' מדרגות: רוח סערה הוא מלכות, ענן גדול הוא ז\"א, אש מתלקחת היא בינה, ונגה לו סביב היא חכמה שבימין.המתקנה את הבינה, ומתוכה כעין החשמל, הוא אור החכמה מבינה החוזרת לחכמה, שנקראת ל\"ב נתיבות החכמה. ומ\"ש מתוכה, אין הפירוש מתוך הנוגה, אלא מתוך אש מתלקחת. ונמצא שהחשמל היא מדרגה רביעית ונגה לו סביב הוא מדרגה חמשית. ומ\"ש, \u0003דאיהי בתר ארבע דרגין,\u0004 היינו שהחשמל מתגלה אחר ד' מדרגות האלו. כי אחר שנגה מתקנת את האש מתלקחת מתגלה החשמל."]],[[0,"","אָמַר רַבִּי אֶלְעָזָר, וְכָל הָעָם רֹאִים, רֹאִים - כְּמוֹ שֶׁאָמַרְנוּ, שֶׁרָאוּ מֵהָאוֹר שֶׁל אוֹתָם הַקּוֹלוֹת מַה שֶּׁלֹּא רָאוּ דוֹרוֹת אַחֲרוֹנִים אֲחֵרִים. אֶת הַקּוֹלֹת - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) וָאֵרֶא אֶת ה'. וָאֵרֶא ה' לֹא כָתוּב, אֶלָּא אֶת ה'. אַף כָּאן, וְכָל הָעָם רֹאִים הַקּוֹלֹת לֹא נֶאֱמַר, אֶלָּא אֶת הַקּ וֹלֹת."],[1,"","כְּמוֹ זֶה אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. שֶׁהֲרֵי הָאֶתִים שֶׁבַּתּוֹרָה נִתְּנוּ כְּדֵי לְהִסְתַּכֵּל בַּתּוֹרָה (בחכמה). כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. (משלי ג) כַּבֵּד אֶת ה' מֵהוֹנֶךְ. וְכֻלָּם לְהַכְלִיל בָּהֶם דָּבָר אַחֵר. אַף כָּאן אֶת הַקּוֹלֹת - לְרַבּוֹת אוֹתוֹ קוֹל אַחֵר לְמַטָּה, שֶׁכּוֹנֵס אוֹתָם אֵלָיו מַה שֶּׁיּוֹצֵא מֵהֶם, שֶׁבּוֹ רוֹאִים וּמִסְתַּכְּלִים בְּחָכְמָה עֶלְיוֹנָה כָּל הַגְּנָזִים הָעֶלְיוֹנִים וְכָל הַסּוֹדוֹת הַטְּמִירִים וְנִסְתָּרִים, מַה שֶּׁלֹּא הִתְגַּלָּה לְדוֹרוֹת אַחֲרוֹנִים שֶׁבָּאוּ אַחֲרֵיהֶם וְלֹא לַדּוֹרוֹת שֶׁיָּבאוּ לְעוֹלָמִים עַד הַזְּמַן שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. וְאֶת הַלַּפִּידִם - בַּתְּחִלָּה בְּרָקִים, וְעַכְשָׁו לַפִּידִים. הַכֹּל אֶחָד. אֲבָל מִשֶּׁהִתְתַּקְּנוּ בְתִקּוּנִים לְהֵרָאוֹת, נִקְרְאוּ כָּךְ."],[2,"","וְאֵת קוֹל הַשֹּׁפָר - שָׁנָה רַבִּי יִצְחָק, כָּתוּב (תהלים סב) אַחַת דִּבֶּר אֱלֹהִים שְׁתַּיִם זוּ שָׁמַעְתִּי, כְּמוֹ שֶׁנֶּאֱמַר אָנֹכִי, וְלֹא יִהְיֶה לְךְ."],[3,"","אָמַר רַבִּי יְהוּדָה, קוֹל בַּשּׁוֹפָר הָיָה צָרִיךְ לִהְיוֹת! לָמָּה הַשֹּׁפָר? אֶלָּא אוֹתוֹ קוֹל שֶׁנִּקְרָא שׁוֹפָר, שֶׁכָּתוּב (ויקראכה) וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה בַּחֹדֶשׁ הַשְּׁבִעִי בֶּעָשׂוֹר לַחֹדֶשׁ בְּיוֹם הַכִּפֻּרִים. בָּזֶה נִבְרָא (נקרא) שׁוֹפָר."],[4,"","אָמַר רַבִּי יוֹסֵי, מַה שּׁוֹפָר מוֹצִיא קוֹל, אֵשׁ רוּחַ וּמַיִם (דין חסד ורחמים), אַף כָּאן הַכֹּל נִכְלָל בָּזֶה, וּמִזֶּה יוֹצְאִים הַקּוֹלוֹת הָאֲחֵ רִים."],[5,"","אָמַר רַבִּי אֶלְעָזָר, קוֹל שֶׁיּוֹצֵא מִשּׁוֹפָר, שֶׁמַּשְׁמָע שֶׁשּׁוֹפָר אֶחָד, וְקוֹל יוֹצֵא מִמֶּנּוּ, וְשׁוֹפָר בְּקִיּוּמוֹ מָצוּי, וּמִשּׁוּם כָּךְ כָּתוּב קוֹל הַשֹּׁפָר."],[6,"","רַבִּי יְהוּדָה אָמַר כָּךְ, קוֹל הַשֹּׁפָר - הַשֹּׁפָר כָּתוּב חָסֵר, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ו) שְׁפַר קֳדָם דָּרְיָוֶשׁ. (שם ד) מִלְכִּי יִשְׁפַּר עֲלָךְ. (שם ג) שְׁפַר קָדָמַי לְהַחֲוָיָה."],[7,"","רַבִּי שִׁמְעוֹן אָמַר, קוֹל הַשֹּׁפָר - מָקוֹם שֶׁקּוֹל יוֹצֵא מִמֶּנּוּ נִקְרָא שׁוֹפָר. עוֹד אָמַר רַבִּי שִׁמְעוֹן, בֹּא וּרְאֵה, קוֹל הַשֹּׁפָר - מָקוֹם שֶׁל קוֹל, הַיְנוּ שֶׁכָּתוּב (דברים ח) כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. מַה זֶּה מוֹצָא פִּי ה'? זֶה קוֹל (ס\"ר שיוצא משופר, וזה קול) הַשּׁוֹפָר, הוּא גָּדוֹל מִכָּל שְׁאָר הַקּוֹלוֹת הַתַּחְתּוֹנִים וְחָזָק מִכֻּלָּם, שֶׁכָּתוּב וְקֹל שֹׁפָר חָזָק מְאֹד, וְעַל כָּל שְׁאָר הַקּוֹלוֹת לֹא נֶאֱמַר חָזָק מְאֹד. (אמר רבי שמעון) בְּקוֹל הַשּׁוֹפָר הַזֶּה הַכֹּל תָּלוּי, וְזֶהוּ שֶׁנִּקְרָא קוֹל גָּדוֹל, שֶׁכָּתוּב קוֹל גָּדוֹל וְלֹא יָסָף. וְנִקְרָא קוֹל דְּמָמָה דַקָּה, אוֹר הַמְּנוֹרוֹת, שֶׁהוּא זַךְ וְדַקִּיק וּמְזֻכָּךְ וּמֵאִיר לַכֹּל."],[8,"","דְּמָמָה, מַה זֶּה דְּמָמָה? אָמַר רַבִּי שִׁמְעוֹן, שֶׁצָּרִיךְ אָדָם לִשְׁתֹּק מִמֶּנּוּ וְלַחְסֹם אֶת פִּיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אָמַרְתִּי אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי אֶשְׁמְרָה לְפִי מַחְסוֹם. דְּמָמָה הִיא שְׁתִיקָה שֶׁלֹּא נִשְׁמַעַת הַחוּצָה. וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק, שֶׁרָאוּ מַה שֶּׁרָאוּ. וַיָּנֻעוּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) וַיָּנֻעוּ אַמּוֹת הַסִּפִּים מִקּוֹל הַקּוֹרֵא."],[9,"","שָׁנִינוּ, מַה כָּתוּב בִּיחֶזְקֵאל כְּשֶׁרָאָה גְבוּרוֹת הַנְהָגוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה וְגוֹ'. לָמָּה רוּחַ סְעָרָה? אָמַר רַבִּי יוֹסֵי, כְּדֵי לִשְׁבֹּר אַרְבַּע מַלְכֻיּוֹת. אָמַר רַבִּי יְהוּדָה, שָׁנִינוּ, רוּחַ גְּדוֹלָה שֶׁמִּתְעוֹרֶרֶת בְּהַנְהָגוֹת הַגְּבוּרָה שֶׁלְּמַעְלָה בָּאָה מִן הַצָּפוֹן. לֹא כָתוּב מִצָּפוֹן אֶלָּא מִן הַצָּפוֹן, מִן אוֹתוֹ הַצָּפוֹן, אוֹתוֹ שֶׁנּוֹדָע לְמַעְלָה, אוֹתוֹ שֶׁטָּמִיר וְגָנוּז לְמַעְלָה."],[10,"","עָנָן גָּדוֹל וְאֵשׁ מִתְלַקַּחַת, שֶׁהָיָה אָחוּז בּוֹ (ולא אחוז, אחוז בצדדיו) וְלֹא הָיָה אָחוּז בְּצִדּוֹ לְעוֹרֵר הַדִּין, שֶׁשָּׁנִינוּ, שָׁלֹשׁ פְּעָמִים בְּיוֹם יוֹנֵק אוֹתוֹ דִין הַקָּשֶׁה בַּמְמֻנִּים חֲקוּקִים מִצַּד הַגְּבוּרָה. זֶהוּ שֶׁכָּתוּב וְאֵשׁ מִתְלַקַּחַת, כְּדֵי לְעוֹרֵר בָּעוֹלָם."],[11,"","וּמַה מְבַסֵּם אוֹתוֹ? אוֹתוֹ שֶׁכָּתוּב בּוֹ וְנֹגַהּ לוֹ סָבִיב. שֶׁאוֹתוֹ זֹהַר שֶׁמַּקִּיף אוֹתוֹ מִכָּל צְדָדָיו מְבַסֵּם אוֹתוֹ וּמְתַקֵּן אוֹתוֹ כְּדֵי שֶׁלֹּא יִהְיֶה דִין קָשֶׁה וְיוּכְלוּ בְנֵי אָדָם לִסְבֹּל אוֹתוֹ."],[12,"","וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל. שָׁנִינוּ, וּמִתּוֹכָהּ - וּמִתּוֹכָהּ. כְּעֵין הַחַשְׁמַל - מַה זֶּה חַשְׁמַל? אָמַר רַבִּי יְהוּדָה, חַיּוֹת אֵשׁ מְדַבְּרוֹת."],[13,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, חַשְׁמַל - מַה שֶּׁהָיָה לֵב לָאֵשׁ, שֶׁכָּתוּב מִתּוֹךְ הָאֵשׁ כְּעֵין הַחַשְׁמַל. וְלֹא הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, מִתּוֹךְ אֵשׁ שֶׁהִיא לְתוֹךְ אֵשׁ. כְּעֵין הַחַשְׁמַל, שֶׁהִיא אַחַר אַרְבַּע דְּרָגוֹת, שֶׁכָּתוּב רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב. וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, אוֹתוֹ שֶׁכָּתוּב בּוֹ וְאֵשׁ מִתְלַקַּחַת."]]],[["תַּנְיָא רַבִּי יוֹסֵי בַּר רַבִּי יְהוּדָה אָמַר, חָמוּ יִשְׂרָאֵל הָכָא, מַה דְּלָא חָמָא יְחֶזְקֵאל בֶּן בּוּזִי, וְכֻלְּהוּ אִתְדְּבָקוּ בֶּחָכְמְתָא עִלָּאָה יַקִּירָא. חֲמִשָּׁה דַּרְגִּין דְּקַלִין, חָמוּ יִשְׂרָאֵל בְּטוּרָא דְּסִינַי. וּבַחֲמִשָּׁה דַּרְגִּין אִלֵּין אִתְיְיהִיבַת אוֹרַיְיתָא. דַּרְגָּא חֲמִישָׁאָה הוּא, דִּכְתִּיב קוֹל הַשֹׁפָר. יְחֶזְקֵאל לָקֳבְלֵיהוֹן חָמָא חֲמִשָּׁה דַּרְגִּין דְּאִינּוּן לְבַר מֵאִלֵּין, דְּאִינּוּן רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב, וְעֵין הַחַשְׁמַל.","אָמַר רַבִּי אֶלְעָזָר, בְּיִשְׂרָאֵל כְּתִיב, (דברים ה׳:ד׳) פָּנִים בְּפָנִים דִּבֶּר יְיָ' וְגוֹ'. בִּיחֶזְקֵאל כְּתִיב, כְּעֵין, וּדְמוּת, כְּמַאן דְּחָמֵי בָּתַר כּוֹתָלִין סַגִּיאִין, כְּמַאן דְּחָמֵי בַּר נָשׁ בָּתַר כּוֹתָלָא. אָמַר רַבִּי יְהוּדָה, מַה דְּחָמוּ יִשְׂרָאֵל, לָא חָמָא נְבִיאָה אַחֲרָא, כָּל שֶׁכֵּן מַה דְּחָמָא מֹשֶׁה, דְּלָא חָמָא נְבִיאָה אַחֲרָא. (ס\"א כל שכן בר נש אחרא) זַכָּאָה חוּלָקֵיהּ, דִּכְתִּיב בֵּיהּ, (שמות לה) וַיְהִי שָׁם עִם יְיָ' וְלֹא בְּחֵיזוּ אַחֲרָא, כְּמָה דִּכְתִּיב, (במדבר י״ב:ח׳) וּמַרְאֶה וְלא בְחִידוֹת.","אָמַר רַבִּי יוֹסֵי, תָּא חֲזֵי, כְּתִיב, (יחזקאל א) (ב' א') הָיֹה הָיָה דְּבַר יְיָ', נְבוּאָה לְשַׁעֲתָא הָיְתָה. ר' יְהוּדָה אוֹמֵר, לְקִיּוּמָא הוּא דְּאָתָא, דְּאִצְטְרִיךְ לְמֶהֱוֵי בְּגִינֵיהוֹן דְּיִשְׂרָאֵל, לְאִשְׁתְּמוֹדְעָא דְּהָא לָא שָׁבִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וּבְכָל אֲתָר דְּמִתְפָּזְרִין יִשְׂרָאֵל בְּגָלוּתָא, עִמְהוֹן הוּא שַׁרְיָא.","אָמַר רַבִּי אֶלְעָזָר, הָיֹה הָיָה: דְּחָמָא וְלָא חָמָא, דְּקָאִים בְּאִינּוּן מִלִּין, וְלָא קָאִים. הֲדָא הוּא דִכְתִיב וָאֵרֶא כְּעֵין חַשְׁמַל, וְלָא חַשְׁמַל אֲבָל יִשְׂרָאֵל, מַה כְּתִיב בְּהוּ, וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, כָּל חַד וְחַד חָמָא, כַּדְקָא חֲזֵי לֵיהּ.","דְּתַנְיָא, כָּל חַד וְחַד הֲווֹ קַיְימִין שׁוּרִין שׁוּרִין, תְּחוּמִין תְּחוּמִין, וְכַדְקָא אִתְחָזֵי לְהוּ, חָמוּ כָּל חַד וְחַד. אָמַר רַבִּי שִׁמְעוֹן, רֵישֵׁי דְּעַמָּא בִּלְחוֹדַיְיהוּ, רֵישֵׁי דִּשְׁבָטִין בִּלְחוֹדַיְיהוּ. נוּקְבֵי בִּלְחוֹדַיְיהוּ. ה' דַּרְגִּין לִימִינָא, וְה' דַּרְגִּין לִשְׂמָאלָא. הֲדָא הוּא דִכְתִיב, (דברים כ״ט:ט׳) אַתֶּם נִצָּבִים הַיּוֹם כֻּלְכֶם לִפְנֵי יְיָ' אֱלהֵיכֶם רָאשֵׁיכֶם שִׁבְטֵיכֶם זִקְנֵיכֶם וְשׁוֹטְרֵיכֶם כֹּל אִישׁ וְגוֹ', הָא ה' דַּרְגִּין לִימִינָא. וְה' דַּרְגִּין לִשְׂמָאלָא מַאן אִינּוּן. הַיְינוּ דִּכְתִּיב, (דבהם כט) טַפְּכֶם, נְשֵׁיכֶם, וְגֵרְךָ אֲשֶׁר בְּקֶרֶב מַחֲנְיךָ, מֵחֹטֵב עֵצֶיךָ, עַד שֹׁאֵב מֵימֶיךָ. הָא ה' דַּרְגִּין לִשְׂמָאלָא.","כֻּלְּהוּ דַּרְגִּין אִתְתָּקָנוּ כְּגַוְונָא דִּלְעֵילָּא. לָקֳבְלֵיהוֹן יַרְתּוּ יִשְׂרָאֵל אַחֲסָנַת עָלְמִין, עֶשֶׂר אֲמִירָן, דִּבְהוּ תַּלְיָין כָּל פִּקּוּדִין, וְכָל זַכְוָון, וְכָל יְרוּתַת אַחֲסָנָא, דְּאִינּוּן חוּלָקָא טָבָא דְּיִשְׂרָאֵל.","תָּאנָא, בְּהַהִיא שַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי בְּטוּרָא דְּסִינַי, הֲווֹ חָמָאן כָּל יִשְׂרָאֵל, כְּמַאן דְּחָמֵי נְהוֹרָא בַּעֲשִׁישָׁתָא, וּמֵהַהוּא נְהוֹרָא הֲוָה חָמֵי כָּל חַד וְחַד, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה.","מַאי טַעְמָא. מִשּׁוּם דְּאִינּוּן קַלִין עִלָּאִין, אִתְגְּלִיאוּ (נ\"א אתגליפו) בְּחַד, כְּמָה דַּאֲמֵינָא, דִּכְתִּיב, וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת. אֲבָל בִּיחֶזְקֵאל, שְׁכִינְתָּא אִתְגְּלֵי בִּרְתִּיכוֹי, וְלָא יַתִּיר, וַהֲוָה חָמֵי, כְּמַאן דְּחָמֵי בָּתַר כּוֹתָלִין סַגִּיאִין.","אָמַר רַבִּי יְהוּדָה, זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דִּכְתִּיב בֵּיהּ, וַיֵּרֶד יְיָ' עַל הַר סִינַי וַיִּקְרָא יְיָ' לְמֹשֶׁה, זַכָּאָה דָּרָא, דִּכְתִּיב בֵּיהּ, יֵרֵד יְיָ' לְעֵינֵי כָל הָעָם עַל הַר סִינַי.","תָּא חֲזֵי, כְּתִיב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, דְּהָא מִימִינָא אִתְגְּלֵי מַה דְּאִתְגְלֵי. מַה בֵּין הַאי לְהַאי. אָמַר ר' יוֹסֵי, הָכָא בְּסִינַי, רֵישָׁא וְגוּפָא דְּמַלְכָּא, דִּכְתִּיב, (שמואל ב כ״ב:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד, וּבַאֲתַר דְּאִית רֵישָׁא, אִית גּוּפָא, אֲבָל בִּיחֶזְקֵאל כְּתִיב (יחזקאל א׳:ג׳) וַתְּהִי עָלָיו שָׁם יַד יְיָ', דְּאִתְגְלֵי יְדָא, וְלָא גּוּפָא. וְתָנֵינָן, אֲפִילּוּ בִּידָא, יַד יְיָ' עִלָּאָה, יַד יְיָ' תַּתָּאָה.","תָּא חֲזֵי, כְּתִיב נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאֹת אֱלֹהִים. מַרְאֹת כְּתִיב חָסֵר, לְאִתְחֲזָאָה דִּבְגִין שְׁכִינְתָּא קָאָמַר, דְּהָא וָאֶרְאֶה מַרְאֹת חָסֵר, מַרְאֶה חַד. אָמַר ר' יֵיסָא, וְכִי שְׁכִינְתָּא לָאו כֹּלָּא. אָמַר רַבִּי יוֹסֵי, לָא דָּמֵי רֵישָׁא דְּמַלְכָּא, לְרַגְלוֹי דְּמַלְכָּא, אַף עַל גַּב דְּכֹלָּא הֲוֵי בְּגוּפָא דְּמַלְכָּא.","תָּא חֲזֵי, בִּישַׁעְיָהוּ כְּתִיב, (ישעיה ו) וָאֵרֶא אֶת יְיָ', בִּיחֶזְקֵאל כְּתִיב, וָאֶרְאֶה מַרְאֹת אֱלהִים, הָכָא אֶת, הָתָם מַרְאֹת. מַה דְּחָמָא דָּא, חָמָא דָּא. זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּלָא הֲוָה נְבִיאָה מְהֵימָנָא שְׁלֵימָא כְּוָותֵיהּ."],[[0,"תניא רבי יוסי בר ר' יהודה וכו':","למדנו ר\"י בר\"י אמר, ראו כאן ישראל, מה שלא ראה יחזקאל בן בוזי. וכולם התדבקו בחכמה העליונה היקרה. חמש מדרגות של קולות ראו ישראל בהר סיני, ובחמש מדרגות אלו ניתנה התורה. מדרגה חמשית הוא, שכתוב, קול השופר. כנגדם ראה יחזקאל חמש מדרגות שהם מחוץ, לאלו ה' קולות, שהם, רוח סערה, ענן גדול, ואש מתלקחת, ונגה לו סביב, ועין החשמל."],[1,"אמר ר' אלעזר וכו':","אר\"א, בישראל כתוב, פנים בפנים דבר ה' וגו'. ביחזקאל כתוב, כעין, ודמות, כמי שרואה אחר כתלים רבים. כמו שאדם רואה מאחורי הכותל. אמר ר' יהודה מה שראו ישראל לא ראה נביא אחר. כל שכן מה שראה משה לא ראה נביא אחר. אשרי חלקו, שכתוב בו ויהי שם עם הויה, שה\"ס אספקלריאה המאירה, ולא במראה אחרת, שאינה מאירה. כמ\"ש, ומראה ולא בחידות, אבל אספקלריאה שאינה מאירה, היא מראה, בחידות."],[2,"אמר ר' יוסי וכו':","אר\"י, בוא וראה, כתוב, היה היה דבר ה'. נבואה לשעה היתה, ע\"כ נאמר היה היה. ר' יהודה אומר, לקיום הוא בא, שהיה צריך להיות בשביל ישראל, לדעת שהקב\"ה לא עזב אותם, ובכל מקום שנתפזרו ישראל בגלות הוא שורה עמהם."],[3,"אמר ר' אלעזר וכו':","אר\"א, היה היה, פירושו, שראה ולא ראה, שעמד בדברים אלו, ולא עמד. ז\"ש וארא כעין חשמל ולא כתוב וארא חשמל. אבל ישראל מה כתוב בהם, וכל העם רואים את הקולות, דהיינו, שכל אחד ואחד ראה כראוי לו."],[4,"דתניא כל חד וכו':","שלמדנו, כל אחד ואחד, היו עומדים שורות שורות, גבולים גבולים, וכראוי להם ראה כל אחד ואחד. אמר ר' שמעון, ראשי העם היו עומדים בלבדם, ראשי השבטים בלבדם, נקבות בלבדן. ה' מדרגות עמדו לימין, וה' מדרגות לשמאל. ז\"ש אתם נצבים היום כלכם לפני ה' אלקיכם, ראשיכם, שבטיכם, זקניכם, ושוטריכם, כל איש וגו'. הרי חמש מדרגות לימין. וחמש מדרגות לשמאל מי הן. היינו שכתוב, טפכם, נשיכם, וגרך אשר בקרב מחניך, מחטב עציך, עד שאב מימיך, הרי המש מדרגות לשמאל."],[5,"כלהו דרגין אתתקנו וכו':","כל המדרגות האלו נתקנו כעין של מעלה. כנגדם ירשו ישראל ירושת עולם, עשרת הדברות, שבהם תלוים כל המצות וכל הזכיות, וכל ירושת נחלתם, שהם חלק הטוב של ישראל."],[6,"תאנא בההיא שעתא וכו':","למדנו, בשעה ההיא שנגלה הקב\"ה בהר סיני, היו רואים כל ישראל, כמי שרואה אור בעששית ומאור ההוא היה רואה כל אחד ואחד, מה שלא ראה יחזקאל הנביא. \u0003עששית.\u0004 פירושו מנורה שכתליה זכוכית ונר מאיר מתוכה."],[7,"מ\"ט, משום דאינון וכו':","שואל, מה הטעם. ומשיב, משום שאלו קולות העליונים נגלו כאחד כמו שאמרנו, שכתוב, וכל העם רואים את הקולות. אבל ביחזקאל, השכינה נגלה במרכבותיה, ולא יותר, והיה רואה, כמי שרואה אחרי כתלים רבים."],[8,"אמר רבי יהודה וכו':","אר\"י, אשרי חלקו של משה, שכתוב בו, וירד ה' על הר סיני ויקרא ה' למשה. אשרי הדור, שכתוב בו, וירד ה' לעיני כל העם על הר סיני."],[9,"ת\"ח וכו':","בוא וראה כתוב, מימינו אש דת למו, כי מימין נגלה מה שנגלה. שואל, מה בין זה לזה של יחזקאל. אמר ר' יוסי, כאן בסיני היה ראש וגוף של המלך, שכתוב, ויט שמים וירד. כי לפני זה כתוב, עלה עשן \u0003באפו\u0004 ואש \u0003מפיו\u0004 תאכל וגו' וירד, הרי שיש כאן ראש, שנאמר בו אף ופה. ובמקום שיש ראש יש גוף. אבל ביחזקאל כתוב, ותהי עליו שם \u0003יד\u0004 ה', שנגלה יד ולא גוף. ולמדנו, אפילו ביד, יש יד ה' עליונה דהיינו יד של ז\"א, ויש יד ה' תחתונה דהיינו המלכות שנקראת יד. ולו נגלה יד התחתונה."],[10,"ת\"ח כתיב נפתחו וכו':","בוא וראה, כתוב נפתחו השמים ואראה מראת אלקים. \u0003מראת,\u0004 כתוב חסר \u0003ו'\u0004 להראות, שעל השכינה אומר, כי ואראה מראת חסר \u0003ו'\u0004, יורה על מראה אחת, שהיא השכינה, אמר ר' ייסא, וכי השכינה אינה הכל. אמר ר' יוסי אינה דומה הראש של המלך לרגליו של המלך, שהיא השכינה המלבשתו מחזה ולמטה, שנקרא רגליו. אע\"פ שהכל הוא בגופו של המלך."],[11,"ת\"ח בישעיהו כתיב וכו':","בוא וראה, בישעיהו כתוב, וארא \u0003את\u0004 ה'. שהיא השכינה הנקראת \u0003את.\u0004 וביחזקאל כתוב, ואראה \u0003מראת\u0004 אלקים, כאן \u0003את\u0004 שהיא השכינה, ושם \u0003מראת,\u0004 שהיא השכינה, כי מה שראה זה ראה זה. דהיינו רק השכינה. אשרי חלקו של משה, שלא היה נביא שלם כמותו, שהוא ראה באספקלריאה המאירה, שהוא ז\"א."]],[[0,"","שָׁנִינוּ, רַבִּי יוֹסֵי בַּר רַבִּי יְהוּדָה אָמַר, רָאוּ יִשְׂרָאֵל כָּאן מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל בֶּן בּוּזִי, וְכֻלָּם נִדְבְּקוּ בְחָכְמָה עֶלְיוֹנָה נִכְבָּדָה. חָמֵשׁ דְּרָגוֹת שֶׁל קוֹלוֹת רָאוּ יִשְׂרָאֵל בְּהַר סִינַי, וּבַחֲמֵשׁ הַדְּרָגוֹת הַלָּלוּ נִתְּנָה תוֹרָה. דַּרְגָּה חֲמִישִׁית הוּא, שֶׁכָּתוּב קוֹל הַשֹּׁפָר. כְּנֶגְדָּם רָאָה יְחֶזְקֵאל חָמֵשׁ דְּרָגוֹת שֶׁהֵן חוּץ לְאֵלֶּה, שֶׁהֵם: רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב, כְּעֵין הַחַשְׁמַל."],[1,"","אָמַר רַבִּי אֶלְעָזָר, בְּיִשְׂרָאֵל כָּתוּב (דברים ה) פָּנִים בְּפָנִים דִּבֶּר ה' וְגוֹ'. בִּיחֶזְקֵאל כָּתוּב כְּעֵין, וּדְמוּת, כְּמִי שֶׁרוֹאֶה אַחַר כְּתָלִים רַבִּים, כְּמִי שֶׁרוֹאֶה אָדָם אַחַר כֹּתֶל. אָמַר רַבִּי יְהוּדָה, מַה שֶּׁרָאוּ יִשְׂרָאֵל - לֹא רָאָה נָבִיא אַחֵר. כָּל שֶׁכֵּן מַה שֶּׁרָאָה מֹשֶׁה שֶׁלֹּא רָאָה נָבִיא אַחֵר (כל שכן אדם אחר). אַשְׁרֵי חֶלְקוֹ, שֶׁכָּתוּב בּוֹ (שמות לד) וַיְהִי שָׁם עִם ה', וְלֹא בְמַרְאֶה אַחֵר, כַּכָּתוּב (במדבר לד) וּמַרְאֶה וְלֹא בְחִידוֹת."],[2,"","אָמַר רַבִּי יוֹסֵי, בֹּא וּרְאֵה, כָּתוּב הָיֹה הָיָה דְבַר ה'. נְבוּאָה לִשְׁעָתָהּ הָיְתָה. רַבִּי יְהוּדָה אוֹמֵר, לְקִיּוּם הוּא בָּא, שֶׁהִצְטָרֵךְ לִהְיוֹת בִּשְׁבִיל יִשְׂרָאֵל, לְהוֹדִיעַ שֶׁהֲרֵי לֹא עָזַב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל מִתְפַּזְּרִים בַּגָּלוּת, הוּא שָׁרוּי עִמָּהֶם."],[3,"","אָמַר רַבִּי אֶלְעָזָר, הָיֹה הָיָה - שֶׁרָאָה וְלֹא רָאָה, שֶׁעוֹמֵד בְּאוֹתָם דְּבָרִים וְלֹא עוֹמֵד. זֶהוּ שֶׁכָּתוּב וָאֵרֶא כְּעֵין הַחַשְׁמַל, וְלֹא חַשְׁמַל. אֲבָל יִשְׂרָאֵל מַה כָּתוּב בָּהֶם? וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. כָּל אֶחָד וְאֶחָד רָאָה כָּרָאוּי לוֹ."],[4,"","שֶׁשָּׁנִינוּ, כָּל אֶחָד וְאֶחָד הָיוּ עוֹמְדִים שׁוּרוֹת שׁוּרוֹת, תְּחוּמִים תְּחוּמִים, וּכְמוֹ שֶׁרָאוּי לָהֶם רָאוּ כָּל אֶחָד וְאֶחָד. אָמַר רַבִּי שִׁמְעוֹן, רָאשֵׁי הָעָם לְבַדָּם, רָאשֵׁי הַשְּׁבָטִים לְבַדָּם. הַנְּקֵבוֹת לְבַדָּן. חָמֵשׁ דְּרָגוֹת לְיָמִין, וְחָמֵשׁ דְּרָגוֹת לִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (דבריםכט) אַתֶּם נִצָּבִים הַיּוֹם כֻּלְּכֶם לִפְנֵי ה' אֱלֹהֵיכֶם רָאשֵׁיכֶם שִׁבְטֵיכֶם זִקְנֵיכֶם וְשֹׁטְרֵיכֶם כֹּל אִישׁ וְגוֹ'. הֲרֵי חָמֵשׁ דְּרָגוֹת לְיָמִין. וְחָמֵשׁ דְּרָגוֹת לִשְׂמֹאל מַה הֵן? הַיְנוּ שֶׁכָּתוּב טַפְּכֶם, נְשֵׁיכֶם, וְגֵרְךְ אֲשֶׁר בְּקֶרֶב מַחֲנֶיךְ, מֵחֹטֵב עֵצֶיךְ, עַד שֹׁאֵב מֵימֶיךְ. הֲרֵי חָמֵשׁ דְּרָגוֹת לִשְׂמֹאל."],[5,"","כָּל הַדְּרָגוֹת הִתְתַּקְּנוּ כְּמוֹ שֶׁלְּמַעְלָה. כְּנֶגְדָּם יָרְשׁוּ יִשְׂרָאֵל יְרֻשַּׁת עוֹלָמִים, עֶשֶׂר אֲמִירוֹת, שֶׁבָּהֶן תְּלוּיוֹת כָּל הַמִּצְווֹת וְכָל הַזְּכֻיּוֹת וְכָל יְרֻשַּׁת נַחֲלָה, שֶׁהֵם הַחֵלֶק הַטּוֹב שֶׁל יִשְׂרָאֵל."],[6,"","שָׁנִינוּ, בְּאוֹתָהּ הַשָּׁעָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בְּהַר סִינַי, הָיוּ רוֹאִים כָּל יִשְׂרָאֵל כְּמִי שֶׁרוֹאֶה אוֹר בַּעֲשָׁשִׁית, וּמֵאוֹתוֹ אוֹר הָיָה רוֹאֶה כָּל אֶחָד וְאֶחָד מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא."],[7,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָם קוֹלוֹת עֶלְיוֹנִים הִתְגַּלּוּ (נחקקו) בְאֶחָד, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. אֲבָל בִּיחֶזְקֵאל, הַשְּׁכִינָה נִגְלְתָה בְּמַרְכְּבוֹתֶיהָ וְלֹא יוֹתֵר, וְהָיָה רוֹאֶה כְּמִי שֶׁרוֹאֶה אַחַר כְּתָלִים רַבִּים."],[8,"","אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁכָּתוּב בּוֹ וַיֵּרֶד ה' עַל הַר סִינַי וַיִּקְרָא ה' לְמֹשֶׁה. אַשְׁרֵי דּוֹרוֹ, שֶׁכָּתוּב בּוֹ יֵרֵד ה' לְעֵינֵי כָל הָעָם עַל הַר סִינָי."],[9,"","בֹּא וּרְאֵה, כָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ, שֶׁהֲרֵי מִיָּמִין הִתְגַּלָּה מַה שֶּׁהִתְגַּלָּה. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי יוֹסֵי, כָּאן בְּסִינַי - רֹאשׁ וְגוּף הַמֶּלֶךְ, שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד. וּבְמָקוֹם שֶׁיֵּשׁ רֹאשׁ יֵשׁ גּוּף. אֲבָל בִּיחֶזְקֵאל כָּתוּב וַתְּהִי עָלָיו שָׁם יַד ה', שֶׁהִתְגַּלְּתָה הַיָּד וְלֹא הַגּוּף. וְשָׁנִינוּ, אֲפִלּוּ בַּיָּד, יַד ה' עֶלְיוֹנָה, יַד ה' תַּחְתּוֹנָה."],[10,"","בֹּא וּרְאֵה, כָּתוּב נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאֹת אֱלֹהִים. מַרְאֹת כָּתוּב חָסֵר, לְהַרְאוֹת שֶׁבִּשְׁבִיל הַשְּׁכִינָה זֶה נֶאֱמַר, שֶׁהֲרֵי וָאֶרְאֶה מַרְאֹת חָסֵר, מַרְאֶה אֶחָד. אָמַר רַבִּי יֵיסָא, וְכִי שְׁכִינָה לֹא הַכֹּל? אָמַר רַבִּי יוֹסֵי, לֹא דוֹמֶה רֹאשׁ הַמֶּלֶךְ לְרַגְלֵי הַמֶּלֶךְ, אַף עַל גַּב שֶׁהַכֹּל נִמְצָא בְּגוּף הַמֶּלֶךְ."],[11,"","בֹּא וּרְאֵה, בִּישַׁעְיָהוּ כָּתוּב (ישעיה ו) וָאֵרֶא אֶת ה'. בִּיחֶזְקֵאל כָּתוּב וָאֶרְאֶה מַרְאֹת אֱלֹהִים. כָּאן אֶת, שָׁם מַרְאֹת. מַה שֶּׁרָאָה זֶה - רָאָה זֶה. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁלֹּא הָיָה נָבִיא נֶאֱמָן שָׁלֵם כְּמוֹתוֹ."]]],[["וָאֵרֶא אֶת יְיָ', אֶת דַּיְיקָא. וָאֶרְאֶה מַרְאֹת אֱלהִים, מַרְאֹת דַּיְיקָא. וּבְדַרְגָּא חַד הָווֹ. אִי הָכִי, אֲמַאי לָא פָּרִישׁ יְשַׁעְיָה כּוּלֵי הַאי. אָמַר רַבִּי יוֹסֵי, דָּא כָּלִיל, דָּא פָּרִישׁ. מַאי טַעֲמָא פָּרִישׁ כּוּלֵי הַאי יְחֶזְקֵאל. אֶלָּא, כֹּלָּא אִצְטְרִיךְ בְּגִינֵיהוֹן דְּיִשְׂרָאֵל, דְּיִנְדְּעוּן חֲבִיבוּתָא דְּחָבִיב לְהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְּשְׁכִינְתֵּיהּ וּרְתִיכוֹי אַתְיָין לְדַיָּירָא בֵּינַיְיהוּ בְּגָלוּתָא.","אָמַר רִבִּי חִיָּיא, בְּאֶרֶץ כַּשְׂדִּים, וְהָא כְּתִיב (ישעיהו כ״ג:י״ג) הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה, אֲמַאי אִתְגְּלֵי שְׁכִינְתָּא תַּמָּן. אִי תֵּימָא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל, הֲוָה טָב דְּתִשְׁרֵי שְׁכִינְתָּא בְּגַוַּויְיהוּ, וְלָא יִתְגַּלְיָיא. אֶלָּא, הָכִי תָּאנָא, אִי לָאו דְּאִתְגַּלְיָיא לָא הֲווֹ יַדְעִין.","וְהָא דְּאִתְגַּלְיָיא, מַה כְּתִיב, עַל נְהַר כְּבָר, עַל מַיָּא, בְּאֲתָר דְּלָא יִסְתְּאַב, וְלָא (ויחי רכ\"ב ע\"ב) שַׁרְיָא מְסָאֳבוּתָא. וְהַהוּא נַהֲרָא, הֲוָה חַד מֵאַרְבַּע נָהֲרִין, דְּנָפְקִין מִגִּנְתָּא דְּעֵדֶן, דִּכְתִּיב עַל נְהַר כְּבָר. מַאי כְּבָר. דִּכְבָר הֲוָה. מֵאֲתָר דִּשְׁכִינְתָּא שַׁרְיָא עֲלוֹי. וּכְתִיב וַתְּהִי עָלָיו שָׁם יַד יְיָ', שָׁם, וְלָא בְּאֲתָר אַחֲרָא.","אָמַר רַבִּי חִיָּיא, כְּתִיב וּמִתּוֹכָהּ דְּמוּת אַרְבַּע חַיּוֹת וְזֶה מַרְאֵיהֶן דְּמוּת אָדָם לָהֵנָּה. תָּאנָא בְּרָזָא עִלָּאָה, אַרְבַּע חִיוָון אִית, דְּאִינְהוּ לְגוֹ בְּגוֹ הֵיכָלָא קַדִּישָׁא, וְאִינּוּן קַדְמָאֵי, עַתִּיקִין דְּעַתִּיקָא קַדִּישָׁא, כְּלָלָא דִּשְׁמָא עִלָּאָה. וִיחֶזְקֵאל חָמָא, דְּמוּת דִּרְתִּיכִין עִלָּאִין, דְּהָא הוּא חָמָא, מֵאֲתָר דְּלָא הֲוָה נָהִיר כָּל כַּךְ. תָּאנָא, כְּגַוְונָא דִּלְעֵילָּא, אִית לְתַתָּא מִינַיְיהוּ, וְכֵן בְּכֻלְּהוּ עָלְמִין, כּוּלְּהוּ אֲחִידָן דָּא בְּדָא, וְדָא בְּדָא.","וְאִי תֵּימָא לְעֵילָּא יַתִּיר דְּחָמָא. תָּנִינָן, מֹשֶׁה חָמָא בְּאַסְפָּקָלַרְיָא דְּנָהֲרָא, וְכֻלְּהוּ נְבִיאֵי לָא חָמוּ אֶלָּא מִגּוֹ אַסְפָּקָלַרְיָא דְּלָא נָהֲרָא, דִּכְתִּיב וָאֶרְאֶה מַרְאֹת אֱלהִים. וּכְתִיב (במדבר י״ב:ו׳) אִם יִהְיֶה נְבִיאֲכֶם יְיָ' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע וְגוֹ' לא כֵן עַבְדִּי מֹשֶׁה וְגו', וּכְתִיב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.","אָמַר רִבִּי יוֹסֵי, תָּא חֲזֵי, דִּנְבִיאִין כֻּלְּהוּ לְגַבֵּיהּ, כְּנוּקְבָא לְגַבֵּי דְּכוּרָא, דִּכְתִּיב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה. וְלִשְׁאַר נְבִיאִים (כתיב, במראות ולמשה יי) בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. בַּמַּרְאָה וְלָא מַרְאֹת. כָּל שֶׁכֵּן יְחֶזְקֵאל, דְּאֲפִילּוּ מַרְאֶה לָא כְּתִיב בֵּיהּ, אֶלָּא מַרְאֹת חָסֵר, וְכָּל שֶׁכֵּן דִּכְתִּיב בְּמֹשֶׁה, וְלֹא בְחִידוֹת, אֶלָּא כָּל מִלָּה עַל בּוּרְיֵיהּ. זַכָּאָה אִיהוּ דָּרָא, דִּנְבִיאָה דָּא שָׁרֵי בְּגַוַּויְיהוּ.","אָמַר רִבִּי יוֹסֵי בְּרַבִּי יְהוּדָה, אַפִּין בְּאַפִּין חָמוּ יִשְׂרָאֵל זִיו יְקָרָא דְּמַלְכֵּיהוֹן, (נ\"א דמאריהון) וְלָא הֲוָה בְּהוֹן סוּמִין, וְחִגְּרִין, וּקְטִיעִין, וְחֵרְשִׁין. סוּמִין, מַשְׁמַע דִּכְתִּיב וְכָל הָעָם רוֹאִים. חִגְרִין, דִּכְתִּיב וַיִתְיַצְּבוּ בְּתַחְתִּית הָהָר. קְטִיעִין וְחֵרְשִׁין, נַעֲשֶׂה וְנִשְׁמָע. וּלְזִמְנָא דְּאָתֵי כְּתִיב (ישעיהו ל״ה:ו׳) אָז יְדַלֵּג כְּאַיָּל פִּסֵּחַ וְתָרוֹן לְשׁוֹן אִלֵּם.","(שמות כ׳:א׳) וַיְדַבֵּר אֱלהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. רַבִּי יְהוּדָה פָּתַח, (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת יְיָ' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. בְּכַמָּה אָרְחִין, אוֹרַיְיתָא אַסְהִידַת בְּבַר נָשׁ, דְּלָא יְחוּב קַמֵי מָארֵיהּ. בְּכַמָּה אָרְחִין, יָהִיב לֵיהּ עֵיטָא, דְּלָא יִסְטֵי מֵאָרְחוֹי לִימִינָא וְלִשְׂמָאלָא. בְּכַמָּה אָרְחִין יָהִיב לֵיהּ עֵיטָא, הֵיךְ יֵתוּב קָמֵי מָארֵיהּ, וְיִמְחוֹל לֵיהּ.","דִּתְנָן, שִׁית מְאָה וּתְלַת עָשָׂר זִינֵי עֵיטָא, יָהִיב אוֹרַיְיתָא לְבַר נָשׁ, לְמֶהוֵי שְׁלִים בְּמָארֵיהּ, בְּגִין דְּמָארֵיהּ בָּעָא לְאוֹטָבָא לֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. וְיַתִּיר בְּעָלְמָא דְּאָתֵי, דְּהָא תָּנֵינָן, כָּל מַה דְּקוּדְשָׁא בְּרִיךְ הוּא אַשְׁלִים לֵיהּ לְבַר נָשׁ, מֵאִינּוּן טָבָאן דְּזָכֵי בְּהוּ לְעָלְמָא דְּאָתֵי אִשְׁתְּלִים בְּהוּ. מַאי טַעֲמָא. מִשּׁוּם דְּעָלְמָא דְּאָתֵי דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוִי. (ואי תימא דהאי עלמא לאו דידיה הוא אלא)","וְהָכִי תָּנֵינָן, הַאי עָלְמָא לָקֳבְלֵיהּ דְּעָלְמָא דְּאָתֵי, לָא הֲוֵי אֶלָּא כִּפְרוֹזְדוֹר לְגַבֵּי טְרַקְלִין. (בגין כך עלמא דאתי דקודשא בריך הוא הוי) וְכַד זָכֵי הַהוּא זַכָּאָה, בְּדִידֵיהּ זָכֵי. דְּתַנְיָא, כְּתִיב (דברים י״ח:ב׳) וְנַחֲלָה לֹא יִהְיֶה לּוֹ בְּקֶרֶב אֶחָיו. מַאי טַעְמָא. מִשּׁוּם דַּיְיָ' הוּא נַחֲלָתוֹ. זַכָּאָה חוּלָקֵיהּ, מַאן דְּזָכֵי לְאַחֲסָנָא אַחֲסַנְתָּא עִלָּאָה דָּא. זָכֵי בָּהּ בְּעָלְמָא דָּא, וּבְבֵיתָא דְּהַאי עָלְמָא. כַּךְ בְּעָלְמָא דְּאָתֵי, וּבְבֵיתָא עִלָּאָה קַדִּישָׁא, דִּכְתִּיב, (ישעיהו נ״ו:ה׳) וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמוֹתַי יָד וָשֵׁם, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא זַכָּאָה, דְּמָדוֹרֵיהּ עִם מַלְכָּא בְּבֵיתֵיהּ."],[[0,"וארא את ה':","את, הוא בדיוק. שהיא השכינה, ואראה מראת אלקים, מראת הוא בדיוק, שהיא השכינה, ובמדרגה אחת היו שניהם, ישעיהו ויחזקאל. שואל, אם כן, למה לא פירש ישעיהו כל כך כמו יחזקאל, אמר ר' יוסי זה כלל דהיינו ישעיה, וזה פירש, דהיינו יחזקאל. מה הטעם שיחזקאל פירש כל כך. ומשיב, אלא, מה שפירש יחזקאל, הכל היה צריך בשביל ישראל, שידעו האהבה שאהב אותם הקב\"ה, שהשכינה ומרכבותיה באות לגור ביניהם בגלות."],[1,"א\"ר חייא וכו':","אר\"ח, כתוב, בארץ כשדים. והרי כתוב, הן ארץ כשדים זה העם לא היה, למה נגלתה השכינה שם. אם תאמר, בשביל ישראל, היה טוב שהשכינה תשרה בתוכם ולא תהיה נגלית. ומשיב, אלא כך למדנו, אם לא היתה נגלית, לא היו יודעים שהשכינה בתוכם."],[2,"והא דאתגלייא וכו':","ומה שנתגלתה, מה כתוב, על נהר כבר, דהיינו על מים, במקום שאינו נטמא ואינו שורה בו טומאה. ונהר ההוא היה אחד מארבעה נהרות היוצאים מעדן שכתוב, על נהר כבר, מהו כבר. שכבר היה. ממקום שהשכינה שורה עליו. וכתוב, ותהי עליו שם יד ה', שם, ולא במקום אחר."],[3,"אמר רבי חייא וכו':","אר\"ח כתוב, ומתוכה דמות ארבע חיות וגו'. למדנו בסוד העליון, ארבע חיות יש שהם לפני ולפנים בהיכל הקדוש, שהוא בינה, והן הראשונות, זקנים הנמשכים מעתיקא קדישא, הן הכלל של השם הקדוש הוי\"ה. כי \u0003י'\u0004 היא אריה, \u0003ה'\u0004 היא שור, \u0003ו'\u0004 היא נשר, \u0003ה'\u0004 אחרונה היא אדם. שה\"ס ג' קוים ומלכות המקבלתם. ויחזקאל ראה רק דמות של המרכבות העליונות, כי הוא ראה אותן ממקום שאינו מאיר כל כך. דהיינו בעולם היצירה. למדנו, כעין שיש למעלה, בבינה כן יש למטה מהן, בזו\"ן, וכן יש בכל העולמות, הנקראים, בריאה, יצירה, עשיה, כולם אחוזים זה בזה וזה בזה. וכל מה שיש בעולם העליון יש בעולם התחתון, והוא ראה אותן, בעולם היצירה."],[4,"ואי תימא לעילא וכו':","ואם תאמר שראה אותן יותר למעלה מעולם היצירה. למדנו, משה ראה ממראה המאירה, שהוא ז\"א. וכל הנביאים לא ראו אלא מתוך מראה שאינה מאירה, שכתוב, ואראה מראת אלקים חסר ו' שהיא מלכות. וכתוב, אם יהיה נביאכם ה' במראה אליו אתודע וגו' לא כן עבדי משה וגו' וכתוב, פה אל פה אדבר בו."],[5,"א\"ר יוסי ת\"ח וכו':","אר\"י, בוא וראה, שהנביאים כולם כלפי משה, הם כנקבה כלפי זכר, שכתוב פה אל פה אדבר בו ומראה, שהיא בהכרח מראה המאירה, שהרי כתוב, פה אל פה אדבר בו. ולשאר הנביאים כתוב, במראה אליו אתודע, שהיא מראה שאינה מאירה. וכתוב, במראה, ולא במראת חסר \u0003ו'\u0004. כל שכן יחזקאל, שאפילו מראה לא כתוב בו, אלא מראת חסר \u0003ו'\u0004. שהוא ראה בעולם היצירה. וכל שכן שכתוב בו, במשה, ולא בחידות, אלא כל מלה על בירורו אשרי הדור, שנביא הזה היה שורה בתוכם."],[6,"א\"ר יוסי ברבי יהודה וכו':","אר\"י בר\"י, פנים בפנים ראו ישראל זיו יקר מלכם, ולא היה בהם עורים ופסחים וקצוצי ידים וחרשים. עורים, משמע, משכתוב, וכל העם רואים. פסחים, משכתוב, ויתיצבו בתחתית ההר. קצוצי ידים וחרשים, שכתוב נעשה ונשמע ולעתיד לבא כתוב, אז ידלג כאיל פסח ותרון לשון אלם."],[7,"וידבר אלקים את כל וגו':","רבי יהודה פתח, מי ימלל גבורות ה' ישמיע כל תהלתו. בכמה דרכים מעידה התורה באדם, שלא יחטא לפני אדונו. בכמה דרכים נותנת לו עצה שלא יסור מדרכיו לימין ולשמאל. בכמה דרכים נותנת לו עצה, איך לשוב לפני אדונו, וימחול לו."],[8,"דתנן שית מאה וכו':","שלמדנו, שש מאות ושלש עשרה מיני עצות נותנת התורה לאדם להיות שלם עם אדונו, משום שאדונו רצה להטיב לו בעולם הזה ובעולם הבא. וביותר, בעולם הבא. כי למדנו כל מה שהקב\"ה משלים את האדם, מטוב הזה שזוכה בהם לעולם הבא הוא נשלם בו. מה הטעם. משום שעולם הבא הוא של הקב\"ה."],[9,"והכי תנינן האי וכו':","וכך למדנו. עולם הזה כלפי עולם הבא אינו אלא כמו חדר הכניסה כלפי האולם. וכשזוכה אותו הצדיק זוכה בשלו. שלמדנו, כתוב, ונחלה לא יהיה לו בקרב אחיו. מה הטעם. משום שהוי\"ה הוא נחלתו. אשרי חלקו, מי שזוכה לרשת נחלה עליונה הזו, זוכה בה בעולם הזה, ובבית של עולם הזה, כך זוכה בעולם הבא ובבית העליון הקדוש, שכתוב, ונתתי להם בביתי ובחומותי יד ושם. אשרי חלקו של הצדיק ההוא שמדורו עם המלך בביתו."]],[[0,"","וָאֵרֶא אֶת ה', אֶת דַּוְקָא. וָאֶרְאֶה מַרְאֹת אֱלֹהִים, מַרְאֹת דַּוְקָא. וּבְדַרְגָּה אַחַת הָיוּ. אִם כָּךְ, אָז לָמָּה לֹא פֵרַשׁ יְשַׁעְיָה כָּל זֶה? אָמַר רַבִּי יוֹסֵי, זֶה כָּלַל וְזֶה פֵּרַשׁ. מָה הַטַּעַם יְחֶזְקֵאל פֵּרַשׁ אֶת כָּל זֶה? אֶלָּא הַכֹּל הִצְטָרֵךְ בִּשְׁבִיל יִשְׂרָאֵל, שֶׁיֵּדְעוּ אֶת הַחִבָּה שֶׁחִבֵּב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁשְּׁכִינָתוֹ וּמַרְכְּבוֹתָיו בָּאוּ לָדוּר בֵּינֵיהֶם בַּגָּלוּת."],[1,"","אָמַר רַבִּי חִיָּיא, בְּאֶרֶץ כַּשְׂדִּים? וַהֲרֵי כָּתוּב (ישעיה כג) הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה. לָמָּה הִתְגַּלְּתָה שָׁם שְׁכִינָה? אִם תֹּאמַר בִּשְׁבִיל יִשְׂרָאֵל - הָיָה טוֹב שֶׁתִּשְׁרֶה שְׁכִינָה בְתוֹכָם וְלֹא תִתְגַּלֶּה. אֶלָּא כָּךְ שָׁנִינוּ, אִם לֹא הָיָה נִגְלֵית, לֹא הָיוּ יוֹדְעִים."],[2,"","וְזְהִ שֶׁהִתְגַּלְּתָה, מַה כָּתוּב? עַל נְהַר כְּבָר. עַל הַמַּיִם. בְּמָקוֹם שֶׁלֹּא נִטְמָא וְלֹא שׁוֹרָה טֻמְאָה. וְאוֹתוֹ נָהָר הָיָה אֶחָד מֵאַרְבָּעָה נְהָרוֹת שֶׁיּוֹצְאִים מִגַּן עֵדֶן, שֶׁכָּתוּב עַל נְהַר כְּבָר. מַה זֶּה כְּבָר? שֶׁכְּבָר הָיָה מִמָּקוֹם שֶׁשְּׁכִינָה שׁוֹרָה עָלָיו, וְכָתוּב וַתְּהִי עָלָיו שָׁם יַד ה', שָׁם וְלֹא בְמָקוֹם אַחֵר."],[3,"","אָמַר רַבִּי חִיָּיא, כָּתוּב וּמִתּוֹכָהּ דְּמוּת אַרְבַּע חַיּוֹת וְזֶה מַרְאֵיהֶן דְּמוּת אָדָם לָהֵנָּה. שָׁנִינוּ, בְּסוֹד עֶלְיוֹן אַרְבַּע חַיּוֹת יֵשׁ שֶׁהֵן לִפְנַי וְלִפְנִים הַהֵיכָל הַקָּדוֹשׁ, וְהֵן רִאשׁוֹנוֹת, הָעַתִּיקִים מֵהָעַתִּיק הַקָּדוֹשׁ, כְּלַל הַשֵּׁם הָעֶלְיוֹן. וִיחֶזְקֵאל רָאָה דְמוּת הַמֶּרְכָּבוֹת הָעֶלְיוֹנוֹת, שֶׁהֲרֵי הוּא רָאָה מִמָּקוֹם שֶׁלֹּא הָיָה מֵאִיר כָּל כָּךְ. שָׁנִינוּ, כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה מֵהֶם, וְכֵן בְּכָל הָעוֹלָמוֹת כֻּלָּם אֲחוּזִים זֶה בָּזֶה וְזֶה בָּזֶה."],[4,"","וְאִם תֹּאמַר שֶׁהוּא רָאָה יוֹתֵר לְמַעְלָה - שָׁנִינוּ, מֹשֶׁה רָאָה בְּאַסְפַּקְלַרְיָה שֶׁמְּאִירָה, וְכָל הַנְּבִיאִים לֹא רָאוּ אֶלָּא מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, שֶׁכָּתוּב וָאֶרְאֶה מַרְאֹת אֱלֹהִים. וְכָתוּב (במדבר יב) אִם יִהְיֶה נְבִיאֲכֶם ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע וְגוֹ' לֹא כֵן עַבְדִּי מֹשֶׁה וְגוֹ', וְכָתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ."],[5,"","אָמַר רַבִּי יוֹסֵי, בֹּא וּרְאֵה שֶׁכָּל הַנְּבִיאִים כֻּלָּם לְגַבָּיו כִּנְקֵבָה לְגַבֵּי הַזָּכָר, שֶׁכָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה. וְלִשְׁאָר הַנְּבִיאִים (כתוב במראות, ולמשה ה') בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, בַּמַּרְאָה וְלֹא מַרְאוֹת. כָּל שֶׁכֵּן יְחֶזְקֵאל, שֶׁאֲפִלּוּ מַרְאָה לֹא כָתוּב בּוֹ, אֶלָּא מַרְאֹת חָסֵר, וְכָל שֶׁכֵּן שֶׁכָּתוּב בְּמֹשֶׁה וְלֹא בְחִידוֹת, אֶלָּא כָּל דָּבָר עַל בֻּרְיוֹ. אַשְׁרֵי הַדּוֹר שֶׁהַנָּבִיא הַזֶּה שָׁרוּי בְּתוֹכָם."],[6,"","אָמַר רַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה, פָּנִים בְּפָנִים רָאוּ יִשְׂרָאֵל אֶת זִיו כְּבוֹד מַלְכָּם, (של רבונם) וְלֹא הָיוּ בָהֶם סוּמִים וְחִגְּרִים וְקִטְּעִים וְחֵרְשִׁים. סוּמִים - מַשְׁמָע שֶׁכָּתוּב וְכָל הָעָם רֹאִים. חִגְּרִים - שֶׁכָּתוּב וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. קִטְּעִים וְחֵרְשִׁים - נַעֲשֶׂה וְנִשְׁמָע. וְלֶעָתִיד לָבֹא כָּתוּב (ישעיה לה) אָז יְדַלֵּג כְּאַיָּל פִּסֵּחַ וְתָרֹן לְשׁוֹן אִלֵּם."],[7,"","וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. רַבִּי יְהוּדָה פָּתַח, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. בְּכַמָּה דְרָכִים הֵעִידָה הַתּוֹרָה בָּאָדָם שֶׁלֹּא יֶחֱטָא לִפְנֵי רִבּוֹנוֹ. בְּכַמָּה דְרָכִים נָתְנָה לוֹ עֵצָה שֶׁלֹּא יִסְטֶה מִדְּרָכָיו יָמִין וּשְּׂמֹאל. בְּכַמָּה דְרָכִים נָתְנָה לוֹ עֵצָה אֵיךְ יָשׁוּב לִפְנֵי רִבּוֹנוֹ וְיִמְחֹל לוֹ."],[8,"","שֶׁשָּׁנִינוּ, שֵׁשׁ מֵאוֹת וּשְׁלֹשָׁה עָשָׂר מִינֵי עֵצָה נָתְנָה תוֹרָה לָאָדָם לִהְיוֹת שָׁלֵם בְּרִבּוֹנוֹ, מִשּׁוּם שֶׁרִבּוֹנוֹ רוֹצֶה לְהֵיטִיב לוֹ בָּעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא, וְיוֹתֵר לָעוֹלָם הַבָּא, שֶׁהֲרֵי שָׁנִינוּ, כָּל מַה שֶּׁהִשְׁלִים הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם - מֵאוֹתָן טוֹבוֹת שֶׁזּוֹכֶה בָּהֶם לָעוֹלָם הַבָּא הִשְׁתַּלֵּם בָּהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהָעוֹלָם הַבָּא הוּא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. (ואם תאמר שהעולם הזה אינו שלו אלא)"],[9,"","וְכָךָ שָׁנִינוּ, הָעוֹלָם הַזֶּה כְּנֶגֶד הָעוֹלָם הַבָּא אֵינוֹ אֶלָּא כִּפְרוֹזְדוֹר לִטְרַקְלִין. (משום כך העולם הבא הוא של הקדוש ברוך הוא) וּכְשֶׁזּוֹכֶה אוֹתוֹ הַצַּדִּיק - בְּשֶׁלּוֹ הוּא זוֹכֶה. שֶׁשָּׁנִינוּ, כָּתוּב (דברים ב) וְנַחֲלָה לֹא יִהְיֶה לּוֹ בְּקֶרֶב אֶחָיו. מָה הַטַּעַם? מִשּׁוּם שֶׁה' הוּא נַחֲלָתוֹ. אַשְׁרֵי חֶלְקוֹ מִי שֶׁזּוֹכֶה לְחֵלֶק יְרֻשָּׁה עֶלְיוֹן זֶה. זוֹכֶה בָּהּ בָּעוֹלָם הַזֶּה, וּבַבַּיִת שֶׁל הָעוֹלָם הַזֶּה. כָּךְ בָּעוֹלָם הַבָּא וּבַבַּיִת הָעֶלְיוֹן הַקָּדוֹשׁ, שֶׁכָּתוּב (ישעיהנו) וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ צַדִּיק שֶׁמְּדוֹרוֹ עִם הַמֶּלֶךְ בְּבֵיתוֹ."]]],[["ר' שִׁמְעוֹן אָמַר, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא זַכָּאָה, דְּזָכֵי לְהַאי דִּכְתִּיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', עִם יְיָ' לָא כְּתִיב, אֶלָּא עַל יְיָ'. מַאי עַל יְיָ'. אֲתָר דְּעִלָּאִין וְתַתָּאִין אִתְמַשְּׁכָן מִינֵּיהּ, וְתָאָבִין לְהַהוּא אֲתָר, דִּכְתִּיב, (תהילים קכ״א:א׳) מֵאַיִן יָבֹא עֶזְרִי. וּכְתִיב, (דניאל ז׳:י״ג) וְעַד עַתִּיק יוֹמַיָּא מְטָה וּקְדָמוֹהִי הַקְרְבוּהִי. וְתִיאוּבְתָּא וְעִנּוּגָא דְּצַדִּיקַיָּא, לְאִסְתַּכְּלָא לְהַהוּא זִיוָא, דְּכָל זִיוָא מִינֵּיהּ נָפְקָא, וְאִתְמַשְּׁכָן מִנֵיהּ כָּל אִינּוּן כִּתְרִין.","תּוּ אָמַר רַבִּי שִׁמְעוֹן, תָּנֵינָן בְּהַאי קְרָא אָז תִּתְעַנַּג עַל יְיָ', סוֹפְיֵהּ דִּקְרָא מַה כְּתִיב, וְהִרְכַּבְתִּיךָ עַל בָּמוֹתֵי אָרֶץ, עַל הַהוּא אֲתָר דְּאִקְרֵי בָּמוֹתֵי אָרֶץ, אִיהוּ לְעֵילָּא מֵהַאי אֶרֶץ, וְהַהוּא אֲתָר דְּאִקְרֵי בָּמֳתֵי אָרֶץ, הַיְינוּ שָׁמַיִם. וְהַיְינוּ דִּכְתִּיב עַל בָּמֳתֵי אָרֶץ.","עַל יְיָ' אָמַר ר' אַבָּא, אָז תֵּשֵׁב לָא כְּתִיב, אֶלָּא אָז תִּתְעַנַּג עַל יְיָ', הַיְינוּ שָׁמַיִם. דִּכְתִּיב, (תהילים נ״ז:ו׳) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים. וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ, הַיְינוּ אֶרֶץ הַחַיִּים, מִמַּשְׁמַע דִּכְתִּיב עַל בָּמוֹתֵי, לְאַכְלְלָא צִיּוֹן וִירוּשְׁלֵים, דְּאִקְרוּן בָּמֳתֵי אָרֶץ, וְהַיְינוּ שָׁמַיִם דִּלְעֵילָּא, וְאֶרֶץ דִּלְעֵילָּא. וּמִלָּה דְּאָמַר ר' שִׁמְעוֹן, הָכִי הוּא, וְכֹלָּא חַד, דִּכְתִּיב וְעַד עַתִּיק יוֹמַיָא מְטָה וְגוֹ', וְכָל הָנֵי מִילֵי לַאֲתָר חַד סַלְּקִין.","אָמַר ר' אַבָּא לְּרַבִּי שִׁמְעוֹן, לֵימָא לִי מֹר, הַאי קְרָא כּוּלֵיהּ, בְּמַאי אוֹקִימְנָא לֵיהּ, דִּכְתִּיב אָז תִּתְעַנַּג עַל יְיָ' וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ. אָמַר לֵיהּ, הָא כֹּלָּא אִתְּמַר, דְּתַפְנוּקָא וְעִדּוּנָא עַל יְיָ' כְּתִיב, אֲתָר דְּאִיהוּ לְעֵילָּא. וּכְתִיב וְעַד עַתִּיק יוֹמַיָּא מְטָה וְגוֹ'. עַל בָּמֳתֵי אָרֶץ כְּמָה דְּאִתְּמַר.","וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ. כְּמָה דִּכְתִּיב, (בראשית כ״ז:כ״ח) וְיִתֵּן לְךָ הָאֱלהִים מִטַּל הַשָּׁמַיִם וְגוֹ', וְהַיְינוּ נַחֲלַת יַעֲקֹב. וּבִרְכָּתָא דְּבָרִיךְ יִצְחָק לְיַעֲקֹב, עַל הַאי שָׁמַיִם קָאָמַר. וּבַרְכֵיהּ בְּבִרְכָּתָא, דִּזְמִינִין בְּנוֹי דְּיַעֲקֹב, לְאַחֲיָא בְּהַהוּא טַלָּא לְזִמְנָא דְּאָתֵי, דִּכְתִּיב וְיִתֵּן לְךָ הָאֱלהִים. לְךָ וְלא לְאַחֲרָא. מִטַּל הַשָּׁמַיִם, דְּבֵיהּ זְמִינִין מֵתַיָּא לְאַחֲיָא לְזִמְנָא דְּאָתֵי, דְּנָפִיק מֵעַתִּיקָא לְזְעֵירָא דְּאַפִּין, וְשַׁרְיָא בְּהַאי שָׁמַיִם. אִסְתָּכַּל ר' אַבָּא וְאָמַר, הַשְׁתָּא אִשְׁתְּמַע כֹּלָּא וְאִשְׁתְּכַח דְּבִרְכָּתָא דְּיִצְחָק, עִלָּאָה מִמַּאי דַּחֲשִׁיבְנָא.","תָּאנָא (תהלים כו) מִי יְמַלֵּל (ס\"ד ע\"א) גְבוּרֹת יְיָ'. מִי יְמַלֵּל, מִי יְדַבֵּר מִבָּעֵי לֵיהּ. אָמַר ר' חִיָּיא, כְּמָה דְאַתְּ אָמֵר, (דברים כ״ג:כ״ו) וְקָטַפְתָּ מְלִילוֹת בְּיָדֶךָ. גְבוּרֹת יְיָ', דְּסַגִּיאִין אִינּוּן, וְנָפְקִין מִגְּבוּרָה חַד. וְתָאנָא, חַד גְּבוּרָה עִלָּאָה, עִטְרָא דְּעִטְּרִין, מִתְעַטְּרָא, וְנָפְקִין מִינֵּיהּ חַמְשִׁין תַּרְעִין. מִנְּהוֹן יְמִינָא, וּמִנְהוֹן שְׂמָאלָא. וְכָל חַד וְחַד גְּבוּרָה אִתְקְרֵי, וְכָל חַד וְחַד מִתְעַטְּרָא, בְּקַרְדִיטִי גְּלִיפִין נְהוֹרִין, וְכֻלְּהוּ אִקְרוּן גְבוּרֹת יְיָ'.","אָמַר רַבִּי חִיָּיא, גְבוּרֹת יְיָ' חָסֵר כְּתִיב, דְּהָא כֻּלְּהוּ כְּלִילָן בְּדָא. יַשְׁמִיעַ כָּל תְּהִלָּתוֹ: דָּא הוּא שְׁכִינַת זִיו יְקָרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב וּתְהִלָּתוֹ מָלְאָה הָאָרֶץ.","אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', שֵׁם הָאֶחָד פִּישׁוֹן וְגוֹ'. הָא אִלֵּין בִּשְׁמָהָן אִקְרוּן. וַהֲנִי אַרְבַּע מֵהַהוּא נָהָר דְּנָפִיק אִתְמַשְּׁכָן. מַה שְּׁמֵיהּ דְּהַהוּא נַהֲרָא דְּנָפִיק. אָמַר ר' שִׁמְעוֹן, (ויקרא נ\"ה ע\"א) יוּבַל שְׁמֵיהּ. דִּכְתִּיב, (ירמיהו י״ז:ח׳) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו, וּכְתִיב וְלֹא יָמִישׁ מֵעֲשׂוֹת פֶּרִי. מַאי טַעֲמָא לא יָמִישׁ, מִשּׁוּם דְּעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְעַל דָּא כְּתִיב (ישעיהו נ״ח:י״א) וּכְמוֹצָא מַיִם אֲשֶׁר לא יְכַזְּבוּ מֵימָיו. וּבְגִין כַּךְ כְּתִיב יוֹצֵא, (ויקרא ס\"ה ע\"ב) יוֹצֵא וְאֵינוֹ פּוֹסֵק.","תָּאנָא אָמַר רִבִּי שִׁמְעוֹן כְּתִיב (שמות כ׳:א׳) וַיְדַבֵּר אֱלהִים אֵת כָּל הַדְּבָרִים וְגוֹ', וַיְדַבֵּר, בְּגִין לְאַכְרְזָא מִילִין. דְּתָאנָא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי, וְשָׁאֲרִי לְמַלְּלָא, עִלָּאִין וְתַתָּאִין אִתְחַלְחֲלוּ, וְנַפְקוּ נִשְׁמָתְהוֹן דְּיִשְׂרָאֵל.","וְתָאנָא הַהוּא מִלָּה, הֲוָה טָאס מִלְּעֵילָּא לְתַתָּא, וּמִתְגַּלְּפָא בְּאַרְבַּע רוּחֵי עָלְמָא, וְסַלְּקָא וְנַחְתָּא. כַּד סַלְּקָא, אִשְׁתַּאֲבָא מִטוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא, וְאִשְׁתָּאֲבָא בְּהַהוּא טַלָּא דִּלְעֵילָּא, וְאַסְחַר בְּסַחֲרָנֵיהוֹן דְּיִשְׂרָאֵל, וְתָבַת בְּהוֹן נִשְׁמָתְהוֹן וְאַסְחַר וִּמִתְגַּלְּפָא בְּאַתְרֵיהּ, בְּלוּחֵי אַבְנָא. וְכֵן כָּל מִלָּה וּמִלָּה."],[[0,"ר' שמעון אמר וכו':","רש\"א, אשרי חלקו של צדיק ההוא שזכה לזה, שכתוב, אז תתענג על ה', עם ה' לא כתוב, אלא, על ה', מהו על ה'. ומשיב, הוא מקום שעליונים ותחתונים נמשכים ממנו ומשתוקקים למקום ההוא שכתוב, \u0003מאין\u0004 יבא עזרי, דהיינו הכתר שנקרא \u0003אין\u0004 וכתוב, ועד עתיק יומיא מטא וקדמוהי הקרבוהי. דהיינו הכתר שנקרא עתיק יומיא. וחשקם ועינוגם של הצדיקים הוא, להסתכל בזיו ההוא,שכל זיו יוצא ממנו, וממנו נמשכים כל הכתרים. שהם הספירות."],[1,"תו אמר ר' שמעון וכו':","עוד, אמר ר\"ש, למדנו במקרא זה, אז תתענג על ה'. סופו של המקרא מה כתוב, והרכבתיך על במתי ארץ. היינו על מקום ההוא שנקרא במתי ארץ, שהוא למעלה מארץ הזו, דהיינו למעלה מן המלכות שנקראת ארץ, ומקום ההוא שנקרא במתי ארץ, היינו השמים, שהוא ז\"א, והיינו שכתוב, על במתי ארץ, כי השמים הם למעלה מארץ."],[2,"על ה' אמר ר\"א וכו':","אר\"א, אז תשב לא כתוב, אלא אז תתענג על ה', היינו שמים שהוא ז\"א, שכתוב רומה על השמים אלקים, שפירושו ז\"א, והרכבתיך על במתי ארץ, היינו ארץ החיים, שהיא המלכות שנקראת ארץ, ומשמע משכתוב, על במתי, הוא לכלול ציון וירושלים שהם פנימיות וחיצוניות של יסוד המלכות, והיינו שהכתוב מדבר משמים של מעלה, שהוא ז\"א ומארץ שלמעלה, שהיא המלכות. והדבר שאמר ר' שמעון כך הוא כמו שאמרתי, והכל אחד, שכתוב, ועד עתיק יומיא מטא וגו'. וכל אלו הדברים עולים במקום אחד."],[2,"","פירוש. ר' אבא מבאר דברי ר' שמעון, שאמר, על ה' פירושו כתר, ואומר ר' אבא, שכונתו, שפע הכתר הנמשך מכתר לז\"א, והמקבל הוא במקום ז\"א. כי אם היתה הכונה במקום כתר, היה צריך לומר אז תשב על ה', שישב במקום כתר, והכתוב אומר אז תתענג, היינו שיתענג משפע הכתר שבמקום ז\"א, הנקרא שמים, ולא ממקום הכתר, שאין השגה שם. וכן על במתי ארץ שמפרש ר\"ש שהוא שמים, דהיינו ז\"א, אומר ר' אבא שהיא המלכות, והיינו ג\"כ שפע ז\"א המקובל ממקום המלכות, הנקראת ארץ. וז\"ש, \u0003ומלה דאמר ר\"ש הכי הוא\u0004 וכו'. כי רק מפרש דבריו כמו שנתבאר. ומוכיח דבריו, שאין כונת ר\"ש כתר ממש, שהרי מביא הכתוב, ועד עתיק יומיא מטא, דהיינו רק שמגיע לכתר הנקרא עתיק יומיא, כי מטא פירושו מגיע, והיינו ע\"י שמקבל שפע הכתר ממקום ז\"א, הוא מגיע לכתר."],[3,"אמר ר' אבא לר\"ש וכו':","אר\"א לר' שמעון, יאמר לי אדוני מקרא זה כולו, במה הוא מעמיד אותו. שכתוב, אז תתענג וגו' והאכלתיך נחלת יעקב אביך. אמר לו ר' שמעון, והרי הכל נאמר. שהתענוג והעדן \u0003על ה',\u0004 כתוב, שהוא למעלה דהיינו כתר כנ\"ל. וכתוב, ועד עתיק יומיא מטא וגו'. \u0003על במתי ארץ,\u0004 כמו שאמרנו. שהוא ארץ החיים דהיינו מלכות."],[4,"והאכלתיך נחלת יעקב אביך:","הוא כמו שכתוב, ויתן לך האלקים מטל השמים וגו'. וטל השמים, היינו נחלת יעקב. והברכה שברך יצחק ליעקב על שמים הזה אמר, שהוא ז\"א, וברכו בברכה, שעתידים בניו של יעקב לעמוד לתחיה על ידי טל ההוא לעתיד לבא, שכתוב, \u0003ויתן לך האלקים,\u0004 לך ולא לאחר. \u0003מטל השמים,\u0004 שבו עתידים המתים לעמוד לתחיה לעתיד לבא. אשר טל הזה יוצא מעתיקא קדישא לזעיר אנפין, הנקרא שמים, ושורה בשמים הזה. הסתכל ר' אבא במקרא, ואמר, עתה מובן הכל, ונמצא שברכתו של יצחק היא יותר למעלה ממה שחשבתי."],[5,"תאנא, מי ימלל גבורות ה':","שואל, אומר, מי ימלל, מי ידבר היה צריך לומר. אמר ר' חייא, כמש\"א, וקטפת \u0003מלילות\u0004 בידך. שנקראים כן, משום שמפרישים הגרעינים מן השבלת על ידי מלילה, אף כאן מי ימלל, פירושו, מי ימלל ויבטל גבורות ה'. \u0003גבורת ה',\u0004 חסר \u0003ו'\u0004 של סימן הרבים, רומז, שגבורות הרבה הן, ויוצאות מגבורה אחת. ולמדנו, גבורה עליונה אחת, עטרה של העטרות, שהיא בינה שדינים מתעוררים ממנה, מתעטרת, ויוצאים ממנה חמשים שערים, מהם ימין, ומהם שמאל, וכל אחד ואחד נקרא גבורה, וכל אחד ואחד מתעטר באורות של חקיקות הגבוהות, וכולם נקראים גבורות ה'."],[5,"","חקיקות הגבוהות, היינו חקיקות הדין שנעשו בבינה על ידי עלית המלכות אליה, שבסבתה באה הבינה לקטנות. ואורות החקיקות הגבוהות, היינו הג\"ר שחוזרות לבינה בסבת ירידת המלכות ממנה."],[6,"אמר ר' חייא וכו':","אר\"ח, על כן, גבורת ה' כתוב חסר ו', משום שכל הגבורות כלולות בזו, דהיינו בגבורה העליונה שהיא בינה. \u0003ישמיע כל תהלתו,\u0004 זו היא השכינה, זיו יקרו של הקב\"ה, שכתוב, \u0003ותהלתו\u0004 מלאה הארץ."],[7,"אמר ר' שמעון וכו':","אר\"ש, כתוב, ונהר יוצא מעדן וגו' שם האחד פישון וגו'. הרי אלו הנהרות נקראים בשמות, ואלו הארבעה נמשכים מנהר ההוא היוצא מעדן. ומה שמו של הנהר היוצא מעדן. אמר ר' שמעון, יובל שמו, שכתוב, ועל יובל ישלח שורשיו, וכתוב, ולא ימיש מעשות פרי. מה הטעם לא ימיש מעשות פרי, משום דעל יובל ישלח שורשיו, שהיא בינה. ועל כן כתוב, וכמוצא מים אשר לא יכזבו מימיו, ששפע הבינה אינו פוסק. וע\"כ כתוב, יוצא מעדן, יוצא ואינו פוסק."],[8,"תאנא א\"ר שמעון וכו':","למדנו אמר ר' שמעון, כתוב, וידבר אלקים את כל וגו': אומר וידבר, ולא ויאמר, הוא משום, כי וידבר הוא בהרמת קול להכריז הדברים. (כמ\"ש בזהר נשא קל\"ב ע\"ב דפ\"י) שלמדנו, בשעה שהקב\"ה נתגלה והתחיל לדבר, העליונים והתחתונים נתחלחלו, ויצאו נשמות ישראל."],[9,"ותאנא ההוא מלה וכו':","ולמדנו, מלה ההיא היתה פורחת מלמעלה למטה, ונחקקה בארבע רוחות העולם, ועלתה וירדה. כשעלתה, נתמלאה מהרי אפרסמון הטהור, ונתמלאה בטל ההיא שלמעלה, ומסבבת סביב ישראל ומחזירה להם נשמתם. ומסבבת וחוזרת ונחקקת במקומה בלוחות האבן. וכן כל מלה ומלה."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ צַדִּיק שֶׁזּוֹכֶה לָזֶה, שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. לֹא כָתוּב עִם ה', אֶלָּא עַל ה'. מַה זֶּה עַל ה'? מָקוֹם שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים נִמְשָׁכִים מִמֶּנּוּ וּתְאֵבִים לְאוֹתוֹ מָקוֹם, שֶׁכָּתוּב (תהלים קכא) מֵאַיִן יָבא עֶזְרִי. וְכָתוּב (דניאלז) וְעַד עַתִּיק הַיָּמִים מַגִּיעַ וּלְפָנָיו הִקְרִיבוּהוּ. וּתְשׁוּקַת וְעֹנֶג הַצַּדִּיקִים לְהִסְתַּכֵּל לְאוֹתוֹ זִיו, שֶׁכָּל זִיו יוֹצֵא מִמֶּנּוּ, וּמִמֶּנּוּ נִמְשָׁכִים כָּל אוֹתָם הַכְּתָרִים."],[1,"","עוֹד אָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ בְּפָסוּק זֶה אָז תִּתְעַנַּג עַל ה', בְּסוֹף הַפָּסוּק מַה כָּתוּב? וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ, עַל אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּמֳתֵי אָרֶץ, הוּא לְמַעְלָה מֵהָאָרֶץ הַזּוֹ. וְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּמֳתֵי אָרֶץ, הַיְנוּ שָׁמַיִם, וְהַיְנוּ שֶׁכָּתוּב עַל בָּמֳתֵי אָרֶץ."],[2,"","עַל ה' - אָמַר רַבִּי אַבָּא, לֹא כָתוּב אָז תֵּשֵׁב, אֶלָּא אָז תִּתְעַנַּג עַל ה', הַיְנוּ שָׁמַיִם, שֶׁכָּתוּב (תהליםנז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים. וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ, הַיְנוּ אֶרֶץ הַחַיִּים, מִמַּשְׁמָע שֶׁכָּתוּב עַל בָּמֳתֵי, לְהַכְלִיל צִיּוֹן וִירוּשָׁלַיִם שֶׁנִּקְרְאוּ בָּמֳתֵי אָרֶץ, וְהַיְנוּ שָׁמַיִם שֶׁלְּמַעְלָה וְאֶרֶץ שֶׁלְּמַעְלָה. וְהַדָּבָר שֶׁאָמַר רַבִּי שִׁמְעוֹן כָּךְ הוּא, וְהַכֹּל אֶחָד, שֶׁכָּתוּב וְעַד עַתִּיק הַיָּמִים מַגִּיעַ וְגוֹ', וְכָל הַדְּבָרִים הַלָּלוּ עוֹלִים לְמָקוֹם אֶחָד."],[3,"","אָמַר רַבִּי אַבָּא לְרַבִּי שִׁמְעוֹן, יֹאמַר לִי מוֹרִי, פָּסוּק זֶה כֻּלּוֹ בַּמֶּה בֵּאַרְנוּ אוֹתוֹ, שֶׁכָּתוּב אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ? אָמַר לוֹ, הֲרֵי הַכֹּל נֶאֱמַר כְּבָר, שֶׁתַּפְנוּק וְעִדּוּן עַל ה' כָּתוּב, מָקוֹם שֶׁהוּא לְמַעְלָה, וְכָתוּב וְעַד עַתִּיק הַיָּמִים מַגִּיעַ. עַל בָּמֳתֵי אָרֶץ, כְּמוֹ שֶׁנִּתְבָּאֵר."],[4,"","וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךְ, כְּמוֹ שֶׁכָּתוּב (בראשית כז) וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וְגוֹ', וְהַיְנוּ נַחֲלַת יַעֲקֹב. וְהַבְּרָכָה שִּבּרַךָ יּצּחָק אִת יַּעַקב, עַל הַשָּמַיּם הַלָּלוּ הוּא אָמַר, וּברכו בּברָכָה, שִּעַתיּדיּם בּניּ יַּעַקב, להחָיּות בּאותו טַל לִעָתיּד לָבא, שִּכָּתוּב ויּתִן לךְ הָאִלהיּם, לךְ ולא לאַחר, מטַל הַשָּמַיּם, שִּבּו עַתיּדיּם הַמּתיּם להחָיּות לִעָתיּד לָבא, שִּיּוצּא מֵהָעַתִּיק לִזְעֵיר אַנְפִּין וְשׁוֹרֶה בַשָּׁמַיִם הַלָּלוּ. הִתְבּוֹנֵן רַבִּי אַבָּא וְאָמַר, עַכְשָׁו נִשְׁמָע הַכֹּל, וְנִמְצֵאת בִּרְכַּת יִצְחָק עֶלְיוֹנָה מִמַּה שֶּׁחָשַׁבְתִּי."],[5,"","שָׁנִינוּ, מִי יְמַלֵּל גְּבוּרֹת ה'. מִי יְמַלֵּל? מִי יְדַבֵּר הָיָה צָרִיךְ לִהְיוֹת! אָמַר רַבִּי חִיָּיא, כְּמוֹ שֶׁנֶּאֱמַר (דברים כג) וְקָטַפְתָּ מְלִילֹת בְּיָדֶךְ. גְּבוּרֹת ה', שֶׁרַבִּים הֵם וְיוֹצְאִים מִגְּבוּרָה אַחַת. וְשָׁנִינוּ, גְּבוּרָה עֶלְיוֹנָה אַחַת, עֲטֶרֶת הָעֲטָרוֹת, מִתְעַטֶּרֶת, וְיוֹצְאִים מִמֶּנָּה חֲמִשִּׁים שְׁעָרִים, מֵהֶם יָמִינָה וּמֵהֶם שְׂמֹאלָה, וְכָל אַחַת נִקְרֵאת גְּבוּרָה, וְכָל אַחַת וְאַחַת מִתְעַטֶּרֶת בָּאוֹרוֹת שֶׁל חֲקִיקוֹת גְּבוֹהוֹת, וְכֻלָּם נִקְרָאוֹת גְּבוּרוֹת ה'."],[6,"","אָמַר רַבִּי חִיָּיא, גְּבוּרֹת ה' חָסֵר כָּתוּב, שֶׁהֲרֵי כֻּלָּם כְּלוּלִים בָּזֶה. יַשְׁמִיעַ כָּל תְּהִלָּתוֹ - זוֹהִי שְׁכִינַת זִיו כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וּתְהִלָּתוֹ מָלְאָה הָאָרֶץ."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', שֵׁם הָאֶחָד פִּישׁוֹן וְגוֹ'. הֲרֵי אֵלֶּה נִקְרָאִים בְּשֵׁמוֹת, וְאַרְבָּעָה הַלָּלוּ מֵאוֹתוֹ נָהָר שֶׁיּוֹצֵא הֵם נִמְשָׁכִים. מַה שֵּׁם אוֹתוֹ הַנָּהָר שֶׁיּוֹצֵא? אָמַר רַבִּי שִׁמְעוֹן, שְׁמוֹ יוּבַל, שֶׁכָּתוּב (ירמיה יז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו, וְכָתוּב וְלֹא יָמִישׁ מֵעֲשׂוֹת פֶּרִי. מָה הַטַּעַם לֹא יָמִישׁ? מִשּׁוּם שֶׁעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְעַל זֶה כָּתוּב (ישעיה נח) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו. וּמִשּׁוּם כָּךְ כָּתוּב יֹצֵא, יוֹצֵא וְאֵינוֹ פוֹסֵק."],[8,"","שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים וְגוֹ'. וַיְדַבֵּר, כְּדֵי לְהַכְרִיז דְּבָרִים. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְחִיל לְדַבֵּר, עֶלְיוֹנִים וְתַחְתּוֹנִים הִתְחַלְחֲלוּ, וְיָצְאוּ נִשְׁמוֹתֵיהֶם שֶׁל יִשְׂרָאֵל."],[9,"","וְשָׁנִינוּ, אוֹתוֹ דִבּוּר הָיָה טָס מִלְמַעְלָה לְמַטָּה, וְנֶחְקָק בְּאַרְבַּע רוּחוֹת הָעוֹלָם וְעוֹלֶה וְיוֹרֵד. כְּשֶׁעוֹלֶה, נִשְׁאָב מֵהָרֵי אֲפַרְסְמוֹן זַךְ, וְנִשְׁאָב בְּאוֹתוֹ טַל שֶׁלְּמַעְלָה וְסוֹבֵב סְבִיב יִשְׂרָאֵל, וְשָׁבָה בָּהֶם נִשְׁמָתָם, וְסוֹבֵב וְנֶחְקָק בִּמְקוֹמוֹ בְּלוּחוֹת אֶבֶן. וְכֵן כָּל מִלָּה וּמִלָּה."]]],[["אָמַר רַבִּי שִׁמְעוֹן, כָּל מִלָּה וּמִלָּה הֲוָה מַלְיָא בְּכָל אִינּוּן טַעֲמִין, בְּכָל אִינּוּן מִלִּין גְּזִרִין, אַגְרִין, וְעוֹנָשִׁין, רָזִין וְסִתְרִין כְּאַסְקוּפָּא (נ\"א כאספוקא) דָּא, דְּאִיהִי מַלְיָא מִכֹּלָּא.","וּבְשַׁעֲתָא דְּהֲוָה נָפִיק הַהוּא מִלָּה, אִתְחָזֵי חַד. וְכַד הֲוָה מִתְגַּלְּפָא בְּאַתְרוֹי אִתְחָזוּן בְּהַהוּא מִלָּה, שִׁבְעִין עַנְפִּין, דְּסַלְּקִין בְּגַוָּה, וְחַמְשִׁין כִּתְרִין (נ\"א רתיכין) חָסֵר חַד מֵהַאי גִּיסָא, וְחַמְשִׁין חָסֵר חַד מִגִּיסָא אַחֲרָא כְּפַטִּישָׁא דָּא, בְּזִמְנָא דְּאִיהוּ בָּטַשׁ בְּטִנָרָא. כְּמָה דְּאַתְּ אָמֵר (ירמיהו כ״ג:כ״ט) וּכְפַטִּישׁ יְפוֹצֵץ סָלַע. וַהֲווּ חָמָאן כָּל יִשְׂרָאֵל עֵינָא בְּעֵינָא, וַהֲווּ חַדָּאן.","וְכֻלְּהוּ דָּרִין בַּתְרָאִין כֻּלְּהוּ אִזְדְּמָנוּ לְתַמָּן, וְכֻלְּהוּ קַבִּילוּ אוֹרַיְיתָא בְּטוּרָא דְּסִינַי, דִּכְתִּיב, (דברים כ״ט:י״ד) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ', וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם. וְכֻלְּהוּ כָּל חַד וְחַד כַּדְקָא חֲזֵי לֵיהּ. וְכֻלְּהוּ חָמָאן וּמְקַבְּלִין מִלִּין.","אֱלהִים: דָּא גְּבוּרָא. אֵת: דְּאִתְכְּלִיל בִּימִינָא, כְּמָה דְּתָנֵינָן (בראשית א) אֵת הַשָּׁמַיִם, דְּאִיהוּ יְמִינָא. וְאֵת הָאָרֶץ, דְּאִיהוּ שְׂמָאלָא. דִּכְתִּיב, (ישעיהו מ״ח:י״ג) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם. וִימִינָא דָּא הוּא אֵת. כָּל: לְאַכְלְלָא כָּל שְׁאַר כִּתְרִין. הַדְּבָרִים: מִתְקַשְּׁרָן דָּא בְּדָא הָאֵלֶּה: כָּל אִינּוּן טַעֲמִין, כָּל אִינּוּן רָזִין, כָּל אִינּוּן סִתְרִין, גִּזְרִין וְעוֹנָשִׁין.","לֵאמֹר: לְמֶהֱוֵי יָרוּתָא לְכֹלָּא. דִּכְתִּיב, (דברים ל״ג:ד׳) תּוֹרָה צִוָּה לָנוּ מֹשֶׁה מוֹרָשָׁה וְגו'. דְּאִי תֵּימָא לְגַלָּאָה מַה דְּלָא אִצְטְרִיךְ לְגַלָּאָה לְכָל בַּר נָשׁ, כְּתִיב אָנֹכִי יְיָ' אֱלֹהֶיךָ. כְּמָה דַּאֲנָא טְמִירָא וְסָתִים, כַּךְ יִהְיוּ מִלִּין אִלֵּין טְמִירִין וּסְתִימִין בְּלִבָּךְ.","דָּבָר אַחֵר וַיְדַבֵּר אֱלֹהִים, חַד. אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר הָא חָמֵשׁ דַּרְגִּין אַחֲרָנִין. ר' יְהוּדָה אָמַר, וַיְדַבֵּר אֱלהִים: גְּבוּרָה. אֶת: יְמִינָא. כָּל: דָּא וְדָא (האלה, אינון דאתגליין דכתיב וכל העם ראים את הקולת דבר אחר כל) אָמַר ר' יִצְחָק, לְאַכְלְלָא אַבְרָהָם דִּכְתִּיב, (בראשית כ״ד:א׳) וַיְיָ' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל.","הַדְּבָרִים: לְאַכְלְלָא שְׁאַר כִּתְרִין דְּאִתְכַּסְיָין. הָאֵלֶּה: אִינּוּן דְּאִתְגַּלְּיָין. וּכְתִיב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. לֵאמֹר: דָּא הוּא דִּכְתִּיב, (משלי י״ב:ד׳) אֵשֶׁת חָיִל עֲטֶרֶת בַּעְלָהּ. וּכְתִיב, (ירמיהו ג׳:א׳) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ.","אָמַר ר' יִצְחָק, אֲמַאי אִתְיְהִיבַת אוֹרַיְיתָא בְּאֶשָּׁא וַחֲשׁוֹכָא, דִּכְתִּיב, (דברים ד׳:י״א) וְהָהָר בּוֹעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם חֹשֶׁךְ עָנָן וַעֲרָפֶל. דְּכָל מַאן דְּיִשְׁתָּדַּל בְּאוֹרַיְיתָא, אִשְׁתֵּזִיב מֵאֶשָּׁא אַחֲרָא דְּגֵיהִנָּם, וּמֵחֲשׁוֹכָא דִּמְחַשְׁכִין כָּל שְׁאַר עַמִּין לְיִשְׂרָאֵל, דְּבִזְכוּתֵיהּ דְּאַבְרָהָם אִשְׁתֵּזִיבוּ יִשְׂרָאֵל מֵאֶשָּׁא דְּגֵיהִנָּם.","דְּתַנְיָא אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, כָּל זִמְנָא דְּבָנֶיךָ יִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא, יִשְׁתֵּזְבוּן מֵאִלֵּין. וְאִי לָא, הָא נוּרָא דְּגִיהִנָּם דְּשַׁלְטָא בְּהוּ, וְיִשְׁתַּעְבְּדוּן בֵּינִי עֲמַמְיָא. אֲמַר לֵיהּ, בִּתְרֵי קְטוּרֵי לָא מִזְדַּקְּפָן מִלִּין, אֶלָּא אִי נִיחָא קַמָּךְ, יִשְׁתֵּזְבוּן מִנּוּרָא דְּגֵיהִנָּם, וְיִשְׁתַּעְבְּדוּן בֵּינִי עֲמַמְיָא, עַד דִּיתוּבוּן גַּבָּךְ. אָמַר לֵיהּ יֵאוֹת הוּא וַדַּאי, הֲדָא הוּא דִכְתִיב, (דברים ל״ב:ל׳) אִם לֹא כִּי צוּרָם מְכָרָם. מַאן הוּא צוּרָם. דָּא הוּא אַבְרָהָם. דִּכְתִּיב, (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. וַיְיָ' הִסְגִּירָם, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְּאִסְתָּכַּם עַל יְדוֹי.","אָמַר ר' יְהוּדָה, מִיּוֹמָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם עַד יוֹמָא דְּאִתְיְהִיבַת אוֹרַיְיתָא, חַמְשִׁין יוֹמִין הֲווֹ. מַאי טַעְמָא אָמַר ר' יְהוּדָה, מִשּׁוּם אִינּוּן שָׁנֵי דְּיוֹבְלָא, דִּכְתִּיב, (ויקרא כ״ה:י׳) וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה.","תָּאנָא, אָמַר רַבִּי שִׁמְעוֹן, הַהוּא יוֹבְלָא אַפִּיק לוֹן לְיִשְׂרָאֵל מִמִּצְרַיִם. וְאִי תֵּימָא דְּיוֹבְלָא מַמָּשׁ. אֶלָּא (מ\"ו ע\"ב, פ\"ה ע\"ב) מִסִּטְרָא דְּיוֹבְלָא הֲוָה, וּמִסִּטְרָא דְּיוֹבְלָא אִתְּעַר דִּינָא עַל מִצְרָאֵי, וּבְגִינֵי כַּךְ חַמְשִׁין אִלֵּין דְּיוֹבְלָא הֲווֹ."],[[0,"אמר ר' שמעון וכו':","אר\"ש, כל מלה ומלה היתה מלאה בכל אלו הטעמים, בכל אלו דברי גזרות, שכר ועונש, סודות וסתרים, כאוצר הזה המלא מכל."],[1,"ובשעתא דהוה נפיק וכו':","ובשעה שמלה ההיא היתה יוצאת נראית כאחת, וכשהיתה נחקקת במקומה, בלוחות האבן, נראים במלה ההיא ע' ענפים שעולים בתוכה, וחמשים כתרים חסר אחד מצד ההיא, וחמשים חסר אחד מצד האחר. כפטיש הזה בזמן שהוא מכה בהר, כש\"א כפטיש יפוצץ סלע. והיו רואים ישראל עין בעין והיו שמחים."],[2,"וכלהו דרין בתראין וכו':","וכל הדורות שאחריהם, כולם נזדמנו שם, וכולם קבלו התורה בהר סיני. שכתוב, כי את אשר ישנו פה וגו' ואת אשר איננו פה עמנו היום. וכולם היו כל אחד ואחד כראוי לו, וכולם רואים, ומקבלים הדברים."],[3,"אלקים דא גבורה וכו':","וידבר אלקים, הנה השם \u0003אלקים,\u0004 הוא גבורה, \u0003את,\u0004 יורה שנכלל בימין. כמו שלמדנו, את השמים הוא ימין ואת הארץ הוא שמאל, שכתוב, אף ידי יסדה ארץ וימיני טפחה שמים, וימין, זה הוא \u0003את.\u0004 דהיינו חסד. \u0003כל,\u0004 בא לכלול כל שאר הספירות. \u0003הדברים,\u0004 יורה שהדברים מתקשרים ונכללים זה בזה, \u0003האלה,\u0004 יורה על כל הטעמים, וכל הסודות, וכל הסתרים, והגזרות והעונשים."],[4,"לאמר, למהוי ירותא וכו':","המלה \u0003לאמר,\u0004 פירושו, להיות ירושה לכל. שכתוב, תורה צוה לנו משה \u0003מורשה\u0004 וגו'. כי אם תאמר כפשוטו, לומר לכל, ולגלות מה שלא נצרך לגלות לכל אדם. הרי כתוב, אנכי ה' אלקיך, יורה, כמו שאני מכוסה וסתים כך יהיו דברים אלו מכוסים וסתומים בלבך."],[5,"ד\"א, וידבר אלקים וגו':","פירוש אחר. וידבר אלקים, הוא מדרגה אחת. את כל הדברים האלה לאמר, הרי חמש מדרגות אחרות. שכל מלה היא מדרגה אחת. ר' יהודה אומר, \u0003וידבר אלקים,\u0004 הוא גבורה. \u0003את,\u0004 הוא ימין דהיינו חסד. \u0003כל,\u0004 זה וזה, חסד וגבורה ביחד. אמר ר' יצחק, כל, כולל את אברהם, שכתוב, וה' ברך את אברהם בכל."],[6,"הדברים, לאכללא וכו':","המלה \u0003הדברים,\u0004 הוא לכלול שאר הכתרים שנתכסו. \u0003האלה,\u0004 לכלול אלו שנתגלו וכתוב, וכל העם רואים את הקולות. שהם המתגלים הנכללים באלה. \u0003לאמר,\u0004 ז\"ש אשת חיל עטרת בעלה, דהיינו, שיורה על השכינה. וכתוב, לאמר הן ישלח איש את אשתו, הרי שהמלה לאמר סמוכה אל אשה. אשר כאן יורה על הנוקבא דז\"א שהיא השכינה."],[7,"אמר ר' יצחק וכו':","אר\"י, למה ניתנה התורה באש וחשך, שכתוב, וההר בוער באש עד לב השמים חשך וענן וערפל. ומשיב, הוא משום, שכל מי שעוסק בתורה ניצל מאש אחרת, של גיהנם, ומחושך שמחשיכים כל שאר העמים לישראל, שבזכותו של אברהם נצולו ישראל מאש של גיהנם."],[8,"דתניא אמר ליה וכו':","שלמדנו, אמר לו הקב\"ה לאברהם כל זמן שבניך יעסקו בתורה יהיו ניצולים מאלו, מאש וחשך, ואם לא, הרי אש של גיהנם שולטת בהם, וישתעבדו בין האומות. אמר לו אברהם, בשני קשרים לא יקומו הדברים, דהיינו אש גיהנם וגלות, אלא אם טוב לפניך, יהיו ניצולים מאש גיהנם וישתעבדו בין העמים עד שישובו אליך. אמר לו הקב\"ה, כן הוא ודאי, זה שכתוב, \u0003אם לא כי צורם מכרם.\u0004 מי הוא צורם. זה הוא אברהם, שכתוב, הביטו אל צור חצבתם. \u0003וה' הסגירם,\u0004 זהו הקב\"ה, שהסכים על ידו."],[9,"אמר ר' יהודה וכו':","אר\"י מיום שיצאו ישראל ממצרים עד יום שניתנה התורה, הם חמשים יום. מה הטעם. אר\"י, משום שהם שנים של יובל, שהוא בינה, שכתוב, וקדשתם את שנת החמשים שנה. דהיינו שער החמשים שבבינה."],[10,"תאנא אמר ר\"ש וכו':","למדנו אר\"ש, יובל ההוא, הוציא את ישראל ממצרים. ואם תאמר יובל ממש, דהיינו בינה בעצמה. לא, אלא מצד יובל היתה היציאה, ומצד יובל נתעורר הדין על המצרים, ומשום זה חמשים שנה אלו הם חמשים שערים של יובל שהיא בינה."],[10,"","פירוש. לא בינה עצמה הוציאה את ישראל ממצרים, אלא שהנוקבא דז\"א עלתה והלבישה את הבינה, ונעשתה כמוה, והוציאה את ישראל ממצרים. וזה נבחן שהוא מצד הבינה ולא בינה ממש."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, כָּל מִלָּה וּמִלָּה הָיְתָה מְלֵאָה בְּכָל אוֹתָם טְעָמִים, בְּכָל אוֹתָם דִּבְרֵי גְזֵרוֹת, שָׂכָר וָעֳנָשִׁים, סוֹדוֹת וּסְתָרִים כְּאוֹצָר (כצנצנת) זֶה שֶׁמָּלֵא מִן הַכֹּל."],[1,"","וּבְשָׁעָה שֶׁהָיָה יוֹצֵא אוֹתוֹ הַדִּבּוּר, נִרְאָה אֶחָד. וּכְשֶׁהָיָה נֶחְקָק בִּמְקוֹמוֹ, נִרְאוּ בְּאוֹתוֹ הַדִּבּוּר שִׁבְעִים עֲנָפִים שֶׁנִּכְנָסִים לְתוֹכָהּ, וַחֲמִשִּׁים כְּתָרִים חָסֵר אֶחָד מִצַּד זֶה, וַחֲמִשִּׁים חָסֵר אֶחָד מִצַּד הָאַחֵר, כְּמוֹ הַפַּטִּישׁ הַזֶּה בִּזְמַן שֶׁהוּא מַכֶּה בְּסֶלַע, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהכג) וּכְפַטִּישׁ יְפוֹצֵץ סָלַע. וְהָיוּ כָּל יִשְׂרָאֵל רוֹאִים עַיִן בְּעַיִן וְהָיוּ שְׂמֵחִים."],[2,"","וְכָל הַדּוֹרוֹת הָאַחֲרוֹנִים הִזְדַּמְּנוּ לְשָׁם, וְכֻלָּם קִבְּלוּ תוֹרָה בְּהַר סִינַי, שֶׁכָּתוּב (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ' וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם. וְכֻלָּם כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכֻלָּם רוֹאִים וּמְקַבְּלִים דְּבָרִים."],[3,"","אֱלֹהִים - זוֹ גְבוּרָה. אֵת - שֶׁנִּכְלָל בַּיָּמִין, כְּמוֹ שֶׁשָּׁנִינוּ אֵת הַשָּׁמַיִם שֶׁהוּא יָמִין, וְאֵת הָאָרֶץ שֶׁהוּא שְׂמֹאל, שֶׁכָּתוּב (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם. וְיָמִין זֶה הוּא אֵת. כָּל - לִכְלֹל אֶת כָּל שְׁאָר הַכְּתָרִים. הַדְּבָרִים - מִתְקַשְּׁרִים זֶה בָּזֶה. הָאֵלֶּה - כָּל אוֹתָם טְעָמִים, כָּל אוֹתָם סוֹדוֹת, כָּל אוֹתָם סְתָרִים, גְּזֵרוֹת וָעֳנָשִׁים."],[4,"","לֵאמֹר - לִהְיוֹת יְרֻשָּׁה לַכֹּל, שֶׁכָּתוּב (דברים לג) תּוֹרָה צִוָּה לָנוּ מֹשֶׁה מוֹרָשָׁה וְגוֹ'. שֶׁאִם תֹּאמַר, לְגַלּוֹת מַה שֶּׁלֹּא הִצְטָרֵךְ לְגַלּוֹת לְכָל אָדָם - כָּתוּב אָנֹכִי ה' אֱלֹהֶיךְ. כְּמוֹ שֶׁאֲנִי טָמִיר וְנִסְתָּר, כָּךְ יִהְיוּ הַדְּבָרִים הַלָּלוּ טְמִירִים וְנִסְתָּרִים בְּלִבְּךְ."],[5,"","דָּבָר אַחֵר וַיְדַבֵּר אֱלֹהִים - אֶחָד. אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר - הֲרֵי חָמֵשׁ דְּרָגוֹת אֲחֵרוֹת. רַבִּי יְהוּדָה אָמַר, וַיְדַבֵּר אֱלֹהִים - גְּבוּרָה. אֵת - יָמִין. כָּל - זֶה וָזֶה (האלה אותם שגתגלו, שכתוב וכל העם ראים את הקולת. דבר אחר, כל). אָמַר רַבִּי יִצְחָק, לִכְלֹל אֶת אַבְרָהָם, שֶׁכָּתוּב וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל."],[6,"","הַדְּבָרִים - לִכְלֹל שְׁאָר הַכְּתָרִים הַמְכֻסִּים. הָאֵלֶּה - אֵלּוּ שֶׁהִתְגַּלּוּ, וְכָתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. לֵאמֹר - זֶהוּ שֶׁכָּתוּב (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ. וְכָתוּב (ירמיה ג) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ."],[7,"","אָמַר רַבִּי יִצְחָק, לָמָּה נִתְּנָה תוֹרָה בְּאֵשׁ וַחֲשֵׁכָה, שֶׁכָּתוּב וְהָהָר בֹּעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם חֹשֶׁךְ עָנָן וַעֲרָפֶל. שֶׁכָּל מִי שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה, יִנָּצֵל מֵאֵשׁ אַחֶרֶת שֶׁל הַגֵּיהִנָּם וּמֵהַחֹשֶׁךְ שֶׁמַּחְשִׁיכִים כָּל שְׁאָר הָעַמִּים לְיִשְׂרָאֵל, שֶׁבִּזְכוּת אַבְרָהָם נִצְּלוּ יִשְׂרָאֵל מֵאֵשׁ הַגֵּיהִנָּם."],[8,"","שֶׁשָּׁנִינוּ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, כָּל זְמַן שֶׁבָּנֶיךְ יִשְׁתַּדְּלוּ בַתּוֹרָה, הֵם יִנָּצְלוּ מֵאֵלֶּה, וְאִם לֹא - הֲרֵי אֵשׁ הַגֵּיהִנָּם תִּשְׁלֹט בָּהֶם וְיִשְׁתַּעְבְּדוּ בֵּין הָעַמִּים. אָמַר לוֹ, בִּשְׁנֵי קְשָׁרִים לֹא יָקוּמוּ הַדְּבָרִים, אֶלָּא אִם נוֹחַ לְפָנֶיךְ - שֶׁיִּנָּצְלוּ מֵאֵשׁ הַגֵּיהִנָּם, וְיִשְׁתַּעְבְּדוּ בֵּין הָעַמִּים עַד שֶׁיָּשׁוּבוּ אֵלֶיךְ. אָמַר לוֹ, יָפֶה זֶה וַדַּאי. זֶהוּ שֶׁכָּתוּב (דברים לב) אִם לֹא כִּי צוּרָם מְכָרָם. מִיהוּ צוּרָם? זֶהוּ אַבְרָהָם, שֶׁכָּתוּב (ירמיה ג) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. וַה' הִסְגִּירָם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִסְכִּים עַל יָדוֹ."],[9,"","אָמַר רַבִּי יְהוּדָה, מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם עַד הַיּוֹם שֶׁנִּתְּנָה בּוֹ תּוֹרָה הָיוּ חֲמִשִּׁים יוֹם, מָה הַטַּעַם? אָמַר רַבִּי יְהוּדָה, מִשּׁוּם אוֹתָן שְׁנוֹת הַיּוֹבֵל, שֶׁכָּתוּב (ויקרא כה) וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה."],[10,"","שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, אוֹתוֹ הַיּוֹבֵל הוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם. וְאִם תֹּאמַר שֶׁיּוֹבֵל מַמָּשׁ, אֶלָּא מִצַּד הַיּוֹבֵל זֶה הָיָה, וּמִצַּד הַיּוֹבֵל הִתְעוֹרֵר דִּין עַל הַמִּצְרִים, וְלָכֵן חֲמִשִּׁים אֵלֶּה הָיוּ שֶׁל הַיּוֹבֵל."]]],[["תָּאנָא, לָקֳבֵל דָּא, חַמְשִׁין זִמְנִין אִתְּמַר וְאַדְכַּר בְּאוֹרַיְיתָא, נִמּוּסִין דְּמִצְרַיִם, וְשְׁבָחֵי אִינּוּן כֻּלְּהוּ, אֲשֶׁר הוֹצֵאתִיךָ. (דברים ד׳:ל״ד) וַיּוֹצִיאֲךָ. (שמות י״ג:ט׳) כִּי בְּיַד חֲזָקָה הוֹצִיאֲךָ. וְכֻלְּהוּ זִמְנֵי, חַמְשִׁין אִינּוּן, וְלָא יַתִּיר, מִשּׁוּם דְּכֹלָּא בְּיוֹבְלָא אִתְעַטָּר, וּמִסִּטְרָא דְּיוֹבְלָא אָתָא כֹּלָּא. וּבְגִינֵי כַּךְ, אוֹרַיְיתָא דְּאָתֵי מִגְּבוּרָה, אִתְעַטְּרָת בִּימִינָא. דִּכְתִּיב, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. וְתַנְיָא חֲמִשָּׁא קָלִין הֲווֹ. וְכֻלְּהוּ אִתְחֲזִיאוּ בְּהוּ, וְאִתְכְּלִילוּ בְּהוּ, וְאִתְעַטְּרוּ בְּדָא.","אָמַר ר' שִׁמְעוֹן, בְּהַהוּא זִמְנָא דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא, יוֹבְלָא דָּא אַעְטַּר בְּעִטְּרוֹי לְקוּדְשָׁא בְּרִיךְ הוּא, כְּמַלְכָּא דְּאִתְעַטָּר בְּגוֹ חֵילֵיהּ. דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ. מַאן אִמּוֹ. דָּא יוֹבְלָא. וְיוֹבְלָא אִתְעַטָּר, בְּחֶדְוָה בִּרְחִימוּ בִּשְׁלִימוּ. דִּכְתִּיב, (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה. מַאן אֵם הַבָּנִים. אָמַר רַבִּי שִׁמְעוֹן דָּא יוֹבְלָא.","אָמַר רִבִּי יְהוּדָה, עַל דָּא כְּתִיב, (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְתָגֵל יוֹלַדְתֶּךָ. מַאן אָבִיךָ וְאִמֶּךָ. אָמַר רִבִּי יְהוּדָה, כְּמָה דְּאוּקְמוּהָ בְּסִפְרָא דִּצְנִיעוּתָא, דִּכְתִּיב, (ויקרא י״ח:ז׳) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמֶּךָ לא תְּגַלֵּה וַוי לְמַאן דְּגַלֵּי עֲרָיַיתְהוֹן.","תָּאנָא, אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי בְּטוּרָא דְּסִינַי, אִזְדַּעְזָע טוּרָא. וּבְשַׁעֲתָא דְּסִינַי אִזְדַּעְזָע, כָּל שְׁאַר טוּרֵי עָלְמָא אִזְדַּעְזְעוּ, וַהֲווּ סַלְּקִין וְנַחְתִּין, עַד דְּאוֹשִׁיט קוּדְשָׁא בְּרִיךְ הוּא יְדוֹי עָלַיְיהוּ, וְאִתְיַשְּׁבוּ. וְקָלָא נָפְקָא וּמַכְרְזָא, (תהילים קי״ד:ה׳-ו׳) מַה לְּךָ הַיָּם כִּי תָנוּס הַיַּרְדֵּן תִּסוֹב לְאָחוֹר הֶהָרִים תִּרְקְדוּ כְאֵילִם וְגוֹ'.","וְאִינּוּן תָּבָאן וְאַמְרִין, מִלְּפָנַי אֲדוֹן חוּלִי אָרֶץ. אָמַר ר' יִצְחָק, מִלְּפָנַי אֲדוֹן, דָּא אִימָא, דִּכְתִּיב אִם הַבָּנִים שְׂמֵחָה. חוּלִי אָרֶץ, דָּא אִימָא תַּתָּאָה. מִלְּפָנַי אֱלוֹהַּ יַעֲקֹב, דָּא הוּא אַבָּא, דִּכְתִּיב, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל. וְעַל הַאי כְּתִיב בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ.","מַהוּ בַּעֲטָרָה. אָמַר רִבִּי יִצְחָק, כְּמָה דִּכְתִּיב, (שמואל א כ״ג:כ״ו) וְשָׁאוּל וַאֲנָשָׁיו עוֹטְרִים אֶת דָּוִד. מִשּׁוּם דְּמִתְעַטָּר, בְּחִוָורָא בְּסוּמָקָא וּבִירוֹקָא, בְּכָל גַּוְונִין דְּכֻלְּהוּ כְּלִילָן בֵּיהּ, וְאִסְתַּחֲרָן בֵּיהּ. אָמַר ר' יְהוּדָה, בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ. מַאן עֲטָּרָה. דִּכְתִּיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. וּכְתִיב (ישעיהו ס׳:ז׳) וּבֵית תִּפְאַרְתִּי אֲפַאֵר.","אָמַר ר' יִצְחָק, אוֹרַיְיתָא אִתְיְהִיבַת בְּאֶשָּׁא אוּכָּמָא, עַל גַּבֵּי אֶשָּׂא חִוָּורָא, לְאַכְלְלָא יְמִינָא בִּשְׂמָאלָא, וּשְׂמָאלָא דְּאִתְחַזָּר יְמִינָא, דִּכְתִיב מִימִינוֹ אֵשׁ דָּת לָמוֹ.","אָמַר רִבִּי אַבָּא, בְּשַׁעֲתָא דִּתְנָנָא דְּסִינַי הֲוָה נָפִיק, סָלִיק אֶשָּׁא, וּמִתְעַטָּר בְּהַהוּא תְּנָנָא בְּאִתְגַּלְּיָיא, כְּאַתְכְּלָא דָּא, וְסָלִיק וְנָחִית, וְכָל רֵיחִין וּבוּסְמִין דִּבְגִנְתָּא דְּעֵדֶן, הֲוָה סָלִיק הַהוּא תְּנָנָא, בְּחֵיזוּ דְּחִוָּור וְסוּמָק וְאוּכָם, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:ו׳) מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל.","הַהוּא תְּנָנָא מַאן הֲוָה. אָמַר ר' יִצְחָק, (נ\"ח ע\"ב) שְׁכִינְתָּא דְּאִתְגְלֵי לְתַמָּן, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ג׳:ו׳) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר כְּתִמְרוֹת עָשָׁן. אָמַר ר' יְהוּדָה, לָמָּה לָךְ כּוּלֵי הַאי הָא קְרָא שְׁלִים הוּא, דִּכְתִּיב וְהַר סִינַי עָשָׁן כֻּלּוֹ מִפְּנִי אֲשֶׁר יָרַד עָלָיו יְיָ' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. זַכָּאָה עַמָּא דְּחָמָאן דָּא, וְיַדְעִין דָּא.","אָמַר רִבִּי חִיָּיא, כַּד אִתְגְּלִיפוּ אַתְוָון בְּלוּחֵי אֲבָנָא, הֲווֹ מִתְחַזְיָין בִּתְרֵין סִטְרִין, מִסִּטְרָא דָּא, וּמִסִּטְרָא דָּא, וְלוּחִין מֵאֶבֶן סַנְפִּירִינוֹן הֲווֹ, וְאִתְגְּלִיפוּ וְאִתְחַפְיָין בְּאֶשָּׁא חִוָּורָא, וְאַתְוָון הֲווֹ מֵאֶשָּׁא אוּכָמָא, וּמִתְגַּלְּפָן בִּתְרֵין סִטְרִין, מִסִּטְרָא דָּא וּמִסִּטְרָא דָּא.","אָמַר ר' אַבָּא, לוּחִין הֲווֹ בְּעֵינַיְיהוּ, וְאַתְוָון הֲווֹ טָאסִין, וּמִתְחַזְיָין בִּתְרֵין אֶשִׁין, אֶשָּׂא חִוָּורָא, וְאֶשָּׁא אוּכָמָא, לְאִתְחֲזָאָה כַּחֲדָא, יְמִינָא וּשְׂמָאלָא, דִּכְתִּיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וְגוֹ'. וְהָא כְּתִיב מִימִינוֹ אֵשׁ דָּת לָמוֹ. אֶלָּא מִסִּטְרָא דִּגְבוּרָה הֲוָה, וְאִתְכְּלִילַת בִּימִינָא. וּבְגִין כַּךְ אֶשָּׂא חִוָּורָא וְאֶשָּׁא אוּכָמָא.","תָּאנָא, כְּתִיב (שמות ל״ב:ט״ז) וְהַלֻּחֹת מַעֲשֵׂה אֱלהִים הֵמָּה וְגו', (מעשה אלהים ודאי) אָמַר רִבִּי יְהוּדָה, וְהַלֻּחֹת כְּתִיב, חַד. תְּרֵי הֲווֹ וּמִתְחַזְיָין חַד. וָעֶשֶׁר אֲמִירָן מִתְגַּלְּפֵי בְּהוּ. חָמֵשׁ כְּלִילָן בְּחָמֵשׁ, לְמֶהֱוֵי כֹּלָּא יְמִינָא. מַעֲשֵׂה אֱלהִים הֵמָּה וַדַּאי."],[[0,"תאנא לקבל דא וכו':","למדנו, כנגד זה חמשים פעמים נאמר ונזכר בתורה המעשים של מצרים, וכולם שבחים הם, דהיינו אשר הוצאתיך מארץ מצרים, ויוציאך ה' משם. כי ביד חזקה הוציאך ה' מארץ מצרים. וכו'. וכולם הם חמשים פעמים ולא יותר משום שהכל נעטר ביובל, שהוא בינה, ומצד היובל בא הכל. ובבינה יש חמשים שערים. ומשום זה התורה הבאה מגבורה נעטרה בימין, שכתוב מימינו אש דת למו. ולמדנו חמשה קולות היו במתן תורה, כנגד חג\"ת נ\"ה דבינה, וכולם נראים בהם ונכללו בהם. ונתעטרו בזה, בבינה."],[1,"אמר ר' שמעון וכו':","אר\"ש, בזמן ההוא שקבלו ישראל את התורה, יובל זה, שהיא בינה, העטיר בעטרות שלו להקב\"ה, שהוא ז\"א, כמלך המתעטר בתוך צבאיו. שכתוב, צאנה וראנה בנות ציון במלך שלמה בעטרה שעטרה לו אמו. מי אמו. זה הוא יובל. כי בינה הנקראת יובל היא אמא של ז\"א, שנקרא שלמה. והיובל נתעטר בשמחה באהבה ובשלימות, שכתוב, אם הבנים שמחה. מי היא אם הבנים. א\"ר שמעון, זה היא יובל."],[2,"א\"ר יהודה וכו':","אר\"י, על כן כתוב, ישמח אביך ואמך ותגל יולדתך. מי הם אביך ואמך. אר\"י, הם כמו שבארוה בספרא דצניעותא שכתוב ערות אביך וערות אמך לא תגלה. אוי למי שמגלה ערותם. שה\"ס חכמה ובינה המכונים או\"א. (כמ\"ש שם, תרומה קע\"ז ע\"ב דפו\"י)."],[3,"תאנא א\"ר יצחק וכו':","למדנו, אר\"י, בשעה שנתגלה הקב\"ה על הר סיני נזדעזע ההר, ובשעה שסיני נזדעזע נזדעזעו כל שאר הרי העולם, והיו עולים ויורדים עד שהושיט הקב\"ה את ידו עליהם והתישבו. וקול יוצא ומכריז, מה לך הים כי תנוס הירדן תסוב לאחור ההרים תרקדו כאילם וגו'."],[4,"ואינון תבאן ואמרין וכו':","והם משיבים ואומרים, מלפני אדון חולי ארץ. א\"ר יצחק, \u0003מלפני אדון,\u0004 זה הוא אמא, שהיא בינה. שכתוב, אם הבנים שמחה. \u0003חולי ארץ,\u0004 זו היא אמא תחתונה, שהיא מלכות. \u0003מלפני אלקי יעקב,\u0004 זה הוא אבא, שהוא ז\"א, אבא תתאה, שכתוב בני בכרי ישראל, דהיינו ז\"א שנקרא ישראל. ועל זה כתוב, בעטרה שעטרה לו אמו, שהיא בינה."],[5,"מהו בעטרה וכו':","שואל, מהו בעטרה שעטרה לו. א\"ר יצחק, כמו שכתוב, ושאול ואנשיו עוטרים את דוד. שהוא לשון מסבבים. משום שז\"א מתעטר ומסובב על ידי אמא בלבן אדום וירוק בכל הצבעים שה\"ס ג' קוים, שכולם כלולים בו ומסבבים בתוכו. אמר ר' יהודה, \u0003בעטרה שעטרה לו אמו,\u0004 מהו עטרה. היינו שכתוב, ישראל אשר בך אתפאר. וכתוב, ובית תפארתי אפאר. דהיינו הג\"ר, שהם פאר של ז\"א הנקרא ישראל. ונקרא תפארת."],[6,"אמר ר' יצחק וכו':","אר\"י, התורה ניתנה באש שחורה על אש לבנה, לכלול הימין בשמאל והשמאל שהוחזר לימין, שכתוב, מימינו אש דת למו."],[7,"אמר ר' אבא וכו':","אר\"א, בשעה שעשן הסיני היה יוצא, עלתה האש והתעטרה בעשן ההוא בגלוי, והיתה נראית כאשכול הזה. ועלתה וירדה. וכל הריחות והבשמים שבגן עדן, היה מעלה עשן ההוא, במראה של לבן ואדום ושחור, ז\"ש, מקטרת מר ולבונה מכל אבקת רוכל."],[8,"ההוא תננא מאן וכו':","עשן זה מי היה. א\"ר יצחק, הוא, השכינה שנתגלתה לשם. כש\"א, מי זאת עולה מן המדבר כתמרות עשן. שסובב על השכינה. א\"ר יהודה, למה לך כל כך, הרי מקרא שלם הוא, שכתוב, והר סיני עשן כולו מפני אשר ירד עליו ה' באש ויעל עשנו כעשן הכבשן. אשרי העם שראו את זה ויודעים את זה."],[9,"אמר ר' חייא וכו':","אר\"ח, כשנחקקו האותיות בלוחות האבן, היו נראות משני הצדדים, מצד זה ומצד זה. והלוחות מאבן ספיר היו, ונחקקו ונתכסו באש לבנה, והאותיות היו מאש שחורה, ונחקקו משני הצדדים מצד זה ומצד זה."],[10,"אמר ר' אבא וכו':","אר\"א, הלוחות היו בעינם, דהיינו בשלימות בלי שינוי, והאותיות היו פורחות ונראות בשתי מיני אש, אש לבנה ואש שחורה, כדי להראות יחד ימין ושמאל, שלבן הוא ימין ושחור הוא שמאל. שכתוב, ארך ימים בימינה בשמאלה וגו'. שואל הרי כתוב, מימינו אש דת למו. ומשיב, אלא מצד הגבורה היתה, שהוא שמאל ונכללה בימין. ומשום זה היתה בה, אש לבנה ואש שחורה."],[11,"תאנא כתיב וכו':","למדנו, כתוב, והלוחות מעשה אלקים המה וגו'. אמר ר' יהודה, והלוחת כתוב, חסר ו', דהיינו אחד, שנים היו ונראו כאחד. ועשרה דברות נחקקו בהם. חמשה כלולים בחמשה, כדי שיהיה הכל ימין. מעשה אלקים המה ודאי."]],[[0,"","שָׁנִינוּ, כְּנֶגֶד זֶה חֲמִשִּׁים פְּעָמִים נֶאֱמַר וְנִזְכַּר בַּתּוֹרָה הַנְהָגוֹת מִצְרַיִם, וְכֻלָּם הֵם שְׁבָחִים: אֲשֶׁר הוֹצֵאתִיךְ. וַיֹּצִאֲךְ. כִּי בְּיָד חֲזָקָה הוֹצִיאֲךְ. וְכָל הַפְּעָמִים הֵם חֲמִשִּׁים, וְלֹא יוֹתֵר. מִשּׁוּם שֶׁהַכֹּל הִתְעַטֵּר בַּיּוֹבֵל. וּמִצַּד הַיּוֹבֵל הַכֹּל בָּא. וְלָכֵן תּוֹרָה שֶׁבָּאָה מִגְּבוּרָה הִתְעַטְּרָה בַּיָּמִין, שֶׁכָּתוּב (דברים לג) כִּי מִימִינוֹ אֵשׁ דָּת לָמוֹ. וְשָׁנִינוּ, חֲמִשָּׁה קוֹלוֹת הָיוּ, וְכֻלָּם נִרְאוּ בָהֶם וְנִכְלְלוּ בָהֶם וְהִתְעַטְּרוּ בָזֶה."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתוֹ זְמַן שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, הַיּוֹבֵל הַזֶּה עִטֵּר בְּעַטְרוֹתָיו אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמֶלֶךְ שֶׁהִתְעַטֵּר בְּתוֹךְ חֵילוֹ, שֶׁכָּתוּב (שירג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. מִי זוֹ אִמּוֹ? זֶה הַיּוֹבֵל, וְהַיּוֹבֵל הִתְעַטֵּר בְּשִׂמְחָה בְּאַהֲבָה בִּשְׁלֵמוּת, שֶׁכָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה. מִי זוֹ אֵם הַבָּנִים? אָמַר רַבִּי שִׁמְעוֹן, זֶה הַיּוֹבֵל."],[2,"","אָמַר רַבִּי יְהוּדָה, עַל זֶה כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ. מִי זֶה אָבִיךְ וְאִמֶּךְ? אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁבֵּאֲרוּהָ בְּסִפְרָא דִצְנִיעוּתָא, שֶׁכָּתוּב עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. אוֹי לְמִי שֶׁמְּגַלֶּה עֶרְוָתָם."],[3,"","שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה בְּהַר סִינַי, הִזְדַּעֲזַע הָהָר, וּבְשָׁעָה שֶׁסִּינַי הִזְדַּעֲזַע, כָּל שְׁאָר הָרֵי הָעוֹלָם הִזְדַּעְזְעוּ וְהָיוּ עוֹלִים וְיוֹרְדִים, עַד שֶׁהוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא יָדוֹ עֲלֵיהֶם וְהִתְיַשְּׁבוּ, וְקוֹל יוֹצֵא וּמַכְרִיז, (תהלים קיד) מַה לְּךְ הַיָּם כִּי תָנוּס הַיַּרְדֵּן תִּסֹּב לְאָחוֹר, הֶהָרִים תִּרְקְדוּ כְאֵילִים וְגוֹ'."],[4,"","וְהֵם שָׁבִים וְאוֹמְרִים, מִלִּפְנֵי אָדוֹן חוּלִי אָרֶץ. אָמַר רַבִּי יִצְחָק, מִלִּפְנֵי אָדוֹן - זוֹ הָאֵם, שֶׁכָּתוּב אֵם הַבָּנִים שְׂמֵחָה. חוּלִי אָרֶץ - זוֹ הָאֵם הַתַּחְתּוֹנָה. מִלִּפְנֵי אֱלוֹהַּ יַעֲקֹב - זֶהוּ הָאָב, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. וְעַל זֶה כָּתוּב בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ."],[5,"","מַה זֶּה בָּעֲטָרָה? אָמַר רַבִּי יִצְחָק, כַּכָּתוּב (שמואל א כג) וְשָׁאוּל וַאֲנָשָׁיו עֹטְרִים אֶל דָּוִד. מִשּׁוּם שֶׁמִּתְעַטֵּר בְּלָבָן וּבְאָדם וּבְיָרֹק, בְּכָל הַגְּוָנִים שֶׁכֻּלָּם כְּלוּלִים בּוֹ וּמֻקָּפִים בּוֹ. אָמַר רַבִּי יְהוּדָה, בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ, מִי זוֹ הָעֲטָרָה? שֶׁכָּתוּב (ישעיהמט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, וְכָתוּב (שםס) וּבֵית תִּפְאַרְתִּי אֲפָאֵר."],[6,"","אָמַר רַבִּי יִצְחָק, תּוֹרָה נִתְּנָה בְּאֵשׁ שְׁחֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה, לִכְלֹל יָמִין בִּשְׂמֹאל, וּשְׂמֹאל שֶׁחוֹזֵר לִהְיוֹת יָמִין, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ."],[7,"","אָמַר רַבִּי אַבָּא, בְּשָׁעָה שֶׁעָשָׁן שֶׁל סִינַי הָיָה יוֹצֵא, עוֹלֶה אֵשׁ, וּמִתְעַטֵּר בְּאוֹתוֹ עָשָׁן בְּגָלוּי כְּאֶשְׁכּוֹל הַזֶּה, וְעוֹלֶה וְיוֹרֵד, וְכָל הָרֵיחוֹת וְהַבְּשָׂמִים שֶׁל גַּן עֵדֶן הָיָה מַעֲלֶה אוֹתוֹ עָשָׁן בְּמַרְאֶה שֶׁל לָבָן וְאָדם וְשָׁחֹר. זֶהוּ שֶׁכָּתוּב (שיר ג) מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל."],[8,"","אוֹתוֹ עָשָׁן מֶה הָיָה? אָמַר רַבִּי יִצְחָק, שְׁכִינָה שֶׁנִּגְלְתָה לְשָׁם, שֶׁנֶּאֱמַר מִי זאת עֹלָה מִן הַמִּדְבָּר כְּתִמְרוֹת עָשָׁן. אָמַר רַבִּי יְהוּדָה, לָמָּה לָךְ כָּל זֶה, הֲרֵי פָּסוּק שָׁלֵם הוּא, שֶׁכָּתוּב וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. אַשְׁרֵי הָעָם שֶׁרָאוּ אֶת זֶה וְיָדְעוּ אֶת זֶה."],[9,"","אָמַר רַבִּי חִיָּיא, כְּשֶׁנֶּחְקְקוּ הָאוֹתִיּוֹת בְּלוּחוֹת הָאֶבֶן, הָיוּ נִרְאִים מִשְּׁנֵי צְדָדִים - מִצַּד זֶה וּמִצַּד זֶה, וְהַלּוּחוֹת הָיוּ מֵאֶבֶן סַנְפִּירִינוֹן, וְנֶחְקְקוּ וְנִתְכַּסּוּ בְּאֵשׁ לְבָנָה, וְהָאוֹתִיּוֹת הָיוּ מֵאֵשׁ שְׁחֹרָה, וַחֲקוּקִים בִּשְׁנֵי צְדָדִים - מִצַּד זֶה וּמִצַּד זֶה."],[10,"","אָמַר רַבִּי אַבָּא, הַלּוּחוֹת הָיוּ בְּעֵינֵיהֶם, וְהָאוֹתִיּוֹת הָיוּ טָסוֹת וְנִרְאוֹת בִּשְׁנֵי סוּגֵי אֵשׁ - אֵשׁ לְבָנָה וְאֵשׁ שְׁחֹרָה, לְהֵרָאוֹת כְּאֶחָד יָמִין וּשְׂמֹאל, שֶׁכָּתוּב (משליג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וְגוֹ'. וַהֲרֵי כָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ. אֶלָּא מִצַּד הַגְּבוּרָה זֶה הָיָה, וְנִכְלֶלֶת בַּיָּמִין. וְלָכֵן אֵשׁ לְבָנָה וְאֵשׁ שְׁחֹרָה."],[11,"","שָׁנִינוּ, כָּתוּב (שמות לב) וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְגוֹ'. (מעשה אלהים ודאי) אָמַר רַבִּי יְהוּדָה, כָּתוּב וְהַלֻּחֹת, אֶחָד. שְׁנַיִם הָיוּ וְנִרְאִים אֶחָד. וְעֶשֶׂר אֲמִירוֹת חֲקוּקוֹת בָּהֶם, חָמֵשׁ כְּלוּלוֹת בְּחָמֵשׁ, לִהְיוֹת הַכֹּל יָמִין. מַעֲשֵׂה אֱלֹהִים הֵמָּה וַדַּאי."]]],[["רַבִּי יִצְחָק אָמַר, שֶׁל סַנְפִּירִינוֹן הָווֹ, וּתְרֵין אַבְנִין הֲווֹ. וְאַבְנִין הֲווֹ סְתִימָאן. נָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא בְּרוּחָא, וְאִתְפָּשָׁטוּ וְאִתְגְּלִיפוּ תְּרֵין לוּחִין. ר' יְהוּדָה אָמַר, כְּעֵין סַנְפִּירִינוֹן הֲווֹ. (דהוה אבן טבא) מַשְׁמַע דִּכְתִּיב מַעֲשֵׂה אֱלֹהִים הֵמָּה.","אָמַר לֵיהּ, אִי הָכִי, סַנְפִּירִינוֹן דָּא דְּהוּא אַבְנָא טָבָא יַקִּירָא מִשְּׁאָר אַבְנִין, לָאו עוֹבָדָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן. אֲמַר לֵיהּ, בְּמַאי אוֹקִימְנָא מַעֲשֵׂה אֱלֹהִים הֵמָּה. הֵמָּה דַּיְיקָא. אֶלָּא תָּא חֲזֵי, כְּתִיב וְהַלֻּחֹת מַעֲשֵׂה אֱלהִים. הַלֻּחֹת כְּתִיב, וְלָא כְּתִיב וְהָאֲבָנִים מַעֲשֵׂה אֱלֹהִים הֵמָּה.","אָמַר ר' שִׁמְעוֹן, כֹּלָּא חַד הוּא, אֲבָל אִלֵּין תְּרֵין לוּחִין עַד לָא אִתְבְּרֵי עָלְמָא הֲווֹ, וְאִסְתָּלָּקוּ מֵעֶרֶב שַׁבָּת, וְעָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְעוֹבָדוֹי הֲווֹ.","מִמַּה אִתְעָבִידוּ. תָּאנָא, מֵהַהוּא טַלָּא עִלָּאָה, דְּנָגִיד מֵעַתִּיקָא קַדִּישָׁא. וְכַד נָגִיד וְאִתְמְשַׁךְ לַחֲקַל דְּתַפּוּחִין קַדִּישִׁין, נָטַל קוּדְשָׁא בְּרִיךְ הוּא תְּרֵין כִּפּוֹרֵי מִנַּיְיהוּ, וְאִתְגְּלִידוּ, וְאִתְעָבִידוּ תְּרֵין אַבְנִין יַקִּירִין. נָשַׁב בְּהוּ, וְאִתְפָּשָׁטוּ לִתְרֵין לוּחִין, הֲדָא הוּא דִכְתִיב מַעֲשֵׂה אֱלהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא. כְּמָה דִּכְתִּיב, (דברים ט׳:י׳) כְּתוּבִים בְּאֶצְבַּע אֱלהִים.","תָּאנָא, אֶצְבַּע אֱלֹהִים. הַהוּא אֶצְבַּע סָלִיק לַעֲשָׂרָה. כְּמָה דְּאִתְּמַר, אֶצְבַּע אֱלהִים הִיא. וְכָל אֶצְבַּע וְאֶצְבַּע סָלִיק לַעֲשָׂרָה, עַד דְּאִתְעָבִיד יְדָא שְׁלֵימָתָא, דִּכְתִּיב, (שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה.","אָמַר ר' יְהוּדָה, חָרוּת עַל הַלֻּחֹת, נְקִיבָן הֲווֹ אַבְנִין, וְאִתְחֲזִיאוּ לִתְרֵין סִטְרִין, חָרוּת גִּלּוּפָא דִּגְלִיפִין. אָמַר ר' אַבָּא, מֵהַאי סִטְרָא אִתְחָזֵי סִטְרָא אַחֲרָא, וְאִתְקְרֵי מֵהָכָא, מַה דִּכְתִּיב בְּסִטְרָא אַחֲרָא.","רַבִּי אֶלְעָזָר אָמַר, בְּנִס הֲווֹ כְּתִיבִין, דְּכָל בְּנִי נָשָׁא, הֲווֹ אַמְרִין וְסָהֲדִין, דְּהָא מִכְתַּב אֱלהִים הוּא וַדַּאי, דְּהָא כָּל בְּנֵי עָלְמָא לָא יַכְלִין לְמִנְדַּע לוֹן כְּמָה דַּהֲווֹ.","לְדַעְתַּיְיהוּ דְּאִינּוּן דְּאַמְרִין, נְקִיבִין הֲווֹ, מִי כְּתִיב חָרוּת בַּלֻּחֹת, עַל הַלֻּחֹת כְּתִיב. אֶלָּא הָכִי תָּאנָא, חֲמִשָּׁא קָלִין אִינּוּן לִימִינָא, וְחַמְשָׁא לִשְׂמָאלָא. וְאִינּוּן דִּשְׂמָאלָא כְּלִילָן בִּימִינָא. וּמִן יְמִינָא, אִתְחָזוּן אִינּוּן דִּשְׂמָאלָא, וְהָכָא כֹּלָּא אִיהוּ יְמִינָא, וְאִתְכְּלִילָן אִלֵּין בְּאִלֵּין, מַאן דְּהֲוָה בְּסִטְרָא דָּא, חָמֵי לְסִטְרָא אַחֲרָא, וְקָרֵי לוֹן לְאִינוּן אַתְוָון. דְּהָא תָּנֵינָן, שְׂמָאלָא אִתְחֲזָר יְמִינָא, דִּכְתִּיב מִימִינוֹ אֵשׁ דָּת לָמוֹ, וּבְגִין כַּךְ מִכְתַּב אֱלֹהִים הוּא וַדַּאי.","הָא כֵּיצַד, מַאן דְּהֲוָה מִסִּטְרָא דָּא, הֲוָה קָרֵי בְּדָא, אָנֹכִי יְיָ' אֱלֹהֶיךָ. וּמֵאִלֵּין אַתְוָון הֲוָה חָמֵי, וְקָרֵי לא תִּרְצַח. הֲוָה קָרֵי לא יִהְיֶה לְךָ. וַהֲוָה חָמֵי וְקָרֵי, לֹא תִּנְאַף. וַהֲוָה קָרֵי לֹא תִשָּׂא אֶת שֵׁם יְיָ' אֱלֹהֶיךָ לַשָּׁוְא. וַהֲוָה חָמֵי וְקָרֵי לא תִּגְנֹב. וְכֹלָּא מִסִּטְרָא דָּא, וְכָךְ לְכֻלְּהוּ, וּכְדֵין מִסִּטְרָא אַחֲרָא, וְכֻלְּהוּ כְּלִילָן דָּא בְּדָא כְּהַאי גַּוְונָא. הֲדָא הוּא דִכְתִיב, (שמות ל״ב:ט״ז) מִכְתַּב אֱלהִים הוּא. מִכְתַּב אֱלֹהִים הוּא וַדַּאי.","וַיֵּרֶד מֹשֶׁה אֶל הָעָם וַיֹּאמֶר אֲלֵיהֶם. רַבִּי יוֹסֵי אָמַר, מַאי אֲמִירָא דָּא דִּכְתִּיב וַיֹּאמֶר אֲלֵיהֶם, וְלָא כְּתִיב מַאי קָאָמַר. אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, אָרְחָא דְּעָלְמָא הוּא, כַּד אָתֵי חֶדְוָותָא לְבַר נָשׁ, אוֹ כַּד אָתֵי צַעֲרָא, עַד לָא יָדַע מִנֵּיהּ לָא יָכִיל לְמִסְבַּל, דְּהָא לִבָּא אִתְפְּרַח לְשַׁעֲתָא. וְכַד יָדַע מִנֵּיהּ, קָאִים בְּקִיוּמֵיהּ, וְיָכִיל לְמִסְבַּל. כָּל שֶׁכֵּן הָכָא, (נ\"א והכא לאו הכי) דְּהָא מֹשֶׁה אָמַר לוֹן כָּל מַה דְּהֲוָה לְבָתַר, וְאַתְקִיף לִבַּיְיהוּ בְּמִלִּין, וְלָא יָכִילוּ לְמִסְבַּל. כָּל שֶׁכֵּן אִי לָא אָמַר לוֹן מִידִי. וּבְּגִין כָּךְ וַיֹּאמֶר אֲלֵיהֶם בְּקַדְמִיתָא, וְאִתְתָּקַּף לִבַּיְיהוּ. וּלְבָתַר וַיְדַבֵּר אֱלהִים.","וְעִם כָּל דָּא, לָא יָכִילוּ לְמִסְבַּל, דְּהָא תָּנֵינָן, אָמַר ר' יְהוּדָה אָמַר ר' חִיָּיא אָמַר ר' יוֹסֵי, כַּד שָׁמְעוּ מִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא, פַּרְחַת נִשְׁמָתַיְיהוּ, וְסַלְּקָא נִשְׁמָתַיְיהוּ דְּיִשְׂרָאֵל, עַד כּוּרְסֵי יְקָרָא דִּילֵיהּ, לְאִתְדַּבְּקָא תַּמָּן."],[[0,"ר' יצחק אמר וכו':","רי\"א, של ספיר היו, ושני אבנים היו, והאבנים היו סתומים, נפח הקדוש ברוך הוא ברוח, ונתפשטו ונחקקו ב' לוחות. ר' יהודה אמר, כעין ספיר היו, ולא ספיר ממש, זה משמע משכתוב, מעשה אלקים המה. ואם היו אבן ספיר הרי הם כשאר אבנים טובות, ולא מעשה אלקים."],[1,"אמר ליה אי וכו':","א\"ל א\"כ, ספיר זה שהוא אבן טוב יקר משאר האבנים, אינו מעשה אלקים, והלא כל הבריאה היא מעשה אלקים. אמר לו במה אנו מבארים הכתוב מעשה אלקים המה, המה בדיוק, שהם מעשה אלקים ביחוד, ואינם נכללים במעשי הבריאה. אלא בוא וראה, כתוב והלוחת מעשה אלקים, הלוחת כתוב, ולא כתוב, והאבנים מעשה אלקים המה. אלא שנפח באבנים ונתפשטו ונחקקו שני לוחות כנ\"ל. והאבנים עצמם היו אבן ספיר ממש."],[2,"אמר ר' שמעון וכו':","אר\"ש, הכל הוא אחד. שדברי ר' יצחק ודברי ר' יהודה הולכים אל מקום אחד. אבל אלו שני לוחות, היו עד שלא נברא העולם ועלו מערב שבת, ועשה אותם הקב\"ה, ומעשיו היו."],[3,"ממה אתעבידו וכו':","שואל, ממה נעשו הלוחות. ומשיב, למדנו, מטל העליון ההוא הנמשך מעתיקא קדישא, שהוא הכתר, וכשנוזל ונמשך לשדה תפוחים הקדושים, שהיא המלכות, לקח הקב\"ה שתי כוסות מהם ונקפאו ונעשו שתי אבנים יקרות. נפח בהם, ונתפשטו לשני לוחות ז\"ש מעשה אלקים המה והמכתב מכתב אלקים. כמ\"ש כתובים באצבע אלקים."],[4,"תאנא אצבע אלקים וכו':","למדנו, אצבע אלקים. הנה אצבע ההוא עולה לעשרה. כי עשר אצבעות הן עשר ספירות, וכלולות זה מזה ויש בכל אצבע עשר ספירות. כמו שלמדנו, אצבע אלקים היא. וכל אצבע ואצבע עולה לעשר, עד שנעשו יד שלם, שכתוב, וירא ישראל את היד הגדולה. אף כאן אצבע אלקים עולה לעשר."],[5,"אמר ר' יהודה וכו':","אר\"י, חרות על הלחת, נקובים היו כתב האבנים מעבר לעבר, והכתב נראה משני הצדדים. \u0003חרות,\u0004 פירושו, חקיקת החקיקות, דהיינו מעבר לעבר. אמר ר' אבא מצד הזה נראה צד האחר, ונקרא מכאן, מה שכתוב בצד האחר."],[6,"ר' אלעזר אמר וכו':","רא\"א, בנס היו כתובים, שכל בני אדם היו אומרים ומעידים שהוא מכתב אלקים ודאי, כי כל בני העולם לא יכלו לדעת אותם כמו שהיו."],[7,"לדעתייהו דאינון דאמרין וכו':","שואל, לדעתם של אלו האומרים שהיו נקובים מעבר לעבר, מי כתוב, חרות בלוחות, חרות על הלוחות כתוב. ולא מעבר לעבר. ומשיב, אלא כך למדנו, חמשה קולות הם לימין.וחמשה לשמאל, ואלו של השמאל כלולים בימין, ומן הימין היו נראים אלו שבשמאל. וכאן, בלוחות, הכל הוא ימין שנכללו אלו ה' הדברות שבשמאל באלו שבימין. וע\"כ מה שהיה בצד זה רואה לצד האחר וקורא אלו האותיות. באופן, שזה הנס הנאמר בלוחות שקורא מצד זה מה שכתוב בצד זה אינו נאמר על פנים ואחור של הלוחות, אלא על ימין ושמאל שבהם, כי לא היו חרותים מעבר לעבר. כי למדנו, השמאל חזר לימין, שכתוב, מימינו אש דת למו. ומשום זה מכתב אלקים הוא ודאי."],[8,"הא כיצד, מאן וכו':","ומפרש. איך זה היה מי שהיה מצד זה היה קורא אנכי ה' אלקיך, ומאלו האותיות היה רואה וקורא לא תרצח, היה קורא לא יהיה לך, והיה רואה וקורא לא תנאף, והיה קורא לא תשא את שם ה' אלקיך לשוא, והיה רואה וקורא לא תגנוב. והכל מצד זה שבימין, וכך לכולם כן מצד האחר, וכולם כלולים זה בזה כאופן הזה. ז\"ש מכתב אלקים הוא. מכתב אלקים הוא ודאי."],[9,"וירד משה אל העם ויאמר אליהם:","ר' יוסי אמר, מהו אמירה הזו שכתוב, ויאמר אליהם, ולא כתוב מה שאמר. א\"ר יצחק בוא וראה, דרך העולם הוא, כשבא שמחה לאדם, או כשבא צער, בטרם שיבין אותו אינו יכול לסבול, כי לבו פורח ממנו מיד, וכשמבין ויודע אותו, הוא עומד בקיומו ויכול לסבול. כל שכן כאן, שמשה אמר להם מה שיהיה לאחר כך וחיזק לבם בדברים, ועם זה לא יכלו לסבול, כל שכן אם לא היה אמר להם כלום. ומשום זה, \u0003ויאמר אליהם\u0004 מתחילה, וחיזק את לבם, ואח\"כ \u0003וידבר\u0004 אלקים."],[10,"ועם כל דא וכו':","ועם כל זה, לא יכלו לסבול. כי למדנו, א\"ר יהודה אמר ר' חייא אמר ר' יוסי, כששמעו מלה של הקב\"ה, פרחה נשמתם, ועלו נשמות ישראל עד כסא הכבוד שלו להתדבק שם."]],[[0,"","רַבִּי יִצְחָק אָמַר, שֶׁל סַנְפִּירִינוֹן הָיוּ, וּשְׁתֵּי אֲבָנִים הָיוּ, וְהָאֲבָנִים הָיוּ סְתוּמוֹת. נָשַׁב הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרוּחַ, וְהִתְפַּשְּׁטוּ וְנֶחְקְקוּ שְׁנֵי לוּחוֹת. רַבִּי יְהוּדָה אָמַר, כְּעֵין סַנְפִּירִינוֹן הָיוּ, (שהיתה אבן טובה) מַשְׁמָע שֶׁכָּתוּב מַעֲשֵׂה אֱלֹהִים הֵמָּה."],[1,"","אָמַר לוֹ, אִם כָּךְ, סַנְפִּירִינוֹן זֶה, שֶׁהִיא אֶבֶן טוֹבָה וּכְבֵדָה מִשְּׁאָר הָאֲבָנִים, אֵינָם מַעֲשֵׂה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? אָמַר לוֹ, בַּמֶּה בֵּאַרְנוּ מַעֲשֵׂה אֱלֹהִים הֵמָּה? הֵמָּה דַּוְקָא. אֶלָּא בֹּא וּרְאֵה, כָּתוּב וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים. הַלֻּחֹת כָּתוּב, וְלֹא כָתוּב וְהָאֲבָנִים מַעֲשֵׂה אֱלֹהִים הֵמָּה."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל אֶחָד הוּא, אֲבָל שְׁנֵי הַלּוּחוֹת הַלָּלוּ, עַד שֶׁלֹּא נִבְרָא הָעוֹלָם הָיוּ, וְנִתְעַלּוּ מֵעֶרֶב שַׁבָּת, וְעָשָׂה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַעֲשָׂיו הָיוּ."],[3,"","מִמָּה הֵם נַעֲשׂוּ? שָׁנִינוּ, מֵאוֹתוֹ הַטַּל הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ מִן הָעַתִּיק הַקָּדוֹשׁ. וּכְשֶׁשּׁוֹפֵעַ וְנִמְשָׁךְ לִשְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁתֵּי טִפּוֹת כְּפוֹר מֵהֶם וְנִגְלְדוּ, וְנַעֲשׂוּ שְׁתֵּי אֲבָנִים יְקָרוֹת. נָשַׁב בָּהֶן, וְהִתְפַּשְּׁטוּ לִשְׁנֵי לוּחוֹת. זֶהוּ שֶׁכָּתוּב מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא, כְּמוֹ שֶׁכָּתוּב (שמות לב) כְּתוּבִים בְּאֶצְבַּע אֱלֹהִים."],[4,"","שָׁנִינוּ, אֶצְבַּע אֱלֹהִים - אוֹתָהּ אֶצְבַּע עוֹלָה לַעֲשָׂרָה, כְּמוֹ שֶׁנֶּאֱמַר אֶצְבַּע אֱלֹהִים הִיא. וְכָל אֶצְבַּע וְאֶצְבַּע עוֹלָה לַעֲשָׂרָה, עַד שֶׁנַּעֲשֵׂית יָד שְׁלֵמָה, שֶׁכָּתוּב (שמות יד) וירא ישראל את היד הגדלה."],[5,"","אָמַר רַבִּי יְהוּדָה, חָרוּת עַל הַלֻּחֹת - נְקוּבִים הָיוּ הָאֲבָנִים וְנִרְאוּ מִשְּׁנֵי צְדָדִים, חָרוּת חֲקִיקָה שֶׁל חֲקִיקוֹת. אָמַר רַבִּי אַבָּא, מִצַּד זֶה נִרְאֶה הַצַּד הָאַחֵר, וְנִקְרָא מִכָּאן מַה שֶּׁכָּתוּב בַּצַּד הָאַחֵר."],[6,"","רַבִּי אֶלְעָזָר אָמַר, בְּנֵס הָיוּ כְתוּבִים, שֶׁכָּל בְּנֵי הָאָדָם הָיוּ אוֹמְרִים וּמְעִידִים שֶׁהֲרֵי מִכְתַּב אֱלֹהִים הוּא וַדַּאי, שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם לֹא יָכְלוּ לָדַעַת אוֹתָם כְּמוֹ שֶׁהָיוּ."],[7,"","לְדַעִִתָּם שֶׁל הָאוֹמְרִים נְקוּבִים הָיוּ, הַאִם כָּתוּב חָרוּת בַּלֻּחֹת? עַל הַלֻּחֹת כָּתוּב. אֶלָּא כָּךְ שָׁנִינוּ, חֲמִשָּׁה קוֹלוֹת הֵם לְיָמִין וַחֲמִשָּׁה לִשְׂמֹאל, וְאוֹתָם שֶׁל הַשְּׂמֹאל כְּלוּלִים בַּיָּמִין. וּמֵהַיָּמִין נִרְאוּ אוֹתָם שֶׁבַּשְּׂמֹאל, וְכָאן הַכֹּל הוּא יָמִין, וְנִכְלְלוּ אֵלֶּה בְּאֵלֶּה, מַה שֶּׁהָיָה בְּצַד זֶה נִרְאֶה לַצַּד הָאַחֵר, וְקוֹרְאִים אֶת אוֹתָם הָאוֹתִיּוֹת. שֶׁהֲרֵי שָׁנִינוּ, הַשְּׂמֹאל הָפַךְ לִהְיוֹת יָמִין, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ, וּמִשּׁוּם כָּךְ מִכְתַּב אֱלֹהִים הוּא וַדַּאי."],[8,"","הָכֵיצַד, ? מַה שֶּׁהָיָה בַּצַּד הַזֶּה הָיָה קוֹרֵא בָּזֶה, אָנֹכִי ה' אֱלֹהֶיךְ. וּמֵהָאוֹתִיּוֹת הַלָּלוּ הָיָה רוֹאֶה וְקוֹרֵא לֹא תִרְצַח. הָיָה קוֹרֵא לֹא יִהְיֶה לְךְ, וְהָיָה רוֹאֶה וְקוֹרֵא לֹא תִנְאָף. וְהָיָה קוֹרֵא לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא. וְהָיָה רוֹאֶה וְקוֹרֵא לֹא תִגְנֹב. וְהַכֹּל מִצַּד זֶה. וְכָךְ לְכֻלָּם, וְאָז מִצַּד הָאַחֵר, וְכֻלָּם כְּלוּלִים זֶה בָּזֶה כְּגוֹן זֶה. זֶהוּ שֶׁכָּתוּב (שםלג) מִכְתַּב אֱלֹהִים הוּא. מִכְתַּב אֱלֹהִים הוּא וַדַּאי."],[9,"","וַיֵּרֶד מֹשֶׁה אֶל הָעָם וַיֹּאמֶר אֲלֵהֶם. רַבִּי יוֹסֵי אָמַר, מַהִי הָאֲמִירָה הַזּוֹ שֶׁכָּתוּב וַיֹּאמֶר אֲלֵהֶם, וְלֹא כָתוּב מָה אָמַר? אָמַר רַבִּי יִצְחָק, בֹּא וּרְאֵה, דֶּרֶךְ הָעוֹלָם הוּא, כְּשֶׁבָּאָה שִׂמְחָה לָאָדָם אוֹ כְּשֶׁבָּא צַעַר - כְּשֶׁעֲדַיִן לֹא יוֹדֵעַ מִמֶּנּוּ, לֹא יָכוֹל לִסְבֹּל, שֶׁהֲרֵי לִבּוֹ פּוֹרֵחַ לְשָׁעָה. וּכְשֶׁיּוֹדֵעַ מִמֶּנּוּ, עוֹמֵד בְּקִיּוּמוֹ וְיָכוֹל לִסְבּל. כָּל שֶׁכֵּן כָּאן, (וכאן אינו כך) שֶׁהֲרֵי מֹשֶׁה אָמַר לָהֶם כָּל מַה שֶּׁהָיָה אַחַר כָּךְ וְחִזֵּק לִבָּם בִּדְבָרִים, וְלֹא יָכְלוּ לִסְבֹּל. כָּל שֶׁכֵּן אִם לֹא הָיָה אוֹמֵר לָהֶם דָּבָר. וּמִשּׁוּם כָּךְ וַיֹּאמֶר אֲלֵהֶם בַּתְּחִלָּה, וְחִזֵּק לִבָּם, וְאַחַר כָּךְ וַיְדַבֵּר אֱלֹהִים."],[10,"","וְעִם כָּל זֶה לֹא יָכְלוּ לִסְבֹּל, שֶׁהֲרֵי שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, כְּשֶׁשָּׁמְעוּ דְבָרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, פָּרְחָה נִשְׁמָתָם, וְעָלְתָה נִשְׁמָתָם שֶׁל יִשְׂרָאֵל עַד כִּסֵּא כְבוֹדוֹ לְהִדָּבֵק שָׁם."]]],[["אָמְרָה אוֹרַיְיתָא קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכִי לְמַגָּנָא הֲוֵינָא מִתְּרֵי אַלְפֵי שְׁנִין, עַד לָא אִתְבְּרֵי עָלְמָא, לְמַגָּנָא כְּתִיב בָּהּ, (ויקרא י״ז:י״ג) וְאִישׁ אִישׁ מִבְּנֵי יִשְׂרָאֵל וּמִן הַגֵר הַגָר בְּתוֹכָם (ויקרא כ״ד:ט״ו) וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר. (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים. אָן אִינּוּן בְּנִי יִשְׂרָאֵל. בָּהּ שַׁעֲתָא, אָהַדְרַת אוֹרַיְיתָא נִשְׁמָתַיְיהוּ דְּיִשְׂרָאֵל, כָּל חַד וְחַד לְאַתְרֵיהּ. אוֹרַיְיתָא אַתְקִיפַת, וַאֲחִידַת בְּהוּ בְּנִשְׁמָתַיְיהוּ, לְאָהַדְּרָא לְהוּ לְיִשְׂרָאֵל הֲדָא הוּא דִכְתִיב, (תהילים י״ט:ח׳) תּוֹרַת יְיָ' תְּמִימָה מְשִׁיבַת נָפֶשׁ. מְשִׁיבַת נֶפֶשׁ מַמָּשׁ.","תָּאנָא, כְּתִיב (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יְיָ' לְמֶלֶךְ, כְּמָה דִּכְתִּיב, (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. ר' אַבָּא אָמַר, דְּקַיְּימָא סִיהֲרָא בְּאַשְׁלָמוּתָא. דְּתָנֵינָן, בְּיוֹמוֹי דְּשְׁלֹמֹה, קַיְּימָא סִיהֲרָא בְּאַשְׁלָמוּתָא.","אֵימָתַי בְּאַשְׁלָמוּתָא. (נ\"א תאנא כתיב ותרב חכמת שלמה וגו' מאי ותרב, אמר ר' אבא דקיימא סיהרא באשלמותא מאי באשלמותא) דְּקַיְּימָא בַּחֲמִשָּׁה עָשָׂר, כְּמָה דְּתָנֵינָן, אַבְרָהָם. יִצְחָק. יַעֲקֹב. יְהוּדָה. פֶּרֶץ. חֶצְרוֹן. רָם. עֲמִּינָדָב. נַחְשׁוֹן. שַׂלְמוֹן. בּוֹעַז. עוֹבֵד. יִשַׁי. דָּוִד. שְׁלֹמֹה. כַּד אָתָא שְׁלֹמֹה, קַיְּימָא סִיהֲרָא בְּאַשְׁלָמוּתָא. הֲדָא הוּא דִכְתִיב, וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יְיָ' לְמֶלֶךְ. וּכְתִיב שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא.","בְּיוֹמוֹי דְּצִדְקִיָּה, קַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, וְאִתְפְּגִים. כְּמָה דְאַתְּ אָמֵר, (ישעיהו י״ג:י׳) וַיָרֵחַ לֹא יַגִּיהַּ אוֹרוֹ. דְּתָנֵינָן, (ויקרא מ' ע\"ב) בְּיוֹמוֹי דְּצִדְקִיָּה, אִתְפְּגִים סִיהֲרָא, וְאִתְחַשּׁכוּ אַנְפַּיְיהוּ דְּיִשְׂרָאֵל.","פּוּק וְחָשִׁיב, רְחַבְעָם. אָבִיהָ. אָסָא. יְהוֹשָׁפָט. יְהוֹרָם. אֲחַזְיָהוּ. יוֹאָשׁ. אֲמַצְיָהוּ. עוּזִיָּהוּ. יוֹתָם. אָחָז. יְחִזְקִיָּהוּ. מְנַשֶּׁה. אָמוֹן. יֹאשִׁיָּהוּ. צִדְקִיָּהוּ. וְכַד אָתָא צִדְקִיָּהוּ אִתְפְּגִים סִיהֲרָא וְקַיְּימָא עַל פְּגִימוּתָא. דִּכְתִּיב, (ירמיהו נ״ב:י״א) וְאֶת עֵינֵי צִדְקִיָּה עִוֵּר. בֵּיהּ זִמְנָא (איכה ב׳:א׳) הִשְׁלִיךְ (ויקרא קי\"ד ע\"א) מִשָּׁמַיִם אֶרֶץ. הַאי אֶרֶץ אִתְעַבְּרָא מִקָּמֵי שָׁמַיִם, וְאִתְרָחָקַת מִנֵּיהּ, וְאִתְחַשְּׁכָא הַאי אֶרֶץ. (כלומר דקיימא סיהרא בפגימותא).","תָּאנָא, בְּשַׁעֲתָא דְּקַיְימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי שָׁארֵי סִיהֲרָא לְאַנְהָרָא, דִּכְתִּיב, (שמואל ב כ״ב:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד. מַהוּ וַיֵּרַד. דְּקָרִיב שִׁמְשָׁא לְגַבֵּי סִיהֲרָא, וְשָׁרֵי לְאַנְהָרָא סִיהֲרָא. דִּכְתִּיב, (במדבר ב׳:ג׳) דֶּגֶל מַחֲנֵה יְהוּדָה מִזְרָחָה.","בְּטוּרָא דְּסִינַי, אִתְמָנָא יְהוּדָה, רוֹפִינֻס בְּמַלְכוּתָא, דִּכְתִּיב, (הושע י״ב:א׳) וִיהוּדָה עוֹד רֵד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. (נ\"א רבי יצחק אמר מהכא ויהודה עוד רד עם אל הוי שולטנא בשעתא דהאי אל שליט מלכותיה על טורא דסיני בהאי שעתא שליט מלכותא דיהודה) מַהוּ וְעִם קְדוֹשִׁים נֶאֱמָן. כַּד אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ, נֶאֱמָן הֲוָה יְהוּדָה לְקַבְּלָא מַלְכוּתָא, וְשָׁאֲרִי סִיהֲרָא לְאַנְהָרָא.","(שמות כ׳:ב׳) אָנֹכִי יְיָ' אֱלהֶיךָ אֲשֶׁר הוֹצֵאתִיךָ וְגוֹ' ר' אֶלְעָזָר פָּתַח, (משלי א׳:ח׳) שְׁמַע בְּנִי מוֹסֵר אָבִיךָ וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ. שְׁמַע בְּנִי מוּסַר אָבִיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ: דָּא כְּנֶסֶת יִשְׂרָאֵל. מַאן כְּנֶסֶת יִשְׂרָאֵל. דָּא בִּינָה. כְּמָה דִּכְתִּיב, (משלי א׳:ב׳) לְהָבִין אִמְרֵי בִינָה","ר' יְהוּדָה אָמַר, מוּסַר אָבִיךָ: דָּא הִיא חָכְמָה. וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ: דָּא הִיא בִּינָה. ר' יִצְחָק אָמַר, הָא וְהָא, חַד מִלָּה אִתְפְּרָשׁוּ. דְּתָנֵינָן, (בראשית מ\"ז ע\"ב) אוֹרַיְיתָא מֵחָכְמָה דִּלְעֵילָּא נַפְקַת. ר' יוֹסֵי אָמַר, מִבִּינָה נַפְקַת, דִּכְתִּיב לְהָבִין אִמְרֵי בִינָה, וּכְתִיב וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ.","אָמַר ר' יְהוּדָה, אוֹרַיְיתָא מֵחָכְמָה וּבִינָה אִתְכְּלִילַת, דִּכְתִּיב, שְׁמַע בְּנִי מוּסַר אָבִיךָ וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ. ר' אַבָּא אָמַר, בְּכֹלָּא אִתְכְּלִילַת, דְּכֵיוָן דִּבְאִלֵּין תְּרֵין אִתְכְּלִילַת, אִתְכְּלִילַת בְּכֹלָּא. בְּחֶסֶד, בְּדִינָא בְּרַחֲמֵי. בְּכֻלְּהוּ שְׁלֵימוּתָא דְּאִצְטְרִיךְ מִלָּה. אִי מַלְכָּא וּמַטְרוֹנִיתָא מִסְתַּכְּמִין, כֹּלָּא מִסְתַּכְּמִין. בַּאֲתָר דְּאִלֵּין מִשְׁתַּכְּחִין, כֹּלָּא מִשְׁתַּכְּחִין.","ר' יוֹסֵי אָמַר, אָנֹכִי: דָּא שְׁכִינְתָּא. כְּמָה דִּכְתִּיב, (בראשית מ״ו:ד׳) אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה. יְיָ' אֱלהֶיךָ: (נ\"א כלא סליק לעילא, למהר כלא חד) (דא כנסת ישראל דכתיב ואל תטוש תורת אמך) ר' יִצְחָק אָמַר, אָנֹכִי: דָּא שְׁכִינְתָּא. וּפָסְקָא טַעֲמָא. כְּמָה דְאַתְּ אָמֵר (בראשית כ״ז:י״ט) אָנֹכִי עֵשָׂו בְּכוֹרֶךָ. יְיָ' אֱלֹהֶיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דִּכְתִּיב, (דבהם ד) מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קוֹלוֹ. וּכְתִיב אַתֶּם רְאִיתֶם כִּי מִן הַשָּׁמַיִם דִּבַּרְתִּי עִמָּכֶם. מִן הַשָּׁמַיִם (מן השמים ממש דא קודשא בריך הוא.)"],[[0,"אמרה אורייתא קמיה וכו':","אמרה התורה לפני הקב\"ה, וכי לחנם הייתי שני אלפים שנה מטרם שנברא העולם. לחנם כתוב בה, ואיש איש מבני ישראל ומן הגר הגר בתוכם. ואל בני ישראל תדבר לאמר. כי לי בני ישראל עבדים. איפה הם בני ישראל. בה בשעה החזירה התורה את נשמות בני ישראל כל אחת ואחת למקומה. התורה התקיפה ואחזה בהן בנשמות להחזירן לישראל. ז\"ש תורת ה' תמימה משיבת נפש, משיבת נפש ממש. כי השיבה נשמות ישראל אחר שפרחו מהם."],[1,"תאנא כתיב וכו':","למדנו, כתוב, וישב שלמה על כסא ה' למלך. כמו שכתוב, שש מעלות לכסא. כנגד שש הספירות חג\"ת נה\"י, וע\"כ נקרא כסא ה'. ר' אבא אמר, שעמדה הלבנה במלואה, שלמדנו, בימיו של שלמה עמדה הלבנה במלואה. דהיינו הנוקבא דז\"א הנקראת לבנה, היתה בכל שלמותה."],[2,"אימתי באשלמותא וכו':","שואל, מתי הלבנה שהיא המלכות היא במלואה. ומשיב בשעה שעומדת בחמשה עשר מלכים, כמו שלמדנו, אברהם, יצחק, יעקב, יהודה, פרץ, חצרון, רם, עמינדב, נחשון, שלמון, בועז, עובד, ישי, דוד, שלמה. כשבא שלמה, שהוא מלך הט\"ו, עמדה הלבנה, שהיא המלכות, במלואה. ז\"ש וישב שלמה על כסא ה' למלך, שהוא המלכות. וכתוב, שש מעלות לכסא, כנגד חג\"ת נה\"י שלה, הכל כעין של מעלה."],[3,"ביומוי דצדקיה וכו':","בימיו של צדקיהו, עמדה הלבנה, שהיא המלכות, בחסרון, ונפגמה. כש\"א, וירח לא יגיה אורו. שלמדנו, בימיו של צדקיהו נפגמה הלבנה, ונחשכו פניהם של ישראל."],[4,"פוק וחשוב וכו':","צא וחשוב. רחבעם, אביה, אסא, יהושפט, יהורם, אחזיהו, יואש, אמציהו, עוזיהו, יותם, אחז, יחזקיהו, מנשה, אמון, יאשיהו, צדקיהו. וכשבא צדקיהו נפגמה הלבנה ועמדה בחסרונה, שכתוב, ואת עיני צדקיהו עור. בו בזמן, השליך משמים ארץ, דהיינו ארץ זו, שהיא המלכות, נעברה מלפני שמים, שהוא ז\"א, ונרחקה ממנו, ונחשכה ארץ הזאת."],[5,"תאנא בשעתא וכו':","למדנו, בשעה שעמדו ישראל על הר סיני התחילה הלבנה להאיר. שכתוב, ויט שמים וירד. מהו וירד. היינו שהשמש, שהוא ז\"א הנקרא שמים, קרב אל הלבנה, שהיא המלכות, והלבנה התחילה להאיר. שכתוב, דגל מחנה יהודה מזרחה. יהודה הוא מרכבה למלכות, מזרחה, לשון זריחה והארה."],[6,"בטורא דסיני וכו':","בהר סיני, נתמנה יהודה לשלוט במלכות, שכתוב, ויהודה עוד רד עם אל ועם קדושים נאמן. שואל, מהו ועם קדושים נאמן. ומשיב, כשאמר הקב\"ה לישראל, ואתם תהיו לי ממלכת כהנים וגוי קדוש, נאמן היה יהודה לקבל את המלכות. והתחילה הלבנה, שהיא המלכות, להאיר."],[7,"אנכי ה' אלקיך וגו':","ר' אלעזר פתח, שמע בני מוסר אביך ואל תטוש תורת אמך. שמע בני מוסר אביך זה הקב\"ה, דהיינו ז\"א, ואל תטוש תורת אמך, זו היא כנסת ישראל. מי כנסת ישראל. זו היא בינה. כמ\"ש להבין אמרי בינה."],[8,"ר' יהודה אמר וכו':","רי\"א, מוסר אביך, זה הוא חכמה, שנקראת אבא. ואל תטוש תורת אמך, זו היא בינה. ר' יצחק אמר, זה וזה, מוסר אביך ותורת אמך, בדבר אחד מתבארים שלמדנו, התורה יצאה מחכמה של מעלה. והחכמה עצמה מתחלקת לימין שנקרא אבא, ולשמאל שנקרא אמא. ר' יוסי אמר מבינה יוצאת התורה, שכתוב, להבין אמרי בינה, וכתוב, אל תטוש תורת אמך. והבינה נקראת אמא."],[9,"אמר ר' יהודה וכו':","אר\"י, התורה מחכמה ובינה נכללה, שכתוב, שמע בני מוסר אביך ואל תטוש תורת אמך. ר' אבא אמר בכל הספירות נכללה, כיון שנכללה באלו השנים, חו\"ב, היא נכללה בכולם. כי חו\"ב כוללים בעצמם כל הספירות, בחסד, בדין ברחמים. שהם חג\"ת, בכל השלמות שהדבר צריך. אם המלך והמלכה התחברו בה כולם מתחברים בה. במקום שאלו, חו\"ב, נמצאים. נמצאים כולם."],[10,"ר' יוסי אמר וכו':","רי\"א, \u0003אנכי,\u0004 זו היא השכינה, כמ\"ש אנכי ארד עמך מצרימה. \u0003ה' אלקיך,\u0004 ר' יצחק אמר, אנכי, שהיא השכינה פוסק אותה הטעם, שתחת המלה, אנכי, כתוב טעם טפחה, שנגינתו מפסיקה מן המלה שלאחריה ה' אלקיך. כמש\"א אנכי עשו בכורך. שדרשינן, אנכי, מי שאני, עשו, הוא בכורך. וע\"כ, ה' אלקיך זה הקב\"ה, שהוא ז\"א. כמ\"ש מן השמים השמיעך את קולו. ושמים הוא ז\"א. וכתוב, אתם ראיתם כי מן השמים דברתי עמכם. מן השמים ממש, זה הקב\"ה. דהיינו ז\"א."]],[[0,"","אָמְרָה תוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי לְחִנָּם הָיִיתִי מֵאַלְפַּיִם שָׁנִים טֶרֶם שֶׁנִּבְרָא הָעוֹלָם?! לְחִנָּם כָּתוּב בָּהּ (ויקראיז) וְאִישׁ אִישׁ מִבְּנֵי יִשְׂרָאֵל וּמִן הַגֵּר הַגָּר בְּתוֹכָם, (שמות ל) וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר, (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים?! אֵיפֹה הֵם בְּנֵי יִשְׂרָאֵל? בְּאוֹתָהּ שָׁעָה הֶחֱזִירָה הַתּוֹרָה אֶת נִשְׁמוֹת יִשְׂרָאֵל כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. הַתּוֹרָה חִזְּקָה וְאָחֲזָה בְּנִשְׁמוֹתֵיהֶם לְהַחֲזִיר אוֹתָן לְיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (תהלים יט) תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ. מְשִׁיבַת נֶפֶשׁ מַמָּשׁ."],[1,"","שָׁנִינוּ, כָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ, כְּמוֹ שֶׁכָּתוּב (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. רַבִּי אַבָּא אָמַר, שֶׁהַלְּבָנָה עָמְדָה בִּשְׁלֵמוּת, שֶׁשָּׁנִינוּ שֶׁבִּימֵי שְׁלֹמֹה עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת."],[2,"","אֵימָתַי בִּשְׁלֵמוּת? (שנינו, כתוב ותרב חכמת שלמה וגו'. מהו ותרב, ' אמר רבי אבא, שעמדה הלבנה בשלמותה. מהו בשלמותה, ') שֶׁעָמְדָה בַּחֲמִשָּׁה עָשָׂר, כְּמוֹ שֶׁשָּׁנִינוּ, אַבְרָהָם. יִצְחָק. יַעֲקֹב. יְהוּדָה. פֶּרֶץ. חֶצְרוֹן. רָם. עַמִּינָדָב. נַחְשׁוֹן. שַׂלְמוֹן. בּעַז. עוֹבֵד. יִשַׁי. דָּוִד. שְׁלֹמֹה. כְּשֶׁבָּא שְׁלֹמֹה עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ. וְכָתוּב שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה."],[3,"","בִּימֵי צִדְקִיָּה עָמְדָה הַלְּבָנָה בִּפְגָם וְנִפְגְּמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יג) וְיָרֵחַ לֹא יַגִּיהַּ אוֹרוֹ. שֶׁשָּׁנִינוּ, בִּימֵי צִדְקִיָּה נִפְגְּמָה הַלְּבָנָה וְחָשְׁכוּ פְנֵיהֶם שֶׁל יִשְׂרָאֵל."],[4,"","צֵא וַחֲשֹׁב, רְחַבְעָם. אֲבִיָּה. אָסָא. יְהוֹשָׁפָט. יְהוֹרָם. אֲחַזְיָהוּ. יוֹאָשׁ. אֲמַצְיָהוּ. עֻזִּיָּהוּ. יוֹתָם. אָחָז. יְחִזְקִיָּהוּ. מְנַשֶּׁה. אָמוֹן. יֹאשִׁיָּהוּ. צִדְקִיָּהוּ. וּכְשֶׁבָּא צִדְקִיָּהוּ, נִפְגְּמָה הַלְּבָנָה וְעָמְדָה עַל פְּגָם, שֶׁכָּתוּב (ירמיה נב) וְאֶת עֵינֵי צִדְקִיָּה עִוֵּר. בְּאוֹתוֹ זְמַן (איכהב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. אֶרֶץ זוֹ הָעָבְרָה מִלִּפְנֵי שָׁמַיִם וְהִתְרַחֲקָה מִמֶּנּוּ, וְנֶחְשְׁכָה הָאָרֶץ הַזּוֹ. (כלומר, שעמדה הלבנה בפגימותה)."],[5,"","שָׁנִינוּ, בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, הִתְחִילָה הַלְּבָנָה לְהָאִיר, שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד. מַה זֶּה וַיֵּרַד? שֶׁקֵּרַב הַשֶּׁמֶשׁ לַלְּבָנָה, וְהִתְחִילָה לְהָאִיר הַלְּבָנָה, שֶׁכָּתוּב (במדבר כ) דֶּגֶל מַחֲנֵה יְהוּדָה מִזְרָחָה."],[6,"","בְּהַר סִינַי הִתְמַנָּה יְהוּדָה כְּשַׁלִּיט בַּמַּלְכוּת, שֶׁכָּתוּב (הושע יב) וִיהוּדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. (רבי יצחק אמר מכאן, ויהודה עד רד עם אל, השלטון היה בשעה שהאל הזה שולטת מלכותו על הר סיני, באותה שעה מלכותו של יהודה) מַה זֶּה וְעִם קְדוֹשִׁים נֶאֱמָן? כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ, נֶאֱמָן הָיָה יְהוּדָה לְקַבֵּל מַלְכוּת, וְהִתְחִילָה הַלְּבָנָה לְהָאִיר."],[7,"","אָנֹכִי ה' אֱלֹהֶיךְ אֲשֶׁר הוֹצֵאתִיךְ וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (משלי א) שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ. שְׁמַע בְּנִי מוּסַר אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִי זוֹ כְּנֶסֶת יִשְׂרָאֵל? זוֹ בִּינָה, כְּמוֹ שֶׁכָּתוּב לְהָבִין אִמְרֵי בִינָה."],[8,"","רַבִּי יְהוּדָה אָמַר, מוּסַר אָבִיךְ - זוֹ הִיא חָכְמָה. וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ - זוֹ הִיא בִּינָה. רַבִּי יִצְחָק אָמַר, זֶה וָזֶה דָּבָר אֶחָד הִתְפָּרְשׁוּ. שֶׁשָּׁנִינוּ, תּוֹרָה יָצְאָה מֵחָכְמָה שֶׁל מַעְלָה. רַבִּי יוֹסֵי אָמַר, מִבִּינָה יָצְאָה, שֶׁכָּתוּב לְהָבִין אִמְרֵי בִינָה, וְכָתוּב וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ."],[9,"","אָמַר רַבִּי יְהוּדָה, תּוֹרָה נִכְלְלָה מֵחָכְמָה וּבִינָה, שֶׁכָּתוּב שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ. רַבִּי אַבָּא אָמַר, בַּכֹּל הִיא נִכְלֶלֶת. שֶׁכֵּיוָן שֶׁנִּכְלֶלֶת בִּשְׁנֵי אֵלֶּה, הִיא נִכְלֶלֶת בַּכֹּל - בְּחֶסֶד, בְּדִין וּבְרַחֲמִים. בְּכֻלָּם הַשְּׁלֵמוּת שֶׁהַדָּבָר צָרִיךְ. אִם הַמֶּלֶךְ וְהַגְּבִירָה מַסְכִּימִים - הַכֹּל מַסְכִימִים. בְּמָקוֹם שֶׁאֵלֶּה נִמְצָאִים - כֻּלָּם נִמְצָאִים."],[10,"","רַבִּי יוֹסֵי אָמַר, אָנֹכִי - זוֹ הַשְּׁכִינָה, כְּמוֹ שֶׁכָּתוּב (בראשית מו) אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה. ה' אֱלֹהֶיךְ. (הכלעולה למעלה להיות הכל אחד) (זו כנסת ישראל, שכתוב ואל תטש תורת אמך) רַבִּי יִצְחָק אָמַר, אָנֹכִי - זוֹ הַשְּׁכִינָה, וּמַפְסִיק הַטַּעַם, כְּמוֹ שֶׁנֶּאֱמַר אָנֹכִי עֵשָׂו בְּכוֹרֶךְ. ה' אֱלֹהֶיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (דברים ד) מִן הַשָּׁמַיִם הִשְׁמִיעֲךְ אֶת קֹלוֹ. וְכָתוּב אַתֶּם רְאִיתֶם כִּי מִן הַשָּׁמַיִם דִּבַּרְתִּי עִמָּכֶם. מִן הַשָּׁמַיִם (מןהשמים ממש, זה הקדוש ברוך הוא)."]]],[["אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם. אֲשֶׁר: אֲתָר דְּכֹלָּא מְאַשְּׁרִין לֵיהּ. הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם: דָּא יוֹבְלָא. כְּמָה דְּתָנֵינָן, מִסִּטְרָא דְּיוֹבְלָא נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. וּבְגִין כַּךְ, חַמְשִׁין זִמְנִין אִדְכַּר יְצִיאַת מִצְרַיִם בְּאוֹרַיְיתָא. חַמְשִׁין יוֹמִין לְקַבְּלָא אוֹרַיְיתָא. חַמְשִׁין שְׁנִין לְחֵירוּ דְּעַבְדִין.","מִבֵּית עֲבָדִים: כְּמָה דִּכְתִּיב, (שמות י״ב:כ״ט) הִכָּה כָל בְּכוֹר בְּאֶרֶץ מִצְרַיִם. וְתָנֵינָן אִלֵּין כִּתְרִין תַּתָּאִין, דְּאִתְרְחִיצוּ בְּהוּ מִצְרָאֵי. כְּמָה דְּאִית בֵּיתָא לְעֵילָּא, אִית בֵּיתָא לְתַתָּא. בֵּיתָא קַדִּישָׁא לְעֵילָּא, דִּכְתִּיב, (משלי כ״ד:ג׳) בְּחָכְמָה יִבָּנֶה בָּיִת. בֵּיתָא תַּתָּאָה לְתַתָּא, דְּלָא קַדִּישָׁא, כְּמָה דִּכְתִּיב מִבֵּית עֲבָדִים.","תָּאנָא, בְּשַׁעֲתָא דְּאִתְּמַר אָנֹכִי, כָּל אִינּוּן פִּקּוּדֵי אוֹרַיְיתָא, דְּמִתְאַחֲדָן בְּמַלְכָּא קַדִּישָׁא עִלָּאָה, בְּסִטְרָא (ס\"א דא') כֻּלְּהוּ הֲוָה כְּלִילָן בְּהַאי מִלָּה.","כְּמָה דְּתָנֵינָן, כָּל פִּקּוּדֵי אוֹרַיְיתָא, מִתְאַחֲדָן בְּגוּפָא דְּמַלְכָּא. (דבר אחר במלכא קדישא עלאה) מִנְּהוֹן בְּרֵישָׁא דְּמַלְכָּא, וּמִנְהוֹן בְּגוּפָא, וּמִנְהוֹן בִּידֵי מַלְכָּא, וּמִנְהוֹן בְּרַגְלוֹי, וְלֵית מַאן דְּנָפִיק מִן גּוּפָא דְּמַלְכָּא לְבַר. וּבְגִין כַּךְ, מַאן דְּפָשַׁע בְּחַד פִּקּוּדֵי אוֹרַיְיתָא, כְּמַאן דְּפָשַׁע בְּגוּפָא דְּמַלְכָּא, כְּמָה דִּכְתִּיב, (ישעיהו ס״ו:כ״ד) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי. בִּי מַמָּשׁ. וַוי לְחַיָּיבַיָּא, דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְלָא יַדְעִין מַאי קָא עַבְדִין.","דְּאָמַר ר' שִׁמְעוֹן, הַהוּא אֲתָר דְּאִיהוּ חָב לְגַבֵּיהּ, הַהוּא אֲתָר מַמָּשׁ גַּלֵּי חוֹבֵיהּ. (ואמר ר' שמעון קודשא בריך הוא ממש גלי חוביה) חָב בְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא גַּלֵּי חוֹבֵיהּ, דִּכְתִּיב, (איוב כ׳:כ״ז) יְגַלּוּ שָׁמַיִם עֲוֹנוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. יְגַלּוּ שָׁמַיִם עֲוֹנוֹ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאֶרֶץ מִתְקוֹמָמָה לוֹ: דָּא קוּדְשָׁא בְּרִיךְ הוּא (נ\"א דא כנסת ישראל.)","תַּנְיָא, שָׁמַיִם גַּלְּיָין חוֹבֵיהּ דְּבַר נָשׁ. וּבְשַׁעֲתָא דְּאִיהוּ גַּלְּיָא חוֹבֵיהּ, אֶרֶץ עָבִיד דִּינָא דְּבַר נָשׁ, דִּכְתִּיב וְאֶרֶץ מִתְקוֹמָמָה לוֹ, לְמֶעְבַּד דִּינָא בֵּיהּ. אָמַר ר' יוֹסֵי, תָּנֵינָן מִשְּׁמֵיהּ דְּר' שִׁמְעוֹן, בְּשַׁעֲתָא דְּאִתְיְהִיבַת אוֹרַיְיתָא, אִימָא וּבְנִין בִּשְׁלֵימוּתָא אִשְׁתְּכָחוּ, דִּכְתִּיב, (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה.","אָנֹכִי יְיָ' אֱלֹהֶיךָ. אָנֹכִי, כְּמָה דְּתָנֵינָן, בַּת הָיְתָה לוֹ לְאַבְרָהָם אָבִינוּ, הִיא שְׁכִינְתָּא. וְדָא בַּת. יְיָ' אֱלהֶיךָ, דִּכְתִּיב (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל. וּכְתִיב (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, הָא בֵּן.","אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם, דִּכְתִּיב, (ויקרא כ״ה:י״ב) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, וּכְתִיב (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה. וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר, הָא אִימָא וּבְנִין. יָתְבָא אִימָא יַתְבִין בְּנִין. (ועלמין) כֻּלְּהוּ בְּחֶדְוָה בִּשְׁלִימוּתָא. וְעַל דָּא כְּתִיב, אֵם הַבָּנִים שְׂמֵחָה. מִתְעַבְּרָא אִימָא, כֻּלְּהוּ מִתְעַבְּרָן בְּדוּכְתַּיְיהוּ. וּכְתִיב, (דברים כ״ב:ו׳) לא תִקַּח הָאֵם עַל הַבָּנִים. וְתָנֵינָן, לָא יַעְבִיד בַּר נָשׁ חוֹבֵי לְתַתָּא, בְּגִין דְּאִתְעֲבָר אִימָּא מֵעַל בְּנִין.","אָמַר ר' יִצְחָק, כֹּלָּא קוּדְשָׁא בְּרִיךְ הוּא. כֹּלָּא הוּא. כֹּלָּא חַד. וּמִלִּין אִלֵּין, לִמְחַצְּדֵי חַקְלָא אִתְגַּלְּיָין. זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.","תָּאנֵי אָמַר ר' אֶלְעָזָר, כְּתִיב, בְּרֵאשִׁית בָּרָא אֱלהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. וּכְתִיב, (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יְיָ' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. בְּמָאי אוֹקִימְנָא הָנִי קְרָאֵי, הָא תָּנֵינָן, דְּתַרְוַויְיהוּ כַּחֲדָא אִתְבְּרִיאוּ. מְלַמֵּד, שֶׁנָּטָה הַקָדוֹשׁ בָּרוּךְ הוּא קַו יְמִינוֹ וּבָרָא הַשָּׁמַיִם, וּנְטֵה קַו שְׂמֹאלוֹ, וּבָרָא אֶת הָאָרֶץ. בְּקַדְמִיתָא אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וּלְבָתַר אֶרֶץ וְשָׁמָיִם.","תְּנָן, כְּתִיב, (הושע ב׳:כ״ג-כ״ד) בַּיּוֹם הַהוּא אֶעֱנֶה נְאֻם יְיָ' אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. אֶעֱנֶה אֶת הַשָּׁמָיִם, שָׁמַיִם מַמָּשׁ. דִּכְתִּיב, (ישעיהו ס״ו:א׳) הַשָּׁמַיִם כִּסְאִי. וְהֵם יַעֲנוּ אֶת הָאָרֶץ. הָאָרֶץ מַמָּשׁ, דִּכְתִּיב וְהָאָרֶץ הֲדוֹם רַגְלָי. שָׁמַיִם, שָׁמַיִם עִלָּאִין. וְאֶרֶץ, אֶרֶץ עִלָּאָה. דְּתַנְיָא, כַּד אִתָּקַן שָׁמַיִם דָּא בְּתִיקוּנוֹי, (אתקן) לָקֳבְלֵיהּ דְּהַאי אֶרֶץ, וְתֵיאוּבְתֵיהּ לְקַבְּלָהּ, בְּחַד דַּרְגָּא דְּאִקְרֵי צַדִּיק. כְּמָה דִּכְתִּיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, וְאִתְדָּבַּק בְּהַאי אֶרֶץ."],[[0,"אשר הוצאתיך מארץ מצרים:","אשר, פירושו, מקום שהכל מאשרים אותו, שהוא בינה. \u0003הוצאתיך מארץ מצרים,\u0004 זה יובל, שהוא בינה הנקראת אשר, הוציאנו ממצרים. כמו שלמדנו, מצד יובל, שהוא בינה, יצאו ישראל ממצרים. ומשום זה חמשים פעמים נזכר יציאת מצרים בתורה, וכן חמשים יום לקבלת התורה, וכן חמשים שנים לחירות העבדים. שכל אלו הם כנגד חמשים שערי בינה."],[1,"מבית עבדים:","כמו שכתוב, הכה כל בכור בארץ מצרים, ולמדנו, שהם אלו כתרים התחתונים שהמצרים בטחו בהם. כמו שיש בית למעלה יש בית למטה, בית הקדוש למעלה כמ\"ש בחכמה יבנה \u0003בית.\u0004 בית תחתון למטה בקליפות, שאינו קדוש, הוא כמ\"ש \u0003מבית\u0004 עבדים."],[2,"תאנא בשעתא דאתמר וכו':","למדנו, בשעה שנאמר אנכי, כל אלו מצות התורה שנאחזים במלך הקדוש העליון, שהוא ז\"א בצד זה, כולם היו כלולים במלה הזו, אנכי."],[3,"כמה דתנינן וכו':","כמו שלמדנו. כל מצות התורה נאחזים בגוף המלך, שהוא ז\"א, מהם בראש המלך, מהם בגוף, ומהם בידי המלך, ומהם ברגליו. ואין מהם מי שיוצא מגוף המלך ולחוץ. ומשום זה, מי שפושע במצוה אחת שבתורה, הוא כמי שפושע בגוף המלך. כמ\"ש, ויצאו וראו בפגרי האנשים הפושעים בי, \u0003בי\u0004 ממש. אוי לרשעים העוברים על דברי תורה, ואינם יודעים מה שעושים."],[4,"דאמר ר' שמעון וכו':","דאר\"ש, מקום ההוא שחטא לו, מקום ההוא ממש מגלה חטאו. חטא בהקב\"ה, כנ\"ל, הקב\"ה מגלה חטאו, שכתוב, יגלו שמים עונו וארץ מתקוממה לו. יגלו שמים עונו, זה הקב\"ה, דהיינו ז\"א הנקרא שמים, וארץ מתקוממה לו זו כנסת ישראל, דהיינו המלכות הנקראת ארץ."],[5,"תניא שמים גליין וכו':","למדנו השמים, שהוא ז\"א, מגלים עונו של אדם, ובשעה שהוא מגלה עונו, הארץ, שהיא המלכות עושה הדין של האדם, שכתוב, וארץ מתקוממה לו, לעשות בו דין. אמר ר' יוסי למדנו בשם ר' שמעון, בשעה שניתנה התורה, האם, שהיא בינה, והבנים, שהם זו\"ן, נמצאו בשלימות. שכתוב, אם הבנים שמחה."],[6,"אנכי ה' אלקיך:","אנכי, הוא כמו שלמדנו, בת היתה לו לאברהם אבינו, שהיא השכינה. וזו היא בת. \u0003ה' אלקיך,\u0004 הוא כמו שכתוב, בני בכורי ישראל. שהוא ז\"א הנקרא ישראל. וכתוב, עץ חיים היא למחזיקים בה. שהוא ז\"א הנקרא עץ החיים. הרי בן."],[7,"אשר הוצאתיך מארץ מצרים:","היינו שכתוב, יובל היא קדש תהיה לכם. שהיא בינה. וכתוב אם הבנים שמחה. וכתוב, וקדשתם את שנת החמשים שנה וקראתם דרור. שהיא בינה הנקראת שנת החמשים, ונקראת אמא. הרי אמא ובנים. אמא שהוציאנו ממצרים, ובנים שהם, אנכי שהיא בת. ה' אלקיך שה\"ס בן, כנ\"ל. יושבת אמא יושבים הבנים, כולם בשמחה בשלימות. ועל זה כתוב, אם הבנים שמחה. נעברה אמא, כולם נעברים ממקומם, וכתוב, לא תקח האם על הבנים, ולמדנו שפירושו, לא יעשה אדם חטאים למטה הגורמים להעביר אמא מעל הבנים."],[8,"אמר ר' יצחק וכו':","אר\"י, הכל, כל המדרגות הנ\"ל, הוא הקב\"ה, הכל, הוא. הכל אחד. ודברים אלו מגולים לקוצרי השדה, דהיינו אותם שכבר זכו לסו\"ה, ברנה יקצורו. כלומר, שכבר זכו לקבל מדרגותיהם מן המלכות המכונה שדה. אשרי הם בעולם הזה ובעולם הבא."],[9,"תאני אמר ר' אלעזר וכו':","למדנו, אר\"א, כתוב, בראשית ברא אלקים את השמים ואת הארץ, שהשמים קדמו לארץ, וכתוב, ביום עשות ה' אלקים ארץ ושמים, שהארץ קודמת לשמים. במה נישב כתובים אלו הסותרים זה את זה. ומשיב, הרי למדנו, ששניהם נבראו יחד, מלמד, שנטה הקב\"ה קו ימינו וברא את השמים, ונטה קו שמאלו וברא את הארץ. וע\"כ, כתוב תחלה את השמים ואת הארץ, ואח\"כ ארץ ושמים."],[10,"תנן כתיב וכו':","למדנו, כתוב, ביום ההוא אענה נאם ה' אענה את השמים והם יענו את הארץ. אענה את השמים היינו השמים ממש שהוא ז\"א, שכתוב, השמים כסאי, שבינה אומרת, הז\"א הוא כסאי. והם יענו את הארץ, הארץ ממש, שהיא המלכות. שכתוב, והארץ הדום רגלי. שמים, היינו שמים עליונים, שהוא ז\"א. וארץ, ארץ עליונה, שהיא המלכות. שלמדנו, כשנתקן השמים הזה בתקוניו, נתתקן כנגד ארץ הזו, והשתוקקותו כנגדה. הוא במדרגה אחת שנקראת צדיק, שכתוב, וצדיק יסוד עולם. והתדבק בארץ הזו."]],[[0,"","אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם. אֲשֶׁר - מָקוֹם שֶׁהַכֹּל מְאַשְּׁרִים אוֹתוֹ. הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם - זֶה יוֹבֵל, כְּמוֹ שֶׁשָּׁנִינוּ, מִצַּד הַיּוֹבֵל יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וּמִשּׁוּם כָּךְ חֲמִשִּׁים פְּעָמִים נִזְכְּרָה יְצִיאַת מִצְרַיִם בַּתּוֹרָה. חֲמִשִּׁים יָמִים לְקַבָּלַת הַתּוֹרָה. חֲמִשִּׁים יָמִים לְחֵרוּת הָעֲבָדִים."],[1,"","מִבֵּית עֲבָדִים - כְּמוֹ שֶׁכָּתוּב (שמות יב) הִכָּה כָל בְּכוֹר בְּאֶרֶץ מִצְרַיִם. וְשָׁנִינוּ, הַכְּתָרִים הַתַּחְתּוֹנִים הַלָּלוּ שֶׁהַמִּצְרִים בָּטְחוּ בָהֶם. כְּמוֹ שֶׁיֵּשׁ בַּיִת לְמַעְלָה - יֵשׁ בַּיִת לְמַטָּה. בַּיִת קָדוֹשׁ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת - בַּיִת תַּחְתּוֹן לְמַטָּה שֶׁאֵינוֹ קָדוֹשׁ, כְּמוֹ שֶׁכָּתוּב מִבֵּית עֲבָדִים."],[2,"","שָׁנִינוּ, בְּשָׁעָה שֶׁנֶּאֱמַר אָנֹכִי, כָּל אוֹתָן מִצְווֹת הַתּוֹרָה שֶׁנֶּאֶחְזוּ בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן בְּצַד (זה), כֻּלָּם הָיוּ כְּלוּלוֹת בַּדָּבָר הַזֶּה."],[3,"","כְּמוֹ שֶׁשָּׁנִינוּ, כָּל מִצְווֹת הַתּוֹרָה אֲחוּזוֹת בְּגוּף הַמֶּלֶךְ, (במלך הקדוש העליון) מֵהֶן בְּרֹאשׁ הַמֶּלֶךְ, וּמֵהֶן בַּגּוּף, וּמֵהֶן בִּידֵי הַמֶּלֶךְ, וּמֵהֶן בְּרַגְלָיו, וְאֵין מִי שֶׁיּוֹצֵא מִגּוּף הַמֶּלֶךְ הַחוּצָה. וְלָכֵן מִי שֶׁפָּשַׁע בְּמִצְוָה אַחַת שֶׁל הַתּוֹרָה, כְּמִי שֶׁפָּשַׁע בְּגוּף הַמֶּלֶךְ, כְּמוֹ שֶׁכָּתוּב (ישעיה ס) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי, בִּי מַמָּשׁ. אוֹי לָרְשָׁעִים שֶׁעוֹבְרִים עַל מִצְווֹת הַתּוֹרָה וְלֹא יוֹדְעִים מַה הֵם עוֹשִׂים."],[4,"","שֶׁאָמַר רַבִּי שִׁמְעוֹן, אוֹתוֹ מָקוֹם שֶׁהוּא חָטָא אֵלָיו, אוֹתוֹ מָקוֹם מַמָּשׁ מְגַלֶּה חֶטְאוֹ. (ואמר רבי שמעון, הקדוש ברוך הוא ממש מגלה חטאו) חָטָא בַּקָּדוֹשׁ-בָּרוּךְ-הוּא - הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה חֶטְאוֹ, שֶׁכָּתוּב (איוב כ) יְגַלּוּ שָׁמַיִם עֲונוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. יְגַלּוּ שָׁמַיִם עֲונוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶרֶץ מִתְקוֹמָמָה לוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (זו כנסת ישראל)."],[5,"","שָׁנִינוּ, שָׁמַיִם מְגַלִּים חֶטְאוֹ שֶׁל אָדָם, וּבְשָׁעָה שֶׁהוּא מְגַלֶּה חֶטְאוֹ, אֶרֶץ עוֹשָׂה דִּין הָאָדָם, שֶׁכָּתוּב וְאֶרֶץ מִתְקוֹמָמָה לוֹ, לַעֲשׂוֹת בּוֹ דִּין. אָמַר רַבִּי יוֹסֵי, שָׁנִינוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה, הָאֵם וְהַבָּנִים נִמְצְאוּ בִשְׁלֵמוּת, שֶׁכָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה."],[6,"","אָנֹכִי ה' אֱלֹהֶיךְ. אָנֹכִי, כְּמוֹ שֶׁשָּׁנִינוּ, בַּת הָיְתָה לוֹ לְאַבְרָהָם אָבִינוּ. הִיא שְׁכִינָה, וְזוֹ בַּת. ה' אֱלֹהֶיךְ, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. וְכָתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. הִנֵּה בֵּן."],[7,"","אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם, שֶׁכָּתוּב (ויקרא כה) יוֹבֵל הִוא קֹדֶשׁ תִּהְיֶה לָכֶם. וְכָתוּב אֵם הַבָּנִים שְׂמֵחָה. וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר. הֲרֵי אֵם וּבָנִים. יוֹשֶׁבֶת הָאֵם, יוֹשְׁבִים הַבָּנִים. (והעולמות) כֻּלָּם בְּשִׂמְחָה בִּשְׁלֵמוּת, וְעַל זֶה כָּתוּב אֵם הַבָּנִים שְׂמֵחָה. נֶעֶבְרָה הָאֵם - כֻּלָּם נֶעֱבָרִים מִמְּקוֹמָם. וְכָתוּב (דבריםכב) לֹא תִקַּח הָאֵם עַל הַבָּנִים. וְשָׁנִינוּ, לֹא יַעֲשֶׂה אָדָם חֲטָאִים לְמַטָּה, כְּדֵי שֶׁתַּעֲבֹר הָאֵם מֵעַל הַבָּנִים."],[8,"","אָמַר רַבִּי יִצְחָק, הַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא. הַכֹּל הוּא. הַכֹּל אֶחָד. וְהַדְּבָרִים הַלָּלוּ הִתְגַּלּוּ לְקוֹצְרֵי הַשָּׂדֶה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[9,"","שָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, כָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וְכָתוּב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. בַּמֶּה בֵּאַרְנוּ פְּסוּקִים אֵלּוּ, הֲרֵי שָׁנִינוּ שֶׁשְּׁנֵיהֶם נִבְרְאוּ כְאֶחָד? מְלַמֵּד שֶׁנָּטָה הַקָּדוֹשׁ בָּרוּךְ הוּא קַו יְמִינוֹ וּבָרָא הַשָּׁמַיִם, וְנָטָה קַו שְׂמֹאלוֹ וּבָרָא אֶת הָאָרֶץ. בַּתְּחִלָּה אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וְאַחַר כָּךְ אֶרֶץ וְשָׁמָיִם."],[10,"","שָׁנִינוּ, כָּתוּב (הושע ב) בַּיּוֹם הַהוּא אֶעֱנֶה נְאֻם ה' אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. אֶעֱנֶה אֶת הַשָּׁמָיִם - שָׁמַיִם מַמָּשׁ, שֶׁכָּתוּב (ישעיה סו) הַשָּׁמַיִם כִּסְאִי. וְהֵם יַעֲנוּ אֶת הָאָרֶץ - הָאָרֶץ מַמָּשׁ, שֶׁכָּתוּב וְהָאָרֶץ הֲדם רַגְלָי. שָׁמַיִם - שָׁמַיִם הָעֶלְיוֹנִים. וְאֶרֶץ - הָאָרֶץ הָעֶלְיוֹנָה. שֶׁשָּׁנִינוּ, כְּשֶׁהִתְתַּקֵּן שָׁמַיִם זֶה בְּתִקּוּנָיו, (התתקן) כְּנֶגֶד אֶרֶץ זוֹ, וּתְשׁוּקָתוֹ כְּנֶגְדָּהּ בְּדַרְגָּה אַחַת שֶׁנִּקְרֵאת צַדִּיק, כְּמוֹ שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, וְנִדְבָּק בָּאָרֶץ הַזּוֹ."]]],[["וּמֵרֵישָׁא דְּמַלְכָּא, עַד הַהוּא אֲתָר דְּשָׁאֲרִי הַאי צַדִּיק, אָתֵי חַד נַהֲרָא קַדִּישָׁא, מִשְׁחָא דִּרְבוּת, וְאַטִּיל בִּסְגִיאוּת תִּיאוּבְתָּא, בְּהַאי אֶרֶץ קַדִּישָׁא, וְנָטַל כֹּלָּא הַאי אֶרֶץ. וּלְבָתַר, מֵהַאי אֶרֶץ אִתְּזַן כֹּלָּא, עִילָּאֵי וְתַתָּאֵי. כִּדְכוּרָא דָּא, כַּד תִּיאוּבְתֵּיהּ לְאִתְדַּבְּקָא בְּנוּקְבָא, דְּאַפִּיק זַרְעָא דִּרְבוּת, מֵרֵישָׁא דְּמוֹחָא, בְּהַהוּא אָמָה, וְאַטִּיל בְּנוּקְבָא, וּמִנֵּיהּ מִתְעַבְּרָא נוּקְבָּא, אִשְׁתְּכַח, דְּכֻלְּהוּ שַׁיְיפִין דְּגוּפָא, כֻּלְּהוּ מִתְדַבְּקָן בְּנוּקְבָא, וְנוּקְבָּא אֲחִידָא כֹּלָּא. כְּדוּגְמָא דָּא תָּנִינָן, כָּל דְּאַשְׁלִים לַעֲשָׂרָה קַדְמָאֵי דְּבֵי כְּנִישְׁתָּא, נוֹטֵל אֲגַר כֻּלְּהוּ. ר' יוֹסֵי אוֹמֵר, לָקֳבְלֵי דְּכֻלְּהוּ.","ר' יִצְחָק אָמַר, כְּתִיב (שמואל ב כ״ב:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד, וּכְתִיב וַיֵּרַד יְיָ' לְעֵינֵי כָל הָעָם עַל הַר סִינַי, (ד\"א לא גרסינן תנא) וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן נָחַת. אִי תֵּימָא דְּנָחַת לְסִינַי, עַל הַר סִינַי כְּתִיב וְלָא כְּתִיב בְּהַר סִינַי.","אֶלָּא, וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן נָחַת. אָמַר ר' יוֹסֵי, (אמר רבי יהודה אמר רבי חייא) נָחִית בְּדַרְגּוֹי, מִדַּרְגָּא לְדַרְגָּא, וּמִכִּתְרָא לְכִתְרָא, עַד דְּאִתְדַּבָּק בְּהַאי אֶרֶץ, וּכְדֵין אִתְנְהַר סִיהֲרָא, וְקַיְּימָא בְּאַשְׁלָמוּתָא. הֲדָא הוּא דִכְתִיב וַיֵּט שָׁמַיִם וַיֵּרַד, לְהַאי אֶרֶץ. וּכְדֵין כְּתִיב, עַל הַר סִינַי. מַה קַּיְימָא עַל הַר סִינַי, הֲוֵי אֵימָא דָּא שְׁכִינְתָּא.","ר' אַבָּא אָמַר מֵהָכָא, (שמות י״ט:י״ח) מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ' בָּאֵשׁ. וּכְתִיב (דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. וּכְתִיב, (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. וַיְיָ' הִמְטִיר דָּא הוּא אֶרֶץ מֵאָן אֲתָר נָטִיל הַאי, סוֹפְיֵהּ דִּקְרָא מוֹכַח, דִּכְתִּיב מֵאֵת יְיָ' מִן הַשָּׁמָיִם, מִן הַשָּׁמָיִם מַמָּשׁ. רַבִּי חִיָּיא אָמַר מֵהָכָא, וַיְדַבֵּר אֱלהִים אֵת כָּל. כָּל, כְּלָלָא דְּכֹלָּא, דְּהָא בְּהַאי תַּלְיָא כֹּלָּא.","(שמות כ׳:ג׳) לֹא יִהְיֶה לְךָ אֱלהִים אֲחֵרִים עַל פָּנָי. רַבִּי יִצְחָק אָמַר, אֱלהִים אֲחֵרִים, לְאַפָּקָא שְׁכִינְתָּא. עַל פָּנָי, לְאַפָּקָא אַפֵּי מַלְכָּא. דִּבְהוּ אִתְחָזֵי מַלְכָּא קַדִּישָׁא, וְאִינּוּן שְׁמֵיהּ. וְהוּא אִינּוּן. הוּא שְׁמֵיהּ, דִּכְתִּיב, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי. הוּא וּשְׁמֵיהּ חַד הוּא בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא.","תָּאנֵי רַבִּי שִׁמְעוֹן, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרָא לוֹן אָדָם, דִּכְתִּיב, (יחזקאל לה) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם. מַאי טַעֲמָא קָרָא לוֹן אָדָם. מִשּׁוּם דִּכְתִּיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלהֵיכֶם. אַתֶּם וְלֹא שְׁאַר עַמִּין. וּבְּגִין כָּךְ אָדָם אַתֶּם, אַתֶּם קְרוּיִין אָדָם, וְאֵין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת קְרוּיִין אָדָם.","דְּתַנְיָא, אָמַר ר' שִׁמְעוֹן, כֵּיוָן דְּבַר נָשׁ יִשְׂרָאֵל אִתְגְּזַר, עָאל בִּבְרִית דְּגָזַר קוּדְשָׁא בְּרִיךְ הוּא בְּאַבְרָהָם, דִּכְתִּיב (בראשית כ״ד:א׳) וַיְיָ' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וּכְתִיב (מיכה ז׳:כ׳) חֶסֶד לְאַבְרָהָם. וְשָׁארֵי לְמֵיעָאל בְּהַאי אֲתָר. (נ\"א אדם) כֵּיוָן דְּזָכָה לְקַיְּימָא פִּקּוּדֵי אוֹרַיְיתָא, עָאל בֵּיהּ בְּהַאי אָדָם, (נ\"א אתר) וְאִתְדַּבַּק (ויחי רי\"ו ע\"א) בְּגוּפָא דְּמַלְכָּא, וּכְדֵין אִקְרֵי אָדָם.","וְזַרְעָא דְּיִשְׂרָאֵל אִקְרוּן אָדָם. תָּא חֲזֵי, כְּתִיב בֵּיהּ בְּיִשְׁמָעֵאל, (בראשית טז) וְהוּא יִהְיֶה פֶּרֶא אָדָם. פֶּרֶא אָדָם, וְלֹא אָדָם. פֶּרֶא אָדָם, מִשּׁוּם דְּאִתְגְּזַר. וְשֵׁירוּתָא דְּאָדָם הֲוָה בֵּיהּ, דִּכְתִּיב, (בראשית י״ז:כ״ה) וְיִשְׁמָעֵאל בְּנוֹ בֶּן שְׁלשׁ עֶשְׂרֵה שָׁנָה בְּהִמּוֹלוֹ אֵת בְּשַׂר עָרְלָתוֹ, כֵּיוָן דְּאִתְגְּזַר, עָאל בְּהַאי שֵׁירוּתָא, דְּאִקְרֵי כָּל. הֲדָא הוּא דִכְתִיב, (בראשית ט״ז:י״ב) וְהוּא יִהְיֶה פֶּרֶא אָדָם, וְלֹא אָדָם. יָדוֹ בַכֹּל, יָדוֹ בַכֹּל וַדַּאי, וְלָא יַתִּיר, מִשּׁוּם דְּלָא קַבִּיל פִּקּוּדֵי אוֹרַיְיתָא. שֵׁירוּתָא הֲוָה בֵּיהּ, בְּגִין דְּאִתְגְּזַר, וְלָא אִשְׁתְּלִים בְּפִקּוּדֵי אוֹרַיְיתָא. אֲבָל זַרְעָא דְּיִשְׂרָאֵל, דְּאִשְׁתְּלִימוּ בְּכֹלָּא, אִקְרוּן אָדָם מַמָּשׁ, וּכְתִיב (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","אָמַר רִבִּי יוֹסֵי, בְּגִין דָּא, כָּל פַּרְצוּפִין שָׁרוּ, בַּר מִפַּרְצוּפָא דְּאָדָם. ר' יִצְחָק אָמַר, כַּד אִתְעֲבָד, אִתְחָזֵי דִּגְלִיפָא גּוֹ גְּלִיפִין דְּאַשְׁלָמוּתָא. אָמַר רִבִּי יְהוּדָה, הַיְינוּ דְּאַמְרֵי אִינְשֵׁי קִיטְרוֹי בְּזִיקָא, בְּטִפְסָא שְׁכִיחֵי.","רַבִּי יְהוּדָה הֲוָה אָזִיל מִקַּפּוּטְקִיָּא לְלוּד, לְמֵחֱמֵי לְרַבִּי שִׁמְעוֹן, דְּהֲוָה תַּמָּן, וַהֲוָה רַבִּי חִזְקִיָּה אָזִיל עִמֵּיהּ. אָמַר רַבִּי יְהוּדָה לְרַ' חִזְקִיָּה, הָא דְּתָנֵינָן, קָמֵי ר' שִׁמְעוֹן, וְהוּא יִהְיֶה פֶּרֶא אָדָם, וַדַּאי כַּךְ הוּא. וְדָא הוּא בְּרִירָא דְּמִלָּה. סוֹפְיֵהּ דִּקְרָא דִּכְתִּיב, וְעַל פְּנֵי כָל אֶחָיו יִשְׁכּוֹן. מַהוּ וְעַל פְּנֵי כָל אֶחָיו יִשְׁכּוֹן."],[[0,"ומרישא דמלכא וכו':","ומראש המלך, שהוא הג\"ר דז\"א, עד מקום ההוא ששורה צדיק הזה, שהוא יסוד דז\"א, בא ונמשך נהר אחד קדוש של שמן המשחה ומטיל בחשק גדול בארץ הזו, שהיא המלכות. וארץ הזו לוקחת הכל, ואח\"כ מארץ הזו ניזונים הכל, עליונים ותחתונים. כדכורא הזה, כשחשקו להתדבק בנוקבא, שמוציא זרע של רביה מראש המוח, באמה ההוא ומטיל אל הנוקבא, שממנו מתעברת הנוקבא, ונמצא שכל איברי הגוף כולם מתדבקים בנוקבא, והנוקבא לוקחת הכל. כדמיון הזה, למדנו, כל המשלים את עשרה הראשונים בבית הכנסת לוקח שכר כולם, ר' יוסי אומר, כנגד כולם. כי עשרה ראשונים הם כנגד עשר ספירות, והמשלים הוא כנגד המלכות, שהמלכות שהיא הנוקבא, לוקחת הכל. כנ\"ל."],[1,"ר' יצחק אמר וכו':","ר' יצחק אמר, כתוב, ויט שמים וירד ובתורה כתוב, וירד ה' לעיני כל העם על הר סיני, ולפי זה, ויט שמים וירד, לאן ירד, ואם תאמר שירד לסיני, כבכתוב שבתורה, הרי על הר סיני כתוב, ולא כתוב בהר סיני."],[2,"אלא ויט שמים וגו':","ומשיב, אלא ויט שמים וירד, לאן נחת, אמר ר' יוסי, ירד במדרגותיו ממדרגה למדרגה מכתר לכתר עד שנתדבק בארץ הזו, שהיא המלכות, ואז הלבנה שהיא המלכות, האירה ועמדה במלואה. ז\"ש, ויט שמים וירד, לארץ הזו. ואז כתוב, על הר סיני. מי עמדה על הר סיני, הוי אומר, השכינה. וירד אל השכינה."],[3,"ר' אבא אמר וכו':","רא\"א, מכאן נשמע שירד אל השכינה. כתוב, מפני אשר ירד עליו ה' באש, וכתוב, כי ה' אלקיך אש אוכלה הוא, דהיינו השכינה. הרי שירד אל השכינה. ומקשה, וכתוב, וה' המטיר על סדום ועמורה גפרית ואש מאת ה' מן השמים. הרי שז\"א עצמו הוא אש שממנו ירד על סדום. ומשיב, וה' המטיר זה ארץ, שהיא השכינה. כי והויה יורה על הוא ובית דינו שהיא השכינה, (כנ\"ל בשלח דף י\"ג אות נ\"ב) וממנה נמשך האש על סדום. אלא מאיזה מקום לקחה זה, מוכיח סוף המקרא, שכתוב מאת ה' מן השמים, מן השמים ממש שהוא ז\"א. שכל מה שיש לשכינה מקבלת מן ז\"א. ר' חייא אמר, מכאן נשמע שירד ונתחבר עם השכינה. וידבר אלקים את כל. אלקים הוא השכינה, \u0003כל\u0004, היינו כלל הכל שהוא ז\"א, כי בזה, בז\"א, תלוים הכל. הרי שז\"א ירד ונתחבר עם השכינה."],[4,"לא יהיה לך אלהים אחרים על פני:","ר' יצחק אמר \u0003אלהים אחרים\u0004 להוציא השכינה. שלא יהיה לך אלהים אחרים במקום השכינה שנקראת אלקים. \u0003על פני,\u0004 להוציא פני המלך, שבהם נראה המלך הקדוש, והם שמו, ושמו הם, שהפנים הנראים הם שמו, שהוא המלכות, ושמו הוא הפנים הנראים. הוא שמו ז\"א הוא שמו, כלומר שהם אחד, שכתוב, אני הויה הוא שמי. הוא ושמו אחד הוא. ברוך שמו לעולם ולעלמי עולמים."],[5,"תאני ר' שמעון וכו':","תאני ר\"ש, אשרי הם ישראל, שהקב\"ה קראם אדם, שכתוב, ואתן צאני צאן מרעיתי אדם אתם. וכן, אדם כי יקריב מכם. מה הטעם שקראם אדם, הוא משום שכתוב, ואתם הדבקים בה' אלקיכם. אתם, ולא שאר עמים עכו\"ם, ומשום זה אדם אתם, אתם קרואים אדם ואין עכו\"ם קרואים אדם."],[6,"דתניא אמר ר' שמעון וכו':","שלמדנו, אר\"ש, כיון שאדם מישראל נימול נכנס בברית שכרת הקב\"ה עם אברהם, שכתוב, וה' ברך את אברהם בכל. וכתוב, חסד לאברהם, והתחיל להכנס במקום הזה, כיון שזכה לקיים מצות התורה נכנס בו באדם הזה, של המרכבה העליונה, ונתדבק בגוף המלך, ואז נקרא \u0003אדם.\u0004"],[7,"וזרעא דישראל אקרון וכו':","וזרע ישראל נקראים אדם. בוא וראה, כתוב בו בישמעאל, והוא יהיה פרא אדם. פרא אדם ולא אדם, פרא אדם נקרא משום שנמול, והתחלה של אדם היתה בו, שכתוב, וישמעאל בנו בן שלש עשרה שנה בהמולו בשר ערלתו. כיון שנמול נכנס בהתחלה זו שנקרא \u0003כל,\u0004 שהוא יסוד. ז\"ש והוא יהיה פרא אדם. ולא אדם. ידו \u0003בכל,\u0004 בכל ודאי ולא יותר, משום שלא קיבל מצות התורה, התחלה היתה בו משום שנמול, אבל לא נשלם במצות התורה. אבל זרע ישראל שנשלמו בכל נקראים אדם ממש, וכתוב, כי חלק ה' עמו יעקב חבל נחלתו."],[8,"א\"ר יוסי וכו':","אר\"י, משום זה כל צורת פנים מותר לעשות חוץ מפני אדם. ר' יצחק אמר, כשנעשה צורת אדם, נראה שחקוק תוך חקיקות של השלמות. דהיינו שניכר בה שלמות מיוחדת. א\"ר יהודה, היינו שאומרים אנשים, קשריו עם הרוח נמצא בצורה, שבצורת אדם הנעשה, ניכר קשריו עם הרוח שבו."],[9,"ר' יהודה הוה וכו':","ר\"י היה הולך מקפוטקיא ללוד, לראות את ר' שמעון שהיה שם. ור' חזקיה היה הולך עמו. אמר ר' יהודה לר' חזקיה זה שלמדנו לפני ר' שמעון, והוא יהיה פרא אדם, ודאי כך הוא, וזה הוא בירורו של הדבר, אבל סוף הכתוב שכתוב, ועל פני כל אחיו ישכון, מהו ועל פני כל אחיו ישכון."]],[[0,"","וּמֵרֹאשׁ הַמֶּלֶךְ עַד אוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה הַצַּדִּיק הַזֶּה, בָּא נָהָר אֶחָד קָדוֹשׁ, שֶׁמֶן מִשְׁחָה, וּמַטִּיל בְּרֹב תְּשׁוּקָה בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, וְהָאָרֶץ הַזּוֹ נוֹטֶלֶת הַכֹּל, וְאַחַר כָּךְ מֵהָאָרֶץ הַזּוֹ הַכֹּל נִזּוֹנִים, עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ הַזָּכָר הַזֶּה כְּשֶׁתְּשׁוּקָתוֹ לְהִדָּבֵק בִּנְקֵבָה, שֶׁמּוֹצִיא זֶרַע שֶׁל רְבִיָּה מֵרֹאשׁ הַמֹּחַ בְּאוֹתָהּ אַמָּה וּמַטִּיל בַּנְּקֵבָה וּמִמֶּנּוּ הַנְּקֵבָה מִתְעַבֶּרֶת. נִמְצָא שֶׁכָּל אֵיבְרֵי הַגּוּף כֻּלָּם נִדְבָּקִים בַּנְּקֵבָה, וְהַנְּקֵבָה אוֹחֶזֶת הַכֹּל. כְּדֻגְמָה זוֹ שָׁנִינוּ, כָּל הַמַּשְׁלִים לַעֲשָׂרָה רִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת, נוֹטֵל שְׂכַר כֻּלָּם. רַבִּי יוֹסֵי אָמַר, כְּנֶגֶד כֻּלָּם."],[1,"","רַבִּי יִצְחָק אָמַר, כָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד, וְכָתוּב יֵרֵד ה' לְעֵינֵי כָל הָעָם עַל הַר סִינָי. (לא גורסים תנא) וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן יָרַד? אִם תֹּאמַר שֶׁיָּרַד לְסִינַי, הֲרֵי כָּתוּב עַל הַר סִינָי, וְלֹא כָתוּב בְּהַר סִינַי?"],[2,"","אֶלָּא וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן יָרַד? אָמַר רַבִּי יוֹסֵי (אמר רבי יהודה אמר רבי חייא), יָרַד בְּדַרְגוֹתָיו מִדַּרְגָּה לְדַרְגָּה וּמִכֶּתֶר לְכֶתֶר עַד שֶׁנִּדְבַּק בָּאָרֶץ הַזּוֹ, וְאָז הֵאִירָה הַלְּבָנָה וְעָמְדָה בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב וַיֵּט שָׁמַיִם וַיֵּרַד, לָאָרֶץ הַזּוֹ. וְאָז כָּתוּב עַל הַר סִינָי. מֶה עָמַד עַל הַר סִינַי? הֱוֵה אוֹמֵר זוֹ שְׁכִינָה."],[3,"","רַבִּי אַבָּא אָמַר מִכָּאן, (שמות יט) מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ. וְכָתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא. וְכָתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. וַה' הִמְטִיר - זוֹהִי אֶרֶץ. מֵאֵיזֶה מָקוֹם נָטַל אֶת זֶה? סוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם, מִן הַשָּׁמַיִם מַמָּשׁ. רַבִּי חִיָּיא אָמַר מִכָּאן, וַיְדַבֵּר אֱלֹהִים אֵת כָּל, כָּל - הַכְּלָל שֶׁל הַכֹּל, שֶׁהֲרֵי בָּזֶה תָּלוּי הַכֹּל."],[4,"","לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. רַבִּי יִצְחָק אָמַר, אֱלֹהִים אֲחֵרִים - לְהוֹצִיא שְׁכִינָה. עַל פָּנָי - לְהוֹצִיא פְּנֵי הַמֶּלֶךְ שֶׁבָּהֶם נִרְאֶה הַמֶּלֶךְ הַקָּדוֹשׁ, וְהֵם שְׁמוֹ, וְהוּא הֵם. הוּא שְׁמוֹ, שֶׁכָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי. הוּא וּשְׁמוֹ אֶחָד הוּא. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[5,"","שָׁנָה רַבִּי שִׁמְעוֹן, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לָהֶם אָדָם, שֶׁכָּתוּב (יחזקאללד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם. מָה הַטַּעַם קָרָא לָהֶם אָדָם? מִשּׁוּם שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם. אַתֶּם וְלֹא לִשְׁאָר עַמִּים. וּמִשּׁוּם כָּךְ אָדָם אַתֶּם. אַתֶּם קְרוּיִים אָדָם, וְאֵין עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת קְרוּיִים אָדָם."],[6,"","שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כֵּיוָן שֶׁאָדָם מִיִּשְׂרָאֵל נִמּוֹל, נִכְנָס לַבְּרִית שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא עִם אַבְרָהָם, שֶׁכָּתוּב (בראשיתכד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְכָתוּב (מיכה ז) חֶסֶד לְאַבְרָהָם. וְהִתְחִיל לְהִכָּנֵס לַמָּקוֹם הַזֶּה. (אדם) כֵּיוָן שֶׁזָּכָה לְקַיֵּם מִצְווֹת הַתּוֹרָה, נִכְנָס לָאָדָם (למקום) וְנִדְבָּק בְּגוּף הַמֶּלֶךְ, וְאָז נִקְרָא אָדָם."],[7,"","וְזֶרַע יִשְׂרָאֵל נִקְרְאוּ אָדָם. בֹּא וּרְאֵה, כָּתוּב בְּיִשְׁמָעֵאל וְהוּא יִהְיֶה פֶּרֶא אָדָם. פֶּרֶא אָדָם, וְלֹא אָדָם. פֶּרֶא אָדָם, מִשּׁוּם שֶׁנִּמּוֹל, וְרֵאשִׁיתוֹ שֶׁל אָדָם הָיָה בּוֹ, שֶׁכָּתוּב (בראשית יז) וְיִשְׁמָעֵאל בְּנוֹ בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה בְּהִמֹּלוֹ אֵת בְּשַׂר עָרְלָתוֹ. כֵּיוָן שֶׁנִּמּוֹל נִכְנַס לָרֵאשִׁית הַ את שֶׁנִּקְרֵאת כֹּל. זֶהוּ שֶׁכָּתוּב וְהוּא יִהְיֶה פֶּרֶא אָדָם, וְלֹא אָדָם. יָדוֹ בַכֹּל, יָדוֹ בַכֹּל וַדַּאי - וְלֹא יוֹתֵר, מִשּׁוּם שֶׁלֹּא קִבֵּל מִצְווֹת הַתּוֹרָה. רֵאשִׁית הָיְתָה בּוֹ מִשּׁוּם שֶׁנִּמּוֹל, וְלֹא הִשְׁתַּלֵּם בְּמִצְווֹת הַתּוֹרָה. אֲבָל זֶרַע יִשְׂרָאֵל שֶׁנִּשְׁלְמוּ בַכֹּל, נִקְרְאוּ אָדָם מַמָּשׁ, וְכָתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[8,"","אָמַר רַבִּי יוֹסֵי, מִשּׁוּם כָּךְ כָּל הַפַּרְצוּפִים מֻתָּרִים, פְּרָט לְפַרְצוּף אָדָם. רַבִּי יִצְחָק אָמַר, כְּשֶׁנַּעֲשֶׂה, נִרְאֶה שֶׁחָקוּק תּוֹךְ הַחֲקִיקוֹת שֶׁל הַשְּׁלֵמוּת. אָמַר רַבִּי יְהוּדָה, הַיְנוּ מַה שֶּׁאֲנָשִׁים אוֹמְרִים, קְשָׁרָיו בָּרוּחַ מְצוּיִים בַּצּוּרָה."],[9,"","רַבִּי יְהוּדָה הָיָה הוֹלֵךְ מִקַּפּוּטְקִיָּא לְלוֹד לִרְאוֹת אֶת רַבִּי שִׁמְעוֹן שֶׁהָיָה שָׁם, וְהָיָה רַבִּי חִזְקִיָּה הוֹלֵךְ עִמּוֹ. אָמַר רַבִּי יְהוּדָה לְרַבִּי חִזְקִיָּה, זֶה שֶּׁשָּׁנִינוּ לִפְנֵי רַבִּי שִׁמְעוֹן וְהוּא יִהְיֶה פֶּרֶא אָדָם - וַדַּאי כָּךְ הוּא. וְזֶהוּ בֵּרוּר הַדָּבָר - סוֹף הַפָּסוּק, שֶׁכָּתוּב וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. מַה זֶּה וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן?"]]],[["אָמַר לֵיהּ, לָא שְׁמַעְנָא, וְלָא אֵימָא. דְּהָא אוֹלִיפְנָא, כְּתִיב (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. אֲשֶׁר שָׂם מֹשֶׁה, אַתָּה יָכוֹל לוֹמַר. דְּלָא שָׂם מֹשֶׁה, אִי אַתָּה יָכוֹל לוֹמַר.","פָּתַח ר' יְהוּדָה וְאָמַר, (דברים ל׳:כ׳) כִּי הוּא חַיֶּיךָ וְאֹרֶךְ יָמֶיךָ. מַאן דְּזָכֵי בְּאוֹרַיְיתָא, וְלָא אִתְפְּרַשׁ מִינָהּ, זָכֵי לִתְרֵין חַיִּין, חַד בְּעָלְמָא דֵּין, וְחַד בְּעָלְמָא דְּאָתֵי. דִּכְתִּיב חַיֶּיךָ, תְּרֵי. וְכָל מַאן דְּיִתְפְּרַשׁ מִינָהּ, כְּמַאן דְּמִתְפְּרַשׁ מִן חַיֵּי, וּמַאן דְּמִתְפְּרַשׁ מֵר' שִׁמְעוֹן, כְּאִילּוּ מִתְפְּרַשׁ מִכֹּלָּא.","וּמַה בְּהַאי קְרָא דְּאִיהוּ פָּתַח פִּתְחָא, לָא יָכִילְנָא לְמֵיעָאל בָּהּ. פִּתְגָּמֵי אוֹרַיְיתָא דִּסְתִּימִין, עַל אַחַת כַּמָּה וְכַמָּה. וַוי לְדָרָא, דְּר' שִׁמְעוֹן בֶּן יוֹחָאי יִסְתְּלִיק מִנֵּיהּ. דְּכַד אֲנָן קַיְימִין קָמֵי דְּר' שִׁמְעוֹן, מַבּוּעִין דְּלִבָּא פְּתִיחִין לְכָל עִיבָר, וְכֹלָּא מִתְגַּלְיָא. וְכַד אִתְפְּרַשְׁנָא מִנֵּיהּ. לָא יְדַעְנָא מִידִי, וְכָל מַבּוּעִין סְתִימִין.","אָמַר ר' חִזְקִיָּה, הַיְינוּ דִּכְתִּיב, (במדבר י״א:כ״ה) וַיָּאצֶל מִן הָרוּחַ אֲשֶׁר עָלָיו וְיִתֵּן עַל שִׁבְעִים אִישׁ הַזְּקֵנִים, כְּבוּצִינָא דָּא, דְּנָהֲרִין מִינֵּהּ כַּמָּה בּוּצִינִין, וְהוּא בְּקִיוּמֵיהּ שְׁכִיחַ. כַּךְ ר' שִׁמְעוֹן בֶּן יוֹחָאי, מָארֵי דְּבוּצִינִין, הוּא נָהִיר לְכֹלָּא, וּנְהוֹרָא לָא אַעְדֵּי מִנֵּיהּ, וְאִשְׁתְּכַח בְּקִיוּמֵיהּ. אָזְלוּ עַד דְּמָטוּ לְגַבֵּיהּ.","כַּד מָטוּ גַּבֵּיהּ, אַשְׁכְּחוּהוּ, דְּהֲוָה יָתִיב וְלָעֵי בְּאוֹרַיְיתָא, וַהֲוָה אָמַר, (תהילים ק״ב:א׳) תְּפִלָּה לְעָנִי כִּי יַעֲטֹף וְלִפְנֵי יְיָ' יִשְׁפּוֹךְ שִׂיחוֹ. כָּל צְלוֹתָא דְּיִשְׂרָאֵל צְלוֹתָא, וּצְלוֹתָא דְּעָנִי עִלָּאָה מִכֻּלְּהוּ. מַאי טַעֲמָא. מִשּׁוּם דְּהַאי סַלְּקָא עַד כּוּרְסֵי יְקָרָא דְּמַלְכָּא, וְאִתְעַטָּר בְּרֵישֵׁיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתָּבַּח (נ\"א מתעטף) בְּהַהִיא צְלוֹתָא וַדַּאי. תְּפִלָּה דְּעָנִי, תְּפִלָּה אִקְרֵי.","כִּי יַעֲטֹף. עִטּוּפָא דָּא, לָאו עִטּוּפָא דְּכַסוּ הוּא, דְּהָא לֵית לֵיהּ. אֶלָּא, כְּתִיב הָכָא כִּי יַעֲטֹף. וּכְתִיב הָתָם, (איכה ב׳:י״ט) הָעֲטוּפִים בְּרָעָב. וְלִפְנֵי יְיָ' יִשְׁפֹּךְ שִׂיחוֹ, דְּיִקְבַּל קַמֵּי מָארֵיהּ, וְדָא נִיחָא לֵיהּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, מִשּׁוּם דְּעָלְמָא מִתְקַיְּימָא בֵּיהּ, כַּד לָא אִשְׁתְּכָחוּ שְׁאַר קַיְימֵי עָלְמָא בְּעָלְמָא. וַוי לְמַאן דְּהַהוּא מִסְכְּנָא יְקַבֵּל עֲלוֹהִי לְמָארֵיהּ, מִשּׁוּם דְּמִסְכְּנָא קָרִיב לְמַלְכָּא יַתִּיר מִכֻּלְּהוּ, דִּכְתִּיב, (שמות כ״ב:כ״ו) וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אֲנִי.","וְלִשְׁאַר בְּנֵי עָלְמָא, זִמְנִין דִּשְׁמַע, זִמְנִין דְּלָא שָׁמַע. מַאי טַעְמָא. מִשּׁוּם דְּדִיוּרֵיהּ דְּמַלְכָּא בְּהָנֵי מָאנִי תְּבִירֵי, דִּכְתִּיב, (ישעיהו נ״ז:ט״ו) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וּכְתִיב (תהלים לה) קָרוֹב יְיָ' לְנִשְׁבְּרֵי לֵב. (תהילים נ״א:י״ט) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לא תִבְזֶה.","מִכָּאן תָּנֵינָן, מַאן דְּנָזִיף בְּמִסְכְּנָא, נָזִיף בִּשְׁכִינְתָּא, דִּכְתִּיב וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וּכְתִיב (משלי כ״ב:כ״ג) כִּי יְיָ' יָרִיב רִיבָם וְגוֹ'. בְּגִין דְּאַפּוֹטְרוֹפָּא דִּלְהוֹן תַּקִּיפָא, וְשַׁלִּיטָא עַל כֹּלָּא, דְּלָא אִצְטְרִיךְ סַהֲדֵי, וְלָא אִצְטְרִיךְ לְדַיָּינָא אַחֲרָא, וְלָא נָטִיל מַשְׁכּוֹנָא, כִּשְׁאַר דַּיָּינָא. וּמַה מַשְׁכּוֹנָא נָטִיל, נִשְׁמָתִין דְּבַר נָשׁ, דִּכְתִּיב וְקָבַע אֶת קוֹבְעֵיהֶם נָפֶשׁ.","תּוּ אָמַר תְּפִלָּה לְעָנִי, כָּל אֲתָר דְּאִקְרֵי תְּפִלָּה, מִלָּה עִלָּאָה הִיא, דְּהִיא סַלְּקָא לַאֲתָר (דקודשא בריך הוא אחד) עִלָּאָה. תְּפִלָּה דְּרֵישָׁא, אִינּוּן תְּפִלֵי דְּמַלְכָּא, דְּאָנַח לְהוּ.","ר' שִׁמְעוֹן אַסְחַר רֵישֵׁיהּ, וְחָמָא לְרַ' יְהוּדָה וּלְר' חִזְקִיָּה, דְּמָטוּ גַּבֵּיהּ. בָּתַר דְּסִיֵּים אִסְתָּכַּל בְּהוּ. אָמַר לְהוּ, סִימָא הֲוָה לְכוּ וְאִתְאֲבִיד מִנַּיְיכוּ. אָמְרוּ לֵיהּ, וַדַּאי דְּפִתְחָא עִלָּאָה פָּתַח מֹר, וְלָא יָכִילְנָא לְמֵיעָאל בָּהּ.","אָמַר, מַאי הִיא. אָמְרוּ לֵיהּ, (בראשית ט״ז:י״ב) וְהוּא יִהְיֶה פֶּרֶא אָדָם, וְסוֹפְיֵהּ דִּקְרָא בָּעֵינָא לְמִנְדַּע, דִּכְתִּיב וְעַל פְּנֵי כָל אֶחָיו יִשְׁכּוֹן, מַהוּ עַל פְּנֵי כָל אֶחָיו. דְּהָא בְּרִירָא דְּכוּלֵיהּ קְרָא יְדַעְנָא, וְהַאי לָא יְדַעְנָא, דְּסֵיפֵיהּ דִּקְרָא, לָא אִתְחָזֵי כְּרִישֵׁיהּ.","אָמַר לוֹן, חַיֵּיכוֹן, כֹּלָּא חַד מִלָּה הִיא, וּבְחַד דַּרְגָּא סַלְּקָא. תָּאנָא, כַּמָּה פָּנִים לַפָּנִים, אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. פָּנִים דְּנַהֲרִין. פָּנִים דְּלָא נַהֲרִין. פָּנִים תַּתָּאִין. פָּנִים רְחִיקִין. פָּנִים קְרִיבִין. פָּנִים דִּלְגוֹ. פָּנִים דִּלְבַר. פָּנִים דִּימִינָא. פָּנִים דִּשְׂמָאלָא."],[[0,"אמר ליה לא וכו':","א\"ל לא שמעתי ולא אומר. כי למדנו, וזאת התורה אשר שם משה. אשר שם משה אתה יכול לומר, שלא שם משה, דהיינו שלא שמע מרבו, אין אתה יכול לומר."],[1,"פתח ר' יהודה וכו':","פר\"י ואמר, כי הוא חייך ואורך ימיך. מי שזכה בתורה ולא נפרד ממנה, זוכה לשני חיים, אחד בעולם הזה, ואחד בעולם הבא, שכתוב, חייך לשון רבים, שהם שנים. וכל מי שנפרד ממנה, הוא כמו שנפרד מן החיים. ומי שנפרד מן ר' שמעון כאלו נפרד מכל."],[2,"ומה בהאי קרא וכו':","ומה במקרא הזה שהוא פתח בו פתח לא יכולנו לכנוס בה. דברי תורה הסתומים על אחת כמה וכמה. אוי לדור שר' שמעון יסתלק ממנו. כי כשאנו עומדים לפני ר' שמעון, מבועי הלב פתוחים לכל עיבר, והכל מתגלה, וכשנפרדנו ממנו אין אנו יודעים כלום, וכל המבועים סתומים."],[3,"אמר ר' חזקיה וכו':","אר\"ח, היינו שכתוב, ויאצל מן הרוח אשר עליו ויתן על שבעים איש הזקנים, כנר הזה שמאירים ממנו כמה נרות, והוא נמצא על שלמותו, שלא נחסר ממנו כלום מחמת שהדליקו ממנו הנרות. כך ר' שמעון בן יוחאי בעל הנרות, הוא מאיר לכל, והאור לא סר ממנו ונמצא על שלמותו. הלכו עד שהגיעו אצלו."],[4,"כד מטו לגביה וכו':","כשהגיעו אצלו מצאוהו שהיה יושב ועוסק בתורה, והיה אומר, תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו. כל התפלות של ישראל הם תפלה, ותפלת העני עליונה מכולם. מה הטעם. משום שזו עולה עד כסא הכבוד של המלך ונתעטרה בראשו. והקב\"ה משתבח בתפלה ההוא, בודאי, ע\"כ תפלה של עני נקרא תפלה."],[5,"כי יעטוף:","עטוף זה אינו עטוף של כסות, שהרי אין לו כסות, אלא כתוב כאן כי יעטוף, וכתוב שם העטופים ברעב. אף כאן, כי יעטוף הוא ברעב. \u0003ולפני ה' ישפוך שיחו,\u0004 שיצעק לפני אדונו. וזה נוח לו לפני הקב\"ה, משום שהעולם מתקיים בו, בשעה שלא נמצא מקיימי עולם אחרים בעולם. אוי למי, שעני ההוא יצעק עליו לאדונו, משום שהעני קרוב אל המלך יותר מכולם, שכתוב, והיה כי יצעק אלי ושמעתי כי חנון אני."],[6,"ולשאר בני עלמא וכו':","ולשאר בני העולם, פעמים ששומע ופעמים שאינו שומע. מה הטעם. הוא משום שמשכנו של הקב\"ה הוא באלו כלים השבורים, שכתוב, ואת דכא ושפל רוח. וכתוב, קרוב ה' לנשברי לב. לב נשבר ונדכה אלקים לא תבזה."],[7,"מכאן תנינן וכו':","מכאן למדנו, מי שגוער בעני גוער בשכינה, שכתוב, ואת דכא ושפל רוח. וכתוב, כי ה' יריב ריבם וגו'. כי האפטרופוס שלהם הוא גבור ושולט על כל, שאין צריך לעדים, ואינו צריך לדיין אחר, ואינו מקבל משכון כשאר הדיינים, ואיזה משכון הוא מקבל, היינו נשמות של בני אדם, שכתוב, וקבע את קובעיהם נפש."],[8,"תו אמר תפלה וכו':","עוד אמר. תפלה לעני, כל מקום שנקרא תפלה, הוא דבר עליון, שהיא עולה למקום עליון. תפלה של ראש, הם התפלין שהמלך מניח אותם. דהיינו מוחין דז\"א, הנקראים תפלה של ראש."],[9,"ר' שמעון אסחר וכו':","החזיר ר' שמעון ראשו, וראה את ר' יהודה ור' חזקיה שבאו אצלו. אחר שסיים, דברי תורה שלו, הסתכל בהם. אמר להם אוצר היה לכם ונאבד מכם. דהיינו ששמעו דברי תורה ושכחו אותם. אמרו לו ודאי שפתח עליון פתח אדוני, ואין אנו יכולים להכנס בו."],[10,"אמר מאי היא וכו':","אמר. מה הוא. אמרו לו, והוא יהיה פרא אדם, וסוף המקרא אנו רוצים לדעת, שכתוב, ועל פני כל אחיו ישכון, מהו, על פני כל אחיו. כי בירורו של כל המקרא אנו יודעים וזה אין אנו יודעים, כי סוף המקרא אינו נראה כראשו."],[11,"אמר לון חייכון וכו':","אמר להם, חייכם שהכל הוא דבר אחד, ובמדרגה אחת עולה. למדנו, כמה פנים לפנים יש להקב\"ה. יש פנים המאירים, פנים שאינם מאירים, פנים תחתונים, פנים רחוקים, פנים קרובים, פנים שבפנים, פנים שבחוץ, פנים של ימין, פנים של שמאל."]],[[0,"","אָמַר לוֹ, לֹא שָׁמַעְתִּי וְלֹא אֹמַר, שֶׁהֲרֵי לָמַדְנוּ, כָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. אֲשֶׁר שָׂם מֹשֶׁה - אַתָּה יָכוֹל לוֹמַר. אֲבָל שֶׁלֹּא שָׂם מֹשֶׁה - אֵינְךְ יָכוֹל לוֹמַר."],[1,"","פָּתַח רַבִּי יְהוּדָה וְאָמַר, (שם) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ. מִי שֶׁזּוֹכֶה בַּתּוֹרָה וְלֹא נִפְרָד מִמֶּנָּה, זוֹכֶה לִשְׁנֵי חַיִּים - אֶחָד בָּעוֹלָם הַזֶּה, וְאֶחָד בָּעוֹלָם הַבָּא, שֶׁכָּתוּב חַיֶּיךְ, שְׁנַיִם. וְכָל מִי שֶׁנִּפְרָד מִמֶּנָּה, כְּמִי שֶׁנִּפְרָד מִן הַחַיִּים, וּמִי שֶׁנִּפְרָד מֵרַבִּי שִׁמְעוֹן, כְּאִלּוּ נִפְרָד מֵהַכֹּל."],[2,"","וּמַה בַּפָּסוּק הַזֶּה שֶׁהוּא פּוֹתֵחַ פֶּתַח לֹא יָכֹלְנוּ לְהִכָּנֵס אֵלָיו - דִּבְרֵי תוֹרָה הַנִּסְתָּרִים עַל אַחַת כַּמָּה וְכַמָּה. אוֹי לַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי יִסְתַּלֵּק מִמֶּנּוּ. שֶׁכְּשֶׁאָנוּ עוֹמְדִים לִפְנֵי רַבִּי שִׁמְעוֹן, מַעַיְנוֹת הַלֵּב פְּתוּחִים לְכָל עֵבֶר וְהַכֹּל מִתְגַּלֶּה. וּכְשֶׁנִּפְרָדִים מִמֶּנּוּ, לֹא יוֹדְעִים דָּבָר, וְכָל הַמַּעְיָנוֹת נִסְתָּמִים."],[3,"","אָמַר רַבִּי חִזְקִיָּה, הַיְנוּ שֶׁכָּתוּב (במדבר יא) וַיָּאצֶל מִן הָרוּחַ אֲשֶׁר עָלָיו וַיִּתֵּן עַל שִׁבְעִים אִישׁ הַזְּקֵנִים. כַּמְּנוֹרָה הַזּוֹ שֶׁמְּאִירִים מִמֶּנָּה כַּמָּה מְנוֹרוֹת, וְהִיא מְצוּיָה בְקִיּוּמָהּ. כָּךְ רַבִּי שִׁמְעוֹן בַּר יוֹחַאי בַּעַל הַמְּנוֹרוֹת הוּא מֵאִיר לַכֹּל, וְהָאוֹר לֹא זָז מִמֶּנּוּ וְנִמְצָא בְקִיּוּמוֹ. הָלְכוּ עַד שֶׁהִגִּיעוּ אֵלָיו."],[4,"","כְּשֶׁהִגִּיעוּ אֵלָיו, מְצָאוּהוּ שֶׁהָיָה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, וְהָיָה אוֹמֵר (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ. כָּל תְּפִלַּת יִשְׂרָאֵל הִיא תְפִלָּה, וּתְפִלַּת הֶעָנִי עֶלְיוֹנָה מִכֻּלָּם. מָה הַטַּעַם? מִשּׁוּם שֶׁזּוֹ עוֹלָה עַד כִּסֵּא הַכָּבוֹד שֶׁל הַמֶּלֶךְ וּמִתְעַטֶּרֶת בְּרֹאשׁוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ (מתעטף) בְּאוֹתָהּ תְּפִלָּה וַדַּאי, תְּפִלַּת הֶעָנִי נִקְרֵאת תְּפִלָּה."],[5,"","כִּי יַעֲטֹף. עִטּוּף זֶה אֵינוֹ עִטּוּף שֶׁל כִּסּוּי, שֶׁהֲרֵי אֵין לוֹ. אֶלָּא כָּתוּב כָּאן כִּי יַעֲטֹף, וְכָתוּב שָׁם (איכה ב) הָעֲטוּפִים בְּרָעָב. וְלִפְנֵי ה' יִשְׂפֹּךְ שִׂיחוֹ, שֶׁקּוֹבֵל לִפְנֵי רִבּוֹנוֹ. וְזֶה נוֹחַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁהָעוֹלָם מִתְקַּיֵּם בּוֹ כְּשֶׁלֹּא נִמְצָאִים שְׁאָר מְקַיְּמֵי הָעוֹלָם בָּעוֹלָם. אוֹי לְמִי שֶׁאוֹתוֹ הֶעָנִי יִקְבֹּל עָלָיו לְרִבּוֹנוֹ, מִשּׁוּם שֶׁהֶעָנִי קָרוֹב לַמֶּלֶךְ יוֹתֵר מִכֻּלָּם, שֶׁכָּתוּב (שמות כב) וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי."],[6,"","וְלִשְׁאָר בְּנֵי הָעוֹלָם - לִפְעָמִים שֶׁשּׁוֹמֵעַ וְלִפְעָמִים שֶׁלֹּא שׁוֹמֵעַ. מָה הַטַּעַם? מִשּׁוּם שֶׁדִּיּוּר הַמֶּלֶךְ הוּא בַּכֵּלִים הַשְּׁבוּרִים הַלָּלוּ, שֶׁכָּתוּב (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וְכָתוּב (תהלים לד) קָרוֹב ה' לְנִשְׁבְּרֵי לֵב. (שם נה) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה."],[7,"","מִכָּאן שָׁנִינוּ, מִי שֶׁנּוֹזֵף בְּעָנִי - נוֹזֵף בַּשְּׁכִינָה, שֶׁכָּתוּב וְאֶת דַּכָּא וּשְׁפַל רוּחַ, וְכָתוּב (משלי כב) כִּי ה' יָרִיב רִיבָם וְגוֹ'. מִשּׁוּם שֶׁהָאַפּוֹטְרוֹפּוֹס שֶׁלָּהֶם חָזָק וְשׁוֹלֵט עַל הַכֹּל, שֶׁלֹּא צָרִיךְ עֵדִים וְלֹא צָרִיךְ דַּיָּן אַחֵר, וְלֹא נוֹטֵל מַשְׁכּוֹן כִּשְׁאָר הַדַּיָּנִים. וְאֵיזֶה מַשְׁכּוֹן נוֹטֵל? נִשְׁמוֹת בְּנֵי אָדָם, שֶׁכָּתוּב וְקָבַע אֶת קבְעֵיהֶם נָפֶשׁ."],[8,"","עוֹד אָמַר, תְּפִלָּה לְעָנִי - כָּל מָקוֹם שֶׁנִּקְרָא תְפִלָּה, דָּבָר עֶלְיוֹן הוּא, שֶׁהוּא עוֹלֶה לְמָקוֹם (שהקדוש ברוך הוא) עֶלְיוֹן. תְּפִלַּת הָרֹאשׁ הֵן הַתְּפִלִּין שֶׁל הַמֶּלֶךְ שֶׁמֵּנִיחַ אוֹתָם."],[9,"","רַבִּי שִׁמְעוֹן סוֹבֵב רֹאשׁוֹ, וְרָאָה אֶת רַבִּי יְהוּדָה וְאֶת רַבִּי חִזְקִיָּה שֶׁהִגִּיעוּ אֵלָיו. אַחַר שֶׁסִּיֵּם, הִסְתַּכֵּל בָּהֶם. אָמַר לָהֶם, אוֹצָר הָיָה לָכֶם וְאָבַד מִכֶּם. אָמְרוּ לוֹ, וַדַּאי שֶׁפֶּתַח עֶלְיוֹן פָּתַח מוֹרֵנוּ, וְלֹא יָכֹלְנוּ לְהִכָּנֵס בּוֹ."],[10,"","אָמַר, מַה הוּא? אָמְרוּ לוֹ, (בראשית טז) וְהוּא יִהְיֶה פֶּרֶא אָדָם. וְסוֹף הַפָּסוּק אָנוּ רוֹצִים לָדַעַת, שֶׁכָּתוּב וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. מַה זֶּה עַל פְּנֵי כָל אֶחָיו? שֶׁהֲרֵי בֵּרוּר שֶׁל כָּל הַפָּסוּק יָדַעְנוּ, וְאֶת זֶה לֹא יָדַעְנוּ, שֶׁסּוֹף הַכָּתוּב לֹא נִרְאֶה כְרֹאשׁוֹ."],[11,"","אָמַר לָהֶם, חַיֵּיכֶם, הַכֹּל הוּא דָּבָר אֶחָד, וּבְדַרְגָּה אַחַת עוֹלֶה. שָׁנִינוּ, כַּמָּה פָנִים לַפָּנִים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא: פָּנִים הַמְּאִירִים. פָּנִים שֶׁלֹּא מְאִירִים. פָּנִים תַּחְתּוֹנִים. פָּנִים רְחוֹקִים. פָּנִים קְרוֹבִים. פָּנִים שֶׁלְּפָנִים. פָּנִים שֶׁלַּחוּץ. פָּנִים שֶׁל יָמִין. פָּנִים שֶׁל שְׂמֹאל."]]],[["תָּא חֲזִי, זַכָּאִין אִינּוּן יִשְׂרָאֵל קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דַּאֲחִידָן בְּאַנְפִּין עִלָּאִין דְּמַלְכָּא. בְּאִינּוּן פָּנִים דְּהוּא וּשְׁמֵיהּ אֲחִידָן בְּהוּ, וְאִינּוּן וּשְׁמֵיהּ חַד הוּא. וּשְׁאַר עַמִּין אֲחִידָן בְּאִינּוּן פָּנִים רְחִיקִין, בְּאִינּוּן פָּנִים תַּתָּאִין. וּבְגִינִי כַּךְ אִינּוּן רְחִיקִין מִגּוּפָא דְּמַלְכָּא, דְּהָא חֲמֵינָא כָּל אִינּוּן דְּמִצְרַיִם, קְרִיבוֹי דְּיִשְׁמָעֵאל, כְּמָה אַחִין וּקְרִיבִין הֲווֹ לֵיהּ, וְכֻלְּהוּ הֲווֹ בְּאַנְפִּין תַּתָּאִין, בְּאִינּוּן פָּנִים רְחִיקִין.","וּבְגִינֵיהּ דְּאַבְרָהָם, כַּד אִתְגְּזַר יִשְׁמָעֵאל, זָכָה, דְּשַׁוֵּי מָדוֹרֵיהּ וְחוּלָקֵיהּ בַּאֲתַר דְּשָׁלִיטָא עַל כָּל אִינּוּן פָּנִים רְחִיקִין וְתַתָּאִין, עַל כָּל אִינּוּן פָּנִים דִּשְׁאַר עַמִּין. הֲדָא הוּא דִכְתִיב יָדוֹ בַכֹּל, וּבְגִינֵי כַּךְ עַל פְּנִי כָל אֶחָיו יִשְׁכּוֹן, כְּלוֹמַר, יְשַׁוֵּי מָדוֹרֵיהּ וְחוּלָקֵיהּ לְעֵילָּא מִכֻּלְּהוּ, דִּכְתִּיב יָדוֹ בַכֹּל, דְּשַׁלְטָא עַל כָּל שְׁאַר פָּנִים דִּלְתַתָּא. וּבְּגִין כָּךְ עַל פְּנֵי כָל אֶחָיו וַדַּאי, דְּלָא זָכוּ כְּוָותֵיהּ.","אָתוּ רַבִּי יְהוּדָה וְר' חִזְקִיָּה, וְנָשְׁקוּ יְדוֹי. אָמַר רִבִּי יְהוּדָה, הַיְינוּ דְּאַמְרִי אִינְשֵׁי, חֲמָרָא בְּדֻרְדְיָא, וּנְבִיעָא דְּבֵירָא, בִּקְטִירָא דְּקִיזְרָא אִתְעַטָּר. וַוי לְעָלְמָא, כַּד יִסְתַּלַּק מֹר מִנֵּיהּ. וַוי לְדָרָא, דְּיִתְּעָרַע בְּהַהוּא זִמְנָא. זַכָּאָה דָּרָא דְּאִשְׁתְּמוֹדְעוּן לֵיהּ לְמֹר. זַכָּאָה דָּרָא דְּאִיהוּ שָׁרֵי בְּגַוֵּיהּ.","אָמַר רַבִּי חִזְקִיָּה, הָא תָּנֵינָן, גִּיּוֹרָא כַּד אִתְגְּזַר, אִקְרֵי (ויקרא קס\"ח ע\"א) גֵּר צֶדֶק, וְלָא יַתִּיר. וְהָכָא אָמַר מֹר יָדוֹ בַכֹּל. אָמַר רַבִּי שִׁמְעוֹן, כֹּלָּא אִתְקְשָׁר בְּחַד. אֲבָל גִּיּוֹרָא תָּנֵינָן. שָׁאנֵי יִשְׁמָעֵאל, דְּלָאו גִּיּוֹרָא הוּא. בְּרֵיהּ דְּאַבְרָהָם הֲוָה, בְּרֵיהּ דְּקַדִּישָׁא הֲוָה. וּכְתִיב בֵּיהּ בְּיִשְׁמָעֵאל, (בראשית י״ז:כ׳) הִנִּה בֵּרַכְתִּי אוֹתוֹ. כְּתִיב הָכָא, בֵּרַכְתִּי אוֹתוֹ. וּכְתִיב הָתָם, (בראשית כ״ד:א׳) וַיְיָ' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְעַל כַּךְ כְּתִיב, יָדוֹ בַכֹּל.","וּבְגִינֵי כַּךְ כְּתִיב, עַל פְּנֵי כָל אֶחָיו יִשְׁכּוֹן. דְּאִי שְׁאַר קְרִיבוֹי אִתְגְּזָרוּ (ס\"א אתגיירו) אִקְרוּן גֵּירֵי צֶדֶק, וְלָא יַתִּיר, וְהוּא יַתִּיר וְעִלָּאָה מִכֻּלְּהוּ. כָּל שֶׁכֵּן אִינּוּן דְּלָא אִתְגְּזָרוּ, דְּקַיְימִין בְּאִינּוּן אַפִּין רְחִיקִין, בְּאִינּוּן אַפִּין תַּתָּאִין. וְאִיהוּ, מָדוֹרֵיהּ לְעֵילָּא מִכָּל פָּנִים דִּידְהוּ, וּמִכָּל פָּנִים דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, הֲדָא הוּא דִּכְתִּיב, עַל פְּנֵי כָל אֶחָיו יִשְׁכּוֹן. אָמַר רִבִּי יְהוּדָה, קוּדְשָׁא בְּרִיךְ הוּא בְּגִין כַּךְ אַכְרִיז וְאָמַר, לֹא יִהְיֶה לְךָ אלֹהִים אֲחֵרִים עַל פָּנָי, דְּדָא הוּא מְהֵימָנוּתָא דִּילֵיהּ.","(שמות כ׳:ד׳) לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה. הָא אִתְּמַר. וְאָמַר רַבִּי יוֹסִי, כָּל פַּרְצוּפִין שָׁרֵי, בַּר מִפַּרְצוּפָא דְּאָדָם, דְּהָא הַאי פַּרְצוּפָא שָׁלִיט בְּכֹלָּא.","דָּבָר אַחֵר, לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה. רַבִּי יִצְחָק פָּתַח, (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ. כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא עַל פִּתְגָּמֵי אוֹרַיְיתָא, כַּמָּה אִית לֵיהּ לְאִזְדַּהֲרָא דְּלָא יִטְעֵי בְּהוּ, וְלָא יָפִיק מֵאוֹרַיְיתָא מַה דְּלָא יָדַע, וְלָא קַבִּיל מֵרַבֵּיהּ. דְּכָל מַאן דְּאָמַר בְּמִלֵּי דְּאוֹרַיְיתָא מַה דְּלָא יָדַע, וְלָא קַבִּיל מֵרַבֵּיהּ, עָלֵיהּ כְּתִיב לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה. וְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאִתְפָּרְעָא מִנִּיהּ, בְּעָלְמָא דְּאָתֵי, בְּזִמְנָא דְּנִשְׁמָתֵיהּ בַּעְיָא לְמֵיעָאל לְדוּכְתָּא, דַחְיָין לָהּ לְבַר, וְתִשְׁתְּצֵי מֵהַהוּא אֲתָר דִּצְרִירָא בִּצְרוֹרָא דְּחַיֵּי דִּשְׁאַר נִשְׁמָתִין.","(רבי יהודה אומר מהכא) כְּמָה דְּתָנֵינָן, (קהלת ה׳:ה׳) לָמָּה יִקְצֹף הָאֱלֹהִים עַל קוֹלֶךָ. קוֹלֶךָ: דָּא הִיא נִשְׁמָתֵיהּ דְּבַר נָשׁ. אָמַר רַבִּי חִיָּיא, עַל דָּא כְּתִיב, כִּי יְיָ' אֱלֹהֶיךָ אֵל קַנָּא. מַאי טַעְמָא. מִשּׁוּם דְּקַנִּי לִשְׁמֵיהּ בְּכֹלָּא. אִי בְּגִין פַּרְצוּפִין מְקַנִּי לִשְׁמֵיהּ, מִשּׁוּם דִּמְשַׁקֵּר בִּשְׁמֵיהּ. אִי מִשּׁוּם אוֹרַיְיתָא.","תָּנֵינָן, אוֹרַיְיתָא כֹּלָּא שְׁמָא קַדִּישָׁא הִיא, דְּלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא דְּלָא כָּלִיל בִּשְׁמָא קַדִּישָׁא. וּבְגִינִי כַּךְ, בָּעֵי לְאִזְדַּהֲרָא, בְּגִין דְּלָא יִטְעֵי בִּשְׁמֵיהּ קַדִּישָׁא, וְלָא יְשַׁקֵּר בֵּיהּ. וּמַאן דִּמְשַׁקֵּר בְּמַלְכָּא עִלָּאָה, לָא עָאלִין לֵיהּ לִפַלְטְרוֹי דְּמַלְכָּא, וְיִשְׁתְּצֵי מֵעָלְמָא דְּאָתֵי."],[[0,"תא חזי זכאין וכו':","בוא וראה, אשרי הם ישראל לפני הקב\"ה, שנאחזים בפנים העליונים של המלך, בפנים ההם, שהוא ושמו אחוזים בהם, והוא ושמו אחד. (כנ\"ל אות ת\"ד) ושאר העמים אחוזים באלו פנים הרחוקים, באלו פנים התחתונים, ומשום זה הם רחוקים מגוף המלך. כי אנו רואים, כל אלו המצרים קרוביו של ישמעאל, וכמה אחים וקרובים היו לו, וכולם היו בפנים התחתונים באלו פנים הרחוקים."],[1,"ובגיניה דאברהם וכו':","ובשביל אברהם, כשנמול ישמעאל, זכה, ששם משכנו וחלקו במקום השולט על כל אלו פנים הרחוקים ותחתונים, על כל אלו הפנים של שאר העמים. ז\"ש, ידו בכל, אשר כל, פירושו יסוד (כנ\"ל אות ת\"ז) ומשום זה על פני כל אחיו ישכון, כלומר, ישום משכנו וחלקו למעלה מכולם, שכתוב, ידו בכל, השולט על כל שאר הפנים שלמטה. ומשום זה, על פני כל אחיו, ודאי שהם לא זכו כמוהו."],[2,"אתו ר' יהודה וכו':","באו ר' יהודה ור' חזקיה ונשקו ידיו. א\"ר יהודה, זהו שאנשים אומרים, יין מתחזק על שמריו ומבוע הבאר מתעטר על קשר העפר והפסולת שמכסה אותו, שמתוך דוחקו לפרוץ העפר נובע ביותר כח. כן ישמעאל התחזק בשליטתו על כל הפסולת של אחיו שהם הפנים המרוחקים והתחתונים הנ\"ל. אוי לעולם כשיסתלק אדוני ממנו. אוי לדור שיקרה בזמן ההוא. אשרי הדור שמכיר את אדוני, אשרי הדור שהוא שורה בתוכו."],[3,"אמר ר' חזקיה וכו':","אר\"ח, הרי למדנו, גר שנתגייר נקרא גר צדק ולא יותר, וכאן אמר אדוני, ידו בכל, שזכה ליסוד שנקרא כל. א\"ר שמעון הכל נקשר במקום אחד, אבל גר למדנו, ומשונה ישמעאל שאינו גר, שבנו של אברהם היה, בנו של קדוש היה. וכתוב בו בישמעאל, הנה ברכתי אותו, כתוב כאן הנה ברכתי, וכתוב שם, וה' ברך את אברהם בכל, אף ברכה שבכאן הוא בכל. ועל כך כתוב, ידו בכל."],[4,"ובגיני כך כתיב וכו':","ומשום זה כתוב, על פני כל אחיו ישכון, כי אם שאר קרוביו נתגיירו היו נקראים גר צדק ולא יותר, והוא יותר, ועליון מכולם. כל שכן אלו שלא נמולו העומדים באלו פנים הרחוקים באלו התחתונים, שהוא, משכנו למעלה מכל פנים שלהם, ומכל פנים של העמים עכו\"ם, ז\"ש על \u0003פני\u0004 כל אחיו ישכון. אמר ר' יהודה, הקב\"ה הכריז בשביל זה, ואמר, לא יהיה לך אלהים אחרים על \u0003פני.\u0004 כי זה היא האמונה שלו. דהיינו המלכות, שנקראת פנים (כנ\"ל באות ת\"ד)."],[5,"לא תעשה לך פסל וכל תמונה:","כבר נתבאר. ואמר ר' יוסי, כל צורת פנים מותר לעשות חוץ מפני אדם, כי פני אדם שולט על כל."],[6,"דבר אחר לא וגו':","פירוש אחר, על לא תעשה לך פסל וכל תמונה. ר' יצחק פתח, אל תתן את פיך לחטיא את בשרך. כמה יש לו לאדם להזהר בדברי תורה, כמה יש לו להזהר שלא יטעה בהם, ולא יוציא דבר בתורה מה שאינו יודע ומה שלא קבל מרבו, שכל מי שאומר בדברי תורה מה שאינו יודע ולא קבל מרבו, עליו כתוב, לא תעשה לך פסל וכל תמונה. ועתיד הקב\"ה להפרע ממנו בעולם הבא, בזמן שנשמתו רוצה להכנס למקומה דוחים אותה לחוץ, ותכלה ממקום ההוא הצרור בצרור החיים של שאר הנשמות."],[7,"ר' יהודה אומר וכו':","רי\"א מכאן, כמו שלמדנו, למה יקצוף אלקים על קולך. קולך, זה הוא נשמתו של אדם. אמר ר' חייא, על זה כתוב, כי ה' אלקיך אל קנא הוא. מה הטעם. משום שמקנא לשמו בכל, אם בשביל צורת פנים מקנא לשמו, משום שמשקר בשמו. אם משום התורה, שאומר מה שלא יודע ולא קיבל מרבו."],[8,"תנינן אורייתא כלא וכו':","למדנו, התורה כולה היא שם קדוש, שאין לך דבר בתורה שאינו כלול בשם הקדוש. ומשום זה צריכים להזהר, שלא לטעות בשמו הקדוש ולא ישקר בו, ומי שמשקר במלך העליון אין מכניסים אותו לארמון המלך, ויכלה מעולם הבא."]],[[0,"","בֹּא וּרְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֲחוּזִים בַּפָּנִים הָעֶלְיוֹנִים שֶׁל הַמֶּלֶךְ בְּאוֹתָם פָּנִים שֶׁהוּא וּשְׁמוֹ אֲחוּזִים בָּהֶם, וְהֵם וּשְׁמוֹ אֶחָד הוּא, וּשְׁאָר הָעַמִּים אֲחוּזִים בְּאוֹתָם פָּנִים רְחוֹקִים, בְּאוֹתָם פָּנִים תַּחְתּוֹנִים, וְלָכֵן הֵם רְחוֹקִים מִגּוּף הַמֶּלֶךְ, שֶׁהֲרֵי רָאִינוּ כָּל אוֹתָם שֶׁל מִצְרַיִם, קְרוֹבֵי יִשְׁמָעֵאל, כְּמוֹ אַחִים וּקְרוֹבִים הָיוּ לוֹ, וְכֻלָּם הָיוּ בְּפָנִים תַּחְתּוֹנִים וּבְאוֹתָם פָּנִים רְחוֹקִים."],[1,"","וּבִגְלַל אַבְרָהָם, כְּשֶׁנִּמּוֹל יִשְׁמָעֵאל, זָכָה שֶׁשָּׂם מְדוֹרוֹ וְחֶלְקוֹ בְּמָקוֹם שֶׁשּׁוֹלֵט עַל כָּל אוֹתָם פָּנִים רְחוֹקִים וְתַחְתּוֹנִים, עַל כָּל אוֹתָם פָּנִים שֶׁל שְׁאָר הָעַמִּים. זֶהוּ שֶׁכָּתוּב יָדוֹ בַכֹּל. וּמִשּׁוּם כָּךְ עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. כְּלוֹמַר, יָשִׂים מְדוֹרוֹ וְחֶלְקוֹ לְמַעְלָה מִכֻּלָּם, שֶׁכָּתוּב יָדוֹ בַכֹּל, שֶׁשּׁוֹלֵט עַל כָּל שְׁאָר הַפָּנִים שֶׁלְּמַטָּה, וּמִשּׁוּם כָּךְ עַל פְּנֵי כָל אֶחָיו וַדַּאי, שֶׁלֹּא זָכוּ כְמוֹתוֹ."],[2,"","בָּאוּ רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה וְנָשְׁקוּ יָדוֹ. אָמַר רַבִּי יְהוּדָה, הַיְנוּ מַה שֶּׁאֲנָשִׁים אוֹמְרִים, יַיִן בִּשְׁמָרָיו וּנְבִיעַת הַבְּאֵר, בְּקֶשֶׁר שֶׁל קְיָמָא מִתְעַטֵּר. אוֹי לָעוֹלָם כְּשֶׁיִּסְתַּלֵּק מִמֶּנּוּ מוֹרֵנוּ! אוֹי לַדּוֹר כְּשֶׁזֶּה יֶאֱרַע בְּאוֹתוֹ הַזְּמַן! אַשְׁרֵי הַדּוֹר שֶׁמַּכִּירִים אֶת מוֹרֵנוּ! אַשְׁרֵי הַדּוֹר שֶׁהוּא שָׁרוּי בְּתוֹכוֹ!"],[3,"","אָמַר רַבִּי חִזְקִיָּה, הֲרֵי שָׁנִינוּ, כְּשֶׁגֵּר נִמּוֹל נִקְרָא גֵּר צֶדֶק, וְלֹא יוֹתֵר. וְכָאן אָמַר מוֹרֵנוּ יָדוֹ בַכֹּל. אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל נִקְשָׁר בְּאֶחָד. אֲבָל שָׁנִינוּ שֶׁהַגֵּר, שׁוֹנֶה יִשְׁמָעֵאל, שֶׁאֵינוֹ גֵר. בֶּן אַבְרָהָם הוּא הָיָה, בְּנוֹ שֶׁל קָדוֹשׁ הָיָה. וְכָתוּב בּוֹ בְּיִשְׁמָעֵאל, (בראשית יז) הִנֵּה בֵּרַכְתִּי אֹתוֹ. כָּתוּב כָּאן בֵּרַכְתִּי אֹתוֹ, וְכָתוּב שָׁם (שםכד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְעַל כָּךְ כָּתוּב יָדוֹ בַכֹּל."],[4,"","וּמִשּׁוּם כָּךְ כָּתוּב עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. שֶׁאִם שְׁאָר קְרוֹבָיו נִמּוֹלוּ (התגירו), נִקְרָאִים גֵּרֵי צֶדֶק וְלֹא יוֹתֵר, וְהוּא יוֹתֵר וְעֶלְיוֹן מִכֻּלָּם. כָּל שֶׁכֵּן הֵם שֶׁלֹּא נִמּוֹלוּ שֶׁעוֹמְדִים בְּאוֹתָם פָּנִים רְחוֹקִים, בְּאוֹתָם פָּנִים תַּחְתּוֹנִים. וְהוּא מְדוֹרוֹ לְמַעְלָה מִכָּל הַפָּנִים שֶׁלָּהֶם, וּמִכָּל הַפָּנִים שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. זֶהוּ שֶׁכָּתוּב עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. אָמַר רַבִּי יְהוּדָה, מִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הִכְרִיז וְאָמַר, לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי, שֶׁזּוֹהִי הָאֱמוּנָה שֶׁלּוֹ."],[5,"","לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה. הֲרֵי נִתְבָּאֵר. וְאָמַר רַבִּי יוֹסֵי, כָּל הַפַּרְצוּפִים מֻתָּרִים, פְּרָט לְפַרְצוּף אָדָם, שֶׁהֲרֵי פַּרְצוּף זֶה שׁוֹלֵט בַּכֹּל."],[6,"","דָּבָר אַחֵר לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה - רַבִּי יִצְחָק פָּתַח, אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ. כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִזָּהֵר עַל דִּבְרֵי הַתּוֹרָה, כַּמָּה יֵשׁ לוֹ לְהִזָּהֵר שֶׁלֹּא יִטְעֶה בָהֶם, וְשֶׁלֹּא יוֹצִיא מֵהַתּוֹרָה מַה שֶּׁלֹּא יוֹדֵעַ וְלֹא קִבֵּל מֵרַבּוֹ. שֶׁכָּל מִי שֶׁאוֹמֵר דִּבְרֵי תוֹרָה מַה שֶּׁלֹּא יוֹדֵעַ וְלֹא קִבֵּל מֵרַבּוֹ, עָלָיו כָּתוּב לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהִפָּרַע מִמֶּנּוּ בָּעוֹלָם הַבָּא, בִּזְמַן שֶׁנִּשְׁמָתוֹ תִּרְצֶה לְהִכָּנֵס לִמְקוֹמָהּ, דּוֹחִים אוֹתָהּ הַחוּצָה, וְתֻשְׁמַד מֵאוֹתוֹ מָקוֹם שֶׁצְּרוּרָה בִּצְרוֹר חַיֵּי שְׁאָר הַנְּשָׁמוֹת."],[7,"","(רבי יהודה אומר מכאן) כְּמוֹ שֶׁשָּׁנִינוּ, לָמָּה יִקְצֹף הָאֱלֹהִים עַל קוֹלֶךְ. קוֹלֶךְ - זוֹהִי נִשְׁמָתוֹ שֶׁל הָאָדָם. אָמַר רַבִּי חִיָּיא, עַל זֶה כָּתוּב כִּי ה' אֱלֹהֶיךְ אֵל קַנָּא. מָה הַטַּעַם? מִשּׁוּם שֶׁמְּקַנֵּא לִשְׁמוֹ בַּכֹּל. אִם מִשּׁוּם הַפַּרְצוּפִים מְקַנֵּא לִשְׁמוֹ, מִשּׁוּם שֶׁמְּשַׁקֵּר בִּשְׁמוֹ, אוֹ מִשּׁוּם הַתּוֹרָה."],[8,"","שָׁנִינוּ, כָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ, שֶׁאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא כָלוּל בַּשֵּׁם הַקָּדוֹשׁ, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִזָּהֵר שֶׁלֹּא יִטְעֶה בִּשְׁמוֹ הַקָּדוֹשׁ וְלֹא יְשַׁקֵּר בּוֹ. וּמִי שֶׁמְּשַׁקֵּר בַּמֶּלֶךְ הָעֶלְיוֹן, לֹא מַכְנִיסִים אוֹתוֹ לַפַּלְטֵרִין שֶׁל הַמֶּלֶךְ, וְיֻשְׁמַד מִן הָעוֹלָם הַבָּא."]]],[["אָמַר רַבִּי אַבָּא, כְּתִיב הָכָא לא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה. וּכְתִיב הָתָם, (שמות לה) פְּסָל לְךָ שְׁנִי לֻחֹת אֲבָנִים. כְּלוֹמַר, לֹא תַעֲשֶׂה לְךָ פֶסֶל, לָא תַּעְבֵּד לְךָ אוֹרַיְיתָא אַחֲרָא דְּלָא יַדְעַת, וְלָא אָמַר לָךְ רַבָּךְ. מַאי טַעֲמָא. כִּי אָנֹכִי יְיָ' אֱלהֶיךָ אֵל קַנָּא, אֲנָא הוּא דְּזַמִּין לְאִתְפָּרְעָא מִינָךְ בְּעָלְמָא דְּאָתֵי, בְּשַׁעֲתָא דְּנִשְׁמְתָא בַּעְיָא לְמֵיעָאל קַמָּאי, כַּמָּה זְמִינִין לְשַׁקְרָא בָּהּ, וּלְעַיְּילָא לָהּ גּוֹ גֵּיהִנָּם.","תַּנְיָא, אָמַר ר' יִצְחָק, לֹא תַעֲשֶׂה לְךָ וְגוֹ', דְּבָעֵי בַּר נָשׁ דְּלָא לְשַׁקְרָא בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא (ס\"א דבר אחר לא תעשה לך פסל וגו' דבעי בר נש דלא לשקרא בשמיה דקודשא בריך הוא, ומאי איהו, דא ברית את קיימא קדישא דמאן דמשקר בהאי ברית משקר בשמא דקודשא בריך הוא) דְּקִשְׁרָא קַדְמָאָה, דְּאִתְקְשָׁרוּ יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד אִתְגְּזָרוּ. וְדָא הוּא קִיּוּמָא קַדְמָאָה דְּכֹלָּא, לְמֵיעָאל בִּבְרִית דְּאַבְרָהָם, דְּהוּא קִשְׁרָא דִּשְׁכִינְתָּא. וּבָעֵי בַּר נָשׁ, דְּלָא לְשַׁקְּרָא בְּהַאי בְּרִית, דְּמַאן דִּמְשַׁקֵּר בְּהַאי בְּרִית, מְשַׁקֵּר בְּקוּדְשָׁא בְּרִיךְ הוּא. מַאי שִׁקְרָא. הוּא, דְּלָא יֵיעוּל הַאי בְּרִית בִּרְשׁוּתָא אַחֲרָא. כְּמָה דְּאַתְּ אָמַר (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר.","ר' יְהוּדָה אָמַר מֵהָכָא, (הושע ה׳:ז׳) בַּיְיָ' בָּגָדוּ כִּי בָּנִים זָרִים יָלָדוּ. מַאן דִּמְשַׁקֵּר בְּהַאי בְּרִית, מְשַׁקֵּר בְּקוּדְשָׁא בְּרִיךְ הוּא. מִשּׁוּם דְהַאי בְּרִית בְּקוּדְשָׁא בְּרִיךְ הוּא אֲחִידָא, וּכְתִיב לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה אֲשֶׁר בַּשָּׁמַיִם מִמַּעַל וְגוֹ'.","(שמות כ׳:ה׳) לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם. ר' אֶלְעָזָר הֲוָה אָזִיל בְּאָרְחָא, וַהֲוָה ר' חִיָּיא עִמֵּיהּ. אָמַר ר' חִיָּיא, כְּתִיב (דברים כ״א:י״א) וְרָאִיתָ בַּשִּׁבְיָה אֵשֶׁת יְפַת תֹּאַר וְגוֹ', מַאי טַעֲמָא. וְהָא כְּתִיב לֹא תִתְחַתֵּן בָּם. אָמַר לֵיהּ, בְּעוֹד דְּבִרְשׁוּתַיְיהוּ קַיְימֵי.","וְתָא חֲזִי, לֵית לָךְ אִנְתּוּ בְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת כְּשֵׁרָה כַּדְקָא חֲזִי. דְּתָנֵינָן, אֲמַאי אַסְמִיךְ פַּרְשְׁתָּא דָּא, לְבֶן סוֹרֵר וּמוֹרֶה. אֶלָּא בְּוַדַּאי, מַאן דְּנָסִיב הַאי אִתְּתָא, בֶּן סוֹרֵר וּמוֹרֶה יָרִית מִינָהּ. מַאי טַעֲמָא. מִשּׁוּם דְּקָשֶׁה לְמֶעְבַּר זוּהֲמָא מִינָהּ, וְכָל שֶׁכֵּן הַהִיא דְּאִתְנְסִיבַת בְּקַדְמִיתָא, דְּדִינָא בְּדִינָא אִתְדְּבַק, וְאִסְתְּאָבָת בָּהּ, וְקַשְׁיָא זוּהֲמָא לְמֶעְבַּר מִינָהּ, וְהַיְינוּ דְּאָמַר מֹשֶׁה בִּנְשֵׁי מִדְיָן, (במדבר ל״א:י״ז) וְכָל אִשָּׁה יֹדַעַת אִישׁ לְמִשְׁכַּב זָכָר הֲרֹגוּ.","זַכָּאָה חוּלָקֵיהּ, דְּהַהוּא בַּר נָשׁ דְּיָרִית אַחֲסַנְתָּא דָּא, וְנָטִיר לָהּ. דִּבְהַהוּא אַחֲסָנָא קַדִּישָׁא אִתְדָּבַּק בַּר נָשׁ בְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל שֶׁכֵּן אִי זָכֵי בְּפִקּוּדֵי אוֹרַיְיתָא, דְּהָא פָּשִׁיט מַלְכָּא יְמִינֵיהּ לָקֳבְלֵיהּ, וְאִתְדְּבַק בְּגוּפָא קַדִּישָׁא. וְעַל דָּא כְּתִיב בְּהוּ בְּיִשְׂרָאֵל, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם. וּכְתִיב (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ'. בָּנִים אַתֶּם מַמָּשׁ. דִּכְתִּיב, (שמותד) בְּנִי בְכוֹרִי יִשְׂרָאֵל. וּכְתִיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","(שמות כ) לא תִשָּׂא אֶת שֵׁם וְגוֹ'. ר' שִׁמְעוֹן פָּתַח, (מלכים ב ד׳:ב׳) וַיֹּאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָךְ הַגִּידִי לִי מַה יֵשׁ לָךְ בַּבָּיִת. אָמַר לָהּ אֱלִישָׁע, כְּלוּם אִית לָךְ עַל מַה דְּתִשְׁרֵי בִּרְכָתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּתָנֵינָן אָסוּר לֵיהּ לְבַר נָשׁ, לְבָרְכָא עַל פָּתוֹרָא רֵיקָנַיָּא. מַאי טַעְמָא. מִשּׁוּם דְּבִרְכָּתָא דִּלְעֵילָּא, לָא שַׁרְיָא בַּאֲתָר רֵיקָנַיָּא.","וּבְגִינֵי כַּךְ, בָּעֵי בַּר נָשׁ לְסַדְּרָא עַל פָּתוֹרֵיהּ, חַד נַהֲמָא, אוֹ יַתִּיר, לְבָרְכָא עֲלוֹי. וְאִי לָא יָכִיל, בָּעֵי לְשַׁיְּירָא מֵהַהוּא מְזוֹנָא דְּאָכַל, עַל מַה דִּיבָרֵךְ. וְלָא יִשְׁתְּכַּח דִּיבָרֵךְ בְּרֵיקַנְיָּא.","כֵּיוָן דְּאָמְרָה, אֵין לְשִׁפְחָתְךָ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. אָמַר וַדַּאי הָא בִּרְכָתָא שְׁלֵימָתָא בְּהַאי, דִּכְתִּיב, (קהלת ז׳:א׳) טוֹב שֵׁם מִשֶּׁמֶן טוֹב. דִּשְׁמָא קַדִּישָׁא מִשֶּׁמֶן נָפְקָא, לְאִתְבָּרְכָא, לְאַדְלְקָא בּוּצִינִין קַדִּישִׁין. מַאי (ט' ע\"א) שֶׁמֶן דָּא. (כמה דאת אמר בראשית ב׳:י׳ ונהר יוצא מעדן להשקות את הגן) ר' יִצְחָק אָמַר, כְּמָה דְּאַתְּ אָמֵר, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ'. ר' אֶלְעָזָר אוֹמֵר, אִלֵּין טוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא.","אָמַר ר' שִׁמְעוֹן, טוֹב שֵׁם, כַּמָּה טָבָא שְׁמָא עִלָּאָה, דְּבוּצִינִין עִלָּאִין קַדִּישִׁין, כַּד כֻּלְּהוּ נַהֲרִין מִשֶּׁמֶן טוֹב, כְּמָה דַּאֲמֵינָא. וְאָסִיר לֵיהּ לְבַר נָשׁ, לְאַדְכְּרָא שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּרֵיקַנְיָּא. דְּכָל מַאן דְּאִדְכַּר שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּרֵיקַנְיָּא, טָב לֵיהּ דְּלָא אִתְבְּרֵי.","ר' אֶלְעָזָר אָמַר, לָא אִצְטְרִיךְ לְמִדְכַּר שְׁמָא קַדִּישָׁא אֶלָּא בָּתַר מִלָּה. (כלומר עלמלה) דְּהָא שְׁמָא קַדִּישָׁא, לָא אִדְכַּר בְּאוֹרַיְיתָא, אֶלָּא בָּתַר תְּרֵין מִלִּין, דִּכְתִּיב בְּרֵאשִׁית בָּרָא אֱלֹהִים."],[[0,"אמר ר' אבא וכו':","אר\"א, כתוב כאן לא תעשה לך פסל וכל תמונה, וכתוב שם, פסל לך שני לוחות אבנים, כלומר, לא תעשה לך פסל, פירושו, לא תעשה לך תורה אחרת שלא ידעת ולא אמר לך רבך. מהו הטעם. כי אנכי ה' אלקיך אל קנא. היינו אני הוא העתיד להפרע ממך בעולם הבא, בשעה שהנשמה תבקש להכנס לפני. כמה עתידים לשקר בה ולהכניסה לתוך הגיהנם."],[1,"תניא אמר ר' יצחק וכו':","למדנו, אר\"י, לא תעשה לך וגו', היינו שצריך האדם שלא ישקר בשמו של הקב\"ה, כי קשר הראשון שנתקשרו ישראל בהקב\"ה, היה כשנמולו, וזה הוא חוק הראשון לכולם, להכנס בבריתו של אברהם, שהוא קשר של השכינה. וצריך האדם שלא ישקר בברית הזה, שמי שמשקר בברית הזה הוא משקר בהקב\"ה, ומהו שקר, הוא שלא יכניס ברית ההוא ברשות אחר, כש\"א, ובעל בת אל נכר."],[2,"ר' יהודה אמר וכו':","רי\"א, מכאן, בה' בגדו כי בנים זרים ילדו. כי מי שמשקר בברית הזה הוא משקר בהקב\"ה, משום שברית הזה אחוז בהקב\"ה. וכתוב, לא תעשה לך פסל וגו'."],[3,"לא תשתחוה להם ולא תעבדם:","ר' אלעזר היה הולך בדרך, והיה ר' חייא עמו. אמר ר' חייא כתוב, וראית בשביה אשת יפת תואר וגו'. מהו הטעם התירה התורה, והרי כתוב, לא תתחתן בם. אמר לו לא תתחתן היינו בעוד שעומדת ברשותם. אבל כאן שנשבתה ובאה לרשות ישראל התירה התורה."],[4,"ותא חזי לית וכו':","ובוא וראה, אין לך אשה כשרה בעמים עכו\"ם כראוי. שלמדנו, למה נסמכה פרשה זו לבן סורר ומורה, אלא בודאי, מי שנושא אשה זו, יורש ממנה בן סורר ומורה. מהו הטעם. משום שקשה להעביר הזוהמה ממנה, וכל שכן אותה, שהיתה נשאת מקודם לאיש עכו\"ם, שהדין נתדבק בדין, ונטמאת, וקשה להעביר ממנה הזוהמה. והיינו שאמר משה בנשי מדין, וכל אשה יודעת איש למשכב זכור הרוגו."],[5,"זכאה חולקיה וכו':","אשרי חלקו של אדם ההוא היורש ירושה זו של אות ברית קודש, ושומר אותה, שבירושה הקדושה הזו מתדבק האדם בהקב\"ה. כל שכן אם זוכה במצות התורה, שהמלך מושיט ימינו לנגדו, ומתדבק בגוף הקדוש, בז\"א. ועל כן כתוב בהם בישראל, ואתם הדבקים בה' אלקיכם. וכתוב, בנים אתם לה'. בנים אתם ממש. שכתוב, בני בכורי ישראל, וכתוב ישראל אשר בך אתפאר."],[6,"לא תשא את שם וגו':","ר' שמעון פתח, ויאמר אליה אלישע מה אעשה לך הגידי לי מה יש לך בבית. אמר לה אלישע, היש לך על מה שתשרה ברכת הקב\"ה, שלמדנו, אסור לו לאדם שיברך על שלחן ריק. מה הטעם. משום שהברכה שלמעלה אינה שורה על מקום ריק."],[7,"ובגיני כך בעי וכו':","ומשום זה צריך האדם לסדר על שלחנו לחם אחד או יותר לברך עליו. ואם אינו יכול לסדר הרבה, צריך להשאיר ממזון ההוא שאכל כדי שיהיה לו על מה לברך, ולא ימצא שיברך על שלחן ריק."],[8,"כיון דאמרה וכו':","כיון שאמרה, אין לשפחתך כל בבית כי אם אסוך שמן, אמר, ודאי, הברכה שלמה בזה, שכתוב, טוב שם משמן טוב, כי השם הקדוש יוצא משמן, להתברך ולהדליק את נרות הקדשים. שואל, מהו שמן הזה. ומשיב, ר' יצחק אמר, כש\"א, כשמן הטוב על הראש וגו'. דהיינו השפע העליון. ר' אלעזר אומר, אלו הם הרי אפרסמון הטהור דהיינו שפע בינה עילאה (כמ\"ש להלן קכ\"ז ע\"ב ד\"י)."],[9,"אמר ר' שמעון וכו':","אר\"ש, \u0003טוב שם,\u0004 פירושו, כמה טוב הוא שם העליון של המאורות העליונים הקדושים, כשכולם מאירים \u0003משמן טוב.\u0004 כמו שביארתי. ואסור לו לאדם להזכיר שמו של הקב\"ה בריקנות, שכל מי שמזכיר שמו של הקב\"ה בריקנות, טוב לו שלא נברא."],[10,"ר' אלעזר אמר וכו':","רא\"א, לא צריכים להזכיר שם הקדוש אלא אחר מלה. כי השם הקדוש לא נזכר בתורה אלא אחר שתי מלות, שכתוב, בראשית ברא אלקים."]],[[0,"","אָמַר רַבִּי אַבָּא, כָּתוּב כָּאן לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְמוּנָה, וְכָתוּב שָׁם (שמות לד) פְּסָל לְךְ שְׁנֵי לֻחֹת אֲבָנִים. כְּלוֹמַר, לֹא תַעֲשֶׂה לְךְ פֶסֶל - לֹא תַעֲשֶׂה לְךְ תּוֹרָה אַחֶרֶת שֶׁלֹּא יָדַעְתָּ וְלֹא אָמַר לְךְ רַבְּךְ. מָה הַטַּעַם? כִּי אָנֹכִי ה' אֱלֹהֶיךְ אֵל קַנָּא. אֲנִי הוּא שֶׁעָתִיד לְהִפָּרַע מִמְּךְ בָּעוֹלָם הַבָּא בְּשָׁעָה שֶׁהַנְּשָׁמָה רוֹצָה לְהִכָּנֵס לְפָנַי, כַּמָּה מְזֻמָּנִים לְשַׁקֵּר בָּהּ וּלְהַכְנִיסָהּ לַגֵּיהִנֹּם."],[1,"","שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, לֹא תַעֲשֶׂה לְךְ וְגוֹ' - שֶׁצָּרִיךְ הָאָדָם שֶׁלֹּא לְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (דבראחרלאתעשהלךפסלוגו' שצריך האדם שלא לשקר בשמו של הקדוש ברוך הוא, ומהו, 'זובריתאותהקיוםהקדושה. שמישמשקר בברית הזו, משקר בשמו של הקדוש ברוך הוא) שֶׁל הַקֶּשֶׁר הָרִאשׁוֹן שֶׁנִּקְשְׁרוּ יִשְׂרָאֵל בַּקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנִּמּוֹלוּ, וְזֶהוּ הַקִּיּוּם הָרִאשׁוֹן שֶׁל הַכֹּל - לְהִכָּנֵס בִּבְרִית אַבְרָהָם, שֶׁהוּא קֶשֶׁר הַשְּׁכִינָה. וְצָרִיךְ אָדָם שֶׁלֹּא לְשַׁקֵּר בַּבְּרִית הַזּוֹ, שֶׁמִּי שֶׁמְּשַׁקֵּר בַּבְּרִית הַזּוֹ, מְשַׁקֵּר בַּקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַשֶּׁקֶר? הוּא שֶׁלֹּא יַכְנִיס בְּרִית זוֹ לְרָשׁוּת אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר וּבָעַל בַּת אֵל נֵכָר."],[2,"","רַבִּי יְהוּדָה אָמַר מִכָּאן, (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ - מִי שֶׁמְּשַׁקֵּר בַּבְּרִית הַזּוֹ, מְשַׁקֵּר בַּקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁבְּרִית זוֹ אֲחוּזָה בַּקָּדוֹשׁ בָּרוּךְ הוּא, וְכָתוּב לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה אֲשֶׁר בַּשָּׁמַיִם מִמַּעַל וְגוֹ'."],[3,"","לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם. רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי חִיָּיא. אָמַר רַבִּי חִיָּיא, כָּתוּב וְרָאִיתָ בַּשִּׁבְיָה אֵשֶׁת יְפַת תֹּאַר. מָה הַטַּעַם, וַהֲרֵי כָּתוּב לֹא תִתְחַתֵּן בָּם? אָמַר לוֹ, בְּעוֹדּ שֶׁהֵן קַיָּמוֹת בִּרְשׁוּתָם."],[4,"","וּבֹא רְאֵה, אֵין לְךְ אִשָּׁה בָּעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת כְּשֵׁרָה כָּרָאוּי, שֶׁשָּׁנִינוּ, לָמָּה סָמַךְ פָּרָשַׁה זוֹ לְבֵן סוֹרֵר וּמוֹרֶה? אֶלָּא בְּוַדַּאי מִי שֶׁנּוֹשֵׂא אִשָּׁה זוֹ, יוֹרֵשׁ מִמֶּנָּה בֵּן סוֹרֵר וּמוֹרֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁקָּשֶׁה לְהַעֲבִיר מִמֶּנּוּ זֻהֲמָה, וְכָל שֶׁכֵּן אוֹתָהּ שֶׁנִּשְּׂאָה בַּתְּחִלָּה, שֶׁדִּין בְּדִין נִדְבָּק וְנִטְמֵאת בָּהּ, וְקָשֶׁה לְהַעֲבִיר מִמֶּנָּה הַזֻּהֲמָה, וְהַיְנוּ מַה שֶּׁאָמַר מֹשֶׁה בִּנְשׁוֹת מִדְיָן, (במדבר לא) וְכָל אִשָּׁה יֹדַעַת אִישׁ לְמִשְׁכַּב זָכָר הֲרֹגוּ."],[5,"","אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁיּוֹרֵשׁ נַחֲלָה זוֹ וְשׁוֹמֵר אוֹתָהּ, שֶׁבְּאוֹתָהּ יְרֻשָּׁה קְדוֹשָׁה נִדְבָּק הָאָדָם בַּקָּדוֹשׁ בָּרוּךְ הוּא. כָּל שֶׁכֵּן אִם זוֹכֶה לְמִצְווֹת הַתּוֹרָה, שֶׁהֲרֵי פּוֹשֵׁט הַמֶּלֶךְ יְמִינוֹ כְּנֶגְדּוֹ וְנִדְבָּק בַּגּוּף הַקָּדוֹשׁ. וְעַל זֶה כָּתוּב בָּהֶם בְּיִשְׂרָאֵל, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם, וְכָתוּב (שם יד) בָּנִים אַתֶּם לַה'. בָּנִים אַתֶּם מַמָּשׁ, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[6,"","לֹא תִשָּׂא אֶת שֵׁם וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח, (מלכים ב ד) וַיֹּאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָּךְ הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. אָמַר לָהּ אֱלִישָׁע, כְּלוּם יֵשׁ לָךְ עַל מַה שֶּׁתִּשְׁרֶה בִּרְכַּת הַקָּדוֹשׁ בָּרוּךְ הוּא? שֶׁשָּׁנִינוּ, אָסוּר לְאָדָם לְבָרֵךְ עַל שֻׁלְחָן רֵיק, מָה הַטַּעַם? מִשּׁוּם שֶׁהַבְּרָכָה שֶׁלְּמַעְלָה לֹא שׁוֹרָה בְּמָקוֹם רֵיק."],[7,"","וּמִשּׁוּם כָּךְ צָרִיךְ אָדָם לְסַדֵּר עַל שֻׁלְחָנוֹ לֶחֶם אֶחָד אוֹ יוֹתֵר לְבָרֵךְ עָלָיו. וְאִם לֹא יָכוֹל, צָרִיךְ לְהַשְׁאִיר מֵאוֹתוֹ מָזוֹן שֶׁאָכַל עַל מַה שֶּׁיְּבָרֵךְ, וְלֹא יִמָּצֵא שֶׁמְּבָרֵךְ בְּרֵיקָנוּת."],[8,"","כֵּיוָן שֶׁאָמְרָה אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן - אָמַר, וַדַּאי הֲרֵי בְּרָכָה שְׁלֵמָה בָּזֶה, שֶׁכָּתוּב (קהלת ז) טוֹב שֵׁם מִשֶּׁמֶן טוֹב. שֶׁשֵּׁם קָדוֹשׁ יוֹצֵא מִשֶּׁמֶן לְהִתְבָּרֵךְ וּלְהַדְלִיק מְנוֹרוֹת קְדוֹשׁוֹת. מַהוּ הַשֶּׁמֶן הַזֶּה? (כמו שגאמר (בראשית ב) ונהר יצא מעדן להשקות את הגן) רַבִּי יִצְחָק אָמַר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ'. רַבִּי אֶלְעָזָר אוֹמֵר, אֵלּוּ הָרֵי אֲפַרְסְמוֹן זַךְ."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, טוֹב שֵׁם - כַּמָּה טוֹב שֵׁם עֶלְיוֹן שֶׁל מְנוֹרוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת כְּשֶׁכֻּלָּן מְאִירוֹת מִשֶּׁמֶן טוֹב, כְּמוֹ שֶׁאָמַרְנוּ. וְאָסוּר לְאָדָם לְהַזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרֵיקָנוּת. שֶׁכָּל מִי שֶׁמַּזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרֵיקָנוּת, טוֹב לוֹ שֶׁלֹּא נִבְרָא."],[10,"","רַבִּי אֶלְעָזָר אָמַר, לֹא צָרִיךְ לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ, אֶלָּא אַחַר דָּבָר. שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ לֹא נִזְכַּר בַּתּוֹרָה אֶלָּא אַחַר שְׁנֵי דִבּוּרִים (כלומר על דבר), שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים."]]],[["רַבִּי שִׁמְעוֹן אָמַר, לָא אִדְכַּר שְׁמָא קַדִּישָׁא, אֶלָּא עַל עוֹלָם שָׁלֵם. דִּכְתִּיב, (בראשיתב) בְּיוֹם עֲשׂוֹת יְיָ' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. מִכָּאן, דְּלָא לְאַדְכְּרָא שְׁמֵיהּ קַדִּישָׁא בְּרֵיקַנְיָּא. וּכְתִיב לא תִשָּׂא אֶת שֵׁם יְיָ' אֱלהֶיךָ לַשָּׁוְא. (ס\"א כתיב לא תשא את שם יי אלהיך לשוא דלא לאדכרא שמא קדישא בריקנייא אלא בברכתא או בצלותא ומאן דאדכר שמא קדישא בריקנייא דלא בברכתא או בצלותא כה נשמתיה נפקא מיניה זמינין לאתפרעא מיניה ולנקמא מיניה נוקמין דכתיב כי לא ינקה יי את אשר ישא את שמו לשוא)","וְתָנֵינָן, אָמַר רַבִּי יוֹסִי, מַהוּ בְּרָכָה. שְׁמָא קַדִּישָׁא. בְּגִין דְּמִינֵיהּ מִשְׁתְּכַח בִּרְכְתָא, לְכָל עָלְמָא. וּבִרְכְתָא לָא אִשְׁתְּכַח עַל אֲתָר רֵיקָנַיָּא, וְלָא שַׁרְיָיא עֲלוֹי, הֲדָא הוּא דִּכְתִּיב לא תִשָּׂא אֶת שֵׁם יְיָ' אֱלהֶיךָ לַשָּׁוְא.","(שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. רַבִּי יִצְחָק אָמַר, כְּתִיב (בראשית ב׳:ג׳) וַיְבָרֶךְ אֱלהִים אֶת יוֹם הַשְּׁבִיעִי, וּכְתִיב בַּמָּן (שמות ט״ז:כ״ו) שֵׁשֶׁת יָמִים תִּלְקְטֻהוּ וּבְיוֹם הַשְּׁבִיעִי שַׁבָּת לא יִהְיֶה בּוֹ. כֵּיוָן דְּלָא מִשְׁתְּכַח בֵּיהּ מְזוֹנֵי, מַה בִּרְכְתָא אִשְׁתְּכַח בֵּיהּ.","אֶלָּא הָכִי תָּאנָא, כָּל בִּרְכָּאן דִּלְעֵילָּא וְתַתָּא, בְּיוֹמָא שְׁבִיעָאָה תַּלְיָין. וְתָאנָא, אֲמַאי לָא אִשְׁתְּכַח מָנָּא בְּיוֹמָא שְׁבִיעָאָה, מִשּׁוּם דְּהַהוּא יוֹמָא, מִתְבָּרְכָאן מִינֵּיהּ כָּל שִׁיתָא יוֹמִין עִלָּאִין, וְכָל חַד וְחַד יָהִיב מְזוֹנֵיהּ לְתַתָּא, כָּל חַד בְּיוֹמוֹי, מֵהַהִיא בְּרָכָה דְּמִתְבָּרְכָאן בְּיוֹמָא שְׁבִיעָאָה.","וּבְגִינֵי כַּךְ, מַאן דְּאִיהוּ בְּדַרְגָּא דִּמְהֵימָנוּתָא, בָּעֵי לְסַדְּרָא פָּתוֹרָא, וּלְאַתְקְנָא סְעוּדָתָא בְּלֵילְיָא דְּשַׁבְּתָא, בְּגִין דְּיִתְבָּרֵךְ פָּתוֹרֵיהּ, כָּל אִינּוּן שִׁיתָא יוֹמִין, דְּהָא בְּהַהוּא זִמְנָא, אִזְדָּמַן בְּרָכָה, לְאִתְבָּרְכָא כָּל שִׁיתָא יוֹמִין דְּשַׁבְּתָא, וּבִרְכָתָא לָא אִשְׁתְּכַח בְּפָתוֹרָא רֵיקָנַיָּא. וְעַל כַּךְ, בָּעֵי לְסַדְּרָא פָּתוֹרֵיהּ בְּלֵילְיָא דְּשַׁבְּתָא, בְּנַהֲמֵי וּבִמְזוֹנֵי.","רַבִּי יִצְחָק אָמַר, אֲפִילוּ בְּיוֹמָא דְּשַׁבְּתָא נָמֵי. רַבִּי יְהוּדָה אָמַר, בָּעֵי לְאִתְעַנְגָּא בְּהַאי יוֹמָא, וּלְמֵיכַל תְּלַת סְעוּדָתֵי בְּשַׁבְּתָא, בְּגִין דְּיִשְׁתְּכַח שָׂבְעָא וְעִנּוּגָא בְּהַאי יוֹמָא בְּעָלְמָא.","רַבִּי אַבָּא אָמַר, לְאִזְדַּמְּנָא בִּרְכְתָא בְּאִינּוּן יוֹמִין דִּלְעֵילָּא, דְּמִתְבָּרְכָאן מֵהַאי יוֹמָא. וְהַאי יוֹמָא, מַלְיָא רֵישֵׁיהּ דִּזְעֵיר אַנְפִּין, מִטַּלָּא דְּנָחִית מֵעַתִּיקָא קַדִּישָׁא סְתִימָא דְּכֹלָּא, וְאָטִיל לְחַקְלָא דְּתַפּוּחִין קַדִּישִׁין, תְּלַת זִמְנֵי, מִכַּד עָיִיִל שַׁבְּתָא, דְּיִתְבָּרְכוּן כֻּלְּהוּ כַּחֲדָא.","וְעַל דָּא בָּעֵי בַּר נָשׁ, לְאִתְעַנְגָּא תְּלַת זִמְנִין אִלֵּין, דְּהָא בְּהָא תַּלְיָא מְהֵימָנוּתָא דִּלְעֵילָּא, בְּעַתִּיקָא קַדִּישָׁא, וּבִזְעֵיר אַפִּין, וּבְחַקְלָא דְּתַפּוּחִין. וּבָעֵי בַּר נָשׁ לְאִתְעַנְגָּא בְּהוּ, וּלְמֵחדֵי בְּהוּ. וּמַאן דְּגָרַע סְעוּדָתָא מִנַיְיהוּ, אַחְזֵי פְּגִימוּתָא לְעֵילָא וְעוֹנְשֵׁיהּ דְּהַהוּא בַּר נָשׁ סַגִּי.","בְּגִינֵי כַּךְ, בָּעֵי לְסַדְּרָא פָּתוֹרֵיהּ, תְּלַת זִמְנֵי, מִכַּד עָיִיִל שַׁבְּתָא, וְלָא יִשְׁתְּכַּח פָּתוֹרֵיהּ רֵיקָנַיָּא, וְתִשְׁרֵי בִּרְכְתָא עֲלֵיהּ, כָּל שְׁאַר יוֹמֵי דְּשַׁבְּתָא. וּבְהַאי מִלָּה, אַחְזֵי, וְתָלֵי מְהֵימָנוּתָא לְעֵילָּא.","רַבִּי שִׁמְעוֹן אָמַר, הַאי מַאן דְּאַשְׁלִים תְּלַת סְעוּדָתֵי בְּשַׁבָּתָא, קָלָא נָפִיק וּמַכְרְזָא עָלֵיהּ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', דָּא סְעוּדָתָא חֲדָא, לָקֳבֵל (ויקרא רפ\"ח ע\"ב) עַתִּיקָא קַדִּישָׁא דְּכָל קַדִּישִׁין. וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ, דָּא סְעוּדָתָא תִּנְיָינָא, לָקֳבֵל חַקְלָא דְּתַפּוּחִין קַדִּישִׁין. וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ, דָּא הוּא שְׁלִימוּ דְּאִשְׁתְּלִים בִּזְעֵיר אַפִּין.","וּלֳקָבְלַיְיהוּ בָּעֵי לְאַשְׁלְמָא סְעוּדָתֵיהּ, וּבָעֵי לְאִתְעַנְגָּא בְּכֻלְּהוּ סְעוּדָתֵי, וּלְמֵחדֵי בְּכָל חַד וְחַד מִנַּיְיהוּ, מִשּׁוּם דְּאִיהוּ מְהֵימָנוּתָא שְׁלֵימָתָא. וּבְגִין כַּךְ, שַׁבְּתָא אִתְיָקָּר, מִכָּל שְׁאַר זִמְנִין וְחַגִּין, מִשּׁוּם דְּכֹלָּא בֵּיהּ אִשְׁתְּכַח, וְלָא אִשְׁתְּכַח הָכִי בְּכֻלְּהוּ זִמְנֵי וְחַגֵּי. אָמַר רַבִּי חִיָּיא, בְּגִין כָּךְ, מִשּׁוּם דְּאִשְׁתְּכַח כֹּלָּא בֵּיהּ, אִידְכַּר תְּלַת זִמְנִין. דִּכְתִּיב, (בראשית ב׳:ב׳) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלהִים אֶת יוֹם הַשְּׁבִיעִי.","רַבִּי אַבָּא, (נ\"א רב המנונא סבא) כַּד הֲוָה יָתִיב בִּסְעוּדָתָא דְּשַׁבְּתָא, הֲוֵי חַדֵּי, בְּכָל חַד וְחַד, וַהֲוָה אָמַר, דָּא הִיא סְעוּדָתָא קַדִּישָׁא, דְּעַתִּיקָא קַדִּישָׁא סְתִימָא דְּכֹלָּא. בִּסְעוּדָתָא אַחֲרָא הֲוָה אָמַר, דָּא הִיא סְעוּדָתָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְכֵן בְּכֻלְּהוּ סְעוּדָתֵי, וַהֲוָה חַדֵּי בְּכָל חַד וְחַד. כַּד הֲוָה אַשְׁלִים סְעוּדָתֵי, אָמַר אַשְׁלִימוּ סְעוּדָתֵי דִּמְהֵימָנוּתָא."],[[0,"ר' שמעון אמר וכו':","רש\"א, לא נזכר השם הקדוש אלא על עולם שלם, היינו השם הויה, שכתוב, ביום עשות הויה אלקים ארץ ושמים. מכאן, שלא להזכיר השם הקדוש בריקנות. וכתוב, לא תשא את שם ה' אלקיך לשוא."],[1,"ותנינן א\"ר יוסי וכו':","ולמדנו אר\"י, מהו ברכה. הוא השם הקדוש, משום שממנו נמצאת הברכה בכל העולם. וברכה אינה נמצאת במקום ריק ואינה שורה עליו. זהו שכתוב, לא תשא את שם ה' אלקיך לשוא."],[2,"זכור את יום השבת לקדשו:","ר' יצחק אמר, כתוב, ויברך אלקים את יום השביעי, וכתוב במן ששת ימים תלקטוהו וביום השביעי שבת לא יהיה בו. שואל, כיון שאינו נמצא בו מזון, מהו הברכה שנמצא בו."],[3,"אלא הכי תאנא וכו':","ומשיב, אלא כך למדנו. כל הברכות שלמעלה ומטה תלויות ביום השביעי. ולמדנו, למה לא היה נמצא מן ביום השביעי, משום שמיום ההוא מתברכים כל ששה ימים העליונים, שהם חג\"ת נה\"י, וכל אחד ואחד נותן מזון למטה כל אחד ביומו, מברכה ההיא שמתברכים ביום השביעי."],[4,"ובגיני כך מאן וכו':","ומשום זה, מי שהוא במדרגת האמונה, צריך לסדר השלחן ולתקן סעודה בליל שבת, כדי שיתברך שלחנו כל אלו ששת ימים, כי בזמן ההוא נזדמן הברכה להתברך כל ששת ימי השבת, וברכה אינה נמצאת בשלחן ריק, ועל כך, צריכים לסדר השלחן בליל שבת בלחם ומזון. כדי להמשיך ברכה לששת ימים."],[5,"ר' יצחק אמר וכו':","רי\"א, אפילו ביום השבת גם כן צריכים לסדר סעודה ולהמשיך ברכה לששת ימים. ר' יהודה אמר, צריכים להתענג ביום ההוא, ולאכול ג' סעודות בשבת, כדי שימצא שובע ועונג בעולם ביום ההוא."],[6,"ר' אבא אמר וכו':","רא\"א, שהטעם של ג' סעודות, הוא, כדי להמשיך ברכות בימים אלו של מעלה חג\"ת נה\"י, המתברכים מיום ההוא, שהוא השכינה מדה השביעית. ויום הזה, מלא ראשו של ז\"א, דהיינו הג\"ר שלו, מטל, דהיינו שפע, היורד מעתיקא קדישא הסתום לכל, ומשפיע לחקל תפוחין קדישין, שהוא השכינה, ג' פעמים מעת כניסת השבת, שיתברכו כולם כאחד."],[6,"","ביאור הדברים. ז' ימים ה\"ס ז' ספירות חג\"ת נהי\"מ. שז\"א כולל ששת ימים, והמלכות ה\"ס יום השביעי. וע\"כ ביום השביעי מתגלה שלמות המלכות ובנינה פב\"פ עם ז\"א, והם עולים ומלבישים את או\"א עלאין ומקבלים השפע מפה דא\"א הנקרא עתיקא סתימאה. אבל בימות החול אין שלמות למלכות מטרם גמר התקון, ונמצא ז\"א שאינו בזווג השלם עם המלכות, וכשאינו בזווג עם המלכות הוא חסר ג\"ר. וע\"כ נבחן, שביום השבת כשנשלמה המלכות, ובאה בזווג עם ז\"א, מקבל ז\"א ג\"ר על ידי המלכות, והששה ימים של ז\"א מתברכים בג\"ר על ידה."],[6,"","וזה אמרו. \u0003לאזדמנא ברכתא באינון יומין דלעילא,\u0004 שהם חג\"ת נה\"י דז\"א, כי בשבת מקבל ג\"ר ממנה ע\"י זווגה עמה. אמנם אין למלכות כלום אלא מה שמקבלת מז\"א. וזה אמרו, \u0003והאי יומא מליא רישיה דז\"א\u0004 וכו' \u0003ואטיל לחקלא דתפוחין קדישין.\u0004 כי כל השפעה באה אל המלכות מז\"א. ואע\"פ שששת ימים דז\"א מתברכים בג\"ר ממנה, זה הוא רק מכח הזווג עמה כנ\"ל."],[7,"ועל דא בעי וכו':","ועל כן צריך האדם להתענג אלו ג' פעמים כי בזה תלויה האמונה שלמעלה, בעתיקא קדישא, ובזעיר אנפין, ובשדה תפוחים הקדושים, דהיינו שז\"א מקבל מעתיקא ומשפיע למלכות כנ\"ל. וצריך האדם להתענג בהם ולשמוח בהם. ומי שגורע סעודה מהם מראה פגם למעלה, ועונשו של האדם מרובה."],[8,"בגיני כך בעי וכו':","משום זה צריך לסדר שלחנו ג' פעמים מעת כניסת השבת, ולא ימצא שלחנו ריקם, ותשרה הברכה עליו כל שאר ימי השבת. ובדבר זה מראה, ותלויה, האמונה שלמעלה."],[9,"ר' שמעון אמר וכו':","רש\"א, מי שהשלים שלשה סעודות בשבת, קול יוצא ומכריז עליו, \u0003אז תתענג על ה',\u0004 זהו סעודה אחת כנגד עתיקא קדישא דכל קדישין. \u0003והרכבתיך על במתי ארץ,\u0004 זהו סעודה שניה, כנגד שדה תפוחים הקדושים, שהוא המלכות. \u0003והאכלתיך נחלת יעקב אביך,\u0004 זהו השלמות שנשלם בזעיר אנפין. בסעודה שלישית."],[10,"ולקבלייהו בעי וכו':","וכנגדם צריך להשלים סעודותיו, וצריך להתענג בכל הסעודות, ולשמוח בכל אחת ואחת מהן, משום שהיא אמונה שלמה. ומשום זה חשוב השבת יותר מכל שאר הזמנים והחגים, משום שהכל נמצא בו, ולא נמצא כן בכל הזמנים והחגים. א\"ר חייא משום כך, משום שנמצא הכל בו, נזכר ג' פעמים, שכתוב, ויכל אלקים ביום השביעי, וישבות ביום השביעי, ויברך אלקים את יום השביעי."],[11,"ר' אבא כד וכו':","ר' אבא, כשהיה יושב בסעודה של שבת, היה שמח בכל אחת ואחת, והיה אומר, זו היא הסעודה הקדושה של עתיקא קדישא הסתום לכל. בסעודה האחרת היה אומר, זו היא סעודה דקודשא בריך הוא, היינו דז\"א. וכן בכל סעודה וסעודה. כשהשלים הסעודות, אמר נשלמו הסעודות של האמונה."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, לֹא נִזְכַּר שְׁמוֹ הַקָּדוֹשׁ אֶלָּא עַל עוֹלָם שָׁלֵם, שֶׁכָּתוּב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. מִכָּאן שֶׁלֹּא לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ בְּרֵיקָנוּת. וְכָתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא. (כתוב לא תשא את שם ה' אלהיך לשוא, שלא להזכיר שם הקדוש בריקנות, אלא בברכה או בתפלה. ומי שמזכיר השם הקדוש בריקנות, שלא בברכה או בתפלה, כאשר נשמתו תצא ממגו עתידים להפרע ממגו ולנקם ממגו נקמות, שכתוב כי לא ינקה ה' את אשר ישא את שמו לשוא)."],[1,"","וְשָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מַהִי בְּרָכָה? הַשֵּׁם הַקָּדוֹשׁ. מִשּׁוּם שֶׁמִּמֶּנּוּ נִמְצֵאת הַבְּרָכָה לְכָל הָעוֹלָם, וְהַבְּרָכָה לֹא נִמְצֵאת עַל מָקוֹם רֵיק וְלֹא שׁוֹרָה עָלָיו. זֶהוּ שֶׁכָּתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא."],[2,"","זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. רַבִּי יִצְחָק אָמַר, כָּתוּב (שם א) וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי, וְכָתוּב בַּמָּן (שמות טז) שֵׁשֶׁת יָמִים תִּלְקְטֻהוּ וּבַיּוֹם הַשְּׁבִיעִי שַׁבָּת לֹא יִהְיֶה בּוֹ. כֵּיוָן שֶׁלֹּא נִמְצָא בּוֹ מְזוֹנוֹת, אֵיזוֹ בְּרָכָה נִמְצֵאת בּוֹ?"],[3,"","אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַבְּרָכוֹת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה תְּלוּיוֹת בַּיּוֹם הַשְּׁבִיעִי. וְשָׁנִינוּ, לָמָּה לֹא נִמְצָא מָן בַּיּוֹם הַשְּׁבִיעִי? מִשּׁוּם שֶׁמֵּאוֹתוֹ יוֹם מִתְבָּרְכִים כָּל שֵׁשֶׁת הַיָּמִים הָעֶלְיוֹנִים, וְכָל אֶחָד וְאֶחָד נוֹתֵן מְזוֹנוֹ לְמַטָּה, כָּל אֶחָד בְּיוֹמוֹ, מֵאוֹתָהּ בְּרָכָה שֶׁמִּתְבָּרְכִים בַּיּוֹם הַשְּׁבִיעִי."],[4,"","וּמִשּׁוּם כָּךְ, מִי שֶׁהוּא בְּדַרְגַּת הָאֱמוּנָה, צָרִיךְ לְסַדֵּר שֻׁלְחָן וּלְתַקֵּן סְעוּדָה בְּלֵיל שַׁבָּת כְּדֵי שֶׁיִּתְבָּרֵךְ שֻׁלְחָנוֹ כָּל אוֹתָם שִׁשָּׁה יָמִים, שֶׁהֲרֵי בְּאוֹתוֹ זְמַן מִזְדַּמֶּנֶת הַבְּרָכָה לְהִתְבָּרֵךְ כָּל שֵׁשֶׁת יְמֵי הַשַּׁבָּת, וְהַבְּרָכָה לֹא נִמְצֵאת בְּשֻׁלְחָן רֵיק, וְעַל כָּךְ צָרִיךְ לְסַדֵּר שֻׁלְחָנוֹ בְּעֶרֶב שַׁבָּת בִּלְחָמִים וּמְזוֹנוֹת."],[5,"","רַבִּי יִצְחָק אָמַר, אֲפִלּוּ בְּיוֹם הַשַּׁבָּת גַּם. רַבִּי יְהוּדָה אָמַר, צָרִיךְ לְהִתְעַנֵּג בַּיּוֹם הַזֶּה וְלֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, כְּדֵי שֶׁיִּמָּצְאוּ שּׁבַע וְעֹנֶג בַּיּוֹם הַזֶּה בָּעוֹלָם."],[6,"","רַבִּי אַבָּא אָמַר, לְהַזְמִין בְּרָכָה בְּאוֹתָם יָמִים שֶׁלְּמַעְלָה שֶׁמִּתְבָּרְכִים מִן הַיּוֹם הַזֶּה, וּבַיּוֹם הַזֶּה מָלֵא רֹאשׁוֹ שֶׁל זְעֵיר אַנְפִּין מִטַּל שֶׁנּוֹחֵת מֵהָעַתִּיק הַקָּדוֹשׁ הַנִּסְתָּר שֶׁל הַכֹּל, וּמַטִּיל לִשְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים שָׁלֹשׁ פְּעָמִים מִשֶּׁנִּכְנֶסֶת שַׁבָּת, שֶׁכֻּלָּם יִתְבָּרְכוּ כְּאֶחָד."],[7,"","וְעַל זֶה צָרִיךְ אָדָם לְהִתְעַנֵּג שְׁלֹשׁ הַפְּעָמִים הַלָּלוּ, שֶׁהֲרֵי בָּזֶה תְּלוּיָה הָאֱמוּנָה הָעֶלְיוֹנָה - בָּעַתִּיק הַקָּדוֹשׁ, וּבִזְעֵיר אַנְפִּין, וּבִשְׂדֵה הַתַּפּוּחִים. וְצָרִיךְ אָדָם לְהִתְעַנֵּג בָּהֶם וְלִשְׂמֹחַ בָּהֶם. וּמִי שֶׁגּוֹרֵעַ סְעוּדָה מֵהֶם, מַרְאֶה פְּגָם לְמַעְלָה, וְעָנְשׁוֹ שֶׁל הָאָדָם הַהוּא גָּדוֹל."],[8,"","מִשּׁוּם כָּךְ צָרִיךְ לְסַדֵּר שֻׁלְחָנוֹ שָׁלֹשׁ פְּעָמִים מִשֶּׁנִּכְנֶסֶת שַׁבָּת, וְלֹא יִמָּצֵא שֻׁלְחָנוֹ רֵיק, וְתִשְׁרֶה עָלָיו הַבְּרָכָה כָּל שְׁאָר יְמוֹת הַשַּׁבָּת, וּבַדָּבָר הַזֶּה מַרְאֶה וְתוֹלֶה אֶת הָאֱמוּנָה הָעֶלְיוֹנָה."],[9,"","רַבִּי שִׁמְעוֹן אָמַר, זֶה מִי שֶׁמַּשְׁלִים שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, קוֹל יוֹצֵא וּמַכְרִיז עָלָיו: (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. זוֹ סְעוּדָה אַחַת כְּנֶגֶד הָעַתִּיק הַקָּדוֹשׁ שֶׁל כָּל הַקְּדוֹשִׁים. וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ - זוֹ סְעוּדָה שְׁנִיָּה כְּנֶגֶד שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ - זוֹהִי הַשְּׁלֵמוּת שֶׁהִשְׁתַּלְּמָה בִּזְעֵיר אַנְפִּין."],[10,"","וּכְנֶגְדָּם צָרִיךְ לְהַשְׁלִים סְעוּדָתוֹ, וְצָרִיךְ לְהִתְעַנֵּג בְּכָל הַסְּעוּדוֹת וְלִשְׂמֹחַ בְּכָל אַחַת וְאַחַת מֵהֶן, מִשּׁוּם שֶׁהִיא הָאֱמוּנָה הַשְּׁלֵמָה, וּמִשּׁוּם כָּךְ הַשַּׁבָּת נִתְכַּבְּדָה מִכָּל שְׁאָר הַזְּמַנִּים וְהַחַגִּים, מִשּׁוּם שֶׁהַכֹּל בָּהּ נִמְצָא, וְלֹא נִמְצָא כָּךְ בְּכָל הַזְּמַנִּים וְהַחַגִּים. אָמַר רַבִּי חִיָּיא, מִשּׁוּם כָּךְ, מִשּׁוּם שֶׁהַכֹּל נִמְצָא בּוֹ, נִזְכַּר שָׁלֹשׁ פְּעָמִים, שֶׁכָּתוּב (בראשית ב) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי."],[11,"","רַבִּי אַבָּא (רב המנונא סבא), כְּשֶׁהָיָה יוֹשֵׁב בִּסְעוּדַת הַשַּׁבָּת, הָיָה שָׂמֵחַ בְּכָל אַחַת וְאַחַת, וְהָיָה אוֹמֵר: זוֹהִי סְעוּדָה קְדוֹשָׁה שֶׁל הָעַתִּיק הַקָּדוֹשׁ הַנִּסְתָּר שֶׁל הַכֹּל. בַּסְּעוּדָה הָאַחֶרֶת הָיָה אוֹמֵר: זוֹהִי סְעוּדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵן בְּכָל הַסְּעוּדוֹת. וְהָיָה שָׂמֵחַ בְּכָל אַחַת וְאַחַת. כְּשֶׁהָיָה מַשְׁלִים אֶת הַסְּעוּדוֹת, אוֹמֵר: נִשְׁלְמוּ סְעוּדוֹת הָאֱמוּנָה."]]],[["רַבִּי שִׁמְעוֹן, כַּד הֲוָה אָתֵי לִסְעוּדָתָא, הֲוָה אָמַר הָכִי, אַתְקִינוּ סְעוּדָתָא דִּמְהֵימְנוּתָא עִלָּאָה, אַתְקִינוּ סְעוּדָתָא דְּמַלְכָּא, וַהֲוָה יָתִיב וְחַדֵּי. כַּד אַשְׁלִים סְעוּדָתָא תְּלִיתָאָה, הֲווֹ מַכְרִזֵי עָלֵיהּ, אָז תִּתְעַנַּג עַל יְיָ' וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ.","אָמַר רַבִּי אֶלְעָזָר לְאָבוּי, אִלֵּין סְעוּדָתֵי הֵיךְ מִתְתַּקְנִין. אָמַר לֵיהּ, לֵילְיָא דְּשַׁבְּתָא, כְּתִיב, וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ. בֵּיהּ בְּלֵילְיָא, מִתְבָּרְכָא מַטְרוֹנִיתָא, וְכֻלְּהוּ חֲקַל תַּפּוּחִין, וּמִתְבָּרְכָא פָּתוֹרֵיהּ דְּבַר נָשׁ, וְנִשְׁמְתָא אִתּוֹסְפַת, וְהַהוּא לֵילְיָא, חֶדְוָה דְּמַטְרוֹנִיתָא הֲוֵי. וּבָעֵי בַּר נָשׁ לְמֶחדֵי בְּחֶדְוָותָא, וּלְמֵיכַל סְעוּדָתָא דְּמַטְרוֹנִיתָא.","בְּיוֹמָא דְּשַׁבְּתָא, בִּסְעוּדָתָא תִּנְיָינָא, כְּתִיב (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ'. עַל יְיָ' וַדַּאי. דְּהַהִיא שַׁעֲתָא אִתְגַּלְיָא עַתִּיקָא קַדִּישָׁא, וְכֻלְּהוּ עָלְמִין בְּחֶדְוָותָא, וּשְׁלִימוּ וְחֶדְוָותָא דְּעַתִּיקָא עַבְדֵּינָן, וּסְעוּדָתָא דִּילֵיהּ הוּא וַדַּאי.","בִּסְעוּדָתָא תְּלִיתָאָה דְּשַׁבְּתָא, כְּתִיב וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ. דָּא הִיא סְעוּדָתָא דִּזְעֵיר אַפִּין, דְּהַוֵי בִּשְׁלֵימוּתָא. וְכֻלְּהוּ שִׁיתָא יוֹמִין, מֵהַהוּא שְׁלִימוּ מִתְבָּרְכָן. וּבָעֵי בַּר נָשׁ לְמֶחדֵי בִּסְעוּדָתֵיהּ, וּלְאַשְׁלְמָא אִלֵּין סְעוּדָתֵי, דְּאִינּוּן סְעוּדָתֵי מְהֵימָנוּתָא שְׁלֵימָתָא, דְּזַרְעָא קַדִּישָׁא דְּיִשְׂרָאֵל, דִּי מְהֵימָנוּתָא עִלָּאָה, דְּהָא דִּילְהוֹן הִיא, וְלָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבְגִינִי כַּךְ אָמַר, (שמות לא) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל.","תָּא חֲזֵי, בִּסְעוּדָתֵי אִלֵּין, אִשְׁתְּמוֹדְעוּן יִשְׂרָאֵל, דְּאִינּוּן בְּנִי מַלְכָּא. דְּאִינּוּן מֵהֵיכָלָא דְּמַלְכָּא, דְּאִינּוּן בְּנִי מְהֵימָנוּתָא, וּמַאן דְּפָגִים חַד סְעוּדָתָא מִנַּיְיהוּ, אַחְזֵי פְּגִימוּתָא לְעֵילָּא, וְאַחְזֵי גַּרְמֵיהּ דְּלָאו מִבְּנֵי מַלְכָּא עִלָּאָה הוּא, דְּלָאו מִבְּנֵי הֵיכָלָא דְּמַלְכָּא הוּא דְּלָאו מִזַּרְעָא קַדִּישָׁא דְּיִשְׂרָאֵל הוּא. וְיָהֲבִין עָלֵיהּ חוּמְרָא דִּתְלַת מִלִּין, דִּינָא דְּגֵיהִנָּם וְגו'.","וְתָא חֲזִי, בְּכֻלְּהוּ שְׁאַר זִמְנִין וְחַגִּין, בָּעֵי בַּר נָשׁ לֶחְדֵי, וּלְמֵחְדֵי לְמִסְכְּנֵי. וְאִי הוּא חַדֵּי בִּלְחוֹדוֹי, וְלָא יָהִיב לְמִסְכְּנֵי, עוֹנְשֵׁיהּ סַגִּי, דְּהָא בִּלְחוֹדוֹי חַדֵּי, וְלָא יָהִיב חִדוּ לְאָחֲרָא. עָלֵיהּ כְּתִיב, (מלאכי ב׳:ג׳) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם פֶּרֶשׁ חַגֵּיכֶם. וְאִי אִיהוּ בְּשַׁבָּתָא חַדֵּי, אַף עַל גַּב דְּלָא יָהִיב לְאַחֲרָא, לָא יַהֲבִין עָלֵיהּ עוֹנְשָׁא, כִּשְׁאַר זִמְנִין וְחַגִּין, דִּכְתִּיב פֶּרֶשׁ חַגֵּיכֶם. פֶּרְשׁ חַגֵּיכֶם קָאָמַר, וְלֹא פֶּרֶשׁ שַׁבַּתְּכֶם. וּכְתִיב (ישעיהו א׳:י״ד) חָדְשֵׁיכֶם וּמוֹעֲדֵיכֶם שָׂנְאָה נַפְשִׁי. וְאִלּוּ שַׁבָּת לָא קָאָמַר.","וּבְגִינֵי כַּךְ כְּתִיב, בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וּמִשּׁוּם דְּכָל מְהֵימָנוּתָא אִשְׁתְּכַח בְּשַׁבָּתָא, יַהֲבִין לֵיהּ לְבַר נָשׁ נִשְׁמְתָא אַחֲרָא, נִשְׁמְתָא עִלָּאָה, נִשְׁמְתָא דְּכָל שְׁלִימוּ בָּהּ, כְּדוּגְמָא דְּעָלְמָא דְּאָתֵי. וּבְגִינֵי כַּךְ אִקְרֵי שַׁבָּת. מַהוּ שַׁבָּת. שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא. שְׁמָא דְּאִיהוּ שְׁלִים מִכָּל סִטְרוֹי.","אָמַר רַבִּי יוֹסִי, וַדַּאי כַּךְ הוּא. וַוי לֵיהּ לְבַר נָשׁ, דְּלָא אַשְׁלִים חֶדָוָותָא דְּמַלְכָּא קַדִּישָׁא. וּמַאן חֶדְוָותָא דֵּילֵיהּ. אִלֵּין תְּלַת סְעוּדָתֵי מְהֵימָנוּתָא. סְעוּדָתֵי דְּאַבְרָהָם יִצְחָק וְיַעֲקֹב כְּלִילָן בְּהוּ. וְכֻלְּהוּ חִדוּ עַל חִדוּ מְהֵימָנוּתָא שְׁלֵימוּתָא, מִכָּל סִטְרוֹי.","תָּאנָא, בַּהֲדֵין יוֹמָא מִתְעַטְּרָן אֲבָהָן, וְכָל בְּנִין יַנְקִין, מַה דְּלָאו הָכִי בְּכָל שְׁאַר חַגִּין וּזְמָנִין. בַּהֲדֵין יוֹמָא, חַיָּיבַיָּא דְּגֵיהִנָּם נַיְיחִין. בַּהֲדֵין יוֹמָא, כָּל דִּינִין אִתְכַּפְיָין, וְלָא מִתְעָרִין בְּעָלְמָא. בַּהֲדֵין יוֹמָא אוֹרַיְיתָא מִתְעַטְּרָא בְּעִטְרִין שְׁלֵימִין. בַּהֲדֵין יוֹמָא, חֶדְוָותָא וְתַפְנוּקָא אִשְׁתְּמַע, בְּמָאתָן וְחַמְשִׁין עָלְמִין.","תָּא חֲזִי, בְּכָל שִׁיתָא יוֹמֵי דְּשַׁבְּתָא, כַּד מָטָא שַׁעֲתָא דִּצְלוֹתָא דְּמִנְחָה, דִּינָא (קנ\"ו ע\"א) תַּקִּיפָא שַׁלְטָא, וְכָל דִּינִין מִתְעָרִין. אֲבָל בְּיוֹמָא דְּשַׁבְּתָא, כַּד מָטָא עִדַן דִּצְלוֹתָא דְּמִנְחָה, רַעֲוָא דְּרַעֲוִין אִשְׁתְּכַח, וְעַתִּיקָא קַדִּישָׁא גַּלְיָא רָצוֹן דִּילֵיהּ, וְכָל דִּינִין מִתְכַּפְיָין, וּמִשְׁתְּכַח רְעוּתָא וְחֵדּוּ בְּכֹלָּא."],[[0,"ר' שמעון כד הוה וכו':","ר\"ש כשהיה בא אל הסעודה, היה אומר כך, התקינו הסעודה של האמונה העליונה. התקינו הסעודה של המלך והיה יושב ושמח. כשהשלים סעודה השלישית, היו מכריזים עליו, אז תתענג על ה' והרכבתיך על במתי ארץ והאכלתיך נחלת יעקב אביך."],[1,"אמר ר' אלעזר לאבוי וכו':","אר\"א לאביו, אלו הסעודות איך מתתקנות. אמר לו, ליל שבת, כתוב, והרכבתיך על במתי ארץ, בו בלילה מתברכת המטרוניתא, וכל שדה התפוחים, שהיא המלכות, ומתברך שלחנו של אדם, ונשמה נתוספת לאדם, ולילה ההוא שמחת המטרוניתא הוא, וצריך האדם לשמוח בשמחה ולאכול הסעודה של המטרוניתא, שהיא המלכות."],[2,"ביומא דשבתא בסעודתא וכו':","ביום השבת בסעודה השניה, כתוב, אז תתענג על ה', על ה' ודאי, שפירושו למעלה מז\"א, כי בשעה ההיא מתגלה עתיקא קדישא, וכל העולמות הם בשמחה, והשלמות והשמחה של עתיקא אנו עושים. והסעודה שלו היא, ודאי."],[3,"בסעודתא תליתאה דשבתא וכו':","בסעודה הג' של שבת, כתוב, והאכלתיך נחלת יעקב אביך. זו היא הסעודה של זעיר אנפין שהוא בשלמות, וכל ששת הימים משלמות ההיא מתברכים, וצריך האדם לשמוח בסעודתו, ולהשלים אלו הסעודות, שהם סעודות האמונה השלמה של זרע הקדוש דישראל, של האמונה העליונה, כי שלהם הוא ולא של עמים עכו\"ם, ומשום זה אמר, ביני ובין בני ישראל."],[4,"ת\"ח בסעודתי וכו':","בוא וראה, בסעודות האלו ניכרים ישראל שהם בני המלך, שהם מהיכל המלך, שהם בני האמונה. ומי שפוגם סעודה אחת מהם, מראה פגם למעלה, ומראה עצמו, שאינו מבני המלך העליון, שאינו מבני היכל המלך, שאינו מזרע קדוש של ישראל, ונותנים עליו כובד של ג' דברים, דין גיהנם ומלחמת גוג ומגוג, וחבלי משיח. (שבת קי\"ח)."],[5,"ותא חזי בכלהו וכו':","ובוא וראה, בכל שאר הזמנים והחגים צריך האדם לשמוח ולשמח את העני. ואם הוא שמח בלבדו, ואינו נותן לעני, עונשו גדול, כי שמח בלבדו ואינו נותן שמחה לאחר. עליו כתוב, וזריתי פרש על פניכם פרש חגיכם. ואם הוא שמח בשבת, אע\"פ שאינו נותן לאחר, אין נותנים עליו עונש כשאר הזמנים והחגים, שכתוב, פרש חגיכם. פרש חגיכם אומר ולא פרש שבתכם. וכתוב, חדשיכם ומועדיכם שנאה נפשי. ואלו שבת אינו אומר."],[6,"ובגיני כך כתיב וכו':","ומשום זה כתוב, ביני ובין בני ישראל. ומשום שכל האמונה נמצא בשבת, נותנים לאדם נשמה אחרת, נשמה עליונה, נשמה שכל השלמות בה כמו עולם הבא. ומשום זה נקרא שבת. מהו שבת. הוא השם של הקב\"ה. שהוא המלכות. השם, שהוא שלם מכל צדדיו. ביום השבת."],[7,"אמר ר' יוסי וכו':","אר\"י. ודאי כך הוא, אוי לו לאדם שאינו משלים השמחה של מלך הקדוש. ומהו השמחה שלו. הוא אלו ג' הסעודות של האמונה, סעודות שאברהם יצחק יעקב כלולים בהן, וכולם שמחה על שמחה, אמונה, שהיא המלכות, השלמה מכל צדדיה."],[8,"תאנא בהדין יומא וכו':","למדנו, ביום הזה,כל הדינים נכנעים ואינם מתעוררים הנעשים לג\"ר, וכל הבנים שהם נה\"י, יונקים מהם, מה שאין כן בכל החגים וזמנים. כלומר, שבשאר חגים וזמנים מתעטרים האבות במוחין דישסו\"ת אבל בשבת האבות מתעטרים במוחין דאו\"א עלאין. ביום הזה, נחים הרשעים בגיהנם, ביום הזה מתעטרים האבות, שהם חג\"ת בעולם. ביום הזה התורה, שהוא ז\"א, מתעטר בעטרות שלמות, דהיינו מאו\"א עלאין, ביום הזה, שמחה ועונג נשמע בר\"נ עולמות."],[9,"ת\"ח בכל שיתא וכו':","בוא וראה בכל ששת ימי השבת, כשמגיע שעת תפלת המנחה, דין קשה שולט, וכל הדינים מתעוררים, אבל ביום השבת, כשמגיע שעת תפלת המנחה, רצון הרצונות נמצא, ועתיקא קדישא מגלה הרצון שלו, וכל הדינים נכנעים, ונמצא רצון ושמחה בכל."]],[[0,"","כְּשֶׁרַבִּי שִׁמְעוֹן הָיָה בָּא לַסְּעוּדָה, הָיָה אוֹמֵר כָּךְ: הַתְקִינוּ סְעוּדָה שֶׁל הָאֱמוּנָה הָעֶלְיוֹנָה. הַתְקִינוּ סְעוּדַת הַמֶּלֶךְ. וְהָיָה יוֹשֵׁב וְשָׂמֵחַ. כְּשֶׁהִשְׁלִים סְעוּדָה שְׁלִישִׁית, הָיוּ מַכְרִיזִים עָלָיו: (ישעיהנח) אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ."],[1,"","אָמַר רַבִּי אֶלְעָזָר לְאָבִיו, אֵיךְ מְתַקְּנִים אֶת הַסְּעוּדוֹת הַלָּלוּ? אָמַר לוֹ, לֵיל שַׁבָּת כָּתוּב וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ. בּוֹ בַּלַּיְלָה מִתְבָּרֶכֶת הַגְּבִירָה וְכָל שְׂדֵה הַתַּפּוּחִים, וּמִתְבָּרֵךְ שֻׁלְחָנוֹ שֶׁל אָדָם, וּנְשָׁמָה נוֹסֶפֶת, וְאוֹתוֹ הַלַּיְלָה שִׂמְחַת הַגְּבִירָה הוּא."],[2,"","וְצָרִיךְ אָדָם לִשְׂמֹחַ בְּשִׂמְחָה וְלֶאֱכֹל סְעוּדַת הַגְּבִירָה. בְּיוֹם הַשַּׁבָּת, בַּסְּעוּדָה הַשְּׁנִיָּה כָּתוּב אָז תִּתְעַנַּג עַל ה'. עַל ה' וַדַּאי. שֶׁאוֹתָהּ שָׁעָה נִגְלֶה הָעַתִּיק הַקָּדוֹשׁ, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, וְהַשְּׁלֵמוּת וְהַחֶדְוָה שֶׁל הָעַתִּיק אָנוּ עוֹשִׂים, וְזוֹהִי סְעוּדָתוֹ וַדַּאי."],[3,"","בַּסְּעוּדָה הַשְּׁלִישִׁית שֶׁל שַׁבָּת כָּתוּב וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ. זוֹהִי הַסְּעוּדָה שֶׁל זְעֵיר אַנְפִּין שֶׁהוּא בִּשְׁלֵמוּת. וְכָל שֵׁשֶׁת הַיָּמִים מֵאוֹתָהּ שְׁלֵמוּת מִתְבָּרְכִים. וְצָרִיךְ אָדָם לִשְׂמֹחַ בִּסְעוּדָתוֹ וּלְהַשְׁלִים הַסְּעוּדוֹת הַלָּלוּ, שֶׁהֵן סְעוּדוֹת הָאֱמוּנָה הַשְּׁלֵמָה שֶׁל זֶרַע קָדוֹשׁ שֶׁל יִשְׂרָאֵל, שֶׁהָאֱמוּנָה הָעֶלְיוֹנָה הִיא שֶׁלָּהֶם וְלֹא שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּמִשּׁוּם כָּךְ אָמַר, (שמות לא) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל."],[4,"","בֹּא וּרְאֵה, בַּסְּעוּדוֹת הַלָּלוּ נוֹדָעִים יִשְׂרָאֵל שֶׁהֵם בְּנֵי הַמֶּלֶךְ וְשֶׁהֵם מֵהֵיכַל הַמֶּלֶךְ וְשֶׁהֵם בְּנֵי הָאֱמוּנָה, וּמִי שֶׁפּוֹגֵם סְעוּדָה אַחַת מֵהֶם, מַרְאֶה פְּגָם לְמַעְלָה, וּמַרְאֶה אֶת עַצְמוֹ שֶׁאֵינוֹ מִבְּנֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁאֵינוֹ מִבְּנֵי הֵיכַל הַמֶּלֶךְ, וְשֶׁאֵינוֹ מִזֶּרַע קָדוֹשׁ שֶׁל יִשְׂרָאֵל, וְנוֹתְנִים עָלָיו חֹמֶר שֶׁל שְׁלֹשָׁה דְבָרִים - דִּין הַגֵּיהִנֹּם וְכוּ'."],[5,"","וּבֹא רְאֵה, בְּכָל שְׁאָר הַזְּמַנִּים וְהַחַגִּים צָרִיךְ אָדָם לִשְׂמֹחַ וּלְשַׂמֵּחַ אֶת הָעֲנִיִּים, וְאִם הוּא שָׂמֵחַ לְבַדּוֹ וְלֹא נוֹתֵן לַעֲנִיִּים - עָנְשׁוֹ רַב, שֶׁהֲרֵי לְבַדּוֹ שָׂמֵחַ, וְלֹא נוֹתֵן שִׂמְחָה לְאַחֵר. עָלָיו כָּתוּב (מלאכי ב) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם פֶּרֶשׁ חַגֵּיכֶם. וְאִם הוּא שָׂמֵחַ בְּשַׁבָּת, אַף עַל גַּב שֶׁלֹּא נוֹתֵן לְאַחֵר - לֹא נוֹתְנִים עָלָיו עֹנֶשׁ כְּבִשְׁאָר הַזְּמַנִּים וְהַחַגִּים, שֶׁכָּתוּב פֶּרֶשׁ חַגֵּיכֶם. אָמַר פֶּרֶשׁ חַגֵּיכֶם, וְלֹא פֶּרֶשׁ שַׁבַּתְּכֶם. וְכָתוּב (ישעיה א) חָדְשֵׁיכֶם וּמוֹעֲדֵיכֶם שָׂנְאָה נַפְשִׁי. וְאִלּוּ שַׁבָּת לֹא אָמַר."],[6,"","וּמִשּׁוּם כָּךְ כָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וּמִשּׁוּם שֶׁכָּל הָאֱמוּנָה נִמְצֵאת בְּשַׁבָּת, נוֹתְנִים לָאָדָם נְשָׁמָה אַחֶרֶת, נְשָׁמָה עֶלְיוֹנָה, נְשָׁמָה שֶׁכָּל הַשְּׁלֵמוּת בָּהּ, כְּדֻגְמַת הָעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ נִקְרֵאת שַׁבָּת. מַה זֶּה שַׁבָּת? שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֵׁם שֶׁהוּא שָׁלֵם מִכָּל צְדָדָיו."],[7,"","אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא. אוֹי לָאָדָם שֶׁלֹּא מַשְׁלִים אֶת שִׂמְחַה הַמֶּלֶךְ הַקָּדוֹשׁ. וּמַהִי שִׂמְחָתוֹ? אֵלּוּ שְׁלֹשׁ הַסְּעוּדוֹת שֶׁל הָאֱמוּנָה, סְעוּדוֹת שֶׁאַבְרָהָם יִצְחָק וְיַעֲקֹב כְּלוּלִים בָּהֶם, וְכֻלָּם שִׂמְחָה עַל שִׂמְחָה, אֱמוּנָה שְׁלֵמָה מִכָּל צְדָדָיו."],[8,"","שָׁנִינוּ, בַּיּוֹם הַזֶּה מִתְעַטְּרִים הָאָבוֹת, וְכָל הַבָּנִים יוֹנְקִים, מַה שֶּׁאֵין כֵּן בְּכָל שְׁאָר הַחַגִּים וְהַזְּמַנִּים. בַּיּוֹם הַזֶּה רִשְׁעֵי הַגֵּיהִנֹּם נָחִים. בַּיּוֹם הַזֶּה כָּל הַדִּינִים נִכְפִּים וְלֹא מִתְעוֹרְרִים בָּעוֹלָם. בַּיּוֹם הַזֶּה הַתּוֹרָה מִתְעַטֶּרֶת בַּעֲטָרוֹת שְׁלֵמוֹת. בַּיּוֹם הַזֶּה שִׂמְחָה וְתַפְנוּק נִשְׁמָעִים בְּמָאתַיִם וַחֲמִשִּׁים עוֹלָמוֹת."],[9,"","בֹּא וּרְאֵה, בְּכָל שֵׁשֶׁת יְמֵי הַשַּׁבָּת, כְּשֶׁמַּגִּיעָה שְׁעַת תְּפִלַּת הַמִּנְחָה, הַדִּין הַקָּשֶׁה שׁוֹלֵט וְכָל הַדִּינִים מִתְעוֹרְרִים, אֲבָל בְּיוֹם הַשַּׁבָּת, כְּשֶׁמַּגִּיעַ זְמַן תְּפִלַּת הַמִּנְחָה, נִמְצָא רְצוֹן הָרְצוֹנוֹת, וְהָעַתִּיק הַקָּדוֹשׁ מְגַלֶּה רְצוֹנוֹ, וְכָל הַדִּינִים נִכְפִּים, וְנִמְצָא רָצוֹן וְשִׂמְחָה בַּכֹּל."]]],[["וּבְהַאי רָצוֹן, אִסְתַּלָּק מֹשֶׁה, נְבִיאָה מְהֵימָנָא קַדִּישָׁא מֵעָלְמָא. בְּגִין לְמִנְדַּע, דְּלָא בְּדִינָא אִסְתַּלָּק, וְהַהִיא שַׁעֲתָא בְּרָצוֹן דְּעַתִּיקָא קַדִּישָׁא נָפַק נִשְׁמָתֵיהּ, וְאִתְטָמַּר בֵּיהּ. בְּגִין כַּךְ, (דברים לה) וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ כְּתִיב. מַה עַתִּיקָא קַדִּישָׁא, טְמִירָא מִכָּל טְמִירִין, וְלָא יַדְעִין עִלָּאִין וְתַתָּאִין. אוּף הָכָא, הַאי נִשְׁמְתָא דְּאִתְטַמַּר בְּהַאי רָצוֹן, דְּאִתְגַּלְיָא בְּשַׁעֲתָא דִּצְלוֹתָא דְּמִנְחָה דְּשַׁבְּתָא, כְּתִיב וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ וְהוּא טָמִיר מִכָּל טְמִירִין דְּעָלְמָא, וְדִינָא לָא שַׁלְטָא בֵּיהּ. זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה.","תָּאנָא, בְּהַאי יוֹמָא, דְּאוֹרַיְיתָא מִתְעַטְּרָא בֵּיהּ, מִתְעַטְּרָא בְּכֹלָּא, בְּכָל אִינּוּן פִּקּוּדִין בְּכָל אִינּוּן גִּזְרִין וְעוֹנָשִׁין, בְּשִׁבְעִין עֲנָפִין דִּנְהוֹרָא, דְּזָהֲרִין מִכָּל סִטְרָא וְסִטְרָא. מַאן חָמֵי, עֲנָפִין דְּנָפְקִין מִכָּל עֲנָפָא וַעֲנָפָא, חֲמִשָּׁא קַיְימִין בְּגוֹ אִילָנָא, כֻּלְּהוּ אַנְפִּין בְּהוּ אֲחִידָן. מַאן חָמֵי, אִינּוּן תַּרְעִין דְּמִתְפַּתְּחָן בְּכָל סְטָר וּסְטָר, כֻּלְּהוּ מִזְדַּהֲרִין וְנַהֲרִין, בְּהַהוּא נְהוֹרָא דְּנָפִיק וְלָא פָּסִק.","קָל כָּרוֹזָא נָפִיק, אִתְּעֲרוּ קַדִּישֵׁי עֶלְיוֹנִין, אִתְּעֲרוּ עַמָּא קַדִּישָׁא, דְּאִתְבַּחֲר לְעֵילָּא וְתַתָּא. אִתְּעֲרוּ חֶדְוָותָא לְקַדְמוּת מָארֵיכוֹן. אִתְּעֲרוּ בְּחֶדְוָותָא שְׁלֵימָתָא. אִזְדְּמָנוּ בִּתְלַת חֶדְוָון, דִּתְלַת אֲבָהָן. אִזְדְּמָנוּ לְקַדְמוּת מְהֵימָנוּתָא, דְּחֶדְוָוה דְּכָל חֶדְוָותָא. זַכָּאָה חוּלְקֵכוֹן, יִשְׂרָאֵל קַדִּישִׁין, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. דָּא הוּא יָרוּתָא לְכוֹן, מִכָּל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְעַל דָּא כְּתִיב, בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל.","אָמַר ר' יְהוּדָה, הָכִי הוּא וַדַּאי. וְעַל דָּא כְּתִיב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ וּכְתִיב (ויקרא י״ט:ב׳) קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'. וּכְתִיב, (ישעיהו נ״ח:י״ג) וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ יְיָ' מְכוּבָּד.","תָּאנָא, בְּהַאי יוֹמָא, כָּל נִשְׁמָתֵיהוֹן דְּצַדִּיקַיָּיא, מִתְעַדְּנִין בְּתַפְנוּקֵי עַתִּיקָא קַדִּישָׁא, סְתִימָא דְּכָל סְתִימִין. וְרוּחָא חֲדָא מֵעִנּוּגָא דְּהַהוּא עַתִּיקָא קַדִּישָׁא מִתְפַּשְׁטָא (ההוא מתפשט) בְּכֻלְּהוּ עָלְמִין, וְסַלְּקָא וְנַחְתָּא, וּמִתְפַּשְּׁטָא לְכֻלְּהוּ בְּנֵי קַדִּישִׁין, לְכֻלְּהוּ נְטוּרֵי אוֹרַיְיתָא, וְנַיְיחִין בְּנַיְיחָא שְׁלִים, מִתְנְשֵׁי מִכֻּלְּהוּ, כָּל רוּגְזִין, כָּל דִּינִין, וְכָל פּוּלְחָנִין קָשִׁין. הֲדָא הוּא דִכְתִיב, (ישעיהו י״ד:ג׳) בְּיוֹם הִנִּיחַ יְיָ' לָךְ מֵעָצְבְּךָ וּמִרָגְזֶךָ וּמִן הָעֲבוֹדָה הַקָּשָׁה.","בְּגִינֵי כַּךְ, שָׁקִיל שַׁבְּתָא לָקֳבֵל אוֹרַיְיתָא, וְכָל דְּנָטִיר שַׁבְּתָא, כְּאִילּוּ נָטִיר אוֹרַיְיתָא כֻּלָּא. וּכְתִיב (ישעיהו נ״ו:ב׳) אַשְׁרֵי אֱנוֹשׁ יַעֲשֶׂה זֹאת וּבֶן אָדָם יַחֲזִיק בָּהּ שׁוֹמֵר שַׁבָּת מֵחַלְּלוֹ וְשוֹמֵר יָדוֹ מֵעֲשׂוֹת כָּל רָע. אִשְׁתְּמַע, דְּמַאן דְּנָטִיר שַׁבָּת, כְּמַאן דְּנָטִיר אוֹרַיְיתָא כֻּלָּא.","ר' יוּדָאי שָׁאִיל לֵיהּ לְרַ' שִׁמְעוֹן, יוֹמָא חַד דְּאַעְרַע עִמֵּיהּ בְּאָרְחָא, אָמַר לֵיהּ, ר', הָא כְּתִיב (ס\"א בפרשתא דשבת) בְּפַרְשְׁתָּא דָּא שַׁבָּת, דְּאָמַר יְשַׁעְיָה, דִּכְתִּיב, (ישעיהו נ״ו:ד׳) כֹה אָמַר יְיָ' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וְגוֹ', וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמוֹתַי וְגוֹ'. מַה קָא מַיְירֵי.","אֲמַר לֵיהּ, קַפּוּטְקָאָה, חֲמָרָךְ קִטְרֵי בְּטִיפְסָא, וּנְחִית, דְּמִלָּה דְּאוֹרַיְיתָא בָּעֵי צָחוּתָא. אוֹ אַפְכֵי לַאֲחוֹרָךְ, וְזִיל אֲבַתְרָאי, וּתְכַוֵּון לִבָּךְ. אֲמַר לֵיהּ, בְּגִינֵיהּ דְּמֹר עֲבִידְנָא אָרְחָא, וּבַתְרֵיהּ דְּמֹר אֶסְתָּכֵּל בִּשְׁכִינְתָּא.","אֲמַר לֵיהּ, תָּא חֲזֵי, מִלָּה דָּא הָא אוּקְמוּהָ חַבְרַיָּיא, וְלָא פְּרִישׁוּ מִלָּה. כֹה אָמַר יְיָ' לַסָּרִיסִים. מַאן סָרִיסִים. אִלֵּין אִינּוּן חַבְרַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וּמְסָרְסֵי גַּרְמַיְיהוּ כָּל שִׁיתָא יוֹמִין דְּשַׁבְּתָא, וְלָעָאן בְּאוֹרַיְיתָא, וּבְלֵילְיָא דְּשַׁבְּתָא מְזָרְזֵי גַּרְמַיְיהוּ בְּזִוּוּגָא דִּלְהוֹן, מִשּׁוּם דְּיַדְעֵי רָזָא עִלָּאָה, בְּשַׁעֲתָא דְּמַטְרוֹנִיתָא אִזְדַּוְּוגַת בְּמַלְכָּא.","וְאִינּוּן חַבְרַיָּיא דְּיַדְעִין רָזָא דָּא, מְכַוְּונִין לִבַּיְיהוּ לִמְהֵימָנוּתָא דְּמָארֵיהוֹן וּמִתְבָּרְכָאן בְּאִיבָּא דִּמְעֵיהוֹן בְּהַהוּא לֵילְיָא. וְדָא הוּא דִּכְתִּיב, אֲשֶׁר יִשְׁמְרוּ, כְּמָה דְּאַתְּ אָמַר, (בראשית ל״ז:י״א) וְאָבִיו שָׁמַר אֶת הַדָּבָר.","וְאִקְרוּן סָרִיסִים וַדַּאי, בְּגִין לְחַכָּאָה לְשַׁבְּתָא לְאַשְׁכְּחָא רַעֲוָא דְּמָארֵיהוֹן, דִּכְתִּיב ובְחָרוֹ בַּאֲשֶׁר חָפָצְתִּי. מַאי בַּאֲשֶׁר חָפָצְתִּי. דָּא זִוּוּגָא דְּמַטְרוֹנִיתָא. וּמַחֲזִיקִים בִּבְרִיתִי, כֹּלָּא חַד, בִּבְרִיתִי סְתָם. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּאִתְקַדָּשׁ בִּקְדוּשָׁה דָּא, וְיָדַע רָזָא דָּא."],[[0,"ובהאי רצון אסתלק וכו':","וברצון הזה נסתלק משה, הנביא הנאמן הקדוש, מן העולם כדי לדעת שלא נסתלק בדין, ושעה ההיא, יצא נשמתו ברצון של עתיקא קדישא ונגנז בו, משום זה, ולא ידע איש את קבורתו, כתוב, מה עתיקא קדישא נעלם מכל נעלם ולא יודעים אותו עליונים ותחתונים, אף כאן, נשמה זו, שנסתרה ברצון הזה של עתיקא קדישא, שנתגלה בשעת תפלת המנחה של שבת, כתוב בה, ולא ידע איש את קבורתו, והוא נסתר מכל הנסתרות שבעולם, ודין אינו שולט בו, אשרי חלקו של משה."],[1,"תאנא בהאי יומא וכו':","למדנו, ביום הזה, של שבת, התורה מתעטרת בו, מתעטרת בכל, בכל אלו המצות, בכל אלו הגזרות והעונשין, בשבעים ענפים של אור המאיר בכל צד וצד, כי ז' ספירות הם חג\"ת נהי\"מ, וכל אחת כלולה מעשר הם שבעים. מי ראה הענפים היוצאים מכל ענף וענף של שבעים הענפים. חמשה עומדים בתוך האילן, היינו ה' ספירות חג\"ת נ\"ה שבז\"א, הנקרא אילן. המקבל אותם מבינה. כל הפנים נאחזים בהם. מי ראה אלו השערים הנפתחים בכל צד וצד מהם, שכל אחת כלולה מעשר והם חמשים שערים. כולם מזדהרים ומאירים באור ההוא היוצא ואינו נפסק."],[2,"קל כרוזא נפיק וכו':","קול כרוז יוצא, התעוררו קדושים העליונים, התעוררו עם קדוש הנבחר למעלה ולמטה, עוררו שמחה לפני אדוניכם, התעוררו בשמחה שלמה, הזדמנו בשלש שמחות של שלשה אבות, דהיינו שלש סעודות, הזדמנו לקראת האמונה, שהיא שמחת השמחות. אשרי חלקכם ישראל הקדושים בעולם הזה ובעולם הבא. זו היא הירושה שלכם, יותר מכל העמים עכו\"ם, ועל זה כתוב, ביני ובין בני ישראל."],[3,"אמר ר' יהודה וכו':","אר\"י, כן הוא ודאי, וע\"כ כתוב, זכור את יום השבת לקדשו. וכתוב, קדושים תהיו כי קדוש אני ה'. וכתוב, וקראת לשבת ענג לקדוש ה' מכובד."],[4,"תאנא בהאי יומא וכו':","למדנו, ביום ההוא, של שבת, כל נשמות הצדיקים מתעדנים בתענוגי עתיקא קדישא הסתום מכל סתומים, שהוא הכתר. ורוח אחד מעונג עתיקא קדישא ההוא, מתפשט בכל העולמות ועולה ויורד, ומתפשט לכל בנים הקדושים, לכל שומרי התורה, ונחים במנוחה שלמה ונשכחים מכולם, כל רוגז, כל הדינים וכל עבודה קשה. ז\"ש, ביום הניח ה' לך מעצבך ומרגזך ומן העבודה הקשה."],[5,"בגיני כך שקיל וכו':","משום זה שקולה שבת כנגד התורה, וכל השומר שבת כאלו שמר התורה כולה. וכתוב, אשרי אנוש יעשה זאת ובן אדם יחזיק בה שומר שבת מחללו ושומר ידו מעשות כל רע. נשמע, שמי ששומר שבת כמי ששומר התורה כולה."],[6,"ר' יודאי שאיל וכו':","ר\"י שאל את ר' שמעון, יום אחד שנפגש עמו בדרך. אמר לו, רבי, הרי כתוב בפרשה זו של שבת שאמר ישעיהו, שכתוב, כה אמר ה' לסריסים אשר ישמרו את שבתותי וגו' ונתתי להם בביתי ובחומותי וגו'. מה הוא אומר."],[7,"א\"ל קפוטקאה וכו':","אמר לו ר\"ש קפוטקאי, שקראו על שם עירו, קשור חמרך בגדר ורד, כי דברי תורה צריכים צחות השכל, או הפוך לאחוריך ולך אחרי וכוון את לבך. אמר לו, בשביל אדוני עשיתי הדרך, ואחרי אדוני אסתכל בהשכינה."],[8,"א\"ל ת\"ח מלה וכו':","אמר לו, דבר זה בארוהו החברים, ולא פרשו הדבר. כה אמר ה' לסריסים. מי הם סריסים. אלו הם החברים העוסקים בתורה ומסרסים עצמם כל ששת ימי השבת ועוסקים בתורה, ובליל שבת מזרזים עצמם בזווג שלהם, משום שיודעים סוד העליון, בשעה שהמטרוניתא מתחברת בהמלך."],[9,"ואינון חבריא דידעין וכו':","ואלו החברים היודעים סוד הזה, מכוונים את לבם לאמונת אדונם, ומתברכים בפרי בטנם בלילה ההוא. וזהו שכתוב, אשר \u0003ישמרו,\u0004 כמש\"א, ואביו \u0003שמר\u0004 את הדבר."],[10,"ואקרון סריסים וכו':","ונקראים ודאי סריסים, משום שמחכים עד השבת למצוא רצון של אדונם, שכתוב, ובחרו באשר חפצתי. מהו באשר חפצתי. זהו הזווג של מטרוניתא. ומחזיקים בבריתי, הכל אחד, שפירושו ג\"כ זווג, בבריתי סתם, שהוא יסוד העליון המתחבר עם המטרוניתא. אשרי חלקו של מי שמתקדש בקדושה זו, ויודע סוד הזה."]],[[0,"","וּבָרָצוֹן הַזֶּה הִסְתַּלֵּק מֹשֶׁה, הַנָּבִיא הַנֶּאֱמָן הַקָּדוֹשׁ מִן הָעוֹלָם, כְּדֵי לְהוֹדִיעַ שֶׁלֹּא בְדִין הִסְתַּלֵּק, וְאוֹתָהּ שָׁעָה בְּרָצוֹן שֶׁל הָעַתִּיק הַקָּדוֹשׁ יָצְאָה נִשְׁמָתוֹ וְנִטְמְנָה בּוֹ. מִשּׁוּם כָּךְ וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ כָּתוּב. מָה הָעַתִּיק הַקָּדוֹשׁ טָמִיר שֶׁל כָּל הַטְּמִירִים, וְלֹא יוֹדְעִים עֶלְיוֹנִים וְתַחְתּוֹנִים - אַף כָּאן נְשָׁמָה זוֹ שֶׁנִּטְמְנָה בָּרָצוֹן הַזֶּה שֶׁהִתְגַּלָּה בִּשְׁעַת תְּפִלַּת מִנְחַת הַשַּׁבָּת, כָּתוּב וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ, וְהוּא טָמִיר מִכָּל הַטְּמִירִים שֶׁל הָעוֹלָם, וְהַדִּין לֹא שׁוֹלֵט בּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה!"],[1,"","שָׁנִינוּ, בַּיּוֹם הַזֶּה שֶׁהַתּוֹרָה מִתְעַטֶּרֶת בּוֹ, מִתְעַטֶּרֶת בַּכֹּל, בְּכָל אוֹתָן מִצְווֹת, בְּכָל אוֹתָן גְּזֵרוֹת וָעֳנָשִׁים, בְּשִׁבְעִים עֲנָפִים שֶׁל אוֹר שֶׁזּוֹהֲרִים מִכָּל צַד וְצַד. מִי רָאָה הָעֲנָפִים שֶׁיּוֹצְאִים מִכָּל עָנָף וְעָנָף, חֲמִשָּׁה עוֹמְדִים בְּתוֹךְ הָאִילָן, וְכָל הַפָּנִים אֲחוּזִים בָּהֶם? מִי רָאָה אוֹתָם שְׁעָרִים שֶׁנִּפְתָּחִים בְּכָל צַד וְצַד, וְכֻלָּם זוֹהֲרִים וּמְאִירִים בִּאוֹתוֹ הָאוֹר שֶׁיּוֹצֵא וְלֹא פוֹסֵק?"],[2,"","קֹוֹל הַכָּרוֹז יוֹצֵא: הִתְעוֹרְרוּ קְדוֹשִׁים עֶלְיוֹנִים, הִתְעוֹרְרוּ הָעָם הַקָּדוֹשׁ שֶׁנִּבְחָר לְמַעְלָה וּלְמַטָּה, עוֹרְרוּ שִׂמְחָה כְּנֶגֶד רִבּוֹנְכֶם, הִתְעוֹרְרוּ בְשִׂמְחָה שְׁלֵמָה, הִזְדַּמְּנוּ לְשָׁלֹשׁ שְׂמָחוֹת שֶׁל שְׁלֹשֶׁת הָאָבוֹת, הִזְדַּמְּנוּ לִקְרַאת הָאֱמוּנָה שֶׁל שִׂמְחַת כָּל הַשְּׂמָחוֹת. אַשְׁרֵי חֶלְקְכֶם, יִשְׂרָאֵל קְדוֹשִׁים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא! זוֹהִי יְרֻשָּׁה לָכֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב בֵּינֵי וּבֵין בְּנֵי יִשְׂרָאֵל."],[3,"","אָמַר רַבִּי יְהוּדָה, כָּךְ הוּא וַדַּאי. וְעַל זֶה כָּתוּב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְכָתוּב (ויקרא יט) קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. וְכָתוּב (ישעיה נח) וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ ה' מְכֻבָּד."],[4,"","שָׁנִינוּ, בַּיּוֹם הַזֶּה כָּל נִשְׁמוֹת הַצַּדִּיקִים מִתְעַדְּנִים בְּתַפְנוּקֵי הָעַתִּיק הַקָּדוֹשׁ, נִסְתַּר כָּל הַנִּסְתָּרִים, וְרוּחַ אַחַת מֵהָעֹנֶג שֶׁל אוֹתוֹ הָעַתִּיק הַקָּדוֹשׁ מִתְפַּשֶּׁטֶת (ההואמתפשט) בְּכָל הָעוֹלָמוֹת, וְעוֹלָה וְיוֹרֶדֶת, וּמִתְפַּשֶּׁטֶת לְכָל הַבָּנִים הַקְּדוֹשִׁים לְכָל שׁוֹמְרֵי הַתּוֹרָה, וְנָחִים בִּמְנוּחָה שְׁלֵמָה, נִשְׁכָּחִים מִכֻּלָּם כָּל הָרְגָזִים, כָּל הַדִּינִים וְכָל הָעֲבוֹדוֹת הַקָּשׁוֹת. זֶהוּ שֶׁכָּתוּב (שם יד) בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמִרָגְזֶךְ וּמִן הָעֲבֹדָה הַקָּשָׁה."],[5,"","מִשּׁוּם כָּךְ שְׁקוּלָה שַׁבָּת כְּנֶגֶד הַתּוֹרָה, וְכָל מִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שׁוֹמֵר אֶת כָּל הַתּוֹרָה. וְכָתוּב (ישעיה נו) אַשְׁרֵי אֱנוֹשׁ יעֲשֶׂה את וּבֶן אָדָם יַחֲזִיק בָּהּ שמֵר שַׁבָּת מֵחַלְּלוֹ וְשֹׁמֵר יָדוֹ מֵעֲשׂוֹת כָּל רָע. נִשְׁמָע, שֶׁמִּי שֶׁשּׁוֹמֵר אֶת הַשַּׁבָּת כְּמִי שֶׁשּׁוֹמֵר כָּל הַתּוֹרָה."],[6,"","רַבִּי יוּדַאי שָׁאַל אֶת רַבִּי שִׁמְעוֹן יוֹם אֶחָד שֶׁנִּפְגַּשׁ עִמּוֹ בַּדֶּרֶךְ, אָמַר לוֹ, רַבִּי, הֲרֵי כָּתוּב (בפרשת השבת) בְּפָרָשָׁה זוֹ שַׁבָּת שֶׁאָמַר יְשַׁעְיָה, שֶׁכָּתוּב כֹּה אָמַר ה' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וְגוֹ', וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי וְגוֹ'. מַה זֶּה אוֹמֵר?"],[7,"","אָמַר לוֹ, קַפּוּטְקָאִי, קְשֹׁר אֶת חֲמוֹרְךְ בַּגָּדֵר וְרֵד, שֶׁדְּבַר תּוֹרָה צָרִיךְ צַחוּת, אוֹ הֲפֹךְ לַאֲחוֹרֶיךְ וְלֵךְ אַחֲרַי וּתְכַוֵּן לִבְּךְ. אָמַר לוֹ, מִשּׁוּם מוֹרִי עָשִׂיתִי אֶת הַדֶּרֶךְ, וְאַחֲרֵי מוֹרִי אֶסְתַּכֵּל בַּשְּׁכִינָה."],[8,"","אָמַר לוֹ, בֹּא וּרְאֵה, דָּבָר זֶה הֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים וְלֹא פֵרְשׁוּ דָבָר. כֹּה אָמַר ה' לַסָּרִיסִים, מִי הֵם הַסָּרִיסִים? אֵלּוּ הֵם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וּמְסָרְסִים עַצְמָם כָּל שֵׁשֶׁת יְמֵי הַשַּׁבָּת וְעוֹסְקִים בַּתּוֹרָה, וּבְלֵיל הַשַּׁבָּת מְזָרְזִים אֶת עַצְמָם בְּזִוּוּגָם מִשּׁוּם שֶׁיּוֹדְעִים הַסּוֹד הָעֶלְיוֹן בְּשָׁעָה שֶׁהַגְּבִירָה מִזְדַּוֶּגֶת בַּמֶּלֶךְ."],[9,"","וְאוֹתָם חֲבֵרִים שֶׁיּוֹדְעִים סוֹד זֶה, מְכַוְּנִים לִבָּם לֶאֱמוּנַת רִבּוֹנָם, וּמִתְבָּרְכִים בִּפְרִי מְעֵיהֶם בְּאוֹתוֹ הַלַּיְלָה. וְזֶהוּ שֶׁכָּתוּב אֲשֶׁר יִשְׁמְרוּ, כְּמוֹ שֶׁנֶּאֱמַר וְאָבִיו שָׁמַר אֶת הַדָּבָר."],[10,"","וְנִקְרָאִים סָרִיסִים וַדַּאי, בִּשְׁבִיל לְחַכּוֹת לְשַׁבָּת לִמְצֹא אֶת רְצוֹן רִבּוֹנָם, שֶׁכָּתוּב וּבָחֲרוּ בַּאֲשֶׁר חָפָצְתִּי. מַה זֶּה בַּאֲשֶׁר חָפָצְתִּי? זֶה זִוּוּג הַגְּבִירָה. וּמַחֲזִיקִים בִּבְרִיתִי, הַכֹּל אֶחָד. בִּבְרִיתִי סְתָם. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְקַדֵּשׁ בַּקְּדֻשָּׁה הַזּוֹ וְיוֹדֵעַ הַסּוֹד הַזֶּה."]]],[["תָּא חֲזִי, כְּתִיב שֵׁשֶׁת יָמִים תַּעֲבֹד וְעָשִׂיתָ כָּל מְלַאכְתֶּךָ וְיוֹם הַשְּׁבִיעִי שַׁבָּת לַיְיָ' אֱלהֶיךָ וְגוֹ', כָּל מְלַאכְתֶּךָ, בְּאִינּוּן שִׁיתָא יוֹמֵי עֲבִידְתַּיְיהוּ דִּבְנֵי נָשָׁא וּבְגִין הַאי מִלָּה. לָא מִזְדַּוְּוגֵי חַבְרַיָּיא, בַּר בְּזִמְנָא דְּלָא יִשְׁתְּכַּח מֵעֲבִידְתַּיְיהוּ דִּבְנִי נָשָׁא, אֶלָּא עֲבִידְתֵּיה דְּקוּדְשָׁא בְּרִיךְ הוּא. וּמַאי עֲבִידְתֵּיה. זִוּוּגָא דְּמַטְרוֹנִיתָא, לְאַפָּקָא נִשְׁמָתִין קַדִּישִׁין לְעָלְמָא.","וּבְגִין כָּךְ, בְּהַאי לֵילְיָא חַבְרַיָּיא מִתְקַדְּשֵׁי בִּקְדוּשָּׁה דְּמָארֵיהוֹן, וּמְכַוְּונֵי לִבַּיְיהוּ, וְנַפְקֵי בְּנֵי מַעֲלֵי, בְּנִין קַדִּישִׁין, דְּלָא סָטָאן לִימִינָא וְלִשְׂמָאלָא, בְּנִין דְּמַלְכָּא וּמַטְרוֹנִיתָא. וְעַל אִלֵּין כְּתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלהֵיכֶם, לַיְיָ' אֱלֹהֵיכֶם וַדַּאי. בְּגִין דְּאִלֵּין אִקְרוּן בְּנִין דִּילֵיהּ, בְּנִין לְמַלְכָּא וּלְמָטְרוֹנִיתָא.","וְהָא דַּעְתַּיְיהוּ דְּחַבְרַיָּיא דְּיַדְעִין רָזָא דָּא, בְּדָא מִתְדַבְּקָן. וּבְגִין כַּךְ אִקְרוּן בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְהָנִי אִינּוּן דְּעָלְמָא מִתְקַיְּימָא בְּגִינַיְיהוּ. וְכַד סָלִיק עָלְמָא בְּדִינָא, אִסְתָּכַּל קוּדְשָׁא בְּרִיךְ הוּא בְּאִינּוּן בְּנוֹי, וּמְרַחֵם עַל עָלְמָא. וְעַל דָּא כְּתִיב (ירמיהו ב׳:כ״א) כֻּלֹּה זֶרַע אֱמֶת. זֶרַע אֱמֶת וַדַּאי. מַהוּ אֱמֶת. עִזְקָא קַדִּישָׁא שְׁלֵימָתָא. כְּמָה דְאַתְּ אָמֵר (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב. (אמת דא קודשא בריך הוא) וְכֹלָּא חַד. וּבְגִינֵי כַּךְ, זֶרַע אֱמֶת וַדַּאי.","אָמַר לֵיהּ ר' יוּדָאי, בְּרִיךְ רַחֲמָנָא דְּשָׁדַרְנִי הָכָא, בְּרִיךְ רַחֲמָנָא, דְּהָא מִלָּה דָּא שְׁמַעְנָא מִפּוּמָךְ. בָּכָה רַבִּי יוּדָאי. אָמַר לֵיהּ ר' שִׁמְעוֹן, אֲמַאי קָא בָּכִית. אָמַר לֵיהּ, בָּכֵינָא, דַּאֲמֵינָא דְּוַוי לְאִינוּן בְּנֵי עָלְמָא, דְּאָרְחֵיהוֹן כִּבְעִירֵי, וְלָא יַדְעֵי וְלָא מִסְתַּכְּלֵי, דְּטָב לוֹן דְּלָא אִתְבְּרִיאוּ. וַוי לְעָלְמָא כַּד יִפּוּק מֹר מִנֵּיהּ, דְּמַאן יָכִיל לְגַלָּאָה רָזִין, וּמַאן יִנְדַּע לוֹן, וּמַאן יִסְתָּכַּל בְּאָרְחֵי אוֹרַיְיתָא.","אָמַר לֵיהּ, חַיֶּיךָ, לֵית עָלְמָא אֶלָּא לְאִינוּן חַבְרַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא וְיַדְעִין סְתִימֵי אוֹרַיְיתָא. וַדַּאי בִּקְשׁוֹט גָּזְרוּ חַבְרַיָּיא עַל עַמָּא דְּאַרְעָא, דִּמְחַבְּלִין אָרְחַיְיהוּ, וְלָא יַדְעִין בֵּין יְמִינָא לִשְׂמָאלָא, דְּהָא אִינּוּן כִּבְעִירֵי, דְּיֵאוֹת לְמֶעְבַּד בְּהוּ דִּינָא, אֲפִילּוּ בְּיוֹם הַכִּפּוּרִים. וְעַל בְּנַיְיהוּ כְּתִיב, (הושע ב׳:ו׳) כִּי בְנֵי זְנוּנִים הֵמָּה, בְנֵי זְנוּנִים מַמָּשׁ.","אָמַר לֵיהּ, ר', הַאי קְרָא בָּעֵי לְאִתְיַישְּׁבָא בְּאָרְחוֹי. כְּתִיב (ישעיהו נ״ו:ה׳) וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמוֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֶּן לוֹ. אֶתֶּן לָהֶם מִבָּעֵי לֵיהּ, מַהוּ אֶתֵּן לוֹ.","אָמַר לֵיהּ, תָּא חֲזֵי, וְנָתַתִּי לָהֶם בְּבֵיתִי, מַהוּ בֵּיתִי. כְּמָה דְּאַתְּ אָמַר (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נֶאֱמָן הוּא. (שמא דקודשא בריך הוא אקרי בית) וּבְחוֹמוֹתַי, כְּמָה דְאַתְּ אָמֵר (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַיִךְ יְרוּשָׁלַ ם הִפְקַדְתִּי שׁוֹמְרִים יָד וָשֵׁם, כְּלוֹמַר דְּיִשְׁלְפוּן נִשְׁמָתִין קַדִּישִׁין מִדּוּכְתָּא דָּא. וְהַהוּא יַד, חוּלָק בְּאַשְׁלָמוּתָא. טַב, מַלְיָא מִבְּנִין וּמִבְּנָתָן. שֵׁם עוֹלָם אֶתֵּן לוֹ, לְהַהוּא חוּלָק שְׁלִים. אֲשֶׁר לֹא יִכָּרֵת לְדָרֵי דָּרִין. דָּבָר אַחֵר אֶתֵּן לוֹ לְהַהוּא דְּיָדַע רָזָא דְּמִלָּה, וְיִתְכְּוַון בְּמָה דְּבָעֵי לְכַוְּונָא.","תּוּ אָמַר ר' שִׁמְעוֹן, כְּתִיב, (שמות ל״ה:ג׳) לא תְבַעֲרוּ אֵשׁ בְּכָל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. מַאי טַעֲמָא. בְּגִין דְּלָא אִתְחָזֵי דִּינָא בְּהַאי יוֹמָא. וְאִי תֵּימָא הָא לַגָּבוֹהַּ סַלְּקָא. בְּכָל מוֹשְׁבוֹתֵיכֶם קָאָמַר, וְלָא לַגָּבוֹהַּ. וְהַהוּא דְּסַלְּקָא לַגָּבוֹהַּ, לְאַכְפְיָא לְדִינָא אַחֲרָא סַלְּקָא. דְּתָנֵינָן, אִית אֶשָּׁא אָכְלָא אֶשָּׁא. וְאֶשָׁא דְּמַדְבְּחָא, אָכְלָא אֶשָּׁא אַחֲרָא.","וּבְגִינֵי כַּךְ, אִתְגַּלְיָא עַתִּיקָא קַדִּישָׁא בְּהַאי יוֹמָא, מִכָּל שְׁאַר יוֹמִין. וּבְזִמְנָא דְּאִתְגַּלְיָא עַתִּיקָא, לָא אִתְחָזֵי דִּינָא כְּלָל. וְכָל עִלָּאִין וְתַתָּאִין מִשְׁתַּכְּחִין בְּחֶדְוָותָא שְׁלֵימָתָא, וְדִינָא לָא שַׁלְטָא.","תָּאנָא, כְּתִיב (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. שֵׁשֶׁת יָמִים וַדַּאי, וְלָא בְּשֵׁשֶׁת. וְהָנֵי יוֹמִין קַדִּישִׁין עִלָּאִין, אִקְרוּן יוֹמֵי דִּשְׁמָא קַדִּישָׁא אִתְכְּלִיל בְּהוּ, וְאִינּוּן אִתְּכְּלִילָן בֵּיהּ. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, עָלַיְיהוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם חַיִּים כּוּלְּכֶם הַיּוֹם."],[[0,"תא חזי כתיב וכו':","בוא וראה, כתוב, ששת ימים תעבוד ועשית כל מלאכתך ויום השביעי שבת לה' אלקיך וגו'. כל מלאכתך, יורה, שבאלו ששה ימים נמצא מעשיהם של בני אדם, ובשביל דבר זה אינם מזדווגים החברים רק בזמן שלא נמצא מעשיהם של בני אדם אלא מעשיו של הקב\"ה. דהיינו בשבת שאסור לאדם עשית מלאכה. ומהו מעשיו, הוא הזווג עם מטרוניתא, שהיא המלכות, להוציא נשמות קדושות לעולם."],[1,"ובג\"כ בהאי ליליא וכו':","ומשום זה בלילה הזה, החברים מתקדשים בקדושת אדונם, ומכוונים לבם, ויוצאים בנים טובים בנים קדושים שאינם סרים ימין ושמאל, בנים של המלך והמטרוניתא. ועל אלו כתוב, בנים אתם לה' אלקיכם. לה' אלקיכם ודאי, משום שאלו נקראים בנים שלו, בנים של המלך ומטרוניתא."],[2,"והא דעתייהו דחבריא וכו':","והרי דעת החברים היודעים סוד הזה, מתדבקים בזה, ומשום זה נקראים בנים להקב\"ה. ואלו הם שהעולם מתקיים בשבילם. וכשהעולם עולה בדין, מסתכל הקב\"ה בבניו אלו, ומרחם על העולם. ועל זה כתוב, כולו זרע אמת, זרע אמת ודאי, מהו אמת. הוא טבעת הקדושה השלמה, פירוש, שהם בקו האמצעי, ואינם יוצאים מגבולם האמצעי, לא לימין ולא לשמאל, כמו מוקפים בטבעת. כמש\"א תתן אמת ליעקב. ויעקב ה\"ס קו האמצעי, והכל אחד. ומשום זה זרע אמת ודאי."],[3,"אמר ליה ר' יודאי וכו':","א\"ל ר\"י, ברוך הרחמן ששלחני כאן. ברוך הרחמן, שדבר זה שמעתי מפיך. בכה ר' יודאי. אמר לו ר' שמעון למה אתה בוכה. אמר לו אני בוכה, שאני אומר, אוי לבני העולם שדרכם כבהמות, ואינם יודעים ואינם מסתכלים, שטוב להם שלא נבראו. אוי לעולם כשאדוני יצא ממנו, שמי יוכל לגלות סודות, ומי ידע אותם, ומי יסתכל בדרכי התורה."],[4,"אמר ליה חייך וכו':","א\"ל חייך, אין העולם אלא בשביל החברים העוסקים בתורה, ויודעים נסתרות התורה. ודאי באמת גזרו החברים על עמי הארץ שמחבלים דרכם ואינם יודעים בין ימין לשמאל, כי הם כבהמות, שראוי לעשות בהם דין אפילו ביום הכפורים. ועל בניהם כתוב, כי בני זנונים המה. בני זנונים ממש."],[5,"אמר ליה רבי וכו':","א\"ל רבי, מקרא זה צריכים לישבו בדרכיו. כתוב, ונתתי להם בביתי ובחומותי יד ושם טוב מבנים ומבנות שם עולם אתן לו. שואל, אתן להם היה צריך לומר, דהיינו לסריסים, מהו אתן לו."],[6,"אמר ליה תא חזי וכו':","א\"ל בוא וראה, \u0003ונתתי להם בביתי.\u0004 מהו ביתי. הוא כש\"א, בכל ביתי נאמן הוא. שהוא השכינה הנקראת בית. \u0003ובחומותי,\u0004 הוא כמש\"א, על חומותיך ירושלם הפקדתי שומרים. שהוא חיצוניות השכינה. \u0003יד ושם,\u0004 כלומר שיוציאו נשמות קדושות ממקום הזה, מן השכינה, ויד ההיא, פירושו, חלק השלמות. \u0003טוב\u0004 פירושו, מלא \u0003מבנים ובנות. שם עולם אתן לו\u0004 היינו לחלק השלמות, הנקרא יד, \u0003אשר לו כרת\u0004 לדורי דורות. פירוש אחר, \u0003אתן לו,\u0004 היינו לאותו שיודע סוד הדבר, של הסריסים אשר ישמרו את שבתותי, ויכוון מה שצריך לכוון."],[7,"תו אמר ר' שמעון וכו':","עוד אמר ר\"ש, כתוב, לא תבערו אש בכל מושבותיכם ביום השבת. מהו הטעם. הוא משום שאין דין נראה ביום ההוא. והמבעיר אש גורם שיתעורר הדין. ואם תאמר, הרי עולה לגבוה, דהיינו אש המזבח שנוהג גם בשבת. ומשיב, במושבותיכם כתוב, ולא לגבוה. ואש ההוא העולה לגבוה, עולה להכניע דין אחר, שלמדנו, יש אש אוכלה אש. ואש המזבח אוכלת אש אחרת. דהיינו שמכניע דין אחר, שלא יהיה לו שליטה בימות החול."],[8,"ובגיני כך אתגליא וכו':","ובשביל זה, נתגלה עתיקא קדישא ביום ההוא יותר מכל שאר הימים. ובזמן שמתגלה עתיקא אינו נראה דין כלל, וכל העליונים והתחתונים נמצאים בשמחה שלמה והדין אינו שולט."],[9,"תאנא כתיב וכו':","למדנו, כתוב, כי ששת ימים עשה ה' את השמים ואת הארץ. ששת ימים ודאי, שהם חג\"ת נה\"י, שמהם נעשו שמים וארץ שהם זו\"ן. ולא כתוב ע\"כ, בששת. ואלו ימים הקדושים העליונים נקראים ימים, שהשם הקדוש, שהוא המלכות הנקראת ארץ, נכלל בהם, והם נכללו בו. אשרי חלקם של ישראל מכל העמים עכו\"ם, עליהם כתוב, ואתם הדבקים בה' אלקיכם חיים כולכם היום."]],[[0,"","בֹּא וּרְאֵה, כָּתוּב שֵׁשֶׁת יָמִים תַּעֲבֹד וְעָשִׂיתָ כָּל מְלַאכְתֶּךְ וְיוֹם הַשְּׁבִיעִי שַׁבָּת לַה' אֱלֹהֶיךְ וְגוֹ'. כָּל מְלַאכְתֶּךְ - בְּאוֹתָם שֵׁשֶׁת הַיָּמִים מְלֶאכֶת בְּנֵי הָאָדָם, וּמִשּׁוּם הַדָּבָר הַזֶּה לֹא מִזְדַּוְּגִים הַחֲבֵרִים, רַק בִּזְמַן שֶׁלֹּא נִמְצָא מִמַּעֲשֵׂי בְּנֵי אָדָם, אֶלָּא מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַה מַּעֲשֵׂהוּ? זִוּוּג הַגְּבִירָה לְהוֹצִיא נְשָׁמוֹת קְדוֹשׁוֹת לָעוֹלָם."],[1,"","וּמִשּׁוּם כָּךְ בַּלַּיְלָה הַזֶּה הַחֲבֵרִים מִתְקַדְּשִׁים בִּקְדֻשַּׁת רִבּוֹנָם וּמְכַוְּנִים לִבָּם, וְיוֹצְאִים בָּנִים מְעֻלִּים, בָּנִים קְדוֹשִׁים, שֶׁלֹּא סוֹטִים יָמִינָה וּשְׂמֹאלָה, בְּנֵי הַמֶּלֶךְ וְהַגְּבִירָה, וְעַל אֵלֶּה כָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. לַה' אֱלֹהֵיכֶם וַדַּאי. מִשּׁוּם שֶׁאֵלֶּה נִקְרָאִים בָּנִים שֶׁלּוֹ, בָּנִים לַמֶּלֶךְ וְלַגְּבִירָה."],[2,"","וְזוֹ דַעַת הַחֲבֵרִים שֶׁיּוֹדְעִים סוֹד זֶה, בָּזֶה נִדְבָּקִים, וּמִשּׁוּם כָּךְ נִקְרָאִים בָּנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וְאֵלֶּה הֵם שֶׁהָעוֹלָם מִתְקַיֵּם בִּשְׁבִילָם. וּכְשֶׁעוֹלֶה הָעוֹלָם בְּדִין, מִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּבָּנִים הַלָּלוּ וּמְרַחֵם עַל הָעוֹלָם, וְעַל זֶה כָּתוּב כֻּלֹּה זֶרַע אֱמֶת. זֶרַע אֱמֶת וַדַּאי. מַה זֶּה אֱמֶת? טַבַּעַת קְדוֹשָׁה שְׁלֵמָה, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב. (אמת זה הקדוש ברוך הוא) וְהַכֹּל אֶחָד. וּמִשּׁוּם כָּךְ זֶרַע אֱמֶת וַדַּאי."],[3,"","אָמַר לוֹ רַבִּי יוּדַאי, בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן. בָּרוּךְ הָרַחֲמָן, שֶׁהֲרֵי דָּבָר זֶה שָׁמַעְתִּי מִפִּיךְ. בָּכָה רַבִּי יוּדַאי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, לָמָּה בָּכִיתָ? אָמַר לוֹ, בָּכִיתִי, שֶׁאָמַרְתִּי אוֹי לְאוֹתָם בְּנֵי הָעוֹלָם שֶׁדַּרְכֵיהֶם כַּבְּהֵמוֹת וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים, שֶׁטּוֹב לָהֶם שֶׁלֹּא נִבְרְאוּ. אוֹי לָעוֹלָם כְּשֶׁיָּצָא מוֹרֵנוּ מִמֶּנּוּ, שֶׁמִּי יָכוֹל לְגַלּוֹת סוֹדוֹת, וּמִי יוֹדֵעַ אוֹתָם, וּמִי יִסְתַּכֵּל בְּדַרְכֵי הַתּוֹרָה?"],[4,"","אָמַר לוֹ, חַיֶּיךְ, אֵין עוֹלָם אֶלָּא לְאוֹתָם חֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים נִסְתְּרוֹת הַתּוֹרָה. וַדַּאי בֶּאֱמֶת גָּזְרוּ הַחֲבֵרִים עַל עַמֵּי הָאֲרָצוֹת שֶׁמַּשְׁחִיתִים דַּרְכָּם וְלֹא יוֹדְעִים בֵּין יָמִין לִשְׂמֹאל, שֶׁהֲרֵי הֵם כִּבְהֵמוֹת שֶׁנָּאֶה לַעֲשׂוֹת בָּהֶם דִּין אֲפִלּוּ בְּיוֹם הַכִּפּוּרִים. וְעַל בְּנֵיהֶם כָּתוּב (הושעב) כִּי בְנֵי זְנוּנִים הֵמָּה. בְּנֵי זְנוּנִים מַמָּשׁ."],[5,"","אָמַר לוֹ, רַבִּי, פָּסוּק זֶה צָרִיךְ לְהִתְיַשֵּׁב בְּדַרְכּוֹ. כָּתוּב וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֶּן לוֹ. אֶתֶּן לָהֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶתֶּן לוֹ?"],[6,"","אָמַר לוֹ, בֹּא וּרְאֵה, וְנָתַתִּי לָהֶם בְּבֵיתִי, מַה זֶּה בְּבֵיתִי? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא. (שמו של הקדוש ברוך הוא נקרא בית) וּבְחוֹמֹתַי, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סב) עַל חוֹמֹתַיִךְ יְרוּשָׁ לם הִפְקַדְתִּי שֹׁמְרִים. יָד וָשֵׁם, כְּלוֹמַר, שֶׁיֵּצְאוּ נְשָׁמוֹת קְדוֹשׁוֹת מִמָּקוֹם זֶה. וְאוֹתָהּ יָד, חֵלֶק הַשְּׁלֵמוּת, טוֹב מָלֵא מִבָּנִים וּמִבָּנוֹת. שֵׁם עוֹלָם אֶתֶּן לוֹ, לְאוֹתוֹ חֵלֶק שָׁלֵם, אֲשֶׁר לֹא יִכָּרֵת לְדוֹרֵי דוֹרוֹת. דָּבָר אַחֵר אֶתֶּן לוֹ - לְאוֹתוֹ שֶׁיּוֹדֵעַ סוֹד הַדָּבָר וְיִתְכַּוֵּן בְּמַה שֶּׁצָּרִיךְ לְכַוֵּן."],[7,"","עוֹד אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבתֵיכֶם בְּיוֹם הַשַּׁבָּת. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא יֵרָאֶה דִין בַּיּוֹם הַזֶּה. וְאִם תֹּאמַר, הֲרֵי לְגָבוֹהַּ עוֹלֶה? בְּכֹל מֹשְׁבתֵיכֶם אָמַר, וְלֹא לְגָבוֹהַּ. וְאוֹתוֹ שֶׁעוֹלֶה לְגָבוֹהַּ, עוֹלֶה לִכְפּוֹת דִּין אַחֵר. שֶׁשָּׁנִינוּ, יֵשׁ אֵשׁ אוֹכֵל אֵשׁ, וְאֵשׁ הַמִּזְבֵּחַ אוֹכֵל אֵשׁ אַחֵר."],[8,"","וּמִשּׁוּם כָּךְ מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ בַּיּוֹם הַזֶּה מִכָּל שְׁאָר הַיָּמִים. וּבִזְמַן שֶׁמִּתְגַּלֶּה הָעַתִּיק, לֹא נִרְאֶה דִין כְּלָל, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים נִמְצָאִים בְּשִׂמְחָה שְׁלֵמָה, וְהַדִּין לֹא שׁוֹלֵט."],[9,"","שָׁנִינוּ, כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. שֵׁשֶׁת יָמִים וַדַּאי, וְלֹא בְּשֵׁשֶׁת. וְהַיָּמִים הַקְּדוֹשִׁים הָעֶלְיוֹנִים הַלָּלוּ נִקְרָאִים יָמִים שֶׁהַשֵּׁם הַקָּדוֹשׁ נִכְלָל בָּהֶם, וְהֵם נִכְלָלִים בּוֹ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, עֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם."]]],[["(שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ. רַבִּי חִיָּיא פָּתַח, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן וְגוֹ'. וְנָהָר, דָּא נְבִיעוּ דְּמַבּוּעָא, דְּנָפִיק תָּדִיר וְלָא פָּסַק. וּמִנַּהֲרָא דְּמַבּוּעָא דָּא, אִתְשָׁקְיָא כָּל גִּנְתָּא דְּעֵדֶן. וְהַהוּא נַהֲרָא דְּמַבּוּעָא קַדִּישָׁא, אִקְרֵי אָ\"ב. מַאי טַעֲמָא. מִשּׁוּם דְּאִיהוּ נְבִיעָא לְאִתְּזָנָא לְגִנְתָּא.","רַבִּי אַבָּא אָמַר, עֵדֶן מַמָּשׁ אִקְרֵי אָב. מִשּׁוּם דְּהַאי עֵדֶן, מִשְׁתְּכַח מֵהַהוּא אֲתָר, דְּאִקְרֵי אַיִן. וּבְגִינִי כַּךְ, אִקְרֵי אָב. וְהָא אוּקִימְנָא, מֵאֲתָר דְּשָׁארֵי לְאִתְמַשְּׁכָא כֹּלָּא, אִקְרֵי אַתָּה, וְאִקְרֵי אָב. כְּמָה (עיין סוף הספר גי' מספר לבנת הספיר) דְּאַתְּ אָמַר, (ישעיהו ס״ג:ט״ז) כִּי אַתָּה אָבִינוּ.","ר' אֶלְעָזָר אָמַר, כַּבֵּד אֶת אָבִיךָ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאֶת אִמֶּךָ, דָּא כְּנֶסֶת יִשְׂרָאֵל. אֶת אָבִיךָ, אֶת דַּיְיקָא, לְאַכְלְלָא שְׁכִינְתָּא (דבר אחר עילאה). רַבִּי יְהוּדָה אָמַר, כַּבֵּד אֶת אָבִיךָ, סְתָם. וְאֶת אִמֶּךָ, סְתָם. דְּהָא כֹּלָּא הֲוָה בְּמִנְיָינָא. אֶת, לְרַבּוֹת כָּל מַה דִּלְעֵילָּא וְתַתָּא.","רַבִּי יוֹסִי אָמַר, הַאי דְּאָמַר רַבִּי אַבָּא, מֵאֲתָר דְּשָׁארֵי לְאִתְמַשְּׁכָא כֹּלָּא, אִקְרֵי אַתָּה, שַׁפִּיר. דְּהָא אוֹלִיפְנָא, הַהוּא דְּטָמִיר וְלָא אִית בֵּיהּ שֵׁירוּתָא, קָרֵינָן הוּא. מֵאֲתָר (ויקרא ב', ע\"א וע\"ב, ר\"ץ ע\"א) דְּשֵׁירוּתָא אִשְׁתְּכַח, קָרֵינָן אַתָּה. וְאִקְרֵי אָב. וְכֹלָּא חַד. בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא אָמֵן.","רַבִּי חִזְקִיָּה אָמַר, וַדַּאי כֹּלָּא חַד. כַּבֵּד אֶת אָבִיךָ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאֶת אִמֶּךָ, דָּא כְּנֶסֶת יִשְׂרָאֵל. דְּהָא תְּנָן, אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלהֵיכֶם, הַהוּא אֲתָר דְּאִקְרֵי בָּנִים. וּבְגִינֵי כַּךְ סְתִימָא דְּמִלָּה, כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ, לְאַכְלְלָא כֹּלָּא, דִּלְעֵילָּא וְתַתָּא. ר' יִצְחָק אָמַר, לְאַכְלְלָא בֵּיהּ רַבֵּיהּ, דְּהוּא אָעִיל לֵיהּ לְעָלְמָא דְּאָתֵי. אָמַר רַבִּי יְהוּדָה, בִּכְלָלָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוֵי.","תָּאנָא, בְּהָנֵי חָמֵשׁ אֲמִירָן, כָּלִיל כֹּלָּא. בְּהָנֵי חָמֵשׁ אֲמִירָן, אִתְגְּלִיפוּ חָמֵשׁ אַחֲרָנִין, וַדַּאי חָמֵשׁ גּוֹ חָמֵשׁ. הָא כֵּיצַד. אָנֹכִי יְיָ' אֱלהֶיךָ, (פ\"ד ע\"ב) לָקֳבֵל לא תִּרְצַח. דְּתָנֵינָן, (אמר רבי יצחק אמר רבי יהודה) תְּרֵין אִלֵּין, בִּכְלָלָא חֲדָא אִתְּכְּלִילָן, דְּמַאן דְּקָטִיל, אַזְעִיר דְּמוּתָא וְצַלְמָא דְּמָארֵיהּ. דִּכְתִּיב, (בראשית ט׳:ו׳) כִּי בְּצֶלֶם אֱלהִים עָשָׂה אֶת הָאָדָם. וּכְתִיב (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם.","אָמַר ר' חִיָּיא, כְּתִיב (בראשיתט) שֹׂפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ וְגו', (שפך דם האדם) מַאן דְּשָׁפִיךְ דָּמָא, כְּאִלּוּ אַזְעִיר דְּמוּתָא וְצַלְמָא דִּלְעֵילָּא, כְּלוֹמַר, לָא אַזְעַר דְּמוּתָא דָּא, אֶלָּא דְּמוּתָא אַחֲרָא, מַשְׁמַע דִּכְתִּיב שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ. בָּאָדָם עִלָּאָה, מָטֵי הַאי פְּגִימוּתָא, מֵהַהוּא דָּמָא דְּאוֹשִׁיד. מַאי טַעֲמָא. מִשּׁוּם כִּי בְּצֶלֶם אֱלהִים עָשָׂה אֶת הָאָדָם. וּבְגִין כָּךְ, הָא בְּהָא תַּלְיָא.","לֹא יִהְיֶה לְךָ, לָקֳבֵל לֹא תִּנְאָף דָּא מְשַׁקֵּר בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְרְשִׁים בֵּיהּ בְּבַר נָשׁ. וּבְדָא, כַּמָּה וְכַמָּה חוֹבִין וְגַזְרִין וְעוֹנָשִׁין, תַּלְיָין. וּמַאן דִּמְשַׁקֵּר בְּהַאי, מְשַׁקֵּר בֵּיהּ בְּמַלְכָּא, דִּכְתִּיב, (הושע ה׳:ז׳) בַּיְיָ' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ. וּכְתִיב לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם, וְהָא בְּהָא תַּלְיָא.","לֹא תִשָּׂא לָקֳבֵל לא תִגְנוֹב. וּכְתִיב (משלי כ״ט:כ״ד) חוֹלָק עִם גַּנָּב שׂוֹנֵא נַפְשׁוֹ אָלָּה יִשְׁמַע וְלֹא יַגִּיד. וַדַּאי הָא בְּהָא תַּלְיָא, דְּהָא גַּנָּבָא לְדָא אִזְדָּמַן, לְאוּמָאָה בְּשִׁקְרָא. מַאן דְּעָבִיד דָּא, עָבִיד דָּא.","זָכוֹר אֶת יוֹם הַשַּׁבָּת, לָקֳבֵל לא תַעֲנְה בְרֵעֲךָ עֵד שָׁקֶר. דְּאָמַר ר' יוֹסִי, שַׁבָּת סַהֲדוּתָא אִקְרֵי. וּבָעֵי בַּר נָשׁ לְסַהֲדָא עַל הָא דִּכְתִּיב כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ' וְגוֹ'. וְשַׁבָּת כְּלָלָא (נ\"א סהדותא) דְּכֹלָּא. וְאָמַר ר' יוֹסִי, מַאי דִּכְתִּיב, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, כְּמָה דְּאַתְּ אָמַר (שמות ל״א:ט״ז) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וּמַאן דְּאַסְהִיד שִׁקְרָא, מְשַׁקֵּר בְּשַׁבָּת, דְּהִיא סַהֲדוּתָא דִּקְשׁוֹט, וּמַאן דִּמְשַׁקֵּר בְּשַׁבָּת, מְשַׁקֵּר בְּאוֹרַיְיתָא כֻּלָּא. וּבְּגִין כָּךְ, הָא בְּהָא תַּלְיָא.","כַּבֵּד אֶת אָבִיךָ, לָקֳבֵל לא תַחְמֹד אֵשֶׁת רֵעֶךָ. וְאָמַר ר' יִצְחָק, כַּבֵּד אֶת אָבִיךָ, אָבִיךָ מַמָּשׁ. דְּהָא מַאן דְּחָמִיד אִתְּתָא, וְאוֹלִיד בַּר, הַהוּא בַּר אוֹקִיר לְאַחֲרָא, דְּלָא אֲבוּי. וּכְתִיב כַּבֵּד אֶת אָבִיךָ וְגוֹ', לא תַחְמֹד בֵּית רֵעֶךָ, שָׂדֵהוּ. וּכְתִיב הָכָא, עַל הָאֲדָמָה אֲשֶׁר יְיָ' אֱלהֶיךָ נוֹתֵן לָךְ. הַהוּא דְּיָהַב לָךְ, יְהֵא דִּילָךְ, וְלֹא תַחְמֹד אַחֲרָא. וַדַּאי הָא בְּהָא תַּלְיָא."],[[0,"כבד את אביך ואת אמך:","ר' חייא פתח, ונהר יוצא מעדן וגו'. ונהר, זהו הנביעה של המבוע שיוצא תמיד ואינו נפסק, ומן הנהר של המביע הזה נשקה כל גן העדן, ונהר ההוא של המבוע הקדוש נקרא אב. מהו הטעם. הוא משום שהוא נובע להזין את הגן."],[0,"","ביאור הדברים. נודע שזו\"ן מצד אצילותם אינם ראוים לקבל אור העליון, משום ששולט בהם מלכות דצמצום א', וכדי שיהיו ראוים לקבלת האור העלה הבינה אליה את המלכות הזו, שע\"י עליה זו נעשתה ראויה לקבלת האור. כמ\"ש כל זה לעיל (ב\"א דף ז' ד\"ה כבר ע\"ש). ומטעם תקון הזה נשתנה שמם של חכמה ובינה שבבינה, לאו\"א, וזו\"ן נקראים בנים שלהם, להיותם מתקנים ודואגים לתקון זו\"ן כאו\"א על בנים."],[0,"","והנה עליה הראשונה של המלכות במקום בינה היתה בראש א\"א, שמחמת עליה זו יצאה הבינה מראש א\"א, שמטעם זה נקרא א\"א, ראשית. (כנ\"ל בראשית א' דף ו' ד\"ה אחר ע\"ש) וזסו\"ה, \u0003ונהר יוצא מעדן,\u0004 כי עדן, הוא חכמה דא\"א, ונהר, היינו הבינה שיצאה מבחינת ראש ונעשתה לבחינת גוף דא\"א בלי ראש. והיתה זה, כדי \u0003להשקות את הגן,\u0004 לתת אור אל המלכות, כי לולא העלאה הזו לא יכלה המלכות לקבל אור לעולם."],[0,"","וז\"ש, \u0003ונהר, דא נביעו דמבועא דנפיק\u0004 וכו', כי חכמה דא\"א נקראת עדן, והוא \u0003המבוע,\u0004 ובינה היוצאת ממנו, נקראת \u0003נביעו.\u0004 ונקראת נהר. \u0003וההוא נהרא דמבועא קדישא אקרי אב.\u0004 דהיינו הבינה הזו נקראת אב, משום שהיא קבלה המלכות לתוכה ונתמעטה על ידה לבחינת גוף כדי לתקנה. שמטעם זה נקרא החו\"ב שבה בשם אבא ואמא. כנ\"ל. וז\"ש, \u0003מאי טעמא, משום דאיהו נביעא לאתזנא לגנתא,\u0004 שמטעם שהיא דואגת לתקון הגן, שהוא המלכות, ע\"כ נקראת אב, כנ\"ל."],[1,"ר' אבא אמר וכו':","רא\"א, עדן ממש נקרא אב, משום שעדן הזה נמשך ממקום ההוא שנק' אין, שהוא כתר דא\"א, שבו אין שום השגה, ותחילת הגילוי לתקון המלכות בבינה נעשה בראש א\"א שנקרא עדן, שמטעם זה נק' א\"א \u0003ראשית,\u0004 כנ\"ל בדיבור הסמוך, ומשום זה נקרא אב. והרי העמדנו, ממקום שמתחיל להמשך הכל, נקרא \u0003אתה\u0004 ונקרא אב. כמש\"א, כי אתה אבינו."],[2,"ר' אלעזר אמר וכו':","רא\"א, כבד את אביך זה הקב\"ה, דהיינו ז\"א. ואת אמך, זו כנסת ישראל, דהיינו המלכות. את אביך, \u0003את\u0004 הוא בדיוק, שבא לכלול השכינה העליונה, שהיא הנוקבא העומדת מחזה ולמעלה דז\"א. ר' יהודה אמר, כבד את אביך, סתם. ואת אמך, סתם. כי הכל הוא בחשבון. כלומר שרומזים הן לחכמה ובינה והן לז\"א ונוקבא, מפני שכתוב סתם. כי \u0003את,\u0004 בא לרבות כל מה שלמעלה ומטה. הן או\"א והן זו\"ן."],[3,"ר' יוסי אמר וכו':","רי\"א, זה שאמר ר' אבא, שהמקום שממנו מתחיל להמשך הכל נקרא אתה יפה הוא, כי למדנו, ההוא שנסתר ואין בו התחלה להשפעת המוחין אנו קוראים, \u0003הוא.\u0004 שהוא לשון נסתר. המקום שממנו נמצא התחלה להשפעת המוחין, אנו קוראים, \u0003אתה.\u0004 ונקרא אב. והכל אחד. ברוך שמו לעולם ולעולמי עולמים אמן."],[4,"ר' חזקיה אמר וכו':","רח\"א, ודאי הכל אחד. כבד את אביך, זה הקב\"ה, דהיינו ז\"א, ואת אמך, זו כנסת ישראל דהיינו המלכות, כי למדנו, אמר ר' שמעון כתוב, בנים אתם לה' אלקיכם, היינו מקום ההוא שנקרא בנים, שהם זו\"ן. ומשום זה סתם הדבר, כבד את אביך ואת אמך לכלול הכל, דהיינו או\"א שלמעלה ולמטה. ר' יצחק אמר, לכלול בו רבו, שהוא מביאו לעולם הבא. אמר ר' יהודה, רבו, בכלל הקב\"ה הוא."],[5,"תאנא בהני חמש וכו':","למדנו, באלו חמשה הדברות שבימין כלול הכל. באלו חמשת הדברות נחקקו חמשה אחרות שבשמאל. ודאי הם חמשה תוך חמשה. כיצד. אנכי ה' אלקיך, הוא כנגד לא תרצח. שלמדנו, שנים אלו בכלל אחד נכללו, כי מי שרצח ממעט דמות וצלם של אדונו, שכתוב, כי בצלם אלקים עשה את האדם. ועל דמות הכסא דמות כמראה אדם."],[6,"אמר ר' חייא וכו':","אר\"ח, כתוב, שפך דם האדם באדם דמו ישפך. מי ששופך דם כאלו ממעיט דמות וצלם שלמעלה. כלומר, לא מיעט דמות זה של התחתון, אלא דמות אחר, זה משמע שכתוב, שפך דם האדם \u0003באדם\u0004 דמו ישפך, באדם העליון מגיע פגם ההוא מדם ששפך. מהו הטעם. משום כי בצלם אלקים עשה את האדם. ומשום זה תלוים זה בזה, שאנכי וגו' תלוי בלא תרצח."],[7,"לא יהיה לך וכו':","לא יהיה לך, הוא כנגד לא תנאף. זה, הנואף, משקר בשמו של הקב\"ה שנרשם באדם, ובזה, כמה וכמה חטאים וגזרות ועונשים, תלוים. ומי שמשקר בזה משקר במלך, שכתוב, בה' בגדו כי בנים זרים ילדו. וכתוב, לא תשתחוה להם ולא תעבדם. וזה בזה תלוים. לא יהיה לך תלוי בלא תנאף."],[8,"לא תשא וכו':","לא תשא הוא כנגד לא תגנב. וכתוב, חולק עם גנב שונא נפשו אלה ישמע ולא יגיד. ודאי זה בזה תלוי, כי גנב, לזה מזדמן לשבע לשקר, מי שעושה זה עושה זה."],[9,"זכור את יום השבת וכו':","זכור וגו' הוא כנגד לא תענה ברעך עד שקר. דאמר ר' יוסי, שבת נקרא עדות, וצריך האדם להעיד על זה שכתוב, כי ששת ימים עשה ה' וגו'. ושבת הוא כלל הכל. ואמר ר' יוסי, מה שכתוב, תתן אמת ליעקב, הוא כש\"א, ושמרו בני ישראל את השבת, שמי שמעיד שקר משקר בשבת, שהוא עדות אמת, ומי שמשקר בשבת משקר בכל התורה. ומשום זה תלוים זה בזה. זכור תלוי בלא תענה."],[10,"כבד את אביך וכו':","כבד את אביך, הוא כנגד לא תחמוד אשת רעך. ואמר ר' יצחק, כבד את אביך, אביך ממש. כי מי שחומד אשה ומוליד בן, בן ההוא מכבד לאחר שאינו אביו. וכתוב, כבד את אביך וגו'. לא תחמוד בית רעך שדהו. וכתוב כאן, בכבד, על האדמה אשר ה' אלקיך נותן לך, שפירושו, זה שנותן יהיה שלך, ולא תחמוד אחר. ודאי זה בזה תלוים. שכבד תלוי בלא תחמוד."]],[[0,"","כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. רַבִּי חִיָּיא פָּתַח, (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן וְגוֹ'. וְנָהָר - זוֹ נְבִיעַת הַמַּעְיָן שֶׁיּוֹצֵא תָמִיד וְלֹא פוֹסֵק, וּמִנְּהַר הַמַּעְיָן הַזֶּה נִשְׁקָה כָּל גַּן הָעֵדֶן. וְאוֹתוֹ נָהָר שֶׁל הַמַּעְיָן הַקָּדוֹשׁ נִקְרָא אָ\"ב. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נוֹבֵעַ לָזוּן אֶת הַגָּן."],[1,"","רַבִּי אַבָּא אָמַר, עֵדֶן מַמָּשׁ נִקְרָא אָב, מִשּׁוּם שֶׁעֵדֶן זֶה נִמְצָא מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אַיִן, וּמִשּׁוּם כָּךְ נִקְרָא אָב. וַהֲרֵי בֵּאַרְנוּ, מִמָּקוֹם שֶׁמַּתְחִיל לְהִמָּשֵׁךְ הַכֹּל נִקְרָא אַתָּה, וְנִקְרָא אָב, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) כִּי אַתָּה אָבִינוּ."],[2,"","רַבִּי אֶלְעָזָר אָמַר, כַּבֵּד אֶת אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אֶת אָבִיךְ, אֶת דַּוְקָא, לְהַכְלִיל שְׁכִינָה (עליונה). רַבִּי יְהוּדָה אָמַר, כַּבֵּד אֶת אָבִיךְ - סְתָם. וְאֶת אִמֶּךְ - סְתָם. שֶׁהֲרֵי הַכֹּל הָיָה בְּמִנְיָן. אֶת - לְרַבּוֹת כָּל מַה שֶּׁלְּמַעְלָה וָמַטָּה."],[3,"","רַבִּי יוֹסֵי אָמַר, זֶה שֶׁאָמַר רַבִּי אַבָּא, מִמָּקוֹם שֶׁמַּתְחִיל לְהִמָּשֵׁךְ הַכֹּל, נִקְרָא אַתָּה, יָפֶה. שֶׁהֲרֵי לָמַדְנוּ שֶׁאוֹתוֹ הַנִּסְתָּר וְאֵין בּוֹ הַתְחָלָה נִקְרָא הוּא. מִמָּקוֹם שֶׁהָרֵאשִׁית נִמְצֵאת נִקְרָא אַתָּה. וְנִקְרָא אָב. וְהַכֹּל אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן."],[4,"","רַבִּי חִזְקִיָּה אָמַר, וַדַּאי הַכֹּל אֶחָד. כַּבֵּד אֶת אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. שֶׁהֲרֵי שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם - אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּנִים. וּמִשּׁוּם כָּךְ הַסְּתִימוּת שֶׁל הַדָּבָר, כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, לְהַכְלִיל אֶת הַכֹּל שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. רַבִּי יִצְחָק אָמַר, לְהַכְלִיל בּוֹ אֶת רַבּוֹ, שֶׁהוּא מַכְנִיס אוֹתוֹ לָעוֹלָם הַבָּא. אָמַר רַבִּי יְהוּדָה, הוּא בִּכְלַל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","שָׁנִינוּ, בַּחֲמֵשׁ הָאֲמִירוֹת הַלָּלוּ כָּלוּל הַכֹּל. בַּחֲמֵשׁ הָאֲמִירוֹת הַלָּלוּ נֶחְקְקוּ חָמֵשׁ אֲחֵרוֹת, וַדַּאי חָמֵשׁ תּוֹךְ הֶחָמֵשׁ. הָכֵיצַד? אָנֹכִי ה' אֱלֹהֶיךְ - כְּנֶגֶד לֹא תִרְצַח. שֶׁשָּׁנִינוּ, (אמר רבי יצחק אמר רבי יהודה) שְׁנֵי אֵלֶּה בִּכְלַל אֶחָד נִכְלְלוּ, שֶׁמִּי שֶׁהוֹרֵג מַקְטִין הַדְּמוּת וְצֶלֶם שֶׁל רִבּוֹנוֹ, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם."],[6,"","אָמַר רַבִּי חִיָּיא, כָּתוּב (בראשית ט) שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ וְגוֹ'. (שפך דם האדם) מִי שֶׁשּׁוֹפֵךְ דָּם כְּאִלּוּ מַקְטִין הַדְּמוּת וְהַצֶּלֶם שֶׁלְּמַעְלָה. כְּלוֹמַר, לֹא הִקְטִין דְּמוּת זוֹ, אֶלָּא דְּמוּת אַחֶרֶת, מַשְׁמָע שֶׁכָּתוּב שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ. בָּאָדָם הָעֶלְיוֹן מַגִּיעַ הַפְּגָם הַזֶּה מֵאוֹתוֹ דָּם שֶׁשָּׁפַךְ. מָה הַטַּעַם? מִשּׁוּם כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וּמִשּׁוּם כָּךְ זֶה בָּזֶה תָּלוּי."],[7,"","לֹא יִהְיֶה לְךְ - כְּנֶגֶד לֹא תִנְאָף. זֶה מְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּרְשָׁם בָּאָדָם. וּבָזֶה כַמָּה וְכַמָּה חֲטָאִים וּגְזֵרוֹת וָעֳנָשִׁים תְּלוּיִים. וּמִי שֶׁמְּשַׁקֵּר בָּזֶה, מְשַׁקֵּר בּוֹ בַּמֶּלֶךְ, שֶׁכָּתוּב (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ. וְכָתוּב לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם, וְזֶה בָּזֶה תָּלוּי."],[8,"","לֹא תִשָּׂא - כְּנֶגֶד לֹא תִגְנֹב. וְכָתוּב (משלי כט) חוֹלֵק עִם גַּנָּב שׂוֹנֵא נַפְשׁוֹ אָלָה יִשְׁמַע וְלֹא יַגִּיד. וַדַּאי זֶה בָּזֶה תָּלוּי, שֶׁהֲרֵי הַגַּנָּב לָזֶה מִזְדַּמֵּן, לְהִשָּׁבַע בְּשֶׁקֶר. מִי שֶׁעוֹשֶׂה זֶה, עוֹשֶׂה זֶה."],[9,"","זָכוֹר אֶת יוֹם הַשַּׁבָּת - כְּנֶגֶד לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. שֶׁאָמַר רַבִּי יוֹסֵי, שַׁבָּת נִקְרֵאת עֵדוּת, וְצָרִיךְ הָאָדָם לְהָעִיד עַל זֶה, שֶׁכָּתוּב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' וְגוֹ'. וְשַׁבָּת כְּלָל (עדות) שֶׁל הַכֹּל. וְאָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וּמִי שֶׁמֵּעִיד שֶׁקֶר - מְשַׁקֵּר בַּשַּׁבָּת, שֶׁהִיא עֵדוּת אֱמֶת. וּמִי שֶׁמְּשַׁקֵּר בַּשַּׁבָּת - מְשַׁקֵּר בְּכָל הַתּוֹרָה. וּמִשּׁוּם כָּךְ זֶה בָּזֶה תָּלוּי."],[10,"","כַּבֵּד אֶת אָבִיךְ - כְּנֶגֶד לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ. וְאָמַר רַבִּי יִצְחָק, כַּבֵּד אֶת אָבִיךְ - אָבִיךְ מַמָּשׁ. שֶׁהֲרֵי מִי שֶׁחוֹמֵד אִשָּׁה וּמוֹלִיד בֵּן, הַהוּא מְכַבֵּד אֶת הָאַחֵר שֶׁאֵינוֹ אָבִיו, וְכָתוּב כַּבֵּד אֶת אָבִיךְ וְגוֹ', לֹא תַחְמֹד בֵּית רֵעֶךְ שָׂדֵהוּ. וְכָתוּב כָּאן, עַל הָאֲדָמָה אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ. אוֹתוֹ שֶׁנָּתַן לְךְ יִהְיֶה שֶׁלְּךְ, וְלֹא תַחְמֹד אַחֵר. וַדַּאי שֶׁזֶּה תָּלוּי בָּזֶה."]]],[["וְאִלֵּין חָמֵשׁ קַדְמָאֵי, כְּלִילָן חָמֵשׁ אַחֲרָנִין. וּבְגִינֵי כַּךְ, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. דְּכֹלָּא אִתְעָבִיד יְמִינָא. וְעַל דָּא, בַּחֲמִשָּׁה קָלִין אוֹרַיְיתָא אִתְיְיהִיבַת. אָמַר ר' יְהוּדָה, כֻּלְּהוּ הֲווֹ חָמֵשׁ גּוֹ חָמֵשׁ. לָקֳבְלֵיהוֹן חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה.","תָּאנֵי ר' אֶלְעָזָר, בְּאִלֵּין עֶשֶׂר אֲמִירָן, אִתְגְּלִיפוּ כָּל פִּקּוּדֵי אוֹרַיְיתָא, גְּזִירִין וְעוֹנָשִׁין. דַּכְיָא וּמְסַאֲבָא. עַנְפִין וְשָׁרָשִׁין. אִילָנִין וּנְטִיעִין. שְׁמַיָּא וְאַרְעָא. יַמָּא וּתְהוֹמֵי. דְּהָא אוֹרַיְיתָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוִי, מַה שְּׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלִיף בְּעֶשֶׂר אֲמִירָן, אוּף אוֹרַיְיתָא אִתְגְּלִיפָא בְּעֶשֶׂר אֲמִירָן. אִלֵּין עֶשֶׂר אֲמִירָן אִינּוּן שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְאוֹרַיְיתָא כֹּלָּא שְׁמָא חַד הֲוֵי, שְׁמָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ.","זַכָּאָה חוּלָקֵיהּ, דְּמַאן דְּזָכֵי בָּהּ. מַאן דְּזָכֵי בְּאוֹרַיְיתָא, זָכֵי בִּשְׁמָא קַדִּישָׁא. (דקודשא בריך הוא ממש) ר' יוֹסִי אָמַר, בְּקוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ זָכֵי, (ס\"א וכנסת ישראל) דְּהָא הוּא וּשְׁמֵיהּ חַד הוּא, בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן.","(שמות כ׳:כ׳) לא תַעֲשׂוּן אִתִּי אֱלֹהֵי כֶּסֶף וֵאלֹהֵי זָהָב. אָמַר ר' יוֹסִי, (דבר אחר לא גרסינן מאי טעמא. משום דכתיב') (חגי ב׳:ח׳) לִי הַכֶּסֶף וְלִי הַזָּהָב, אַף עַל גַּב דְּלִי הַכֶּסֶף וְלִי הַזָּהָב, לא תַעֲשׂוּן אִתִּי, אִתִּי: כְּלוֹמַר אוֹתִי.","אָמַר ר' יִצְחָק, כְּתִיב (ירמיהו י׳:ו׳) מֵאֵין כָּמוֹךָ יְיָ' גָּדוֹל אַתָּה וְגָדוֹל שִׁמְךָ בִּגְבוּרָה וְגוֹ', (גדול אתה וגדול שמך) גָּדוֹל אַתָּה, הַיְינוּ לִי הַכֶּסֶף. וְגָדוֹל שִׁמְךָ בִּגְבוּרָה, הַיְינוּ וְלִי הַזָּהָב. אִלֵּין תְּרֵין גַּוְונִין לָא מִתְחַזְיָין, וְלָא מִתְפָּאֲרָן, בַּר כַּד אִינּוּן גְּלִיפִין בַּאֲתָר חַד, בְּאָן אֲתָר אִתְגְּלִיפוּ. בְּיִשְׂרָאֵל. כָּאן אִתְחָזוּן גַּוְונִין לְאִתְפָּאַרָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","ר' יְהוּדָה פָּתַח, (ישעיהו ס״א:י׳) שׂוֹשׂ אָשִׂישׂ בה' תָּגֵל נַפְשִׁי בֵּאלֹהַי וְגוֹ', זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, מֵעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּחֶדְוְותָא וְתַפְנוּקָא דִּלְהוֹן בְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב שׂוֹשׂ אָשִׂישׂ בַּיְיָ'. כֵּיוָן דְּאָמַר בַּיְיָ', אֲמַאי כְּתִיב בֵּאלֹהַי. אֶלָּא הָכִי אָמְרוּ יִשְׂרָאֵל, אִי בְּרַחֲמֵי אָתֵי עָלָנָא, שׂוֹשׂ אָשִׂישׂ בַּיְיָ'. אִי בְּדִינָא, תָּגֵל נַפְשִׁי בֵּאלהַי.","מַאי טַעְמָא. מִשּׁוּם דְּאִלֵּין בֵּיהּ אִתְגְּלִיפוּ, דִּכְתִּיב, (ישעיהו ס״א:י׳) כִּי הִלְבִּישַׁנִי בִּגְדֵי יֶשַׁע. מַהוּ בִּגְדֵי יֶשַׁע. גַּוְונִין, דְּאִתְגְּלִיפוּ לְאִסְתַּכְּלָא בֵּיהּ. כְּמָה דְאַתְּ אָמֵר, (שמואל ב כב) יִשְׁעוּ וְגוֹ' אֶל יְיָ'. יֶשַׁע אִסְתַּכְּלוּתָא הוּא. מַאן דְּבָעֵי לְאִסְתַּכְּלָא בִּי, בִּגְוָונִין דִּילִי יִסְתָּכַּל. מַאי טַעֲמָא. מִשּׁוּם דִּכְתִּיב, (ישעיהו ס״א:י׳) מְעִיל צְדָקָה יְעָטָנִי, צְדָקָה מַמָּשׁ, דִּגְוָונִין בֵּיהּ אִתְגְּלִיפוּ. כֶּחָתָן יְכַהֵן פְּאֵר, הָא גַּוְונָא חַד. וְכַכַּלָּה תַּעְדֶּה כֵּלֶיהָ, הָא גַּוְונָא אַחֲרָא. וְכַד גַּוְונִין מִתְחַבְּרָן, בֵּיהּ שַׁעֲתָא אִתְחַזְיָין, וְכֻלְּהוּ תְּאִיבִין לְאַחֲזָאָה, וּלְאִסְתַּכְּלָא בֵּיהּ.","ר' יוֹסִי אָמַר, שׂוֹשׂ אָשִׂישׂ בַּיְיָ', תְּרֵין חֶדְוָון. בַּיְיָ': בְּרַחֲמֵי. תָּגֵל נַפְשִׁי, הָא (חד חדוה) בְּדִינָא. אָמַר ר' יְהוּדָה, בְּכֹלָּא חֶדְוָה עַל חֶדְוָה. וְחֶדְוָה דְּצִיּוֹן, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַחְדָּאָה לְיִשְׂרָאֵל, בְּחֶדְוָותָא יַתִּיר מִכֹּלָּא, דִּכְתִּיב, (ישעיהו ל״ה:י׳) וּפְדוּיֵי יְיָ' יְשׁוּבוּן וּבָאוּ צִיּוֹן בְּרִנָּה וְגו', וּפְדוּיֵי יְיָ' יְשׁוּבוּן, הָא חַד. וּבָאוּ צִיּוֹן בְּרִנָּה, הָא תְּרֵי. וְשִׂמְחַת עוֹלָם עַל רֹאשָׁם, הָא תְּלַת. שָׂשׂוֹן וְשִׂמְחָה יַשִּׂיגוּ, הָא אַרְבַּע. לָקֳבְלֵיהוֹן דְּאַרְבַּע זִמְנִין דְּאִתְפְּזָרוּ יִשְׂרָאֵל בֵּינֵי עֲמַמְיָא. וּכְדֵין כְּתִיב (ישעיהו י״ב:ד׳) וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַיְיָ' קִרְאוּ בִשְׁמוֹ וְגוֹ'.","וַיְדַבֵּר אֱלהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה. כָּל הַדְּבָרִים, כְּלָלָא דָּא, הוּא כְּלָלָא דְּכֹלָּא, כְּלָלָא דִּלְעֵילָּא וְתַתָּא.","אָנֹכִי, רָזָא דְּעָלְמָא עִלָּאָה, בְּרָזָא דִּשְׁמָא קַדִּישָׁא יה\"ו. אָנֹכִי, אִתְגַּלְיָא וְאִתְגְּנִיז. אִתְגַּלְיָא בְּרָזָא קַדִּישָׁא דְּכֻרְסְיָיא, דְּסִיהֲרָא קַיְּימָא בִּשְׁלִימוּ כַּחֲדָא, כַּד שִׁמְשָׁא שַׁלְטָא, וְסִיהֲרָא אִתְנְהִירַת, וְלֵית לָהּ שְׁבָחָא, בַּר שְׁבָחָא דִּנְהוֹרָא דְּנָהִיר עָלָּה."],[[0,"ואלין חמש קדמאי וכו':","ובאלו חמשה דברות הראשונות, שבימין, כלולות חמשה דברות האחרות. ובשביל זה, מימינו אש דת למו. שהכל נעשה ימין. ועל כן ניתנה התורה בחמשה קולות. אמר ר' יהודה, כולם, כל עשרת הדברות, היו חמשה תוך חמשה, וכנגדם חמשה חומשי תורה."],[1,"תאני ר' אלעזר וכו':","באלו עשרת הדברות נחקקו כל מצות התורה הגזירות והעונשים, טהרה וטומאה, ענפים ושרשים, אילנות ונטיעות, שמים וארץ, ימים ותהומות, כי התורה היא שמו של הקב\"ה, מה שמו של הקב\"ה נחקק בעשרת הדברות אף התורה נחקקה בעשרת הדברות. אלו עשרת הדברות הם שמו של הקב\"ה. והתורה כולה הוא שם אחד שם הקדוש של הקב\"ה ממש."],[2,"זכאה חולקיה וכו':","אשרי חלקו של מי שזכה בה, שמי שזכה בתורה זכה בשמו הקדוש, ר' יוסי אמר, בהקב\"ה ממש זכה, כי הוא ושמו אחד הוא. ברוך שמו לעולם ולעולמי עולמים, אמן."],[3,"לא תעשון וכו':","לא תעשון אתי אלהי כסף ואלהי זהב. אמר ר' יוסי, מה הטעם. הוא משום שכתוב, לי הכסף ולי הזהב. אע\"פ שלי הכסף ולי הזהב לא תעשון אתי, כלומר אותי."],[4,"אמר ר' יצחק וכו':","אר\"י, כתוב, מאין כמוך ה' גדול אתה וגדול שמך בגבורה. וגו'. גדול אתה, היינו לי הכסף, שהוא חסד, קו ימין, וגדול שמך בגבורה, היינו ולי הזהב, שהוא גבורה, קו שמאל. אלו שני גוונים אינם נראים, ואינם מתפארים רק כשהם חקוקים במקום אחד. באיזה מקום נחקקו. בישראל. שהוא קו אמצעי, ת\"ת, המכריע ומקיים את שני הקוים. כאן נראים הגוונים להתפאר. כש\"א, ישראל אשר בך אתפאר."],[5,"ר' יהודה פתח וכו':","רי\"פ, שוש אשיש בה' תגל נפשי באלקי כי הלבישני בגדי ישע וגו'. אשרי חלקם של ישראל יותר מעמים עכו\"ם, שהשמחה והתענוג שלהם הוא בהקב\"ה, שכתוב, שוש אשיש בה'. כיון שאמר בה', למה כתוב באלקי. אלא כך אמרו ישראל אם ברחמים בא עלינו, שוש אשיש בהויה, שהוא רחמים. אם בדין, תגל נפשי באלקי שהוא דין."],[6,"מ\"ט משום דאלין וכו':","מה הטעם. שישראל שמחים הן בחסד והן בדין. הוא משום שאלו נחקקו בו, בהקב\"ה, שכתוב, כי הלבישני בגדי ישע. מהו בגדי ישע. הם גוונים של חסד וגבורה שנחקקו כדי להסתכל בו, דהיינו להמשיך חכמה. כמש\"א, ישעו ואין מושיע אל ה' וגו'. הרי שישע הוא הסתכלות. מי שרוצה להסתכל בי, יסתכל בגוונים שלי, שהם חסד וגבורה. מה הטעם. הוא משום שכתוב, מעיל צדקה יעטני, צדקה ממש, דהיינו המלכות שנקראת צדקה, שהגוונים נחקקו בה. שהחכמה נמשכת רק ממלכות. כחתן יכהן פאר, הוא גוון אחד, חסד. וככלה תעדה כליה הרי גוון אחר, גבורה. וכשהגוונים מתחברים בקו אמצעי, בה בשעה הם נראים והכל מתאוים לראות ולהסתכל בו."],[7,"ר' יוסי אמר וכו':","רי\"א, שוש אשיש בה' וגו'. שתי שמחות כאן, בה', הוא ברחמים. תגל נפשי באלקי, הוא בדין. אמר ר' יהודה, בכל הם שמחים הן ברחמים והן בדין, שמחה על שמחה. ושמחת ציון, עתיד הקב\"ה לשמח את ישראל בשמחה יתירה מכל. שכתוב, ופדויי ה' ישובון ובאו ציון ברנה וגו'. ופדויי ה' ישובון, הרי אחת. ובאו ציון ברנה, הרי שתים. ושמחת עולם על ראשם, הרי שלש. ששון ושמחה ישיגו, הרי ארבע. הם כנגד ארבע פעמים שנתפזרו ישראל בין העמים, ואז כתוב, ואמרתם ביום ההוא הודו לה' קראו בשמו וגו'."],[8,"וידבר אלקים וגו':","וידבר אלקים את כל הדברים האלה. \u0003כל הדברים,\u0004 כלל הזה הוא כלל הכל, כלל שלמעלה ושל מטה, הכל נכלל בעשרת הדברות."],[9,"אנכי רזא דעלמא וכו': אנכי,","הוא סוד עולם העליון, דהיינו הנוקבא שמחזה ולמעלה דז\"א, בסוד השם הקדוש יה\"ו, שהם ג' קוין חסד גבורה ת\"ת, שהנוקבא מקבלת מז\"א. \u0003אנכי\u0004, היינו המלכות, שנתגלתה ואח\"כ נגנזה. נתגלתה בסוד הקדוש של הכסא, שהוא בינה, שהמלכות נעשתה לו רגל רביעי, שהלבנה, שהיא המלכות, עומדת אז בשלמות עם ז\"א כאחד. דהיינו שקומתם שוה ושניהם משתמשים בכתר אחד. והיא נגנזה, בשעה שהשמש שהוא ז\"א, שולט, והלבנה האירה ממנו, ואין לה אז שום שבח מעצמה, חוץ משבח האור שז\"א מאיר עליה. ונמצאת, שבחינתה עצמה נגנזה. ומצב הזה נעשה אחר שנתמעטה הלבנה. (כמ\"ש היטב לעיל בראשית א' דף ק\"ח ד\"ה וכבר, עש\"ה)."]],[[0,"","וְאֵלּוּ הֶחָמֵשׁ הָרִאשׁוֹנוֹת כּוֹלְלוֹת חָמֵשׁ אַחֲרוֹנוֹת, וּמִשּׁוּם כָּךְ, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. שֶׁהַכֹּל נַעֲשֶׂה יָמִין. וְעַל זֶה בַּחֲמִשָּׁה קוֹלוֹת נִתְּנָה הַתּוֹרָה. אָמַר רַבִּי יְהוּדָה, כֻּלָּם הָיוּ חָמֵשׁ בְּתוֹךְ חָמֵשׁ, כְּנֶגְדָּם חֲמִשָּׁה חֻמְשֵׁי תוֹרָה."],[1,"","שָׁנָה רַבִּי אֶלְעָזָר, בְּעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ נֶחְקְקוּ כָּל מִצְווֹת הַתּוֹרָה, גְּזֵרוֹת וָעֳנָשִׁים, טָהוֹר וְטָמֵא, עֲנָפִים וְשָׁרָשִׁים, אִילָנוֹת וּנְטָעִים, שָׁמַיִם וָאָרֶץ, יָם וּתְהוֹמוֹת, שֶׁהֲרֵי הַתּוֹרָה הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נֶחְקַק בְּעֶשֶׂר אֲמִירוֹת - אַף הַתּוֹרָה נֶחְקְקָה בְּעֶשֶׂר אֲמִירוֹת. עֶשֶׂר הָאֲמִירוֹת הַלָּלוּ הֵם שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל הַתּוֹרָה הִיא שֵׁם אֶחָד, שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ."],[2,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה בָּהּ. מִי שֶׁזּוֹכֶה בַּתּוֹרָה זוֹכֶה בַּשֵּׁם הַקָּדוֹשׁ (של הקדושברוך הוא). רַבִּי יוֹסֵי אוֹמֵר, זוֹכֶה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא מַמָּשׁ (וכנסת ישראל), שֶׁהֲרֵי הוּא וּשְׁמוֹ אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן."],[3,"","לֹא תַעֲשׂוּן אִתִּי אֱלֹהֵי כֶסֶף וֵאלֹהֵי זָהָב. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב. אַף עַל גַּב שֶׁלִּי הַכֶּסֶף וְלִי הַזָּהָב - לֹא תַעֲשׂוּן אִתִּי. אִתִּי, כְּלוֹמַר אוֹתִי."],[4,"","אָמַר רַבִּי יִצְחָק, כָּתוּב (ירמיה י) מֵאֵין כָּמוֹךְ ה' גָּדוֹל אַתָּה וְגָדוֹל שִׁמְךְ בִּגְבוּרָה וְגוֹ'. (גדול אתה וגדול שמך) גָּדוֹל אַתָּה - הַיְנוּ לִי הַכֶּסֶף. וְגָדוֹל שִׁמְךְ בִּגְבוּרָה - הַיְנוּ וְלִי הַזָּהָב. שְׁנֵי הַגְּוָנִים הַלָּלוּ לֹא נִרְאִים וְלֹא מִתְפָּאֲרִים, פְּרָט לִכְשֵׁהֶם חֲקוּקִים בְּמָקוֹם אֶחָד. בְּאֵיזֶה מָקוֹם נֶחְקְקוּ? בְּיִשְׂרָאֵל. כָּאן נִרְאִים הַגְּוָנִים לְהִתְפָּאֵר, כַּכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[5,"","רַבִּי יְהוּדָה פָּתַח, (שם סא) שׂוֹשׂ אָשִׂישׂ בַּה' תָּגֵל נַפְשִׁי בֵּאלֹהַי וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהַשִּׂמְחָה וְהַתַּפְנוּק שֶׁלָּהֶם בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב שׂוֹשׂ אָשִׂישׂ בַּה'. כֵּיוָן שֶׁאָמַר בַּה', לָמָּה כָּתוּב בֵּאלֹהַי? אֶלָּא כָּךְ אָמְרוּ יִשְׂרָאֵל: אִם בְּרַחֲמִים בָּא עָלֵינוּ - שׂוֹשׂ אָשִׂישׂ בַּה', וְאִם בְּדִין - תָּגֵל נַפְשִׁי בֵּאלֹהַי."],[6,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאֵלֶּה נֶחְקְקוּ בוֹ, שֶׁכָּתוּבּ כִּי הִלְבִּישַׁנִי בִּגְדֵי יֶשַׁע. מַה זֶּה בִּגְדֵי יֶשַׁע? גְּוָנִים שֶׁנֶּחְקְקוּ לְהִסְתַּכֵּל בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר יִשְׁעוּ וְגוֹ' אֶל ה'. יֶשַׁע הוּא הִסְתַּכְּלוּת. מִי שֶׁרוֹצֶה לְהִסְתַּכֵּל בִּי, יִסְתַּכֵּל בַּגְּוָנִים שֶׁלִּי. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב מְעִיל צְדָקָה יְעָטָנִי, צְדָקָה מַמָּשׁ, שֶׁהַגְּוָנִים נֶחְקְקוּ בוֹ. כֶּחָתָן יְכַהֵן פְּאֵר, זֶה גָּוֶן אֶחָד. וְכַכַּלָּה תַּעְדֶּה כֵלֶיהָ, זֶה גָּוֶן אַחֵר. וּכְשֶׁהַגְּוָנִים מִתְחַבְּרִים, בְּאוֹתָהּ שָׁעָה נִרְאִים, וְכֻלָּם מִשְׁתּוֹקְקִים לִרְאוֹת וּלְהִסְתַּכֵּל בּוֹ."],[7,"","רַבִּי יוֹסֵי אָמַר, שׂוֹשׂ אָשִׂישׂ בַּה' - שְׁתֵּי חֶדְווֹת. בַּה' - בְּרַחֲמִים. תָּגֵל נַפְשִׁי - הֲרֵי (אחת בחדוה) בְּדִין. אָמַר רַבִּי יְהוּדָה, בַּכֹּל שִׂמְחָה שֶׁל שִׂמְחָה. וְחֶדְוָה שֶׁל צִיּוֹן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ אֶת יִשְׂרָאֵל בְּשִׂמְחָה יְתֵרָה מֵהַכֹּל, שֶׁכָּתוּב (שם לה) וּפְדוּיֵי ה' יְשֻׁבוּן וּבָאוּ צִיּוֹן בְּרִנָּה וְגוֹ'. וּפְדוּיֵי ה' יְשֻׁבוּן - הֲרֵי אַחַת. וּבָאוּ צִיּוֹן בְּרִנָּה - הֲרֵי שְׁתַּיִם. וְשִׂמְחַת עוֹלָם עַל רֹאשָׁם - הֲרֵי שָׁלֹשׁ. שָׂשׂוֹן וְשִׂמְחָה יַשִּׂיגוּ - הֲרֵי אַרְבַּע. כְּנֶגְדָּם שֶׁל אַרְבַּע פְּעָמִים שֶׁהִתְפַּזְּרוּ יִשְׂרָאֵל בֵּין הָעַמִּים, וְאָז כָּתוּב (שם יב) וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַה' קִרְאוּ בִשְׁמוֹ וְגוֹ'."],[8,"","וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה. כָּל הַדְּבָרִים - כְּלָל זֶה הוּא כְּלָל שֶׁל הַכֹּל, כְּלָל שֶׁל מַעְלָה וּמַטָּה."],[9,"","אָנֹכִי, סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ יה\"ו. אָנֹכִי, נִגְלֶה וְנִגְנָז, נִגְלֶה בְּסוֹד קָדוֹשׁ שֶׁל הַכִּסֵּא, שֶׁהַלְּבָנָה עוֹמֶדֶת בִּשְׁלֵמוּת כְּאֶחָד, כְּשֶׁהַשֶּׁמֶשׁ שׁוֹלֵט וְהַלְּבָנָה מְאִירָה, וְאֵין לָהּ שֶׁבַח פְּרָט לַשֶּׁבַח שֶׁל הָאוֹר שֶׁמֵּאִיר עָלֶיהָ."]]],[["אָנֹכִי, בְּאַשְׁלְמוּת רָזִין דִּשְׁלִימוּ דְּכוּרְסְיָּיא לְתַתָּא, וְאִסְתָּלָּקוּ חֵיוָן קַדִּישִׁין, וְאִיהִי אִתְתַּקְנַת בְּתִקּוּנָהָא. וְכַד אִיהִי שַׁפִּירָא בְּחֵיזוּ, וּבַעֲלָהּ אָתֵי לְגַבָּהָא, כְּדֵין אִקְרֵי אָנֹכִי.","אָנֹכִי, רָזָא דְּכֹלָּא כַּחֲדָא, בִּכְלָלָא דְּכָל אַתְוָון, בִּשְׁבִילֵי אוֹרַיְיתָא, דְּנַפְקוּ מִגּוֹ רָזָא עִלָּאָה, בְּהַאי אָנֹכִי, תַּלְיָין רָזִין עִלָּאִין וְתַתָּאִין. אָנֹכִי, רָזָא לְמֵיהָב אֲגָר טָב לְצַדִּיקַיָּא, דְּקָא מְחַכָּן לֵיהּ וְנַטְרֵי פִּקּוּדֵי אוֹרַיְיתָא, בְּהַאי, אִית לוֹן בִּטְחוֹנָא כַּדְקָא חֲזִי לְעָלְמָא דְּאָתֵי, וְסִימָנִיךְ (בראשית מ״א:מ״ד) אֲנִי פַרְעֹה.","אָנֹכִי וְלֹא יִהְיֶה לְךָ, אִתְּמַר בְּרָזָא דְּאוֹרַיְיתָא, וְדָא אִיהוּ זָכוֹר וְשָׁמוֹר. אָנֹכִי, רָזָא סְתִימָא וְגָנִיז, בְּכָל אִינּוּן דַּרְגִּין דְּעָלְמָא עִלָּאָה, בִּכְלָלָא חֲדָא. וְכֵיוָן דְּאִתְּמַר אָנֹכִי, אִתְחַבַּר כֹּלָּא כַּחֲדָא, בְּרָזָא חֲדָא.","אָנֹכִי, רָזָא דִּתְרֵין כֻּרְסְוָון. אֲנִי יְיָ דְכוּרְסְיָא אַחֲרָא (נ\"א אני כורסייא חדא. כ', כורסייא אחרא עלאה.)","אָנֹכִי, דְּקָא אִתְדָּכֵי מַקְדְּשָׁא, וְנוּכְרָאָה לָא אִתְקְרַב בַּהֲדֵיהּ, וּמַקְדְּשָׁא נָהִיר בִּלְחוֹדוֹי, דְּקָא אִתְבַּטַּל בְּהַהִיא שַׁעֲתָא יֵצֶר הָרַע מֵעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלָּק בִּיקָרֵיהּ בִּלְחוֹדוֹי, וּכְדֵין אִתְּמַר אָנֹכִי יְיָ' אֱלֹהֶיךָ. רָזָא שְׁלִים, בִּשְׁמָא קַדִּישָׁא. א': לְיַחֲדָא רָזָא דִּשְׁמָא קַדִּישָׁא בְּדַרְגּוֹי, לְמֶהֱוֵי חַד. בְּגִין דְרָזָא דִּילֵיהּ אִיהוּ ו'. נ': רָזָא לְמִדְחַל מִּקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִנְדַּע דְּאִית דִּין וְאִית דַּיָּין, וְאִית אֲגָר טָב לְצַדִּיקַיָּיא וּפוּרְעָנוּת לְרַשִׁיעַיָּא, בְּגִין דְרָזָא דִּילֵיהּ ה' תַּתָּאָה.","כ': לְקַדְּשָׁא שְׁמָא קַדִּישָׁא בְּכָל יוֹמָא, לְאִתְקַדְּשָׁא בְּדַרְגִּין קַדִּישִׁין, וּלְצַלָּאָה צְלוֹתָא לְגַבֵּיהּ בְּכָל זִמְנָא, לְאִסְתַּלְּקָא כִּתְרָא עִלָּאָה, רָזָא דְּכוּרְסְיָּיא עִלָּאָה, עַל גַּבֵּי חִיוָון עִלָּאִין, כְּדְקָא יֵאוֹת, וְרָזָא דִּילֵיהּ ה' עִלָּאָה.","י': לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, וּלְמִגְזַר גְּזִירוּ, בְּרָזָא לִתְמַנְיָא יוֹמִין, וּלְקַדְּשָׁא בֻּכְרָא. וּלְאַנָּחָא תְּפִילִין וְצִיצִית וּמְזוּזָה. וּלְמִמְסַר נַפְשָׁא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְדַּבְּקָא בֵּיהּ. אִלֵּין אִינּוּן תְּרֵיסַר פִּקּוּדִין עִלָּאִין, דִּכְלִילָן רל\"ו פִּקּוּדִין אַחֲרָנִין דְּאִינּוּן בְּרָזָא דְּאָנֹכִי, כְּלָלָא דְּזָכוֹר. וְאָת דָּא, לָא אִתְחַלָּף בְּאֲתָר אַחֲרָא דָּא, בְּגִין דְּאִיהִי י', רָזָא עִלָּאָה, כְּלָלָא דְּאוֹרַיְיתָא, וּבְאִלֵּין תְּרֵיסַר, אִית תְּרֵיסַר מְכִילִין דְּרַחֲמֵי, דְּתַלְיָין מִנַּיְיהוּ, וְחַד דְּשַׁלְטָא לְמֶהֱוֵי תְּלֵיסַר.","לֹא יִהְיֶה לְךָ, רָזָא דְּשָׁמוֹר, בִּתְלַת מְאָה וְשִׁתִּין וְחָמֵשׁ פִּקּוּדֵי אוֹרַיְיתָא. ל': רָזָא דְּלָא לְמֵיהַב יְקָר וּרְבוּ לֶאֱלָהָא אַחֲרָא. ל': מִגֲדְּלָא דְּפָרַח וְסָלִיק בַּאֲוִירָא, דְּלָא יִסְטֵי לִבָּא, לְמִבְנֵי לָהּ לֶאֱלָהָא אַחֲרָא, כְּמָה דְּאִית רָזָא, דְּבוֹנֶא מִגֲדְּלָא. (לאלהא אחרא) ל': דְּלָא לְמִפְנִי בְּדִיּוּקְנָא דְּעֲבוֹדָה זָרָה, דְּלָא לְהַרְהַרָא אֲבַתְרָהָא, דְּלָא לְסַגְּדָא, וְלָא לְאַכְפְיָא גַּרְמֵיהּ לֶאֱלָהָא אַחֲרָא.","א': דְּלָא לְחַלְּפָא יִחוּדָא דְּמָרֵיהּ, בְּגִין טַעֲוָון אַחֲרָנִין. א': דְּלָא לְהַרְהַרָא דְּאִית אֱלָהָא אַחֲרָא בַּר מִנֵּיהּ. א': דְּלָא לְמִסְטֵי בָּתַר בִּידִין וּדְכוּרוֹ, בְּרָזָא דְּדִיּוּקְנָא דְּאָדָם, וְלָא בְּדִיּוּקְנָא אַחֲרָא. א': דְּלָא לְמִשְׁאַל מִן מֵתַיָּיא, וְלָא לְמֶעְבַּד חַרְשִׁין. א': דְּלָא יוֹמֵי בְּפוּמוֹי, בִּשְׁמָא דֶּאֱלָהָא אַחֲרָא. עַד הָכָא, תְּרֵיסַר אַחֲרָנִין, דְּאִינּוּן פִּקּוּדֵי שָׁמוֹר. וּבְאִלֵּין תְּרֵיסָר, תַּלְיָין תְּלַת מְאָה וְחַמְשִׁין וּתְלַת פִּקּוּדֵי דְּשָׁמוֹר אַחֲרָנִין, דִּכְלִילָן בְּאִלֵּין תְּרֵיסַר, וְרָזָא דָּא אָנֹכִי.","אָמַר רַבִּי שִׁמְעוֹן, תּוּ תָּנֵינָן, אָנֹכִי כְּלָלָא דְּעֵילָּא וְתַתָּא, כְּלָלָא דְּעִלָּאִין וְתַתָּאִין, כְּלָלָא דְּחֵיוָן קַדִּישִׁין, דִּכְלִילָן בֵּיהּ, כֹּלָּא הוּא בְּרָזָא דְּאָנֹכִי. לֹא יִהְיֶה לְךָ לְתַתָּא, רָזָא דִּתְרֵיסָר חֵיוָן תַּתָּאִין.","לֹא תַּעֲשֶׂה לְךָ פֶסֶל. פִּסְלוּ מֵהַהוּא אֲתָר עִלָּאָה, מֵהַהוּא אֲתָר קַדִּישָׁא. פֶסֶל. פְּסוֹלֶת דִּקְדוּשָׁא דְּאִיהוּ רָזָא דְּטַעֲוָא אַחֲרָא. וְרָזָא דָּא, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:ד׳) וָאֵרֶא וְהִנִּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. וְכָל תְּמוּנָה הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:ד׳) וְאֵשׁ מִתְלַקַּחַת. כִּי אָנֹכִי יְיָ' אֱלֹהֶיךָ, בְּגִין לְאַתְעֲרָא לִבָּא לְגַבֵּי עֵילָּא, וְלָא לְנַחְתָּא לְתַתָּא וְלָא לְמִקְרַב לִתְרַע בֵּיתָא. אֵל קַנָּא, דְּקִנְאָה אִיהוּ בְּהַהוּא אֲתָר.","וְרָזָא דָּא, (משלי ל׳:כ״א) תַּחַת שָׁלשׁ רָגְזָה אֶרֶץ. וְאִיהוּ לא תַּעֲשֶׂה לְךָ, חַד. פֶסֶל, תְּרֵין. וְכָל תְּמוּנָה, תְּלַת. וְאֶרֶץ דָּא, עַל דָּא אִתְרְגִיזַת."],[[0,"אנכי באשלמות רזין וכו':","אנכי, היינו המלכות כשהיא בהשלמת סוד השלמות של כסא התחתון דהיינו אחר שנתמעטה וירדה מן למעלה מחזה אל למטה מחזה, ונתקנה שם בסוד כסא תחתון, ונסתלקו ממנה החיות הקדושות שמחזה ולמעלה, והיא נתקנה בתיקוניה. וכשהיא יפת מראה, ובעלה, ז\"א, בא אצלה, אז נקראת \u0003אנכי.\u0004"],[1,"אנכי, רזא דכלא וכו':","אנכי, סוד הכולל הכל יחד, שכולל יחד כ\"ב אותיות ול\"ב שבילי החכמה, דהיינו בכלל כל האותיות שהם כ\"ב, בשבילי אורייתא, שהם ל\"ב, היוצאים מתוך סוד העליון, דהיינו מחכמה. באנכי הזה תלוים סודות העליונים והתחתונים. אנכי, הוא סוד לתת שכר טוב לצדיקים המחכים לו ושומרים מצוות התורה, בזה באנכי, יש להם בטחון כראוי לעולם הבא. וסימנך, \u0003אני\u0004 פרעה. שאמר כן, כדי לתת בטחון ליוסף שיתקיימו דבריו."],[2,"אנכי ולא יהיה לך וכו':","אנכי ולא יהיה לך נאמר בסוד התורה, וזה הוא זכור ושמור. שאנכי ה\"ס זכור. ולא יהיה לך ה\"ס שמור. אנכי, ה\"ס סתום וגנוז בכל אלו המדרגות של עולם העליון, שהן יה\"ו, כנ\"ל. בכלל אחד. וכיון שנאמר אנכי, נתחבר הכל יחד בסוד אחד. כלומר, שאנכי, הוא תמצית של התחברות כל המדרגות יחד."],[3,"אנכי, רזא דתרין כרסוון וכו':","אנכי, הוא סוד שני הכסאות, שהם כסא עליון שהיא בינה, דהיינו במה שהמלכות משמשת לה לרגל רביעי. וכסא התחתון שהוא המלכות עצמה אחר שנתמעטה, כנ\"ל. \u0003אני\u0004 של אנכי רומזת לכסא אחד דהיינו התחתון. \u0003כ'\u0004 של אנכי רומזת לכסא אחר העליון."],[4,"אנכי, דקא אתדכי וכו':","אנכי, יורה, שנטהר המקדש, שהוא המלכות, וזר לא נקרב אליו, והמקדש מאיר בלבדו, שנתבטל בשעה ההיא היצר הרע מן העולם, והקב\"ה התעלה בכבודו בלבדו, ואז נאמר אנכי ה' אלקיך. הוא סוד, שלם בשם הקדוש. \u0003א'\u0004 דאנכי, מורה, ליחד סוד השם הקדוש במדרגותיו להיות אחד. כי הסוד שלו הוא ו' של הויה. \u0003נ'\u0004 דאנכי, הוא סוד, ליראה את הקב\"ה ולדעת שיש דין ויש דיין, ויש שכר טוב לצדיקים ועונש לרשעים. כי הסוד שלו הוא ה' תחתונה של הוי\"ה."],[5,"כ' לקדשא שמא וכו': כ'","דאנכי הוא, לקדש השם הקדוש בכל יום, ולהתקדש במדרגות הקדושות, ולהתפלל תפלה אליו בכל זמן, להעלות כתר העליון, שהוא סוד כסא העליון, דהיינו בינה, על החיות העליונות כראוי, שהם חו\"ג תו\"מ, שמחזה ולמעלה דז\"א, שהם ד' רגלי הכסא, שהמלכות הוא חיה רביעית ורגל רביעי. והסוד שלו הוא \u0003ה'\u0004 עליונה של השם הוי\"ה. שהוא בינה, כי מבחינת מה שהמלכות הוא רגל רביעי אל כסא העליון שהוא בינה, נחשבת לבחינת בינה, וה' עליונה של הויה."],[6,"יוד, לאשתדלא באורייתא וכו': י'","דאנכי, היא, לעסוק בתורה ימים ולילות. ולמול מילה בסוד שמונת ימים, ולקדש הבכור, ולהניח תפילין וציצית ומזוזה, ולמסור הנפש אל הקב\"ה ולהתדבק בו, אלו הן י\"ב מצות עליונות הרמוזים באנכי הכוללים רל\"ו מצות אחרות, שהם בסוד אנכי, שביחד הן רמ\"ח מצות עשה, שהם כלל של זכור. כי זכור כולל רמ\"ח מצות עשה, ושמור כולל שס\"ה מצות לא תעשה. ואות זו אינה מתחלפת במקום אחר, כמו א' נ' כ' דאנכי, שמתחלפת על ה' ו' ה' דהויה. משום שהיא \u0003י',\u0004 סוד העליון כלל התורה, דהיינו שה\"ס חכמה תתאה המתיחדת עם \u0003י'\u0004 דהויה שה\"ס חכמה עלאה. וע\"כ אין זה חילוף מקום. ובאלו י\"ב מצות, יש י\"ב מדות הרחמים התלויות מהן, ואחת השולטת בכולן, שהיא עצם המלכות הנקראת אנכי, הם י\"ג. כנגד י\"ג מדות הרחמים."],[7,"לא יהיה לך וגו':","לא יהיה לך, הוא סוד שמור, הכולל שס\"ה מצות לא תעשה שבתורה, כנ\"ל. \u0003ל',\u0004 של לא יהיה לך, הוא סוד שלא לתת כבוד וגדולה לאלהים אחרים. \u0003ל'\u0004 הוא מגדל הפורח ועולה באויר. שה\"ס החכמה הנגלית על ידי יציאת \u0003י'\u0004 מאויר ונשאר אור, (כנ\"ל בראשית א' מ\"ה ד\"ה כד) שעי\"ז שב הבינה להיות חכמה. שלא יסור לבבו לבנות מגדל לאלהים אחרים. כמו שיש סוד בונה מגדל. דהיינו בדור הפלגה. \u0003ל'\u0004 שלא יסתכל בצורת עבודה זרה, שלא להרהר אחריה, שלא ישתחוה, ולא יכניע עצמו לאלהים אחרים."],[8,"א' דלא לחלפא וכו': א'","של לא יהיה לך, הוא שלא יחליף יחוד אדונו בשביל אלהים אחרים. \u0003א'\u0004 שלא יהרהר שיש אל אחר חוץ ממנו. \u0003א'\u0004 שלא יסור אחר אוב וידעוני בסוד צורת אדם, ולא בצורה אחרת. \u0003א'\u0004 שלא לשאול ממתים ולא לעשות כשפים. \u0003א',\u0004 שלא ישבע בפיו בשם אלהים אחרים. עד כאן י\"ב מצות אחרות שהם מצות הכלולות בשמור. ובאלו י\"ב תלוים שנ\"ג מצות אחרות של שמור, הכלולות באלו י\"ב, שביחד הן שס\"ה. וזה סוד אנכי ולא יהיה לך."],[9,"א\"ר שמעון תו וכו':","אר\"ש, עוד למדנו, \u0003אנכי\u0004 הוא כלל של מעלה ושל מטה. כלל של עליונים ותחתונים. כלל של חיות הקדושות הכלולות בו. הכל הוא בסוד אנכי. לא יהיה לך, הוא למטה, סוד י\"ב חיות תחתונות שהן במלכות."],[10,"לא תעשה לך פסל:","היינו פסולת ממקום ההוא העליון, ממקום קדוש ההוא, דהיינו, מצד שמאל דקדושה, \u0003פסל,\u0004 היינו פסולת דקדושה, שהוא סוד אלהים אחרים. וסוד זה הוא כש\"א, וארא, והנה רוח סערה בא מן הצפון וגו'. הצפון, ה\"ס צד שמאל של הקדושה. \u0003וכל תמונה.\u0004 זה שכתוב, ואש מתלקחת. \u0003כי אנכי ה' אלקיך,\u0004 בשביל לעורר הלב כלפי מעלה, ולא לירד למטה, ולא לקרב לשער הבית של הס\"א. \u0003אל קנא,\u0004 שבמקום זה יש קנאה."],[11,"ורזא דא תחת וגו':","וזה סוד, תחת שלש רגזה ארץ, והם, לא תעשה לך, אחד. פסל, שנים. וכל תמונה, שלש. והארץ רגזה על זה."]],[[0,"","אָנֹכִי, בְּהַשְׁלָמַת סוֹדוֹת שֶׁל שְׁלֵמוּת שֶׁל הַכִּסֵּא לְמַטָּה, וְהִתְעַלּוּ הַחַיּוֹת הַקְּדוֹשׁוֹת, וְהִיא הִתְתַּקְּנָה בְּתִקּוּנֶיהָ. וּכְשֶׁהִיא יָפָה לְמַרְאֶה וּבַעְלָהּ בָּא אֵלֶיהָ, אָז נִקְרֵאת אָנֹכִי."],[1,"","אָנֹכִי, סוֹד שֶׁל הַכֹּל כְּאֶחָד, בַּכְּלָל שֶׁל כָּל הָאוֹתִיּוֹת בִּשְׁבִילֵי הַתּוֹרָה שֶׁיָּצְאוּ מִתּוֹךְ סוֹד עֶלְיוֹן. בָּאָנֹכִי הַזֶּה תְּלוּיִים עֶלְיוֹנִים וְתַחְתּוֹנִים. אָנֹכִי, סוֹד לָתֵת שָׂכָר טוֹב לַצַּדִּיקִים שֶׁמְּחַכִּים לוֹ וְשׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה, בָּזֶה יֵשׁ לָהֶם בִּטָּחוֹן כָּרָאוּי לָעוֹלָם הַבָּא, וְסִימָנְךְ - אֲנִי פַרְעֹה."],[2,"","אָנֹכִי וְלֹא יִהְיֶה לְךְ נֶאֱמַר בְּסוֹד הַתּוֹרָה, וְזֶהוּ זָכוֹר וְשָׁמוֹר. אָנֹכִי, סוֹד נִסְתָּר וְגָנוּז בְּכָל אוֹתָן דְּרָגוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן בִּכְלָל אֶחָד. וְכֵיוָן שֶׁנֶּאֱמַר אָנֹכִי, הִתְחַבֵּר הַכֹּל כְּאֶחָד, בְּסוֹד אֶחָד."],[3,"","אָנֹכִי, סוֹד שֶׁל שְׁנֵי כִּסְאוֹת. אֲנִי ה' - שֶׁל כִּסֵּא אַחֵר. (אני כסא אחד. כ' כסא אחר עליון)."],[4,"","אָנֹכִי, שֶׁכְּשֶׁנִּטְהָר הַמִּקְדָּשׁ וְנָכְרִי לֹא יִקְרַב אֵלָיו וְהַמִּקְדָּשׁ מֵאִיר לְבַדּוֹ, שֶׁהֲרֵי הִתְבַּטֵּל בְּאוֹתָהּ שָׁעָה יֵצֶר הָרָע מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְעַלָּה בִּכְבוֹדוֹ לְבַדּוֹ, וְאָז נֶאֱמַר אָנֹכִי ה' אֱלֹהֶיךְ. סוֹד שָׁלֵם בַּשֵּׁם הַקָּדוֹשׁ. א' - לְיַחֵד סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּדַרְגוֹתָיו לִהְיוֹת אֶחָד, מִשּׁוּם שֶׁסּוֹדוֹ הוּא ו'. נ' - סוֹד לִירָא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא וְלָדַעַת שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן, וְיֵשׁ שָׂכָר טוֹב לַצַּדִּיקִים וּפֻרְעָנוּת לָרְשָׁעִים, מִשּׁוּם שֶׁהַסּוֹד שֶׁלּוֹ ה' תַּחְתּוֹנָה."],[5,"","כ', ' לְקַדֵּשׁ אֶת הַשֵּׁם הַקָּדוֹשׁ בְּכָל יוֹם, וּלְהִתְקַדֵּשׁ בִּדְרָגוֹת קְדוֹשׁוֹת, וּלְהִתְפַּלֵּל אֵלָיו תְּפִלָּה בְּכָל זְמַן לְהַעֲלוֹת הַכֶּתֶר הָעֶלְיוֹן, סוֹד שֶׁל הַכִּסֵּא הָעֶלְיוֹן עַל גַּבֵּי הַחַיּוֹת הָעֶלְיוֹנוֹת כָּרָאוּי, וְהַסּוֹד שֶׁלּוֹ ה' עֶלְיוֹנָה."],[6,"","י', ' לְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, וְלָמוּל מִילָה בְּסוֹד לִשְׁמֹנָה יָמִים, וּלְקַדֵּשׁ הַבְּכוֹר, וּלְהָנִיחַ תְּפִלִּין וְצִיצִית וּמְזוּזָה, וְלִמְסֹר אֶת הַנֶּפֶשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וּלְהִדָּבֵק בּוֹ. אֵלֶּה הֵן שְׁתֵּים עֶשְׂרֵה מִצְווֹת עֶלְיוֹנוֹת שֶׁכּוֹלְלוֹת מָאתַיִם שְׁלֹשִׁים וְשֵׁשׁ מִצְווֹת אֲחֵרוֹת שֶׁהֵן בַּסּוֹד שֶׁל אָנֹכִי, כְּלָל שֶׁל זָכוֹר. וְאוֹת זוֹ לֹא מִתְחַלֶּפֶת בְּמָקוֹם אַחֵר, זֶה מִשּׁוּם שֶׁהִיא י', סוֹד עֶלְיוֹן, כְּלָל שֶׁל הַתּוֹרָה, וּבִשְׁתֵּים עֶשְׂרֵה הַלָּלוּ יֵשׁ שְׁתֵּים עֶשְׂרֵה מִדּוֹת הָרַחֲמִים שֶׁתְּלוּיוֹת מֵהֶם, וְאַחַת שֶׁשּׁוֹלֶטֶת לִהְיוֹת שְׁלֹשׁ עֶשְׂרֵה."],[7,"","לֹא יִהְיֶה לְךְ, סוֹד שֶׁל שָׁמוֹר בִּשְׁלֹשׁ מֵאוֹת שִׁשִּׁים וְחָמֵשׁ מִצְווֹת הַתּוֹרָה. ל' - סוֹד שֶׁלֹּא לָתֵת כָּבוֹד וּגְדֻלָּה לֵאלוֹהַּ אַחֵר, ל' - מִגְדָּל שֶׁפּוֹרֵחַ וְעוֹלֶה בָּאֲוִיר, שֶׁלֹּא יִסְטֶה הַלֵּב לִבְנוֹת לֵאלוֹהַּ אַחֵר, כְּמוֹ שֶׁיֵּשׁ סוֹד שֶׁל בּוֹנֵה מִגְדָּל (לאלוה אחר). ל' - שֶׁלֹּא לִפְנוֹת בִּדְיוֹקָן שֶׁל עֲבוֹדָה זָרָה, שֶׁלֹּא לְהַרְהֵר אַחֲרֶיהָ, שֶׁלֹּא לְהִשְׁתַּחֲווֹת וְלֹא לִכְפּוֹת עַצְמוֹ לֵאלוֹהַּ אַחֵר."],[8,"","שֶׁלֹּא לִסְטוֹת אַחַר אוֹב וְיִדְּעוֹנִי בְּסוֹד שֶׁל דְּמוּת אָדָם, וְלֹא בִּדְמוּת אַחֶרֶת. א': שֶׁלֹּא לִשְׁאֹל מִן הַמֵּתִים וְלֹא לַעֲשׂוֹת כְּשָׁפִים. א': שֶׁלֹּא יִשָּׁבַע בְּפִיו בְּשֵׁם שֶׁל אֱלוֹהַּ אַחֵר. עַד כָּאן שְׁתֵּים עֶשְׂרֵה אֲחֵרוֹת שֶׁהֵם מִצְווֹת שָׁמוֹר, וּבַשְּׁתֵּים עֶשְׂרֵה הַלָּלוּ תְּלוּיוֹת שְׁלֹשׁ מֵאוֹת חֲמִשִּׁים וְשָׁלֹשׁ מִצְווֹת שֶׁל שָׁמוֹר אֲחֵרוֹת שֶׁכְּלוּלוֹת בַּשְּׁתֵּים עֶשְׂרֵה הַלָּלוּ, וְסוֹד זֶה אָנֹכִי."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, עוֹד שָׁנִינוּ, אָנֹכִי - כְּלָל שֶׁל מַעְלָה וּמַטָּה, כְּלָל שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּלָל שֶׁל חַיּוֹת הַקְּדוֹשׁוֹת שֶׁכְּלוּלוֹת בּוֹ, הַכֹּל הוּא בְּסוֹד שֶׁל אָנֹכִי. לֹא יִהְיֶה לְךְ - לְמַטָּה, סוֹד שֶׁל שְׁתֵּים עֶשְׂרֵה הַחַיּוֹת הַתַּחְתּוֹנוֹת."],[10,"","לֹא תַעֲשֶׂה לְךְ פֶסֶל. נִפְסְלוּ מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, מֵאוֹתוֹ מָקוֹם קָדוֹשׁ. פֶּסֶל - פְּסֹלֶת שֶׁל קְדֻשָּׁה, שֶׁהוּא סוֹד שֶׁל אֱלִיל אַחֵר, וְסוֹד זֶה כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. וְכָל תְּמוּנָה, זֶהוּ שֶׁכָּתוּב (שמות ט) וְאֵשׁ מִתְלַקַּחַת. כִּי אָנֹכִי ה' אֱלֹהֶיךְ, כְּדֵי לְעוֹרֵר אֶת הַלֵּב לְמַעְלָה וְלֹא לָרֶדֶת לְמַטָּה, וְלֹא לִקְרַב לְשַׁעַר הַבַּיִת אֵל קַנָּא, שֶׁהַקִּנְאָה הִיא בְּאוֹתוֹ מָקוֹם."],[11,"","וְסוֹד זֶה - (משליל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ. וְהוּא, לֹא תַעֲשֶׂה לְךְ - אֶחָד. פֶסֶל - שְׁנַיִם. וְכָל תְּמוּנָה - שָׁלֹשׁ. וִאֶרֶץ זוֹ עַל זֶה הִיא הִתְרַגְּזָה."]]],[["(שמות כ׳:ה׳) פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים. אִלָנָא חֲדָא, דְּאִינְצִיב חֲדָא, וּתְרֵין זִמְנִין, וּתְלַת זִמְנִין, וְאַרְבַּע זִמְנִין, וְאִתְפְּקַד עַל חוֹבֵי קַדְמָאֵי, אָב וּבֶן. שְׁלִישִׁי וּרְבִיעִי חַד הוּא כַּד לָא אִתְתַּקַּן, וְלָא חָיִישׁ לְאִתְתַּקְנָא, וְכֵן בְּהִפּוּכָא דְּדָא, לְאִילָנָא דְּאִיהוּ אִתְתַּקַּן כַּדְקָא חֲזִי, וְקָאִים עַל קִיוּמֵיהּ (נ\"א כדין) וְעוֹשֶׂה חֶסֶד וְגוֹ'.","(שמות כ) לא תִשָּׂא, רָזָא דָּא הָא אוּקְמוּהָ חַבְרַיָּיא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד שָׁתִיל עָלְמָא, אַטְבַּע גּוֹ תְּהוֹמֵי, צְרוֹרָא חֲדָא, חֲקִיקָא בִּשְׁמָא קַדִּישָׁא, וְאַטְבַּע לָהּ לְגוֹ תְּהוֹמָא. וְכַד מַיָּא בָּעָאן לְסַלְּקָא, חָמָאן רָזָא דִּשְׁמָא קַדִּישָׁא, חָקִיק עַל הַהוּא צְרוֹרָא, וְתַיְיבִין וּמִשְׁתַּקְּעִין, וְהַדְרִין לַאֲחוֹרָא, וּשְׁמָא דָּא קַיְּימָא עַד יוֹמָא דָּא, גּוֹ תְּהוֹמָא.","וּבְשַׁעֲתָא דְּאוֹמִין בְּנֵי נָשָׁא עַל קְשׁוֹט, בְּקִיּוּמָא דִּקְשׁוֹט, הַהוּא צְרוֹרָא סַלְּקָא, וּמְקַבְּלָא הַהוּא אוֹמָאָה, וְאַהְדָּר וְאִתְקַיַּים עַל תְּהוֹמָא, וְעָלְמָא אִתְקַיַּים, וְהַהוּא אוֹמָאָה דִּקְשׁוֹט קַיָּים עָלְמָא.","וּבְשַׁעֲתָא דְּאוֹמוּ בְּנֵי נָשָׁא אוֹמָאָה לְשַׁקְּרָא, הַהוּא צְרוֹרָא סַלְּקָא לְקַבְּלָא לָהּ לְהַהִיא אוֹמָאָה, כֵּיוָן דְּחָזֵי דְּאִיהוּ דְּשִׁקְרָא. כְּדֵין הַהוּא צְרוֹרָא דְּהֲוָה סָלִיק, תָּב לַאֲחוֹרָא, וּמַיִין אַזְלִין וְשָׁטִין, וְאַתְוָון דְּהַהוּא צְרוֹרָא, פַּרְחָן גּוֹ תְּהוֹמֵי, וְאִתְבַּדְּרָן, וּבָעָאן מַיָּא לְסַלְּקָא לְחַפְיָיא עָלְמָא, וּלְאַהְדָּרָא לֵיהּ כְּמִלְּקַדְּמִין.","עַד דְּזַמִּין (נ\"א דרמיז) קוּדְשָׁא בְּרִיךְ הוּא, לְחַד מְמָנָא, יְעַזְרִיאֵ\"ל, דִּי מְמָנָא עַל שִׁבְעִין מַפְתְּחָן, בְּרָזָא דִּשְׁמָא קַדִּישָׁא, וְעָאל לְגַבֵּיהּ דְּהַהוּא צְרוֹרָא, וְחָקִיק בֵּיהּ אַתְוָון כְּמִלְקַדְּמִין, וּכְדֵין אִתְקָיָּים עָלְמָא, וְאָהַדְרוּ מַיִין לְדוּכְתַיְיהוּ. (נ\"א דההוא צרורא ורגיש להו לאתוון דשמא קדישא וחקיק להו כמלקדמין ואהדרו מיין לדוכתייהו וכדין אתקיים עלמא) וְעַל דָּא כְּתִיב לא תִשָּׂא אֶת שֵׁם ה' אֱלהֶיךָ לַשָּׁוְא.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא י\"ב, לְאוֹמָאָה בִּשְׁמֵיהּ בְּאֹרַח קְשׁוֹט. וּמַאן דְּאוֹמֵי שְׁבוּעָה, הוּא כָּלִיל גַּרְמֵיהּ, בְּאִינּוּן ז' דַּרְגִּין עִלָּאִין, דִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְכְּלִיל בְּהוּ. וְהָא שִׁיתָא אִינּוּן. הַהוּא בַּר נָשׁ דְּאוֹמֵי אוֹמָאָה דִּקְשׁוֹט עַל פִּי בֵּית דִּין, כָּלִיל גַּרְמֵיהּ בְּהוּ, וְהוּא שְׁבִיעָאָה, לְקַיְּימָא שְׁמָא קַדִּישָׁא בְּדוּכְתֵּיהּ. ועַל דָּא כְּתִיב, (דברים ו׳:י״ג) וּבִשְׁמוֹ תִּשָּׁבֵעַ. וּמַאן דְּאוֹמֵי אוֹמָאָה לְמַגְּנָא וּלְשַקְּרָא, גָּרִים לְהַהוּא אֲתָר דְּלָא יִתְקָיָּים בְּדוּכְתֵּיהּ.","אוֹמָאָה לְקַיְּימָא פִּקּוּדָא דְּמָארֵיהּ, דָּא אִיהוּ שְׁבוּעָה דִּקְשׁוֹט, כַּד הַהוּא יִצֶּר הָרָע מְקַטְרֵג לְבַר נָשׁ, וּמְפַתֶּה לֵיהּ לְמֶעְבַּר עַל פִּקּוּדָא דְּמָארֵיהּ. דָּא אִיהוּ אוֹמָאָה דְּמָארֵיהּ אִשְׁתְּבַּח בֵּיהּ, וְאִצְּטְרִיךְ לֵיהּ לְבַר נָשׁ לְאוּמָאָה בְּמָארֵיהּ עַל דָּא, ואִיהוּ שְׁבָחָא דִּילֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתְּבַּח בֵּיהּ. כְּגוֹן בּוֹעַז, דִּכְתִּיב, (רות ג׳:י״ג) חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר. הָא יִצֶּר הָרָע הֲוָה מְקַטְרֵג לֵיהּ, ואוֹמֵי עַל דָּא.","נֶדֶר אִיהוּ לְעֵילָּא, ואִינּוּן חַיֵּי מַלְכָּא, רָזָא דְּרמ\"ח שַׁיְיפִין, וּתְרִיסַר קְטִירִין, כְּחוּשְׁבָּן ונֶדֶ\"ר. וְעַל דָּא חָמִיר מִשְּׁבוּעָה. חַיֵּי דְּמַלְכָּא אִלֵּין, דְּיָהִיב חַיִּין לְכָל אִלֵּין שַׁיְיפִין, ואִקְרוּן הָכִי בְּגִין אִינּוּן חַיִּין, וְאִינּוּן חַיִּין נַחְתִּין מֵעֵילָּא לְתַתָּא. לְהַהוּא מְקורָא דְּחַיּין. וּמֵהַהוּא מְקורָא נַחְתִּין לְתַתָּא, לְכָל אִינּוּן שַׁיְיפִין.","שְׁבוּעָה לְקַיְּימָא דַּרְגָּא דִּלְתַתָּא, רָזָא דִּשְׁמָא קַדִּישָׁא. ודָא אִקְרֵי מֶלֶךְ עַצְּמוֹ, דְּרוּחָא עִלָּאָה וְגוּפָא דִּילֵיהּ, לְמִשְׁרֵי בְּגַוִּיהּ, וּלְדַיְּירָא בֵּיהּ, בְּרוּחָא דְּשַׁארֵי גּוֹ גּוּפָא. וְעַל דָא אִקְרֵי מֶלֶךְ עַצְּמוֹ דְרוּחָא עִילָאָה תַּאִיבָה דִּילֵיה לְמִשְׁרֵי בְּגָוִיה עַצְּמוֹ דְהַהוּא דְסַתִּיר לְעֵילָא. וּבְגִין כַּךְ, מַאן דְּאוֹמֵי בִּקְשׁוֹט, הוּא מְקַיֵּים לְהַהוּא אֲתָר, וְכַד קָאֵי הַאי אֲתָר מְקוּיָים, מְקַיֵּים כָּל עָלְמָא. נֶדֶר שַׁרְיָא עַל כֹּלָּא, עַל מִצְּוָה, וְעַל רְשׁוּתָא דְּלָאו הָכִי בִּשְׁבוּעָה, והָכִי אוּקְמוּהָ חַבְרַיָּיא. (ע\"כ רעיא מהימנא) (פקודא י\"ג לאתעסקא בפריה ורביה וכו' עד בכל סטרין. ומשם תלך ויקרא מ\"ג ע\"ב וביום השמיני)"],[[0,"פקד עון וגו':","פקד עון אבות על בנים על שלשים ועל רבעים. הוקשה לו, והרי כתוב ובנים לא יומתו על אבות. ואומר, שהוא אילן אחד, דהיינו נשמה אחת, שנטע פעם אחת ושתי פעמים ושלש פעמים וארבע פעמים, כלומר שנתגלגלה ובאה בארבעה גופים, נפקד על עונות הראשונים בגלגול הרביעי, כי אב ובן שלישי ורביעי, דהיינו ד' גלגולים האלו, אחד הוא, שהם נשמה אחת, כשלא נתקן ולא דאג להתתקן. וע\"כ נענש על הגלגולים הראשונים, וכן להפך מזה, אילן שנתקן כראוי במשך זמן הגלגולים, ועומד על קיומו, אז כתוב עליו, ועושה חסד וגו'."],[1,"לא תשא:","סוד הזה כבר העמידוהו החברים. כי הקב\"ה, כששתל העולם הטביע תוך התהומות צרור אחד, דהיינו רסיס אבן, חקוק בשם הקדוש, והטביע אותו בתוך התהום. וכשהמים רוצים לעלות, להטביע העולם רואים סוד השם הקדוש חקוק על צרור ההוא, ושבים ומשתקעים וחוזרים לאחור. ושם הזה נמצא עד היום הזה תוך התהום."],[2,"ובשעתא דאומין בני וכו':","ובשעה שבני אדם נשבעים על אמת, בקיום אמת. צרור ההוא עולה ומקבל שבועה ההיא, וחוזר ומתקיים על התהום, והעולם מתקיים, ושבועת אמת ההיא מקיים העולם."],[3,"ובשעתא דאומו וכו':","ובשעה שבני אדם נשבעים שבועה לשוא, צרור ההיא עולה לקבל שבועה ההיא, כיון שרואה שהיא שקר, אז צרור ההוא שהיה עולה שב לאחור, והמים הולכים ושטים והאותיות של צרור ההוא פורחות תוך התהום ומתפזרות. והמים רוצים לעלות ולכסות העולם, ולהחזיר אותו לקדמותו, שהיה מים."],[4,"עד דזמין קב\"ה וכו':","עד שמזמין הקב\"ה ממונה אחד, יעזריאל, הממונה על שבעים מפתחות בסוד השם הקדוש, ונכנס אל צרור ההוא, וחוקק בו האותיות כמקודם, ואז מתקיים העולם, וחוזרים המים למקומם, ועל זה כתוב, לא תשא את שם ה' אלקיך לשוא."],[5,"פקודא י\"ב:","לשבע בשמו בדרך אמת. ומי שנשבע שבועה הוא כולל את עצמו באלו ז' מדרגות עליונות, ששם הקב\"ה שהוא המלכות, נכלל בהם. והרי שש מדרגות הן, חג\"ת נה\"י, שאדם ההוא שנשבע שבועת אמת על פי בית דין כלל את עצמו בהן, והוא עצמו הוא שביעי, כננד המלכות, לקיים השם הקדוש, שהיא מלכות, במקומו. וע\"כ כתוב, ובשמו תשבע. ומי שנשבע שבועה לשוא ולשקר. גורם למקום ההוא, למלכות, שלא יתקיים במקומו."],[6,"אומאה לקיימא פקודא וכו':","שבועה לקיים מצות רבונו, זו היא שבועת אמת, כשהיצר הרע מקטרג על האדם, ומפתהו לעבור על מצות רבונו. זו היא שבועה שרבונו משתבח בה, וצריך האדם לשבע ברבונו על זה, והוא שבח שלו, והקב\"ה משתבח בו. כגון בועז, שכתוב, חי ה' שכבי עד הבוקר, כי היצה\"ר היה מקטרג עליו, ונשבע על זה."],[7,"נדר איהו לעילא וכו':","נדר הוא למעלה והוא חיי המלך, דהיינו המוחין של המלכות שהם בבינה, סוד רמ\"ח אברים וי\"ב קשרים, שהם ארבע ספירות חו\"ג תו\"מ, שכל אחת כלולה מג' קוין. שהם כחשבון נדר, כי רמ\"ח וי\"ב הם רנ\"ד. ועל כן הוא חמור משבועה. חיי המלך אלו, נותן חיים לכל אלו האיברים, רמ\"ח, ונקרא כך, חיי המלך, משום אלו החיים. ואלו החיים יורדים ממעלה, מא\"ס ב\"ה, למטה, למקור החיים ההוא, שהוא בינה. וממקור ההוא יורדים למטה, למלכות, לכל אלו האברים, רמ\"ח."],[8,"שבועה לקיימא דרגא וכו':","השבועה היא, לקיים המדרגה שלמטה, סוד השם הקדוש, שהוא המלכות, וזה נקרא מלך עצמו, שרוח העליון בגוף שלו, בא לשכון בתוכו ולדור בו כרוח השוכן בתוך הגוף, כלומר, שהמוחין כבר נתלבשו בכלי מלכות, שנקרא גוף. שהוא נסתר למעלה בבינה, ואינה מתגלה אלא במלכות. ומשום זה מי שנשבע אמת הוא מקיים מקום ההוא, וכשמקום ההוא מקוים מקיים כל העולם. נדר שורה על הכל, על מצוה ועל רשות, מה שאין כן בשבועה, שאינה חלה על מצוה. וכך העמידו החברים."]],[[0,"","פֹּקֵֹד עֲון אָבוֹת עַל בָּנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים. אִילָן אֶחָד שֶׁנִּנְטַע פַּעַם וּפַעֲמַיִם וְשָׁלֹשׁ פְּעָמִים וְאַרְבַּע פְּעָמִים, וְנִפְקַד עַל חֲטָאִים רִאשׁוֹנִים אָב וּבֵן. שְׁלִישִׁי וּרְבִיעִי אֶחָד הוּא כְּשֶׁלֹּא הִתְתַּקֵּן וְלֹא חָשַׁשׁ לְהִתְתַּקֵּן, וְכֵן בַּהִפּוּךְ שֶׁל זֶה, לְאִילָן שֶׁהִתְתַּקֵּן כָּרָאוּי וְעוֹמֵד עַל קִיּוּמוֹ (אז) וְעוֹשֶׂה חֶסֶד וְגוֹ'."],[1,"","לֹא תִשָּׂא. אֶת הַסּוֹד הַזֶּה הֲרֵי בֵּאֲרוּ הַחֲבֵרִים, מִשּׁוּם שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁתַל אֶת הָעוֹלָם, הִטְבִּיעַ בְּתוֹךְ הַתְּהוֹמוֹת צְרוֹר אֶחָד חָקוּק בַּשֵּׁם הַקָּדוֹשׁ, וְהִטְבִּיעַ אוֹתוֹ בְּתוֹךְ הַתְּהוֹם, וּכְשֶׁהַמַּיִם רוֹצִים לַעֲלוֹת, הֵם רוֹאִים אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ חָקוּק עַל אוֹתוֹ צְרוֹר, וְשָׁבִים וְנִשְׁקָעִים וְחוֹזְרִים לְאָחוֹר, וְהַשֵּׁם הַזֶּה עוֹמֵד עַד הַיּוֹם הַזֶּה בְּתוֹךְ הַתְּהוֹם."],[2,"","וּבְשָׁעָה שֶׁנִּשְׁבָּעִים בְּנֵי אָדָם עַל אֱמֶת, בְּקִיּוּם שֶׁל אֱמֶת, אוֹתוֹ הַצְּרוֹר עוֹלֶה וּמְקַבֵּל אֶת אוֹתָהּ שְׁבוּעָה, וְחוֹזֵר וּמִתְקַיֵּם עַל הַתְּהוֹם וְהָעוֹלָם מִתְקַיֵּם, וְאוֹתָהּ שְׁבוּעַת אֱמֶת עוֹמֶדֶת לְעוֹלָם."],[3,"","וּבְשָׁעָה שֶׁנִּשְׁבָּעִים בְּנֵי אָדָם שְׁבוּעָה לַשֶּׁקֶר, אוֹתוֹ הַצְּרוֹר עוֹלֶה לְקַבֵּל אֶת אוֹתָהּ שְׁבוּעָה. כֵּיוָן שֶׁרוֹאֶה שֶׁהוּא שֶׁקֶר, אָז אוֹתוֹ צְרוֹר שֶׁהָיָה עוֹלֶה שָׁב לְאָחוֹר, וְהַמַּיִם הוֹלְכִים וְשָׁטִים, וְהָאוֹתִיּוֹת שֶׁל אוֹתוֹ צְרוֹר פּוֹרְחוֹת לְתוֹךְ הַתְּהוֹמוֹת וּמִתְפַּזְּרוֹת, וְרוֹצִים הַמַּיִם לְכַסּוֹת אֶת הָעוֹלָם וּלְהַחֲזִירוֹ כְּמוֹ מִקֹּדֶם."],[4,"","עֵד שֶׁמַּזְמִין (שרומז) הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְמֻנֶּה אֶחָד, יְעַזְרִיאֵ\"ל, שֶׁמְּמֻנֶּה עַל שִׁבְעִים מַפְתְּחוֹת בַּסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְנִכְנָס לְאוֹתוֹ צְרוֹר, וְחוֹקֵק בּוֹ אוֹתִיּוֹת כְּמוֹ מִקֹּדֶם, וְאָז מִתְקַיֵּם הָעוֹלָם וְחוֹזְרִים הַמַּיִם לִמְקוֹמָם, (שאותו צרור ומרגיש את האותיות של השם הקדוש וחוקק אותן כבתחלה, וחוזרים המים למקומם, ואז מתקים העולם) וְעַל זֶה כָּתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא."],[5,"","מִצְוָה י\"ב - לְהִשָּׁבַע בִּשְׁמוֹ בְּדֶרֶךְ אֱמֶת. וּמִי שֶׁנִּשְׁבָּע שְׁבוּעָה הוּא כּוֹלֵל אֶת עַצְמוֹ בְּאוֹתָן שֶׁבַע דְּרָגוֹת עֶלְיוֹנוֹת שֶׁהַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְלָל בָּהֶן. וַהֲרֵי הֵם שֵׁשׁ. אוֹתוֹ אָדָם שֶׁנִּשְׁבָּע שְׁבוּעַת אֱמֶת עַל פִּי בֵּית דִּין, כּוֹלֵל אֶת עַצְמוֹ בָּהֶן, וְהוּא שְׁבִיעִי לְקַיֵּם אֶת הַשֵּׁם הַקָּדוֹשׁ בִּמְקוֹמוֹ, וְעַל כֵּן כָּתוּב וּבִשְׁמוֹ תִּשָּׁבֵעַ. וּמִי שֶׁנִּשְׁבָּע שְׁבוּעָה לְחִנָּם וְלַשֶּׁקֶר, גּוֹרֵם לְאוֹתוֹ מָקוֹם שֶׁלֹּא יִתְקַיֵּם בִּמְקוֹמוֹ."],[6,"","שְׁבוּעָה לְקַיֵּם מִצְוַת רִבּוֹנוֹ - זוֹהִי שְׁבוּעַת אֱמֶת, כְּשֶׁאוֹתוֹ יֵצֶר הָרָע מְקַטְרֵג לָאָדָם וּמְפַתֶּה אוֹתוֹ לַעֲבֹר עַל מִצְוַת רִבּוֹנוֹ. זוֹהִי שְׁבוּעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ, וְצָרִיךְ לָאָדָם לְהִשָּׁבַע בְּרִבּוֹנוֹ עַל זֶה, וְהוּא שִׁבְחוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ, כְּמוֹ בֹּעַז, שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁהֲרֵי יֵצֶר הָרָע הָיָה מְקַטְרֵג לוֹ, וְנִשְׁבַּע עַל זֶה."],[7,"","נֶדֶר הוּא לְמַעְלָה, וְהֵם חַיֵּי הַמֶּלֶךְ, סוֹד שֶׁל רמ\"ח אֵיבָרִים וּשְׁנֵים עָשָׂר קְשָׁרִים כְּחֶשְׁבּוֹן וְנֶדֶ\"ר. וְעַל זֶה חָמוּר מִשְּׁבוּעָה. חַיֵּי הַמֶּלֶךְ אֵלֶּה, שֶׁנּוֹתֵן חַיִּים לְכָל הָאֵיבָרִים הַלָּלוּ, וְנִקְרָאִים כָּךְ בִּשְׁבִיל אוֹתָם חַיִּים, וְאוֹתָם חַיִּים יוֹרְדִים מִמַּעְלָה לְמַטָּה, לְאוֹתוֹ מְקוֹר הַחַיִּים, וּמֵאוֹתוֹ מָקוֹר יוֹרְדִים לְמַטָּה לְכָל אוֹתָם אֵיבָרִים."],[8,"","שְׁבוּעָה לְקַיֵּם דַּרְגָּה שֶׁלְּמַטָּה, סוֹד הַשֵּׁם הַקָּדוֹשׁ. וְזֶה נִקְרָא מֶלֶךְ עַצְמוֹ, שֶׁל רוּחַ עֶלְיוֹנָה וְגוּף שֶׁלּוֹ, לִשְׁרוֹת בְּתוֹכוֹ וְלָדוּר בּוֹ כְּמוֹ הָרוּחַ שֶׁשּׁוֹרָה בְּתוֹךְ הַגּוּף, וְעַל זֶה נִקְרָא מֶלֶךְ עַצְמוֹ, שֶׁרוּחַ עֶלְיוֹנָה הִשְׁתּוֹקְקוּת שֶׁלָּהּ לִשְׁרוֹת בְּתוֹכוֹ עַצְמוֹ שֶׁל הַהוּא הַנִּסְתָּר לְמַעְלָה. וּמִשּׁוּם כָּךְ מִי שֶׁנִּשְׁבָּע בֶּאֱמֶת, הוּא מְקַיֵּם אֶת אוֹתוֹ מָקוֹם, וּכְשֶׁעוֹמֵד הַמָּקוֹם הַזֶּה מְקֻיָּם, מְקַיֵּם אֶת כָּל הָעוֹלָם. הַנֶּדֶר שׁוֹרֶה עַל הַכֹּל, עַל מִצְוָה, וְעַל רְשׁוּת שֶׁלֹּא כָּךְ בִּשְׁבוּעָה, וְכָךְ פֵּרְשׁוּהָ הַחֲבֵרִים."]]],[["(שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ דָּא אִיהוּ רָזָא דִּבְרִית קַדִּישָׁא. וּבְגִין דִּבְּהַאי בְּרִית קַיְימִין כָּל מְקוֹרִין דְּשַׁיְיפֵי גּוּפָא, וְאִיהוּ כָּלַל כֹּלָּא. כְּגַוְונָא, דָּא שַׁבָּת אִיהוּ כְּלָלָא דְּאוֹרַיְיתָא, וְכָל רָזִין דְּאוֹרַיְיתָא בֵּיהּ תַּלְיָין, וְקִיּוּמָא דְּשַׁבָּת, כְּקִיּוּמָא דְּכָל אוֹרַיְיתָא, מַאן דְּנָטִיר שַׁבָּת, כְּאִילּוּ נָטִיר אוֹרַיְיתָא כֻּלָּא.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא כ\"ד, לְמֶהֱוִי דָּכִיר יוֹם הַשַּׁבָּת, כְּמָה דְאַתְּ אָמֵר זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. רָזָא דְּשַׁבָּת, הָא אוֹקִימְנָא בְּכָל אִינּוּן דּוּכְתֵּי, יוֹמָא דּוּכְרָנָא דְּנַיְיחָא דְּעָלְמָא וְאִיהוּ כְּלָלָא דְּאוֹרַיְיתָא. וּמַאן דְּנָטִיר שַׁבָּת, כְּאִילּוּ נָטִיר אוֹרַיְיתָא כֹּלָּא. וְהָא אִתְּמַר, דּוּכְרָנָא דְּשַׁבָּת, לְקַדְּשָׁא לֵיהּ בְּכָל זִינֵי קִדוּשִׁין. מַאן דְּאִדְכַּר לְמַלְכָּא, אִצְּטְרִיךְ לְבָרְכָא לֵיהּ, מַאן דְּאִדְכַּר שַׁבָּת, צָּרִיךְ לְקַדְּשָׁא לֵיהּ וְהָא אִתְּמַר.","זָכוֹר לִדְכוּרָא אִיהוּ. שָׁמוֹר אִיהוּ לְנוּקְבָּא. (ודא בלא פרודא) יוֹם שַׁבָּת, רָזָא דְּכָל מְהֵימָנוּתָא, דְּתַלְיָא מֵרֵישָׁא עִלָּאָה, עַד סוֹפָא דְּכָל דַּרְגִּין, שַׁבָּת אִיהוּ כֹּלָּא.","תְּלַת דַּרְגִּין אִינּוּן, וְכֻלְּהוּ אִקְרוּן שַׁבָּת. שַׁבָּת עִלָּאָה. שַׁבָּת דְּיוֹמָא. שַׁבָּת דְּלֵילְיָא. וְכֻלְּהוּ חַד וְאִקְרֵי כֹּלָּא שַׁבָּת. וְכָל חַד, כַּד אִיהוּ שַׁלְטָא, נָטִיל לְחַבְרוֹי, וְזָמִין לוֹן בַּהֲדֵיהּ, בְּהַהוּא שׁוּלְטָנוּ דִּילֵיהּ. וְכַד הַאי אָתֵי לְעָלְמָא, כֻּלְּהוּ אַתְיָין וּזְמִינִין בַּהֲדֵיהּ.","כַּד אָתֵי לֵילְיָא, זַמִין בַּהֲדֵיהּ לְשַׁבָּת דִּימָמָא, וְזַמִין לֵיהּ בְּהֵיכָלֵיהּ, וְאִתְטָמַּר בַּהֲדֵיהּ. כֵּיוָן דְהַאי אַתְיָא, שַׁבָּת עִלָּאָה אִתְמְשָׁךְ עָלֵיהּ, וכֻלְּהוּ גְּנִיזִין בְּהֵיכְלָא דְּלֵילְיָא וּבְגִין דָּא סְעוּדָתָא דְּלֵילְיָא חָמוּר מִבְּיְמָמָא (ס\"א כדביממא.)","כַּד אָתֵי יְמָמָא, זַמִין בַּהֲדֵיהּ לִתְרֵין אִלֵּין אַחֲרָנִין, דַּרְגָּא עִלָּאָה וְדַרְגָּא תַּתָּאָה, דָּא דְּאַנְהִיר לֵיהּ, וְדָא דְּאִתְנְהִיר מִנִיהּ. וְכֹלָּא כַּחֲדָא אִקְרֵי שַׁבָּת, וְשַׁלְטִין בְּיוֹמָא דְּשַׁבָּת. וְאִלֵּין תְּלַת דַּרְגִּין, אִינּוּן כְּלָלָא ורָזָא דְּכָל אוֹרַיְיתָא, תּוֹרָה שֶׁבִּכְתָב, נְבִיאִים וּכְתוּבִים. מַאן דְּנָטִיר שַׁבָּת, נָטִיר אוֹרַיְיתָא כֻּלָּא.","תְּרֵין מַרְגְּלָן אִינּוּן, וחַד סִיכָתָא בַּהֲדַיְיהוּ, בְּגַוַּויְיהוּ, דְּקָאִים בֵּין הַאי וּבֵין הַאי. מַרְגְּלָא עִלָּאָה לֵית בֵּיהּ גּוָֹון, לֵית בֵּהּ חֵיזוּ בְּאִתְגַּלְּיָיא.","הַאי מַרְגְּלָא, כַּד שָׁאֲרִי לְאִתְגַּלְיָיא, נַהֲרִין, ז' אַתְוָון גְּלִיפִין, בַּלְטִין וְנֹצְּצִּין וּבְקָעִין בְּקִיעִין וקַסְטִירִין, ונַהֲרִין כָּל חַד וְחָד. וְאִינּוּן ז' אַתְוָון, אִינּוּן תְּרֵין שְׁמָהָן מְחֻקָּקִין בְּהַהוּא מַרְגְּלָא. וּבְיוֹמָא דְּשַׁבָּת, נָצְּצִּין וְנָהֲרִין, וּפַתְחִין פִּתְחִין, וְנַפְקֵי וְשַׁלְטֵי. וְאִינּוּן אהי\"ה יה\"ו, מִתְנָצְּצֵּי אַתְוָון, וּבִנְצִּיצּוּ דִּלְהוֹן, עָאלִין דָּא בְּדָא, וְנַהֲרִין דָּא בְּדָא.","וְכַד עָאלִין דָּא בְּדָא, נָהֲרִין דָּא מִגּוֹ דָּא, בִּתְרֵין גַּוונִין. חַד גּוָֹון חִוָּור, וְחַד גּוָֹון סוּמָק. וּמֵאִינּוּן תְּרֵין גַּוונִין, אִתְעֲבִידוּ תְּרֵין שְׁמָהָן אַחֲרָנִין, עַד דְּסַלְּקִין אַתְוון לְשֶׁבַע שְׁמָהָן.","א' נָפִיק וְנָצִּיץ, ועָאל בְּאָת ו', ונָהֲרִין תַּרְוַויְיהוּ, בִּתְרֵין גַּוְונִין, ואִינּוּן תְּרֵין שְׁמָהָן, חַד אִקְרֵי ידו\"ד, וְחַד אִקְרֵי אֵ\"ל, וְנַהֲרִין כַּחֲדָא. ה' נָפִיק ונָצִּיץ, וְעָאל בְּאָת ה' וְנָהֲרִין תַּרְוַויְיהוּ, בִּתְרֵין גַּוְונִין, וְאִינּוּן תְּרֵין שְׁמָהָן, חַד אִקְרֵי יֶדוִֹד רָזָא דֶּאֱלֹהִים. וְחַד אִקְרֵי אֱלהִים. וְנָהֲרִין כַּחֲדָא. י' עָאל בְּי', וְנַהֲרִין וּנְצִּיצִּין כַּחֲדָא, וְעָאלוּ דָּא בְּדָא, וְנַהֲרִין תַּרְוַויְיהוּ, גְּלִיפִין מְחֻקְּקָן כַּחֲדָא, וְאִינּוּן זַקְפָן רֵישָׁא, נְהִירִין מְנַצְּצִּין עַנְפִּין סַלְּקִין מֵהַאי סִטְרָא, וּמֵהַאי סִטְרָא, ואִינּוּן חַד סָרֵי עַנְפִּין.","וְאִלֵּין תְּרֵין אַתְוָון דְּנַהֲרָן, מִתְחַבְּקָן דָּא בְּדָא, אִינּוּן יְדוֹ\"ד יְדוֹ\"ד מצּפץ מצּפץ, בְּרָזָא דִּתְלֵיסָר מְכִילָן דְּרַחֲמֵי. וְאִלֵּין תְּרֵין אַתְוון, כַּד עָאלִין דָּא בְּדָא, וְכַד מִתְחַבְּקָן דָּא בְּדָא, (וכד מתדבקן דא בדא) זַקְפִין רֵישָׁא, ונָהֲרָן וּמְנַצְּצָּן עַל כֹּלָּא, בְּאִינּוּן חַד סָרֵי עַנְפִּין, דְּנָפְקִין בְּכָל סְטָר."],[[0,"זכור את יום השבת לקדשו:","זה הוא סוד הברית הקדוש, שהוא יסוד, ומשום שבברית הזה נמצאים כל המקורות של אברי הגוף, והוא כלל הכל, כעין זה, שבת היא כלל של התורה וכל סודות התורה בה תלוים, וקיום השבת הוא כקיום כל התורה. מי ששומר שבת כאלו שומר כל התורה."],[1,"פקודא כ\"ד:","לזכור את יום השבת, כמש\"א זכור את השבת לקדשו, סוד השבת העמדנו בכל המקומות, יום זכרון של מנוחת העולם. והוא כלל התורה, ומי ששומר שבת כאלו שומר התורה כולה. והרי למדנו, זכרון השבת, לקדש אותו בכל מיני קדושות, מי שזוכר את המלך צריך לברכו, מי שזוכר את השבת צריך לקדשו. וכבר למדנו."],[2,"זכור לדכורא איהו וכו':","זכור הוא לדכר, שהוא ז\"א, שמור הוא לנוקבא, שהיא מלכות. יום השבת הוא סוד של כל האמונה, התלויה מראש העליון, שהוא כתר, עד סוף כל המדרגות. שבת הוא הכל."],[3,"תלת דרגין אינון וכו':","שלש מדרגות הם וכולם נקראים שבת. שבת העליון, שהוא בינה, שבת של יום, שהוא ז\"א, שבת של לילה, שהיא המלכות. וכולם אחד, ונקרא הכל שבת. וכל אחד כשהוא שולט לוקח חבריו ומזמינם עמו בממשלה שלו, וכשזה בא לעולם כולם באים ונועדים עמו."],[4,"כד אתי ליליא וכו':","כשבא שבת של לילה, מזמין עמו שבת של יום, ומזמין אותו בהיכלו ומסתתר עמו, כיון שזה בא, נמשך עליו גם שבת העליון, וכולם גנוזים בהיכל השבת של לילה. ומשום זה סעודת הלילה חשוב כביום."],[5,"כד אתי יממא וכו':","כשבא שבת של יום, שהוא ז\"א, מזמין עמו לשנים אלו האחרים, מדרגה העליונה ומדרגה התחתונה זו שמאירה, וזו שהאירה ממנו. דהיינו בינה ומלכות. וכולם כאחד נקראים שבת, ושולטים ביום השבת. ואלו שלש מדרגות, הן כלל וסוד של כל התורה, תורה שבכתב נביאים וכתובים. מי ששומר שבת שומר התורה כולה."],[6,"תרין מרגלן אינון וכו':","שתי מרגליות הן ומסך אחד ביניהם העומד בין זו לזו. מרגלית העליונה אין בה צבע, אין בה מראה בגלוי."],[7,"האי מרגלא כד וכו':","מרגלית זו, העליונה, כשמתחילה להגלות מאירות ז' אותיות חקוקות, בולטות ומנצצות ובוקעות בקיעים והיכלות, ומאירות כל אחת ואחת. ואלו ז' האותיות הם שני שמות הנחקקים במרגלית ההיא, וביום השבת מנצצות ומאירות ופותחות פתחים ויוצאות ושולטות. והן \u0003אהי\"ה יה\"ו.\u0004 האותיות מתנוצצות ובהתנוצצות שלהן נכנסות זו בזו ומאירות זו בזו."],[7,"","ביאור הדברים. המלכות נקראת \u0003מרגלא,\u0004 להיותה נאחזת בנה\"י דז\"א, הנקראים רגלין. והוא מלשון ותגל מרגלותיו. ומחמת עלית המלכות לבינה, נקראת גם הבינה בשם מרגלא. והיא \u0003מרגלא עלאה.\u0004 ונודע שמחמת עלית המלכות לבינה נתמעטה הבינה לבחינת ו\"ק בלי ראש שה\"ס חסדים בלי חכמה. אמנם זה יתכן בז\"ת: חג\"ת נה\"י דבינה, שהן צריכות לחכמה וכשאין להן הן פגומות. אבל ג\"ר דבינה שהן תמיד באור החסדים ואינן מקבלות חכמה לעולם, אינן מתמעטות כלום מחמת עלית המלכות, (כמ\"ש היטב בהקדמת ספר הזהר דף י\"ד במראות הסולם ד\"ה והטעם ע\"ש)."],[7,"","וזה אמרו, \u0003מרגלא עלאה לית ביה גוון לית ביה חיזו באתגליא.\u0004 מרגלא עלאה היא בינה, ואין בה צבע, היינו הג\"ר דבינה שהיא תמיד באור החסדים ואור החסדים אין בהם צבע, שאין בהם שום אחיזה לדינים, \u0003ולית בה חיזו,\u0004 היינו שאין שם חכמה הנקרא מראה, אבל לא מחמת פגם, כי בג\"ר דבינה אין פגם כנ\"ל, וז\"ש \u0003באתגליא\u0004 שאין הגילוי חכמה נוהג שם לעולם. אבל בז\"ת דבינה שהן חג\"ת נהי\"מ יש בהם גוון ויש בהם חיזו (כמ\"ש במראות הסולם הנ\"ל) וז\"ש \u0003כד שארי לאתגליא,\u0004 דהיינו ז\"ת של המרגלא, שממנה נמשכים כל הגילוים, שבתחילת הן בו\"ק בלי ראש, מחמת עלית המלכות בהן כנ\"ל, וז\"ש \u0003נהרין ז' אתוון גליפין,\u0004 כנגד ז\"ת חג\"ת נהי\"מ, \u0003בלטין,\u0004 היינו בחסדים \u0003ונצצין,\u0004 היינו באור חוזר, \u0003ובקעין בקיעין וקסטירין,\u0004 היינו ע\"י עלית המלכות, נתבקעה המדרגה לשתים \u0003שחסד וגבורה ושליש ת\"ת\u0004 עד החזה נשארו במדרגת בינה, וגם המלכות נתחברה בהם מחמת העליה, ונה\"י, נפלו ממדרגת בינה וירדו למדרגה שמתחתיה, דהיינו לז\"א. וז\"ש, \u0003ואינון ז' אתוון אינון תרין שמהן מחקקין בההוא מרגלא,\u0004 דהיינו, \u0003אהי\"ה יה\"ו\u0004 ש \u0003חג\"ת\u0004 עד החזה, שעודם במדרגת בינה. ונקראים בשם \u0003אהי\"ה\u0004 כמו בינה. אבל \u0003נה\"י\u0004 שנפלו ממדרגת בינה לז\"א אינם נקראים עוד אהיה, אלא \u0003יה\"ו,\u0004 כמו ז\"א. באופן, אשר \u0003א'\u0004 דאהיה הוא \u0003חסד, ה'\u0004 דאהיה הוא \u0003גבורה, י'\u0004 דאהיה הוא \u0003תפארת\u0004 עד החזה, \u0003ה'\u0004 דאהיה, ה\"ס המלכות שעלתה שמה במקום החזה. שהן נשארו במדרגת בינה. שנקרא אהיה. ויה\"ו, שהם נה\"י שנפלו ממדרגת בינה, ה \u0003י'\u0004 הוא \u0003יסוד,\u0004 וה \u0003ה'\u0004 הוא \u0003הוד,\u0004 וה \u0003ו'\u0004 הוא נצח."],[7,"","ולעת גדלות יורדת המלכות ממקום בינה למקומה ואז חצאי המדרגות חוזרות ומתחברות (כנ\"ל בראשית א' דף ר\"צ, ד\"ה בגין ע\"ש) ואז מתחברות ב' חצאי המדרגות אהי\"ה יה\"ו. וז\"ש \u0003וביומא דשבת,\u0004 שאז עת הגדלות. \u0003נצצין\u0004 וכו' \u0003ואינון אהי\"ה יה\"ו מתנצצי אתוון, ובנציצו דלהון עאלין דא בדא ונהרין דא בדא\u0004 כי ב' חצאי המדרגות אהי\"ה יה\"ו מתחברות לאחת ומאירים זה בזה."],[7,"","ומה שהמלכות עלתה במקום החזה, ששם שליש עליון דת\"ת, הלא למקום בינה היתה צריכה לעלות. הענין הוא, כי בז\"ת נחשבים חג\"ת כמו כח\"ב בראש, ונמצא הת\"ת שהוא בינה, וע\"כ עלתה לת\"ת. (כמ\"ש בהקסה\"ז דף י\"א במראות הסולם ד\"ה ומה)."],[8,"וכד עאלין דא וכו':","וכשנכנסים זה בזה, מאירים זה מזה בשני צבעים, אחד צבע לבן שהוא ימין, ואחד צבע אדום שהוא שמאל. כלומר, שאינם נעשים מדרגה אחת ממש, אלא שנעשים לימין ושמאל, שאהיה נעשה לימין ויה\"ו נעשה לשמאל, ומזדווגים זה בזה. ומאלו ב' צבעים נעשו שני שמות אחרים, עד שעולים האותיות לז' שמות. שכל אות ואות מז' אותיות אהי\"ה יה\"ו נעשה לשם אחד."],[9,"א' נפיק ונציץ וכו':","ומפרש איך נעשות האותיות לז' שמות. ואומר, כי \u0003א'\u0004 דאהי\"ה יוצאת ונוצצת ונכנסת באות \u0003ו'\u0004 דיה\"ו, ומאירות בשני צבעים, לבן ואדום כנ\"ל, והם שני שמות, אחד נקרא \u0003הויה,\u0004 ואחד נקרא \u0003אל,\u0004 ומאירים יחד. \u0003ה',\u0004 דאהי\"ה יוצאת ונוצצת ונכנסת באות ה' דיה\"ו, ומאירות שתיהן בשני צבעים, לבן ואדום, ואלו שני השמות, אחד נקרא \u0003הויה\u0004 בסוד ניקוד אלקים שה \u0003י'\u0004 בחטף סגול, וה \u0003ה'\u0004 בחולם, וה \u0003ו'\u0004 בחירק, ואחד נקרא \u0003אלקים,\u0004 ומאירים יחד \u0003י'\u0004 דאהי\"ה, נכנסת ב \u0003י'\u0004 דיה\"ו, ונוצצות יחד, ונכנסות זו בזו ומאירות שתיהן, מפותחות וחקוקות כאחד, והן זוקפות ראש, דהיינו שמשיגות ג\"ר, ומאירות ומנוצצות, ענפין עולים מצד זה ומצד זה, דהיינו מימין ומשמאל, והם אחד עשר ענפים, מכל צד, שביחד הם כ\"ב ענפים, שה\"ס כ\"ב אותיות."],[9,"","ביאור הדברים. ביום השבת, אחר שיה\"ו שה\"ס נה\"י, חזרו ונתחברו עם חג\"ת שה\"ס אהי\"ה הם נתחברו ונסתדרו בסוד ג' קוין, חסד ונצח בקו ימין, גבורה והוד בקו שמאל, ת\"ת ויסוד בקו האמצעי. וז\"ש, \u0003א'\u0004 נפיק ונציץ ועאל באות \u0003ו',\u0004 כי א' דאהיה הוא חסד, כנ\"ל, ונתחברה עם אות \u0003ו'\u0004 דיה\"ו, שהוא נצח, ונגמר הקו ימין. וז\"ש, \u0003ואינון תרין שמהן, חד אקרי הויה,\u0004 שהוא חסד, \u0003וחד אקרי אל,\u0004 שהוא נצח. \u0003ונהרין כחדא\u0004 בקו ימין. ואח\"כ נתקן הקו שמאל, שהוא החיבור של גבורה והוד. וז\"ש, \u0003ה'\u0004 נפיק ונציץ ועאל באות \u0003ה'.\u0004 ש \u0003ה'\u0004 דאהיה שהיא גבורה כנ\"ל, נכנסה ונתחברה עם \u0003ה'\u0004 דיה\"ו שהוא הוד ונעשו לקו שמאל, ואינון תרין שמהן, \u0003חד אקרי הויה רזא דאלקים,\u0004 שהוא השם של גבורה. וחד אקרי אלקים, שהוא השם של הוד. ואח\"כ נתתקן קו האמצעי, דהיינו החיבור של ת\"ת ויסוד, וז\"ש \u0003י'\u0004 עאל ב \u0003י'\u0004 וכו', שה \u0003י'\u0004 דאהי\"ה שהוא תפארת עד החזה, כנ\"ל, נתחברה עם ה \u0003י'\u0004 דיה\"ו, שהיא יסוד, ונעשו לקו האמצעי. ובזה נשלם החזרה וההתחברות של חצי המדרגה נה\"י בחג\"ת, ואז חוזרים הג\"ר אל הבינה כמקודם לכן וז\"ש, \u0003ואינון זקפן רישא\u0004 וכו'. דהיינו שמשיגים ג\"ר. ומהארת קו האמצעי שהם ב' יודין, שהם ת\"ת ויסוד, יוצאים סוד כ\"ב אותיות, שהם כלל כל התורה. וז\"ש, \u0003ענפין סלקין מהאי סטרא ומהאי סטרא ואינון חד סרי ענפין,\u0004 מכל סטר, שהן כ\"ב אותיות."],[10,"ואלין תרין אתוון וכו':","ואלו ב' אותיות המאירות, שהן \u0003י'\u0004 דאהיה ו \u0003י'\u0004 דיה\"ו, שמתחבקות זו בזו, הן, הוי\"ה הוי\"ה, \u0003מצפץ מצפץ\u0004 בסוד שלש עשרה מדות הרחמים. ואלו שתי האותיות כשנכנסות זו בזו, ומתחבקות זו בזו, זוקפים ראש, דהיינו שמשיגים ג\"ר, ומאירים ומנוצצים על כל, באלו י\"א ענפים היוצאים מכל צד, דהיינו מצד ימין י\"א ומצד שמאל י\"א, שהם כ\"ב אותיות התורה כנ\"ל, שכל התורה והחכמה מתגלה ע\"י כ\"ב אותיות."],[10,"","פירוש. יש ב' שמות הויה קודם י\"ג מדות הרחמים שהם, אל רחום וחנון וגו'. והויה בא\"ת ב\"ש הוא \u0003מצפץ,\u0004 וסוד י\"ג מדות הרחמים הם בדיקנא דא\"א, וב' פאתי הראש הקודמים לדיקנא ה\"ס ב' שמות מצפץ. וענין ב' שמות אלו מבוארים לעיל (בראשית א' דף ק\"ה אות קי\"ב בסולם, ובמראות הסולם ע\"ש) ותמצית הדברים, שהכלים הריקנים שנשארו בראש א\"א אחר הסתלקות האורות דג\"ר דג\"ר, לא יכלו להשאר בראש א\"א מחמת עוביותם, ויצאו מראש א\"א ונתלו בחוץ על עור הראש דא\"א. והם המכונים שערות דא\"א. ואחר שיצאו נבקעו לב' חצאי מדרגה, שכו\"ח נשארו על ראש א\"א, ובינה ותו\"מ יצאו ממדרגת ראש ונעשו לשערות דיקנא. ולעת גדלות יורדת המלכות שבסיום שערות ראש לסיום שערות דיקנא, ואז עולות שערות דיקנא בחזרה לשערות ראש ונעשות מדרגה אחת. והנה הסיום דשערות רישא הנטהר מכל דין מחמת ירידת המלכות משם, הוא הנקרא בשם \u0003מצפץ.\u0004 והוא מצפץ הימני, שבסיום שערות ראש הנקרא פאה. ואותו הסיום הימני שנטהר נעשה לראש לשערות דיקנא, והוא מצפץ השמאלי. עש\"ה."],[10,"","וז\"ס ב' יודין יוד דאהיה ויוד דיה\"ו, שאומר כאן, שמתחברים בסוד ב' שמות מצפץ מצפץ. כי \u0003י'\u0004 דאהיה, ה\"ס שליש תפארת העליון עד החזה, כנ\"ל, בדבור הסמוך, שבעת הקטנות עלתה שם המלכות במקום החזה, בסוד \u0003י'\u0004 הנכנס ב \u0003אור\u0004 ונעשה \u0003אויר,\u0004 בחי' רוח בחסר ג\"ר. ועתה ביום השבת כשירדה המלכות ממקום החזה, ונטהר הת\"ת, מכל דין, נקרא הת\"ת עתה בשם \u0003מצפץ.\u0004 והוא מצפץ הימני. הרי ש \u0003י'\u0004 דאהי\"ה ה\"ס \u0003מצפץ.\u0004 וכשה \u0003י'\u0004 הזו מאירה ב \u0003י'\u0004 דיה\"ו, ונעשתה לראש אליה, נקרא ה \u0003י'\u0004 דיה\"ו ג\"כ בשם מצפץ, אלא שה\"ס מצפץ השמאלי כנ\"ל."]],[[0,"","זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, זֶהוּ סוֹד שֶׁל הַבְּרִית הַקָּדוֹשׁ. וּמִשּׁוּם שֶׁבִּבְרִית זוֹ עוֹמְדִים כָּל הַמְּקוֹרוֹת שֶׁל אֵיבְרֵי הַגּוּף וְהוּא כְּלַל הַכֹּל, כְּמוֹ זֶה שַׁבָּת הִיא כְּלָל שֶׁל הַתּוֹרָה, וְכָל סוֹדוֹת הַתּוֹרָה תְּלוּיִים בָּהּ, וְקִיּוּם שֶׁל הַשַּׁבָּת כְּמוֹ קִיּוּם שֶׁל כָּל הַתּוֹרָה. מִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה."],[1,"","מִצְוָה כ\"ד - לִהְיוֹת זוֹכֵר אֶת יוֹם הַשַּׁבָּת, כְּמוֹ שֶׁנֶּאֱמַר זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. סוֹד שֶׁל שַׁבָּת, הֲרֵי בֵּאַרְנוּ בְּכָל אוֹתָם מְקוֹמוֹת, יוֹם זִכָּרוֹן שֶׁל מְנוּחָה שֶׁל הָעוֹלָם, וְהוּא כְּלָל שֶׁל הַתּוֹרָה. וּמִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר כָּל הַתּוֹרָה. וַהֲרֵי נִתְבָּאֵר, זִכָּרוֹן שֶׁל שַׁבָּת לְקַדֵּשׁ אוֹתָהּ בְּכָל מִינֵי קִדּוּשִׁים. מִי שֶׁמַּזְכִּיר אֶת הַמֶּלֶךְ, צָרִיךְ לְבָרֵךְ אוֹתוֹ. מִי שֶׁמַּזְכִּיר שַׁבָּת, צָרִיךְ לְבָרֵךְ אוֹתָהּ, וַהֲרֵי נִתְבָּאֵר."],[2,"","זָכוֹר הוּא לְזָכָר. שָׁמוֹר הוּא לִנְקֵבָה. (וזהבליפרוד) יוֹם שַׁבָּת הַסּוֹד שֶׁל כָּל הָאֱמוּנָה, שֶׁתְּלוּיָה מֵהָרֹאשׁ הָעֶלְיוֹן עַד סוֹף כָּל הַדְּרָגוֹת, שַׁבָּת הִיא הַכֹּל."],[3,"","שָׁלש דְּרָגוֹת הֵן, וְכֻלָּן נִקְרָאוֹת שַׁבָּת. שַׁבָּת עֶלְיוֹנָה. שַׁבַּת שֶׁל הַיּוֹם. שַׁבָּת שֶׁל הַלַּיְלָה. וְכֻלָּן אַחַת, וְהַכֹּל נִקְרָא שַׁבָּת. וְכָל אַחַת כְּשֶׁהִיא שׁוֹלֶטֶת, לוֹקַחַת אֶת חַבְרוֹתֶיהָ וּמַזְמִינָה אוֹתָן עִמָּהּ בְּאוֹתוֹ הַשִּׁלְטוֹן שֶׁלָּהּ. וּכְשֶׁזֶּה בָּא לָעוֹלָם, כֻּלָּם בָּאִים וּמְזֻמָּנִים עִמּוֹ."],[4,"","כְּשֶׁבָּא הַלַּיְלָה, מַזְמִין עִמּוֹ שַׁבָּת שֶׁל הַיּוֹם, וּמַזְמִין אוֹתוֹ לְהֵיכָלוֹ וּמִסְתַּתֵּר עִמּוֹ. כֵּיוָן שֶׁזֶּה בָּא, שַׁבָּת הָעֶלְיוֹנָה נִמְשֶׁכֶת עָלֶיהָ, וְכֻלָּם גְּנוּזִים בַּהֵיכָל שֶׁל הַלַּיְלָה, וּמִשּׁוּם כָּךְ סְעוּדַת הַלַּיְלָה חֲמוּרָה מִבַּיּוֹם (כמו של היום)."],[5,"","כְּשֶׁבָּא הַיּוֹם, מַזְמִין עִמּוֹ אֶת שְׁתֵּי הָאֲחֵרוֹת הַלָּלוּ - דַּרְגָּה עֶלְיוֹנָה וְדַרְגָּה תַּחְתּוֹנָה, זוֹ שֶׁמְּאִירָה לָהּ וְזוֹ שֶׁנְּאוֹרָה מִמֶּנָּה, וְכֻלָּן כְּאַחַת נִקְרָאוֹת שַׁבָּת, וְשׁוֹלְטוֹת בְּיוֹם שַׁבָּת. וּשְׁלֹשׁ הַדְּרָגוֹת הַלָּלוּ הֵן כְּלָל וְסוֹד שֶׁל כָּל הַתּוֹרָה, תּוֹרָה שֶׁבִּכְתָב, נְבִיאִים וּכְתוּבִים. מִי שֶׁשּׁוֹמֵר שַׁבָּת, שׁוֹמֵר אֶת כָּל הַתּוֹרָה."],[6,"","שְׁתֵּי מַרְגָּלִיּוֹת הֵן, וְיָתֵד אֶחָד עִמָּן בְּתוֹכָן שֶׁעוֹמֵד בֵּין זוֹ וּבֵין זוֹ. הַמַּרְגָּלִית הָעֶלְיוֹנָה אֵין בָּהּ גָּוֶן, וְאֵין בָּהּ מַרְאֶה בְּהִתְגַּלּוּת."],[7,"","הַמַּרְגָּלִית הַזּוֹ, כְּשֶׁמַּתְחִילָה לְהִתְגַּלּוֹת, מְאִירוֹת שֶׁבַע אוֹתִיּוֹת חֲקוּקוֹת בּוֹלְטוֹת וְנוֹצְצוֹת, וּבוֹקְעוֹת בְּקָעִים וְהֵיכָלוֹת וּמְאִירִים כָּל אֶחָד וְאֶחָד, וְאוֹתָן שֶׁבַע הָאוֹתִיּוֹת הֵן שְׁנֵי שֵׁמוֹת חֲקוּקִים בְּאוֹתָהּ הַמַּרְגָּלִית, וּבְיוֹם הַשַּׁבָּת נוֹצְצִים וּמְאִירִים, וּפוֹתְחִים פְּתָחִים וְיוֹצְאִים וְשׁוֹלְטִים. וְאוֹתָם אהי\"ה יה\"ו, מִתְנוֹצְצוֹת הָאוֹתִיּוֹת, וּבָאוֹתִיּוֹת שֶׁלָּהֶן נִכְנָסוֹת זוֹ בָּזוֹ וּמְאִירוֹת זוֹ בָּזוֹ."],[8,"","וּכְשֶׁנִּכְנָסוֹת זוֹ בָּזוֹ, הֵן מְאִירוֹת זוֹ מִתּוֹךְ זוֹ בִּשְׁנֵי גְוָנִים. גָּוֶן אֶחָד לָבָן וְגָוֶן אֶחָד אָדם. וּמֵאוֹתָם שְׁנֵי גְוָנִים נַעֲשִׂים שְׁנֵי שֵׁמוֹת אֲחֵרִים, עַד שֶׁעוֹלוֹת הָאוֹתִיּוֹת לְשִׁבְעָה שֵׁמוֹת."],[9,"","א' יּוצּא וְנוֹצֵץ, וְנִכְנַס בָּאוֹת ו', וּמְאִירִים שְׁנֵיהֶם בִּשְׁנֵי גְוָנִים. וְאוֹתָם שְׁנֵי שֵׁמוֹת, אֶחָד נִקְרָא יְהֹוָ\"ה, וְאֶחָד נִקְרָא אֵ\"ל, וּמְאִירִים כְּאֶחָד. ה' יוֹצֵאת וְנוֹצֶצֶת, וְנִכְנֶסֶת בָּאוֹת ה', וּמְאִירוֹת שְׁתֵּיהֶם בִּשְׁנֵי גְוָנִים, וְאוֹתָם שְׁנֵי שֵׁמוֹת, אֶחָד נִקְרָא יֶהֹוִה, סוֹד שֶׁל אֱלֹהִים, וְאֶחָד נִקְרָא אֱלֹהִים, וּמְאִירִים כְּאֶחָד. י' נִכְנֶסֶת בְּי', וּמְאִירוֹת וְנוֹצְצוֹת כְּאַחַת, וְנִכְנָסוֹת זוֹ בָּזוֹ וּמְאִירוֹת שְׁתֵּיהֶן, חֲקִיקוֹת חֲקוּקוֹת כְּאַחַת, וְהֵן זוֹקְפוֹת רֹאשׁ, מְאִירוֹת וְנוֹצְצוֹת, הָעֲנָפִים עוֹלִים מִן הַצַּד הַזֶּה וּמִן הַצַּד הַזֶּה, וְהֵם אַחַד עָשָׂר עֲנָפִים."],[10,"","וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ שֶׁמְּאִירוֹת, מִתְחַבְּקוֹת זוֹ בָּזוֹ, הֵן יְהֹוָ\"ה יְהֹוָ\"ה מצפץ מצפץ, בְּסוֹד שֶׁל שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים. וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ, כְּשֶׁהֵן נִכְנָסוֹת זוֹ בָּזוֹ וּכְשֶׁמִּתְחַבְּקוֹת זוֹ בָּזוֹ, (וכשגדבקות זו בזו) זוֹקְפוֹת רֹאשָׁן וּמְאִירוֹת וְנוֹצְצוֹת עַל הַכֹּל בְּאוֹתָם אַחַד עָשָׂר הָעֲנָפִים שֶׁיּוֹצְאִים בְּכָל צַד."]]],[["ה' דְּאִשְׁתְּאַר, אִיהִי סַלְּקָא בִּשְׁמָא חַד, לְאִתְחַבְּרָא בַּהֲדַיְיהוּ, ואִיהִי אֲדֹנָי. וְכָל אִלֵּין שְׁמָהָן, בַּלְטִין וְנֹצְּצִּין וְנַפְקֵי וְשַׁלְטֵי בְּהַאי יוֹמָא. כֵּיוָן דְּאִלֵּין שַׁלְטֵי, נָפַק הַהוּא מַרְגְּלָא עִלָּאָה, בָּלְטָא מְנַצְּצָּא. וּמִגּוֹ נְצִּיצּוּ דִּילָהּ, לָא אִתְחָזִי בָּהּ גּוָֹון.","כַּד נָפְקָא, בָּטַשׁ בְּאִלֵּין שְׁמָהָן, חַד שְׁמָא מִנַּיְיהוּ אֲדֹנָי, דְּאִיהוּ שְׁבִיעָאָה, מִתְעַטְרָא ועָאל בְּמַרְגְּלָא תַּתָּאָה, וְאִתְיְישָׁב שְׁמָא אַחֲרָא תְּחוֹתֵיהּ, וְאִיהוּ י\"ה. וְאִסְתְּחַר הַהוּא מַרְגְּלָא עִלָּאָה בֵּיהּ, וּמִתְעַטְרָא הַהוּא נְצִּיצּוּ דְּנָצִּיץ, בְּהַאי שְׁמָא.","לְבָתַר דְכָנִישׁ (נ\"א דבטש) בְּהָנֵי שְׁמָהָן, נָפְקִין מִינַיְיהוּ שִׁבְעִים עַנְפִּין לְכָל סְטָר, וּמִתְחַבְּרָן כֻּלְּהוּ כַּחֲדָא, וְאִתְעָבִיד רְתִיכָא וְכֻרְסְיָיא חֲדָא, לְהַהוּא מַרְגְּלָא עִלָּאָה, ושָׁלְטָא בְּעִטְרוֹי, מַלְכָּא בְּכֻרְסְיָיא, בְּיוֹמָא דָּא, וְחַדֵּי כֹּלָּא. כֵּיוָן דְּחַדֵּי כֹּלָּא, יָתִיב מַלְכָּא עַל כֻּרְסְיָיא, וְסַלִיק בְּשִׁבְעִין עַנְפִּין כֻּרְסְיָיא, כִּדְקָאמְרַן.","וְאִינּוּן תְּרֵין (תרומה קל\"ב ע\"א) אַתְוָון, סַלְּקִין וְנַחְתִּין, וְנָהֲרִין וּמִתְעַטְרִין אַתְוון כ\"ב, (ס\"א בכ\"ב אתוון) כְּלָלָא דְּאוֹרַיְיתָא. בַּטְשֵׁי בִּתְרֵי (קל\"ב ע\"א) אַתְוָון קַדְמָאֵי, וְסַלְקֵי לְחָד, בְּשִׁית שְׁבָטִין, וּלְחַד בְּשִׁית שְׁבָטִין אַחֲרָנִין. וְאִלֵּין אִינּוּן י\"ב שְׁבָטִין דְּיִשְׂרָאֵל עִלָּאָה.","תּוּ, אִלֵּין תְּרִין אַתְוון, (נ\"א קדמאי סלקין) סַלְּקִין ונַחְתִּין, וּבַטְשֵׁי בִּתְרֵין אַתְוון, דְּסוֹפָא דכ\"ב אַתְוון. וסַלְקֵי, חַד בְּחָמֵשׁ דַּרְגִּין, וְחַד בְּחָמֵשׁ דַּרְגִּין. וְאִלֵּין עֶשֶׂר אֲמִירָן (ס\"א לשכללא) לְאַכְלְלָא לְכ\"ב אַתְוון, י\"ב שְׁבָטִין בִּתְרִין אַתְוון, (ס\"א קדמאי) כְּלָלָא דְּאוֹרַיְיתָא וָעֶשֶׁר אֲמִירָן דִּתְרֵין אַתְוון דְּסוֹפָא, הָא כ\"ב אַתְוָון, דְּסוֹפָא דְּאוֹרַיְיתָא. ורָזָא דָּא, יָרִית מַרְגְּלָא עִלָּאָה, בְּהַהוּא כֻּרְסְיָיא דְּע\"ב, ונָהֲרִין כ\"ב אַתְוָון.","מַרְגְּלָא תַּתָּאָה, בְּשַׁעֲתָא דְּיָתִיב מַרְגְּלָא עִלָּאָה בְּהַהוּא כּוּרְסְיָיא דְּע\"ב, ונַהֲרִין כ\"ב אַתְוון. כְּדֵין הַהוּא מַרְגְּלָא תַּתָּאָה דְּהוּא בְּחָשׁוֹכָא, מִסְתַּכֵּל בְּהַהוּא נְהִירוּ, בְּחֵילָא דְּתּוּקְפָּא דְּאִינּוּן אַתְוון, דְּאִתְרְשִׁים בְּהוֹן, דְּאִקְרוּן אֲדֹנָי, וּכְדֵין אִתְנְהִיר וְסָלִיק הַהוּא נְהוֹרָא, וְנָטִיל כָּל אִינּוּן כ\"ב אַתְוון עִלָּאִין, ושָׁאִיב לוֹן הַהוּא מַרְגְּלָא בְּגַוִּיהּ, וְנָהִיר נְהִירוּ דְּנָצִּיץ לְע\"ב עֵיבָר.","כֵּיוָן דְּהַאי מַרְגְּלָא, נָצִּיץ ושָׁאִיב לְאִינוּן אַתְוָון בַּהֲדָהּ, כְּדֵין מַרְגְּלָא עִלָּאָה אִתְמְשַׁךְ בַּהֲדַיְיהוּ, וְאִתְדַּבָּק מַרְגְּלָא בְּמַרְגְּלָא, והֲוִי כֹּלָּא חַד. וְדָא אִיהוּ רָזָא חֲדָא דְּתוּשְׁבַּחְתָּא, וְהָא אוֹקִימְנָא.","אַתְוון, כַּד נָצְּצִּין מֵהַאי סִטְרָא, וּמֵהַאי סִטְרָא, דָּא אִיהוּ סִיכָתָא דִּי בְּגַוַּויְיהוּ, בֵּין מַרְגְּלָא לְמַרְגְּלָא, כְּדֵין אִתְעָבִידוּ רָזָא דִּשְׁמָא קַדִּישָׁא דְּמ\"ב אַתְוון. בְּכֹלָּא רָזָא דִּשְׁמָא קַדִּישָׁא דְּע\"ב אַתְוון, דִּרְתִיכָא עִלָּאָה, וְכֹלָּא, הַאי והַאי, אִתְקְרֵי שַׁבָּת, וְדָא אִיהוּ רָזָא דְּשַׁבָּת. (ע\"כ רעיא מהימנא).","זָכוֹר רָזָא דִּדְכוּרָא אִיהוּ, רָזָא דִּדְכוּרָא דְּנָקִיט כָּל שַׁיְיפֵי דְּעָלְמָא עִלָּאָה. אֶת יוֹם הַשַּׁבָּת, לְאַסְגָּאָה מַעֲלֵי שַׁבְּתָא, דְּאִיהוּ לַיְלָה, וְדָא אִיהוּ אֶת. לְקַדְּשׁוֹ, דְּאִצְטְרִיךְ קְדוּשָׁה מִגּוֹ עַמָּא קַדִּישָׁא, וּלְאִתְעַטְּרָא בְּהוּ כַּדְקָא חֲזִי.","זָכוֹר, אֲתָר דְּלֵית לֵיהּ שִׁכְחָה, וְלָא קַיְּימָא בֵּיהּ שִׁכְחָה דְּהָא לֵית שִׁכְחָה (בראשית קצ\"ג ע\"ב) בַּאֲתָר דִּבְרִית עִלָּאָה, וְכָּל שֶׁכֵּן לְעֵילָּא. וּלְתַתָּא, אִית שִׁכְחָה, אֲתָר דְּאִצְטְרִיךְ לְאַדְכְּרָא, וְעַל דָּא כְּתִיב, (תהילים ק״ט:י״ד) יִזָּכֵר עֲוֹן אֲבוֹתָיו וְגוֹ'. וְאִית תַּמָּן מְמָנָן, דְּאַדְכְּרָן זַכְיָין דְּבַר נָשׁ, וְחוֹבוֹי.","וְלֵית שִׁכְחָה קָמֵי כֻּרְסְיָיא קַדִּישָׁא, מַה דְּאִיהוּ קָמֵיהּ. וּמַאן אִיהוּ קָמֵיהּ. זָכוֹר. וְכָּל שֶׁכֵּן לְעֵילָּא. בְּגִין דְּכֹלָּא רָזָא דִּדְכוּרָא אִיהוּ, וְתַמָּן אִתְגְּלִיף רָזָא דִּשְׁמָא קַדִּישָׁא יד\"ו. וּלְתַתָּא, אִצְטְרִיךְ לְאִתְקַדְּשָׁא, וּבַמֶּה אִתְקַדָּשׁ. בְּזָכוֹר, דְּהָא מִנֵּיהּ נָטִיל כָּל קִדּוּשָׁן וְכָל בִּרְכָּאן. וְדָא, כַּד מִתְעַטְּרֵי מַעֲלֵי שַׁבְּתָא, עַל עַמָּא קַדִּישָׁא כְּדְקָא יֵאוֹת, בִּצְלוֹתִין וּבְבָעוּתִין, וּבְסִדּוּרָא דְּחֶדְוָה.","וְאִי תֵּימָא, זָכוֹר, לָא אִצְטְרִיךְ לְאִתְקַדְּשָׁא, דְּהָא מִנֵּיהּ נָפְקִין כָּל קְדוּשִׁין דְּעָלְמָא. לָאו הָכִי. דְּהָא דָּא אִצְטְרִיךְ לְאִתְקַדְּשָׁא בִּימָמָא, וְדָא אִצְטְרִיךְ לְאִתְקַדְּשָׁא בְּלֵילְיָא, וְכָל קְדוּשִׁין נַטְלִין לוֹן יִשְׂרָאֵל לְבָתַר, וְאִתְקַדְּשָׁן בְּקִדּוּשֵׁי דְּקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ה' דאשתאר איהי וכו':","ה' דאהיה שנשארה, במקום החזה כנ\"ל, היא עולה בשם אחד להתחבר עמהם והוא \u0003אדני.\u0004 ולהלן מבאר שירדה משם למרגלא תתאה וכל אלו השמות בולטים ומנוצצים ויוצאים ושולטים ביום ההוא. בשבת כיון שאלו שולטים יוצאת מרגלא עליונה, שהיא ג\"ר דבינה, בולטת ומנוצצות ומתוך התנוצצות שלה לא נראה בה גוון. כי מאירה רק בחסדים, ואור החסדים אין בו גוון כנ\"ל."],[1,"כד נפקא בטש וכו':","כשיוצאת המרגלא, היא מזדווגת ומשפעת באלו השמות, אהיה יה\"ו, שהם ז\"ת שלה כנ\"ל, כי אע\"פ שאין בה גוון, שאינה מקבלת חכמה, עכ\"ז כל שפע החכמה שבז\"ת שלה מקובל על ידה, ואז, שם אחד מהם שהוא \u0003אדני,\u0004 שהיא המלכות שבמקום החזה דז\"ת, שהיא השביעית, מתעטרת ונכנסת במרגלא התחתונה, שהיא מלכות. ומתיישב שם אחר במקומו, והוא \u0003י\"ה.\u0004 דהיינו חכמה בינה. שאחר שירדה המלכות ממקום החזה מתגלה הג\"ר שהן י\"ה כנ\"ל. ומתישבת בו בשם י\"ה, מרגלא העליונה, ומתעטרת בהתנוצצות הזו המתנוצץ בשם הזה."],[2,"לבתר דבטש בהני וכו':","אחר שהמרגלא עלאה הזדווגה והשפיעה באלו השמות, אהי\"ה יה\"ו, כנ\"ל, יוצאים מהם ע' ענפים לכל צד, שהוא ז\"א, ומתחברים כולם יחד, ונעשו מרכבה וכסא למרגלא העליונה. והמלך שהוא חכמה שולט בעטרותיו בכסא, ביום הזה, והכל שמחים. כיון שהכל שמחים, יושב המלך על הכסא, והכסא עולה בשבעים ענפים כמו שאמרנו. כי ע' ענפים הם ז\"א, שחגת\"ם שלו נעשו ד' רגלים אל הכסא."],[3,"ואינון תרין אתוון וכו':","ואלו ב' אותיות, דהיינו ב' יודין שבב' שמות אהי\"ה יה\"ו, העולות ויורדות, ומאירים, ומתעטרים כ\"ב אותיות, שהם כלל התורה (כנ\"ל אות תקל\"ו) מזדווגות בב' אותיות הראשונות של כ\"ב אותיות, המסודרות בסדר תשר\"ק צפע\"ס וכו' (כמ\"ש בהקסה\"ז דף כ\"ה אות כ\"ב) שהן \u0003ת' ש',\u0004 ועולות בהארתם, לאחת בששה שבטים, ולאחת בששה שבטים אחרים, ואלו הם י\"ב שבטים דישראל העליון, שהוא ישראל סבא. שה\"ס ד' מדרגות חו\"ג תו\"מ, שכל אחת כלולה מג' קוין חג\"ת שהם י\"ב."],[4,"תו, אלין תרין אתוון וכו':","ועוד, אלו ב' אותיות, דהיינו ב' יודין דאהיה יה\"ו, עולות וירדות ומזדווגות בב' אותיות שבסוף כ\"ב אותיות המסודרות בסדר תשר\"ק, שהן \u0003ב' א'.\u0004 ועולות בהארתם, אחת בחמש מדרגות ואחת בחמש מדרגות, כנגד עשרה מאמרות, ואלו עשרה מאמרות כוללים כ\"ב אותיות. כי י\"ב שבטים יצאו בב' אותיות \u0003ת' ש'\u0004 עם עשרה מאמרות של ב' אותיות דסוף שהן \u0003ב' א'\u0004, הרי הן כ\"ב אותיות שהן כלל התורה. דהיינו ז\"א שנקרא תורה. שהוא נבנה מכ\"ב אותיות אלו. ועי' להלן (בזהר תרומה דף קל\"ב ע\"א ד\"י) ששם מבואר זה היטב בסוד השיר של שבת, אל אדון. וסוד זה יורש מרגלא העליונה בכסא ההוא של ע\"ב, ומאירים כ\"ב האותיות."],[5,"מרגלא תתאה, בשעתא וכו':","מרגלא התחתונה, בשעה שמרגלא העליונה יושבת על כסא ההוא של ע\"ב, וכ\"ב האותיות מאירות, אז מרגלא התחתונה שהיא בחושך, מסתכלת בהארה ההיא, של כ\"ב אותיות, בכח תוקף של אלו האותיות הנרשמות בה הנקראות אדני, ואז האיר ועולה אור ההוא, ומקבל כל אלו כ\"ב אותיות העליונות, ומרגלא התחתונה שואבת אותן לתוכה, ומאירה הארה המתנוצצת לע\"ב צדדים. שהיא הארת החכמה המתגלה בג' קוין."],[6,"כיון דהאי מרגלא וכו':","כיון שמרגלא ההיא התחתונה מנוצצת ושואבת אלו האותיות לתוכה, אז מרגלא העליונה נמשכת עמהן, ומתדבקות מרגלא במרגלא, שמרגלא תתאה שהיא מלכות מתדבקת במרגלא עלאה שהיא בינה, דהיינו שמלבישה אותה ונהיה הכל אחד. וזה הוא סוד של שבח אחד. וכבר בארנוהו. שהוא אל אדון הנאמר ביום השבת, כמ\"ש להלן בזהר, (תרומה קל\"ב ע\"א. ד\"י ע\"ש)."],[7,"אתוון כד נצצין וכו':","כ\"ב האותיות כשהם מנוצצות לצד זה ולצד זה, דהיינו לצד ימין ולצד שמאל, זה הוא המסך שביניהם בין מרגלא העליונה למרגלא התחתונה, ואז נעשו סוד השם הקדוש דמ\"ב אותיות. ובהכל הסוד של שם הקדוש דע\"ב אותיות, של המרכבה העליונה. והכל, זה וזה, דהיינה השם מ\"ב והשם ע\"ב, נקרא שבת, וזה הוא סוד השבת."],[7,"","פירוש. כי כ\"ב אותיות המאירות במזלא עלאה, ה\"ס הדעת שלה, דהיינו קו האמצעי. והארת קו האמצעי הוא באמצע, שאינו נוטה לא לימין ולא לשמאל, אבל במזלא עלאה מנוצצות האותיות לימין ולשמאל, ולא באמצע. והטעם הוא משום שקו האמצעי אינו מגלה שם הארת החכמה עם החסדים יחד, כי מרגלא עלאה היא ג\"ר דבינה, שמהן אין ה \u0003י'\u0004 יוצא מאויר לעולם. וע\"כ אין יחוד בקו האמצעי שהוא הדעת. וגם הוא מחולק לימין ושמאל. וה\"ס השם של \u0003מ\"ב\u0004 אותיות. משא\"כ בז\"ת דבינה ובז\"א מאיר הקו האמצעי באמצע, שאור החסדים ואור החכמה מאירים בו ביחד ואינו נוטה לימין ולשמאל. וה\"ס השם של ע\"ב אותיות. וזה כל ההפרש ממרגלא עלאה, שה\"ס שם מ\"ב ומרגלא תתאה המקבלת משם ע\"ב."],[7,"","וזה אמרו \u0003אתוון כד נצצין מהאי סטרא ומהאי סטרא,\u0004 ולא באמצע כטבע קו האמצעי, \u0003דא איהו סיכתא די בגווייהו\u0004 זה הוא המסך שביניהם, \u0003בין מרגלא למרגלא,\u0004 כי במרגלא עלאה נשאר המסך, שה\"ס ה \u0003י'\u0004 שנכנס באור ונעשה לאויר, וע\"כ אין קו האמצעי מאיר שם בהארת החכמה, ואין הימין והשמאל מיוחד בו, מה שאין כן מרגלא תתאה, מקבלת מקו אמצעי, המאיר בחכמה וחסדים יחדיו ואינו נוטה לא לימין ולא לשמאל, ואין שם \u0003סיכתא,\u0004 כי היוד יצא מאויר וחזר ונעשה אור, שזהו הארת השם ע\"ב. וז\"ש, \u0003כדין אתעבידו רזא דשמא קדישא דמ\"ב אתוון,\u0004 שהארה זו דמרגלא עלאה, נעשה לשם מ\"ב, (כמ\"ש להלן בזהר תרומה דף קל\"ב, ועי' לעיל בהקסה\"ז דף י\"ז ד\"ה ביאור) ואין לטעות שבמרגלא עלאה אין הארת חכמה כלל, לזה אומר, \u0003בכלא רזא דשמא קדישא דע\"ב אתוון דרתיכא עלאה,\u0004 שהארת ע\"ב מאיר אפילו במרגלא עלאה, אלא שאינו מתגלה שמה, כי שם שולט השם מ\"ב. \u0003וכלא, האי והאי אתקרי שבת.\u0004 שבשבת מאירים ב' השמות, מ\"ב וע\"ב. כי בשבת עולים זו\"ן שבהם מאיר ע\"ב ומלבישים לאו\"א עלאין שה\"ס ג\"ר דבינה שבהם מאיר השם מ\"ב. ונמצא שב' השמות מאירים בשבת. \u0003ודא איהו רזא דשבת\u0004 שבשאר ימים טובים אינו מאיר רק ע\"ב בלבד, אבל בשבת מאיר גם השם מ\"ב. (ע\"כ רעיא מהימנא)."],[8,"זכור רזא דדכורא וכו':","זכור, הוא סוד דכר, דהיינו ז\"א, המקבל כל האברים דהיינו כל המוחין, של עולם העליון, שהוא בינה. \u0003את יום השבת,\u0004 לרבות ליל שבת, שהוא לילה, דהיינו המלכות הנקראת לילה, וזה הוא \u0003את.\u0004 שהמלכות נקראת, את. \u0003לקדשו,\u0004 שצריך קדושה מן עם הקדוש ולהתעטר בהם כראוי."],[9,"זכור, אתר דלית וכו':","זכור, מקום שאין לו שכחה, ושכחה אינה נמצאת בו, כי אין שכחה במקום ברית העליון, שהוא יסוד, ומכל שכן למעלה, בז\"א. ולמטה, במלכות, יש שכחה, הוא מקום שצריכים להזכיר, שכתוב, יזכר עון אבותיו וגו'. ויש שם ממונים שמזכירים זכיות האדם ועונותיו."],[10,"ולית שכחה קמי וכו':","ואין שכחה \u0003לפני\u0004 כסא הקדוש, דהיינו מה שהוא לפני הכסא הקדוש שהוא בינה, ומי הוא לפני הכסא, הוא זכור, שהוא ז\"א, כי ז\"א עומד לפני הבינה ומקבל ממנה. ועליו נאמר, ואין שכחה \u0003לפני\u0004 כסא כבודך. ומכל שכן למעלה, מז\"א, שאין שכחה, משום שהכל הוא סוד דכר, ושם נחקק סוד השם הקדוש \u0003יה\"ו.\u0004 ולמטה, דהיינו במלכות, צריך להתקדש. ובמה מתקדש. בזכור, שהוא ז\"א, שממנו מקבלת כל הקדושות וכל הברכות. וזה הוא כשמתעטר ליל שבת שהוא המלכות, על עם הקדוש כראוי, בתפלות ובקשות, ובסדר של שמחה."],[11,"ואי תימא זכור וכו':","ואם תאמר, זכור, שהוא ז\"א, אינו צריך להתקדש, מישראל, שהרי ממנו, יוצאות כל הברכות והקדושות של העולם. אינו כן. כי זה, ז\"א, צריך להתקדש ביום השבת. וזה, המלכות צריך להתקדש בליל שבת. וכל הקדושות מקבלים אח\"כ ישראל, ומתקדשים בקדושה של הקב\"ה."]],[[0,"","ה' שֶׁנִּשְׁאֲרָה, הִיא עוֹלָה בְּשֵׁם אֶחָד לְהִתְחַבֵּר עִמָּם, וְהִיא אֲדנָי. וְכָל הַשֵּׁמוֹת הַלָּלוּ בּוֹלְטִים וְנוֹצְצִים וְיוֹצְאִים וְשׁוֹלְטִים בַּיּוֹם הַזֶּה. כֵּיוָן שֶׁאֵלֶּה שׁוֹלְטִים, יוֹצֵאת אוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה בּוֹלֶטֶת נוֹצֶצֶת, וּמִתּוֹךְ הַהִתְנוֹצְצוּת שֶׁלָּהּ לֹא נִרְאֶה בָּהּ גָּוֶן."],[1,"","כְּשֶׁיּוֹצֵאת, מַכָּה בַּשֵּׁמוֹת הַלָּלוּ. שֵׁם אֶחָד מֵהֶם אֲדנָ\"י, שֶׁהוּא שְׁבִיעִי, מִתְעַטֵּר וְנִכְנָס לַמַּרְגָּלִית הַתַּחְתּוֹנָה, וּמִתְיַשֵּׁב שֵׁם אַחֵר תַּחְתָּיו, וְהוּא י\"ה. וּמֻקֶּפֶת בּוֹ אוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה, וּמִתְעַטֶּרֶת אוֹתָהּ הַהִתְנוֹצְצוּת שֶׁנּוֹצֶצֶת בַּשֵּׁם הַזֶּה."],[2,"","אַחַר שֶׁהִתְכַּנְּסָה בַּשֵּׁמוֹת הַלָּלוּ, יוֹצְאִים מֵהֶם שִׁבְעִים עֲנָפִים לְכָל צַד, וּמִתְחַבְּרִים כֻּלָּם כְּאֶחָד, וְנַעֲשֵׂית מֶרְכָּבָה וְכִסֵּא אֶחָד לְאוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה, וְשׁוֹלֶטֶת בְּעַטְרוֹתֶיהָ, מֶלֶךְ בְּכִסֵּא בַּיּוֹם הַזֶּה, וְהַכֹּל שְׂמֵחִים. כֵּיוָן שֶׁכֻּלָּם שְׂמֵחִים, יוֹשֵׁב הַמֶּלֶךְ עַל הַכִּסֵּא, וְעוֹלֶה בְּשִׁבְעִים עֲנָפִים הַכִּסֵּא, כְּמוֹ שֶׁאָמַרְנוּ."],[3,"","וְאוֹתָן שְׁתֵּי הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, וּמְאִירוֹת וּמִתְעַטְּרוֹת כ\"ב אוֹתִיּוֹת (בכ\"ב אותיות), כְּלָל שֶׁל הַתּוֹרָה, מַכּוֹת בִּשְׁתֵּי הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת וְעוֹלוֹת לְאֶחָד בְּשִׁשָּׁה שְׁבָטִים, וּלְאֶחָד בְּשִׁשָּׁה שְׁבָטִים אֲחֵרִים, וְאֵלֶּה הֵם שְׁנֵים עָשָׂר שִׁבְטֵי יִשְׂרָאֵל הָעֶלְיוֹן."],[4,"","עוֹד, שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ (ראשונותעולות) עוֹלוֹת וְיוֹרְדוֹת וּמַכּוֹת בִּשְׁתֵּי אוֹתִיּוֹת שֶׁל סוֹף כ\"ב הָאוֹתִיּוֹת. וְעוֹלוֹת אַחַת בְּחָמֵשׁ דְּרָגוֹת, וְאַחַת בְּחָמֵשׁ דְּרָגוֹת. וְעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ (לתקן) לִכְלֹל לְכ\"ב אוֹתִיּוֹת. י\"ב שְׁבָטִים בִּשְׁתֵּי אוֹתִיּוֹת (ראשונות), כְּלָל שֶׁל הַתּוֹרָה וְעֶשֶׂר אֲמִירוֹת שֶׁל שְׁתֵּי הָאוֹתִיּוֹת שֶׁבַּסּוֹף - הֲרֵי כ\"ב אוֹתִיּוֹת שֶׁל סוֹף הַתּוֹרָה. וְסוֹד זֶה יוֹרֶשֶׁת הַמַּרְגָּלִית הָעֶלְיוֹנָה בְּאוֹתוֹ כִּסֵּא שֶׁל ע\"ב, וּמְאִירוֹת כ\"ב אוֹתִיּוֹת."],[5,"","הַמַּרְגָּלִית הַתַּחְתּוֹנָה, בְּשָׁעָה שֶׁיּוֹשֶׁבֶת הַמַּרְגָּלִית הָעֶלְיוֹנָה בְּאוֹתוֹ הַכִּסֵּא שֶׁל ע\"ב וּמְאִירוֹת כ\"ב אוֹתִיּוֹת, אָז אוֹתָהּ הַמַּרְגָּלִית הַתַּחְתּוֹנָה שֶׁהִיא בַּחֲשֵׁכָה מִסְתַּכֶּלֶת בְּאוֹתוֹ הָאוֹר, בְּכֹחַ שֶׁל תֹּקֶף שֶׁל אוֹתָן הָאוֹתִיּוֹת שֶׁנִּרְשְׁמָה בָהֶן, שֶׁנִּקְרְאוּ אֲדנָי, וְאָז מֵאִיר וְעוֹלֶה אוֹתוֹ הָאוֹר, וְנוֹטֵל כָּל אוֹתָן כ\"ב אוֹתִיּוֹת עֶלְיוֹנוֹת, וְשׁוֹאֶבֶת אוֹתָן אוֹתָהּ הַמַּרְגָּלִית לְתוֹכָהּ, וּמֵאִיר אוֹר שֶׁנּוֹצֵץ לְע\"ב עֲבָרִים."],[6,"","כֵּיוָן שֶׁהַמַּרְגָּלִית הַזּוֹ נוֹצֶצֶת וְשׁוֹאֶבֶת אֶת אוֹתָן הָאוֹתִיּוֹת עִמָּהּ, אָז הַמַּרְגָּלִית הָעֶלְיוֹנָה נִמְשֶׁכֶת עִמָּם, וְנִדְבֶּקֶת מַרְגָּלִית בְּמַרְגָּלִית, וְנִהְיָה הַכֹּל אֶחָד. וְזֶהוּ סוֹד אֶחָד שֶׁל הַתִּשְׁבַּחַת, וַהֲרֵי בֵּאַרְנוּ."],[7,"","כְּשֶׁהָאוֹתִיּוֹת נוֹצְצוֹת מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה, זֶהוּ הַיָּתֵד שֶׁבֵּינֵיהֶם, בֵּין מַרְגָּלִית לְמַרְגָּלִית, אָז נַעֲשׂוֹת סוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁל מ\"ב אוֹתִיּוֹת. וּבְכָל הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁל ע\"ב אוֹתִיּוֹת שֶׁל הַמֶּרְכָּבָה הָעֶלְיוֹנָה, וְהַכֹּל - זֶה וָזֶה - נִקְרֵאת שַׁבָּת, וְזֶהוּ סוֹד הַשַּׁבָּת. (ע\"כ רעיא מהימנא)"],[8,"","זָכוֹר - הוּא סוֹד שֶׁל זָכָר, סוֹד שֶׁל הַזָּכָר שֶׁלּוֹקֵחַ אֶת כָּל אֵיבְרֵי הָעוֹלָם הָעֶלְיוֹן. אֶת יוֹם הַשַּׁבָּת - לְרַבּוֹת עֶרֶב שַׁבָּת, שֶׁהוּא לַיְלָה. וְזֶהוּ אֶת. לְקַדְּשׁוֹ - שֶׁצָּרִיךְ קְדֻשָּׁה מִתּוֹךְ הָעָם הַקָּדוֹשׁ, וּלְהִתְעַטֵּר בָּהֶם כָּרָאוּי."],[9,"","זָכוֹר - מָקוֹם שֶׁאֵין בּוֹ שִׁכְחָה וְלֹא עוֹמֶדֶת בּוֹ שִׁכְחָה, שֶׁהֲרֵי אֵין שִׁכְחָה בַּמָּקוֹם שֶׁל הַבְּרִית הָעֶלְיוֹן, וְכָל שֶׁכֵּן לְמַעְלָה. וּלְמַטָּה יֵשׁ שִׁכְחָה, מָקוֹם שֶׁצָּרִיךְ לְהַזְכִּיר, וְעַל זֶה כָּתוּב (תהלים קט) יִזָּכֵר עֲוֹן אֲבתָיו וְגוֹ'. וְיֵשׁ שָׁם מְמֻנִּים שֶׁמַּזִכִּירִים זְכֻיּוֹת הָאָדָם וַחֲטָאָיו."],[10,"","וְאֵיןֹ שִׁכְחָה לִפְנֵי הַכִּסֵּא הַקָּדוֹשׁ מַה שֶּׁהוּא לְפָנָיו. וּמַה הוּא לְפָנָיו? זָכוֹר. וְכָל שֶׁכֵּן לְמַעְלָה. מִשּׁוּם שֶׁהַכֹּל הוּא סוֹד שֶׁל זָכָר, וְשָׁם נֶחְקָק סוֹד הַשֵּׁם הַקָּדוֹשׁ יה\"ו. וּלְמַטָּה צָרִיךְ לְהִתְקַדֵּשׁ. וּבַמָּה הִתְקַדֵּשׁ? בְּזָכוֹר, שֶׁהֲרֵי מִמֶּנּוּ נוֹטֵל כָּל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת. וְזֶה כְּשֶׁמִּתְעַטְּרִים עֶרֶב שַׁבָּת עַל הָעָם הַקָּדוֹשׁ כָּרָאוּי בִּתְפִלּוֹת וּבְבַקָּשׁוֹת וּבְסִדּוּר שֶׁל שִׂמְחָה."],[11,"","וְאִם תֹּאמַר, זָכוֹר לֹא צָרִיךְ לְהִתְקַדֵּשׁ, שֶׁהֲרֵי מִמֶּנּוּ יוֹצְאִים שֶׁל הַקְּדֻשּׁוֹת שֶׁל הָעוֹלָם - לֹא כָּךְ! שֶׁהֲרֵי זֶה צָרִיךְ לְהִתְקַדֵּשׁ בַּיּוֹם, וְזֶה צָרִיךְ לְהִתְקַדֵּשׁ בַּלַּיְלָה, וְכָל הַקִּדּוּשִׁים נוֹטְלִים אוֹתָם יִשְׂרָאֵל אַחַר כָּךְ, וּמִתְקַדְּשִׁים בַּקְּדֻשּׁוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["(שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ, בְּכָל זִינֵי יְקָר, לְמֶחדֵי לוֹן בְּעוֹבְדֵי דְּכַשְׁרָאָן, כְּמָה דְאַתְּ אָמֵר (משלי כ״ג:כ״ד) גִּיל יָגִיל אֲבִי צַדִּיק, וְדָא אִיהוּ יְקָרָא דַּאֲבוֹי וּדְאִמֵּיהּ.","\u0003רעיא מהימנא\u0004 כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ. כַּבְּדֵהוּ בִּכְסוּת נְקִיָּיה, דְּהַיינוּ כַּנְפֵי מִצְּוָה, (משלי ג׳:ט׳) כַּבֵּד אֶת ה' מֵהוֹנֶךָ, דָּא תּוֹרָה וּמִצְּוֹת. הֲדָא הוּא דִכְתִיב, (משלי ג׳:ט״ז) אוֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וגוֹ. דְּעָנִי לָאו אִיהוּ בַּר נָשׁ, אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְּוֹת, אִשְׁתְּמוֹדַע, דְּבָתַר דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין אֵין עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְּוֹת, דְּעֻתְרָא דְּבַר נָשׁ אוֹרַיְיתָא וּמִצְּוֹת.","וּבְגִין דָּא, כַּבֵּד אֶת יְיָ' מֵהוֹנֶךָ, ולָא תִּשְׁתַּדֵּל בְּאוֹרַיְיתָא, כְּדֵי לְהִתְגַּדֵּל בָּהּ. כְּמָה דְּאוּקְמוּהָ חַבְרַיָּיא, וְאַל תַּעֲשֵׂם עֲטָרָה לְהִתְגַּדֵּל בָּהֶם, ולא תֹאמַר אֶקְרָא בַּעֲבוּר שֶׁיִּקְרְאוּנִי רַבִּי, אֶלָּא (תהלים לה) גַּדְּלוּ לַיְיָ' אִתִּי. כַּבֵּד אֶת יְיָ' מֵהוֹנֶךָ, כְּבֵן דְּאִיהוּ חַיָּיב בִּיקָרַא דַּאֲבוֹי וְאִמֵּיהּ.","בְּגִין דְּאִיהוּ מְשׁוּתָּף מִתְּרֵין טִפִּין, דְּמִנְּהוֹן נוֹצַּר בַּר נָשׁ. מִטִפָּה דְּאַבוּהָ, חִוָּורוּ דְּעַיְינִין, וְגַרְמִין וְאֵבָרִין. וּמִטִפָּה דְּאִמֵּיהּ, שָׁחוֹר דִּי בְּעַיְינִין, וְשַׂעֲרָא וּמַשְׁכָא וּבִשְׂרָא. וְרַבִּיאוּ לֵיהּ בְּאוֹרַיְיתָא, וְעוֹבָדִין טָבִין.","דְּבַר נָשׁ חַיָּיב לְלַמֵּד בְּנוֹ תּוֹרָה, דִּכְתִּיב, (דברים ו׳:ז׳) וְשִׁנַּנְתָּם לְבָנֶיךָ. וְאִי לָא אוֹלִיף לֵיהּ אוֹרַיְיתָא וּפִקּוּדִין, כְּאִילּוּ עָבִיד לֵיהּ פֶּסֶל, וּבְגִין דָּא לֹא תַעֲשֶׂה לְךָ פֶסֶל. וְעָתִיד לִהְיוֹת בֵּן סוֹרֵר וּמוֹרֶה, וּמְבַזֶּה אָבוּי וְאִמֵּיהּ, וְגוֹזֵל מִנֵּיהּ כַּמָּה בִּרְכָּאן. דְּהוֹאִיל ואִיהוּ עַם הָאָרֶץ, חָשִׁיד אִיהוּ עַל כֹּלָּא, ואֲפִילּוּ עַל שְׁפִיכוּת דָּמִים, וְגִילוּי עֲרָיוֹת, וְעֲבוֹדָה זָרָה. דְּמַאן דְּאִיהוּ עַם הָאָרֶץ. וְאָזִיל לַאֲתָר דְּלָא אִשְׁתְּמוֹדְעוּן לֵיהּ, וְלָא יָדַע לְבָרְכָא, חַשְׁדִינָן לֵיהּ דְּאִיהוּ עוֹבְדֵי עֲבוֹדָה זָרָה. (ע\"כ רעיא מהימנא).","כַּבֵּד אֶת אָבִיךָ כְּמָה דְאַתְּ אָמֵר כַּבֵּד אֶת יְיָ' מֵהוֹנְךָ. מֵהוֹנֶךָ: מִמָּמוֹנֶךָ. מֵהוֹנֶךָ: מֵחִנְּךָ. בְּחֶדְוָה דְּנִגוּנָא, לְמֶחדֵי לִבָּא, דְּהָא דָּא חֶדְוָה דְּלִבָּא, כְּגַוְונָא דָּא נִגּוּנָא דְּכָל עָלְמָא. עוֹבָדִין דְּכַשְׁרָאָן דְּהַהוּא בְּרָא, חַדֵּי לִבָּא דְּאָבוּהָ וּדְאִמֵּיהּ. מֵהוֹנֶךָ, מִמָּמוֹנֶךָ לְכָל מַה דְּאִצְטְרִיכוּ.","כְּגַוְונָא דְּבַר נָשׁ אוֹקִיר לְקוּדְשָׁא בְּרִיךְ הוּא, הָכִי אִצְטְרִיךְ לְאַבָּא וּלְאִמָא, בְּגִין דְּשׁוּתָּפוּתָא חֲדָא אִית לוֹן בְּקוּדְשָׁא בְּרִיךְ הוּא עָלֵיהּ. וּכְמָה דְּאִצְטְרִיךְ לְמִדְחַל לְקוּדְשָׁא בְּרִיךְ הוּא, הָכִי אִצְטְרִיךְ לְמִדְחַל לְאָבוּהָ וּלְאִמֵּיהּ, וּלְאוֹקִיר לוֹן כַּחֲדָא, בְּכָל זִינֵי יְקָר.","לְמַעַן יַאֲרִיכוּן יָמֶיךָ, בְּגִין דְּאִית יוֹמִין לְעֵילָּא, דְּתַלְיָין בְּהוּ חַיֵּי בַּר נָשׁ בְּהַאי עָלְמָא. וְאוֹקִימְנָא עַל אִינּוּן יוֹמִין דְּבַר נָשׁ בְּהַהוּא עָלְמָא לְעֵילָּא, וְכֻלְּהוּ קַיְימִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּבְהוּ אִשְׁתְּמוֹדְעָן חַיֵּי דְּבַר נָשׁ.","עַל הָאֲדָמָה אֲשֶׁר יְיָ' אֱלהֶיךָ נוֹתֵן לָךְ. אַבְטָחוּתָא לְאִתְהַנְיָא בְּאַסְפָּקָלַרְיָא דְּנַהֲרָא, וְרָזָא דָּא עַל הָאֲדָמָה, דָּא אַסְפָּקָלַרְיָא דְּנַהֲרָא, בְּאִינּוּן יוֹמִין עִלָּאִין, דְּנָהֲרִין מִגּוֹ מַבּוּעָא דְּכֹלָּא.","מַאי שְׁנָא, בְּאִלֵּין תְּרֵין פִּקּוּדִין דְּאוֹרַיְיתָא, דִּכְתִּיב בְּהוּ לְמַעַן יַאֲרִיכוּן יָמֶיךָ, בְּדָא, וּבְשִׁלּוּחַ הַקֵּן. אֶלָּא תְּרֵין פִּקּוּדִין אִלֵּין, כֻּלְּהוּ תַּלְיָין לְעֵילָּא. אַבָּא וְאִמָא, רָזָא דְּזָכוֹר וְשָׁמוֹר כַּחֲדָא. וּבְגִינֵי כַּךְ כְּתִיב לְמַעַן יַאֲרִיכוּן יָמֶיךָ. וּבְשִׁלּוּחַ הַקֵּן, דִּכְתִּיב, (דברים כ״ב:ז׳) שַׁלַּח תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ לְמַעַן יִיטַב לָךְ וְגוֹ', רָזָא דְּעָלְמָא עִלָּאָה, דְּלָא אִתְיְיהִיב בֵּיהּ רְשׁוּ לְאִסְתַּכְּלָא, וְאִצְטְרִיךְ לְשַׁלֵּחַ מִגּוֹ שְׁאֵלְתָּא וְאִסְתַּכְּלוּתָא בֵּיהּ.","וְאֶת הַבָּנִים תִּקַּח לָךְ, דִּכְתִּיב, (דברים ד׳:ל״ב) כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגוֹ' מִקְּצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. אֲבָל לְעֵילָּא מִקְּצֵה הַשָּׁמַיִם, שַׁלַּח תְּשַׁלַּח מֵרַעְיוֹנֶיךָ לְמִשְׁאַל.","וּבְדָא כְּתִיב, לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים, לְמַעַן אִיטַב לָךְ לָא כְּתִיב, אֶלָּא לְמַעַן יִיטַב לָךְ. וְיַאֲרִיכוּן יָמֶיךָ לָא כְּתִיב, אֶלָּא וְהַאֲרַכְתָּ יָמִים. לְמַעַן יִיטַב לָךְ, הַהוּא אֲתָר דְּאוֹטִיב לְכֹלָּא, וְאִיהוּ עָלְמָא דְּסָתִים וְגָנִיז. וְהַאֲרַכְתָּ יָמִים, כְּמָה דִּכְתִּיב, תִּקַּח לָךְ, בִּרְשׁוּתָא דְּבַר נָשׁ אִיהוּ."],[[0,"כבד את אביך וגו':","לכבדם בכל מיני כבוד, לשמחם במעשים טובים. כמש\"א גיל יגיל אבי צדיק. וזה הוא כבוד אביו ואמו."],[1,"כבד את אביך וגו':","כבדהו את הקב\"ה שנקרא אביך והמלכות שנקראת אמך, בבגד נקי, שהוא כנפי מצוה, דהיינו טלית נאה. כי טלית בצצית נקרא, תשמיש מצוה. כבד את ה' מהונך, זה תורה ומצות, ז\"ש, אורך ימים בימינה בשמאלה וגו'. שאין אדם עני אלא כשהוא עני מן התורה ומן המצות. ונודע, אחר שהעמידו בעלי המשנה אין עני אלא מן התורה ומן המצות, אשר עושר של האדם הוא תורה ומצות."],[2,"ובגין דא כבד וכו':","ומשום זה, כבד את ה' מהונך, ולא תעסוק בתורה כדי להתגדל בה. כמו שהעמידוהו החברים, ואל תעשם עטרה להתגדל בהם. ואל תאמר, אקרא בעבור שיקראוני רבי, אלא גדלו לה' אתי, כבד את ה' מהונך, כבן שהוא חייב בכבוד אביו ואמו."],[3,"בגין דאיהו משותף וכו':","משום שהוא משותף משתי טפות, שמהן גופו של האדם. מטפה של אביו נעשה הלבן שבעינים ועצמות ואברים. ומטפה של אמו נעשה, השחור שבעין ושערות ועור ובשר. ומגדלים אותו בתורה ומעשים טובים."],[4,"דבר נש חייב וכו':","כי האדם חייב ללמד בנו תורה, שכתוב, ושננתם לבניך, ואם אינו לומד אותו תורה ומצות, הוא כאלו עושה לו פסל. ומשום זה כתוב, לא תעשה לך פסל. ועתיד להיות בן סורר ומורה, ומבזה אביו ואמו, וגוזל ממנו כמה ברכות. כי משום שהוא עם הארץ הוא חשוד על הכל, ואפילו על שפיכות דמים וגילוי עריות ועבודה זרה. כי מי שהוא עם הארץ והולך למקום שאין מכירים אותו, ואינו יודע לברך, חושדים אותו שהוא עובד עבודה זרה."],[5,"כבד את אביך:","הוא כש\"א, כבד את ה' מהונך. מהונך, היינו מכספך, \u0003מהונך,\u0004 היינו מחנך, מן החן שלך, דהיינו בשמחה של נגון. כי זה הוא שמחת הלב כמו הניגון שבכל העולם, המשמח את הלב, מעשים ישרים של הבן משמחים לב אביו ואמו. מהונך, היינו מכספך לכל מה שצריך."],[6,"כגוונא דבר נש וכו':","כמו שאדם מכבד את הקב\"ה, כן צריך לכבד את אביו ואמו, משום ששותפות אחד יש להם עם הקב\"ה, עליו. כי שלשה שותפין יש באדם, הקב\"ה ואביו ואמו, שאביו ואמו נותנים לו הגוף והקב\"ה הנשמה. וכמו שצריכים לירא מהקב\"ה, כן צריכים לירא מאביו ואמו, ולכבד אותם יחד בכל מיני כבוד."],[7,"למען יאריכון ימיך:","משום שיש ימים למעלה, שהם ז' הספירות חג\"ת נהי\"מ, שבהם תלוים חיי האדם בעולם הזה. ובארנו את אלו הימים של האדם בעולם ההוא, למעלה, בז\"ס, וכולם עומדים לפני הקב\"ה, ובהם נודע חיי האדם."],[8,"על האדמה אשר ה' וגו':","הוא הבטחה להנות באספקלריא המאירה, וזה סוד, \u0003על האדמה,\u0004 זהו מראה המאירה באלו ימים העליונים חג\"ת נהי\"מ דז\"א, המאירים מתוך המבוע של כל, שהיא בינה."],[9,"מאי שנא באלין וכו':","שואל, מה השינוי שבאלו שתי מצות התורה כתוב בהם למען יאריכון ימיך, בזה, ובשלוח הקן. ומשיב, אלא שתי מצות אלו, תלויות כולן למעלה: אבא ואמא, ה\"ס זכור ושמור כאחד, שהם ז\"א ומלכות, ומשום זה כתוב, למען יאריכון ימיך. ובשלוח הקן, שכתוב, שלח תשלח את האם וגו' ה\"ס עולם העליון, שהוא בינה שנקראת אם, שפירושו, שלא ניתנה רשות להסתכל בה, וצריכים לשלחה מלשאול שאלה ולהסתכל בה."],[10,"ואת הבנים תקח לך:","שהם ז\"א ומלכות, שכתוב, כי שאל נא לימים הראשונים וגו' מקצה השמים ועד קצה השמים, דהיינו ז\"א הנקרא שמים, בו יש שאלה והסתכלות, אבל למעלה מקצה השמים, שהוא ז\"א, שלח תשלח ממחשבתך לשאול."],[11,"ובדא כתיב למען וגו':","ובזה כתוב, למען ייטב לך והארכת ימים. למען איטב לך לא כתוב, אלא למען ייטב לך. ויאריכון ימיך לא כתוב, אלא והארכת ימים. ומשיב, \u0003למען ייטב לך,\u0004 היינו מקום ההוא שמטיב לכל, והוא עולם הסתום והגנוז, שהוא בינה. \u0003והארכת ימים,\u0004 היינו בכחך עצמך, כמ\"ש תקח לך, כי ברשות האדם הוא. להתדבק בבנים, שהם ז\"א ומלכות, שבהם אריכת ימים."]],[[0,"","כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, בְּכָל מִינֵי כָבוֹד, לְשַׂמְּחָם בְּמַעֲשִׂים כְּשֵׁרִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי כג) גִּיל יָגִיל אֲבִי צַדִּיק. וְזֶהוּ כְּבוֹד אָבִיו וְאִמּוֹ."],[1,"","כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. כַּבְּדֵהוּ בִּכְסוּת נְקִיָּה, דְּהַיְנוּ כַּנְפֵי מִצְוָה, כַּבֵּד אֶת ה' מֵהוֹנֶךְ, זוֹ תוֹרָה וּמִצְווֹת. זֶהוּ שֶׁכָּתוּב אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וְגוֹ'. שֶׁאֵין אָדָם עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְווֹת. נוֹדָע, אַחַר שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, אֵין עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְווֹת, שֶׁעָשְׁרוֹ שֶׁל אָדָם תּוֹרָה וּמִצְווֹת. וּמִשּׁוּם כָּךְ כַּבֵּד אֶת אָבִיךְ מֵהוֹנֶךְ,"],[2,"","וּבְגִין דָּא, פַבֵּד אֶת יְיָ' מֵהוֹנֶךָ, וְלָא תִשְׁתַּדֵּל בְּאוֹדַיְיתָא, פְדֵי לְהִתְגַּדֵּל בָּהּ. פְמָה דְאוּקְמוּהָ וְאַל תִּשְׁתַּדֵּל בַּתּוֹרָה כְּדֵי לְהִתְגַּדֵּל בָּהּ, כְּמוֹ שֶׁבֵּאֲרוּהָ הַחֲבֵרִים, וְאַל תַּעֲשֵׂם עֲטָרָה לְהִתְגַּדֵּל בָּהֶם, וְלֹא תֹאמַר אֶקְרָא בַּעֲבוּר שֶׁיִּקְרְאוּנִי רַבִּי, אֶלָּא (תהליםלד) גַּדְּלוּ לַה' אִתִּי. כַּבֵּד אֶת ה' מֵהוֹנֶךְ, כְּבֵן שֶׁחַיָּב בִּכְבוֹד אָבִיו וְאִמּוֹ."],[3,"","מִשּׁוּם שֶׁהוּא מְשֻׁתָּף מִשְּׁתֵּי טִפּוֹת שֶׁמֵּהֶן נוֹצָר הָאָדָם. מֵהַטִּפָּה שֶׁל אָבִיו לֹבֶן הָעֵינַיִם, וַעֲצָמוֹת וְאֵיבָרִים. וּמִטִּפָּה שֶׁל אִמּוֹ הַשָּׁחֹר שֶׁבָּעַיִן, וְשֵׂעָר וְעוֹר וּבָשָׂר. וּמְגַדְּלִים אוֹתוֹ בַּתּוֹרָה וּמַעֲשִׂים טוֹבִים."],[4,"","שֶׁאָדָם חַיָּב לְלַמֵּד בְּנוֹ תּוֹרָה, שֶׁכָּתוּב (דברים ו) וְשִׁנַּנְתָּם לְבָנֶיךְ. וְאִם לֹא לִמֵּד אוֹתוֹ תּוֹרָה וּמִצְווֹת, כְּאִלּוּ עָשָׂה לוֹ פֶּסֶל, וּמִשּׁוּם כָּךְ לֹא תַעֲשֶׂה לְךְ פֶסֶל. וְעָתִיד לִהְיוֹת בֵּן סוֹרֵר וּמוֹרֶה וּמְבַזֶּה אָבִיו וְאִמּוֹ וְגוֹזֵל מִמֶּנּוּ כַּמָּה בְרָכוֹת. שֶׁהוֹאִיל וְהוּא עַם הָאָרֶץ, הוּא חָשׁוּד עַל הַכֹּל, וַאֲפִלּוּ עַל שְׁפִיכוּת דָּמִים וְגִלּוּי עֲרָיוֹת וַעֲבוֹדָה זָרָה. שֶׁמִּי שֶׁהוּא עַם הָאָרֶץ וְהוֹלֵךְ לְמָקוֹם שֶׁאֵין מַכִּירִים אוֹתוֹ וְלֹא יוֹדֵעַ לְבָרֵךְ, חוֹשְׁדִים אוֹתוֹ שֶׁהוּא עוֹבֵד עֲבוֹדָה זָרָה. (ע\"כ רעיא מהימנא)"],[5,"","כַּבֵּד אֶת אָבִיךְ, כְּמוֹ שֶׁנֶּאֱמַר כַּבֵּד אֶת ה' מֵהוֹנֶךְ. מֵהוֹנֶךְ - מִמָּמוֹנְךְ. מֵהוֹנֶךְ - מֵחִנְּךְ. בְּשִׂמְחַת הַנִּגּוּן לְשַׂמֵּחַ הַלֵּב, שֶׁהֲרֵי זוֹ שִׂמְחַת הַלֵּב, כְּמוֹ זֶה הַנִּגּוּן שֶׁל כָּל הָעוֹלָם. מַעֲשִׂים כְּשֵׁרִים שֶׁל אוֹתוֹ בֵּן מְשַׂמֵּחַ לֵב אָבִיו וְאִמּוֹ. מֵהוֹנֶךְ - מִמָּמוֹנְךְ לְכָל מַה שֶּׁצְּרִיכִים."],[6,"","כְּמוֹ שֶׁהָאָדָם מְכַבֵּד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּךְ צָרִיךְ לְכַבֵּד אָב וָאֵם, מִשּׁוּם שֶׁיֵּשׁ לָהֶם שֻׁתָּפוּת אַחַת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו. וּכְמוֹ שֶׁצָּרִיךְ לִפְחֹד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, כָּךְ צָרִיךְ לִירָא מֵאָבִיו וְאִמּוֹ וּלְכַבְּדָם כְּאֶחָד בְּכָל מִינֵי כָבוֹד."],[7,"","לְמַעַן יַאֲרִיכוּן יָמֶיךְ, מִשּׁוּם שֶׁיֵּשׁ יָמִים לְמַעְלָה שֶׁתְּלוּיִים בָּהֶם חַיֵּי הָאָדָם בָּעוֹלָם הַזֶּה. וּבֵאַרְנוּ עַל אוֹתָם יָמִים שֶׁל אָדָם לְמַעְלָה בְּאוֹתוֹ הָעוֹלָם, וְכֻלָּם עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָהֶם נוֹדָעִים חַיֵּי הָאָדָם."],[8,"","עַל הָאֲדָמָה אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ. הַבְטָחָה לֵהָנוֹת בְּאַסְפַּקְלַרְיָה הַמְּאִירָה, וְסוֹד זֶה עַל הָאֲדָמָה, זוֹ אַסְפַּקְלַרְיָה הַמְּאִירָה, בְּאוֹתָם הַיָּמִים הָעֶלְיוֹנִים שֶׁמְּאִירִים מִתּוֹךְ הַמַּעְיָן שֶׁל הַכֹּל."],[9,"","מַה שּׁוֹנֶה בִּשְׁתֵּי הַמִּצְווֹת הַלָּלוּ שֶׁל הַתּוֹרָה שֶׁכָּתוּב בָּהֶן לְמַעַן יַאֲרִיכוּן יָמֶיךְ, בָּזֶה וּבְשִׁלּוּחַ הַקֵּן? אֶלָּא שְׁתֵּי מִצְווֹת אֵלֶּה כֻּלָּן תְּלוּיוֹת לְמַעְלָה. אָב וָאֵם, סוֹד שֶׁל זָכוֹר וְשָׁמוֹר כְּאֶחָד, וּמִשּׁוּם כָּךְ כָּתוּב לְמַעַן יַאֲרִיכוּן יָמֶיךְ. וּבְשִׁלּוּחַ הַקֵּן, שֶׁכָּתוּב (שם כב) שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ לְמַעַן יִיטַב לָךְ וְגוֹ'. הַסּוֹד שֶׁל עוֹלָם הָעֶלְיוֹן שֶׁלֹּא נִתְּנָה רְשׁוּת לְהִסְתַּכֵּל בּוֹ, וְצָרִיךְ לְשַׁלֵּחַ מִתּוֹךְ שְׁאֵלָה וְהִתְבּוֹנְנוּת בּוֹ."],[10,"","וְאֶת הַבָּנִים תִּקַּח לָךְ, שֶׁכָּתוּב (שם ד) כי שאל נא לימים ראשנים וגו' (ול) מקצה השמים ועד קצה השמים. אבל למעלה מקצה השמים, שלח תשלח מרעיוניך לשאל."],[11,"","וּבָזְהִ כָּתוּב לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים. לֹא כָתוּב לְמַעַן אֵיטִיב לָךְ, אֶלָּא לְמַעַן יִיטַב לָךְ. וְלֹא כָתוּב יַאֲרִיכוּן יָמֶיךְ, אֶלָּא וְהַאֲרַכְתָּ יָמִים. לְמַעַן יִיטַב לָךְ - אוֹתוֹ הַמָּקוֹם שֶׁמֵּיטִיב לָכֹּל, וְהוּא הָעוֹלָם הַגָּנוּז וְהַנִּסְתָּר. וְהַאֲרַכְתָּ יָמִים - כְּמוֹ שֶׁכָּתוּב תִּקַּח לָךְ, זֶהוּ בִּרְשׁוּתוֹ שֶׁל הָאָדָם."]]],[["וְאִי אִזְדָּמַן לֵיהּ עוֹבָדָא וִיכַוֵּון בֵּיהּ, זַכָּאָה אִיהוּ. וְאַף עַל גַּב דְּלָא מְכַוֵּין בֵּיהּ, זַכָּאָה אִיהוּ, דְּעָבִיד פִּקּוּדָא דְּמָרֵיהּ. אֲבָל לָא אִתְחַשִׁיב כְּמַאן דְּעָבִיד רְעוּתָא לִשְׁמָהּ, וִיכַוֵּין בֵּיהּ, בִּרְעוּתָא דְּאִסְתַּכְּלוּתָא בִּיקָרֵא דְּמָרֵיהּ, כְּמַאן דְּלָא יָדַע לְמִסְבַּר סְבָרָא, דְּהָא בִּרְעוּתָא תַּלְיָא מִלָּה לִשְׁמָהּ. וּבְעוֹבָדָא דִּלְתַתָּא לִשְׁמָהּ, אִסְתַּלָּק עוֹבָדָא לְעֵילָּא, וְאִתְתָּקַּן כַּדְקָא יֵאוֹת.","כְּגַוְונָא דָּא, בְּעוֹבָדָא דְּגוּפָא, אִתְתָּקַּן עוֹבָדָא דְּנַפְשָׁא, בְּהַהוּא רְעוּתָא. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לִבָּא, וּרְעוּתָא דְּבַר נָשׁ. וַאֲפִילּוּ הָכִי, אִי לָאו תַּמָּן רְעוּתָא דְּלִבָּא דְּאִיהוּ עִקָרָא דְּכֹלָּא, עַל דָּא צַלֵּי דָּוִד וְאָמַר, (תהילים צ׳:י״ז) וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ וְגוֹ'. דְּהָא לֵית כָּל בַּר נָשׁ חַכִּים, לְשַׁוָּאָה רְעוּתָא וְלִבָּא, לְתַקְּנָא כֹּלָּא וְיַעְבִיד עוֹבָדָא דְּמִצְוָה. עַל דָּא צַלֵּי צְלוֹתָא דָּא, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ.","מַאי כּוֹנְנָה עָלֵינוּ. כּוֹנְנָה, וְאַתְקִין תִּקּוּנָךְ לְעֵילָּא כַּדְקָא יֵאוֹת. עָלֵינוּ, אַף עַל גַּב דְּלֵית אֲנָן יַדְעֵי לְשַׁוָּאָה רְעוּתָא, אֶלָּא עוֹבָדָא בִּלְחוֹדוֹי. מַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ. לְמַאן. לְהַהוּא דַּרְגָּא דְּאִצְטְרִיךְ לְאִתְתַּקְנָא. כּוֹנְנֵהוּ, בְּחִבּוּרָא חֲדָא בַּאֲבָהָן, לְמֶהֱוֵי מְתַּתְקְנָא בְּהוֹן, בְּהַאי עוֹבָדָא, כְּדְקָא יֵאוֹת.","(שמות כ) לא תִּרְצַח. לֹא תִּנְאַף. לא תִּגְנֹב. לא. פָּסְקָא טַעֲמָא בְּכָל הָנִי תְּלָת. וְאִי לָא דְּפָסְקָא טַעֲמָא, לָא הֲוֵי תִּקּוּנָא לְעָלְמִין, וִיְהֵא אָסִיר לָן לְקָטְלָא נַפְשָׁא בְּעָלְמָא, אַף עַל גַּב דְּיַעֲבוֹר עַל אוֹרַיְיתָא. אֲבָל בְּמָה דְּפָסְקָא טַעֲמָא, אָסִיר, וְשָׁרֵי.","לֹא תִּנְאַף. אִי לָאו דְּפָסְקָא טַעֲמָא, אָסִיר אֲפִילּוּ לְאוֹלָדָא, אוֹ לְמֶחדֵי בְּאִתְּתֵיהּ חֶדְוָה דְּמִצְוָה. וּבַמֶּה דְּפָסְקָא טַעֲמָא, אָסִיר וְשָׁרֵי. לֹא תִּגְנֹב. אִי לָאו דְּפָסְקָא טַעֲמָא, הֲוָה אָסִיר אֲפִילּוּ לְמִגְנַב דַּעְתָּא דְּרַבֵּיהּ בְּאוֹרַיְיתָא. אוֹ דַּעְתָּא דְּחָכָם, לְאִסְתַּכְּלָא בֵּיהּ. אוֹ דַּיָּינָא דְּדָאִין דִּינָא לְפוּם טַעֲנָה, דְּאִצְטְרִיךְ לֵיהּ לְמִגְנַב דַּעְתָּא דְּרַמָּאָה, וּלְמִגְנַב דַּעְתָּא דְּתַרְוַויְיהוּ, לְאַפָּקָא דִּינָא לִנְהוֹרָא. וּבַמֶּה דְּפָסְקָא טַעֲמָא, אָסִיר וְשָׁרֵי.","(שמות כ׳:י״ג) לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר. הָכָא לָא פָּסְקָא טַעֲמָא, בְּגִין דְּאָסִיר הוּא כְּלָל כְּלָל. וּבְכָל מִילֵי דְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא שָׁוִי רָזִין עִלָּאִין, וְאוֹלִיף לִבְנֵי נָשָׁא אָרְחָא, לְאִתְתַּקְנָא בָּהּ, וּלְמֵהַךְ בָּהּ. כְּמָה דְּאַתְּ אָמֵר, (ישעיהו מ״ח:י״ז) אֲנִי יְיָ' אֱלֹהֶיךָ מְלַמֶּדְךָ לְהוֹעִיל מַדְרִיכְךָ בְּדֶרֶך תֵּלֵךְ.","אוּף הָכִי, (שמות כ) לֹא תַחְמֹד, לָא פָּסִיק טַעֲמָא כְּלָל. וְאִי תֵּימָא, אֲפִילּוּ חִמּוּדָא דְּאוֹרַיְיתָא אָסִיר, כֵּיוָן דְּלָא פָּסְקָא. תָּא חֲזֵי, בְּכֻלְּהוּ עַבְדַת אוֹרַיְיתָא כְּלָל, וּבְהַאי עַבְדַת פְּרָט. בֵּית רֵעֶךָ שָׂדֵהוּ וְעָבְדוֹ וְגוֹ', בְּכָל מִילֵי דְּעָלְמָא. אֲבָל אוֹרַיְיתָא, אִיהִי חָמוּדַת תָּדִיר, שַׁעֲשׁוּעִים, גִּנְזֵי דְּחַיֵּי, אַרְכָּא דְּיוֹמִין, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","הָנֵי עֶשֶׂר אֲמִירָן דְּאוֹרַיְיתָא, אִינּוּן כְּלָלָא דְּכָל פִּקּוּדֵי אוֹרַיְיתָא, כְּלָלָא דְּעֵילָּא וְתַתָּא, כְּלָלָא דְּכָל עֶשֶׂר אֲמִירָן דִּבְרֵאשִׁית. אִלֵּין אִתְחְקָקוּ עַל לוּחֵי אֲבָנִין, וְכָל גִּנְזִין דַּהֲווֹ בְּהוּ, אִתְחָזוּן לְעֵינֵיהוֹן דְּכֹלָּא, לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּרָזָא דְּתרי\"ג פִּקּוּדִין דְּאוֹרַיְיתָא דִּכְלִילָן בְּהוּ, כֹּלָּא אִתְחָזֵי לְעַיְינִין, כֹּלָּא אִיהוּ בְּסָכְלְתָנוּ, לְאִסְתַּכְּלָא בְּלִבָּא דְּיִשְׂרָאֵל כֻּלְּהוּ, וְכֹלָּא הֲוָה נָהִיר לְעֵינַיְיהוּ.","בְּהַהוּא שַׁעֲתָא, כָּל רָזִין דְּאוֹרַיְיתָא, וְכָל רָזִין עִלָּאִין וְתַתָּאִין, לָא אַעְדֵּי מִינַיְיהוּ. בְּגִין דַּהֲווֹ חָמָאן עֵינָא בְּעֵינָא, זִיו יְקָרָא דְמָרִיהוֹן, מַה דְּלָא הֲוָה כְּהַהוּא יוֹמָא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי בִּיקָרֵיהּ עַל טוּרָא דְּסִינַי."],[[0,"ואי אזדמן ליה וכו':","ואם מזדמן לו מעשה של מצוה ומכוון בה הוא צדיק. ואע\"פ שאינו מכוון בה הוא צדיק, שעושה מצות רבונו, כי מצוות אין צריכות כונה. אבל אינו חשוב כמי שעושה רצונו לשמה, ומכוון בה ברצון של הסתכלות בכבוד רבונו, כמי שאינו יודע להבין הטעם, כי ברצון תלוי הדבר של לשמה. ובמעשה שלמטה שעושה לשמה מתעלה המעשה של מעלה, שהוא המלכות הנקרא מעשה, ומתתקן כראוי."],[1,"כגוונא דא בעובדא וכו':","כעין זה במעשה של הגוף נתתקן ברצון הזה המעשה של הנפש. כי הקב\"ה רוצה הלב והרצון של האדם. ועם זה, אם אין שם רצון הלב שהוא עיקר הכל, התפלל דוד על זה ואמר, ומעשה ידינו כוננה עלינו וגו'. כי אין כל אדם יודע לשים הרצון והלב לתקן הכל ולעשות מעשה המצוה, וע\"כ התפלל תפלה זו, ומעשה ידינו כוננה עלינו."],[2,"מאי כוננה עלינו וכו':","שואל, מהו הפירוש של וכוננה עלינו. ומשיב, שפירושו \u0003כוננה,\u0004 והתקן תקונך למעלה כראוי. \u0003עלינו,\u0004 אף על פי שאין אנו יודעים לשים הרצון, אלא מעשה בלבד. \u0003מעשה ידינו כוננהו.\u0004 שואל, למי. ומשיב, למדרגה ההוא שצריכים לתקנה, דהיינו המלכות, \u0003כוננהו,\u0004 שיהיה בחבור אחד עם האבות, שהם חג\"ת דז\"א, שיהיה מתוקן בהם על ידי מעשה מצוה הזו כראוי."],[3,"לא תרצח לא תנאף לא תגנוב:","תחת לא. יש טעם הפוסק, בכל שלשה דברות אלו, דהיינו טפחה. ואם לא היה טעם הפוסק, לא היה תקון לעולם, והיה אסור לנו להרוג נפש בעולם אע\"פ שיעבור על התורה, אבל במה שיש טעם הפוסק, יורה שאסר והתיר."],[4,"לא תנאף:","אם לא היה טעם הפוסק, היה אסור אפילו להוליד או לשמוח באשתו שמחת מצוה. ובמה שהטעם פסק, יורה שאסר והתיר. \u0003לא תגנוב,\u0004 אם לא היה טעם הפוסק, היה אסור אפילו לגנוב דעתו של רבו בתורה או דעת חכם כדי להסתכל בו, או דיין הדן דין לפי טענה שצריך לגנוב דעת הרמאי, ולגנוב דעת שני הבעל דינים כדי להוציא הדין לאור, ובמה שפסק הטעם, יורה שאסר והתיר."],[5,"לא תענה ברעך עד שקר:","כאן אין טעם הפוסק, משום שהוא אסור לגמרי. ובכל דברי התורה שם הקב\"ה סודות עליונים, ולימד לבני אדם הדרך להתתקן בה, וללכת בה, כש\"א, אני ה' אלקיך מלמדך להועיל מדריכך בדרך תלך."],[6,"אוף הכי לא תחמוד:","אף לא תחמוד, אין טעם הפוסק, כלל. ואם תאמר, אפילו חמדת התורה אסור, כיון שאין טעם הפוסק, בוא וראה בכולם עשתה התורה כלל, ובזה עשתה פרט, שכתוב, בית רעך שדהו ועבדו וגו'. דהיינו בכל דברי העולם דוקא. אבל התורה היא חמודה תמיד, שעשועים אוצרות חיים, אריכת ימים בעולם הזה ובעולם הבא."],[7,"הני עשר אמירן וכו':","אלו עשרת הדברות של התורה, הם כלל של כל מצות התורה, כלל שלמעלה ומטה, כלל של עשרה מאמרות של בראשית. אלו נחקקו על לוחות אבנים, וכל האוצרות שהיו בהם, נראו לעיני הכל, לדעת ולהסתכל בסוד תרי\"ג מצות התורה הכלולים בהם, הכל נראה לעינים, הכל הוא בתבונה, בהסתכלות הלב של כל ישראל, והכל היה מאיר לעיניהם."],[8,"בההוא שעתא וכו':","בשעה ההיא, כל סודות התורה וכל סודות העליונים והתחתונים לא נחסר מהם. משום שהיו רואים עין בעין זיו יקר של אדונם, מה שלא היה כיום ההוא, מיום שנברא העולם, שהקב\"ה נגלה בכבודו על הר סיני."]],[[0,"","וְאִם יִזְדַּמֵּן לוֹ מַעֲשֶׂה וִיכַוֵּן בּוֹ, צַדִּיק הוּא. וְאַף עַל גַּב שֶׁלֹּא מְכַוֵּן בּוֹ, צַדִּיק הוּא, שֶׁעוֹשֶׂה מִצְוַת אֲדוֹנוֹ. אֲבָל לֹא נֶחְשָׁב כְּמִי שֶׁעָשָׂה רְצוֹנוֹ לִשְׁמָהּ, וִיכַוֵּן בּוֹ בְּרָצוֹן שֶׁל הִסְתַּכְּלוּת בִּכְבוֹד רִבּוֹנוֹ, כְּמִי שֶׁלֹּא יוֹדֵעַ לִסְבֹּר סְבָרָא, שֶׁהֲרֵי בְּרָצוֹן תָּלוּי הַדָּבָר לִשְׁמוֹ. וּבְמַעֲשֶׂה שֶׁלְּמַטָּה לִשְׁמוֹ, מִתְעַלֶּה הַמַּעֲשֶׂה לְמַעְלָה וּמִתְתַּקֵּן כָּרָאוּי."],[1,"","כְּמוֹ זֶה בְּמַעֲשֶׂה שֶׁל הַגּוּף נִתְקָן מַעֲשֵׂה הַנֶּפֶשׁ בְּאוֹתוֹ הָרָצוֹן, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה אֶת הַלֵּב וְהָרָצוֹן שֶׁל הָאָדָם, וַאֲפִלּוּ כָּךְ, אִם אֵין שָׁם רָצוֹן שֶׁל הַלֵּב, שֶׁהוּא עִקַּר הַכֹּל, עַל זֶה הִתְפַּלֵּל דָּוִד וְאָמַר, (תהליםצא) וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ וְגוֹ'. שֶׁהֲרֵי אֵין כָּל אָדָם חָכָם לָשִׂים רָצוֹן וְלֵב לְתַקֵּן הַכֹּל וְיַעֲשֶׂה מַעֲשֶׂה שֶׁל מִצְוָה. עַל זֶה הִתְפַּלֵּל תְּפִלָּה זוֹ - וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ."],[2,"","מַה זֶּה כּוֹנְנָה עָלֵינוּ? כּוֹנְנָה וְהַתְקֵן תִּקּוּנְךְ לְמַעְלָה כָּרָאוּי. עָלֵינוּ, אַף עַל גַּב שֶׁאֵינֶנּוּ יוֹדְעִים לָשִׂים הָרָצוֹן, אֶלָּא הַמַּעֲשֶׂה לְבַדּוֹ. מַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ, לְמִי? לְאוֹתָהּ דַּרְגָּה שֶׁצָּרִיךְ לְהִתַּקֵּן. כּוֹנְנֵהוּ, אֶת מִי? בְּחִבּוּר אֶחָד בָּאָבוֹת, לִהְיוֹת מְתֻקָּן בָּהֶם בַּמַּעֲשֶׂה הַזֶּה כָּרָאוּי."],[3,"","לֹא תִרְצַח. לֹא תִנְאָף. לֹא תִגְנֹב. לֹא - יֵשׁ טַעַם מַפְסִיק בְּכָל שְׁלֹשֶׁת אֵלֶּה. וְאִם לֹא הָיָה טַעַם מַפְסִיק, לֹא הָיָה תִקּוּן לָעוֹלָמוֹת, וְיִהְיֶה אָסוּר לָנוּ לַהֲרֹג נֶפֶשׁ בָּעוֹלָם, אַף עַל גַּב שֶׁיַּעֲבֹר עַל הַתּוֹרָה. אֲבָל בְּמַה שֶּׁיֵּשׁ הֶפְסֵק טַעַם - אָסוּר וּמֻתָּר."],[4,"","לֹא תִנְאָף - אִם לֹא טַעַם מַפְסִיק, אָסוּר אֲפִלּוּ לְהוֹלִיד אוֹ לִשְׂמֹחַ בְּאִשְׁתּוֹ שִׂמְחַת מִצְוָה, וּבְמַה שֶּׁהַטַּעַם מַפְסִיק - אָסוּר וּמֻתָּר. לֹא תִגְנֹב - אִם לֹא הָיָה טַעַם מַפְסִיק, הָיָה אָסוּר אֲפִלּוּ לִגְנֹב דַּעַת שֶׁל רַבּוֹ בַּתּוֹרָה אוֹ דַעַת שֶׁל חָכָם כְּדֵי לְהִתְבּוֹנֵן בָּהּ, אוֹ דַיָּן שֶׁדָּן דִּין לְפִי טַעֲנָה שֶׁצָּרִיךְ לִגְנֹב אֶת דַּעַת הָרַמַּאי, וְלִגְנֹב אֶת דַּעַת שְׁנֵיהֶם כְּדֵי לְהוֹצִיא אֶת הַדִּין לָאוֹר. וּבְמַה שֶּׁמַּפְסִיק הַטַּעַם - אָסוּר וּמֻתָּר."],[5,"","לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. כָּאן לֹא מַפְסִיק טַעַם, מִשּׁוּם שֶׁזֶּה אָסוּר כְּלָל וּכְלָל, וּבְכָל דִּבְרֵי הַתּוֹרָה שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹדוֹת עֶלְיוֹנִים, וְלִמֵּד בְּנֵי אָדָם דֶּרֶךְ לְהִתְתַּקֵּן בָּהּ וְלָלֶכֶת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מח) אֲנִי ה' אֱלֹהֶיךְ מְלַמֶּדְךְ לְהוֹעִיל מַדְרִיכְךְ בְּדֶרֶךְ תֵּלֵךְ."],[6,"","אַף כָּאן לֹא תַחְמֹד, לֹא מַפְסִיק טַעַם כְּלָל. וְאִם תֹּאמַר, אֲפִלּוּ חִמּוּד שֶׁל הַתּוֹרָה אָסוּר, כֵּיוָן שֶׁלֹּא מַפְסִיק הַטַּעַם? בֹּא וּרְאֵה, בְּכֻלָּם עָשְׂתָה הַתּוֹרָה כְּלָל, וּבָזֶה עָשְׂתָה פְּרָט. בֵּית רֵעֶךְ שָׂדֵהוּ וְעַבְדּוֹ וְגוֹ', בְּכָל דִּבְרֵי הָעוֹלָם. אֲבָל הַתּוֹרָה הִיא תָּמִיד חוֹמְדִים אוֹתָהּ, שַׁעֲשׁוּעִים, גִּנְזֵי חַיִּים, אֹרֶךְ הַיָּמִים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[7,"","עָשֶׂר הָאֲמִירוֹת הַלָּלוּ שֶׁל הַתּוֹרָה הֵן כְּלָל שֶׁל כָּל מִצְווֹת הַתּוֹרָה, כְּלָל שֶׁל מַעְלָה וְשֶׁל מַטָּה, כְּלָל שֶׁל כָּל עֶשֶׂר הָאֲמִירוֹת שֶׁל בְּרֵאשִׁית. אֵלֶּה נֶחְקְקוּ עַל לוּחוֹת אֲבָנִים, וְכָל הַגְּנָזִים שֶׁהָיוּ בָהֶם נִרְאוּ לְעֵינֵי כֹל, לָדַעַת וּלְהִסְתַּכֵּל בַּסּוֹד שֶׁל תַּרְיַ\"ג הַמִּצְווֹת שֶׁל הַתּוֹרָה שֶׁכְּלוּלִים בָּהֶם, הַכֹּל נִרְאֶה לָעֵינַיִם, הַכֹּל הוּא בִּתְבוּנָה, לְהִתְבּוֹנֵן בַּלֵּב שֶׁל כָּל יִשְׂרָאֵל, וְהַכֹּל הָיָה מֵאִיר לְעֵינֵיהֶם."],[8,"","בְּאוֹתָהּ שָׁעָה כָּל סוֹדוֹת הַתּוֹרָה וְכָל הַסּוֹדוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים לֹא זָזוּ מֵהֶם, מִשּׁוּם שֶׁהָיוּ רוֹאִים עַיִן בְּעַיִן אֶת זִיו כְּבוֹד רִבּוֹנָם - מַה שֶּׁלֹּא הָיָה כְּמוֹ אוֹתוֹ הַיּוֹם מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה בִּכְבוֹדוֹ עַל הַר סִינַי."]]],[["וְאִי תֵּימָא, הָא תָּנֵינָן דְּחָמָאת שִׁפְחָה עַל הַיָּם, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה, יָכוֹל כְּהַהוּא יוֹמָא דְּקָאִימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי. לָאו הָכִי. בְּגִין דְּהַהוּא יוֹמָא דְּקַיְימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי, אַעְבַּר זוּהֲמָא מִנַּיְיהוּ, וְכָל גּוּפִין הֲווֹ מְצַחְצְחָן, כְּצַחְצְחָא דְּמַלְאָכִין עִלָּאִין, כַּד מִתְלַבְּשָׁן בִּלְבוּשֵׁי מְצַחְצְחָן, לְמֶעְבַּד שְׁלִיחוּתָא דְמָרֵיהוֹן.","וּבְהַהוּא מַלְבּוּשָׁא מְצַחְצְחָא, עָאלִין לְאֶשָּׁא, וְלָא דַּחֲלִין. כְּגַוְונָא דְּהַהוּא מַלְאָכָא דְּמָנוֹחַ, כַּד אִתְחָזֵי לֵיהּ, וְעָאל בְּשַׁלְהוֹבָא, וְסָלִיק לִשְׁמַיָּא, דִּכְתִּיב, (שופטים י״ג:כ׳) וַיַּעַל מַלְאַךְ יְיָ' בְּלַהַב הַמִּזְבֵּחַ. וְכַד אַעְבָּר מִינַיְיהוּ הַהוּא זוּהֲמָא, אִשְׁתָּאֲרוּ יִשְׂרָאֵל גּוּפִין מְצוּחְצָחִין בְּלֹא טִנּוּפָא כְּלָל, וְנִשְׁמָתִין לְגוֹ כְּזוֹהֲרָא דִּרְקִיעָא, לְקַבְּלָא נְהוֹרָא.","הָכִי הֲווֹ יִשְׂרָאֵל, דַּהֲווֹ חָמָאן וּמִסְתַּכְּלָן גּוֹ יְקָרָא דְמָרִיהוֹן, מַה דְּלָא הֲוִי הָכִי עַל יַמָּא, דְּלָא אִתְעֲבָר זוּהֲמָא מִנַּיְיהוּ בְּהַהוּא זִמְנָא. וְהָכָא בְּסִינַי דְּפָסְקָא זוּהֲמָא מִגּוּפָא, אֲפִילּוּ עוּבָּרִין דְּבִמְעֵי אִמָן, הֲווֹ חָמָאן וּמִסְתַּכְּלָן בִּיקָרֵא דְמָרֵיהוֹן. וְכֻלְּהוּ קַבִּילוּ כָּל חַד וְחַד, כַּדְקָא חֲזִי לֵיהּ.","וְהַהוּא יוֹמָא, הֲוָה חֶדְוָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, יַתִּיר מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, בְּגִין דְּיוֹמָא דְּאִתְבְּרֵי עָלְמָא, לָא הֲוָה בְּקִיּוּמָא, עַד דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא, דִּכְתִּיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וְלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שַׂמְתִּי.","כֵּיון דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא עַל טוּרָא דְּסִינַי, כְּדֵין אִתְבַּסַּם עָלְמָא, וְאִתְקְיָימוּ שְׁמַיָּא וְאַרְעָא, וְאִשְׁתְּמוֹדָע קוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא, וְאִסְתַּלָּק בִּיקָרֵיהּ עַל כֹּלָּא. וְעַל הַהוּא יוֹמָא כְּתִיב (תהילים צ״ג:א׳) יְיָ' מָלַךְ גֵּאוּת לָבֵשׁ לָבֵשׁ יְיָ' עֹז הִתְאַזָּר. וְאֵין עֹז, אֶלָּא תּוֹרָה. שֶׁנֶּאֱמַר (תהילים כ״ט:י״א) יְיָ' עֹז לְעַמּוֹ יִתֵּן יְיָ' יְבָרֵךְ אֶת עַמּוֹ בְּשָׁלוֹם."],[[0,"ואי תימא הא וכו':","ואם תאמר, הרי למדנו, ראתה שפחה על הים מה שלא ראה יחזקאל הנביא. אתה יכול לומר, שהיה כיום ההוא שעמדו ישראל על הר סיני, אינו כן. משום שביום ההוא שעמדו ישראל על הר סיני. הוסר הזוהמא מהם, וכל הגופים היו מצוחצחים בצחות מלאכים העליונים, כשמתלבשים בלבושי צחצחות לעשות שליחות אדונם."],[1,"ובההוא מלבושא מצחצחא וכו':","ובלבוש ההוא המצוחצח נכנסים לאש ואינם יראים, כעין מלאך ההוא של מנוח, כשנראה לו ונכנס בשלהבת ועלה השמים, שכתוב, ויעל מלאך ה', בלהב המזבח. וכשהוסר מהם זוהמא ההיא, נשארו ישראל גופים מצוחצחים בלי טינוף כלל, והנשמה שבפנים הגוף היתה כזוהר הרקיע לקבל אור."],[2,"הכי הוו ישראל וכו':","כן היו ישראל, שהיו רואים ומסתכלים בכבוד אדונם, מה שלא היה כן על הים, כי לא הוסר מהם הזוהמא בזמן ההוא. וכאן בסיני שפסקה הזוהמא מן הגוף, אפילו עוברים שבמעי אמם היו רואים ומסתכלים בכבוד אדונם. וכולם, כל אחד ואחד קבל כראוי לו."],[3,"וההוא יומא הוה וכו':","ויום ההוא היתה שמחה לפני הקב\"ה, יותר מיום שנברא בו העולם, משום שיום שנברא העולם לא היה העולם בקיום עד שקבלו ישראל את התורה, שכתוב, אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי."],[4,"כיון דקבילו ישראל וכו':","כיון שקבלו ישראל את התורה על הר סיני אז התבשם העולם ונתקיימו שמים וארץ. והקב\"ה נודע למעלה ולמטה, ועלה בכבודו על כל. ועל יום ההוא כתוב, ה' מלך גאות לבש לבש ה' עז התאזר. ואין עז אלא תורה, שנאמר ה' עז לעמו יתן ה' יברך את עמו בשלום."]],[[0,"","וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, יָכוֹל כְּמוֹ אוֹתוֹ יוֹם שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי? לֹא כָּךְ! מִשּׁוּם שֶׁאוֹתוֹ הַיּוֹם שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, עָבְרָה מֵהֶם הַזֻּהֲמָה, וְכָל הַגּוּפִים הָיוּ מְצֻחְצָחִים כְּצִחְצוּחַ שֶׁל מַלְאָכִים עֶלְיוֹנִים כְּשֶׁמִּתְלַבְּשִׁים בִּלְבוּשִׁים מְצֻחְצָחִים לַעֲשׂוֹת אֶת שְׁלִיחוּת רִבּוֹנָם."],[1,"","וּבְאוֹתוֹ מַלְבּוּשׁ מְצֻחְצָח נִכְנָסִים לָאֵשׁ וְלֹא פוֹחֲדִים. כְּמוֹ אוֹתוֹ הַמַּלְאָךְ שֶׁל מָנוֹחַ, כְּשֶׁנִּרְאָה לוֹ וְנִכְנַס בְּשַׁלְהֶבֶת וְעָלָה לַשָּׁמַיִם, שֶׁכָּתוּב (שופטים יג) וַיַּעַל מַלְאַךְ ה' בְּלַהַב הַמִּזְבֵּחַ. וּכְשֶׁעָבְרָה מֵהֶם אוֹתָהּ זֻהֲמָה, נִשְׁאֲרוּ יִשְׂרָאֵל גּוּפִים מְצֻחְצָחִים בְּלִי טִנּוּף כְּלָל, וְהַנְּשָׁמוֹת בִּפְנִים כְּזהַר הָרָקִיעַ לְקַבֵּל אֶת הָאוֹר."],[2,"","כָּךָ הָיוּ יִשְׂרָאֵל, שֶׁהָיוּ רוֹאִים וּמִסְתַּכְּלִים לְתוֹךְ כְּבוֹד רִבּוֹנָם, מַה שֶּׁלֹּא הָיָה כָּךְ עַל הַיָּם, שֶׁלֹּא עָבְרָה מֵהֶם הַזֻּהֲמָה בְּאוֹתוֹ זְמַן. וְכָאן בְּסִינַי, שֶׁפָּסְקָה הַזֻּהֲמָה מִן הַגּוּף, אֲפִלּוּ עֻבָּרִים בִּמְעֵי אִמּוֹתֵיהֶם הָיוּ רוֹאִים וּמִסְתַּכְּלִים בִּכְבוֹד רִבּוֹנָם, וְכֻלָּם קִבְּלוּ כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ."],[3,"","וְאוֹתוֹ יוֹם הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִן הַיּוֹם שֶׁנִּבְרָא הָעוֹלָם, מִשּׁוּם שֶׁהַיּוֹם שֶׁנִּבְרָא הָעוֹלָם לֹא הָיָה בְּקִיּוּם עַד שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, שֶׁכָּתוּב (ירמיהלג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי."],[4,"","כֵּיוָן שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה עַל הַר סִינַי, אָז הִתְבַּשֵּׂם הָעוֹלָם, וְהִתְקַיְּמוּ שָׁמַיִם וָאָרֶץ, וְנוֹדַע הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה, וְהִתְעַלָּה בִּכְבוֹדוֹ עַל הַכֹּל. וְעַל אוֹתוֹ יוֹם כָּתוּב, (תהלים צג) ה' מָלָךְ גֵּאוּת לָבֵשׁ לָבֵשׁ ה' עֹז הִתְאַזָּר. וְאֵין עֹז אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (שם כט) ה' עֹז לְעַמּוֹ יִתֵּן ה' יְבָרֵךְ אֶת עַמּוֹ בַשָּׁלוֹם. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
